+++ b/src/utils/webmcp.ts
@@ -0,0 +1,86 @@
+import { useEffect, useRef } from 'react';
+
+/**
+ * Minimal typings and helpers for WebMCP (`navigator.modelContext`), which lets
+ * a page expose client-side functionality as tools for in-browser AI agents.
+ * https://github.com/webmachinelearning/webmcp
+ */
+
+export interface ToolResult {
+  content: Array<{ type: 'text'; text: string }>;
+  isError?: boolean;
+}
+
+export interface ModelContextTool<Args = any> {
+  name: string;
+  description: string;
+  inputSchema: Record<string, unknown>;
+  annotations?: { readOnlyHint?: boolean; [key: string]: unknown };
+  execute: (args: Args, client?: unknown) => Promise<ToolResult> | ToolResult;
+}
+
+interface ModelContext {
+  registerTool: (tool: ModelContextTool, options?: { signal?: AbortSignal }) => unknown;
+  unregisterTool?: (name: string) => void;
+}
+
+declare global {
+  interface Navigator {
+    modelContext?: ModelContext;
+  }
+}
+
+export const textResult = (text: string, isError = false): ToolResult => ({
+  content: [{ type: 'text', text }],
+  ...(isError ? { isError: true } : {}),
+});
+
+/**
+ * Registers a WebMCP tool while the calling component is mounted.
+ * `execute` is read through a ref so it always sees the latest closure
+ * without re-registering the tool on every render.
+ */
+export function useWebMcpTool<Args>(tool: ModelContextTool<Args>) {
+  const executeRef = useRef(tool.execute);
+  executeRef.current = tool.execute;
+
+  useEffect(() => {
+    const modelContext = typeof navigator !== 'undefined' ? navigator.modelContext : undefined;
+    if (!modelContext?.registerTool) return;
+
+    const controller = new AbortController();
+    let registration: unknown;
+    try {
+      registration = modelContext.registerTool(
+        {
+          name: tool.name,
+          description: tool.description,
+          inputSchema: tool.inputSchema,
+          annotations: tool.annotations,
+          execute: (args: Args, client?: unknown) => executeRef.current(args, client),
+        },
+        { signal: controller.signal },
+      );
+    } catch (err) {
+      console.warn(`WebMCP: failed to register tool "${tool.name}"`, err);
+      return;
+    }
+
+    return () => {
+      // Support the different unregistration styles across WebMCP iterations.
+      controller.abort();
+      const maybeUnregister = (registration as { unregister?: () => void } | undefined)?.unregister;
+      try {
+        if (typeof maybeUnregister === 'function') {
+          maybeUnregister.call(registration);
+        } else {
+          modelContext.unregisterTool?.(tool.name);
+        }
+      } catch {
+        // Already unregistered via the abort signal.
+      }
+    };
+    // Tool metadata is static per component; only re-register if its name changes.
+    // eslint-disable-next-line react-hooks/exhaustive-deps
+  }, [tool.name]);
+}

