+        const submenu = submenuOf(item);
+        submenu.addEventListener('keydown', (e) => {
+          const items = itemsOf(submenu);
+          const current = items.indexOf(document.activeElement);
+          let handled = true;
+          switch (e.key) {
+            case 'ArrowDown': items[(current + 1) % items.length].focus(); break;
+            case 'ArrowUp': items[(current - 1 + items.length) % items.length].focus(); break;
+            case 'Home': items[0].focus(); break;
+            case 'End': items[items.length - 1].focus(); break;
+            case 'ArrowRight': openSubmenu(focusTop(index + 1), 'first'); break;
+            case 'ArrowLeft': openSubmenu(focusTop(index - 1), 'first'); break;
+            case 'Escape':
+              closeSubmenu();
+              focusTop(index);
+              break;
+            case ' ':
+              document.activeElement.click();
+              break;
+            case 'Tab':
+              // Let focus move naturally out of the menubar, but close the submenu.
+              closeSubmenu();
+              handled = false;
+              break;
+            default:
+              if (e.key.length === 1 && /\S/.test(e.key) && !e.ctrlKey && !e.metaKey && !e.altKey) {
+                const match = typeAhead(items, document.activeElement, e.key.toLowerCase());
