+              } else {
+                handled = false;
+              }
+          }
+          if (handled) {
+            e.preventDefault();
+            e.stopPropagation();
+          }
+        });
+      });
+
+      // Close when clicking or focusing outside the menubar.
+      document.addEventListener('pointerdown', (e) => {
+        if (!menubar.contains(e.target)) closeSubmenu();
+      });
+      menubar.addEventListener('focusout', (e) => {
+        if (!menubar.contains(e.relatedTarget)) closeSubmenu();
+      });
+
+      setActiveTop(0);
+    })();
+  </script>
+
