+
+// --- Shaders ----------------------------------------------------------------
+
+const VERTEX_SRC = `#version 300 es
+in vec2 aPos;
+uniform mat4 uMvp;
+out vec2 vUv;
+void main() {
+  vUv = aPos + 0.5;            // 0..1, y up
+  gl_Position = uMvp * vec4(aPos, 0.0, 1.0);
