+const FRAGMENT_SRC = `#version 300 es
+precision highp float;
+in vec2 vUv;
+uniform sampler2D uTex;
+uniform float uTime;
+uniform vec2 uRes;
+uniform vec4 uRipples[8];   // xy = center (uv), z = start time, w = strength
+uniform float uAmbient;
+out vec4 outColor;
