+  for (int i = 0; i < 8; i++) {
+    vec4 r = uRipples[i];
+    float age = uTime - r.z;
+    if (r.w <= 0.0 || age < 0.0 || age > 3.0) continue;
+    vec2 d = (vUv - r.xy) * aspect;
+    float dist = length(d);
+    float band = dist - age * 0.45;                 // expanding wavefront
+    float env = exp(-band * band * 80.0)            // thin ring
+              * exp(-age * 1.6)                     // fade over time
+              * smoothstep(0.0, 0.08, age) * r.w;   // soft start
+    vec2 dir = dist > 1e-4 ? d / dist : vec2(0.0);
+    offset += dir * sin(band * 70.0) * env * 0.016;
+  }
+
+  // Gentle ambient "steam" shimmer.
+  offset += uAmbient * 0.0016 * vec2(
+    sin(vUv.y * 14.0 + uTime * 1.3),
+    cos(vUv.x * 11.0 + uTime * 1.1));
