+  offset /= aspect;
+  vec2 uv = vUv - offset;
+  vec2 tuv = vec2(uv.x, 1.0 - uv.y);                // texture rows are top-down
+
+  // Subtle chromatic split proportional to the distortion.
+  vec2 ca = vec2(length(offset) * 0.4, 0.0);
+  vec4 base = texture(uTex, tuv);
+  vec4 cr = texture(uTex, tuv + ca);
+  vec4 cb = texture(uTex, tuv - ca);
+  float a = max(base.a, max(cr.a, cb.a));
+  outColor = vec4(cr.r, base.g, cb.b, a);           // premultiplied
+}`;

