+  <script>
+    (() => {
+      const form = document.getElementById('payment-form');
+      const fields = {
+        number: form.elements['cc-number'],
+        name: form.elements['cc-name'],
+        exp: form.elements['cc-exp'],
+        csc: form.elements['cc-csc'],
+      };
+
+      const luhn = (digits) => {
+        let sum = 0;
+        for (let i = 0; i < digits.length; i++) {
+          let d = Number(digits[digits.length - 1 - i]);
+          if (i % 2) { d *= 2; if (d > 9) d -= 9; }
+          sum += d;
+        }
+        return sum % 10 === 0;
+      };
+
+      // Returns an error message, or '' if valid.
+      const checks = {
+        'cc-number': (el) => {
+          const v = el.value.trim();
+          if (!v) return 'Enter your card number.';
+          const digits = v.replace(/\s/g, '');
+          if (!/^\d{12,19}$/.test(digits)) return 'Card number should be 12 to 19 digits.';
+          if (!luhn(digits)) return 'That card number doesn\u2019t look right. Please check it.';
+          return '';
+        },
+        'cc-name': (el) => {
+          if (!el.value.trim()) return 'Enter the name exactly as it appears on your card.';
+          if (el.validity.patternMismatch) return 'Use letters, spaces, hyphens, apostrophes or periods only.';
+          return '';
+        },
+        'cc-exp': (el) => {
