+          if (!m) return 'Enter the expiry date as MM/YY, e.g. 08/29.';
+          const now = new Date();
+          const expYear = 2000 + Number(m[2]);
+          const expMonth = Number(m[1]);
+          if (expYear < now.getFullYear() || (expYear === now.getFullYear() && expMonth < now.getMonth() + 1)) {
+            return 'This card has expired.';
+          }
+          return '';
+        },
+        'cc-csc': (el) => {
+          if (!el.value.trim()) return 'Enter the security code.';
+          if (!/^\d{3,4}$/.test(el.value.trim())) return 'Security code should be 3 or 4 digits.';
+          return '';
+        },
+      };
+
+      const showError = (el, message) => {
+        const errorEl = document.getElementById(`${el.id}-error`);
+        el.setCustomValidity(message);
+        if (message) {
+          el.setAttribute('aria-invalid', 'true');
+        } else {
+          el.removeAttribute('aria-invalid');
+        }
+        errorEl.textContent = message;
+      };
+
+      const validate = (el) => {
+        const message = checks[el.id](el);
+        showError(el, message);
+        return !message;
+      };
+
+      Object.values(fields).forEach((el) => {
+        el.dataset.edited = '';
+        // Validate when the user leaves a field they've edited.
+        el.addEventListener('change', () => { el.dataset.edited = 'true'; });
+        el.addEventListener('blur', () => { if (el.dataset.edited) validate(el); });
+        // Clear errors as soon as the value becomes valid; never add errors while typing.
+        el.addEventListener('input', () => {
+          if (el.getAttribute('aria-invalid') === 'true' && !checks[el.id](el)) showError(el, '');
+        });
+      });
+
+      // Auto-insert the slash in MM/YY when typing (not when deleting).
+      fields.exp.addEventListener('input', (e) => {
+        if (e.inputType && e.inputType.startsWith('delete')) return;
+        const digits = fields.exp.value.replace(/\D/g, '').slice(0, 4);
+        let formatted = digits;
+        if (digits.length === 1 && Number(digits) > 1) formatted = `0${digits}/`;
+        else if (digits.length >= 2) formatted = `${digits.slice(0, 2)}/${digits.slice(2)}`;
+        fields.exp.value = formatted;
+      });
+
+      form.addEventListener('submit', (e) => {
+        const invalid = Object.values(fields).filter((el) => !validate(el));
+        if (invalid.length) {
+          e.preventDefault();
+          invalid[0].focus();
+          return;
+        }
+        // Normalise the card number before sending.
+        fields.number.value = fields.number.value.replace(/\s/g, '');
+        const submit = form.querySelector('button[type="submit"]');
+        submit.disabled = true;
+        submit.textContent = 'Processing\u2026';
+        document.getElementById('payment-status').textContent = 'Processing your payment\u2026';
+      });
