+  <script>
+    // Builds the breadcrumb trail from the current URL path so the same
+    // markup works on every page (e.g. /menu/cold-brew -> Home > Menu > Cold Brew).
+    (function () {
+      var LABELS = {
+        '/': 'Home',
+        '/menu': 'Menu',
+        '/menu/seasonal': 'Maple Oat Latte',
+        '/menu/espresso': 'Dark Roast Espresso',
+        '/menu/cold-brew': 'Cold Brew',
+        '/locations': 'Locations',
+        '/rewards': 'Rewards',
+        '/account': 'My Account',
+        '/order-online': 'Order Online',
+        '/about': 'Our Story',
+        '/careers': 'Join the Team',
+        '/contact': 'Contact Us',
+        '/privacy-policy': 'Privacy'
+      };
+
+      function prettify(segment) {
+        return decodeURIComponent(segment)
+          .replace(/[-_]+/g, ' ')
+          .replace(/\b\w/g, function (c) { return c.toUpperCase(); });
+      }
+
+      var list = document.getElementById('breadcrumb-list');
+      if (!list) return;
+
+      var path = window.location.pathname
+        .replace(/\/index\.html?$/i, '/')
+        .replace(/\/+$/, '');
+      var segments = path.split('/').filter(Boolean);
+
+      // Opened as a local file (file:///.../index.html): treat as home.
+      if (window.location.protocol === 'file:') segments = [];
+
+      var crumbs = [{ href: '/', label: LABELS['/'] }];
+      var href = '';
+      segments.forEach(function (seg) {
+        href += '/' + seg;
+        crumbs.push({ href: href, label: LABELS[href] || prettify(seg) });
+      });
+
+      list.textContent = '';
+      crumbs.forEach(function (crumb, i) {
+        var li = document.createElement('li');
+        var el;
+        if (i === crumbs.length - 1) {
+          el = document.createElement('span');
+          el.setAttribute('aria-current', 'page');
+        } else {
+          el = document.createElement('a');
+          el.href = crumb.href;
+        }
+        el.textContent = crumb.label;
+        li.appendChild(el);
+        list.appendChild(li);
+      });
+
+      if (crumbs.length > 1) {
+        document.title = crumbs[crumbs.length - 1].label + ' | The Daily Grind';
+      }
+    })();
+  </script>
+
 </body>

