+  <script type="module">
+    // Pickup time and anniversary are wall-clock / calendar values, not instants.
+    // They are modelled with Temporal Plain types and stored as plain ISO strings
+    // ("08:15", "2019-03-14") so they never shift when the device time zone changes.
+    if (typeof Temporal === 'undefined') {
+      const mod = await import('https://esm.sh/temporal-polyfill');
+      globalThis.Temporal = mod.Temporal;
+    }
+
+    const STORAGE_KEY = 'dailyGrind.coffeeMoments';
+    const form = document.getElementById('prefs-form');
+    const timeInput = document.getElementById('pickup-time');
+    const dateInput = document.getElementById('anniversary-date');
+    const pickupSummary = document.getElementById('pickup-summary');
+    const anniversarySummary = document.getElementById('anniversary-summary');
+    const status = document.getElementById('prefs-status');
+
+    const load = () => {
+      try {
+        const raw = JSON.parse(localStorage.getItem(STORAGE_KEY)) ?? {};
+        return {
+          pickupTime: raw.pickupTime ? Temporal.PlainTime.from(raw.pickupTime) : null,
+          anniversary: raw.anniversary ? Temporal.PlainDate.from(raw.anniversary) : null,
+        };
+      } catch {
+        return { pickupTime: null, anniversary: null };
+      }
+    };
+
+    const save = ({ pickupTime, anniversary }) => {
+      localStorage.setItem(STORAGE_KEY, JSON.stringify({
+        pickupTime: pickupTime?.toString({ smallestUnit: 'minute' }) ?? null,
+        anniversary: anniversary?.toString() ?? null,
+      }));
+    };
+
+    const describePickup = (time) => {
+      if (!time) return '';
+      return `Reminder every day at ${time.toLocaleString(undefined, { timeStyle: 'short' })} local time.`;
+    };
+
+    const describeAnniversary = (date) => {
+      if (!date) return '';
+      const today = Temporal.Now.plainDateISO();
+      // Recurring annual date: convert MonthDay to a PlainDate for a given year
+      // (constrains Feb 29 to Feb 28 in non-leap years).
+      const monthDay = date.toPlainMonthDay();
+      let next = monthDay.toPlainDate({ year: today.year });
+      if (Temporal.PlainDate.compare(next, today) < 0) {
+        next = monthDay.toPlainDate({ year: today.year + 1 });
+      }
+      const days = today.until(next, { largestUnit: 'day' }).days;
+      const years = next.year - date.year;
+      const label = date.toLocaleString(undefined, { dateStyle: 'long' });
+      if (Temporal.PlainDate.compare(date, today) > 0) return `Starting ${label}.`;
+      if (days === 0) return `Happy ${years}-year coffee anniversary! ☕ (since ${label})`;
+      return `Since ${label} — ${years}-year anniversary in ${days} day${days === 1 ? '' : 's'}.`;
+    };
+
+    const render = (prefs) => {
+      if (prefs.pickupTime) timeInput.value = prefs.pickupTime.toString({ smallestUnit: 'minute' });
+      if (prefs.anniversary) dateInput.value = prefs.anniversary.toString();
+      pickupSummary.textContent = describePickup(prefs.pickupTime);
+      anniversarySummary.textContent = describeAnniversary(prefs.anniversary);
+    };
+
+    // Set the max date to today (a calendar date, no time zone conversion).
+    dateInput.max = Temporal.Now.plainDateISO().toString();
+
+    render(load());
+
+    form.addEventListener('submit', (event) => {
+      event.preventDefault();
+      try {
+        const prefs = {
+          pickupTime: Temporal.PlainTime.from(timeInput.value),
+          anniversary: Temporal.PlainDate.from(dateInput.value),
+        };
+        save(prefs);
+        render(prefs);
+        status.textContent = 'Saved!';
+      } catch {
+        status.textContent = 'Please enter a valid time and date.';
+      }
+    });
+  </script>
