+            year: 'numeric', month: 'long', day: 'numeric', timeZone: 'UTC'
+          }).format(new Date(Date.UTC(dt.y, dt.mo - 1, dt.d)));
+        } catch (e) {
+          return dt.text;
+        }
+      }
+
+      // Today's calendar date wherever the user is right now (local fields).
+      function todayLocal() {
+        var n = new Date();
+        return { y: n.getFullYear(), mo: n.getMonth() + 1, d: n.getDate() };
+      }
+
+      // Day number from calendar fields only (UTC math => no DST drift).
+      function dayNumber(y, mo, d) {
+        return Math.floor(Date.UTC(y, mo - 1, d) / 86400000);
+      }
+
+      // Feb 29 anniversaries are observed on Feb 28 in non-leap years.
+      function anniversaryInYear(dt, year) {
+        var day = Math.min(dt.d, daysInMonth(year, dt.mo));
+        return { y: year, mo: dt.mo, d: day };
+      }
+
+      function describeAnniversary(dt) {
+        var today = todayLocal();
+        var todayN = dayNumber(today.y, today.mo, today.d);
+        var originN = dayNumber(dt.y, dt.mo, dt.d);
+        var base = 'Saved: ' + formatDate(dt) + '.';
+
+        if (originN > todayN) {
+          var until = originN - todayN;
+          return base + ' Your first coffee day is in ' + until + (until === 1 ? ' day.' : ' days.');
+        }
+
+        var next = anniversaryInYear(dt, today.y);
+        var nextN = dayNumber(next.y, next.mo, next.d);
+        if (nextN < todayN) {
+          next = anniversaryInYear(dt, today.y + 1);
+          nextN = dayNumber(next.y, next.mo, next.d);
+        }
+        var years = next.y - dt.y;
+        var diff = nextN - todayN;
+
+        if (diff === 0) {
+          return years === 0
+            ? base + ' That’s today — welcome! ☕'
+            : base + ' Happy ' + years + '-year coffee anniversary today! ☕';
+        }
+        return base + ' ' + years + '-year anniversary in ' + diff + (diff === 1 ? ' day.' : ' days.');
+      }
+
+      var pickupForm = document.getElementById('pickup-form');
+      var pickupInput = document.getElementById('pickup-time');
+      var pickupSummary = document.getElementById('pickup-summary');
+      var annivForm = document.getElementById('anniversary-form');
+      var annivInput = document.getElementById('anniversary-date');
+      var annivSummary = document.getElementById('anniversary-summary');
+
+      function renderPickup() {
+        var t = parseTime(storageGet(STORAGE_KEYS.pickup));
+        if (t) {
+          pickupInput.value = t.text;
+          pickupSummary.textContent = 'Saved: every day at ' + formatTime(t) + ' local time.';
+        } else {
+          pickupSummary.textContent = 'No reminder set.';
+        }
+      }
+
+      function renderAnniversary() {
+        var dt = parseDate(storageGet(STORAGE_KEYS.anniversary));
+        if (dt) {
+          annivInput.value = dt.text;
+          annivSummary.textContent = describeAnniversary(dt);
+        } else {
+          annivSummary.textContent = 'No anniversary set.';
+        }
+      }
+
+      pickupForm.addEventListener('submit', function (e) {
+        e.preventDefault();
+        var t = parseTime(pickupInput.value);
+        if (!t) {
+          pickupSummary.textContent = 'Please choose a valid time.';
+          return;
+        }
+        if (!storageSet(STORAGE_KEYS.pickup, t.text)) {
+          pickupSummary.textContent = 'Could not save (storage unavailable).';
+          return;
+        }
+        renderPickup();
+      });
+
+      annivForm.addEventListener('submit', function (e) {
+        e.preventDefault();
+        var dt = parseDate(annivInput.value);
+        if (!dt) {
+          annivSummary.textContent = 'Please choose a valid date.';
+          return;
+        }
+        if (!storageSet(STORAGE_KEYS.anniversary, dt.text)) {
+          annivSummary.textContent = 'Could not save (storage unavailable).';
+          return;
+        }
+        renderAnniversary();
+      });
+
+      document.querySelectorAll('[data-clear]').forEach(function (btn) {
+        btn.addEventListener('click', function () {
+          var which = btn.getAttribute('data-clear');
+          storageRemove(STORAGE_KEYS[which]);
+          if (which === 'pickup') { pickupInput.value = ''; renderPickup(); }
+          else { annivInput.value = ''; renderAnniversary(); }
+        });
+      });
+
+      renderPickup();
+      renderAnniversary();
+    })();
+  </script>
+
