+  <script>
+    (function () {
+      var STORAGE_KEY = 'dailyGrindOrder';
+      var SIZE_LABELS = { small: 'Small', medium: 'Medium', large: 'Large' };
+      var money = function (n) { return '$' + n.toFixed(2); };
+
+      var order = [];
+      try { order = JSON.parse(localStorage.getItem(STORAGE_KEY)) || []; } catch (e) { order = []; }
+
+      var list = document.querySelector('.order-list');
+      var totalEl = document.querySelector('.order-total');
+      var countEl = document.querySelector('.order-count');
+
+      function save() {
+        try { localStorage.setItem(STORAGE_KEY, JSON.stringify(order)); } catch (e) { /* storage unavailable */ }
+      }
+
+      function render() {
+        list.innerHTML = '';
+        var total = 0, count = 0;
+        order.forEach(function (line, i) {
+          total += line.price * line.qty;
+          count += line.qty;
+          var li = document.createElement('li');
+          var label = document.createElement('span');
+          label.textContent = line.qty + ' \u00d7 ' + line.name + ' (' + SIZE_LABELS[line.size] + ')';
+          var right = document.createElement('span');
+          right.textContent = money(line.price * line.qty);
+          var remove = document.createElement('button');
+          remove.type = 'button';
+          remove.textContent = '\u00d7';
+          remove.setAttribute('aria-label', 'Remove ' + line.name + ' (' + SIZE_LABELS[line.size] + ')');
+          remove.addEventListener('click', function () {
+            order.splice(i, 1);
+            save();
+            render();
+          });
+          right.appendChild(remove);
+          li.append(label, right);
+          list.appendChild(li);
+        });
+        totalEl.textContent = money(total);
+        countEl.textContent = count ? String(count) : '';
+      }
+
+      document.querySelectorAll('.drink-card').forEach(function (card) {
+        var form = card.querySelector('.drink-form');
+        var priceEl = card.querySelector('.drink-price');
+        var button = card.querySelector('.add-btn');
+        var img = card.querySelector('.drink-photo img');
+        var resetTimer;
+
+        if (img) {
+          var markBroken = function () { img.classList.add('is-broken'); };
+          if (img.complete && img.naturalWidth === 0 && img.src) markBroken();
+          img.addEventListener('error', markBroken);
+        }
+
+        form.addEventListener('change', function (e) {
+          if (e.target.name === 'size') priceEl.textContent = money(parseFloat(e.target.dataset.price));
+        });
+
+        form.addEventListener('submit', function (e) {
+          e.preventDefault();
+          var choice = form.querySelector('input[name="size"]:checked');
+          if (!choice) return;
+          var id = form.elements.item.value;
+          var existing = order.find(function (l) { return l.id === id && l.size === choice.value; });
+          if (existing) {
+            existing.qty += 1;
+          } else {
+            order.push({ id: id, name: form.dataset.drink, size: choice.value, price: parseFloat(choice.dataset.price), qty: 1 });
+          }
+          save();
+          render();
+
+          button.textContent = 'Added \u2713';
+          button.classList.add('is-added');
+          clearTimeout(resetTimer);
+          resetTimer = setTimeout(function () {
+            button.textContent = 'Add to Order';
+            button.classList.remove('is-added');
+          }, 1500);
+        });
+      });
+
+      render();
+    })();
