@@ -0,0 +1,350 @@
+// Encrypted Delivery Notes
+//
+// Envelope encryption in the browser with WebCrypto:
+//   * Preferred suite: hybrid post-quantum KEM 'MLKEM768-X25519' (ML-KEM-768 + X25519)
+//     whose encapsulated shared key is used directly as a 'ChaCha20-Poly1305' AEAD key.
+//   * Classical fallback: ephemeral-static 'X25519' key agreement -> HKDF-SHA-256 -> 'AES-GCM'.
+//
+// The order number, protocol version, and suite are bound to every ciphertext as AEAD
+// additional data, so tampering with the metadata or moving a note to another order fails.
+//
+// NOTE: The site is static, so the "store" recipient key pair is generated in this browser
+// and persisted (non-extractable) in IndexedDB to demonstrate both halves of the flow.
+// In production, set `STORE_PUBLIC_KEY_B64` to the store's published public key and keep
+// the private key solely on the barista station.
+
+const STORE_PUBLIC_KEY_B64 = ''; // Optional: production store public key (base64).
+
+const PROTOCOL_VERSION = 'daily-grind-note-v1';
+const SUITE_PQ = 'MLKEM768-X25519+ChaCha20-Poly1305';
+const SUITE_CLASSICAL = 'X25519+HKDF-SHA256+AES-GCM';
+
+const KEM_PUBLIC_KEY_ALGORITHMS = {
+  1184: 'ML-KEM-768',
+  1216: 'MLKEM768-X25519',
+  1568: 'ML-KEM-1024',
+};
+
+const DB_NAME = 'daily-grind-secure-notes';
+const STORE_NAME = 'keys';
+const KEY_ID = 'store-recipient-key';
+
+const encoder = new TextEncoder();
+const decoder = new TextDecoder();
+
+/* ---------------------------------------------------------------- encoding helpers */
+
+function toBase64(bytes) {
+  if (typeof bytes.toBase64 === 'function') return bytes.toBase64();
+  let binary = '';
+  for (let i = 0; i < bytes.length; i += 0x8000) {
+    binary += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
+  }
+  return btoa(binary);
+}
+
+function fromBase64(b64) {
+  if (typeof Uint8Array.fromBase64 === 'function') return Uint8Array.fromBase64(b64);
+  return Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
+}
+
+async function fingerprint(bytes) {
+  const digest = new Uint8Array(await crypto.subtle.digest('SHA-256', bytes));
+  return Array.from(digest.subarray(0, 16), (b) => b.toString(16).padStart(2, '0'))
+    .join('')
+    .match(/.{4}/g)
+    .join(':');
+}
+
+/* ---------------------------------------------------------------- feature detection */
+
+export function supportsPostQuantumEnvelope() {
+  try {
+    return (
+      typeof globalThis.SubtleCrypto?.supports === 'function' &&
+      SubtleCrypto.supports('generateKey', 'MLKEM768-X25519') &&
+      SubtleCrypto.supports('encapsulateKey', 'MLKEM768-X25519', 'ChaCha20-Poly1305') &&
+      SubtleCrypto.supports('decapsulateKey', 'MLKEM768-X25519', 'ChaCha20-Poly1305')
+    );
+  } catch {
+    return false;
+  }
+}
+
+/* ---------------------------------------------------------------- IndexedDB key storage */
+
+function openDb() {
+  return new Promise((resolve, reject) => {
+    const req = indexedDB.open(DB_NAME, 1);
+    req.onupgradeneeded = () => req.result.createObjectStore(STORE_NAME);
+    req.onsuccess = () => resolve(req.result);
+    req.onerror = () => reject(req.error);
+  });
+}
+
+async function idb(mode, fn) {
+  const db = await openDb();
+  try {
+    return await new Promise((resolve, reject) => {
+      const tx = db.transaction(STORE_NAME, mode);
+      const req = fn(tx.objectStore(STORE_NAME));
+      tx.oncomplete = () => resolve(req.result);
+      tx.onerror = () => reject(tx.error);
+      tx.onabort = () => reject(tx.error);
+    });
+  } finally {
+    db.close();
+  }
+}
+
+const loadStoredKeys = () => idb('readonly', (s) => s.get(KEY_ID));
+const saveStoredKeys = (record) => idb('readwrite', (s) => s.put(record, KEY_ID));
+
+/* ---------------------------------------------------------------- recipient keys */
+
+async function generateRecipientKeys() {
+  if (supportsPostQuantumEnvelope()) {
+    const keyPair = await crypto.subtle.generateKey(
+      'MLKEM768-X25519',
+      false, // private key never leaves WebCrypto; CryptoKeyPair is structured-cloned into IDB
+      ['encapsulateKey', 'decapsulateKey'],
+    );
+    const publicKeyBytes = new Uint8Array(
+      await crypto.subtle.exportKey('raw-public', keyPair.publicKey),
+    );
+    return { suite: SUITE_PQ, keyPair, publicKeyBytes };
+  }
+
+  const keyPair = await crypto.subtle.generateKey('X25519', false, ['deriveBits']);
+  const publicKeyBytes = new Uint8Array(await crypto.subtle.exportKey('raw', keyPair.publicKey));
+  return { suite: SUITE_CLASSICAL, keyPair, publicKeyBytes };
+}
+
+async function getOrCreateRecipientKeys() {
+  const wantSuite = supportsPostQuantumEnvelope() ? SUITE_PQ : SUITE_CLASSICAL;
+  try {
+    const stored = await loadStoredKeys();
+    if (stored?.suite === wantSuite && stored.keyPair?.privateKey) return stored;
+  } catch {
+    // IndexedDB unavailable (e.g. private mode restrictions) — fall through to ephemeral keys.
+  }
+  const fresh = await generateRecipientKeys();
+  try {
+    await saveStoredKeys(fresh);
+  } catch {
+    // Keys still work for this session.
+  }
+  return fresh;
+}
+
+async function importRecipientPublicKey(bytes) {
+  const kemName = KEM_PUBLIC_KEY_ALGORITHMS[bytes.byteLength];
+  if (kemName) {
+    return crypto.subtle.importKey('raw-public', bytes, kemName, true, ['encapsulateKey']);
+  }
+  if (bytes.byteLength === 32) {
+    return crypto.subtle.importKey('raw', bytes, 'X25519', true, []);
+  }
+  throw new Error('Unrecognized store public key length.');
