+/* ---------------------------------------------------------------- envelope encrypt / decrypt */
+
+function associatedData(orderId, suite) {
+  return encoder.encode(JSON.stringify({ v: PROTOCOL_VERSION, suite, orderId }));
+}
+
+export async function encryptNote(recipientPublicKey, orderId, plaintext) {
+  const info = encoder.encode(`${PROTOCOL_VERSION}|${orderId}`);
+  const { sharedKey, capsule, suite } = await encapsulateEnvelopeKey(recipientPublicKey, info);
