+  if (envelope.v !== PROTOCOL_VERSION) throw new Error('Unsupported envelope version.');
+  const info = encoder.encode(`${PROTOCOL_VERSION}|${envelope.orderId}`);
+  const key = await decapsulateEnvelopeKey(recipientPrivateKey, fromBase64(envelope.capsule), info);
+  const plaintext = await crypto.subtle.decrypt(
+    {
+      name: key.algorithm.name,
+      iv: fromBase64(envelope.iv),
+      additionalData: associatedData(envelope.orderId, envelope.suite),
+    },
+    key,
+    fromBase64(envelope.ciphertext),
+  );
+  return decoder.decode(plaintext);
+}
+
+/* ---------------------------------------------------------------- UI wiring */
+
+const $ = (id) => document.getElementById(id);
+const form = $('secure-note-form');
+const orderInput = $('note-order-id');
+const noteInput = $('note-text');
+const encryptBtn = $('encrypt-btn');
+const decryptBtn = $('decrypt-btn');
+const status = $('note-status');
+const suiteBadge = $('note-suite');
+const envelopeDetails = $('envelope-details');
+const envelopeOutput = $('envelope-output');
+const decryptedWrapper = $('decrypted-wrapper');
+const decryptedNote = $('decrypted-note');
+
+function setStatus(message, state = '') {
+  status.textContent = message;
+  status.dataset.state = state;
+}
+
+let recipient = null; // { keyPair?, publicKey, suite }
+let lastEnvelope = null;
+
+async function init() {
+  if (!window.isSecureContext || !globalThis.crypto?.subtle) {
+    suiteBadge.textContent = 'Encryption unavailable';
+    setStatus('Encrypted notes require a secure (HTTPS) connection.', 'error');
