+    const isPq = recipient.publicKey.algorithm.name !== 'X25519';
+    suiteBadge.textContent = isPq
+      ? '🔒 Hybrid post-quantum: ML-KEM-768 + X25519 · ChaCha20-Poly1305'
+      : '🔒 Classical: X25519 + HKDF · AES-256-GCM (post-quantum not supported by this browser)';
+    $('store-public-key').textContent = toBase64(publicKeyBytes);
+    $('store-key-fingerprint').textContent = await fingerprint(publicKeyBytes);
+    encryptBtn.disabled = false;
+  } catch (err) {
+    console.error(err);
+    suiteBadge.textContent = 'Encryption unavailable';
+    setStatus('Your browser does not support the required encryption algorithms.', 'error');
+  }
+}
+
+form.addEventListener('submit', async (event) => {
+  event.preventDefault();
+  if (!recipient) return;
