+  encryptBtn.disabled = true;
+  decryptedWrapper.hidden = true;
+  try {
+    lastEnvelope = await encryptNote(recipient.publicKey, orderId, note);
+    envelopeOutput.textContent = JSON.stringify(lastEnvelope, null, 2);
