+/**
+ * Daily Grind — encrypted delivery notes (crypto core).
+ *
+ * Hybrid post-quantum public-key encryption of short customer notes, in the
+ * style of HPKE (RFC 9180) "base" mode:
+ *
+ *   KEM  : X-Wing  = X25519 key agreement + ML-KEM-768 (FIPS 203) encapsulation,
+ *          combined with SHA3-256 (draft-connolly-cfrg-xwing-kem).
+ *          Secure as long as EITHER X25519 or ML-KEM-768 remains unbroken.
+ *   KDF  : HKDF-SHA-256 (WebCrypto), bound to the suite, key id and KEM ciphertext.
+ *   AEAD : AES-256-GCM (WebCrypto), 96-bit random nonce, envelope header as AAD.
+ *
+ * Every note uses a fresh encapsulation, so the browser never holds a long-term
+ * secret: only the dispatch team's private key can open an envelope.
+ *
+ * This module runs unchanged in browsers (secure contexts) and Node >= 20.
+ */
+import { ml_kem768_x25519 as XWing } from '../vendor/node_modules/@noble/post-quantum/hybrid.js';
+
+export const SUITE = 'XWING-HKDF-SHA256-AES256GCM';
+export const ENVELOPE_TYPE = 'dailygrind.delivery-note';
+export const ENVELOPE_VERSION = 1;
+export const MAX_NOTE_CHARS = 1000;
+const PAD_BLOCK = 256; // hide exact note length: pad plaintext to 256-byte buckets
+const INFO_LABEL = 'DailyGrind delivery-note v1';
+
+const subtle = globalThis.crypto?.subtle;
+const te = new TextEncoder();
+const td = new TextDecoder('utf-8', { fatal: true });
+
+export function isSupported() {
+  return Boolean(subtle && globalThis.crypto?.getRandomValues);
+}
+
+function requireSubtle() {
+  if (!isSupported()) {
+    throw new Error('Web Crypto is unavailable. Encrypted notes require HTTPS (a secure context).');
+  }
+  return subtle;
+}
+
+// ---------- encoding helpers ----------
+export function b64uEncode(bytes) {
+  let bin = '';
+  for (let i = 0; i < bytes.length; i += 0x8000) {
+    bin += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
+  }
+  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+}
+
+export function b64uDecode(str) {
+  if (typeof str !== 'string' || !/^[A-Za-z0-9_-]*$/.test(str)) throw new Error('Invalid base64url');
+  const b64 = str.replace(/-/g, '+').replace(/_/g, '/') + '==='.slice((str.length + 3) % 4);
+  const bin = atob(b64);
+  const out = new Uint8Array(bin.length);
+  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
+  return out;
+}
+
+const toHex = (bytes) => Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
+
+// ---------- keys ----------
+/** SHA-256 fingerprint of a public key; first 16 bytes, hex, grouped for humans. */
+export async function fingerprint(publicKey) {
+  const digest = new Uint8Array(await requireSubtle().digest('SHA-256', publicKey));
+  return toHex(digest.subarray(0, 16)).match(/.{4}/g).join(':');
+}
+
+/** Key id = first 8 bytes of the SHA-256 fingerprint (hex). */
+export async function keyId(publicKey) {
+  return (await fingerprint(publicKey)).replace(/:/g, '').slice(0, 16);
+}
+
+/** Generate a dispatch (recipient) key pair. Run server-side / offline only. */
+export async function generateRecipientKeys() {
+  const { publicKey, secretKey } = XWing.keygen();
+  const kid = await keyId(publicKey);
+  return {
+    publicJwk: { suite: SUITE, kid, publicKey: b64uEncode(publicKey), created: new Date().toISOString() },
+    privateJwk: { suite: SUITE, kid, secretKey: b64uEncode(secretKey), publicKey: b64uEncode(publicKey) },
+  };
+}
+
+/** Validate a published recipient key document and return the raw key. */
+export async function importRecipientPublicKey(doc) {
+  if (!doc || doc.suite !== SUITE) throw new Error(`Unsupported key suite: ${doc?.suite}`);
+  const publicKey = b64uDecode(doc.publicKey);
+  if (publicKey.length !== XWing.lengths.publicKey) throw new Error('Recipient public key has the wrong length');
+  const kid = await keyId(publicKey);
+  if (doc.kid !== kid) throw new Error('Recipient key id does not match its fingerprint');
+  return { suite: SUITE, kid, publicKey, fingerprint: await fingerprint(publicKey) };
+}
+
+// ---------- KDF / AAD ----------
+async function deriveAeadKey(sharedSecret, kid, enc, usage) {
+  const s = requireSubtle();
+  const ikm = await s.importKey('raw', sharedSecret, 'HKDF', false, ['deriveKey']);
+  // Bind the KEM ciphertext via the salt (WebCrypto caps HKDF `info` at 1024 bytes;
+  // the X-Wing ciphertext is 1120 bytes).
+  const salt = await s.digest('SHA-256', enc);
+  const info = te.encode(`${INFO_LABEL}|${SUITE}|${kid}`);
+  return s.deriveKey(
+    { name: 'HKDF', hash: 'SHA-256', salt, info },
+    ikm,
+    { name: 'AES-GCM', length: 256 },
+    false, // non-extractable
+    [usage],
+  );
+}
+
+/** Every header field is authenticated; tampering with any of them fails decryption. */
+function headerAad(h) {
+  return te.encode(JSON.stringify([h.type, h.v, h.suite, h.kid, h.created, h.enc, h.iv]));
+}
+
+// ---------- padding (ISO/IEC 7816-4) ----------
+function pad(bytes) {
+  const total = Math.ceil((bytes.length + 1) / PAD_BLOCK) * PAD_BLOCK;
+  const out = new Uint8Array(total);
+  out.set(bytes);
+  out[bytes.length] = 0x80;
+  return out;
+}
+
+function unpad(bytes) {
+  let i = bytes.length - 1;
+  while (i >= 0 && bytes[i] === 0) i--;
+  if (i < 0 || bytes[i] !== 0x80) throw new Error('Invalid padding');
+  return bytes.subarray(0, i);
+}
+
+// ---------- seal / open ----------
+/**
+ * Encrypt a note to the recipient key.
+ * @param {{kid:string, publicKey:Uint8Array}} recipient  from importRecipientPublicKey()
+ * @param {string} note
+ * @param {object} [meta]  optional non-secret-but-authenticated context (encrypted alongside)
+ */
+export async function sealNote(recipient, note, meta = {}) {
+  const s = requireSubtle();
+  if (typeof note !== 'string' || !note.trim()) throw new Error('Note is empty');
+  if ([...note].length > MAX_NOTE_CHARS) throw new Error(`Note exceeds ${MAX_NOTE_CHARS} characters`);
+
+  const { cipherText, sharedSecret } = XWing.encapsulate(recipient.publicKey);
+  try {
+    const created = new Date().toISOString();
+    const iv = crypto.getRandomValues(new Uint8Array(12));
+    const header = {
+      type: ENVELOPE_TYPE,
+      v: ENVELOPE_VERSION,
+      suite: SUITE,
+      kid: recipient.kid,
+      created,
+      enc: b64uEncode(cipherText),
+      iv: b64uEncode(iv),
+    };
+    const key = await deriveAeadKey(sharedSecret, recipient.kid, cipherText, 'encrypt');
+    const plaintext = pad(te.encode(JSON.stringify({ note, meta })));
+    const ct = new Uint8Array(
+      await s.encrypt({ name: 'AES-GCM', iv, additionalData: headerAad(header), tagLength: 128 }, key, plaintext),
+    );
+    plaintext.fill(0);
+    return { ...header, ct: b64uEncode(ct) };
+  } finally {
+    sharedSecret.fill(0);
+  }
+}
+
+/** Decrypt an envelope with the dispatch private key document. Server-side / staff use. */
+export async function openNote(privateDoc, envelope) {
+  const s = requireSubtle();
+  if (!envelope || envelope.type !== ENVELOPE_TYPE || envelope.v !== ENVELOPE_VERSION) {
+    throw new Error('Not a v1 delivery-note envelope');
+  }
+  if (envelope.suite !== SUITE || privateDoc.suite !== SUITE) throw new Error('Suite mismatch');
+  if (envelope.kid !== privateDoc.kid) throw new Error(`Envelope is for key ${envelope.kid}, not ${privateDoc.kid}`);
+
+  const enc = b64uDecode(envelope.enc);
+  const iv = b64uDecode(envelope.iv);
+  if (enc.length !== XWing.lengths.cipherText) throw new Error('Bad KEM ciphertext length');
+  if (iv.length !== 12) throw new Error('Bad nonce length');
+
+  const secretKey = b64uDecode(privateDoc.secretKey);
+  const sharedSecret = XWing.decapsulate(enc, secretKey);
+  secretKey.fill(0);
+  try {
+    const key = await deriveAeadKey(sharedSecret, envelope.kid, enc, 'decrypt');
+    let pt;
+    try {
+      pt = new Uint8Array(
+        await s.decrypt(
+          { name: 'AES-GCM', iv, additionalData: headerAad(envelope), tagLength: 128 },
+          key,
+          b64uDecode(envelope.ct),
+        ),
+      );
+    } catch {
+      throw new Error('Authentication failed: envelope was tampered with or encrypted to a different key');
+    }
+    const body = JSON.parse(td.decode(unpad(pt)));
+    pt.fill(0);
+    return { note: body.note, meta: body.meta, created: envelope.created, kid: envelope.kid };
+  } finally {
+    sharedSecret.fill(0);
+  }
+}
