index 0000000..bf15fd2
--- /dev/null
+++ b/js/delivery-notes.js
@@ -0,0 +1,140 @@
+// Daily Grind — encrypted delivery notes (homepage UI).
+// Plaintext never leaves this page: notes are sealed in the browser to the dispatch
+// team's published hybrid post-quantum key, and only the envelope is kept.
+
+const KEY_URL = '/keys/dispatch-public.json';
+const STORAGE_KEY = 'dailygrind.deliveryNote.envelope';
+
+const $ = (id) => document.getElementById(id);
+const form = $('dn-form');
+if (form) init();
+
+function init() {
+  const textarea = $('dn-note');
+  const counter = $('dn-count');
+  const submit = $('dn-submit');
+  const status = $('dn-status');
+  const keyInfo = $('dn-key');
+  const result = $('dn-result');
+  const output = $('dn-envelope');
+  const summary = $('dn-summary');
+
+  let ready; // Promise<{ lib, recipient }>
+  const setStatus = (msg, kind = 'info') => {
+    status.textContent = msg;
+    status.dataset.kind = kind;
+  };
+
+  function load() {
+    if (ready) return ready;
+    ready = (async () => {
+      const lib = await import('./delivery-notes-crypto.js');
+      if (!lib.isSupported()) throw new Error('Encrypted notes need a modern browser over HTTPS.');
+      const res = await fetch(KEY_URL, { cache: 'no-cache', credentials: 'omit' });
+      if (!res.ok) throw new Error(`Could not fetch the dispatch key (HTTP ${res.status}).`);
+      const recipient = await lib.importRecipientPublicKey(await res.json());
+      keyInfo.textContent = `Dispatch key ${recipient.fingerprint}`;
+      keyInfo.title = `Key id ${recipient.kid} · ${recipient.suite}`;
+      return { lib, recipient };
+    })();
+    ready.catch((err) => {
+      ready = undefined; // allow retry
+      keyInfo.textContent = 'Dispatch key unavailable';
+      setStatus(err.message, 'error');
+    });
+    return ready;
+  }
+
+  // Warm up the crypto + key once the section approaches the viewport.
+  if ('IntersectionObserver' in window) {
+    const io = new IntersectionObserver((entries) => {
+      if (entries.some((e) => e.isIntersecting)) { io.disconnect(); load(); }
+    }, { rootMargin: '200px' });
+    io.observe(form);
+  } else {
+    load();
+  }
+  textarea.addEventListener('focus', load, { once: true });
+
+  const max = Number(textarea.getAttribute('maxlength')) || 1000;
+  const updateCount = () => {
+    const n = [...textarea.value].length;
+    counter.textContent = `${n} / ${max}`;
+    submit.disabled = n === 0 || !textarea.value.trim();
+  };
+  textarea.addEventListener('input', updateCount);
+  updateCount();
+
+  document.querySelectorAll('[data-dn-chip]').forEach((chip) => {
+    chip.addEventListener('click', () => {
+      const add = chip.dataset.dnChip;
+      textarea.value = textarea.value ? `${textarea.value.replace(/\s+$/, '')}\n${add}` : add;
+      textarea.focus();
+      textarea.setSelectionRange(textarea.value.length, textarea.value.length);
+      updateCount();
+    });
+  });
+
+  form.addEventListener('submit', async (e) => {
+    e.preventDefault();
+    const note = textarea.value;
+    if (!note.trim()) return;
+    submit.disabled = true;
+    setStatus('Establishing hybrid shared secret and encrypting…');
+    try {
+      const { lib, recipient } = await load();
+      const envelope = await lib.sealNote(recipient, note, { surface: 'homepage' });
+      const json = JSON.stringify(envelope);
+      try { sessionStorage.setItem(STORAGE_KEY, json); } catch { /* storage disabled: envelope still shown */ }
+      textarea.value = ''; // drop plaintext from the DOM as soon as it is sealed
+      updateCount();
+      showEnvelope(envelope, json);
+      setStatus('Note encrypted and attached to your next order. Only our dispatch team can read it.', 'success');
+    } catch (err) {
+      setStatus(`Encryption failed: ${err.message}`, 'error');
+      submit.disabled = false;
+    }
+  });
+
+  function showEnvelope(envelope, json) {
+    output.textContent = JSON.stringify(
+      { ...envelope, enc: abbreviate(envelope.enc), ct: abbreviate(envelope.ct) },
+      null, 2,
+    );
+    output.dataset.full = json;
+    summary.textContent =
+      `${envelope.suite} · key ${envelope.kid} · ${new Date(envelope.created).toLocaleString()} · ${json.length.toLocaleString()} bytes`;
+    result.hidden = false;
+  }
+
+  $('dn-copy').addEventListener('click', async () => {
+    try {
+      await navigator.clipboard.writeText(output.dataset.full || '');
+      setStatus('Encrypted envelope copied to clipboard.', 'success');
+    } catch {
+      setStatus('Clipboard unavailable — select the envelope text to copy it.', 'error');
+    }
+  });
+
+  $('dn-discard').addEventListener('click', () => {
+    try { sessionStorage.removeItem(STORAGE_KEY); } catch { /* ignore */ }
+    result.hidden = true;
+    output.textContent = '';
+    delete output.dataset.full;
+    setStatus('Encrypted note removed from this order.');
+    textarea.focus();
+  });
+
+  // Restore a previously attached envelope (ciphertext only) for this session.
+  try {
+    const saved = sessionStorage.getItem(STORAGE_KEY);
+    if (saved) {
+      showEnvelope(JSON.parse(saved), saved);
+      setStatus('An encrypted note is already attached to your next order.', 'success');
+    }
+  } catch { /* ignore corrupt or unavailable storage */ }
+}
+
+function abbreviate(s) {
+  return s.length > 48 ? `${s.slice(0, 24)}…${s.slice(-16)} (${s.length} chars)` : s;
+}
