+#!/usr/bin/env node
+// Generate the dispatch team's hybrid (X25519 + ML-KEM-768) key pair.
+//   node scripts/generate-dispatch-keys.mjs [--force]
+// Writes the public key to keys/dispatch-public.json (served to browsers) and the
+// private key to secrets/dispatch-private.json (git-ignored, mode 0600). Keep it offline.
+import { mkdir, writeFile, access } from 'node:fs/promises';
+import { dirname, join } from 'node:path';
+import { fileURLToPath } from 'node:url';
+import { generateRecipientKeys, fingerprint, b64uDecode } from '../js/delivery-notes-crypto.js';
+
+const root = join(dirname(fileURLToPath(import.meta.url)), '..');
+const pubPath = join(root, 'keys', 'dispatch-public.json');
+const privPath = join(root, 'secrets', 'dispatch-private.json');
+
+const exists = (p) => access(p).then(() => true, () => false);
+if (!process.argv.includes('--force') && (await exists(privPath))) {
+  console.error(`Refusing to overwrite ${privPath} (pass --force to rotate keys).`);
+  process.exit(1);
+}
+
+const { publicJwk, privateJwk } = await generateRecipientKeys();
+await mkdir(dirname(pubPath), { recursive: true });
+await mkdir(dirname(privPath), { recursive: true, mode: 0o700 });
+await writeFile(privPath, JSON.stringify(privateJwk, null, 2) + '\n', { mode: 0o600 });
+await writeFile(pubPath, JSON.stringify(publicJwk, null, 2) + '\n');
+console.log(`kid:         ${publicJwk.kid}`);
+console.log(`fingerprint: ${await fingerprint(b64uDecode(publicJwk.publicKey))}`);
+console.log(`public  -> ${pubPath}`);
+console.log(`private -> ${privPath}  (never commit or upload this file)`);
