+#!/usr/bin/env node
+// Decrypt a delivery-note envelope (dispatch staff only).
+//   node scripts/open-delivery-note.mjs envelope.json [secrets/dispatch-private.json]
+//   cat envelope.json | node scripts/open-delivery-note.mjs -
+import { readFile } from 'node:fs/promises';
+import { openNote } from '../js/delivery-notes-crypto.js';
+
+const [src = '-', keyPath = 'secrets/dispatch-private.json'] = process.argv.slice(2);
+const readStdin = async () => { let s = ''; for await (const c of process.stdin) s += c; return s; };
+try {
+  const envelope = JSON.parse(src === '-' ? await readStdin() : await readFile(src, 'utf8'));
+  const priv = JSON.parse(await readFile(keyPath, 'utf8'));
+  const { note, meta, created, kid } = await openNote(priv, envelope);
+  console.log(JSON.stringify({ kid, created, meta, note }, null, 2));
+} catch (err) {
+  console.error(`Could not open note: ${err.message}`);
+  process.exit(1);
+}
