+#!/usr/bin/env node
+// Round-trip and tamper tests for the delivery-notes crypto core.
+import assert from 'node:assert/strict';
+import { generateRecipientKeys, importRecipientPublicKey, sealNote, openNote, b64uEncode, b64uDecode, MAX_NOTE_CHARS } from '../js/delivery-notes-crypto.js';
+
+const { publicJwk, privateJwk } = await generateRecipientKeys();
+const recipient = await importRecipientPublicKey(publicJwk);
+const note = 'Gate code 4821# — leave by the side door. 🐕 friendly dog.';
+
+const env = await sealNote(recipient, note, { surface: 'test' });
+const out = await openNote(privateJwk, env);
+assert.equal(out.note, note);
+assert.deepEqual(out.meta, { surface: 'test' });
+assert.ok(!JSON.stringify(env).includes('4821'), 'plaintext leaked into envelope');
+
+// fresh encapsulation + nonce every time
+const env2 = await sealNote(recipient, note);
+assert.notEqual(env.enc, env2.enc); assert.notEqual(env.iv, env2.iv);
+
+// length hiding: short notes share a size bucket
+assert.equal(b64uDecode((await sealNote(recipient, 'a')).ct).length, b64uDecode((await sealNote(recipient, 'a'.repeat(150))).ct).length);
+
+const flip = (s) => { const b = b64uDecode(s); b[b.length >> 1] ^= 1; return b64uEncode(b); };
+for (const field of ['ct', 'enc', 'iv']) await assert.rejects(openNote(privateJwk, { ...env, [field]: flip(env[field]) }), `tampered ${field}`);
+await assert.rejects(openNote(privateJwk, { ...env, created: '2020-01-01T00:00:00.000Z' }), /Authentication failed/);
+
+// wrong recipient key
+const other = await generateRecipientKeys();
+await assert.rejects(openNote({ ...other.privateJwk, kid: env.kid }, env), /Authentication failed/);
+
+// key document validation
+await assert.rejects(importRecipientPublicKey({ ...publicJwk, kid: '0000000000000000' }), /fingerprint/);
+await assert.rejects(importRecipientPublicKey({ ...publicJwk, suite: 'RSA' }), /Unsupported/);
+await assert.rejects(sealNote(recipient, '   '), /empty/);
+await assert.rejects(sealNote(recipient, 'x'.repeat(MAX_NOTE_CHARS + 1)), /exceeds/);
+
+console.log('delivery-notes crypto: all tests passed');

