diff --git a/assets/site.css b/assets/site.css
new file mode 100644
index 0000000..9f92479
--- /dev/null
+++ b/assets/site.css
@@ -0,0 +1,259 @@
+/* ==========================================================================
+   The Daily Grind — shared styles
+   Loaded as a classic <link rel="stylesheet"> in <head>, so it is
+   render-blocking: header/hero styling is always applied before first paint
+   and therefore before any view transition snapshot is taken.
+   ========================================================================== */
+
+:root {
+  --primary: #4e342e;
+  --primary-dark: #3e2723;
+  --secondary: #d7ccc8;
+  --accent: #ffab40;
+  --text: #3e2723;
+  --light: #fafafa;
+  --surface: #ffffff;
+  --shadow: rgba(0, 0, 0, 0.1);
+  --heading: #4e342e;
+  color-scheme: light;
+}
+
+/* Theme is applied by the inline script in <head> before first paint. */
+:root[data-theme="dark"] {
+  --primary: #2b1d19;
+  --primary-dark: #1c1210;
+  --secondary: #3a2c27;
+  --text: #efe7e3;
+  --light: #1a1412;
+  --surface: #261d1a;
+  --shadow: rgba(0, 0, 0, 0.45);
+  --heading: #ffab40;
+  color-scheme: dark;
+}
+
+* {
+  box-sizing: border-box;
+  margin: 0;
+  padding: 0;
+}
+
+body {
+  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
+  line-height: 1.6;
+  color: var(--text);
+  background-color: var(--light);
+}
+
+/* Navigation */
+nav {
+  background: var(--primary);
+  color: white;
+  padding: 1rem 5%;
+  display: flex;
+  justify-content: space-between;
+  align-items: center;
+  position: sticky;
+  top: 0;
+  z-index: 1000;
+  /* Keep the header as its own stable layer across page transitions. */
+  view-transition-name: site-header;
+}
+
+.logo {
+  font-size: 1.5rem;
+  font-weight: bold;
+  letter-spacing: 1px;
+  color: inherit;
+  text-decoration: none;
+}
+
+nav ul {
+  display: flex;
+  align-items: center;
+  list-style: none;
+}
+
+nav ul li {
+  margin-left: 20px;
+}
+
+nav a {
+  color: white;
+  text-decoration: none;
+  font-size: 0.9rem;
+  transition: color 0.3s;
+}
+
+nav a:hover,
+nav a[aria-current="page"] {
+  color: var(--accent);
+}
+
+.logout-link {
+  border: 1px solid var(--accent);
+  padding: 5px 12px;
+  border-radius: 4px;
+}
+
+.theme-toggle {
+  background: none;
+  border: 1px solid rgba(255, 255, 255, 0.4);
+  color: white;
+  border-radius: 4px;
+  padding: 4px 8px;
+  cursor: pointer;
+  font: inherit;
+  font-size: 0.85rem;
+}
+
+/* Hero Section */
+.hero {
+  height: 60vh;
+  background: linear-gradient(rgba(0, 0, 0, 0.5), rgba(0, 0, 0, 0.5)),
+    var(--hero-image, url('https://images.unsplash.com/photo-1495474472287-4d71bcdd2085?auto=format&fit=crop&w=1350&q=80'));
+  background-size: cover;
+  background-position: center;
+  display: flex;
+  flex-direction: column;
+  justify-content: center;
+  align-items: center;
+  color: white;
+  text-align: center;
+  padding: 0 20px;
+  /* Morph the hero banner between pages. */
+  view-transition-name: hero;
+}
+
+.hero--compact {
+  height: 40vh;
+}
+
+.hero h1 {
+  font-size: 3rem;
+  margin-bottom: 1rem;
+  view-transition-name: hero-title;
+}
+
+/* Content Sections */
+.container {
+  max-width: 1100px;
+  margin: 40px auto;
+  padding: 0 20px;
+}
+
+.section-title {
+  text-align: center;
+}
+
+.grid {
+  display: grid;
+  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
+  gap: 20px;
+  margin-top: 20px;
+}
+
+.card {
+  background: var(--surface);
+  padding: 20px;
+  border-radius: 8px;
+  box-shadow: 0 2px 5px var(--shadow);
+  text-align: center;
+}
+
+.card h3 {
+  margin-bottom: 10px;
+  color: var(--heading);
+}
+
+.card img {
+  width: 100%;
+  height: 160px;
+  object-fit: cover;
+  border-radius: 6px;
+  margin-bottom: 12px;
+}
+
+.price {
+  font-weight: bold;
+  margin-top: 8px;
+}
+
+.btn {
+  display: inline-block;
+  background: var(--primary);
+  color: white;
+  padding: 10px 20px;
+  text-decoration: none;
+  border-radius: 5px;
+  margin-top: 15px;
+  transition: background 0.3s;
+}
+
+.btn:hover {
+  background: var(--primary-dark);
+}
+
+footer {
+  background: var(--secondary);
+  text-align: center;
+  padding: 40px 20px;
+  margin-top: 40px;
+}
+
+.footer-links {
+  margin-bottom: 20px;
+}
+
+.footer-links a {
+  margin: 0 10px;
+  color: var(--text);
+  text-decoration: none;
+  font-size: 0.85rem;
+}
+
+/* ==========================================================================
+   Cross-document view transitions (same-origin navigations)
+   ========================================================================== */
+
+@view-transition {
+  navigation: auto;
+}
+
+/* Header stays put — no cross-fade flicker on the sticky nav. */
+::view-transition-old(site-header),
+::view-transition-new(site-header) {
+  animation: none;
+  mix-blend-mode: normal;
+}
+
+/* Hero banner morphs size/position; content cross-fades. */
+::view-transition-group(hero),
+::view-transition-group(hero-title) {
+  animation-duration: 0.45s;
+  animation-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
+}
+
+/* Main page content slides/fades. */
+@keyframes dg-fade-out {
+  to { opacity: 0; transform: translateY(-12px); }
+}
+
+@keyframes dg-fade-in {
+  from { opacity: 0; transform: translateY(12px); }
+}
+
+::view-transition-old(root) {
+  animation: 0.25s cubic-bezier(0.4, 0, 1, 1) both dg-fade-out;
+}
+
+::view-transition-new(root) {
+  animation: 0.35s cubic-bezier(0, 0, 0.2, 1) 0.05s both dg-fade-in;
+}
+
+@media (prefers-reduced-motion: reduce) {
+  ::view-transition-group(*),
+  ::view-transition-old(*),
+  ::view-transition-new(*) {
+    animation: none !important;
+  }
+}
