diff --git a/src/scripts/page-transitions.ts b/src/scripts/page-transitions.ts
new file mode 100644
index 0000000..13be2e7
--- /dev/null
+++ b/src/scripts/page-transitions.ts
@@ -0,0 +1,117 @@
+/**
+ * Page transition readiness gate.
+ *
+ * Astro's ClientRouter already waits for new stylesheets before swapping the
+ * DOM, but not for above-the-fold images or web fonts. If the swap happens
+ * before those are ready, the view transition snapshots a half-rendered page
+ * (empty image boxes, fallback fonts) and then "pops" once they arrive.
+ *
+ * This hooks into `astro:before-preparation` and extends the loader so that,
+ * after the new document has been fetched and parsed, we:
+ *   1. fetch + decode the critical images of the incoming page
+ *      (`[data-vt-critical]`, or the first image inside <main> as a fallback),
+ *   2. make sure the web fonts the new page uses are loaded,
+ * all bounded by a timeout so a slow asset never blocks navigation.
+ *
+ * Only once that is done does Astro start the view transition, so the "new"
+ * snapshot is visually complete.
+ */
+
+const MAX_WAIT_MS = 2000;
+const PROGRESS_DELAY_MS = 150;
+const BRAND_FONT = '500 1em "Grenze"';
+
+// Hold on to decoded images until the new page is shown so the browser keeps
+// the decoded bitmaps around and paints the swapped-in <img> elements instantly.
+let retained: HTMLImageElement[] = [];
+
+function criticalImages(doc: Document): HTMLImageElement[] {
+  const marked = Array.from(doc.querySelectorAll<HTMLImageElement>('img[data-vt-critical]'));
+  if (marked.length) return marked;
+  const first = doc.querySelector<HTMLImageElement>('main img');
+  return first ? [first] : [];
+}
+
+function preloadImage(source: HTMLImageElement, baseUrl: URL): Promise<void> {
+  const src = source.getAttribute('src');
+  if (!src) return Promise.resolve();
+
+  const img = new Image();
+  const crossOrigin = source.getAttribute('crossorigin');
+  if (crossOrigin !== null) img.crossOrigin = crossOrigin;
+  const sizes = source.getAttribute('sizes');
+  if (sizes) img.sizes = sizes;
+  const srcset = source.getAttribute('srcset');
+  if (srcset) img.srcset = srcset;
+  img.decoding = 'async';
+  img.fetchPriority = 'high';
+  img.src = new URL(src, baseUrl).href;
+  retained.push(img);
+
+  return img.decode().catch(() => {
+    /* broken / blocked images must not block navigation */
+  });
+}
+
+function preloadFonts(doc: Document): Promise<unknown> {
+  if (!('fonts' in document)) return Promise.resolve();
+  const tasks: Promise<unknown>[] = [];
+  if (doc.querySelector('.font-brand')) {
+    tasks.push(document.fonts.load(BRAND_FONT).catch(() => {}));
+  }
+  return Promise.all(tasks).then(() => document.fonts.ready);
+}
+
+function timeout(ms: number, signal: AbortSignal): Promise<void> {
+  return new Promise((resolve) => {
+    const id = window.setTimeout(resolve, ms);
+    signal.addEventListener('abort', () => {
+      window.clearTimeout(id);
+      resolve();
+    }, { once: true });
+  });
+}
+
+// Slim progress indicator, only shown if loading takes noticeably long.
+let progressTimer: number | undefined;
+function startProgress() {
+  window.clearTimeout(progressTimer);
+  progressTimer = window.setTimeout(() => {
+    document.documentElement.classList.add('is-navigating');
+  }, PROGRESS_DELAY_MS);
+}
+function stopProgress() {
+  window.clearTimeout(progressTimer);
+  document.documentElement.classList.remove('is-navigating');
+}
+
+document.addEventListener('astro:before-preparation', (event) => {
+  const originalLoader = event.loader;
+  startProgress();
+
+  event.loader = async () => {
+    await originalLoader();
+    // The default loader may have cancelled the navigation (e.g. full reload).
+    if (event.defaultPrevented || event.signal.aborted) {
+      if (event.defaultPrevented) stopProgress();
+      return;
+    }
+
+    const doc = event.newDocument;
+    const ready = Promise.all([
+      ...criticalImages(doc).map((img) => preloadImage(img, event.to)),
+      preloadFonts(doc),
+    ]);
+
+    await Promise.race([ready, timeout(MAX_WAIT_MS, event.signal)]);
+  };
+});
+
+document.addEventListener('astro:after-swap', stopProgress);
+document.addEventListener('astro:page-load', () => {
+  stopProgress();
+  // Release references once the new page has rendered.
+  requestAnimationFrame(() => {
+    retained = [];
+  });
+});
