+// Runs the smallpt WebAssembly module off the main thread.
+// The page spawns several of these and hands each one bands of rows.
+//
+// Message in:  { id, width, height, spp, colors, y0, y1 }
+//   colors: array indexed by sphere, each [r,g,b] or null (keep default).
+//   y0..y1: smallpt row range (smallpt's y runs bottom-up).
+// Message out: { id, y0, y1, pixels } — RGBA for image rows (h-y1)..(h-y0-1).
+import initSmallpt from './smallpt.js';
+
+const wasmReady = initSmallpt();
+let preparedJob = null;
+let ptr = 0;
+
+self.onmessage = async ({ data }) => {
+  const { id, width, height, spp, colors, y0, y1 } = data;
+  const wasm = await wasmReady;
+
+  if (preparedJob !== id) {
+    wasm._reset_scene();
+    colors?.forEach((c, i) => {
+      if (c) wasm._set_sphere_color(i, c[0], c[1], c[2]);
+    });
+    ptr = wasm._render_begin(width, height, spp);
+    preparedJob = id;
+  }
+
+  wasm._render_rows(y0, y1);
+
+  // Read HEAPU8 fresh after the call: memory growth detaches old views.
+  const start = ptr + (height - y1) * width * 4;
+  const pixels = wasm.HEAPU8.slice(start, start + (y1 - y0) * width * 4);
+  self.postMessage({ id, y0, y1, pixels }, [pixels.buffer]);
+};
