+#!/bin/sh
+# Build smallpt to an ES6 WebAssembly module for use in a Web Worker.
+set -e
+cd "$(dirname "$0")/.."
+em++ -c wasm/smallpt.cpp -o wasm/smallpt.o -O3 -Wall -Werror
+em++ wasm/smallpt.o -o pt/smallpt.js \
+  -O3 \
+  -sSTRICT \
+  -sEXPORT_ES6 \
+  -sENVIRONMENT=worker \
+  -sALLOW_MEMORY_GROWTH \
+  -sSTACK_SIZE=1MB \
+  -sEXPORTED_FUNCTIONS=_render_begin,_render_rows,_set_sphere_color,_reset_scene,_sphere_count \
+  -sEXPORTED_RUNTIME_METHODS=HEAPU8
+rm -f wasm/smallpt.o
