+// ---------------------------------------------------------------------------
+// WebAssembly entry points (replace smallpt's main(), which wrote image.ppm).
+// The per-pixel sampling loop below is the original main() loop body, split so
+// JS can render a band of rows at a time and report progress.
+// ---------------------------------------------------------------------------
+static const Sphere defaults[] = {
+  spheres[0],spheres[1],spheres[2],spheres[3],spheres[4],
+  spheres[5],spheres[6],spheres[7],spheres[8]};
+static int W=0, H=0, samps=1;
+static Vec *c=0; static uint8_t *rgba=0;
+static Ray cam(Vec(50,52,295.6), Vec(0,-0.042612,-1).norm()); // cam pos, dir
+static Vec cx, cy;
+extern "C" {
+EMSCRIPTEN_KEEPALIVE int sphere_count(){ return int(sizeof(spheres)/sizeof(Sphere)); }
+EMSCRIPTEN_KEEPALIVE void set_sphere_color(int i, double r, double g, double b){
+  if (i>=0 && i<sphere_count()) spheres[i].c = Vec(r,g,b);
+}
+EMSCRIPTEN_KEEPALIVE void reset_scene(){
+  for (int i=0;i<sphere_count();i++) spheres[i]=defaults[i];
+}
+// Allocate buffers; spp is total samples per pixel (like argv[1]).
+EMSCRIPTEN_KEEPALIVE uint8_t* render_begin(int w, int h, int spp){
+  W=w; H=h; samps = spp/4 > 0 ? spp/4 : 1;
+  delete[] c; delete[] rgba;
+  c = new Vec[w*h]; rgba = new uint8_t[w*h*4];
+  for (int i=0;i<w*h*4;i++) rgba[i] = (i&3)==3 ? 255 : 0;
+  cx=Vec(w*.5135/h); cy=(cx%cam.d).norm()*.5135;
+  return rgba;
+}
+// Render image rows [y0,y1) (bottom-up, as in smallpt) into the RGBA buffer.
+EMSCRIPTEN_KEEPALIVE void render_rows(int y0, int y1){
+  int w=W, h=H; Vec r;
+  for (int y=y0; y<y1 && y<h; y++){                // Loop over image rows
+    unsigned short Xi[3]={0,0,(unsigned short)(y*y*y)};
+    for (int x=0; x<w; x++){                       // Loop cols
+      int i=(h-y-1)*w+x;
+      for (int sy=0; sy<2; sy++)                   // 2x2 subpixel rows
+        for (int sx=0; sx<2; sx++, r=Vec()){       // 2x2 subpixel cols
+          for (int s=0; s<samps; s++){
+            double r1=2*erand48(Xi), dx=r1<1 ? sqrt(r1)-1: 1-sqrt(2-r1);
+            double r2=2*erand48(Xi), dy=r2<1 ? sqrt(r2)-1: 1-sqrt(2-r2);
+            Vec d = cx*( ( (sx+.5 + dx)/2 + x)/w - .5) +
+                    cy*( ( (sy+.5 + dy)/2 + y)/h - .5) + cam.d;
+            r = r + radiance(Ray(cam.o+d*140,d.norm()),0,Xi)*(1./samps);
+          } // Camera rays are pushed ^^^^^ forward to start in interior
+          c[i] = c[i] + Vec(clamp(r.x),clamp(r.y),clamp(r.z))*.25;
+        }
+      rgba[i*4]=toInt(c[i].x); rgba[i*4+1]=toInt(c[i].y); rgba[i*4+2]=toInt(c[i].z);
+    }
+  }
+}
+}

