+// Runs the smallpt WebAssembly module off the main thread.
+// Message in:  { width, height, passes, sampsPerPass, colors: [[i, r, g, b], ...] }
+// Messages out: { type: 'progress', pixels, pass, passes, row }
+//               { type: 'done', pixels, ms }
+importScripts('smallpt.js');
+
+const modulePromise = createSmallpt();
+const ROWS_PER_CHUNK = 8;
+
+self.onmessage = async ({ data }) => {
+  const { width, height, passes, sampsPerPass, colors } = data;
+  const mod = await modulePromise;
+  for (const [i, r, g, b] of colors || []) mod._set_sphere_color(i, r, g, b);
+  const ptr = mod._init(width, height);
+  const size = width * height * 4;
+  const start = performance.now();
+
+  for (let pass = 0; pass < passes; pass++) {
+    for (let y = 0; y < height; y += ROWS_PER_CHUNK) {
+      mod._render_rows(y, y + ROWS_PER_CHUNK, sampsPerPass, pass);
+      // Stream partial progress during the first pass so the image fills in.
+      if (pass === 0 || y + ROWS_PER_CHUNK >= height) {
+        const pixels = mod.HEAPU8.slice(ptr, ptr + size);
+        self.postMessage({ type: 'progress', pixels, pass, passes, row: Math.min(y + ROWS_PER_CHUNK, height) }, [pixels.buffer]);
+      }
+    }
+  }
+  const pixels = mod.HEAPU8.slice(ptr, ptr + size);
+  self.postMessage({ type: 'done', pixels, ms: performance.now() - start }, [pixels.buffer]);
+};
