+#!/bin/sh
+# Builds wasm/smallpt_wasm.cpp -> pathtracer/smallpt.{js,wasm} (requires Emscripten)
+set -e
+cd "$(dirname "$0")/.."
+em++ -O3 wasm/smallpt_wasm.cpp -o pathtracer/smallpt.js \
+  -sMODULARIZE=1 -sEXPORT_NAME=createSmallpt -sENVIRONMENT=worker \
+  -sALLOW_MEMORY_GROWTH=1 -sFILESYSTEM=0 \
+  -sEXPORTED_FUNCTIONS=_init,_render_rows,_set_sphere_color,_sphere_count,_malloc,_free \
+  -sEXPORTED_RUNTIME_METHODS=HEAPU8
