+#!/usr/bin/env sh
+# Compiles wasm/smallpt.cpp to an ES6 WebAssembly module consumed by
+# src/wasm/smallpt.worker.ts. Requires Emscripten (em++) on PATH.
+set -eu
+cd "$(dirname "$0")/.."
+
+OUT=src/wasm/generated
+mkdir -p "$OUT" build
+# -flto omitted: the distro-packaged LTO libc++ fails to link (__cxa_increment_exception_refcount).
+FLAGS="-O3 -Wall -Werror"
+
+em++ -c wasm/smallpt.cpp -o build/smallpt.o $FLAGS
+em++ build/smallpt.o -o "$OUT/smallpt.js" $FLAGS \
+  -sSTRICT \
+  -sEXPORT_ES6 \
+  -sENVIRONMENT=worker \
+  -sALLOW_MEMORY_GROWTH \
+  -sSTACK_SIZE=1MB \
+  -sEXPORTED_FUNCTIONS=_render_row,_set_sphere_color,_sphere_count,_malloc,_free \
+  -sEXPORTED_RUNTIME_METHODS=HEAPF32
+
+echo "Built $OUT/smallpt.js and $OUT/smallpt.wasm"
