new file mode 100644
index 0000000..98fa78b
--- /dev/null
+++ b/src/components/SmallptRender.astro
@@ -0,0 +1,308 @@
+---
+/**
+ * Runs Kevin Beason's smallpt path tracer (compiled to WebAssembly, see
+ * wasm/smallpt.cpp and scripts/build-wasm.sh) in a pool of Web Workers and
+ * progressively renders the result into a canvas.
+ */
+const WIDTH = 320;
+const HEIGHT = 240;
+---
+
+<section class="p-4 md:p-6" aria-labelledby="smallpt-heading">
+  <h2 id="smallpt-heading" class="text-3xl font-bold border-b-2 border-gray-900 pb-2 mb-6 lg:mb-8">
+    Interactive: Light, Simulated
+  </h2>
+
+  <smallpt-render class="grid gap-6 md:grid-cols-3" data-width={WIDTH} data-height={HEIGHT}>
+    <figure class="md:col-span-2">
+      <canvas
+        width={WIDTH}
+        height={HEIGHT}
+        class="block w-full h-auto bg-gray-900"
+        style={`aspect-ratio: ${WIDTH} / ${HEIGHT}`}
+        role="img"
+        aria-label="Path-traced Cornell box scene with colored walls, a mirror sphere and a glass sphere"
+      ></canvas>
+      <progress class="block w-full h-1 mt-2 accent-amber-400" max="1" value="0" aria-label="Render progress"></progress>
+      <figcaption class="text-xs text-gray-500 mt-2">
+        Rendered live in your browser by
+        <a class="underline hover:text-amber-700" href="http://www.kevinbeason.com/smallpt/">smallpt</a>,
+        Kevin Beason's 99-line C++ path tracer, compiled to WebAssembly.
+      </figcaption>
+    </figure>
+
+    <div class="flex flex-col gap-4">
+      <p class="text-gray-700">
+        Every pixel is computed by tracing random light paths through a scene made entirely of spheres;
+        even the walls are spheres with enormous radii. The image sharpens as more samples are added.
+      </p>
+
+      <button
+        type="button"
+        data-randomize
+        class="self-start px-6 py-3 bg-gray-900 text-white font-semibold hover:bg-amber-700 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-amber-700 transition-colors"
+      >
+        Randomize colors &amp; render again
+      </button>
+
+      <p class="text-sm text-gray-600 tabular-nums" data-progress-text>Waiting to start…</p>
+      <p class="sr-only" role="status" data-status></p>
+
+      <div>
+        <h3 class="text-sm font-bold uppercase tracking-wide text-gray-900 mb-2">Sphere colors</h3>
+        <ul class="grid grid-cols-2 gap-x-4 gap-y-1 text-sm text-gray-700" data-swatches></ul>
+      </div>
+    </div>
+  </smallpt-render>
+</section>
+
+<script>
+  import type { RenderTask, RGB, WorkerMessage } from '../wasm/protocol';
+
+  // Spheres in smallpt's scene whose colors we expose (index into spheres[]).
+  // Front wall (3) sits behind the camera and the light (8) is purely emissive.
+  const SPHERES: { index: number; name: string; kind: 'wall' | 'ball' }[] = [
+    { index: 0, name: 'Left wall', kind: 'wall' },
+    { index: 1, name: 'Right wall', kind: 'wall' },
+    { index: 2, name: 'Back wall', kind: 'wall' },
+    { index: 4, name: 'Floor', kind: 'wall' },
+    { index: 5, name: 'Ceiling', kind: 'wall' },
+    { index: 6, name: 'Mirror ball', kind: 'ball' },
+    { index: 7, name: 'Glass ball', kind: 'ball' },
+  ];
+
+  // The original smallpt scene colors.
+  const DEFAULT_COLORS: Record<number, RGB> = {
+    0: [0.75, 0.25, 0.25],
+    1: [0.25, 0.25, 0.75],
+    2: [0.75, 0.75, 0.75],
+    4: [0.75, 0.75, 0.75],
+    5: [0.75, 0.75, 0.75],
+    6: [0.999, 0.999, 0.999],
+    7: [0.999, 0.999, 0.999],
+  };
+
+  const PASSES = 32;
+  const SPP_PER_PASS = 8; // smallpt uses spp/4 samples per 2x2 subpixel
+  const ROWS_PER_TASK = 4;
+
+  const rand = (min: number, max: number) => min + Math.random() * (max - min);
+
+  function hslToRgb(h: number, s: number, l: number): RGB {
+    const k = (n: number) => (n + h / 30) % 12;
+    const a = s * Math.min(l, 1 - l);
+    const f = (n: number) => l - a * Math.max(-1, Math.min(k(n) - 3, 9 - k(n), 1));
+    return [f(0), f(8), f(4)];
+  }
+
+  function randomColors(): Record<number, RGB> {
+    const colors: Record<number, RGB> = {};
+    for (const { index, kind } of SPHERES) {
+      // Walls: mid-tone diffuse colors. Balls: bright tints so the mirror
+      // still reflects and the glass still transmits plenty of light.
+      colors[index] =
+        kind === 'wall'
+          ? hslToRgb(rand(0, 360), rand(0.25, 0.85), rand(0.3, 0.6))
+          : hslToRgb(rand(0, 360), rand(0.4, 1), rand(0.6, 0.85));
+    }
+    return colors;
+  }
+
+  // smallpt's toInt(): gamma 2.2, then scale to 0..255.
+  const toByte = (x: number) => Math.floor(Math.pow(Math.min(Math.max(x, 0), 1), 1 / 2.2) * 255 + 0.5);
+  const toCss = ([r, g, b]: RGB) => `rgb(${toByte(r)} ${toByte(g)} ${toByte(b)})`;
+
+  class SmallptRender extends HTMLElement {
+    #width = 0;
+    #height = 0;
+    #ctx!: CanvasRenderingContext2D;
+    #image!: ImageData;
+    #accum!: Float32Array;
+    #rowPasses!: Uint16Array;
+    #dirtyRows = new Set<number>();
+    #frame = 0;
+
+    #workers: Worker[] = [];
+    #idle: Worker[] = [];
+    #queue: RenderTask[] = [];
+    #jobId = 0;
+    #done = 0;
+    #total = 0;
+    #startedAt = 0;
+    #observer?: IntersectionObserver;
+    #abort = new AbortController();
+
+    connectedCallback() {
+      this.#width = Number(this.dataset.width);
+      this.#height = Number(this.dataset.height);
+      const canvas = this.querySelector('canvas')!;
+      this.#ctx = canvas.getContext('2d')!;
+      this.#image = this.#ctx.createImageData(this.#width, this.#height);
+      this.#accum = new Float32Array(this.#width * this.#height * 3);
+      this.#rowPasses = new Uint16Array(this.#height);
+      this.#abort = new AbortController();
+
+      this.querySelector('[data-randomize]')!.addEventListener(
+        'click',
+        () => {
+          this.#ensureWorkers();
+          this.#render(randomColors());
+        },
+        { signal: this.#abort.signal },
+      );
+
+      // Only spin up the CPU-heavy workers once the demo is on screen.
+      this.#showSwatches(DEFAULT_COLORS);
+      this.#observer = new IntersectionObserver((entries) => {
+        if (!entries.some((e) => e.isIntersecting)) return;
+        this.#observer?.disconnect();
+        if (this.#jobId === 0) {
+          this.#ensureWorkers();
+          this.#render(DEFAULT_COLORS);
+        }
+      });
+      this.#observer.observe(this);
+    }
+
+    disconnectedCallback() {
+      this.#abort.abort();
+      this.#observer?.disconnect();
+      cancelAnimationFrame(this.#frame);
+      this.#frame = 0;
+      for (const w of this.#workers) w.terminate();
+      this.#workers = [];
+      this.#idle = [];
+      this.#queue = [];
+      this.#jobId = 0;
+    }
+
+    #ensureWorkers() {
+      if (this.#workers.length) return;
+      const count = Math.max(1, Math.min((navigator.hardwareConcurrency || 4) - 1, 16));
+      for (let i = 0; i < count; i++) {
+        const worker = new Worker(new URL('../wasm/smallpt.worker.ts', import.meta.url), { type: 'module' });
+        worker.onmessage = (e: MessageEvent<WorkerMessage>) => this.#onMessage(worker, e.data);
+        worker.onerror = (e) => this.#fail(e.message || 'Worker failed to load');
+        this.#workers.push(worker);
+      }
+    }
+
+    #render(colors: Record<number, RGB>) {
+      const jobId = ++this.#jobId;
+      const baseSeed = (Math.random() * 2 ** 32) >>> 0;
+      this.#queue = [];
+      for (let pass = 0; pass < PASSES; pass++) {
+        const seed = (baseSeed + pass * 0x9e3779b9) >>> 0;
+        for (let row0 = 0; row0 < this.#height; row0 += ROWS_PER_TASK) {
+          this.#queue.push({
+            jobId,
+            row0,
+            rows: Math.min(ROWS_PER_TASK, this.#height - row0),
+            width: this.#width,
+            height: this.#height,
+            spp: SPP_PER_PASS,
+            seed,
+            colors,
+          });
+        }
+      }
+      this.#accum.fill(0);
+      this.#rowPasses.fill(0);
+      this.#done = 0;
+      this.#total = this.#queue.length;
+      this.#startedAt = performance.now();
+      this.#showSwatches(colors);
+      this.#announce('Rendering started.');
+      this.#updateProgress();
+      while (this.#idle.length && this.#queue.length) this.#dispatch(this.#idle.pop()!);
+    }
+
+    #dispatch(worker: Worker) {
+      const task = this.#queue.shift();
+      if (task) worker.postMessage(task);
+      else this.#idle.push(worker);
+    }
+
+    #onMessage(worker: Worker, msg: WorkerMessage) {
+      if (msg.type === 'error') return this.#fail(msg.message);
+      if (msg.type === 'rows' && msg.jobId === this.#jobId) {
+        const rowFloats = this.#width * 3;
+        for (let i = 0; i < msg.rows; i++) {
+          const row = msg.row0 + i;
+          const offset = row * rowFloats;
+          for (let j = 0; j < rowFloats; j++) this.#accum[offset + j] += msg.pixels[i * rowFloats + j];
+          this.#rowPasses[row]++;
+          this.#dirtyRows.add(row);
+        }
+        this.#done++;
+        this.#scheduleDraw();
+        if (this.#done === this.#total) {
+          const secs = ((performance.now() - this.#startedAt) / 1000).toFixed(1);
+          this.#announce(`Render complete: ${PASSES * SPP_PER_PASS} samples per pixel in ${secs} seconds.`);
+        }
+      }
+      // 'ready', a finished task, or a stale task from a cancelled render.
+      this.#dispatch(worker);
+    }
+
+    #scheduleDraw() {
+      if (this.#frame) return;
+      this.#frame = requestAnimationFrame(() => {
+        this.#frame = 0;
+        const data = this.#image.data;
+        const w = this.#width;
+        for (const row of this.#dirtyRows) {
+          const inv = 1 / this.#rowPasses[row];
+          for (let x = 0; x < w; x++) {
+            const a = (row * w + x) * 3;
+            const p = (row * w + x) * 4;
+            data[p] = toByte(this.#accum[a] * inv);
+            data[p + 1] = toByte(this.#accum[a + 1] * inv);
+            data[p + 2] = toByte(this.#accum[a + 2] * inv);
+            data[p + 3] = 255;
+          }
+        }
+        this.#dirtyRows.clear();
+        this.#ctx.putImageData(this.#image, 0, 0);
+        this.#updateProgress();
+      });
+    }
+
+    #updateProgress() {
+      const progress = this.querySelector('progress')!;
+      progress.value = this.#total ? this.#done / this.#total : 0;
+      const tasksPerPass = Math.ceil(this.#height / ROWS_PER_TASK);
+      const spp = Math.floor(this.#done / tasksPerPass) * SPP_PER_PASS;
+      const secs = ((performance.now() - this.#startedAt) / 1000).toFixed(1);
+      const state = this.#done === this.#total ? 'Done' : 'Rendering';
+      this.querySelector('[data-progress-text]')!.textContent =
+        `${state}: ${spp} / ${PASSES * SPP_PER_PASS} samples per pixel · ${secs}s · ${this.#workers.length} worker${this.#workers.length === 1 ? '' : 's'}`;
+    }
+
+    #showSwatches(colors: Record<number, RGB>) {
+      const list = this.querySelector('[data-swatches]')!;
+      list.replaceChildren(
+        ...SPHERES.map(({ index, name }) => {
+          const li = document.createElement('li');
+          li.className = 'flex items-center gap-2';
+          const swatch = document.createElement('span');
+          swatch.className = 'inline-block size-4 rounded-full border border-gray-300';
+          swatch.style.background = toCss(colors[index]);
+          li.append(swatch, name);
+          return li;
+        }),
+      );
+    }
+
+    #announce(message: string) {
+      this.querySelector('[data-status]')!.textContent = message;
+    }
+
+    #fail(message: string) {
+      this.querySelector('[data-progress-text]')!.textContent = `Could not run the path tracer: ${message}`;
+      this.#announce(`Could not run the path tracer: ${message}`);
+    }
+  }
+
+  if (!customElements.get('smallpt-render')) customElements.define('smallpt-render', SmallptRender);
+</script>
