+export type RGB = [number, number, number];
+
+/** A block of rows to render for one progressive pass. */
+export interface RenderTask {
+  jobId: number;
+  row0: number;
+  rows: number;
+  width: number;
+  height: number;
+  spp: number;
+  seed: number;
+  /** Sphere index -> linear RGB color (0..1). */
+  colors: Record<number, RGB>;
+}
+
+export type WorkerMessage =
+  | { type: 'ready' }
+  | { type: 'error'; message: string }
+  | {
+      type: 'rows';
+      jobId: number;
+      row0: number;
+      rows: number;
+      /** rows * width * 3 linear RGB floats, already clamped to 0..1. */
+      pixels: Float32Array;
+    };
