@@ -0,0 +1,37 @@
+/// <reference lib="webworker" />
+import createSmallptModule from './generated/smallpt.js';
+import type { RenderTask, WorkerMessage } from './protocol';
+
+declare const self: DedicatedWorkerGlobalScope;
+
+const post = (msg: WorkerMessage, transfer: Transferable[] = []) => self.postMessage(msg, transfer);
+
+const modulePromise = createSmallptModule();
+modulePromise.then(
+  () => post({ type: 'ready' }),
+  (err: unknown) => post({ type: 'error', message: String(err) }),
+);
+
+self.onmessage = async (event: MessageEvent<RenderTask>) => {
+  const task = event.data;
+  const wasm = await modulePromise;
+
+  for (const [index, [r, g, b]] of Object.entries(task.colors)) {
+    wasm._set_sphere_color(Number(index), r, g, b);
+  }
+
+  const rowFloats = task.width * 3;
+  const pixels = new Float32Array(rowFloats * task.rows);
+  const ptr = wasm._malloc(rowFloats * Float32Array.BYTES_PER_ELEMENT);
+  try {
+    for (let i = 0; i < task.rows; i++) {
+      wasm._render_row(ptr, task.row0 + i, task.width, task.height, task.spp, task.seed >>> 0);
+      // Read HEAPF32 fresh after each call: memory growth detaches old views.
+      pixels.set(wasm.HEAPF32.subarray(ptr >> 2, (ptr >> 2) + rowFloats), i * rowFloats);
+    }
+  } finally {
+    wasm._free(ptr);
+  }
+
+  post({ type: 'rows', jobId: task.jobId, row0: task.row0, rows: task.rows, pixels }, [pixels.buffer]);
+};
