@@ -0,0 +1,35 @@
+// Web Worker that runs the smallpt WebAssembly module off the main thread.
+importScripts('smallpt.js');
+
+const ready = createSmallpt();
+let currentJob = 0;
+
+self.onmessage = async (e) => {
+  const { job, width, height, spp, colors, seed } = e.data;
+  currentJob = job;
+  const M = await ready;
+  if (job !== currentJob) return; // superseded while the module was loading
+
+  M._reset_sphere_colors();
+  (colors || []).forEach((c, i) => c && M._set_sphere_color(i, c[0], c[1], c[2]));
+
+  const ptr = M._init(width, height, spp, seed >>> 0);
+  const start = performance.now();
+  const BATCH = 4; // rows per progress message
+
+  for (let y = 0; y < height; y += BATCH) {
+    const yEnd = Math.min(height, y + BATCH);
+    for (let r = y; r < yEnd; r++) M._render_row(r);
+    // Rows are counted from the bottom of the image; send the rendered slice.
+    const top = height - yEnd;
+    const bytes = M.HEAPU8.slice(ptr + top * width * 4, ptr + (height - y) * width * 4);
+    self.postMessage(
+      { type: 'rows', job, top, rows: yEnd - y, pixels: bytes.buffer, progress: yEnd / height },
+      [bytes.buffer]
+    );
+    // Yield so a newer job (if posted) can preempt this one.
+    await new Promise((res) => setTimeout(res, 0));
+    if (job !== currentJob) return;
+  }
+  self.postMessage({ type: 'done', job, ms: performance.now() - start });
+};
