+++ b/src/components/SmallptRenderer.tsx
@@ -0,0 +1,176 @@
+import React, { useCallback, useEffect, useRef, useState } from 'react';
+
+const WIDTH = 320;
+const HEIGHT = 240;
+
+// Sphere indices in smallpt's scene (see wasm/smallpt.cpp).
+const LEFT_WALL = 0;
+const RIGHT_WALL = 1;
+const MIRROR = 6;
+const GLASS = 7;
+
+type RGB = [number, number, number];
+
+const rand = (min: number, max: number) => min + Math.random() * (max - min);
+
+// Random saturated color via HSV, scaled into [lo, hi] so energy stays sane.
+function randomColor(lo: number, hi: number): RGB {
+  const h = Math.random() * 6;
+  const s = rand(0.5, 1);
+  const v = hi;
+  const f = h - Math.floor(h);
+  const p = v * (1 - s), q = v * (1 - s * f), t = v * (1 - s * (1 - f));
+  const table: RGB[] = [[v, t, p], [q, v, p], [p, v, t], [p, q, v], [t, p, v], [v, p, q]];
+  return table[Math.floor(h) % 6].map((c) => Math.max(lo, c)) as RGB;
+}
+
+const toCss = (c: RGB) => `rgb(${c.map((x) => Math.round(x * 255)).join(',')})`;
+
+export default function SmallptRenderer({ baseUrl }: { baseUrl: string }) {
+  const canvasRef = useRef<HTMLCanvasElement>(null);
+  const workerRef = useRef<Worker | null>(null);
+  const jobRef = useRef(0);
+  const [spp, setSpp] = useState(32);
+  const [progress, setProgress] = useState(0);
+  const [status, setStatus] = useState('Loading WebAssembly…');
+  const [rendering, setRendering] = useState(false);
+  const [palette, setPalette] = useState<RGB[] | null>(null);
+
+  const render = useCallback((colors: (RGB | null)[] | null, samples: number) => {
+    const worker = workerRef.current;
+    if (!worker) return;
+    jobRef.current++;
+    setRendering(true);
+    setProgress(0);
+    setStatus(`Rendering ${WIDTH}×${HEIGHT} at ${samples} spp…`);
+    worker.postMessage({
+      job: jobRef.current,
+      width: WIDTH,
+      height: HEIGHT,
+      spp: samples,
+      colors,
+      seed: Math.floor(Math.random() * 65536),
+    });
+  }, []);
+
+  useEffect(() => {
+    const worker = new Worker(`${baseUrl}smallpt/worker.js`);
+    workerRef.current = worker;
+    const ctx = canvasRef.current!.getContext('2d')!;
+    ctx.fillStyle = '#000';
+    ctx.fillRect(0, 0, WIDTH, HEIGHT);
+
+    worker.onmessage = (e) => {
+      const msg = e.data;
+      // Ignore output from superseded renders.
+      if (msg.job !== jobRef.current) return;
+      if (msg.type === 'rows') {
+        const data = new Uint8ClampedArray(msg.pixels);
+        ctx.putImageData(new ImageData(data, WIDTH, msg.rows), 0, msg.top);
+        setProgress(msg.progress);
+      } else if (msg.type === 'done') {
+        setRendering(false);
+        setStatus(`Rendered in ${(msg.ms / 1000).toFixed(2)} s (WebAssembly, in a Web Worker)`);
+      }
+    };
+    worker.onerror = (err) => {
+      setRendering(false);
+      setStatus(`Failed to run path tracer: ${err.message || 'unknown error'}`);
+    };
+
+    render(null, spp); // initial render with smallpt's default Cornell box colors
+    return () => {
+      worker.terminate();
+      workerRef.current = null;
+    };
+    // eslint-disable-next-line react-hooks/exhaustive-deps
+  }, [baseUrl, render]);
+
+  const randomize = () => {
+    const left = randomColor(0.05, 0.85);
+    const right = randomColor(0.05, 0.85);
+    const mirror = randomColor(0.35, 0.999);
+    const glass = randomColor(0.35, 0.999);
+    const colors: (RGB | null)[] = [];
+    colors[LEFT_WALL] = left;
+    colors[RIGHT_WALL] = right;
+    colors[MIRROR] = mirror;
+    colors[GLASS] = glass;
+    setPalette([left, right, mirror, glass]);
+    render(colors, spp);
+  };
+
+  const resetColors = () => {
+    setPalette(null);
+    render(null, spp);
+  };
+
+  return (
+    <div className="flex flex-col md:flex-row gap-6 items-start">
+      <div className="w-full md:w-auto">
+        <canvas
+          ref={canvasRef}
+          width={WIDTH}
+          height={HEIGHT}
+          className="w-full md:w-[480px] bg-black border border-gray-300"
+          style={{ imageRendering: 'pixelated', aspectRatio: `${WIDTH} / ${HEIGHT}` }}
+          aria-label="Path traced Cornell box rendered by smallpt"
+        />
+        <div className="h-1 bg-gray-200 mt-1" aria-hidden="true">
+          <div className="h-1 bg-amber-400 transition-[width]" style={{ width: `${progress * 100}%` }} />
+        </div>
+      </div>
+      <div className="flex-1 text-left space-y-3">
+        <p className="text-sm text-gray-700">
+          This image is computed live in your browser by{' '}
+          <a className="underline hover:text-amber-500" href="http://www.kevinbeason.com/smallpt/" target="_blank" rel="noopener noreferrer">
+            smallpt
+          </a>
+          , Kevin Beason's 99-line C++ global illumination path tracer, compiled to WebAssembly with Emscripten.
+        </p>
+        <div className="flex flex-wrap items-center gap-2">
+          <button
+            type="button"
+            onClick={randomize}
+            className="px-4 py-2 bg-gray-900 text-white text-sm font-bold hover:bg-amber-400 hover:text-gray-900 transition-colors"
+          >
+            Randomize sphere colors &amp; render
+          </button>
+          <button
+            type="button"
+            onClick={resetColors}
+            className="px-3 py-2 border border-gray-400 text-sm hover:bg-gray-100"
+          >
+            Default colors
+          </button>
+          <label className="text-sm text-gray-700 flex items-center gap-1">
+            Samples/pixel
+            <select
+              value={spp}
+              onChange={(e) => setSpp(Number(e.target.value))}
+              className="border border-gray-400 px-1 py-1 text-sm"
+            >
+              {[8, 16, 32, 64, 128, 256].map((n) => (
+                <option key={n} value={n}>{n}</option>
+              ))}
+            </select>
+          </label>
+        </div>
+        {palette && (
+          <div className="flex gap-3 text-xs text-gray-600" aria-label="Current sphere colors">
+            {['Left wall', 'Right wall', 'Mirror', 'Glass'].map((name, i) => (
+              <span key={name} className="flex items-center gap-1">
+                <span className="inline-block w-3 h-3 border border-gray-400" style={{ background: toCss(palette[i]) }} />
+                {name}
+              </span>
+            ))}
+          </div>
+        )}
+        <p className="text-xs text-gray-500" role="status">
+          {status}
+          {rendering && ` ${Math.round(progress * 100)}%`}
+        </p>
+      </div>
+    </div>
+  );
+}
