+#!/bin/sh
+# Builds wasm/smallpt.cpp -> public/smallpt/smallpt.{js,wasm} with Emscripten.
+set -e
+cd "$(dirname "$0")"
+em++ -O3 smallpt.cpp -o ../public/smallpt/smallpt.js \
+  -sENVIRONMENT=worker -sMODULARIZE=1 -sEXPORT_NAME=createSmallpt \
+  -sALLOW_MEMORY_GROWTH=1 -sFILESYSTEM=0 \
+  -sEXPORTED_FUNCTIONS=_init,_render_row,_set_sphere_color,_reset_sphere_colors,_sphere_count \
+  -sEXPORTED_RUNTIME_METHODS=HEAPU8
