+// ---------------------------------------------------------------------------
+// WebAssembly entry points (replace the original main()). The renderer above is
+// unchanged except that sphere colors can be overridden from JavaScript and the
+// image is produced row-by-row into an RGBA buffer instead of a PPM file.
+// ---------------------------------------------------------------------------
+static int W=256, H=192, SAMPS=4;
+static Vec *accum = 0;              // linear radiance per pixel
+static unsigned char *rgba = 0;     // tone-mapped 8-bit RGBA output
+static unsigned short seed = 0;     // varies noise pattern between runs
+static const Vec defaultColors[] = {
+  Vec(.75,.25,.25), Vec(.25,.25,.75), Vec(.75,.75,.75), Vec(),
+  Vec(.75,.75,.75), Vec(.75,.75,.75), Vec(1,1,1)*.999, Vec(1,1,1)*.999, Vec() };
+static Ray cam(Vec(50,52,295.6), Vec(0,-0.042612,-1).norm()); // cam pos, dir
+static Vec cx, cy;
+
+extern "C" {
+EMSCRIPTEN_KEEPALIVE int sphere_count(){ return int(sizeof(spheres)/sizeof(Sphere)); }
+
+EMSCRIPTEN_KEEPALIVE void set_sphere_color(int i, double r, double g, double b){
+  if (i>=0 && i<sphere_count()) spheres[i].c = Vec(r,g,b);
+}
+EMSCRIPTEN_KEEPALIVE void reset_sphere_colors(){
+  for (int i=0;i<sphere_count();i++) spheres[i].c = defaultColors[i];
+}
+// Allocate buffers and set up the camera. spp is total samples per pixel
+// (rounded down to a multiple of 4, like the original's argv[1]).
+EMSCRIPTEN_KEEPALIVE unsigned char* init(int w, int h, int spp, int s){
+  W=w; H=h; SAMPS = spp/4 > 0 ? spp/4 : 1; seed=(unsigned short)s;
+  delete[] accum; delete[] rgba;
+  accum = new Vec[W*H]; rgba = new unsigned char[W*H*4];
+  for (int i=0;i<W*H*4;i++) rgba[i] = (i%4==3) ? 255 : 0;
+  cx=Vec(W*.5135/H); cy=(cx%cam.d).norm()*.5135;
+  return rgba;
+}
+// Render one image row (y counts from the bottom, as in the original loop).
+EMSCRIPTEN_KEEPALIVE void render_row(int y){
+  int w=W, h=H, samps=SAMPS; Vec r, *c=accum;
+  for (unsigned short x=0, Xi[3]={seed,0,(unsigned short)(y*y*y)}; x<w; x++)
+    for (int sy=0, i=(h-y-1)*w+x; sy<2; sy++)
+      for (int sx=0; sx<2; sx++, r=Vec()){
+        for (int s=0; s<samps; s++){
+          double r1=2*erand48(Xi), dx=r1<1 ? sqrt(r1)-1: 1-sqrt(2-r1);
+          double r2=2*erand48(Xi), dy=r2<1 ? sqrt(r2)-1: 1-sqrt(2-r2);
+          Vec d = cx*( ( (sx+.5 + dx)/2 + x)/w - .5) +
+                  cy*( ( (sy+.5 + dy)/2 + y)/h - .5) + cam.d;
+          r = r + radiance(Ray(cam.o+d*140,d.norm()),0,Xi)*(1./samps);
+        }
+        c[i] = c[i] + Vec(clamp(r.x),clamp(r.y),clamp(r.z))*.25;
+      }
+  for (int x=0, i=(h-y-1)*w; x<w; x++, i++){
+    rgba[i*4+0]=toInt(c[i].x); rgba[i*4+1]=toInt(c[i].y);
+    rgba[i*4+2]=toInt(c[i].z); rgba[i*4+3]=255;
+  }
+}
+}

