+    // Background analytics: low priority so it doesn't compete with the critical request.
+    fetch('/api/analytics', {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json' },
+      body: JSON.stringify({ click: 1 }),
+      priority: 'low',
+      keepalive: true
+    }).catch(() => {});
