+  <!--
+    Background-load detection.
+    Kept inline and synchronous in <head> so it runs as early as possible.
+    Preferred: the Performance Timeline "visibility-state" entries, which record
+    the page's visibility from navigation start regardless of when this code runs.
+    Fallback: document.visibilityState / document.hidden, which only reflect the
+    state *at the moment the script executes* — so they can miss (or misreport)
+    a background open when this logic is loaded async/deferred.
+  -->
+  <script>
+    (function () {
+      var FALLBACK_NOTE =
+        'VisibilityStateEntry API unavailable; fell back to document.visibilityState, ' +
+        'which only reflects visibility when this script executed. This check is ' +
+        'unreliable for async/deferred scripts, since the tab may have changed ' +
+        'visibility before the script ran.';
+
+      function detectBackgroundLoad() {
+        var result = { backgrounded: false, timestamp: Date.now() };
+
+        var supportsVisibilityEntries =
+          typeof PerformanceObserver !== 'undefined' &&
+          Array.isArray(PerformanceObserver.supportedEntryTypes) &&
+          PerformanceObserver.supportedEntryTypes.indexOf('visibility-state') !== -1 &&
+          typeof performance !== 'undefined' &&
+          typeof performance.getEntriesByType === 'function';
+
+        if (supportsVisibilityEntries) {
+          var entries = performance.getEntriesByType('visibility-state');
+          // The first entry (startTime 0) records the initial visibility at navigation start.
+          var initial = entries.length ? entries[0] : null;
+          result.backgrounded = !!initial && initial.name === 'hidden';
+          return result;
+        }
+
+        // Older fallback check.
+        result.backgrounded =
+          document.visibilityState === 'hidden' || document.hidden === true;
+        result.note = FALLBACK_NOTE;
+        return result;
+      }
+
