+          return;
+        }
+        if (isDirty()) {
+          showConfirm();
+        } else {
+          closeDialog();
+        }
+      }
+
+      function showToast(message) {
+        toast.textContent = message;
+        toast.hidden = false;
+        clearTimeout(toastTimer);
+        toastTimer = setTimeout(function () { toast.hidden = true; }, 3500);
+      }
+
+      document.querySelectorAll('[data-order-open]').forEach(function (btn) {
+        btn.addEventListener('click', function () {
+          openDialog(btn.getAttribute('data-order-open'), btn);
+        });
+      });
+
+      form.querySelectorAll('[data-dialog-dismiss]').forEach(function (btn) {
+        btn.addEventListener('click', requestDismiss);
+      });
+
+      discardBtn.addEventListener('click', closeDialog);
+
+      keepEditingBtn.addEventListener('click', function () {
+        hideConfirm();
+        var firstField = drinkField.hidden ? form.querySelector('input[name="size"]:checked') : drinkSelect;
+        if (firstField) firstField.focus();
+      });
+
+      // Escape key / platform back gesture.
+      dialog.addEventListener('cancel', function (e) {
+        e.preventDefault();
+        requestDismiss();
+      });
+
+      // Backdrop click: the event target is the <dialog> itself when clicking outside its content box.
+      dialog.addEventListener('mousedown', function (e) {
+        dialog._pressedOnBackdrop = e.target === dialog;
+      });
+      dialog.addEventListener('click', function (e) {
+        if (e.target !== dialog || !dialog._pressedOnBackdrop) return;
+        var r = dialog.getBoundingClientRect();
+        var inside = e.clientX >= r.left && e.clientX <= r.right && e.clientY >= r.top && e.clientY <= r.bottom;
+        if (!inside) requestDismiss();
+      });
+
+      // Safety net: some browsers may force-close a modal (e.g. repeated Esc presses
+      // without user activation). If that happens with unsaved changes, reopen it
+      // and ask for explicit confirmation instead of silently losing the edits.
+      dialog.addEventListener('close', function () {
+        if (!allowClose && isDirty()) {
+          dialog.showModal();
+          showConfirm();
+          return;
+        }
+        document.body.classList.remove('dialog-open');
+        initialState = null;
+        allowClose = false;
+        hideConfirm();
+        if (lastTrigger && document.contains(lastTrigger)) lastTrigger.focus();
+      });
+
+      form.addEventListener('input', function (e) {
+        if (e.target === drinkSelect) {
+          applyDefaults(drinkSelect.value);
+          showDrinkInfo(drinkSelect.value);
+        }
+        updateTotal();
+      });
+      form.addEventListener('change', updateTotal);
+
+      form.addEventListener('submit', function (e) {
+        e.preventDefault();
+        var qtyInput = form.elements.quantity;
+        var q = parseInt(qtyInput.value, 10);
+        if (isNaN(q) || q < 1 || q > 10) {
+          qtyInput.setCustomValidity('Please choose a quantity between 1 and 10.');
+          qtyInput.reportValidity();
+          qtyInput.setCustomValidity('');
+          return;
+        }
+        var drinkName = DRINKS[drinkSelect.value].name;
+        var total = totalEl.textContent;
+        closeDialog();
+        showToast('Added ' + q + ' × ' + drinkName + ' to your order (' + total + ').');
+      });
+    })();
+  </script>
+
 </body>

