+import {
+  SUITES,
+  SUITE_PREFERENCE,
+  detectSupportedSuites,
+  loadKeyring,
+  createSigningKey,
+  exportPublicKey,
+  importTrustedKey,
+  issueDocument,
+  verifyDocument,
+  redeemVoucher,
+  tamperWithDocument,
+  isPersistent,
+} from './signing.js';
+
+const MENU = [
+  { sku: 'maple-oat-latte', name: 'Maple Oat Latte', unitCents: 525 },
+  { sku: 'dark-roast-espresso', name: 'Dark Roast Espresso', unitCents: 350 },
+  { sku: 'cold-brew', name: 'Cold Brew', unitCents: 475 },
+];
+
+const money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' });
+const $ = (sel) => document.querySelector(sel);
+
+const els = {
+  keyStatus: $('#key-status'),
+  keyInfo: $('#key-info'),
+  suiteSelect: $('#suite-select'),
+  rotateBtn: $('#rotate-key'),
+  keyringList: $('#keyring'),
+  copyPubBtn: $('#copy-public-key'),
+  importForm: $('#import-key-form'),
+  importStatus: $('#import-key-status'),
+  issueForm: $('#issue-form'),
+  receiptFields: $('#receipt-fields'),
+  voucherFields: $('#voucher-fields'),
+  receiptTotal: $('#receipt-total'),
+  issuedToken: $('#issued-token'),
+  issuedActions: $('#issued-actions'),
+  issueStatus: $('#issue-status'),
+  verifyForm: $('#verify-form'),
+  verifyInput: $('#verify-input'),
+  verifyFile: $('#verify-file'),
+  verifyResult: $('#verify-result'),
+  tamperBtn: $('#tamper'),
+};
+
+let keyring = [];
+let supportedSuites = [];
+const activeKey = () => keyring.find((k) => k.status === 'active');
+
+/* ------------------------------------------------------------ key management */
+
+function el(tag, props = {}, ...children) {
+  const node = Object.assign(document.createElement(tag), props);
+  node.append(...children.filter((c) => c != null));
+  return node;
+}
+
+function dlRows(dl, rows) {
+  dl.replaceChildren(
+    ...rows.flatMap(([term, value]) => [el('dt', { textContent: term }), el('dd', {}, value)]),
+  );
+}
+
+function renderKeys() {
+  const key = activeKey();
+  if (key) {
+    const suite = SUITES[key.suite];
+    els.keyStatus.textContent = suite.postQuantum
+      ? 'Quantum-resistant signing key active'
+      : 'Classical signing key active';
+    els.keyStatus.dataset.state = suite.postQuantum ? 'pq' : 'classical';
+    dlRows(els.keyInfo, [
+      ['Algorithm', suite.label],
+      ['Key ID', el('code', { textContent: key.kid })],
+      ['Fingerprint', el('code', { textContent: key.fingerprint })],
+      ['Created', new Date(key.createdAt).toLocaleString()],
+      ['Storage', isPersistent() ? 'IndexedDB (private key non-extractable)' : 'Memory only (IndexedDB unavailable)'],
+    ]);
+  } else {
+    els.keyStatus.textContent = 'No signing key';
+    els.keyStatus.dataset.state = 'none';
+    els.keyInfo.replaceChildren();
+  }
+  els.copyPubBtn.disabled = !key;
+
+  els.keyringList.replaceChildren(
+    ...keyring.map((k) =>
+      el(
+        'li',
+        {},
+        el('span', { className: `badge badge-${k.status}`, textContent: k.status }),
+        ' ',
+        el('code', { textContent: k.kid }),
+        ` · ${k.suite}`,
+        k.label ? ` · ${k.label}` : null,
+      ),
+    ),
+  );
+}
+
+async function refreshKeys() {
+  keyring = await loadKeyring();
+  renderKeys();
+}
+
+function populateSuiteSelect() {
+  els.suiteSelect.replaceChildren(
+    ...SUITE_PREFERENCE.map((id) =>
+      el('option', {
+        value: id,
+        textContent: SUITES[id].label + (supportedSuites.includes(id) ? '' : ' (unsupported)'),
+        disabled: !supportedSuites.includes(id),
+      }),
+    ),
+  );
+  els.suiteSelect.value = supportedSuites[0] ?? '';
+}
+
+els.rotateBtn.addEventListener('click', async () => {
+  const suite = els.suiteSelect.value;
+  if (!suite) return;
+  if (
+    activeKey() &&
+    !confirm('Generate a new signing key? The current key will be retired: documents it signed stay valid, but it can no longer sign.')
+  ) {
+    return;
+  }
+  els.rotateBtn.disabled = true;
+  try {
+    await createSigningKey(suite);
+    await refreshKeys();
+  } catch (err) {
+    els.keyStatus.textContent = `Key generation failed: ${err.message}`;
+  } finally {
+    els.rotateBtn.disabled = false;
+  }
+});
+
+els.copyPubBtn.addEventListener('click', async () => {
+  const key = activeKey();
+  if (!key) return;
+  await navigator.clipboard.writeText(exportPublicKey(key));
+  flash(els.copyPubBtn, 'Copied!');
+});
+
+els.importForm.addEventListener('submit', async (e) => {
+  e.preventDefault();
+  const data = new FormData(els.importForm);
+  try {
+    const rec = await importTrustedKey(String(data.get('publicKey')), String(data.get('label') ?? ''));
+    els.importStatus.textContent = `Trusted key ${rec.kid} added.`;
+    els.importForm.reset();
+    await refreshKeys();
+  } catch (err) {
+    els.importStatus.textContent = err.message;
+  }
+});
+
+/* ------------------------------------------------------------------- issuing */
+
+function buildReceiptFields() {
+  const list = els.receiptFields.querySelector('.items');
+  list.replaceChildren(
+    ...MENU.map((item) =>
+      el(
+        'label',
+        { className: 'item-row' },
+        el('span', { textContent: `${item.name} — ${money.format(item.unitCents / 100)}` }),
+        el('input', {
+          type: 'number',
+          name: `qty-${item.sku}`,
+          min: 0,
+          max: 50,
+          value: 0,
+          inputMode: 'numeric',
+        }),
+      ),
+    ),
+  );
+}
+
+function receiptItems() {
+  const data = new FormData(els.issueForm);
+  return MENU.map((m) => ({ ...m, qty: Number(data.get(`qty-${m.sku}`)) || 0 })).filter(
+    (i) => i.qty > 0,
+  );
+}
+
+function updateReceiptTotal() {
+  const total = receiptItems().reduce((sum, i) => sum + i.qty * i.unitCents, 0);
+  els.receiptTotal.value = money.format(total / 100);
+}
+
+function selectedDocType() {
+  return new FormData(els.issueForm).get('docType');
+}
+
+function syncDocType() {
+  const isVoucher = selectedDocType() === 'voucher';
+  // `disabled` keeps the hidden fieldset's controls out of validation and FormData.
+  els.receiptFields.hidden = els.receiptFields.disabled = isVoucher;
+  els.voucherFields.hidden = els.voucherFields.disabled = !isVoucher;
+}
+
+function voucherCode() {
+  const alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
+  const bytes = crypto.getRandomValues(new Uint8Array(8));
+  const chars = [...bytes].map((b) => alphabet[b % alphabet.length]).join('');
+  return `DG-${chars.slice(0, 4)}-${chars.slice(4)}`;
+}
+
+els.issueForm.addEventListener('input', (e) => {
+  if (e.target.name === 'docType') syncDocType();
+  if (e.target.name?.startsWith('qty-')) {
+    els.receiptFields.querySelector('input').setCustomValidity('');
+    updateReceiptTotal();
+  }
+});
+
+els.issueForm.addEventListener('submit', async (e) => {
+  e.preventDefault();
+  const key = activeKey();
+  if (!key) {
+    els.issueStatus.textContent = 'Generate a signing key first.';
+    return;
+  }
+  const docType = selectedDocType();
+  const data = new FormData(els.issueForm);
+  const base = { id: crypto.randomUUID(), issuedAt: new Date().toISOString(), issuer: 'The Daily Grind Coffee Co.' };
+  let payload;
+
+  if (docType === 'receipt') {
+    const items = receiptItems();
+    if (!items.length) {
+      const first = els.receiptFields.querySelector('input');
+      first.setCustomValidity('Add at least one item to the order.');
+      first.reportValidity();
+      return;
+    }
+    payload = {
+      ...base,
+      currency: 'USD',
+      items: items.map(({ sku, name, qty, unitCents }) => ({ sku, name, qty, unitCents })),
+      totalCents: items.reduce((sum, i) => sum + i.qty * i.unitCents, 0),
+    };
+  } else {
+    const expires = new Date(`${data.get('expires')}T23:59:59`);
+    payload = {
+      ...base,
+      code: voucherCode(),
+      currency: 'USD',
+      valueCents: Math.round(Number(data.get('amount')) * 100),
+      recipient: String(data.get('recipient')).trim(),
+      message: String(data.get('message') ?? '').trim(),
+      expiresAt: expires.toISOString(),
+    };
+  }
+
+  try {
+    const token = await issueDocument(key, docType, payload);
+    els.issuedToken.value = token;
+    els.issuedActions.hidden = false;
+    els.issueStatus.textContent = `${docType === 'receipt' ? 'Receipt' : 'Gift voucher'} signed with ${key.suite} (${token.length.toLocaleString()} characters).`;
+  } catch (err) {
+    els.issueStatus.textContent = `Signing failed: ${err.message}`;
+  }
+});
+
+els.issuedActions.addEventListener('click', async (e) => {
+  const action = e.target.closest('button')?.dataset.action;
+  const token = els.issuedToken.value;
+  if (!action || !token) return;
+  if (action === 'copy') {
+    await navigator.clipboard.writeText(token);
+    flash(e.target, 'Copied!');
+  } else if (action === 'download') {
+    const url = URL.createObjectURL(new Blob([token], { type: 'text/plain' }));
+    const a = el('a', { href: url, download: `daily-grind-${selectedDocType()}.dgsig` });
+    a.click();
+    setTimeout(() => URL.revokeObjectURL(url), 0);
+  } else if (action === 'verify') {
+    els.verifyInput.value = token;
+    els.verifyForm.requestSubmit();
+    els.verifyForm.scrollIntoView({ behavior: 'smooth', block: 'start' });
+  }
+});
+
+/* ---------------------------------------------------------------- verifying */
+
+function renderDocument(payload, header) {
+  const rows = [
+    ['Type', header.typ === 'receipt' ? 'Order receipt' : 'Gift voucher'],
+    ['Document ID', el('code', { textContent: payload.id })],
+    ['Issued', new Date(payload.issuedAt).toLocaleString()],
+  ];
+  if (header.typ === 'receipt') {
+    const list = el(
+      'ul',
+      { className: 'receipt-items' },
+      ...(payload.items ?? []).map((i) =>
+        el('li', { textContent: `${i.qty} × ${i.name} — ${money.format((i.qty * i.unitCents) / 100)}` }),
+      ),
+    );
+    rows.push(['Items', list], ['Total', el('strong', { textContent: money.format(payload.totalCents / 100) })]);
+  } else {
+    rows.push(
+      ['Code', el('code', { textContent: payload.code })],
+      ['Value', el('strong', { textContent: money.format(payload.valueCents / 100) })],
+      ['Recipient', payload.recipient],
+    );
+    if (payload.message) rows.push(['Message', payload.message]);
+    rows.push(['Expires', new Date(payload.expiresAt).toLocaleDateString()]);
+  }
+  const dl = el('dl', { className: 'doc-details' });
+  dlRows(dl, rows);
+  return dl;
+}
+
+async function runVerification() {
+  const token = els.verifyInput.value;
+  const result = await verifyDocument(token, keyring);
+  const state = !result.valid ? 'invalid' : result.warnings.length ? 'caution' : 'valid';
+  const box = el('div', { className: `verify-box verify-${state}` });
+  box.append(
+    el('p', { className: 'verify-headline' }, el('strong', {
+      textContent: result.valid ? '✔ Verified' : '✘ Verification failed',
+    }), ` — ${result.reason}`),
+  );
+  if (result.valid) {
+    box.append(
+      el('p', {
+        className: 'verify-meta',
+        textContent: `Signed with ${SUITES[result.key.suite].label}, key ${result.key.kid}.`,
+      }),
+    );
+    for (const w of result.warnings) box.append(el('p', { className: 'verify-warning', textContent: `⚠ ${w}` }));
+    box.append(renderDocument(result.payload, result.header));
+
+    const redeemable =
+      result.header.typ === 'voucher' && !result.warnings.some((w) => /expired|redeemed/i.test(w));
+    if (redeemable) {
+      const btn = el('button', { type: 'button', className: 'btn', textContent: 'Redeem voucher' });
+      btn.addEventListener('click', async () => {
+        try {
+          await redeemVoucher(result.payload);
+          await runVerification();
+        } catch (err) {
+          btn.replaceWith(el('p', { textContent: err.message }));
+        }
+      });
+      box.append(btn);
+    }
+  }
+  els.verifyResult.replaceChildren(box);
+}
+
+els.verifyForm.addEventListener('submit', async (e) => {
+  e.preventDefault();
+  await runVerification();
+});
+
+els.verifyFile.addEventListener('change', async () => {
+  const file = els.verifyFile.files?.[0];
+  if (!file) return;
+  if (file.size > 64 * 1024) {
+    els.verifyResult.textContent = 'File is too large to be a Daily Grind signed document.';
+    return;
+  }
+  els.verifyInput.value = (await file.text()).trim();
+  els.verifyForm.requestSubmit();
+});
+
+els.tamperBtn.addEventListener('click', async () => {
+  const token = els.verifyInput.value || els.issuedToken.value;
+  if (!token) {
+    els.verifyResult.textContent = 'Issue or paste a signed document first.';
+    return;
+  }
+  try {
+    els.verifyInput.value = tamperWithDocument(token);
+  } catch {
+    els.verifyResult.textContent = 'Could not decode that document to tamper with it.';
+    return;
+  }
+  await runVerification();
+});
+
+/* --------------------------------------------------------------------- misc */
+
+function flash(button, text) {
+  const original = button.textContent;
+  button.textContent = text;
+  setTimeout(() => (button.textContent = original), 1500);
+}
+
+async function init() {
+  buildReceiptFields();
+  syncDocType();
+  updateReceiptTotal();
+
+  const expires = els.issueForm.elements.namedItem('expires');
+  const today = new Date();
+  const inAYear = new Date(today.getFullYear() + 1, today.getMonth(), today.getDate());
+  const isoDate = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
+  expires.min = isoDate(today);
+  expires.value = isoDate(inAYear);
+
+  if (!globalThis.crypto?.subtle) {
+    els.keyStatus.textContent = 'Signing requires a secure (HTTPS) context.';
+    els.keyStatus.dataset.state = 'none';
+    els.issueForm.querySelector('button[type="submit"]').disabled = true;
+    els.rotateBtn.disabled = true;
+    return;
+  }
+
+  supportedSuites = await detectSupportedSuites();
+  populateSuiteSelect();
+  await refreshKeys();
+
+  if (!activeKey() && supportedSuites.length) {
+    await createSigningKey(supportedSuites[0]);
+    await refreshKeys();
+  }
+}
+
+init().catch((err) => {
+  els.keyStatus.textContent = `Signing unavailable: ${err.message}`;
+  els.keyStatus.dataset.state = 'none';
+});
