index 0000000..52084ff
--- /dev/null
+++ b/js/signing.js
@@ -0,0 +1,378 @@
+// Digital signing & verification for Daily Grind receipts and gift vouchers.
+//
+// - Prefers post-quantum ML-DSA-65 (FIPS 204); falls back to Ed25519, then ECDSA P-256.
+// - Private keys are generated non-extractable and persisted as CryptoKey objects in
+//   IndexedDB (structured clone), so raw private key material never touches JS.
+// - Signed documents use a compact format:  DG1.<header>.<payload>.<signature>
+//   (each part base64url). The signature covers "DG1.<header>.<payload>", so the
+//   algorithm, key id and document type are all integrity-protected.
+// - Each document type is bound to a domain-separation context so a receipt signature
+//   can never be replayed as a voucher (native ML-DSA context, length-prefixed framing
+//   for classical algorithms).
+
+const enc = new TextEncoder();
+const dec = new TextDecoder();
+
+export const TOKEN_PREFIX = 'DG1';
+export const KEY_PREFIX = 'DGK1';
+export const DOC_TYPES = ['receipt', 'voucher'];
+
+export const SUITES = {
+  'ML-DSA-65': {
+    label: 'ML-DSA-65 — post-quantum (FIPS 204)',
+    postQuantum: true,
+    keyAlg: 'ML-DSA-65',
+    pubFormat: 'raw-public',
+  },
+  Ed25519: {
+    label: 'Ed25519 — classical',
+    postQuantum: false,
+    keyAlg: 'Ed25519',
+    signAlg: 'Ed25519',
+    pubFormat: 'raw',
+  },
+  'ECDSA-P256': {
+    label: 'ECDSA P-256 / SHA-256 — classical',
+    postQuantum: false,
+    keyAlg: { name: 'ECDSA', namedCurve: 'P-256' },
+    signAlg: { name: 'ECDSA', hash: 'SHA-256' },
+    pubFormat: 'raw',
+  },
+};
+
+export const SUITE_PREFERENCE = ['ML-DSA-65', 'Ed25519', 'ECDSA-P256'];
+
+/* ---------------------------------------------------------------- encoding */
+
+export function toBase64Url(bytes) {
+  if (typeof Uint8Array.prototype.toBase64 === 'function') {
+    return bytes.toBase64({ alphabet: 'base64url', omitPadding: true });
+  }
+  let bin = '';
+  for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
+  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+}
+
+export function fromBase64Url(str) {
+  if (!/^[A-Za-z0-9_-]*$/.test(str)) throw new SyntaxError('Invalid base64url');
+  if (typeof Uint8Array.fromBase64 === 'function') {
+    return Uint8Array.fromBase64(str, { alphabet: 'base64url' });
+  }
+  const b64 = str.replace(/-/g, '+').replace(/_/g, '/');
+  const bin = atob(b64 + '='.repeat((4 - (b64.length % 4)) % 4));
+  return Uint8Array.from(bin, (c) => c.charCodeAt(0));
+}
+
+const encodeJson = (obj) => toBase64Url(enc.encode(JSON.stringify(obj)));
+const decodeJson = (str) => JSON.parse(dec.decode(fromBase64Url(str)));
+
+/* -------------------------------------------------------- algorithm support */
+
+export async function detectSupportedSuites() {
+  const supports = globalThis.SubtleCrypto?.supports;
+  const supported = [];
+  for (const id of SUITE_PREFERENCE) {
+    const suite = SUITES[id];
+    if (typeof supports === 'function') {
+      const signAlg = suite.postQuantum
+        ? { name: suite.keyAlg, context: new Uint8Array(1) }
+        : suite.signAlg;
+      if (
+        SubtleCrypto.supports('generateKey', suite.keyAlg) &&
+        SubtleCrypto.supports('sign', signAlg)
+      ) {
+        supported.push(id);
+      }
+      continue;
+    }
+    // Browsers without SubtleCrypto.supports() predate ML-DSA; probe classical suites.
+    if (suite.postQuantum) continue;
+    try {
+      await crypto.subtle.generateKey(suite.keyAlg, false, ['sign', 'verify']);
+      supported.push(id);
+    } catch {
+      /* not supported */
+    }
+  }
+  return supported;
+}
+
+/* ------------------------------------------------------------ sign / verify */
+
+export function contextFor(docType) {
+  return enc.encode(`daily-grind/${docType}/v1`);
+}
+
+// Classical algorithms ignore `context`, so emulate it with a length-prefixed header.
+function frame(data, context) {
+  if (context.byteLength > 255) {
+    throw new DOMException('Context must not exceed 255 bytes', 'OperationError');
+  }
+  const out = new Uint8Array(1 + context.byteLength + data.byteLength);
+  out[0] = context.byteLength;
+  out.set(context, 1);
+  out.set(data, 1 + context.byteLength);
+  return out;
+}
+
+async function signBytes(suiteId, privateKey, data, context) {
+  const suite = SUITES[suiteId];
+  const sig = suite.postQuantum
+    ? await crypto.subtle.sign({ name: suite.keyAlg, context }, privateKey, data)
+    : await crypto.subtle.sign(suite.signAlg, privateKey, frame(data, context));
+  return new Uint8Array(sig);
+}
+
+async function verifyBytes(suiteId, publicKey, signature, data, context) {
+  const suite = SUITES[suiteId];
+  return suite.postQuantum
+    ? crypto.subtle.verify({ name: suite.keyAlg, context }, publicKey, signature, data)
+    : crypto.subtle.verify(suite.signAlg, publicKey, signature, frame(data, context));
+}
+
+/* ----------------------------------------------------------------- storage */
+
+const DB_NAME = 'daily-grind-signing';
+const DB_VERSION = 1;
+let dbPromise;
+const memory = { keys: new Map(), redemptions: new Map() };
+let usingMemory = false;
+
+function openDb() {
+  dbPromise ??= new Promise((resolve) => {
+    let req;
+    try {
+      req = indexedDB.open(DB_NAME, DB_VERSION);
+    } catch {
+      usingMemory = true;
+      resolve(null);
+      return;
+    }
+    req.onupgradeneeded = () => {
+      const db = req.result;
+      db.createObjectStore('keys', { keyPath: 'kid' });
+      db.createObjectStore('redemptions', { keyPath: 'id' });
+    };
+    req.onsuccess = () => resolve(req.result);
+    req.onerror = () => {
+      usingMemory = true;
+      resolve(null);
+    };
+  });
+  return dbPromise;
+}
+
+export const isPersistent = () => !usingMemory;
+
+async function withStore(store, mode, idbOp, memOp) {
+  const db = await openDb();
+  if (!db) return memOp(memory[store]);
+  return new Promise((resolve, reject) => {
+    const t = db.transaction(store, mode);
+    const req = idbOp(t.objectStore(store));
+    t.oncomplete = () => resolve(req.result);
+    t.onerror = () => reject(t.error);
+    t.onabort = () => reject(t.error);
+  });
+}
+
+const dbGetAll = (store) =>
+  withStore(store, 'readonly', (s) => s.getAll(), (m) => [...m.values()]);
+const dbGet = (store, key) =>
+  withStore(store, 'readonly', (s) => s.get(key), (m) => m.get(key));
+const dbPut = (store, value, keyPath) =>
+  withStore(store, 'readwrite', (s) => s.put(value), (m) => m.set(value[keyPath], value));
+
+/* ----------------------------------------------------------------- keyring */
+
+async function keyId(suiteId, publicKeyBytes) {
+  const input = new Uint8Array([...enc.encode(suiteId), 0, ...publicKeyBytes]);
+  const digest = new Uint8Array(await crypto.subtle.digest('SHA-256', input));
+  return {
+    kid: toBase64Url(digest.slice(0, 12)),
+    fingerprint: [...digest.slice(0, 16)]
+      .map((b) => b.toString(16).padStart(2, '0'))
+      .join('')
+      .match(/.{4}/g)
+      .join(':'),
+  };
+}
+
+export async function loadKeyring() {
+  const keys = await dbGetAll('keys');
+  return keys.sort((a, b) => b.createdAt.localeCompare(a.createdAt));
+}
+
+export async function createSigningKey(suiteId) {
+  const suite = SUITES[suiteId];
+  if (!suite) throw new Error(`Unknown suite ${suiteId}`);
+  const keyPair = await crypto.subtle.generateKey(suite.keyAlg, false, ['sign', 'verify']);
+  const publicKeyBytes = new Uint8Array(
+    await crypto.subtle.exportKey(suite.pubFormat, keyPair.publicKey),
+  );
+  const { kid, fingerprint } = await keyId(suiteId, publicKeyBytes);
+
+  // Retire the previous signing key: keep its public key so older documents still
+  // verify, but discard its private key so it can never sign again.
+  for (const old of await loadKeyring()) {
+    if (old.status === 'active') {
+      await dbPut('keys', { ...old, status: 'retired', privateKey: null }, 'kid');
+    }
+  }
+
+  const record = {
+    kid,
+    fingerprint,
+    suite: suiteId,
+    status: 'active',
+    createdAt: new Date().toISOString(),
+    publicKey: keyPair.publicKey,
+    privateKey: keyPair.privateKey,
+    publicKeyBytes,
+  };
+  await dbPut('keys', record, 'kid');
+  return record;
+}
+
+export function exportPublicKey(record) {
+  return `${KEY_PREFIX}.${record.suite}.${toBase64Url(record.publicKeyBytes)}`;
+}
+
+export async function importTrustedKey(text, label = '') {
+  const [prefix, suiteId, b64, ...rest] = text.trim().split('.');
+  if (prefix !== KEY_PREFIX || !SUITES[suiteId] || !b64 || rest.length) {
+    throw new Error('Not a Daily Grind public key (expected DGK1.<algorithm>.<key>).');
+  }
+  const suite = SUITES[suiteId];
+  const publicKeyBytes = fromBase64Url(b64);
+  const publicKey = await crypto.subtle.importKey(
+    suite.pubFormat,
+    publicKeyBytes,
+    suite.keyAlg,
+    true,
+    ['verify'],
+  );
+  const { kid, fingerprint } = await keyId(suiteId, publicKeyBytes);
+  const existing = await dbGet('keys', kid);
+  if (existing) return existing;
+  const record = {
+    kid,
+    fingerprint,
+    suite: suiteId,
+    status: 'trusted',
+    label: label.slice(0, 60),
+    createdAt: new Date().toISOString(),
+    publicKey,
+    privateKey: null,
+    publicKeyBytes,
+  };
+  await dbPut('keys', record, 'kid');
+  return record;
+}
+
+/* --------------------------------------------------------------- documents */
+
+export async function issueDocument(signingKey, docType, payload) {
+  if (!signingKey?.privateKey || signingKey.status !== 'active') {
+    throw new Error('No active signing key.');
+  }
+  if (!DOC_TYPES.includes(docType)) throw new Error(`Unknown document type ${docType}`);
+  const header = { alg: signingKey.suite, kid: signingKey.kid, typ: docType };
+  const signingInput = `${TOKEN_PREFIX}.${encodeJson(header)}.${encodeJson({
+    ...payload,
+    type: docType,
+  })}`;
+  const signature = await signBytes(
+    signingKey.suite,
+    signingKey.privateKey,
+    enc.encode(signingInput),
+    contextFor(docType),
+  );
+  return `${signingInput}.${toBase64Url(signature)}`;
+}
+
+/**
+ * Verify a signed document against the local keyring.
+ * Returns { valid, reason, header?, payload?, key?, warnings[] }.
+ * The payload is only returned when the signature is valid — never act on
+ * unverified data.
+ */
+export async function verifyDocument(token, keyring) {
+  const fail = (reason) => ({ valid: false, reason, warnings: [] });
+  const parts = token.trim().split('.');
+  if (parts.length !== 4 || parts[0] !== TOKEN_PREFIX) {
+    return fail('This is not a Daily Grind signed document.');
+  }
+  const [, headerB64, payloadB64, sigB64] = parts;
+
+  let header, signature;
+  try {
+    header = decodeJson(headerB64);
+    signature = fromBase64Url(sigB64);
+  } catch {
+    return fail('The document is corrupted and cannot be decoded.');
+  }
+  if (!DOC_TYPES.includes(header?.typ)) return fail('Unknown document type.');
+
+  const key = keyring.find((k) => k.kid === header.kid);
+  if (!key) {
+    return fail('Signed by an unknown key — this document was not issued by a trusted Daily Grind key.');
+  }
+  // Never let the document choose the algorithm: it must match the trusted key.
+  if (header.alg !== key.suite) {
+    return fail('Algorithm mismatch between document and trusted key.');
+  }
+
+  let ok = false;
+  try {
+    ok = await verifyBytes(
+      key.suite,
+      key.publicKey,
+      signature,
+      enc.encode(`${TOKEN_PREFIX}.${headerB64}.${payloadB64}`),
+      contextFor(header.typ),
+    );
+  } catch {
+    ok = false;
+  }
+  if (!ok) {
+    return fail('Invalid signature — the document has been altered or forged.');
+  }
+
+  let payload;
+  try {
+    payload = decodeJson(payloadB64);
+  } catch {
+    return fail('Signed payload is not valid JSON.');
+  }
+  if (payload?.type !== header.typ) return fail('Document type mismatch.');
+
+  const warnings = [];
+  if (key.status === 'retired') warnings.push('Signed with a retired key (still trusted).');
+  if (header.typ === 'voucher') {
+    if (payload.expiresAt && Date.parse(payload.expiresAt) < Date.now()) {
+      warnings.push('This voucher has expired.');
+    }
+    const redeemed = await dbGet('redemptions', payload.id);
+    if (redeemed) {
+      warnings.push(`Already redeemed on ${new Date(redeemed.at).toLocaleString()}.`);
+    }
+  }
+  return { valid: true, reason: 'Authentic and unaltered.', header, payload, key, warnings };
+}
+
+export async function redeemVoucher(payload) {
+  if (await dbGet('redemptions', payload.id)) throw new Error('Voucher already redeemed.');
+  await dbPut('redemptions', { id: payload.id, at: new Date().toISOString() }, 'id');
+}
+
+/** Demo helper: alter the payload but keep the original signature. */
+export function tamperWithDocument(token) {
+  const parts = token.trim().split('.');
+  if (parts.length !== 4) return token;
+  const payload = decodeJson(parts[2]);
+  if ('totalCents' in payload) payload.totalCents = Math.max(0, payload.totalCents - 400);
+  if ('valueCents' in payload) payload.valueCents += 10000;
+  parts[2] = encodeJson(payload);
+  return parts.join('.');
+}

