new file mode 100644
index 0000000..9196eab
--- /dev/null
+++ b/js/keystore.js
@@ -0,0 +1,102 @@
+/**
+ * Browser storage for signing keys, trusted public keys, and the local
+ * voucher-redemption ledger.
+ *
+ * Signing keys live in IndexedDB. WebCrypto private keys are stored as
+ * non-extractable CryptoKey objects, so the raw key bytes can't be read,
+ * not even by this page's own scripts. ML-DSA has no native browser support,
+ * so its 32-byte seed is stored as bytes.
+ *
+ * If IndexedDB is unavailable (e.g. some private-browsing modes), everything
+ * falls back to memory for the current session only.
+ */
+const DB_NAME = 'daily-grind-signing';
+const DB_VERSION = 1;
+const STORES = ['keys', 'trusted'];
+const REDEEMED_KEY = 'dg-redeemed-vouchers';
+
+let dbPromise = null;
+const memory = { keys: new Map(), trusted: new Map() };
+export let persistent = true;
+
+function openDb() {
+  if (!dbPromise) {
+    dbPromise = new Promise((resolve) => {
+      if (!globalThis.indexedDB) {
+        persistent = false;
+        return resolve(null);
+      }
+      const req = indexedDB.open(DB_NAME, DB_VERSION);
+      req.onupgradeneeded = () => {
+        for (const s of STORES) {
+          if (!req.result.objectStoreNames.contains(s)) req.result.createObjectStore(s, { keyPath: 'keyId' });
+        }
+      };
+      req.onsuccess = () => resolve(req.result);
+      req.onerror = () => {
+        persistent = false;
+        resolve(null);
+      };
+    });
+  }
+  return dbPromise;
+}
+
+function tx(store, mode, fn) {
+  return openDb().then(
+    (db) =>
+      new Promise((resolve, reject) => {
+        if (!db) {
+          const r = fn(null);
+          return resolve(r && 'result' in r ? r.result : undefined);
+        }
+        const t = db.transaction(store, mode);
+        const req = fn(t.objectStore(store));
+        t.oncomplete = () => resolve(req && 'result' in req ? req.result : undefined);
+        t.onerror = () => reject(t.error);
+        t.onabort = () => reject(t.error);
+      }),
+  );
+}
+
+const list = (store) =>
+  tx(store, 'readonly', (s) => (s ? s.getAll() : { result: [...memory[store].values()] })).then((rows) =>
+    rows.sort((a, b) => (a.createdAt || a.addedAt || '').localeCompare(b.createdAt || b.addedAt || '')),
+  );
+const put = (store, rec) => tx(store, 'readwrite', (s) => (s ? s.put(rec) : void memory[store].set(rec.keyId, rec)));
+const del = (store, keyId) => tx(store, 'readwrite', (s) => (s ? s.delete(keyId) : void memory[store].delete(keyId)));
+
+export const listSigningKeys = () => list('keys');
+export const saveSigningKey = (k) => put('keys', k);
+export const deleteSigningKey = (keyId) => del('keys', keyId);
+
+export const listTrustedKeys = () => list('trusted');
+export const saveTrustedKey = (k) => put('trusted', { ...k, addedAt: new Date().toISOString() });
+export const deleteTrustedKey = (keyId) => del('trusted', keyId);
+
+/* Voucher redemption ledger (local to this browser). A signature shows a
+ * voucher is genuine, but it can't stop the same voucher being used twice.
+ * Stopping that needs a shared ledger on a server. This local ledger shows
+ * the idea and catches repeat use at a single till. */
+function readRedeemed() {
+  try {
+    const v = JSON.parse(localStorage.getItem(REDEEMED_KEY) || '{}');
+    return v && typeof v === 'object' && !Array.isArray(v) ? v : {};
+  } catch {
+    return {};
+  }
+}
+const voucherLedgerKey = (doc) => `${doc.keyId}:${doc.payload.code}`;
+export function getRedemption(doc) {
+  return readRedeemed()[voucherLedgerKey(doc)] || null;
+}
+export function markRedeemed(doc) {
+  const all = readRedeemed();
+  all[voucherLedgerKey(doc)] = new Date().toISOString();
+  try {
+    localStorage.setItem(REDEEMED_KEY, JSON.stringify(all));
+  } catch {
+    /* storage full / disabled */
+  }
+  return all[voucherLedgerKey(doc)];
+}
