+/**
+ * UI for issuing and verifying signed receipts and gift vouchers.
+ * All user-supplied and document-supplied text goes into the DOM through
+ * textContent (never innerHTML), so a pasted document can't inject markup.
+ */
+import {
+  ALGORITHMS,
+  buildReceipt,
+  buildVoucher,
+  computeTaxCents,
+  createSignedDocument,
+  exportPublicKey,
+  formatFingerprint,
+  generateSigningKey,
+  isAlgorithmSupported,
+  parsePublicKeyExport,
+  verifySignedDocument,
+  MAX_DOCUMENT_BYTES,
+} from './signing.js';
+import * as store from './keystore.js';
+
+const MENU = [
+  { sku: 'LATTE-MAPLE-OAT', name: 'Maple Oat Latte', unitCents: 575 },
+  { sku: 'ESP-DARK', name: 'Dark Roast Espresso', unitCents: 350 },
+  { sku: 'COLD-BREW-18H', name: 'Cold Brew', unitCents: 475 },
+  { sku: 'PASTRY-CROISSANT', name: 'Butter Croissant', unitCents: 395 },
+];
+const TAX_BPS = 800; // 8%
+const DEFAULT_ALG = 'ML-DSA-65';
+
+const $ = (sel) => document.querySelector(sel);
+const money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' });
+const fmtMoney = (cents) => money.format(cents / 100);
+const fmtDate = (iso) => new Date(iso).toLocaleString();
+
+/** Tiny DOM builder. String children become text nodes, never HTML. */
+function h(tag, attrs = {}, ...children) {
+  const el = document.createElement(tag);
+  for (const [k, v] of Object.entries(attrs)) {
+    if (v == null || v === false) continue;
+    if (k === 'class') el.className = v;
+    else if (k.startsWith('on')) el.addEventListener(k.slice(2), v);
+    else el.setAttribute(k, v === true ? '' : v);
+  }
+  for (const c of children.flat()) {
+    if (c == null || c === false) continue;
+    el.append(c instanceof Node ? c : document.createTextNode(String(c)));
+  }
+  return el;
+}
+
+const state = { keys: [], trusted: [] };
+const isTrusted = (keyId) => state.keys.some((k) => k.keyId === keyId) || state.trusted.some((k) => k.keyId === keyId);
+
+function download(filename, text) {
+  const url = URL.createObjectURL(new Blob([text], { type: 'application/json' }));
+  const a = h('a', { href: url, download: filename });
+  document.body.append(a);
+  a.click();
+  a.remove();
+  setTimeout(() => URL.revokeObjectURL(url), 1000);
+}
+
+async function copy(text, btn) {
+  try {
+    await navigator.clipboard.writeText(text);
+    const old = btn.textContent;
+    btn.textContent = 'Copied!';
+    setTimeout(() => (btn.textContent = old), 1200);
+  } catch {
+    /* clipboard blocked: the textarea is still selectable */
+  }
+}
+
+function setStatus(el, kind, text) {
+  el.className = `sig-status sig-status--${kind}`;
+  el.textContent = text;
+  el.hidden = !text;
+}
+
+/* ------------------------------------------------------------------ */
+/* Keys                                                                */
+/* ------------------------------------------------------------------ */
+
+function algBadge(alg) {
+  const pq = ALGORITHMS[alg].family === 'post-quantum';
+  return h('span', { class: `alg-badge ${pq ? 'alg-badge--pq' : ''}`, title: ALGORITHMS[alg].label }, pq ? `${alg} · PQ` : alg);
+}
+
+async function refreshKeys() {
+  [state.keys, state.trusted] = await Promise.all([store.listSigningKeys(), store.listTrustedKeys()]);
+  renderKeys();
