+            { class: 'key-item' },
+            h('div', {}, algBadge(k.alg), ' ', h('code', { class: 'fp', title: k.keyId }, formatFingerprint(k.keyId))),
+            h('small', {}, `Created ${fmtDate(k.createdAt)}`),
+            h(
+              'div',
+              { class: 'key-actions' },
+              h('button', {
+                type: 'button',
+                class: 'btn-link',
+                onclick: () =>
+                  download(`daily-grind-pubkey-${k.keyId.slice(0, 8)}.json`, JSON.stringify(exportPublicKey(k, 'The Daily Grind'), null, 2)),
+              }, 'Export public key'),
+              h('button', {
+                type: 'button',
+                class: 'btn-link danger',
+                onclick: async () => {
+                  if (!confirm('Delete this signing key? Documents it signed will show as untrusted in this browser from now on.')) return;
+                  await store.deleteSigningKey(k.keyId);
