+            { class: 'key-item' },
+            h('div', {}, algBadge(k.alg), ' ', h('code', { class: 'fp', title: k.keyId }, formatFingerprint(k.keyId))),
+            k.label ? h('small', {}, k.label) : null,
+            h('div', { class: 'key-actions' },
+              h('button', {
+                type: 'button',
+                class: 'btn-link danger',
+                onclick: async () => {
+                  await store.deleteTrustedKey(k.keyId);
