+  const sel = $('#sign-key-select');
+  const prev = sel.value;
+  sel.replaceChildren(
+    ...state.keys.map((k) => h('option', { value: k.keyId }, `${k.alg} · ${formatFingerprint(k.keyId)}`)),
+  );
+  if (state.keys.some((k) => k.keyId === prev)) sel.value = prev;
+  else if (state.keys.length) sel.value = state.keys[state.keys.length - 1].keyId;
+  sel.disabled = !state.keys.length;
+}
