+async function initAlgSelect() {
+  const sel = $('#alg-select');
+  for (const [alg, spec] of Object.entries(ALGORITHMS)) {
+    const supported = await isAlgorithmSupported(alg);
+    sel.append(
+      h('option', { value: alg, disabled: !supported }, supported ? spec.label : `${spec.label} (not supported in this browser)`),
