+          h('tr', { class: 'pr-total' }, h('td', {}, 'Total'), h('td', { class: 'num' }, fmtMoney(p.totalCents))),
+        ),
+      ),
+    );
+  }
+  return h(
+    'div',
+    { class: 'gift-card' },
