+/**
+ * Daily Grind signed documents: coffee order receipts and gift vouchers.
+ *
+ * Pure crypto + data module (no DOM). It works in browsers and in Node 20+.
+ *
+ * Supported signature algorithms:
+ *   - ECDSA-P256 : classical, WebCrypto, SHA-256, IEEE-P1363 (r||s) signatures
+ *   - Ed25519    : classical, WebCrypto (where the browser supports it)
+ *   - ML-DSA-65  : post-quantum lattice signatures (NIST FIPS 204), via the
+ *                  vendored @noble/post-quantum library
+ *
+ * Wire format (JSON envelope):
+ *   {
+ *     "format":    "daily-grind-signed/v1",
+ *     "type":      "receipt" | "voucher",
+ *     "alg":       "ECDSA-P256" | "Ed25519" | "ML-DSA-65",
+ *     "keyId":     base64url(SHA-256(alg || 0x00 || publicKey)),
+ *     "publicKey": base64url(SPKI for WebCrypto algs, raw for ML-DSA),
+ *     "issuedAt":  ISO-8601 timestamp,
+ *     "payload":   { ...receipt or voucher fields, money in integer cents },
+ *     "signature": base64url(signature)
+ *   }
+ *
+ * The signature covers  DOMAIN || 0x00 || canonicalJSON(every field except
+ * "signature"). Canonical JSON sorts object keys and allows only integers as
+ * numbers, so signer and verifier always build the same bytes.
+ *
+ * A valid signature by itself shows only that the document is intact and was
+ * signed by the holder of the embedded key. It counts as authentic only when
+ * that key's keyId is in the verifier's trusted-key set. verifySignedDocument
+ * reports these two cases separately.
+ */
+import { ml_dsa65 } from '../vendor/noble-post-quantum-ml-dsa-0.7.1.mjs';
+
+export const FORMAT = 'daily-grind-signed/v1';
+export const PUBKEY_FORMAT = 'daily-grind-pubkey/v1';
+export const MAX_DOCUMENT_BYTES = 64 * 1024;
+const DOMAIN = 'DailyGrind/SignedDocument/v1';
+const MLDSA_CONTEXT = utf8('DailyGrind/v1');
+const ENVELOPE_FIELDS = ['format', 'type', 'alg', 'keyId', 'publicKey', 'issuedAt', 'payload', 'signature'];
+const DOC_TYPES = ['receipt', 'voucher'];
+
+const subtle = globalThis.crypto.subtle;
+
+export const ALGORITHMS = Object.freeze({
+  'ECDSA-P256': Object.freeze({
+    label: 'ECDSA P-256 / SHA-256',
+    family: 'classical',
+    publicKeyBytes: 91, // SPKI
+    signatureBytes: 64,
+  }),
+  Ed25519: Object.freeze({
+    label: 'Ed25519',
+    family: 'classical',
+    publicKeyBytes: 44, // SPKI
+    signatureBytes: 64,
+  }),
+  'ML-DSA-65': Object.freeze({
+    label: 'ML-DSA-65 (FIPS 204, post-quantum)',
+    family: 'post-quantum',
+    publicKeyBytes: 1952,
+    signatureBytes: 3309,
+  }),
+});
+
+/* ------------------------------------------------------------------ */
+/* Encoding helpers                                                    */
+/* ------------------------------------------------------------------ */
+
+export function utf8(str) {
+  return new TextEncoder().encode(str);
+}
+
+export function toBase64Url(bytes) {
+  let bin = '';
+  const b = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
+  for (let i = 0; i < b.length; i++) bin += String.fromCharCode(b[i]);
+  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+}
+
+export function fromBase64Url(str) {
+  if (typeof str !== 'string' || !/^[A-Za-z0-9_-]*$/.test(str) || str.length % 4 === 1) {
+    throw new Error('invalid base64url');
+  }
+  const b64 = str.replace(/-/g, '+').replace(/_/g, '/') + '==='.slice((str.length + 3) % 4);
+  const bin = atob(b64);
+  const out = new Uint8Array(bin.length);
+  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
+  // Reject non-canonical encodings (e.g. stray trailing bits) so every value
+  // has exactly one valid encoding.
+  if (toBase64Url(out) !== str) throw new Error('non-canonical base64url');
+  return out;
+}
+
+function concatBytes(...parts) {
+  const len = parts.reduce((n, p) => n + p.length, 0);
+  const out = new Uint8Array(len);
+  let off = 0;
+  for (const p of parts) {
+    out.set(p, off);
+    off += p.length;
+  }
+  return out;
+}
+
+/**
+ * Deterministic JSON: object keys sorted, no whitespace. Numbers must be
+ * safe integers (money is always in cents), so float formatting can never make
+ * the signer and verifier disagree.
+ */
+export function canonicalJSON(value, depth = 0) {
+  if (depth > 16) throw new Error('structure too deep');
+  if (value === null || typeof value === 'boolean') return JSON.stringify(value);
+  if (typeof value === 'number') {
+    if (!Number.isSafeInteger(value)) throw new Error('only safe integers are allowed in signed data');
+    return String(value);
+  }
+  if (typeof value === 'string') return JSON.stringify(value);
+  if (Array.isArray(value)) return '[' + value.map((v) => canonicalJSON(v, depth + 1)).join(',') + ']';
+  if (typeof value === 'object') {
+    return (
+      '{' +
+      Object.keys(value)
+        .sort()
+        .map((k) => JSON.stringify(k) + ':' + canonicalJSON(value[k], depth + 1))
+        .join(',') +
+      '}'
+    );
+  }
+  throw new Error(`unsupported value type: ${typeof value}`);
+}
+
+function signingInput(fields) {
+  return concatBytes(utf8(DOMAIN), new Uint8Array([0]), utf8(canonicalJSON(fields)));
