+
+/* ------------------------------------------------------------------ */
+/* Algorithm back-ends                                                 */
+/* ------------------------------------------------------------------ */
+
+const webCryptoParams = {
+  'ECDSA-P256': {
+    gen: { name: 'ECDSA', namedCurve: 'P-256' },
+    sign: { name: 'ECDSA', hash: 'SHA-256' },
+  },
+  Ed25519: {
+    gen: { name: 'Ed25519' },
+    sign: { name: 'Ed25519' },
+  },
+};
+
+// ML-DSA secret keys are derived again from the 32-byte seed when needed.
+// Caching them per seed avoids repeating keygen on every signature.
+const mldsaSecretCache = new WeakMap();
+function mldsaSecretKey(seed) {
+  let sk = mldsaSecretCache.get(seed);
+  if (!sk) {
+    sk = ml_dsa65.keygen(seed).secretKey;
+    mldsaSecretCache.set(seed, sk);
+  }
+  return sk;
+}
+
+const supportCache = new Map();
+/** Ed25519 support in WebCrypto differs between browsers, so check for it at runtime. */
+export function isAlgorithmSupported(alg) {
+  if (!ALGORITHMS[alg]) return Promise.resolve(false);
+  if (alg === 'ML-DSA-65') return Promise.resolve(true);
+  if (!supportCache.has(alg)) {
+    supportCache.set(
+      alg,
+      subtle.generateKey(webCryptoParams[alg].gen, false, ['sign', 'verify']).then(
+        () => true,
+        () => false,
+      ),
+    );
+  }
+  return supportCache.get(alg);
+}
+
+/**
+ * Generate a new signing key.
+ * Returns { alg, keyId, publicKey: Uint8Array, privateKey, createdAt }, where
+ * privateKey is a non-extractable CryptoKey (WebCrypto algs) or the 32-byte
+ * ML-DSA seed (Uint8Array). Both can be stored in IndexedDB.
+ */
+export async function generateSigningKey(alg) {
+  if (!ALGORITHMS[alg]) throw new Error(`unsupported algorithm: ${alg}`);
+  let publicKey, privateKey;
+  if (alg === 'ML-DSA-65') {
+    privateKey = globalThis.crypto.getRandomValues(new Uint8Array(32));
+    publicKey = ml_dsa65.keygen(privateKey).publicKey;
+  } else {
+    // extractable=false: the private key can be used but never exported, not
+    // even by our own scripts. The public half can always be exported.
+    const pair = await subtle.generateKey(webCryptoParams[alg].gen, false, ['sign', 'verify']);
+    privateKey = pair.privateKey;
+    publicKey = new Uint8Array(await subtle.exportKey('spki', pair.publicKey));
+  }
+  return {
+    alg,
+    keyId: await computeKeyId(alg, publicKey),
+    publicKey,
+    privateKey,
+    createdAt: new Date().toISOString(),
+  };
+}
+
+async function rawSign(alg, privateKey, message) {
+  if (alg === 'ML-DSA-65') {
+    return ml_dsa65.sign(message, mldsaSecretKey(privateKey), { context: MLDSA_CONTEXT });
+  }
+  return new Uint8Array(await subtle.sign(webCryptoParams[alg].sign, privateKey, message));
+}
+
+async function rawVerify(alg, publicKey, signature, message) {
+  const spec = ALGORITHMS[alg];
+  if (publicKey.length !== spec.publicKeyBytes || signature.length !== spec.signatureBytes) return false;
+  try {
+    if (alg === 'ML-DSA-65') {
+      return ml_dsa65.verify(signature, message, publicKey, { context: MLDSA_CONTEXT });
+    }
+    const key = await subtle.importKey('spki', publicKey, webCryptoParams[alg].gen, false, ['verify']);
+    return await subtle.verify(webCryptoParams[alg].sign, key, signature, message);
+  } catch {
+    return false;
+  }
+}
+
+/* ------------------------------------------------------------------ */
+/* Payloads                                                            */
+/* ------------------------------------------------------------------ */
+
+export const STORE_NAME = 'The Daily Grind Coffee Co.';
+const VOUCHER_ALPHABET = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789'; // no 0/O/1/I/L
+const VOUCHER_RE = /^DG(-[A-HJKMNP-Z2-9]{4}){3}$/;
+
+function randomFrom(alphabet, n) {
+  const out = [];
+  // Rejection sampling avoids modulo bias.
+  const limit = 256 - (256 % alphabet.length);
+  while (out.length < n) {
+    for (const b of globalThis.crypto.getRandomValues(new Uint8Array(n * 2))) {
+      if (b < limit && out.length < n) out.push(alphabet[b % alphabet.length]);
+    }
+  }
+  return out.join('');
+}
+
+export function generateVoucherCode() {
+  const r = randomFrom(VOUCHER_ALPHABET, 12);
+  return `DG-${r.slice(0, 4)}-${r.slice(4, 8)}-${r.slice(8, 12)}`;
+}
+
+export function generateOrderId() {
+  const d = new Date().toISOString().slice(0, 10).replace(/-/g, '');
+  return `ORD-${d}-${randomFrom('0123456789ABCDEFGHJKMNPQRSTVWXYZ', 6)}`;
+}
+
+export function computeTaxCents(subtotalCents, taxBps) {
+  return Math.round((subtotalCents * taxBps) / 10000);
+}
+
+/** Build a receipt payload from line items; totals are computed here. */
+export function buildReceipt({ orderId = generateOrderId(), customer = '', items, taxBps }) {
+  const lines = items
+    .filter((i) => i.qty > 0)
+    .map((i) => ({ sku: i.sku, name: i.name, qty: i.qty, unitCents: i.unitCents }));
