+    currency: 'USD',
+    subtotalCents,
+    taxBps,
+    taxCents,
+    totalCents: subtotalCents + taxCents,
+  };
+  validatePayload('receipt', receipt);
+  return receipt;
+}
+
+export function buildVoucher({ code = generateVoucherCode(), amountCents, recipient, sender = '', message = '', expiresOn }) {
+  const voucher = {
+    store: STORE_NAME,
+    code,
+    amountCents,
+    currency: 'USD',
+    recipient: recipient.trim(),
+    sender: sender.trim(),
+    message: message.trim(),
+    expiresOn,
+  };
+  validatePayload('voucher', voucher);
+  return voucher;
+}
+
+function assert(cond, msg) {
+  if (!cond) throw new Error(msg);
+}
+const isStr = (v, min, max) => typeof v === 'string' && v.length >= min && v.length <= max;
+const isInt = (v, min, max) => Number.isSafeInteger(v) && v >= min && v <= max;
+function exactKeys(obj, keys, what) {
+  assert(obj && typeof obj === 'object' && !Array.isArray(obj), `${what} must be an object`);
+  const actual = Object.keys(obj).sort();
+  const expected = [...keys].sort();
+  assert(
+    actual.length === expected.length && actual.every((k, i) => k === expected[i]),
+    `${what} has unexpected or missing fields`,
+  );
+}
+
+function isValidDateOnly(s) {
+  if (typeof s !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(s)) return false;
+  const d = new Date(`${s}T00:00:00Z`);
+  return !Number.isNaN(d.getTime()) && d.toISOString().slice(0, 10) === s;
+}
+
+/** Strict schema + arithmetic checks. Throws with a readable message on failure. */
+export function validatePayload(type, p) {
+  if (type === 'receipt') {
+    exactKeys(p, ['store', 'orderId', 'customer', 'items', 'currency', 'subtotalCents', 'taxBps', 'taxCents', 'totalCents'], 'receipt');
+    assert(p.store === STORE_NAME, 'receipt store name is not recognised');
+    assert(isStr(p.orderId, 1, 40), 'receipt orderId is invalid');
+    assert(isStr(p.customer, 0, 80), 'receipt customer is invalid');
+    assert(p.currency === 'USD', 'receipt currency must be USD');
+    assert(Array.isArray(p.items) && p.items.length >= 1 && p.items.length <= 50, 'receipt must have 1–50 items');
+    let sum = 0;
+    for (const it of p.items) {
+      exactKeys(it, ['sku', 'name', 'qty', 'unitCents'], 'receipt item');
+      assert(isStr(it.sku, 1, 40) && isStr(it.name, 1, 80), 'receipt item name/sku is invalid');
+      assert(isInt(it.qty, 1, 99), 'receipt item quantity must be 1–99');
+      assert(isInt(it.unitCents, 0, 100000), 'receipt item price is invalid');
+      sum += it.qty * it.unitCents;
+    }
+    assert(isInt(p.taxBps, 0, 3000), 'receipt tax rate is invalid');
+    assert(p.subtotalCents === sum, 'receipt subtotal does not match its items');
+    assert(p.taxCents === computeTaxCents(sum, p.taxBps), 'receipt tax does not match its rate');
+    assert(p.totalCents === p.subtotalCents + p.taxCents, 'receipt total does not add up');
+    return;
+  }
+  if (type === 'voucher') {
+    exactKeys(p, ['store', 'code', 'amountCents', 'currency', 'recipient', 'sender', 'message', 'expiresOn'], 'voucher');
+    assert(p.store === STORE_NAME, 'voucher store name is not recognised');
+    assert(typeof p.code === 'string' && VOUCHER_RE.test(p.code), 'voucher code is malformed');
+    assert(isInt(p.amountCents, 100, 50000), 'voucher amount must be $1–$500');
+    assert(p.currency === 'USD', 'voucher currency must be USD');
+    assert(isStr(p.recipient, 1, 80), 'voucher recipient is required (max 80 chars)');
+    assert(isStr(p.sender, 0, 80), 'voucher sender is too long');
+    assert(isStr(p.message, 0, 280), 'voucher message is too long (max 280 chars)');
+    assert(isValidDateOnly(p.expiresOn), 'voucher expiry date is invalid');
+    return;
+  }
+  throw new Error(`unknown document type: ${type}`);
+}
+
+export function isVoucherExpired(voucher, now = new Date()) {
+  // Valid through the end of the expiry day (UTC).
+  return now.getTime() >= new Date(`${voucher.expiresOn}T00:00:00Z`).getTime() + 86400000;
+}
+
+/* ------------------------------------------------------------------ */
+/* Sign / verify                                                       */
+/* ------------------------------------------------------------------ */
+
+/**
+ * @param {'receipt'|'voucher'} type
+ * @param {object} payload  output of buildReceipt / buildVoucher
+ * @param {{alg, keyId, publicKey, privateKey}} key
+ * @returns {Promise<object>} signed envelope (JSON-serialisable)
+ */
+export async function createSignedDocument(type, payload, key) {
+  assert(DOC_TYPES.includes(type), `unknown document type: ${type}`);
+  assert(ALGORITHMS[key.alg], `unsupported algorithm: ${key.alg}`);
+  validatePayload(type, payload);
+  // Re-derive keyId so a corrupted key record can never produce a document
+  // whose keyId is bound to a different public key.
+  const keyId = await computeKeyId(key.alg, key.publicKey);
+  assert(keyId === key.keyId, 'key record is corrupted (keyId mismatch)');
+  const fields = {
+    format: FORMAT,
+    type,
+    alg: key.alg,
+    keyId,
+    publicKey: toBase64Url(key.publicKey),
+    issuedAt: new Date().toISOString(),
+    payload,
+  };
+  const signature = await rawSign(key.alg, key.privateKey, signingInput(fields));
+  return { ...fields, signature: toBase64Url(signature) };
+}
+
+/**
+ * Verify a signed document.
+ *
+ * @param {string|object} input  JSON text or parsed envelope
+ * @param {{ isTrusted?: (keyId: string) => boolean, now?: Date }} [opts]
+ * @returns {Promise<{
