+ *   signatureValid: boolean,
+ *   trusted: boolean,
+ *   reason: string,
+ *   warnings: string[],
+ *   document?: object,
+ *   fingerprint?: string,
+ * }>}
+ */
+export async function verifySignedDocument(input, opts = {}) {
+  const { isTrusted = () => false, now = new Date() } = opts;
+  const fail = (status, reason, extra = {}) => ({
+    status,
+    signatureValid: false,
+    trusted: false,
+    reason,
+    warnings: [],
+    ...extra,
+  });
+
+  let doc = input;
+  if (typeof input === 'string') {
+    if (utf8(input).length > MAX_DOCUMENT_BYTES) return fail('malformed', 'Document is too large.');
+    try {
+      doc = JSON.parse(input);
+    } catch {
+      return fail('malformed', 'The document is not valid JSON.');
+    }
+  }
+
+  let publicKey, signature;
+  try {
+    exactKeys(doc, ENVELOPE_FIELDS, 'document');
+    assert(doc.format === FORMAT, 'unsupported document format');
+    assert(DOC_TYPES.includes(doc.type), 'unknown document type');
+    assert(Object.hasOwn(ALGORITHMS, doc.alg), 'unsupported signature algorithm');
+    assert(typeof doc.issuedAt === 'string' && !Number.isNaN(Date.parse(doc.issuedAt)), 'issuedAt is invalid');
+    publicKey = fromBase64Url(doc.publicKey);
+    signature = fromBase64Url(doc.signature);
+    assert(typeof doc.keyId === 'string', 'keyId is missing');
+    validatePayload(doc.type, doc.payload);
+  } catch (e) {
+    return fail('malformed', `Malformed document: ${e.message}.`);
+  }
+
+  const fingerprint = formatFingerprint(doc.keyId);
+  // Bind keyId <-> (alg, publicKey). This stops a forger from embedding their
+  // own key under a trusted keyId, and stops algorithm-substitution tricks.
+  const expectedKeyId = await computeKeyId(doc.alg, publicKey);
+  if (expectedKeyId !== doc.keyId) {
+    return fail('invalid', 'The key ID does not match the embedded public key. The document has been tampered with.', {
+      document: doc,
+      fingerprint,
+    });
+  }
+
+  const { signature: _sig, ...fields } = doc;
+  let message;
+  try {
+    message = signingInput(fields);
+  } catch (e) {
+    return fail('malformed', `Malformed document: ${e.message}.`);
+  }
+  const ok = await rawVerify(doc.alg, publicKey, signature, message);
+  if (!ok) {
+    return fail('invalid', 'Signature check failed. The document was changed after signing, or the signature is forged.', {
+      document: doc,
+      fingerprint,
+    });
+  }
+
+  const warnings = [];
+  if (Date.parse(doc.issuedAt) > now.getTime() + 5 * 60 * 1000) {
+    warnings.push('The issue date is in the future.');
+  }
+  if (doc.type === 'voucher' && isVoucherExpired(doc.payload, now)) {
+    warnings.push(`This voucher expired on ${doc.payload.expiresOn}.`);
+  }
+
+  const trusted = Boolean(isTrusted(doc.keyId));
+  return {
+    status: trusted ? 'trusted' : 'untrusted',
+    signatureValid: true,
+    trusted,
+    reason: trusted
+      ? 'Authentic: the signature is valid and was made by a trusted Daily Grind key.'
+      : 'The signature is valid, but the signing key is NOT on your trusted list. Anyone can create a key, so this document could be a forgery made with someone else\'s key.',
+    warnings,
+    document: doc,
+    fingerprint,
+  };
+}
+
+/* ------------------------------------------------------------------ */
+/* Public key exchange                                                 */
+/* ------------------------------------------------------------------ */
+
+export function exportPublicKey(key, label = '') {
+  return {
+    format: PUBKEY_FORMAT,
+    alg: key.alg,
+    keyId: key.keyId,
+    publicKey: toBase64Url(key.publicKey),
+    label,
+  };
+}
+
+/** Parse and validate a public-key export (JSON text or object). */
+export async function parsePublicKeyExport(input) {
+  let obj = input;
+  if (typeof input === 'string') {
+    assert(input.length <= 16 * 1024, 'public key file is too large');
+    try {
+      obj = JSON.parse(input);
+    } catch {
+      throw new Error('not valid JSON');
+    }
+  }
+  assert(obj && typeof obj === 'object' && !Array.isArray(obj), 'public key must be a JSON object');
+  // Accept a signed document as well and pull its embedded key out of it.
+  if (obj.format === FORMAT) obj = { format: PUBKEY_FORMAT, alg: obj.alg, keyId: obj.keyId, publicKey: obj.publicKey, label: '' };
+  assert(obj.format === PUBKEY_FORMAT, 'unsupported public key format');
+  assert(Object.hasOwn(ALGORITHMS, obj.alg), 'unsupported algorithm');
+  const publicKey = fromBase64Url(obj.publicKey);
+  assert(publicKey.length === ALGORITHMS[obj.alg].publicKeyBytes, 'public key has the wrong length');
+  if (obj.alg !== 'ML-DSA-65') {
+    try {
+      await subtle.importKey('spki', publicKey, webCryptoParams[obj.alg].gen, false, ['verify']);
+    } catch {
+      throw new Error('public key cannot be imported for this algorithm');
+    }
+  }
+  const keyId = await computeKeyId(obj.alg, publicKey);
+  assert(keyId === obj.keyId, 'keyId does not match public key');
+  const label = typeof obj.label === 'string' ? obj.label.slice(0, 80) : '';
+  return { alg: obj.alg, keyId, publicKey, label };
+}
