new file mode 100644
index 0000000..55b8056
--- /dev/null
+++ b/tests/signing.test.mjs
@@ -0,0 +1,99 @@
+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import {
+  ALGORITHMS, buildReceipt, buildVoucher, canonicalJSON, createSignedDocument,
+  exportPublicKey, fromBase64Url, generateSigningKey, parsePublicKeyExport,
+  toBase64Url, verifySignedDocument, isAlgorithmSupported,
+} from '../js/signing.js';
+
+const receipt = () => buildReceipt({
+  customer: 'Ada', taxBps: 800,
+  items: [{ sku: 'ESP-DARK', name: 'Dark Roast Espresso', qty: 2, unitCents: 350 }],
+});
+const voucher = (expiresOn = '2099-12-31') => buildVoucher({ amountCents: 2500, recipient: 'Grace', expiresOn });
+
+for (const alg of Object.keys(ALGORITHMS)) {
+  test(`${alg}: sign → verify round trip, trust & tamper detection`, async (t) => {
+    if (!(await isAlgorithmSupported(alg))) return t.skip('unsupported');
+    const key = await generateSigningKey(alg);
+    const trust = (id) => id === key.keyId;
+
+    for (const [type, payload] of [['receipt', receipt()], ['voucher', voucher()]]) {
+      const doc = await createSignedDocument(type, payload, key);
+      const json = JSON.stringify(doc);
+
+      const ok = await verifySignedDocument(json, { isTrusted: trust });
+      assert.equal(ok.status, 'trusted', ok.reason);
+      assert.equal((await verifySignedDocument(json)).status, 'untrusted');
+
+      // Payload tampering (kept arithmetically consistent).
+      const t1 = JSON.parse(json);
+      if (type === 'voucher') t1.payload.amountCents = 50000;
+      else t1.payload.customer = 'Mallory';
+      assert.equal((await verifySignedDocument(t1, { isTrusted: trust })).status, 'invalid');
+
+      // Envelope tampering.
+      const t2 = JSON.parse(json); t2.issuedAt = '2020-01-01T00:00:00.000Z';
+      assert.equal((await verifySignedDocument(t2, { isTrusted: trust })).status, 'invalid');
+
+      // Signature bit flip.
+      const t3 = JSON.parse(json); const sig = fromBase64Url(t3.signature); sig[5] ^= 1; t3.signature = toBase64Url(sig);
+      assert.equal((await verifySignedDocument(t3, { isTrusted: trust })).status, 'invalid');
+
+      // Unknown extra field.
+      assert.equal((await verifySignedDocument({ ...doc, extra: 1 })).status, 'malformed');
+    }
+  });
+}
+
+test('forger key swapped in under a trusted keyId is rejected', async () => {
+  const real = await generateSigningKey('ECDSA-P256');
+  const forger = await generateSigningKey('ECDSA-P256');
+  const forged = await createSignedDocument('voucher', voucher(), forger);
+  forged.keyId = real.keyId; // claim to be the real key
+  const r = await verifySignedDocument(forged, { isTrusted: (id) => id === real.keyId });
+  assert.equal(r.status, 'invalid');
+  // Self-consistent forgery: valid signature but untrusted.
+  const forged2 = await createSignedDocument('voucher', voucher(), forger);
+  assert.equal((await verifySignedDocument(forged2, { isTrusted: (id) => id === real.keyId })).status, 'untrusted');
+});
+
+test('algorithm substitution is rejected', async () => {
+  const key = await generateSigningKey('ML-DSA-65');
+  const doc = await createSignedDocument('receipt', receipt(), key);
+  doc.alg = 'ECDSA-P256';
+  assert.notEqual((await verifySignedDocument(doc, { isTrusted: () => true })).status, 'trusted');
+});
+
+test('expired voucher verifies but warns', async () => {
+  const key = await generateSigningKey('ECDSA-P256');
+  const doc = await createSignedDocument('voucher', voucher('2020-01-01'), key);
+  const r = await verifySignedDocument(doc, { isTrusted: () => true });
+  assert.equal(r.status, 'trusted');
+  assert.ok(r.warnings.some((w) => w.includes('expired')));
+});
+
+test('payload validation', () => {
+  assert.throws(() => buildVoucher({ amountCents: 99, recipient: 'x', expiresOn: '2099-01-01' }));
+  assert.throws(() => buildVoucher({ amountCents: 1000, recipient: ' ', expiresOn: '2099-01-01' }));
+  assert.throws(() => buildVoucher({ amountCents: 1000, recipient: 'x', expiresOn: '2099-02-30' }));
+  assert.throws(() => buildReceipt({ taxBps: 800, items: [] }));
+  assert.throws(() => canonicalJSON({ a: 1.5 }));
+  assert.equal(canonicalJSON({ b: [1, 'x'], a: null }), '{"a":null,"b":[1,"x"]}');
+});
+
+test('malformed inputs', async () => {
+  assert.equal((await verifySignedDocument('not json')).status, 'malformed');
+  assert.equal((await verifySignedDocument('[]')).status, 'malformed');
+  assert.equal((await verifySignedDocument('x'.repeat(70000))).status, 'malformed');
+  assert.throws(() => fromBase64Url('ab+c'));
+});
+
+test('public key export/import round trip and keyId binding', async () => {
+  const key = await generateSigningKey('ML-DSA-65');
+  const exp = exportPublicKey(key, 'Main St till');
+  const parsed = await parsePublicKeyExport(JSON.stringify(exp));
+  assert.equal(parsed.keyId, key.keyId);
+  await assert.rejects(parsePublicKeyExport({ ...exp, keyId: 'A'.repeat(43) }));
+  await assert.rejects(parsePublicKeyExport({ ...exp, alg: 'ECDSA-P256' }));
+});
