       text-decoration: none;
       font-size: 0.85rem;
     }
+
+    /* Seasonal Favorites carousel */
+    .carousel {
+      max-width: 520px;
+      margin: 20px auto 0;
+    }
+
+    /* Outer clip used when falling back to a document-level view transition */
+    .carousel-stage {
+      overflow: clip;
+      border-radius: 8px;
+      view-transition-name: seasonal-stage;
+      view-transition-group: contain;
+    }
+
+    ::view-transition-group-children(seasonal-stage) {
+      overflow: clip;
+    }
+
+    /* Scope element for element-scoped view transitions (auto-clips children) */
+    .carousel-viewport {
+      overflow: clip;
+      padding: 6px;
+    }
+
+    .carousel-viewport .card {
+      min-height: 190px;
+      display: flex;
+      flex-direction: column;
+      justify-content: center;
+      align-items: center;
+      view-transition-name: seasonal-card;
+    }
+
+    .carousel-viewport .card[hidden] {
+      display: none;
+    }
+
+    .carousel-controls {
+      display: flex;
+      justify-content: space-between;
+      align-items: center;
+      margin-top: 15px;
+    }
+
+    .carousel-btn {
+      font: inherit;
+      background: var(--primary);
+      color: white;
+      border: none;
+      border-radius: 5px;
+      padding: 8px 18px;
+      cursor: pointer;
+      transition: background 0.3s;
+    }
+
+    .carousel-btn:hover {
+      background: #3e2723;
+    }
+
+    .carousel-btn:focus-visible {
+      outline: 3px solid var(--accent);
+      outline-offset: 2px;
+    }
+
+    .carousel-status {
+      font-size: 0.9rem;
+    }
+
+    /* Directional slide animations */
+    @keyframes slide-to-left {
+      to { transform: translateX(-100%); }
+    }
+
+    @keyframes slide-from-right {
+      from { transform: translateX(100%); }
+    }
+
+    @keyframes slide-to-right {
+      to { transform: translateX(100%); }
+    }
+
+    @keyframes slide-from-left {
+      from { transform: translateX(-100%); }
+    }
+
+    ::view-transition-old(seasonal-card),
+    ::view-transition-new(seasonal-card) {
+      animation-duration: 0.4s;
+      animation-timing-function: ease-in-out;
+      animation-fill-mode: both;
+    }
+
+    /* Swap the default cross-fade for a slide; snapshots keep their own size */
+    ::view-transition-group(seasonal-card) {
+      animation-duration: 0.4s;
+      animation-timing-function: ease-in-out;
+    }
+
+    :active-view-transition-type(forward)::view-transition-old(seasonal-card) {
+      animation-name: slide-to-left;
+    }
+
+    :active-view-transition-type(forward)::view-transition-new(seasonal-card) {
+      animation-name: slide-from-right;
+    }
+
+    :active-view-transition-type(backward)::view-transition-old(seasonal-card) {
+      animation-name: slide-to-right;
+    }
+
+    :active-view-transition-type(backward)::view-transition-new(seasonal-card) {
+      animation-name: slide-from-left;
+    }
+
+    @media (prefers-reduced-motion: reduce) {
+      ::view-transition-group(*),
+      ::view-transition-old(*),
+      ::view-transition-new(*) {
+        animation: none !important;
+      }
+    }
   </style>
