+import { useState } from 'react';
+import { ChevronLeftIcon, ChevronRightIcon } from '@heroicons/react/24/outline';
+
+export interface TopStory {
+  id: string;
+  title: string;
+  date: string;
+  href: string;
+}
+
+interface Props {
+  stories: TopStory[];
+}
+
+type Direction = 'next' | 'prev';
+
+interface SlideState {
+  index: number;
+  /** Index of the story currently animating out, if any. */
+  outgoing: number | null;
+  direction: Direction;
+  /** Incremented on each change so slides remount and restart their animation. */
+  step: number;
+}
+
+export default function TopStoriesCarousel({ stories }: Props) {
+  const [state, setState] = useState<SlideState>({
+    index: 0,
+    outgoing: null,
+    direction: 'next',
+    step: 0,
+  });
+
+  const count = stories.length;
+  if (count === 0) return null;
+
+  const go = (direction: Direction) => {
+    setState((s) => ({
+      index: (s.index + (direction === 'next' ? 1 : -1) + count) % count,
+      outgoing: s.index,
+      direction,
+      step: s.step + 1,
+    }));
+  };
+
+  const clearOutgoing = (step: number) => {
+    setState((s) => (s.step === step ? { ...s, outgoing: null } : s));
+  };
+
+  const { index, outgoing, direction, step } = state;
+  const current = stories[index];
+  const animate = step > 0;
+
+  const renderStory = (
+    key: string,
+    story: TopStory,
+    className: string,
+    extra: Record<string, unknown> = {}
+  ) => (
+    <div key={key} className={`[grid-area:1/1] min-w-0 ${className}`} {...extra}>
+      <a href={story.href}>
+        <h3 className="font-bold text-gray-900 hover:text-amber-400 cursor-pointer">{story.title}</h3>
+      </a>
+      <span className="text-xs text-gray-500">{story.date}</span>
+    </div>
+  );
+
+  const buttonClass =
+    'shrink-0 p-1.5 rounded-full border border-gray-300 text-gray-700 hover:text-amber-400 hover:border-amber-400 focus:outline-none focus-visible:ring-2 focus-visible:ring-amber-400 disabled:opacity-40 disabled:pointer-events-none';
+
+  return (
+    <section
+      className="flex items-center gap-3"
+      aria-roledescription="carousel"
+      aria-label="Top stories"
+    >
+      <button
+        type="button"
+        className={buttonClass}
+        onClick={() => go('prev')}
+        aria-label="Previous story"
+        disabled={count < 2}
+      >
+        <ChevronLeftIcon className="h-5 w-5" aria-hidden="true" />
+      </button>
+
+      <div className="relative flex-1 min-w-0 overflow-hidden grid" aria-live="polite">
+        {outgoing !== null &&
+          outgoing !== index &&
+          renderStory(
+            `out-${step}`,
+            stories[outgoing],
+            direction === 'next' ? 'top-story-out-left' : 'top-story-out-right',
+            {
+              'aria-hidden': true,
+              inert: true,
+              onAnimationEnd: () => clearOutgoing(step),
+            }
+          )}
+        {renderStory(
+          `in-${step}`,
+          current,
+          animate ? (direction === 'next' ? 'top-story-in-right' : 'top-story-in-left') : '',
+          {
+            role: 'group',
+            'aria-roledescription': 'slide',
+            'aria-label': `${index + 1} of ${count}`,
+          }
+        )}
+      </div>
+
+      <span className="hidden sm:inline text-xs text-gray-500 tabular-nums" aria-hidden="true">
+        {index + 1} / {count}
+      </span>
+
+      <button
+        type="button"
+        className={buttonClass}
+        onClick={() => go('next')}
+        aria-label="Next story"
+        disabled={count < 2}
+      >
+        <ChevronRightIcon className="h-5 w-5" aria-hidden="true" />
+      </button>
+    </section>
+  );
+}
