+      const body = $('qo-body');
+      const POS_KEY = 'dailyGrind.quickOrder.pos';
+      const CART_KEY = 'dailyGrind.quickOrder.cart';
+      const STEP = 15;
+      const MARGIN = 8;
+
+      // ---- Progressive enhancement: reveal JS-only controls ----
+      panel.classList.add('is-enhanced');
+      ['qo-grip', 'qo-move-toggle', 'qo-help-toggle', 'qo-collapse'].forEach((id) => { $(id).hidden = false; });
+
+      // ---- Announcements ----
+      let liveTimer;
+      function announce(msg) {
+        live.textContent = msg;
+        clearTimeout(liveTimer);
+        liveTimer = setTimeout(() => { live.textContent = ''; }, 1000);
+      }
+
+      // ---- Positioning ----
+      function moveTo(left, top) {
+        const maxLeft = Math.max(MARGIN, window.innerWidth - panel.offsetWidth - MARGIN);
+        const maxTop = Math.max(MARGIN, window.innerHeight - panel.offsetHeight - MARGIN);
+        const x = Math.max(MARGIN, Math.min(left, maxLeft));
+        const y = Math.max(MARGIN, Math.min(top, maxTop));
+        panel.style.left = `${x}px`;
+        panel.style.top = `${y}px`;
+        panel.style.right = 'auto';
+        panel.style.bottom = 'auto';
+        return { x, y };
+      }
+
+      function savePos() {
+        const rect = panel.getBoundingClientRect();
+        try { localStorage.setItem(POS_KEY, JSON.stringify({ x: rect.left, y: rect.top })); } catch {}
+      }
+
+      function restorePos() {
+        try {
+          const saved = JSON.parse(localStorage.getItem(POS_KEY));
+          if (saved && Number.isFinite(saved.x) && Number.isFinite(saved.y)) moveTo(saved.x, saved.y);
+        } catch {}
+      }
+
+      function reclamp() {
+        if (!panel.style.left) return; // still in default CSS position
+        const rect = panel.getBoundingClientRect();
+        moveTo(rect.left, rect.top);
+      }
+
+      // ---- Pointer dragging (header handle) ----
+      let offsetX = 0, offsetY = 0, startX = 0, startY = 0, dragging = false;
+
+      handle.addEventListener('pointerdown', (event) => {
+        const control = event.target.closest('button, input, select, textarea, a');
+        if (event.button !== 0 || (control && control !== grip)) return;
+        const rect = panel.getBoundingClientRect();
+        offsetX = event.clientX - rect.left;
+        offsetY = event.clientY - rect.top;
+        startX = event.clientX;
+        startY = event.clientY;
+        dragging = false;
+        handle.setPointerCapture(event.pointerId);
+        event.preventDefault();
+      });
+
+      handle.addEventListener('pointermove', (event) => {
+        if (!handle.hasPointerCapture(event.pointerId)) return;
+        if (!dragging) {
+          if (Math.hypot(event.clientX - startX, event.clientY - startY) < 4) return;
+          dragging = true;
+          handle.classList.add('dragging');
+          panel.classList.add('is-dragging');
+        }
+        moveTo(event.clientX - offsetX, event.clientY - offsetY);
+      });
+
+      handle.addEventListener('lostpointercapture', () => {
+        handle.classList.remove('dragging');
+        panel.classList.remove('is-dragging');
+        if (dragging) {
+          savePos();
+          announce('Quick order panel moved');
+        }
+        dragging = false;
+      });
+
+      // ---- Keyboard movement (grip button) ----
+      const KEY_DIRS = {
+        ArrowLeft: [-1, 0, 'left'], ArrowRight: [1, 0, 'right'],
+        ArrowUp: [0, -1, 'up'], ArrowDown: [0, 1, 'down'],
+      };
+      grip.addEventListener('keydown', (event) => {
+        const dir = KEY_DIRS[event.key];
+        if (!dir) return;
+        event.preventDefault();
+        const step = event.shiftKey ? STEP * 4 : STEP;
+        const rect = panel.getBoundingClientRect();
+        moveTo(rect.left + dir[0] * step, rect.top + dir[1] * step);
+        savePos();
+        announce(`Quick order panel moved ${dir[2]}`);
+      });
+
+      // ---- Single-pointer alternative: dock to corners ----
+      function dock(where) {
+        const [v, h] = where.split('-');
+        const left = h === 'left' ? MARGIN : window.innerWidth;
+        const top = v === 'top' ? MARGIN : window.innerHeight;
+        moveTo(left, top);
+        savePos();
+        announce(`Quick order panel docked ${v} ${h}`);
+      }
+      panel.querySelectorAll('[data-dock]').forEach((btn) => {
+        btn.addEventListener('click', () => dock(btn.dataset.dock));
+      });
+
+      // ---- Disclosure toggles ----
+      function bindToggle(btnId, onChange) {
+        const btn = $(btnId);
+        const target = $(btn.getAttribute('aria-controls'));
+        btn.addEventListener('click', () => {
+          const open = btn.getAttribute('aria-expanded') !== 'true';
+          btn.setAttribute('aria-expanded', String(open));
+          target.hidden = !open;
+          onChange?.(open, btn);
+          reclamp();
+        });
+      }
+      bindToggle('qo-move-toggle');
+      bindToggle('qo-help-toggle');
+      bindToggle('qo-collapse', (open, btn) => {
+        btn.textContent = open ? '–' : '+';
+        btn.setAttribute('aria-label', `${open ? 'Collapse' : 'Expand'} quick order panel`);
+        btn.title = open ? 'Collapse' : 'Expand';
+      });
+
+      // Keep the panel reachable when the viewport or panel size changes
+      window.addEventListener('resize', reclamp);
+      new ResizeObserver(reclamp).observe(panel);
+
+      // ---- Order builder ----
+      const form = $('qo-form');
+      const drink = $('qo-drink');
+      const milk = $('qo-milk');
+      const shot = $('qo-shot');
+      const qtyOut = $('qo-qty');
+      const qtyInput = $('qo-qty-input');
+      const linePrice = $('qo-line-price');
+      const cartList = $('qo-cart');
+      const emptyMsg = $('qo-empty');
+      const totalEl = $('qo-total');
+      const countEl = $('qo-count');
+      const fmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' });
+      let qty = 1;
+      let cart = [];
+      try { cart = JSON.parse(localStorage.getItem(CART_KEY)) || []; } catch { cart = []; }
+
+      function currentItem() {
+        const drinkOpt = drink.selectedOptions[0];
+        const sizeInput = form.querySelector('input[name="size"]:checked');
+        const milkOpt = milk.selectedOptions[0];
+        const unit = Number(drinkOpt.dataset.price) + Number(sizeInput.dataset.add) +
+          Number(milkOpt.dataset.add) + (shot.checked ? 0.75 : 0);
+        return {
+          name: drinkOpt.textContent.split(' — ')[0],
+          details: [sizeInput.value, milkOpt.value === 'none' ? 'no milk' : `${milkOpt.value} milk`,
+            shot.checked ? 'extra shot' : null].filter(Boolean).join(', '),
+          unit,
+          qty,
+        };
+      }
+
+      function updateLinePrice() {
+        const item = currentItem();
+        linePrice.textContent = fmt.format(item.unit * item.qty);
+      }
+
+      function setQty(n) {
+        qty = Math.max(1, Math.min(10, n));
+        qtyOut.textContent = qty;
+        qtyInput.value = qty;
+        $('qo-minus').disabled = qty === 1;
+        $('qo-plus').disabled = qty === 10;
+        updateLinePrice();
+      }
+
+      function renderCart() {
+        cartList.replaceChildren(...cart.map((item, i) => {
+          const li = document.createElement('li');
+          const text = document.createElement('span');
+          text.textContent = `${item.qty} × ${item.name}`;
+          const small = document.createElement('small');
+          small.textContent = item.details;
+          text.append(small);
+          const price = document.createElement('strong');
+          price.textContent = fmt.format(item.unit * item.qty);
+          const remove = document.createElement('button');
+          remove.type = 'button';
+          remove.className = 'remove';
+          remove.textContent = '✕';
+          remove.setAttribute('aria-label', `Remove ${item.name} from cart`);
+          remove.addEventListener('click', () => {
+            cart.splice(i, 1);
+            persistCart();
+            renderCart();
+            announce(`${item.name} removed from cart`);
+            (cartList.querySelector('.remove') || drink).focus();
+          });
+          li.append(text, price, remove);
+          return li;
+        }));
+        const count = cart.reduce((n, item) => n + item.qty, 0);
+        const total = cart.reduce((sum, item) => sum + item.unit * item.qty, 0);
+        emptyMsg.hidden = cart.length > 0;
+        totalEl.textContent = fmt.format(total);
+        countEl.textContent = count;
+        countEl.setAttribute('aria-label', `${count} item${count === 1 ? '' : 's'} in cart`);
+      }
+
+      function persistCart() {
+        try { localStorage.setItem(CART_KEY, JSON.stringify(cart)); } catch {}
+      }
+
+      form.addEventListener('input', updateLinePrice);
+      $('qo-minus').addEventListener('click', () => setQty(qty - 1));
+      $('qo-plus').addEventListener('click', () => setQty(qty + 1));
+
+      form.addEventListener('submit', (event) => {
+        event.preventDefault();
+        const item = currentItem();
+        const existing = cart.find((c) => c.name === item.name && c.details === item.details);
+        if (existing) existing.qty += item.qty; else cart.push(item);
+        persistCart();
+        renderCart();
+        announce(`Added ${item.qty} ${item.name} to cart`);
+        setQty(1);
+      });
+
+      $('qo-checkout').addEventListener('click', (event) => {
+        if (!cart.length) {
+          event.preventDefault();
+          announce('Your cart is empty. Add a drink first.');
+          drink.focus();
+        }
+      });
+
+      setQty(1);
+      renderCart();
+      restorePos();
+    })();
+  </script>
+
 </body>

+
 </html>

