+          var moves = { ArrowLeft: [-step, 0], ArrowRight: [step, 0], ArrowUp: [0, -step], ArrowDown: [0, step] };
+          var m = moves[e.key];
+          if (!m) return;
+          e.preventDefault();
+          setPos(r.left + m[0], r.top + m[1]);
+          save();
+        });
+
+        // Keep panel on-screen when the viewport or panel size changes
+        function keepInView() {
+          if (!panel.style.left) return; // still at default CSS anchor
+          var r = panel.getBoundingClientRect();
+          setPos(r.left, r.top);
+        }
+        window.addEventListener('resize', keepInView);
+        panel.addEventListener('qo:resize', keepInView);
+
+        restore();
+      }
+
+      document.querySelectorAll('[data-draggable]').forEach(initDraggable);
+
+      /* ---------- Quick order logic ---------- */
+      var panel = document.getElementById('quick-order');
+      var form = document.getElementById('qo-form');
+      var drinkSel = document.getElementById('qo-drink');
+      var shot = document.getElementById('qo-shot');
+      var qtyOut = document.getElementById('qo-qty');
+      var addBtn = document.getElementById('qo-add');
+      var cartEl = document.getElementById('qo-cart');
+      var totalEl = document.getElementById('qo-total');
+      var badge = document.getElementById('qo-badge');
+      var checkoutBtn = document.getElementById('qo-checkout');
+      var statusEl = document.getElementById('qo-status');
+      var toggle = document.getElementById('qo-toggle');
+
+      var STORAGE_CART = 'dailyGrind.quickOrder.cart';
+      var STORAGE_COLLAPSED = 'dailyGrind.quickOrder.collapsed';
+      var SHOT_PRICE = 0.75;
+      var MAX_QTY = 10;
+      var qty = 1;
+      var cart = [];
+
+      try { cart = JSON.parse(localStorage.getItem(STORAGE_CART)) || []; } catch (e) { cart = []; }
+      if (!Array.isArray(cart)) cart = [];
+
+      function money(n) { return '$' + n.toFixed(2); }
+
+      function currentUnitPrice() {
+        var opt = drinkSel.options[drinkSel.selectedIndex];
+        var size = form.querySelector('input[name="size"]:checked');
+        return parseFloat(opt.dataset.price) + parseFloat(size.dataset.extra) + (shot.checked ? SHOT_PRICE : 0);
+      }
+
+      function updateAddLabel() {
+        qtyOut.textContent = qty;
+        addBtn.textContent = 'Add to Cart — ' + money(currentUnitPrice() * qty);
+      }
+
+      function persistCart() {
+        try { localStorage.setItem(STORAGE_CART, JSON.stringify(cart)); } catch (e) { }
+      }
+
+      function renderCart() {
+        cartEl.innerHTML = '';
+        var total = 0, count = 0;
+        if (!cart.length) {
+          var empty = document.createElement('li');
+          empty.className = 'qo-empty';
+          empty.textContent = 'Your cart is empty';
+          cartEl.appendChild(empty);
+        }
+        cart.forEach(function (item, i) {
+          var line = item.price * item.qty;
+          total += line;
+          count += item.qty;
+
+          var li = document.createElement('li');
+          var name = document.createElement('span');
+          name.className = 'qo-item-name';
+          name.textContent = item.qty + '× ' + item.name;
+          var meta = document.createElement('small');
+          meta.textContent = item.size + (item.extraShot ? ' · extra shot' : '');
+          name.appendChild(meta);
+
+          var price = document.createElement('span');
+          price.textContent = money(line);
+
+          var rm = document.createElement('button');
+          rm.type = 'button';
+          rm.className = 'qo-remove';
+          rm.setAttribute('aria-label', 'Remove ' + item.name);
+          rm.innerHTML = '&times;';
+          rm.addEventListener('click', function () {
+            cart.splice(i, 1);
+            persistCart();
+            renderCart();
+          });
+
+          li.append(name, price, rm);
+          cartEl.appendChild(li);
+        });
+        totalEl.textContent = money(total);
+        badge.textContent = count;
+        checkoutBtn.disabled = !cart.length;
+        panel.dispatchEvent(new Event('qo:resize'));
+      }
+
+      form.addEventListener('change', updateAddLabel);
+      document.getElementById('qo-dec').addEventListener('click', function () {
+        qty = Math.max(1, qty - 1); updateAddLabel();
+      });
+      document.getElementById('qo-inc').addEventListener('click', function () {
+        qty = Math.min(MAX_QTY, qty + 1); updateAddLabel();
+      });
+
+      form.addEventListener('submit', function (e) {
+        e.preventDefault();
+        var opt = drinkSel.options[drinkSel.selectedIndex];
+        var size = form.querySelector('input[name="size"]:checked').value;
+        var item = {
+          id: opt.value,
+          name: opt.textContent.split(' — ')[0],
+          size: size,
+          extraShot: shot.checked,
+          price: currentUnitPrice(),
+          qty: qty
+        };
+        var existing = cart.find(function (c) {
+          return c.id === item.id && c.size === item.size && c.extraShot === item.extraShot;
+        });
+        if (existing) existing.qty += item.qty; else cart.push(item);
+        persistCart();
+        renderCart();
+        statusEl.textContent = 'Added ' + item.qty + '× ' + item.name + '.';
+        qty = 1;
+        shot.checked = false;
+        updateAddLabel();
+      });
+
+      checkoutBtn.addEventListener('click', function () {
+        if (!cart.length) return;
+        var count = cart.reduce(function (n, c) { return n + c.qty; }, 0);
