+          ' ready for pickup in ~10 min.';
+        cart = [];
+        persistCart();
+        renderCart();
+      });
+
+      function setCollapsed(collapsed) {
+        panel.classList.toggle('is-collapsed', collapsed);
+        toggle.setAttribute('aria-expanded', String(!collapsed));
+        toggle.setAttribute('aria-label', (collapsed ? 'Expand' : 'Minimize') + ' quick order panel');
+        toggle.innerHTML = collapsed ? '+' : '&minus;';
+        try { localStorage.setItem(STORAGE_COLLAPSED, collapsed ? '1' : '0'); } catch (e) { }
+        panel.dispatchEvent(new Event('qo:resize'));
+      }
+      toggle.addEventListener('click', function () {
+        setCollapsed(!panel.classList.contains('is-collapsed'));
+      });
+
+      var startCollapsed = false;
+      try { startCollapsed = localStorage.getItem(STORAGE_COLLAPSED) === '1'; } catch (e) { }
+      setCollapsed(startCollapsed);
+      updateAddLabel();
+      renderCart();
+    })();
+  </script>
+
 </body>

 </html>

