+    const getActiveView = (root: HTMLElement) =>
+        root.querySelector<HTMLElement>(`${VIEW_SELECTOR}:not(.inactive)`);
+
+    function deactivate(view: HTMLElement) {
+        view.classList.add('inactive');
+        view.setAttribute('aria-hidden', 'true');
+        view.inert = true;
+    }
+
+    function activate(view: HTMLElement) {
+        view.classList.remove('inactive');
+        view.removeAttribute('aria-hidden');
+        view.inert = false;
+    }
+
+    function updateSectionLinks(viewId: string) {
+        for (const link of document.querySelectorAll<HTMLElement>('[data-section-link]')) {
+            if (link.dataset.sectionLink === viewId) link.setAttribute('aria-current', 'page');
+            else link.removeAttribute('aria-current');
+        }
+    }
+
+    /** Swap views. Returns false if `next` was already active. */
+    function switchTo(root: HTMLElement, next: HTMLElement): boolean {
+        const current = getActiveView(root);
+        if (current === next) return false;
+        if (current) {
+            scrollPositions.set(current.dataset.spaView!, window.scrollY);
+            deactivate(current);
+        }
+        activate(next);
+        if (next.dataset.title) document.title = next.dataset.title;
+        updateSectionLinks(next.dataset.spaView!);
+        return true;
+    }
+
+    document.addEventListener(
+        'click',
+        (ev) => {
+            if (ev.defaultPrevented || ev.button !== 0 || ev.metaKey || ev.ctrlKey || ev.shiftKey || ev.altKey) return;
+            const link = (ev.target as Element | null)?.closest?.('a[href]');
+            if (!(link instanceof HTMLAnchorElement)) return;
+            if ((link.target && link.target !== '_self') || link.hasAttribute('download') || link.hasAttribute('data-astro-reload')) return;
