+            const root = getRoot();
+            if (!root) return;
+            const url = new URL(link.href);
+            if (url.hash) return;
+            const next = findView(root, url);
+            if (!next) return;
+
+            ev.preventDefault();
+
+            if (!switchTo(root, next)) {
+                // Already on this view: behave like a normal same-page link and go to the top.
+                window.scrollTo(0, 0);
+                return;
+            }
