+            // Persist the current scroll position on the entry we are leaving, then push the new one.
+            const state = history.state ?? {};
+            history.replaceState({ ...state, scrollX: window.scrollX, scrollY: window.scrollY }, '');
+            const top = scrollPositions.get(next.dataset.spaView!) ?? 0;
+            history.pushState({ index: (state.index ?? 0) + 1, scrollX: 0, scrollY: top }, '', url);
+
+            window.scrollTo(0, top);
+            next.focus({ preventScroll: true });
+        },
+        { capture: true },
+    );
+
+    window.addEventListener(
+        'popstate',
+        (ev) => {
+            const root = getRoot();
+            if (!root) return; // Not on an SPA page: let the ClientRouter handle it.
+            const next = findView(root, new URL(location.href));
+            if (!next || getActiveView(root) === next) return; // Different page or hash change.
