+            // Handled locally: don't let the ClientRouter refetch and rebuild the page.
+            ev.stopImmediatePropagation();
+            switchTo(root, next);
+            const state = history.state;
+            window.scrollTo(state?.scrollX ?? 0, state?.scrollY ?? scrollPositions.get(next.dataset.spaView!) ?? 0);
+        },
+        { capture: true },
+    );
+
+    // Scroll memory belongs to the DOM it was recorded on; drop it when the ClientRouter swaps pages.
+    document.addEventListener('astro:after-swap', () => scrollPositions.clear());
+</script>
