+}
+
+/* ---------- Native modal dialogs (search, reading list) ---------- */
+.site-dialog {
+  inline-size: min(calc(100% - 2rem), 42rem);
+  margin: 15dvh auto auto;
+  background: #fff;
+  box-shadow: 0 20px 25px -5px rgb(0 0 0 / 0.1), 0 8px 10px -6px rgb(0 0 0 / 0.1);
+}
+
+/* Without these, scrolling inside the dialog or over the backdrop scrolls the page behind it */
+dialog:modal {
+  overscroll-behavior: contain;
+}
+
+dialog::backdrop {
+  overflow: hidden;
+  overscroll-behavior: contain;
+  background-color: rgb(255 255 255 / 0.3);
+  backdrop-filter: blur(4px);
+}
+
+/* ---------- Section mega menu (popover="auto"), anchored to the section bar ---------- */
+.section-bar {
+  anchor-name: --section-bar;
+}
+
+.mega-menu {
+  position: absolute;
+  inset: auto;
+  margin: 0;
+  /* Fallback values (set from script) come first; browsers without anchor() keep them */
+  top: var(--mega-top, 0);
+  top: anchor(--section-bar bottom);
+  left: var(--mega-left, 0);
+  left: anchor(--section-bar left);
+  width: var(--mega-width, 100%);
+  width: anchor-size(--section-bar width);
+  max-height: 80dvh;
+  overflow: auto;
+}
+
+/* ---------- Skip link ---------- */
+.skip-link {
+  position: absolute;
+  inset-inline-start: 1rem;
+  inset-block-start: -100%;
+  z-index: 100;
+  padding: 0.5rem 1rem;
+  background: #111827;
+  color: #fff;
+  font-weight: 600;
+}
+
+.skip-link:focus-visible {
