+import { useEffect, useRef } from 'react';
+
+/**
+ * Load the Popover API polyfill only in browsers that lack native support.
+ * Popover is Baseline "newly available", so older browsers still need it.
+ */
+export function ensurePopoverSupport() {
+  if (typeof HTMLElement === 'undefined') return;
+  if (!Object.hasOwn(HTMLElement.prototype, 'popover')) {
+    import('@oddbird/popover-polyfill');
+  }
+}
+
+/** True when the pointer event happened outside the element's border box. */
+function isOutside(event: PointerEvent, el: HTMLElement) {
+  const r = el.getBoundingClientRect();
+  return event.clientX < r.left || event.clientX > r.right || event.clientY < r.top || event.clientY > r.bottom;
+}
+
+/**
+ * Drive a native modal <dialog> from React state.
+ *
+ * - Opens with showModal() (top layer, inert page, focus containment, Esc).
+ * - Reports every close (Esc, backdrop click, close button, form method="dialog")
+ *   through `onClose`, so React state stays in sync.
+ * - Polyfills `closedby="any"` light dismiss where it is not supported.
+ * - Focus returns to the invoking button natively when the dialog closes.
+ */
+export function useModalDialog(isOpen: boolean, onClose: () => void, onOpen?: (dialog: HTMLDialogElement) => void) {
+  const ref = useRef<HTMLDialogElement>(null);
+  const onCloseRef = useRef(onClose);
+  onCloseRef.current = onClose;
+
+  useEffect(() => {
+    const dialog = ref.current;
+    if (!dialog) return;
+
+    const handleClose = () => onCloseRef.current();
+    dialog.addEventListener('close', handleClose);
+
+    // Fallback for browsers without <dialog closedby> (light dismiss).
+    let pressedOutside = false;
+    const handleDown = (e: PointerEvent) => { pressedOutside = isOutside(e, dialog); };
+    const handleUp = (e: PointerEvent) => {
+      // Require press and release outside so a text-selection drag doesn't dismiss.
+      if (pressedOutside && isOutside(e, dialog)) dialog.close();
+    };
+    const needsLightDismissFallback = !('closedBy' in HTMLDialogElement.prototype);
+    if (needsLightDismissFallback) {
+      dialog.addEventListener('pointerdown', handleDown);
+      dialog.addEventListener('pointerup', handleUp);
+    }
+
+    return () => {
+      dialog.removeEventListener('close', handleClose);
+      if (needsLightDismissFallback) {
+        dialog.removeEventListener('pointerdown', handleDown);
+        dialog.removeEventListener('pointerup', handleUp);
+      }
+    };
+  }, []);
+
+  useEffect(() => {
+    const dialog = ref.current;
+    if (!dialog) return;
+    if (isOpen && !dialog.open) {
+      dialog.showModal();
+      onOpen?.(dialog);
+    } else if (!isOpen && dialog.open) {
+      dialog.close();
+    }
+  }, [isOpen]);
+
+  return ref;
+}

