diff --git a/src/components/useModalDialog.ts b/src/components/useModalDialog.ts
new file mode 100644
index 0000000..fff5062
--- /dev/null
+++ b/src/components/useModalDialog.ts
@@ -0,0 +1,39 @@
+import { useEffect, useRef } from 'react';
+
+/**
+ * Drives a native <dialog> as a modal from a React `open` flag.
+ *
+ * - `showModal()` puts the dialog in the top layer, makes the rest of the page
+ *   inert, traps focus and handles Esc natively.
+ * - Closing via `close()` lets the browser restore focus to the invoking control.
+ * - Clicks on the ::backdrop (i.e. directly on the <dialog> element) close it.
+ */
+export function useModalDialog(open: boolean, onClose: () => void) {
+  const dialogRef = useRef<HTMLDialogElement>(null);
+  const onCloseRef = useRef(onClose);
+  onCloseRef.current = onClose;
+
+  useEffect(() => {
+    const dialog = dialogRef.current;
+    if (!dialog) return;
+    if (open && !dialog.open) dialog.showModal();
+    if (!open && dialog.open) dialog.close();
+  }, [open]);
+
+  useEffect(() => {
+    const dialog = dialogRef.current;
+    if (!dialog) return;
+    const handleClose = () => onCloseRef.current();
+    const handleClick = (event: MouseEvent) => {
+      if (event.target === dialog) dialog.close();
+    };
+    dialog.addEventListener('close', handleClose);
+    dialog.addEventListener('click', handleClick);
+    return () => {
+      dialog.removeEventListener('close', handleClose);
+      dialog.removeEventListener('click', handleClick);
+    };
+  }, []);
+
+  return dialogRef;
+}
