@@ -0,0 +1,26 @@
+// Minimal service worker so The Daily Grind meets browser installability criteria.
+// Network-first: always try the network, fall back to a cached copy of the home page when offline.
+const CACHE = 'daily-grind-v1';
+const OFFLINE_URLS = ['/', '/index.html', '/manifest.webmanifest', '/icon.svg'];
+
+self.addEventListener('install', (event) => {
+  event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(OFFLINE_URLS)).then(() => self.skipWaiting()));
+});
+
+self.addEventListener('activate', (event) => {
+  event.waitUntil(
+    caches.keys()
+      .then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k))))
+      .then(() => self.clients.claim())
+  );
+});
+
+self.addEventListener('fetch', (event) => {
+  const { request } = event;
+  if (request.method !== 'GET' || new URL(request.url).origin !== self.location.origin) return;
+  event.respondWith(
+    fetch(request).catch(() =>
+      caches.match(request).then((res) => res || (request.mode === 'navigate' ? caches.match('/') : Response.error()))
+    )
+  );
+});

