+        hideButton();
+        setStatus('The Daily Grind app is installed. Enjoy!');
+      });
+
+      installBtn.addEventListener('click', async () => {
+        installBtn.disabled = true;
+        try {
+          if (typeof navigator.install === 'function') {
+            await navigator.install();
+            hideButton();
+            setStatus('The Daily Grind app is installed. Enjoy!');
+          } else if (deferredPrompt) {
+            deferredPrompt.prompt();
+            const { outcome } = await deferredPrompt.userChoice;
+            deferredPrompt = null; // The prompt can only be used once.
+            if (outcome === 'accepted') {
+              hideButton();
+            } else {
+              hideButton(); // Browser will fire beforeinstallprompt again if re-offering is allowed.
+              setStatus('No problem. You can install the app any time from your browser menu.');
+            }
+          }
+        } catch (err) {
+          // AbortError = user dismissed the dialog; other errors mean install isn't possible right now.
+          setStatus(err && err.name === 'AbortError'
+            ? 'Installation cancelled.'
+            : 'Installation isn\u2019t available right now. Try your browser menu instead.');
+          console.warn('App install failed:', err);
+        } finally {
+          installBtn.disabled = false;
+        }
+      });
+    })();
+  </script>
+
