+/**
+ * Daily Grind — client-side interaction paint monitoring.
+ *
+ * Measures how long it takes, from the moment the user interacts, until the
+ * resulting visual update is painted on screen for:
+ *   - clicks on the navigation bar          (data-perf-region="nav")
+ *   - the "Order Now" hero button           (data-perf-region="order-now")
+ *   - the "Seasonal Favorites" cards        (data-perf-region="seasonal-card")
+ *   - client-side view switches (soft navigations), wherever they originate
+ *
+ * Metrics per interaction:
+ *   - nextPaint:        input → very next frame (Event Timing / INP-style).
+ *                       Widely supported; used as the fallback signal.
+ *   - contentfulPaint:  input → largest contentful paint caused by the
+ *                       interaction, including async work (fetch, await,
+ *                       timers). Uses `interaction-contentful-paint`.
+ *   - viewSwitch:       FCP/LCP for SPA soft navigations (`soft-navigation`).
+ *
+ * The newer entry types are progressive enhancements: they are feature-detected
+ * and simply skipped in browsers that don't support them.
+ *
+ * Results are batched and sent with navigator.sendBeacon() when the page is
+ * hidden or unloaded. They're also dispatched as a `dailygrind:perf` event on
+ * window (for other analytics code to pick up) and logged to the console
+ * when the URL contains `?perfdebug`.
+ */
+
+const ENDPOINT = '/analytics/perf';
+const TRACKED_REGIONS = new Set(['nav', 'order-now', 'seasonal-card']);
+const DEBUG = new URLSearchParams(location.search).has('perfdebug');
+// How far apart (ms) an input event timestamp and a performance entry
+// startTime may be and still be treated as the same interaction.
+const MATCH_TOLERANCE_MS = 100;
+const MAX_RECENT_INPUTS = 20;
+const MAX_PENDING_RECORDS = 200;
+
+const supports = (type) =>
+  typeof PerformanceObserver !== 'undefined' &&
+  PerformanceObserver.supportedEntryTypes?.includes(type);
+
+/* ------------------------------------------------------------------ */
+/* Region attribution                                                  */
+/* ------------------------------------------------------------------ */
+
+function describeTarget(target) {
+  const el = target instanceof Element ? target : null;
+  const regionEl = el?.closest('[data-perf-region]');
+  if (!regionEl) return { region: 'other', label: null };
+
+  const region = regionEl.dataset.perfRegion;
+  let label = null;
+  if (region === 'seasonal-card') {
+    label = regionEl.querySelector('h3')?.textContent.trim() ?? null;
+  } else {
+    label = (el.closest('a, button') ?? regionEl).textContent.trim().slice(0, 60);
+  }
+  return { region, label };
+}
+
+// Capture-phase listeners remember recent inputs and the region they hit.
+// This lets us attribute entries even when the Event Timing entry for the
+// interaction was below the reporting threshold or its target was detached.
+const recentInputs = [];
+function rememberInput(event) {
+  if (!event.isTrusted) return;
+  recentInputs.push({ time: event.timeStamp, ...describeTarget(event.target) });
+  if (recentInputs.length > MAX_RECENT_INPUTS) recentInputs.shift();
+}
+for (const type of ['pointerdown', 'keydown', 'click']) {
+  addEventListener(type, rememberInput, { capture: true, passive: true });
+}
+
+function regionFromRecentInputs(startTime) {
+  let best = null;
+  let bestDelta = Infinity;
+  for (const input of recentInputs) {
+    const delta = Math.abs(input.time - startTime);
+    if (delta < bestDelta) {
+      best = input;
+      bestDelta = delta;
+    }
+  }
+  return bestDelta <= MATCH_TOLERANCE_MS ? best : null;
+}
+
+/* ------------------------------------------------------------------ */
+/* Per-interaction records (keyed by interactionId)                    */
+/* ------------------------------------------------------------------ */
+
+/** @type {Map<number, object>} */
+const records = new Map();
+const reportedIds = new Set();
+const outbox = [];
+
+function getRecord(interactionId, startTime) {
+  if (reportedIds.has(interactionId)) return null;
+  let record = records.get(interactionId);
+  if (!record) {
+    if (records.size >= MAX_PENDING_RECORDS) finalizeAll();
+    record = {
+      interactionId,
+      startTime: Math.round(startTime),
+      region: null,
+      label: null,
+      eventType: null,
+      nextPaint: null,
+      contentfulPaint: null,
+      lcpElement: null,
+      lcpSize: null,
+      viewSwitch: null,
+    };
+    records.set(interactionId, record);
+  }
+  return record;
+}
+
+function attribute(record, target) {
+  if (record.region && record.region !== 'other') return;
+  const fromTarget = target ? describeTarget(target) : null;
+  const resolved =
+    fromTarget && fromTarget.region !== 'other'
+      ? fromTarget
+      : regionFromRecentInputs(record.startTime) ?? fromTarget;
+  if (resolved) {
+    record.region = resolved.region;
+    record.label = resolved.label;
+  }
+}
+
+function describeElement(el) {
+  if (!(el instanceof Element)) return null;
+  let s = el.tagName.toLowerCase();
+  if (el.id) s += `#${el.id}`;
+  if (el.classList.length) s += `.${[...el.classList].join('.')}`;
+  return s;
+}
+
+/* ------------------------------------------------------------------ */
+/* Observers                                                           */
+/* ------------------------------------------------------------------ */
+
+const observers = [];
+
+// 1. Event Timing: input → next paint. Also gives the interaction's target.
+if (supports('event')) {
+  const eventObserver = new PerformanceObserver((list) => handleEventEntries(list.getEntries()));
+  eventObserver.observe({ type: 'event', durationThreshold: 16, buffered: true });
+  observers.push([eventObserver, handleEventEntries]);
+}
+function handleEventEntries(entries) {
+  for (const entry of entries) {
+    if (!entry.interactionId) continue;
+    const record = getRecord(entry.interactionId, entry.startTime);
+    if (!record) continue;
+    record.startTime = Math.min(record.startTime, Math.round(entry.startTime));
+    attribute(record, entry.target);
+    if (record.nextPaint === null || entry.duration > record.nextPaint) {
+      record.nextPaint = Math.round(entry.duration);
+      record.eventType = entry.name;
+    }
+  }
+}
+
+// 2. Interaction Contentful Paint: input → (progressively larger) contentful
+//    paints caused by the interaction, including async updates.
+if (supports('interaction-contentful-paint')) {
+  const icpObserver = new PerformanceObserver((list) => handleIcpEntries(list.getEntries()));
+  icpObserver.observe({ type: 'interaction-contentful-paint', buffered: true });
+  observers.push([icpObserver, handleIcpEntries]);
+}
+function handleIcpEntries(entries) {
+  for (const entry of entries) {
+    applyIcpEntry(entry);
+  }
+}
+function applyIcpEntry(entry) {
+  if (!entry?.interactionId) return;
+  const record = getRecord(entry.interactionId, entry.startTime);
+  if (!record) return;
+  attribute(record, null);
+  // entry.duration === presentationTime - startTime (interaction start).
+  // Entries are emitted in increasing size order, so the latest one wins.
+  record.contentfulPaint = Math.round(entry.duration);
+  const lcp = entry.largestContentfulPaint;
+  record.lcpElement = describeElement(lcp?.element) ?? record.lcpElement;
+  record.lcpSize = lcp?.size ?? record.lcpSize;
+  if (record.viewSwitch) record.viewSwitch.lcp = record.contentfulPaint;
+}
+
+// 3. Soft navigations: client-side view switches.
+//    ICP entries are correlated by interactionId (not navigationId) because
+//    records are keyed by interactionId, which also picks up paints that
+//    happened before the URL was updated.
+if (supports('soft-navigation') && supports('interaction-contentful-paint')) {
+  const softNavObserver = new PerformanceObserver((list) => handleSoftNavEntries(list.getEntries()));
+  softNavObserver.observe({ type: 'soft-navigation', buffered: true });
+  observers.push([softNavObserver, handleSoftNavEntries]);
+}
+function handleSoftNavEntries(entries) {
+  for (const entry of entries) {
+    const record = getRecord(entry.interactionId, entry.startTime);
+    if (!record) continue;
+    attribute(record, null);
+    record.viewSwitch = {
+      url: entry.name,
+      navigationId: entry.navigationId,
+      // duration === presentationTime - startTime → soft-nav FCP.
+      fcp: Math.round(entry.duration),
+      lcp: record.contentfulPaint,
+    };
+    // Seed with paints that occurred before the URL changed.
+    applyIcpEntry(entry.getLargestInteractionContentfulPaint?.());
+  }
+}
+
+/* ------------------------------------------------------------------ */
+/* Reporting                                                           */
+/* ------------------------------------------------------------------ */
+
+function shouldReport(record) {
+  // View switches are reported wherever they were triggered from; other
+  // interactions only for the tracked homepage regions.
+  return record.viewSwitch !== null || TRACKED_REGIONS.has(record.region);
+}
+
+function finalizeAll() {
+  for (const record of records.values()) {
+    reportedIds.add(record.interactionId);
+    if (!shouldReport(record)) continue;
+    const metric = {
+      type: record.viewSwitch ? 'view-switch' : 'interaction',
+      page: location.pathname,
+      ...record,
+    };
+    outbox.push(metric);
+    dispatchEvent(new CustomEvent('dailygrind:perf', { detail: metric }));
+    if (DEBUG) console.debug('[perf]', metric);
+  }
+  records.clear();
+}
+
+function flush() {
+  // Pull any entries the observers haven't delivered yet (important when the
+  // click triggered a full page navigation and we're about to unload).
+  for (const [observer, handler] of observers) handler(observer.takeRecords());
+  finalizeAll();
+  if (!outbox.length) return;
+
+  const body = JSON.stringify({ sentAt: Date.now(), metrics: outbox.splice(0) });
+  const sent =
+    typeof navigator.sendBeacon === 'function' &&
+    navigator.sendBeacon(ENDPOINT, new Blob([body], { type: 'application/json' }));
+  if (!sent) {
+    fetch(ENDPOINT, { method: 'POST', body, keepalive: true, headers: { 'Content-Type': 'application/json' } })
+      .catch(() => {});
+  }
+}
+
+addEventListener('visibilitychange', () => {
+  if (document.visibilityState === 'hidden') flush();
+});
+addEventListener('pagehide', flush);
+
+// Exposed for debugging / integration with other analytics code.
+window.dailyGrindPerf = { flush, pending: records, outbox };

