+/**
+ * Daily Grind client-side interaction performance monitor.
+ *
+ * Measures how long it takes from a user interaction (or a client-side view
+ * switch) until the browser has painted the resulting visual update.
+ *
+ * Tracked interactions:
+ *   - Clicks on elements carrying a `data-perf-track="<name>"` attribute
+ *     (navigation bar links, the "Order Now" button, Seasonal Favorites cards).
+ *   - Client-side view switches: history.pushState / replaceState, popstate,
+ *     hashchange, and explicit calls to `DailyGrindPerf.trackViewSwitch()`.
+ *
+ * Measurement strategy:
+ *   1. Event Timing API (Chromium/Firefox): for clicks, the browser reports the
+ *      exact time from input to next paint, broken down into input delay,
+ *      processing time and presentation delay.
+ *   2. Fallback (all browsers, and for view switches / fast clicks below the
+ *      Event Timing reporting threshold): requestAnimationFrame followed by a
+ *      MessageChannel task, which runs right after the frame containing the
+ *      update has been handed off for painting.
+ *   3. Clicks that trigger a full-page navigation are handed over via
+ *      sessionStorage and completed on the next page's first contentful paint
+ *      (when that page also loads this script).
+ *
+ * Results are:
+ *   - recorded as `performance.measure()` entries (visible in DevTools),
+ *   - dispatched as a `dailygrind:perf` CustomEvent on `window`,
+ *   - kept in `DailyGrindPerf.entries`,
+ *   - optionally batched to a collection endpoint via `navigator.sendBeacon`
+ *     when `data-endpoint` is set on the <script> tag.
+ *
+ * Script tag options:
+ *   data-endpoint="/path"   POST batched metrics as JSON to this URL.
+ *   data-debug              Log each metric to the console.
+ *   data-sample-rate="0.5"  Fraction of page views to monitor (default 1).
+ */
+(function () {
+  'use strict';
+
+  if (typeof window === 'undefined' || !window.performance || window.DailyGrindPerf) return;
+
+  var script = document.currentScript;
+  var config = {
+    endpoint: (script && script.getAttribute('data-endpoint')) || null,
+    debug: !!(script && script.hasAttribute('data-debug')),
+    sampleRate: parseFloat((script && script.getAttribute('data-sample-rate')) || '1'),
+  };
+  if (isNaN(config.sampleRate)) config.sampleRate = 1;
+
+  var sampled = Math.random() < config.sampleRate;
+
+  var STORAGE_KEY = 'dailygrind:perf:pending-nav';
+  var EVENT_TIMING_WAIT_MS = 1000; // max wait for Event Timing entry after paint
+  var NAV_HANDOFF_MAX_AGE_MS = 30000;
+  var MAX_QUEUE = 50;
+
+  var entries = [];
+  var queue = [];
+  var pendingClicks = []; // clicks awaiting their Event Timing entry
+  var seq = 0;
+  var lastInteraction = null; // most recent tracked click, for view-switch attribution
+  var lastView = location.pathname + location.search + location.hash;
+
+  var supportsEventTiming =
+    typeof PerformanceObserver !== 'undefined' &&
+    PerformanceObserver.supportedEntryTypes &&
+    PerformanceObserver.supportedEntryTypes.indexOf('event') !== -1;
+
+  // ---------------------------------------------------------------------------
+  // Helpers
+  // ---------------------------------------------------------------------------
+
+  function now() {
+    return performance.now();
+  }
+
+  function round(n) {
+    return typeof n === 'number' ? Math.round(n * 10) / 10 : n;
+  }
+
+  /**
+   * Invoke `cb(paintTime)` once the next frame has been painted.
+   * rAF runs just before style/layout/paint; a task posted from inside rAF
+   * runs after that frame has been produced.
+   */
+  var afterNextPaint = (function () {
+    var channel = typeof MessageChannel !== 'undefined' ? new MessageChannel() : null;
+    var callbacks = [];
+    if (channel) {
+      channel.port1.onmessage = function () {
+        var t = now();
+        var cbs = callbacks;
+        callbacks = [];
+        for (var i = 0; i < cbs.length; i++) cbs[i](t);
+      };
+    }
+    return function (cb) {
+      // Pages in background tabs don't paint; rAF won't fire until visible.
+      requestAnimationFrame(function () {
+        if (channel) {
+          callbacks.push(cb);
+          channel.port2.postMessage(null);
+        } else {
+          setTimeout(function () { cb(now()); }, 0);
+        }
+      });
+    };
+  })();
+
+  function describeTarget(el) {
+    if (!el) return null;
+    var text = (el.getAttribute('aria-label') || el.textContent || '').replace(/\s+/g, ' ').trim();
+    return {
+      tag: el.tagName.toLowerCase(),
+      text: text.slice(0, 60),
+      href: el.getAttribute('href') || null,
+    };
+  }
+
+  function currentView() {
+    return location.pathname + location.search + location.hash;
+  }
+
+  // ---------------------------------------------------------------------------
+  // Reporting
+  // ---------------------------------------------------------------------------
+
+  function record(metric) {
+    metric.id = metric.id || 'dg-' + Date.now().toString(36) + '-' + (++seq);
+    metric.page = location.pathname;
+    metric.duration = round(metric.duration);
+    if (metric.breakdown) {
+      for (var k in metric.breakdown) metric.breakdown[k] = round(metric.breakdown[k]);
+    }
