+    if (typeof metric.startTime === 'number' && metric.endTime >= metric.startTime) {
+      try {
+        performance.measure('dg:' + metric.type + ':' + metric.name, {
+          start: metric.startTime,
+          end: metric.endTime,
+          detail: metric,
+        });
+      } catch (e) { /* older browsers without measure options */ }
+    }
