+    try {
+      window.dispatchEvent(new CustomEvent('dailygrind:perf', { detail: metric }));
+    } catch (e) { /* ignore */ }
+
+    if (config.debug && window.console) {
+      console.log('[DailyGrindPerf] ' + metric.type + ' "' + metric.name + '" painted in ' +
+        metric.duration + 'ms (' + metric.source + ')', metric);
