+
+/** Move with animation: record rect → move → FLIP. */
+function animatedMove(card, list, ref) {
+  const from = card.getBoundingClientRect();
+  moveCard(card, list, ref);
+  flyIn(card, from);
+}
+
+/* ---------------- Buttons & keyboard ---------------- */
+
+board.addEventListener('click', (event) => {
+  const btn = event.target.closest('.card-btn');
+  if (!btn) return;
+  const card = btn.closest('.card');
+  const status = statusOf(card);
+  const idx = STATUSES.indexOf(status);
+
+  if (btn.dataset.action === 'forward') {
+    if (status === 'ready') return removeCard(card);
+    animatedMove(card, columns[STATUSES[idx + 1]].list, null);
+  } else if (btn.dataset.action === 'back') {
+    animatedMove(card, columns[STATUSES[idx - 1]].list, null);
+  }
+  announce(`${orderName(card)} moved to ${describePosition(card)}.`);
+});
+
+board.addEventListener('keydown', (event) => {
+  const handle = event.target.closest?.('.card-handle');
+  if (!handle || !event.altKey || drag) return;
+  const card = handle.closest('.card');
+  const status = statusOf(card);
+  const idx = STATUSES.indexOf(status);
+  const cards = cardsIn(columns[status].list);
+  const pos = cards.indexOf(card);
+  const rtl = getComputedStyle(board).direction === 'rtl';
+
+  let step = null;
+  switch (event.key) {
+    case 'ArrowUp':
+      if (pos > 0) step = () => animatedMove(card, columns[status].list, cards[pos - 1]);
+      break;
+    case 'ArrowDown':
+      if (pos < cards.length - 1) step = () => animatedMove(card, columns[status].list, cards[pos + 2] ?? null);
+      break;
+    case 'ArrowLeft':
+    case 'ArrowRight': {
+      const dir = (event.key === 'ArrowRight') !== rtl ? 1 : -1;
+      const target = STATUSES[idx + dir];
+      if (target) step = () => animatedMove(card, columns[target].list, null);
+      break;
+    }
+    default:
+      return;
+  }
+  event.preventDefault();
+  if (!step) return;
+  step();
+  handle.focus({ preventScroll: true });
+  announce(`${orderName(card)} moved to ${describePosition(card)}.`);
+});
+
+// Reveal the whole card (not just the grip) when keyboard focus enters it.
+board.addEventListener('focusin', (event) => {
+  const card = event.target.closest?.('.card-list > .card');
+  if (!card || !event.target.matches(':focus-visible') || card.getAnimations().length) return;
+  card.scrollIntoView({ block: 'nearest', inline: 'nearest' });
+});
+
+/* ---------------- Pointer dragging ---------------- */
+
+let drag = null;
+
+board.addEventListener('pointerdown', (event) => {
+  const handle = event.target.closest('.card-handle');
+  if (!handle || drag || event.button !== 0 || !event.isPrimary) return;
+  const card = handle.closest('.card');
+  if (!card.closest('.card-list')) return;
