+  handle.setPointerCapture(event.pointerId);
+  const rect = card.getBoundingClientRect();
+  drag = {
+    pointerId: event.pointerId,
+    card,
+    handle,
+    ghost: null,
+    started: false,
+    startX: event.clientX,
+    startY: event.clientY,
+    offsetX: event.clientX - rect.left,
+    offsetY: event.clientY - rect.top,
+    x: event.clientX,
+    y: event.clientY,
+    targetList: null,
+    ref: null,
+    noop: true,
+    raf: 0,
+    lastFrame: 0,
+  };
+});
+
+function startDrag() {
+  const { card } = drag;
+  drag.started = true;
+  card.getAnimations().forEach((a) => a.finish());
+  if (card._flight) {
+    card._flight.remove();
+    card._flight = null;
+    card.classList.remove('is-flying');
+  }
+  drag.ghost = makeGhost(card, card.getBoundingClientRect());
+  card.classList.add('is-dragging');
+  document.documentElement.classList.add('is-board-dragging');
+  drag.raf = requestAnimationFrame(autoScroll);
+}
+
+document.addEventListener('pointermove', (event) => {
+  if (!drag || event.pointerId !== drag.pointerId) return;
+  drag.x = event.clientX;
+  drag.y = event.clientY;
+  if (!drag.started) {
+    if (Math.hypot(drag.x - drag.startX, drag.y - drag.startY) < DRAG_THRESHOLD) return;
+    startDrag();
+  }
+  positionGhost();
+  updateDropTarget();
+});
+
+function positionGhost() {
+  drag.ghost.style.translate = `${drag.x - drag.offsetX}px ${drag.y - drag.offsetY}px`;
+}
+
+/** Columns are separate containers, so hit-test to find the column, then use layout midpoints within it. */
+function updateDropTarget() {
+  const hit = document.elementFromPoint(drag.x, drag.y);
+  const column = hit?.closest('.board-column');
+  const list = column?.querySelector('.card-list') ?? null;
+
+  if (drag.targetList && drag.targetList !== list) clearMarker(drag.targetList);
+  drag.targetList = list;
+  if (!list) {
+    drag.noop = true;
+    return;
+  }
+
+  const lr = list.getBoundingClientRect();
+  const y = Math.min(Math.max(drag.y, lr.top), lr.bottom) - lr.top - list.clientTop + list.scrollTop;
+  const others = cardsIn(list).filter((c) => c !== drag.card);
+  const ref = others.find((c) => c.offsetTop + c.offsetHeight / 2 > y) ?? null;
+  drag.ref = ref;
+
+  const currentNext = nextCard(drag.card);
+  drag.noop = list === drag.card.parentElement && ref === currentNext;
