+  const gap = parseFloat(getComputedStyle(list).rowGap) || 0;
+  let markerY;
+  if (ref) {
+    markerY = ref.offsetTop - gap / 2;
+  } else if (others.length) {
+    const last = others[others.length - 1];
+    markerY = last.offsetTop + last.offsetHeight + gap / 2;
+  } else {
+    markerY = parseFloat(getComputedStyle(list).paddingTop) / 2 + 2;
+  }
