+/** Scroll the hovered column list, and the page, while the pointer is near an edge. */
+function autoScroll(now) {
+  if (!drag?.started) return;
+  const dt = drag.lastFrame ? Math.min(now - drag.lastFrame, 50) : 16;
+  drag.lastFrame = now;
+  let scrolled = false;
+  const maxSpeed = 0.9; // px per ms
