+  const speedFor = (pos, start, end, zone) => {
+    if (pos < start + zone) return -Math.min(1.5, (start + zone - pos) / zone);
+    if (pos > end - zone) return Math.min(1.5, (pos - (end - zone)) / zone);
+    return 0;
+  };
