+  const vZone = Math.min(80, innerHeight / 4);
+  const pv = speedFor(drag.y, 0, innerHeight, vZone);
+  if (pv) {
+    const before = scrollY;
+    scrollBy(0, pv * maxSpeed * dt);
+    scrolled ||= scrollY !== before;
+  }
