+document.addEventListener('pointerup', (event) => {
+  if (!drag || event.pointerId !== drag.pointerId) return;
+  const d = endDrag();
+  if (!d.started) return;
+  const ghostRect = d.ghost.getBoundingClientRect();
+  // Rect includes scale; recover the unscaled top-left for the animation start.
+  const from = unscaledRect(d.ghost, ghostRect);
+
+  if (d.targetList && !d.noop) {
+    moveCard(d.card, d.targetList, d.ref);
+    flyIn(d.card, from, d.ghost, 1.03);
+    announce(`${orderName(d.card)} moved to ${describePosition(d.card)}.`);
+  } else {
+    flyIn(d.card, from, d.ghost, 1.03);
+  }
+});
+
+document.addEventListener('pointercancel', (event) => {
+  if (drag && event.pointerId === drag.pointerId) cancelDrag(false);
+});
+
+board.addEventListener('lostpointercapture', (event) => {
+  if (drag && event.pointerId === drag.pointerId && !drag.handle.hasPointerCapture(event.pointerId)) {
+    cancelDrag(false);
+  }
