+          card.tabIndex = 0;
+          card.dataset.id = order.id;
+          card.setAttribute('aria-label', order.size + ' ' + order.drink + ' for ' + order.customer + ', ' + meta.title);
+
+          const top = document.createElement('div');
+          top.className = 'card-top';
+          const drink = document.createElement('span');
+          drink.className = 'card-drink';
+          drink.textContent = order.drink;
+          const id = document.createElement('span');
+          id.className = 'card-id';
+          id.textContent = '#' + order.id;
+          top.append(drink, id);
+
+          const metaEl = document.createElement('div');
+          metaEl.className = 'card-meta';
+          metaEl.textContent = order.size + ' · ' + order.customer;
+
+          const actions = document.createElement('div');
+          actions.className = 'card-actions';
+          if (idx > 0) actions.append(actionBtn('←', 'back', 'Move back to ' + STATUSES[idx - 1].title));
+          if (idx < STATUS_KEYS.length - 1) {
+            actions.append(actionBtn('→', 'forward', 'Move to ' + STATUSES[idx + 1].title));
+          } else {
+            actions.append(actionBtn('Picked up', 'remove', 'Mark as picked up and remove'));
+          }
+
+          card.append(top, metaEl, actions);
+          list.append(card);
+        });
+
+        col.replaceChildren(header, list);
+      }
+
+      function actionBtn(label, action, title) {
+        const b = document.createElement('button');
+        b.type = 'button';
+        b.textContent = label;
+        b.dataset.action = action;
+        b.title = title;
+        b.setAttribute('aria-label', title);
+        b.draggable = false;
+        return b;
+      }
+
+      function renderAll() { STATUS_KEYS.forEach(renderColumn); }
+
+      function findOrder(id) { return orders.find(o => o.id === Number(id)); }
+
+      function focusCard(id) {
+        const el = board.querySelector('.card[data-id="' + id + '"]');
+        if (el) el.focus();
+      }
+
+      function moveOrder(id, toStatus, beforeId) {
+        const order = findOrder(id);
+        if (!order || !STATUS_KEYS.includes(toStatus)) return;
+        const from = order.status;
+        if (beforeId != null && Number(beforeId) === order.id) return;
+
+        orders.splice(orders.indexOf(order), 1);
+        order.status = toStatus;
+        const before = beforeId != null ? findOrder(beforeId) : null;
+        if (before && before.status === toStatus) {
+          orders.splice(orders.indexOf(before), 0, order);
+        } else {
+          orders.push(order);
+        }
+        save();
+        renderColumn(from);
+        if (toStatus !== from) renderColumn(toStatus);
+        announce(order.drink + ' for ' + order.customer + ' moved to ' + STATUSES.find(s => s.key === toStatus).title);
+      }
+
+      function step(id, delta) {
+        const order = findOrder(id);
+        if (!order) return;
+        const next = STATUS_KEYS[STATUS_KEYS.indexOf(order.status) + delta];
+        if (!next) return;
+        moveOrder(id, next);
+        focusCard(id);
+      }
+
+      function removeOrder(id) {
+        const order = findOrder(id);
+        if (!order) return;
+        orders.splice(orders.indexOf(order), 1);
+        save();
+        renderColumn(order.status);
+        announce(order.drink + ' for ' + order.customer + ' picked up');
+      }
+
+      // ---- Drag & drop (delegated so re-rendered columns need no rebinding) ----
+      let draggingId = null;
+
+      board.addEventListener('dragstart', e => {
+        const card = e.target.closest && e.target.closest('.card');
+        if (!card) return;
+        draggingId = card.dataset.id;
+        card.classList.add('dragging');
+        e.dataTransfer.effectAllowed = 'move';
+        e.dataTransfer.setData('text/plain', draggingId);
+      });
+
+      board.addEventListener('dragend', e => {
+        const card = e.target.closest && e.target.closest('.card');
+        if (card) card.classList.remove('dragging');
+        draggingId = null;
+        Object.values(columns).forEach(c => c.classList.remove('drag-over'));
+      });
+
+      board.addEventListener('dragover', e => {
+        const col = e.target.closest('.board-column');
+        if (!col) return;
+        e.preventDefault();
+        e.dataTransfer.dropEffect = 'move';
+        Object.values(columns).forEach(c => c.classList.toggle('drag-over', c === col));
+      });
+
+      board.addEventListener('dragleave', e => {
+        const col = e.target.closest('.board-column');
+        if (col && !col.contains(e.relatedTarget)) col.classList.remove('drag-over');
+      });
+
+      board.addEventListener('drop', e => {
+        const col = e.target.closest('.board-column');
+        if (!col) return;
+        e.preventDefault();
+        col.classList.remove('drag-over');
+        const id = e.dataTransfer.getData('text/plain') || draggingId;
+        if (!id) return;
+
+        // Insert before the card under the pointer (above its midpoint) if any
+        let beforeId = null;
+        const cards = Array.from(col.querySelectorAll('.card')).filter(c => c.dataset.id !== String(id));
+        for (const c of cards) {
+          const r = c.getBoundingClientRect();
+          if (e.clientY < r.top + r.height / 2) { beforeId = c.dataset.id; break; }
+        }
+        moveOrder(id, col.dataset.status, beforeId);
+        draggingId = null;
+      });
+
+      // ---- Buttons & keyboard ----
+      board.addEventListener('click', e => {
+        const btn = e.target.closest('button[data-action]');
+        if (!btn) return;
+        const id = btn.closest('.card').dataset.id;
+        if (btn.dataset.action === 'forward') step(id, 1);
+        else if (btn.dataset.action === 'back') step(id, -1);
+        else if (btn.dataset.action === 'remove') removeOrder(id);
+      });
+
+      board.addEventListener('keydown', e => {
+        const card = e.target.closest('.card');
+        if (!card || e.target !== card) return;
+        if (e.key === 'ArrowRight') { e.preventDefault(); step(card.dataset.id, 1); }
+        else if (e.key === 'ArrowLeft') { e.preventDefault(); step(card.dataset.id, -1); }
+      });
+
+      // ---- New orders ----
+      document.getElementById('order-form').addEventListener('submit', e => {
+        e.preventDefault();
+        const form = e.target;
+        const customer = form.customer.value.trim();
+        if (!customer) return;
+        const order = { id: nextId++, customer, drink: form.drink.value, size: form.size.value, status: 'queued' };
+        orders.push(order);
+        save();
+        renderColumn('queued');
+        announce('New order: ' + order.drink + ' for ' + customer);
+        form.customer.value = '';
+        form.customer.focus();
+      });
+
+      renderAll();
+    })();
+  </script>
+
 </body>

 </html>

