+/* ==========================================================================
+   Interactive 3D coffee box
+   Modes (set on .box-stage[data-mode]):
+     flat   – no JS / no 3D support: the form renders as a normal flat card
+     css3d  – fallback: CSS preserve-3d cube, faces are live DOM
+     canvas – HTML-in-Canvas: faces are drawable children of a WebGL canvas
+   ========================================================================== */
+
+.box-section {
+  --box-w: 400px;
+  --box-h: 590px;
+  --box-d: 290px;
+  --kraft: #c8a27a;
+  --kraft-dark: #a67c52;
+  --ink: #2b1d16;
+
+  display: grid;
+  grid-template-columns: minmax(0, 1fr) minmax(0, 1.3fr);
+  gap: 40px;
+  align-items: center;
+  margin-block: 20px 60px;
+}
+
+@media (max-width: 860px) {
+  .box-section {
+    grid-template-columns: 1fr;
+  }
+}
+
+.box-intro h2 {
+  color: var(--primary);
+  margin-block-end: 0.5rem;
+}
+
+.box-intro p {
+  margin-block-end: 1rem;
+}
+
+.box-controls {
+  display: flex;
+  flex-wrap: wrap;
+  align-items: center;
+  gap: 12px;
+}
+
+.box-motion-toggle {
+  font: inherit;
+  font-size: 0.95rem;
+  min-height: 44px;
+  padding: 0.5rem 1rem;
+  border: 2px solid var(--primary);
+  border-radius: 6px;
+  background: white;
+  color: var(--primary);
+  cursor: pointer;
+  transition: background-color 0.2s, color 0.2s;
+}
+
+.box-motion-toggle:hover {
+  background: var(--primary);
+  color: white;
+}
+
+.box-motion-toggle:focus-visible {
+  outline: 3px solid var(--accent);
+  outline-offset: 2px;
+}
+
+.box-hint {
+  font-size: 0.85rem;
+  color: #6d4c41;
+}
+
+/* Controls only make sense when the box actually moves */
+.box-section:has(.box-stage[data-mode="flat"]) .box-controls {
+  display: none;
+}
+
+/* --------------------------------------------------------------------------
+   Stage
+   -------------------------------------------------------------------------- */
+
+.box-stage {
+  position: relative;
+  display: grid;
+  place-items: center;
+  min-width: 0;
+}
+
+.box-stage[data-mode="css3d"] {
+  min-height: calc(var(--box-h) + 160px);
+  perspective: 1600px;
+  perspective-origin: 50% 40%;
+  touch-action: pan-y;
+  cursor: grab;
+}
+
+.box-stage[data-mode="canvas"] {
+  touch-action: pan-y;
+}
+
+.box-stage.is-dragging {
+  cursor: grabbing;
+}
+
+.box-canvas {
+  display: block;
+  width: min(100%, 620px);
+  aspect-ratio: 5 / 6;
+  cursor: grab;
+  filter: drop-shadow(0 28px 24px rgb(62 39 35 / 0.28));
+}
+
+.box-stage.is-dragging .box-canvas {
+  cursor: grabbing;
+}
+
+/* --------------------------------------------------------------------------
+   Cube (css3d mode)
+   -------------------------------------------------------------------------- */
+
+.box-cube {
+  position: relative;
+  width: var(--box-w);
+  height: var(--box-h);
+}
+
+.box-stage[data-mode="css3d"] .box-cube {
+  transform-style: preserve-3d;
+  will-change: transform;
+}
+
+@media (max-width: 480px) {
+  .box-stage[data-mode="css3d"] .box-cube {
+    scale: 0.82;
+  }
+  .box-stage[data-mode="css3d"] {
+    min-height: calc(var(--box-h) * 0.82 + 120px);
+  }
+}
+
+/* --------------------------------------------------------------------------
+   Faces (shared by all modes)
+   -------------------------------------------------------------------------- */
+
+.box-face {
+  width: var(--box-w);
+  height: var(--box-h);
+  color: var(--ink);
+  background-color: var(--kraft);
+  background-image:
+    radial-gradient(circle at 20% 15%, rgb(255 255 255 / 0.18), transparent 55%),
+    repeating-linear-gradient(
+      93deg,
+      rgb(0 0 0 / 0.025) 0 2px,
+      transparent 2px 7px
+    );
+  border: 2px solid var(--kraft-dark);
+  overflow: hidden;
+}
+
+.box-face--side {
+  width: var(--box-d);
+}
+
+.box-face--lid {
+  height: var(--box-d);
+}
+
+/* Decorative faces only exist in 3D modes */
+.box-stage[data-mode="flat"] .box-face:not(.box-face--front) {
+  display: none;
+}
+
+.box-stage[data-mode="flat"] .box-face--front {
+  max-width: 100%;
+  height: auto;
+  border-radius: 12px;
+  box-shadow: 0 10px 30px rgb(0 0 0 / 0.2);
+}
+
+.box-stage[data-mode="css3d"] .box-face {
+  position: absolute;
+  inset-block-start: 0;
+  inset-inline-start: 0;
+  backface-visibility: hidden;
+}
+
+.box-stage[data-mode="css3d"] .box-face--front {
+  transform: translateZ(calc(var(--box-d) / 2));
+}
+
+.box-stage[data-mode="css3d"] .box-face--back {
+  transform: rotateY(180deg) translateZ(calc(var(--box-d) / 2));
+}
+
+.box-stage[data-mode="css3d"] .box-face--right {
+  inset-inline-start: calc((var(--box-w) - var(--box-d)) / 2);
+  transform: rotateY(90deg) translateZ(calc(var(--box-w) / 2));
+}
+
+.box-stage[data-mode="css3d"] .box-face--left {
+  inset-inline-start: calc((var(--box-w) - var(--box-d)) / 2);
+  transform: rotateY(-90deg) translateZ(calc(var(--box-w) / 2));
+}
+
+.box-stage[data-mode="css3d"] .box-face--top {
+  inset-block-start: calc((var(--box-h) - var(--box-d)) / 2);
+  transform: rotateX(90deg) translateZ(calc(var(--box-h) / 2));
+}
+
+.box-stage[data-mode="css3d"] .box-face--bottom {
+  inset-block-start: calc((var(--box-h) - var(--box-d)) / 2);
+  transform: rotateX(-90deg) translateZ(calc(var(--box-h) / 2));
+}
+
+/* Simple baked shading so the CSS cube reads as a solid object */
+.box-stage[data-mode="css3d"] .box-face--right,
+.box-stage[data-mode="css3d"] .box-face--left {
+  filter: brightness(0.82);
+}
+
+.box-stage[data-mode="css3d"] .box-face--top {
+  filter: brightness(1.08);
+}
+
+.box-stage[data-mode="css3d"] .box-face--bottom {
+  filter: brightness(0.6);
+}
+
+/* In canvas mode the faces are only painted into textures; decorative faces
+   must never intercept input. */
+.box-stage[data-mode="canvas"] .box-face[aria-hidden="true"] {
+  pointer-events: none;
+}
+
+/* --------------------------------------------------------------------------
+   Decorative face artwork
+   -------------------------------------------------------------------------- */
+
+.face-art {
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  justify-content: center;
+  gap: 14px;
+  height: 100%;
+  padding: 24px;
+  text-align: center;
+}
+
+.face-brand {
+  font-weight: 800;
+  letter-spacing: 0.18em;
+  text-transform: uppercase;
+  color: var(--primary);
+}
+
+.box-face--side .face-art {
+  writing-mode: vertical-rl;
+  background:
+    linear-gradient(90deg, transparent 0 14%, var(--primary) 14% 18%, transparent 18% 82%, var(--primary) 82% 86%, transparent 86%);
+}
+
+.box-face--side .face-brand {
+  font-size: 2.2rem;
+}
+
+.box-face--side .face-tag {
+  font-size: 1rem;
+  letter-spacing: 0.3em;
+  text-transform: uppercase;
+}
+
+.face-stamp {
+  display: grid;
+  place-items: center;
+  width: 150px;
+  aspect-ratio: 1;
+  border: 4px double var(--primary);
+  border-radius: 50%;
+  font-weight: 800;
+  line-height: 1.2;
+  letter-spacing: 0.12em;
+  text-transform: uppercase;
+  color: var(--primary);
+  rotate: -12deg;
+}
+
+.box-face--back .face-art {
+  justify-content: space-between;
+  text-align: start;
+  align-items: stretch;
+}
+
+.box-face--back h3 {
+  font-size: 1.6rem;
+  color: var(--primary);
+}
+
+.box-face--back ul {
+  list-style: none;
+  display: grid;
+  gap: 10px;
+  font-size: 1.05rem;
+}
+
+.box-face--back li::before {
+  content: "☕ ";
+}
+
+.face-barcode {
+  height: 60px;
+  width: 180px;
+  background: repeating-linear-gradient(90deg, var(--ink) 0 2px, transparent 2px 5px, var(--ink) 5px 6px, transparent 6px 9px);
+}
+
+/* --------------------------------------------------------------------------
+   Front face: the order form
+   -------------------------------------------------------------------------- */
+
+.box-form {
+  display: flex;
+  flex-direction: column;
+  gap: 12px;
+  padding: 22px 26px;
+}
+
+.box-form-head {
+  text-align: center;
+  border-block-end: 2px dashed var(--kraft-dark);
+  padding-block-end: 8px;
+}
+
+.box-form-head .face-brand {
