+}
+
+.box-form .field-row {
+  display: grid;
+  grid-template-columns: auto 1fr;
+  gap: 12px;
+}
+
+.box-form select,
+.box-form input[type="email"],
+.box-form input[type="number"] {
+  font: inherit;
+  font-size: max(1rem, 1em);
+  min-height: 44px;
