+}
+
+.box-form :is(select, input, button):focus-visible {
+  outline: 3px solid var(--primary);
+  outline-offset: 2px;
+}
+
+.segmented {
+  display: grid;
+  grid-template-columns: repeat(3, 1fr);
+  border: 2px solid #6d4c41;
+  border-radius: 6px;
+  overflow: hidden;
