+  display: grid;
+  place-items: center;
+  min-height: 44px;
+  font-size: 0.9rem;
+  cursor: pointer;
+}
+
+.segmented label + label {
+  border-inline-start: 1px solid #6d4c41;
+}
+
+.segmented input {
+  position: absolute;
+  inset: 0;
+  opacity: 0;
+  margin: 0;
+  cursor: pointer;
+}
+
+.segmented label:has(input:checked) {
+  background: var(--primary);
+  color: white;
+  font-weight: 700;
+}
+
+.segmented label:has(input:focus-visible) {
+  outline: 3px solid var(--primary);
+  outline-offset: -5px;
+}
+
+.stepper {
+  display: grid;
+  grid-template-columns: 44px 56px 44px;
+  border: 2px solid #6d4c41;
+  border-radius: 6px;
+  overflow: hidden;
+  background: #fffaf3;
+}
+
+.stepper button {
+  font: inherit;
+  font-size: 1.3rem;
+  font-weight: 700;
+  border: 0;
+  background: var(--secondary);
+  color: var(--ink);
+  cursor: pointer;
+}
+
+.stepper button:hover {
+  background: var(--kraft-dark);
+  color: white;
+}
+
+.box-form .stepper input[type="number"] {
+  border: 0;
+  border-radius: 0;
+  text-align: center;
+  padding-inline: 0;
+  appearance: textfield;
+  -moz-appearance: textfield;
+}
+
+.stepper input::-webkit-inner-spin-button,
+.stepper input::-webkit-outer-spin-button {
+  -webkit-appearance: none;
+  margin: 0;
+}
+
+.box-form input[type="email"]:user-invalid {
+  border-color: #b3261e;
+  background-color: #fce8e6;
+}
+
+.error-msg {
+  display: none;
+  font-size: 0.8rem;
+  color: #8c1d18;
+}
+
+.box-form input[type="email"]:user-invalid ~ .error-msg {
+  display: block;
+}
+
+.box-total {
+  display: flex;
+  justify-content: space-between;
+  align-items: baseline;
+  font-size: 0.95rem;
+}
+
+.box-total output {
+  font-size: 1.3rem;
+  font-weight: 800;
+}
+
+.box-submit {
+  font: inherit;
+  font-weight: 700;
+  min-height: 48px;
+  border: 0;
+  border-radius: 6px;
+  background: var(--primary);
+  color: white;
+  cursor: pointer;
+  transition: background-color 0.2s;
+}
+
+.box-submit:hover {
+  background: #3e2723;
+}
+
+.box-submit:disabled {
+  opacity: 0.7;
+  cursor: progress;
+}
+
+.box-status {
+  min-height: 1.4em;
+  font-size: 0.85rem;
+  font-weight: 600;
+  text-align: center;
+}

