+        'price-asc': (a, b) => a.price - b.price || a.featured - b.featured,
+        'price-desc': (a, b) => b.price - a.price || a.featured - b.featured,
+      };
+      const sorted = filtered.toSorted ? filtered.toSorted(comparators[state.sort]) : [...filtered].sort(comparators[state.sort]);
