+        const params = new URLSearchParams(window.location.search);
+        const category = params.get('category');
+        const sort = params.get('sort');
+        return {
+          category: VALID_CATEGORIES.includes(category) ? category : DEFAULT_STATE.category,
+          sort: VALID_SORTS.includes(sort) ? sort : DEFAULT_STATE.sort,
+          reverse: parseBool(params.get('reverse')),
+          group: parseBool(params.get('group'))
+        };
+      }
+
+      function writeStateToURL() {
+        const params = new URLSearchParams(window.location.search);
+        params.set('category', state.category);
+        params.set('sort', state.sort);
+        params.set('reverse', state.reverse ? '1' : '0');
+        params.set('group', state.group ? '1' : '0');
+        const url = window.location.pathname + '?' + params.toString() + window.location.hash;
+        window.history.replaceState(window.history.state, '', url);
+      }
+
+      function syncControls() {
+        els.category.value = state.category;
+        els.sort.value = state.sort;
+        els.reverse.setAttribute('aria-pressed', String(state.reverse));
+        els.group.setAttribute('aria-pressed', String(state.group));
+      }
+
+      function dispatchFilterChange() {
+        els.controls.dispatchEvent(new CustomEvent('daily-grind:filter-change', {
+          bubbles: true,
+          detail: { ...state }
+        }));
+      }
+
+      /* ---------- Menu rendering (never mutates MENU) ---------- */
+      function getVisibleItems() {
+        let items = MENU.filter(item => state.category === 'all' || item.category === state.category);
+        if (state.sort === 'price-asc') items.sort((a, b) => a.price - b.price);
+        else if (state.sort === 'price-desc') items.sort((a, b) => b.price - a.price);
+        if (state.reverse) items.reverse();
+        return items;
+      }
+
+      function createCard(item) {
+        const card = document.createElement('article');
+        card.className = 'card menu-item';
+        card.dataset.id = item.id;
+        card.dataset.category = item.category;
+        card.dataset.price = item.price.toFixed(2);
+
+        const tag = document.createElement('span');
+        tag.className = 'tag';
+        tag.textContent = CATEGORY_LABELS[item.category];
+
+        const h3 = document.createElement('h3');
+        h3.textContent = item.name;
+
+        const desc = document.createElement('p');
+        desc.textContent = item.description;
+
+        const price = document.createElement('p');
+        price.className = 'price';
+        price.textContent = money(item.price);
+
+        const btn = document.createElement('button');
+        btn.type = 'button';
+        btn.className = 'btn add-to-order';
+        btn.dataset.id = item.id;
+        btn.textContent = 'Add to Order';
+        btn.setAttribute('aria-label', 'Add ' + item.name + ' to order');
+
+        card.append(tag, h3, desc, price, btn);
+        return card;
+      }
+
+      function createGrid(items) {
+        const grid = document.createElement('div');
+        grid.className = 'grid';
+        items.forEach(item => grid.appendChild(createCard(item)));
+        return grid;
+      }
+
+      function createEmpty(text) {
+        const p = document.createElement('p');
+        p.className = 'empty';
+        p.textContent = text;
+        return p;
+      }
+
+      function renderMenu() {
+        const items = getVisibleItems();
+        const frag = document.createDocumentFragment();
+
+        if (state.group) {
+          CATEGORIES.forEach(cat => {
+            const groupItems = items.filter(item => item.category === cat.id);
+            const section = document.createElement('section');
+            section.className = 'menu-group';
+            section.dataset.category = cat.id;
+
+            const h3 = document.createElement('h3');
+            h3.textContent = cat.label + ' ';
+            const count = document.createElement('span');
+            count.className = 'group-count';
+            count.textContent = '(' + groupItems.length + (groupItems.length === 1 ? ' item)' : ' items)');
+            h3.appendChild(count);
+            section.appendChild(h3);
+
+            section.appendChild(groupItems.length
+              ? createGrid(groupItems)
+              : createEmpty('No ' + cat.label.toLowerCase() + ' drinks match the current filter.'));
+            frag.appendChild(section);
+          });
+        } else {
+          frag.appendChild(items.length ? createGrid(items) : createEmpty('No drinks match the current filter.'));
+        }
+
+        els.list.replaceChildren(frag);
+        const label = state.category === 'all' ? 'all categories' : CATEGORY_LABELS[state.category];
+        els.summary.textContent = 'Showing ' + items.length + ' of ' + MENU.length + ' drinks (' + label + ')';
+      }
+
+      function applyState(next, { updateURL = true, emit = true } = {}) {
+        state = { ...state, ...next };
+        syncControls();
+        if (updateURL) writeStateToURL();
+        renderMenu();
+        if (emit) dispatchFilterChange();
+      }
+
+      els.category.addEventListener('change', () => applyState({ category: els.category.value }));
+      els.sort.addEventListener('change', () => applyState({ sort: els.sort.value }));
+      els.reverse.addEventListener('click', () => applyState({ reverse: !state.reverse }));
+      els.group.addEventListener('click', () => applyState({ group: !state.group }));
+      window.addEventListener('popstate', () => applyState(readStateFromURL(), { updateURL: false }));
+
+      /* ---------- Draft order ---------- */
+      let order = [];
+      let snapshot = null;
+      let nextOrderId = 1;
+
+      function setStatus(text) {
+        els.status.textContent = text;
+      }
+
+      function renderOrder() {
+        const frag = document.createDocumentFragment();
+        if (!order.length) {
+          const li = document.createElement('li');
+          li.className = 'empty';
+          li.textContent = 'Your order is empty. Add a drink from the menu above.';
+          frag.appendChild(li);
+        }
+        order.forEach(entry => {
+          const li = document.createElement('li');
+          li.className = 'order-item';
+          li.dataset.orderId = entry.orderId;
+
+          const info = document.createElement('div');
+          const title = document.createElement('strong');
+          title.textContent = entry.name + ' — ' + money(entry.price);
+          const meta = document.createElement('div');
+          meta.className = 'order-meta';
+          meta.textContent = entry.options.size + ' · ' + entry.options.milk + ' milk · added ' +
+            new Date(entry.addedAt).toLocaleTimeString();
+          info.append(title, meta);
+          if (entry.note) {
+            const note = document.createElement('div');
+            note.className = 'order-meta order-note';
+            note.textContent = 'Note: ' + entry.note;
+            info.appendChild(note);
+          }
+
+          const remove = document.createElement('button');
+          remove.type = 'button';
+          remove.className = 'remove-item';
+          remove.dataset.orderId = entry.orderId;
+          remove.textContent = 'Remove';
+          remove.setAttribute('aria-label', 'Remove ' + entry.name);
+
+          li.append(info, remove);
+          frag.appendChild(li);
+        });
+        els.orderItems.replaceChildren(frag);
+        els.orderTotal.textContent = money(order.reduce((sum, e) => sum + e.price, 0));
+        els.clear.disabled = order.length === 0;
+        els.restore.disabled = snapshot === null;
+      }
+
+      function addToOrder(itemId) {
+        const item = MENU.find(m => m.id === itemId);
+        if (!item) return;
+        order.push({
+          orderId: 'o' + nextOrderId++,
+          itemId: item.id,
+          name: item.name,
+          category: item.category,
+          price: item.price,
+          options: { milk: els.milk.value, size: els.size.value },
+          note: els.note.value.trim(),
+          addedAt: new Date().toISOString()
+        });
+        renderOrder();
+        setStatus(item.name + ' added to your order.');
+      }
+
+      els.list.addEventListener('click', e => {
+        const btn = e.target.closest('.add-to-order');
+        if (btn) addToOrder(btn.dataset.id);
+      });
+
+      els.orderItems.addEventListener('click', e => {
+        const btn = e.target.closest('.remove-item');
+        if (!btn) return;
+        order = order.filter(entry => entry.orderId !== btn.dataset.orderId);
+        renderOrder();
+        setStatus('Item removed.');
+      });
+
+      els.save.addEventListener('click', () => {
+        snapshot = { savedAt: new Date().toISOString(), items: deepCopy(order) };
+        renderOrder();
+        setStatus('Snapshot saved with ' + snapshot.items.length + ' item(s).');
+      });
+
+      els.restore.addEventListener('click', () => {
+        if (!snapshot) return;
+        order = deepCopy(snapshot.items);
+        renderOrder();
+        setStatus('Snapshot from ' + new Date(snapshot.savedAt).toLocaleTimeString() + ' restored.');
+      });
+
+      els.clear.addEventListener('click', () => {
+        order = [];
+        renderOrder();
+        setStatus('Order cleared.');
+      });
+
+      /* ---------- Init ---------- */
+      applyState(readStateFromURL());
+      renderOrder();
+
+      // Expose read-only accessors for debugging / integration.
+      window.dailyGrind = {
+        menu: MENU,
+        getFilterState: () => ({ ...state }),
+        getOrder: () => deepCopy(order),
+        getSnapshot: () => (snapshot ? deepCopy(snapshot) : null)
+      };
+    })();
+  </script>
+
 </body>

 </html>

