+        }
+
+        const code = top.detectedLanguage;
+        let name = code;
+        try { name = languageNames.of(code) ?? code; } catch {}
+        const confidence = Math.round(top.confidence * 100);
+
+        result.replaceChildren(
+          'Detected language: ',
+          Object.assign(document.createElement('strong'), { textContent: name, lang: code }),
+          ` (${code}) \u2014 ${confidence}% confidence.`,
