+            ? [' Short messages may be less accurate.']
+            : [])
+        );
+      } catch (err) {
+        console.error(err);
+        showMessage('Something went wrong while detecting the language. Please try again.');
+      } finally {
+        button.disabled = false;
+      }
+    });
+  </script>
