+          const top = results && results[0];
+          if (!top || top.detectedLanguage === 'und') return null;
+          return { code: top.detectedLanguage, confidence: top.confidence };
+        } catch (e) {
+          return null;
+        }
+      }
+
+      function languageName(code) {
+        try {
+          const names = new Intl.DisplayNames([navigator.language || 'en', 'en'], { type: 'language' });
+          return names.of(code) || code;
+        } catch (e) {
+          return code;
+        }
+      }
+
+      function showResult(message, isError) {
+        result.classList.toggle('error', !!isError);
+        result.innerHTML = '';
+        if (typeof message === 'string') result.textContent = message;
+        else result.appendChild(message);
+      }
+
+      form.addEventListener('submit', async function (event) {
+        event.preventDefault();
+        const text = textarea.value.trim();
+        if (!text) {
+          showResult('Please enter a message before detecting its language.', true);
+          textarea.focus();
+          return;
+        }
+
+        button.disabled = true;
+        showResult('Detecting…');
+        try {
+          const detection = (await browserDetect(text)) || heuristicDetect(text);
+          if (!detection) {
+            showResult('Sorry, we couldn’t identify the language of this message.', true);
+            return;
+          }
+          const frag = document.createDocumentFragment();
+          frag.append('Detected language: ');
+          const strong = document.createElement('strong');
+          strong.textContent = languageName(detection.code);
+          frag.append(strong, ' (' + detection.code + ', ' + Math.round(detection.confidence * 100) + '% confidence)');
+          if (text.split(/\s+/).length < 3) {
+            frag.append(' — short messages may be less accurate.');
+          }
+          showResult(frag);
+        } finally {
+          button.disabled = false;
+        }
+      });
+    })();
+  </script>
+
 </body>

 </html>

