+// On-device AI features for The Daily Grind, built on the Prompt API (LanguageModel).
+// Model output is always rendered with textContent / append(), never innerHTML.
+
+const $ = (id) => document.getElementById(id);
+
+const statusEl = $('model-status');
+const progressEl = $('model-progress');
+
+// Must match between availability() and create() so the check reflects what we'll actually use.
+const MODEL_OPTIONS = {
+  expectedInputs: [{ type: 'text', languages: ['en'] }],
+  expectedOutputs: [{ type: 'text', languages: ['en'] }],
+};
+
+const MENU_FACTS = `
+Maple Oat Latte: double shot of our house espresso, steamed oat milk, real Vermont maple syrup. Seasonal. Dairy-free and vegan. Available hot or iced, 12 oz or 16 oz. About 150 mg caffeine (12 oz). Can be made decaf or with less syrup.
+Cold Brew: house coffee steeped cold for 18 hours, served over ice. Smooth, low acidity, chocolatey notes. About 200 mg caffeine (16 oz). Served black by default; any milk or syrup can be added.`.trim();
+
+const BARISTA_SYSTEM_PROMPT = `You are a warm, knowledgeable barista at The Daily Grind coffee shop.
+You only answer questions about these two drinks:
+${MENU_FACTS}
+If a question is about anything else, politely say you can only help with the Maple Oat Latte and the Cold Brew.
+Never invent facts beyond the ones above; say you're not sure if you don't know.
+Answer in plain text (no Markdown), in at most 4 short sentences.`;
+
+// ---------------------------------------------------------------------------
+// Session lifecycle helpers
+// ---------------------------------------------------------------------------
+
+/** Every session we create is registered so we can always destroy it. */
+const liveSessions = new Set();
+
+function track(session) {
+  liveSessions.add(session);
+  updateSessionStats();
+  return session;
+}
+
+function destroySession(session) {
+  if (!session) return;
+  liveSessions.delete(session);
+  try {
+    session.destroy();
+  } catch {
+    // Already destroyed.
+  }
+  updateSessionStats();
+}
+
+function setStatus(message) {
+  statusEl.textContent = message;
+}
+
+async function getAvailability() {
+  if (!('LanguageModel' in self)) return 'unsupported';
+  try {
+    return await LanguageModel.availability(MODEL_OPTIONS);
+  } catch {
+    return 'unavailable';
+  }
+}
+
+class AIUnavailableError extends Error {
+  name = 'AIUnavailableError';
+}
+
+/**
+ * Creates a session after confirming the model can run here. When the model still
+ * has to be downloaded this must be called from a user gesture (click handler).
+ */
+async function createSession(systemPrompt) {
+  const availability = await getAvailability();
+  if (availability === 'unsupported' || availability === 'unavailable') {
+    throw new AIUnavailableError(unavailableMessage(availability));
+  }
+
+  const needsDownload = availability !== 'available';
+  if (needsDownload) {
+    progressEl.value = 0;
+    progressEl.hidden = false;
+    setStatus('Downloading the on-device AI model…');
+  }
+
+  try {
+    const session = await LanguageModel.create({
+      ...MODEL_OPTIONS,
+      // System instructions go in at creation time for a faster first prompt.
+      initialPrompts: [{ role: 'system', content: systemPrompt }],
+      monitor(m) {
+        m.addEventListener('downloadprogress', (e) => {
+          progressEl.value = e.loaded;
+          progressEl.textContent = `${Math.round(e.loaded * 100)}%`;
+          if (e.loaded < 1) {
+            setStatus(`Downloading the on-device AI model… ${Math.round(e.loaded * 100)}%`);
+          } else {
+            setStatus('Download complete. Preparing the model…');
+          }
+        });
+      },
+    });
+    if (needsDownload) setStatus('On-device AI model ready.');
+    return track(session);
+  } finally {
+    if (needsDownload) progressEl.hidden = true;
+  }
+}
+
+/** Lazily creates a shared base session; failed attempts can be retried. */
+function lazyBaseSession(systemPrompt) {
+  let promise = null;
+  return {
+    get() {
+      promise ??= createSession(systemPrompt).catch((err) => {
+        promise = null;
+        throw err;
+      });
+      return promise;
+    },
+    async reset() {
+      const pending = promise;
+      promise = null;
+      if (pending) destroySession(await pending.catch(() => null));
+    },
+  };
+}
+
+function unavailableMessage(availability) {
+  return availability === 'unsupported'
+    ? 'On-device AI isn’t supported in this browser. Try a recent version of desktop Chrome, or ask a barista in store!'
+    : 'On-device AI can’t run on this device right now. Please ask a barista in store!';
+}
+
+function friendlyError(err) {
+  if (err?.name === 'AIUnavailableError') return err.message;
+  if (err?.name === 'NotAllowedError') return 'The AI model needs your permission to start. Please click the button again.';
+  if (err?.name === 'QuotaExceededError') return 'That message is too long for the on-device model. Please shorten it and try again.';
+  if (err instanceof SyntaxError) return 'The AI returned an unexpected response. Please try again.';
+  console.error(err);
+  return 'Sorry, something went wrong with the on-device AI. Please try again.';
+}
+
+const isAbort = (err) => err?.name === 'AbortError';
+
+/** Streams a response into an element (a polite live region) chunk by chunk. */
+async function streamInto(session, input, outputEl, signal) {
+  let full = '';
+  outputEl.setAttribute('aria-busy', 'true');
+  try {
+    for await (const chunk of session.promptStreaming(input, { signal })) {
+      full += chunk;
+      outputEl.append(chunk);
+    }
+  } finally {
+    outputEl.setAttribute('aria-busy', 'false');
+  }
+  return full;
+}
+
+// ---------------------------------------------------------------------------
+// 1. Ask the Barista (streaming Q&A)
+// ---------------------------------------------------------------------------
+
+const askBtn = $('ask-the-barista');
+const stopBtn = $('barista-stop');
+const questionEl = $('barista-question');
+const answerEl = $('barista-answer');
+
+// Base session holds only the system prompt; each question runs in a fresh clone so
+// unrelated questions don't pollute each other's context.
+const baristaBase = lazyBaseSession(BARISTA_SYSTEM_PROMPT);
+let baristaController = null;
+
+askBtn.addEventListener('click', async () => {
+  const question = questionEl.value.trim();
+  if (!question) {
+    answerEl.textContent = 'Please type a question first.';
+    questionEl.focus();
+    return;
+  }
+
+  baristaController = new AbortController();
+  const { signal } = baristaController;
+  askBtn.disabled = true;
+  stopBtn.hidden = false;
+  answerEl.textContent = '';
+
+  let questionSession = null;
+  try {
+    const base = await baristaBase.get();
+    questionSession = track(await base.clone({ signal }));
+    await streamInto(questionSession, question, answerEl, signal);
+  } catch (err) {
+    if (isAbort(err)) answerEl.append(answerEl.textContent ? ' (stopped)' : 'Stopped.');
+    else answerEl.textContent = friendlyError(err);
+  } finally {
+    destroySession(questionSession);
+    baristaController = null;
+    askBtn.disabled = false;
+    const stopHadFocus = document.activeElement === stopBtn;
+    stopBtn.hidden = true;
+    if (stopHadFocus) askBtn.focus();
+  }
+});
+
+stopBtn.addEventListener('click', () => baristaController?.abort());
+
+// ---------------------------------------------------------------------------
+// 2. Customer feedback analyzer (structured JSON output)
+// ---------------------------------------------------------------------------
+
+const sentimentBtn = $('sentiment-btn');
+const feedbackEl = $('feedback-text');
+const sentimentOut = $('sentiment-output');
+
+const SENTIMENT_SCHEMA = {
+  type: 'object',
+  properties: {
+    score: {
+      type: 'number',
+      minimum: -1,
+      maximum: 1,
+      description: 'Sentiment from -1 (very negative) to 1 (very positive).',
+    },
+    category: {
+      type: 'string',
+      enum: ['positive', 'neutral', 'negative', 'mixed'],
+    },
+  },
+  required: ['score', 'category'],
+  additionalProperties: false,
+};
+
+const sentimentBase = lazyBaseSession(
+  'You analyze customer feedback for a coffee shop. Rate the overall sentiment as a score from -1 (very negative) to 1 (very positive) and pick the best matching category: positive, neutral, negative, or mixed (clear positives and negatives).',
+);
+const sentimentCache = new Map(); // normalized feedback -> JSON string
+
+sentimentBtn.addEventListener('click', async () => {
+  const feedback = feedbackEl.value.trim();
+  if (!feedback) {
+    sentimentOut.textContent = 'Please paste some customer feedback first.';
+    feedbackEl.focus();
+    return;
+  }
+
+  const cacheKey = feedback.toLowerCase().replace(/\s+/g, ' ');
+  if (sentimentCache.has(cacheKey)) {
+    sentimentOut.textContent = sentimentCache.get(cacheKey);
+    return;
+  }
+
+  sentimentBtn.disabled = true;
+  sentimentOut.setAttribute('aria-busy', 'true');
+  sentimentOut.textContent = 'Analyzing…';
+
+  let taskSession = null;
+  try {
+    const base = await sentimentBase.get();
+    taskSession = track(await base.clone());
+    const raw = await taskSession.prompt(`Customer feedback:\n"""${feedback}"""`, {
+      responseConstraint: SENTIMENT_SCHEMA, // plain object, not stringified
+    });
+    const data = JSON.parse(raw);
+    const result = {
+      score: Math.max(-1, Math.min(1, Number(data.score))),
+      category: data.category,
+    };
+    const pretty = JSON.stringify(result, null, 2);
+    sentimentCache.set(cacheKey, pretty);
+    sentimentOut.textContent = pretty;
+  } catch (err) {
+    sentimentOut.textContent = friendlyError(err);
+  } finally {
+    destroySession(taskSession);
+    sentimentOut.setAttribute('aria-busy', 'false');
+    sentimentBtn.disabled = false;
+  }
+});
+
+// ---------------------------------------------------------------------------
+// 3. Conversation branching (clone, context tracking, cleanup)
+// ---------------------------------------------------------------------------
+
+const MAX_BRANCHES = 3;
+const CONTEXT_WARN_RATIO = 0.8;
+
+const cloneBtn = $('clone-btn');
+const branchSendBtn = $('branch-send');
+const branchPromptEl = $('branch-prompt');
+const branchListEl = $('branch-list');
+const branchLogEl = $('branch-log');
+$('branch-max').textContent = String(MAX_BRANCHES);
+
+const branchBase = lazyBaseSession(BARISTA_SYSTEM_PROMPT);
+
+/** @type {{id:number, name:string, session:any, transcript:{role:string,text:string}[], lastUsed:number, overflowed:boolean}[]} */
+let branches = [];
+let activeBranchId = null;
+let nextBranchId = 1;
+let branchBusy = false;
+
+const activeBranch = () => branches.find((b) => b.id === activeBranchId) ?? null;
+
+function contextInfo(session) {
+  // contextUsage/contextWindow, with the older inputUsage/inputQuota names as a fallback.
+  const used = session.contextUsage ?? session.inputUsage ?? 0;
+  const total = session.contextWindow ?? session.inputQuota ?? 0;
+  return { used, total, ratio: total ? used / total : 0 };
+}
+
+function addBranch(session, name, transcript = []) {
+  const branch = { id: nextBranchId++, name, session, transcript, lastUsed: Date.now(), overflowed: false };
+  // Fires when the oldest turns get dropped to make room in the context window.
+  session.addEventListener?.('contextoverflow', () => {
+    branch.overflowed = true;
+    renderBranches();
+  });
+  branches.push(branch);
+  activeBranchId = branch.id;
+  enforceBranchLimit();
+  renderBranches();
+  return branch;
+}
+
+function removeBranch(id) {
+  const branch = branches.find((b) => b.id === id);
+  if (!branch) return;
+  destroySession(branch.session);
+  branches = branches.filter((b) => b.id !== id);
+  if (activeBranchId === id) {
+    activeBranchId = branches.at(-1)?.id ?? null;
+  }
+  renderBranches();
+}
+
+/** Keeps memory bounded: destroy least-recently-used branches beyond the limit. */
+function enforceBranchLimit() {
+  while (branches.length > MAX_BRANCHES) {
+    const victim = branches
+      .filter((b) => b.id !== activeBranchId)
+      .sort((a, b) => a.lastUsed - b.lastUsed)[0];
+    if (!victim) break;
+    removeBranch(victim.id);
+  }
+}
+
+async function ensureMainBranch() {
+  if (branches.length) return activeBranch();
+  const base = await branchBase.get();
+  // Keep the base pristine (system prompt only) so future fresh branches can clone it.
+  return addBranch(track(await base.clone()), 'Main');
+}
+
+function renderBranches() {
+  branchListEl.replaceChildren(
+    ...branches.map((branch) => {
+      const li = document.createElement('li');
+      li.classList.toggle('active', branch.id === activeBranchId);
+
+      const head = document.createElement('div');
+      head.className = 'branch-head';
+
+      const selectBtn = document.createElement('button');
+      selectBtn.type = 'button';
+      selectBtn.textContent = branch.name;
+      selectBtn.setAttribute('aria-pressed', String(branch.id === activeBranchId));
+      selectBtn.disabled = branchBusy;
+      selectBtn.addEventListener('click', () => {
+        activeBranchId = branch.id;
+        branch.lastUsed = Date.now();
+        renderBranches();
+      });
+
+      const closeBtn = document.createElement('button');
+      closeBtn.type = 'button';
+      closeBtn.textContent = '✕';
+      closeBtn.setAttribute('aria-label', `Close ${branch.name}`);
+      closeBtn.disabled = branchBusy;
+      closeBtn.addEventListener('click', () => {
+        removeBranch(branch.id);
+        branchPromptEl.focus();
+      });
+
+      head.append(selectBtn, closeBtn);
+
+      const { used, total, ratio } = contextInfo(branch.session);
+      const meterId = `branch-meter-${branch.id}`;
+      const meterLabel = document.createElement('small');
+      meterLabel.id = `${meterId}-label`;
+      meterLabel.textContent = total
+        ? `Context: ${used.toLocaleString()} / ${total.toLocaleString()} tokens (${Math.round(ratio * 100)}%)`
+        : 'Context usage unavailable';
+
+      const meter = document.createElement('meter');
+      meter.id = meterId;
+      meter.min = 0;
+      meter.max = 1;
+      meter.low = 0.6;
+      meter.high = CONTEXT_WARN_RATIO;
+      meter.optimum = 0;
+      meter.value = ratio;
+      meter.setAttribute('aria-labelledby', meterLabel.id);
+
+      li.append(head, meterLabel, meter);
+
+      if (branch.overflowed || ratio >= CONTEXT_WARN_RATIO) {
+        const warn = document.createElement('small');
+        warn.textContent = branch.overflowed
+          ? 'Older messages were dropped to fit the context window.'
+          : 'Context nearly full — consider closing or starting a new branch.';
+        li.append(warn);
+      }
+      return li;
+    }),
+  );
+
+  renderTranscript();
+  updateSessionStats();
+}
+
+function renderTranscript() {
+  const branch = activeBranch();
+  if (branchBusy) return; // don't clobber an in-progress stream
+  if (!branch) {
+    branchLogEl.textContent = 'No conversation yet. Send a message to start the Main branch.';
+    return;
+  }
+  branchLogEl.textContent = branch.transcript.length
+    ? branch.transcript.map((t) => `${t.role === 'user' ? 'You' : 'Barista'}: ${t.text}`).join('\n\n')
+    : `${branch.name} is empty. Send a message to continue.`;
+}
+
+function setBranchBusy(busy) {
+  branchBusy = busy;
+  branchSendBtn.disabled = busy;
+  cloneBtn.disabled = busy;
+  for (const btn of branchListEl.querySelectorAll('button')) btn.disabled = busy;
+}
+
+async function sendToActiveBranch() {
+  const message = branchPromptEl.value.trim();
+  if (!message) {
+    branchLogEl.textContent = 'Please type a message first.';
+    branchPromptEl.focus();
+    return;
+  }
+
+  setBranchBusy(true);
+  let branch = null;
+  try {
+    branch = await ensureMainBranch();
+    branch.lastUsed = Date.now();
+    branchPromptEl.value = '';
+    branch.transcript.push({ role: 'user', text: message });
+
+    renderTranscriptPrefix(branch);
+    const reply = await streamInto(branch.session, message, branchLogEl);
+    branch.transcript.push({ role: 'assistant', text: reply });
+  } catch (err) {
+    if (branch?.transcript.at(-1)?.role === 'user') branch.transcript.pop();
+    branchPromptEl.value ||= message;
+    branchLogEl.textContent = friendlyError(err);
+    setBranchBusy(false);
+    renderBranches();
+    renderErrorAfter(branchLogEl.textContent);
+    return;
+  }
+  setBranchBusy(false);
+  renderBranches();
+}
+
+function renderTranscriptPrefix(branch) {
+  const prior = branch.transcript
+    .map((t) => `${t.role === 'user' ? 'You' : 'Barista'}: ${t.text}`)
+    .join('\n\n');
+  branchLogEl.textContent = `${prior}\n\nBarista: `;
+}
+
+function renderErrorAfter(message) {
+  // renderBranches() re-renders the transcript; keep the error visible beneath it.
+  branchLogEl.append(`\n\n${message}`);
+}
+
+branchSendBtn.addEventListener('click', sendToActiveBranch);
+branchPromptEl.addEventListener('keydown', (e) => {
+  if (e.key === 'Enter' && !e.isComposing && !branchBusy) {
+    e.preventDefault();
+    sendToActiveBranch();
+  }
+});
+
+cloneBtn.addEventListener('click', async () => {
+  setBranchBusy(true);
+  try {
+    const source = await ensureMainBranch();
+    // A clone inherits the full context of its parent at this point in time.
+    const cloned = track(await source.session.clone());
+    addBranch(cloned, `${source.name.split(' ↳')[0]} ↳ ${nextBranchId}`, structuredClone(source.transcript));
+    source.lastUsed = Date.now() - 1; // clone becomes the most recently used
+  } catch (err) {
+    branchLogEl.textContent = friendlyError(err);
+  } finally {
+    setBranchBusy(false);
+    renderBranches();
+  }
+});
+
+function updateSessionStats() {
+  const statsEl = $('session-stats');
+  if (!statsEl) return;
+  const totals = branches.reduce(
+    (acc, b) => {
+      const { used, total } = contextInfo(b.session);
+      return { used: acc.used + used, total: acc.total + total };
+    },
+    { used: 0, total: 0 },
+  );
+  statsEl.textContent =
+    `Live AI sessions on this page: ${liveSessions.size}. ` +
+    `Branches: ${branches.length}/${MAX_BRANCHES}` +
+    (totals.total ? `, ${totals.used.toLocaleString()} tokens of context in use.` : '.');
+}
+
+// ---------------------------------------------------------------------------
+// Startup + cleanup
+// ---------------------------------------------------------------------------
+
+const aiButtons = [askBtn, sentimentBtn, cloneBtn, branchSendBtn];
+
+async function init() {
+  renderBranches();
+  const availability = await getAvailability();
+  switch (availability) {
+    case 'available':
+      setStatus('On-device AI is ready.');
+      // Pre-warm once the user shows intent, so the first answer has no cold start.
+      questionEl.addEventListener('focus', () => baristaBase.get().catch(() => {}), { once: true });
+      feedbackEl.addEventListener('focus', () => sentimentBase.get().catch(() => {}), { once: true });
+      branchPromptEl.addEventListener('focus', () => branchBase.get().catch(() => {}), { once: true });
+      break;
+    case 'downloadable':
+    case 'downloading':
+      setStatus('The on-device AI model will download the first time you use one of these tools.');
+      break;
+    default:
+      setStatus(unavailableMessage(availability));
+      for (const btn of aiButtons) btn.disabled = true;
+  }
+}
+
+async function destroyAll() {
+  baristaController?.abort();
+  for (const b of branches) destroySession(b.session);
+  branches = [];
+  activeBranchId = null;
+  await Promise.all([baristaBase.reset(), sentimentBase.reset(), branchBase.reset()]);
+  for (const s of [...liveSessions]) destroySession(s);
+}
+
+// Free model memory when the page goes away. If it's restored from the
+// back/forward cache, sessions are lazily recreated on next use.
+addEventListener('pagehide', () => {
+  destroyAll();
+});
+addEventListener('pageshow', (e) => {
+  if (e.persisted) renderBranches();
+});
+
+init();

