+
+function setStatus(el, message, isError = false) {
+  el.textContent = message;
+  el.classList.toggle('error', isError);
+}
+
+function describeUnavailable(status) {
+  return status === 'unsupported'
+    ? "Your browser doesn't support built-in AI yet. Try a recent version of Chrome on desktop."
+    : "The on-device model isn't available on this device (insufficient hardware, storage, or disabled by policy).";
+}
+
+/**
+ * Checks availability and creates a session, reporting model download progress.
+ * Must be called from a user gesture in case the model needs downloading.
+ */
+async function createSession({ statusEl, progressEl, signal, ...options }) {
+  const createOptions = { ...MODEL_OPTIONS, ...options };
+  // Availability must be checked with the same expected I/O used for create().
+  const status = await checkAvailability({
+    expectedInputs: createOptions.expectedInputs,
+    expectedOutputs: createOptions.expectedOutputs,
+  });
+
+  if (status === 'unsupported' || status === 'unavailable') {
+    throw Object.assign(new Error(describeUnavailable(status)), { name: 'NotSupportedError' });
+  }
+
+  if (status !== 'available') {
+    setStatus(statusEl, 'Downloading the on-device model… this only happens once.');
+    progressEl.hidden = false;
+    progressEl.value = 0;
+  }
+
+  try {
+    return await LanguageModel.create({
+      ...createOptions,
+      signal,
+      monitor(m) {
+        m.addEventListener('downloadprogress', (e) => {
+          progressEl.hidden = false;
+          progressEl.value = e.loaded; // 0..1
+          setStatus(statusEl, `Downloading model: ${Math.round(e.loaded * 100)}%`);
+          if (e.loaded >= 1) setStatus(statusEl, 'Download complete. Loading model…');
+        });
+      },
+    });
+  } finally {
+    progressEl.hidden = true;
+  }
+}
+
+// The spec renamed inputUsage/inputQuota -> contextUsage/contextWindow; support both.
+const usageOf = (s) => s?.contextUsage ?? s?.inputUsage ?? 0;
+const quotaOf = (s) => s?.contextWindow ?? s?.inputQuota ?? Infinity;
+
+function onContextOverflow(session, handler) {
+  session.addEventListener('contextoverflow', handler);
+  session.addEventListener('quotaoverflow', handler); // older name
+}
+
+function errorMessage(err) {
+  if (err?.name === 'AbortError') return 'Stopped.';
+  if (err?.name === 'NotSupportedError') return err.message;
+  if (err?.name === 'QuotaExceededError') return 'That input is too long for the model. Please shorten it.';
+  if (err?.name === 'NotAllowedError') return 'Please click the button again to allow the model to start.';
+  return `Something went wrong: ${err?.message ?? err}`;
+}
+
+/** Streams a prompt into `outputEl` (chunks are deltas) and returns the full text. */
+async function streamInto(session, prompt, outputEl, signal) {
+  const stream = session.promptStreaming(prompt, { signal });
+  let text = '';
+  for await (const chunk of stream) {
+    text += chunk;
+    outputEl.textContent = text;
+  }
+  return text;
+}
+
+// Track every live session so they can all be released when the page goes away.
+const liveSessions = new Set();
+function track(session) {
+  liveSessions.add(session);
+  return session;
+}
+function destroy(session) {
+  if (!session) return;
+  liveSessions.delete(session);
+  try {
+    session.destroy();
+  } catch {
+    /* already destroyed */
+  }
+}
+
+// ---------------------------------------------------------------------------
+// 1. Ask the Barista (streaming Q&A)
+// ---------------------------------------------------------------------------
+
+const barista = {
+  session: null,
+  controller: null,
+  btn: $('ask-the-barista'),
+  stopBtn: $('barista-stop'),
+  input: $('barista-question'),
+  output: $('barista-answer'),
+  status: $('barista-status'),
+  progress: $('barista-progress'),
+
+  async getSession(signal) {
+    if (this.session) return this.session;
+    const session = await createSession({
+      statusEl: this.status,
+      progressEl: this.progress,
+      signal,
+      initialPrompts: [{ role: 'system', content: MENU_CONTEXT }],
+    });
+    track(session);
+    onContextOverflow(session, () => {
+      // Oldest turns get evicted; start fresh next time so the system prompt stays intact.
+      this.resetSession();
+    });
+    this.session = session;
+    return session;
+  },
+
+  resetSession() {
+    destroy(this.session);
+    this.session = null;
+  },
+
+  async ask() {
+    const question = this.input.value.trim();
+    if (!question) {
+      setStatus(this.status, 'Please type a question first.', true);
+      this.input.focus();
+      return;
+    }
+
+    this.controller?.abort();
+    const controller = (this.controller = new AbortController());
+    this.btn.disabled = true;
+    this.stopBtn.hidden = false;
+    this.output.textContent = '';
+    setStatus(this.status, 'Checking on-device model availability…');
+
+    try {
+      const session = await this.getSession(controller.signal);
+
+      // Keep the conversation from silently overflowing.
+      if (typeof session.measureContextUsage === 'function' || typeof session.measureInputUsage === 'function') {
+        const measure = session.measureContextUsage ?? session.measureInputUsage;
+        const needed = await measure.call(session, question, { signal: controller.signal });
+        if (usageOf(session) + needed > quotaOf(session)) {
+          this.resetSession();
+        }
+      }
+
+      setStatus(this.status, 'The barista is thinking…');
+      await streamInto(await this.getSession(controller.signal), question, this.output, controller.signal);
+      setStatus(this.status, '');
+    } catch (err) {
+      setStatus(this.status, errorMessage(err), err?.name !== 'AbortError');
+      // A session interrupted mid-create may be in a bad state.
+      if (err?.name !== 'AbortError' && err?.name !== 'QuotaExceededError') this.resetSession();
+    } finally {
+      if (this.controller === controller) this.controller = null;
+      this.btn.disabled = false;
+      this.stopBtn.hidden = true;
+    }
+  },
+
+  init() {
+    this.btn.addEventListener('click', () => this.ask());
+    this.stopBtn.addEventListener('click', () => this.controller?.abort());
+    this.input.addEventListener('keydown', (e) => {
+      if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) this.ask();
+    });
+  },
+};
+
+// ---------------------------------------------------------------------------
+// 2. Customer Feedback Analyzer (structured JSON output)
+// ---------------------------------------------------------------------------
+
+const SENTIMENT_SCHEMA = {
+  type: 'object',
+  properties: {
+    score: { type: 'number', minimum: -1, maximum: 1 },
+    category: { type: 'string', enum: ['positive', 'neutral', 'negative'] },
+  },
+  required: ['score', 'category'],
+  additionalProperties: false,
+};
+
+const sentiment = {
+  // A primed "template" session; each analysis runs on a clone so reviews never
+  // contaminate each other's context, and the clone is destroyed afterwards.
+  baseSession: null,
+  controller: null,
+  btn: $('sentiment-btn'),
+  input: $('feedback-input'),
+  status: $('sentiment-status'),
+  progress: $('sentiment-progress'),
+  output: $('sentiment-output'),
+  summary: $('sentiment-summary'),
+  categoryEl: $('sentiment-category'),
+  scoreEl: $('sentiment-score'),
+
+  async getBase(signal) {
+    if (this.baseSession) return this.baseSession;
+    this.baseSession = track(
+      await createSession({
+        statusEl: this.status,
+        progressEl: this.progress,
+        signal,
+        initialPrompts: [
+          {
+            role: 'system',
+            content:
+              'You are a sentiment analyzer for coffee shop customer feedback. ' +
+              'Return a score from -1 (very negative) to 1 (very positive) and a category: ' +
+              'positive (score > 0.25), negative (score < -0.25), otherwise neutral.',
+          },
+        ],
+      }),
+    );
+    return this.baseSession;
+  },
+
+  async analyze() {
+    const feedback = this.input.value.trim();
+    if (!feedback) {
+      setStatus(this.status, 'Please paste some customer feedback first.', true);
+      this.input.focus();
+      return;
+    }
+
+    this.controller?.abort();
+    const controller = (this.controller = new AbortController());
+    const { signal } = controller;
+    this.btn.disabled = true;
+    this.summary.hidden = true;
+    this.output.textContent = '';
+    setStatus(this.status, 'Checking on-device model availability…');
+
+    let session;
+    try {
+      const base = await this.getBase(signal);
+      session = track(await base.clone({ signal }));
+      setStatus(this.status, 'Analyzing feedback…');
+
+      const raw = await session.prompt(`Customer feedback:\n"""${feedback}"""`, {
+        signal,
+        responseConstraint: SENTIMENT_SCHEMA,
+        omitResponseConstraintInput: false,
+      });
+
+      const result = JSON.parse(raw);
+      const score = Math.max(-1, Math.min(1, Number(result.score)));
+      const category = SENTIMENT_SCHEMA.properties.category.enum.includes(result.category)
+        ? result.category
+        : 'neutral';
+      const clean = { score: Number(score.toFixed(2)), category };
+
+      this.output.textContent = JSON.stringify(clean, null, 2);
+      this.categoryEl.textContent = category;
+      this.categoryEl.className = `sentiment-badge ${category}`;
+      this.scoreEl.textContent = clean.score.toFixed(2);
+      this.summary.hidden = false;
+      setStatus(this.status, '');
+    } catch (err) {
+      const msg = err instanceof SyntaxError ? 'The model returned malformed JSON. Please try again.' : errorMessage(err);
+      setStatus(this.status, msg, err?.name !== 'AbortError');
+      if (err?.name === 'NotSupportedError') {
+        destroy(this.baseSession);
+        this.baseSession = null;
+      }
+    } finally {
+      destroy(session); // one-shot clone: always free it
+      if (this.controller === controller) this.controller = null;
+      this.btn.disabled = false;
+    }
+  },
+
+  init() {
+    this.btn.addEventListener('click', () => this.analyze());
+  },
+};
+
+// ---------------------------------------------------------------------------
+// 3. Conversation Branching (clone sessions, track context, clean up)
+// ---------------------------------------------------------------------------
+
+const MAX_BRANCHES = 4;
+
+const branching = {
+  branches: [], // { id, name, session, transcript, lastUsed, overflowed }
+  activeId: null,
+  nextId: 1,
+  busy: false,
+  controller: null,
+  sendBtn: $('branch-send'),
+  cloneBtn: $('clone-btn'),
+  input: $('branch-input'),
+  list: $('branch-list'),
+  output: $('branch-output'),
+  status: $('branch-status'),
+  progress: $('branch-progress'),
+
+  get active() {
+    return this.branches.find((b) => b.id === this.activeId) ?? null;
+  },
+
+  addBranch(session, name, transcript = '') {
+    const branch = {
+      id: this.nextId++,
+      name,
+      session: track(session),
+      transcript,
+      lastUsed: Date.now(),
+      overflowed: false,
+    };
+    onContextOverflow(session, () => {
+      branch.overflowed = true;
+      this.render();
+    });
+    this.branches.push(branch);
+    this.activeId = branch.id;
+    this.enforceLimit();
+    this.render();
+    return branch;
+  },
+
+  removeBranch(id) {
+    const idx = this.branches.findIndex((b) => b.id === id);
+    if (idx === -1) return;
+    const [branch] = this.branches.splice(idx, 1);
+    destroy(branch.session);
+    if (this.activeId === id) {
+      const next = [...this.branches].sort((a, b) => b.lastUsed - a.lastUsed)[0];
+      this.activeId = next?.id ?? null;
+    }
+    this.render();
+  },
+
+  /** Destroys least-recently-used inactive branches beyond the cap to free memory. */
+  enforceLimit() {
+    while (this.branches.length > MAX_BRANCHES) {
+      const victim = this.branches
+        .filter((b) => b.id !== this.activeId)
+        .sort((a, b) => a.lastUsed - b.lastUsed)[0];
+      if (!victim) break;
+      this.removeBranch(victim.id);
+      setStatus(this.status, `Cleaned up "${victim.name}" to free memory (max ${MAX_BRANCHES} branches).`);
+    }
+  },
+
+  async ensureRoot(signal) {
+    if (this.active) return this.active;
+    const session = await createSession({
+      statusEl: this.status,
+      progressEl: this.progress,
+      signal,
+      initialPrompts: [{ role: 'system', content: MENU_CONTEXT }],
+    });
+    return this.addBranch(session, 'Main');
+  },
+
+  setBusy(busy) {
+    this.busy = busy;
+    this.sendBtn.disabled = busy;
+    this.cloneBtn.disabled = busy;
+    this.list.querySelectorAll('button').forEach((b) => (b.disabled = busy));
+  },
+
+  async send() {
+    const message = this.input.value.trim();
+    if (!message) {
+      setStatus(this.status, 'Type a message for the active branch first.', true);
+      this.input.focus();
+      return;
+    }
+    if (this.busy) return;
+
+    const controller = (this.controller = new AbortController());
+    this.setBusy(true);
+    setStatus(this.status, 'Checking on-device model availability…');
+    try {
+      const branch = await this.ensureRoot(controller.signal);
+      branch.lastUsed = Date.now();
+      setStatus(this.status, `Replying in "${branch.name}"…`);
+      this.output.textContent = '';
+      const reply = await streamInto(branch.session, message, this.output, controller.signal);
+      branch.transcript += `You: ${message}\nBarista: ${reply}\n\n`;
+      this.output.textContent = branch.transcript.trim();
+      this.input.value = '';
+      setStatus(this.status, '');
+    } catch (err) {
+      setStatus(this.status, errorMessage(err), err?.name !== 'AbortError');
+    } finally {
+      this.controller = null;
+      this.setBusy(false);
+      this.render();
+    }
+  },
+
+  async clone() {
+    if (this.busy) return;
+    const controller = (this.controller = new AbortController());
+    this.setBusy(true);
+    try {
+      const source = await this.ensureRoot(controller.signal);
+      if (source.overflowed) {
+        setStatus(this.status, `Note: "${source.name}" overflowed its context; the clone inherits the truncated history.`);
+      }
+      setStatus(this.status, `Cloning "${source.name}"…`);
+      const cloned = await source.session.clone({ signal: controller.signal });
+      source.lastUsed = Date.now();
+      const branch = this.addBranch(cloned, `Branch ${this.nextId - 1} (from ${source.name})`, source.transcript);
+      this.output.textContent = branch.transcript.trim();
+      setStatus(this.status, `Created "${branch.name}". It's now the active branch.`);
+    } catch (err) {
+      setStatus(this.status, errorMessage(err), err?.name !== 'AbortError');
+    } finally {
+      this.controller = null;
+      this.setBusy(false);
+      this.render();
+    }
+  },
+
+  activate(id) {
+    if (this.busy) return;
+    const branch = this.branches.find((b) => b.id === id);
+    if (!branch) return;
+    this.activeId = id;
+    branch.lastUsed = Date.now();
+    this.output.textContent = branch.transcript.trim();
+    this.render();
+  },
+
+  render() {
+    this.list.replaceChildren(
+      ...this.branches.map((b) => {
+        const used = usageOf(b.session);
+        const quota = quotaOf(b.session);
+        const pct = Number.isFinite(quota) && quota > 0 ? Math.round((used / quota) * 100) : 0;
+
+        const li = document.createElement('li');
+        li.className = `branch${b.id === this.activeId ? ' active' : ''}`;
+        li.tabIndex = 0;
+        li.setAttribute('aria-current', b.id === this.activeId ? 'true' : 'false');
+        li.addEventListener('click', () => this.activate(b.id));
+        li.addEventListener('keydown', (e) => {
+          if (e.key === 'Enter' || e.key === ' ') {
+            e.preventDefault();
+            this.activate(b.id);
+          }
+        });
+
+        const title = document.createElement('strong');
+        title.textContent = b.name + (b.id === this.activeId ? ' • active' : '');
+
+        const del = document.createElement('button');
+        del.type = 'button';
+        del.textContent = 'Discard';
+        del.disabled = this.busy;
+        del.setAttribute('aria-label', `Discard ${b.name}`);
+        del.addEventListener('click', (e) => {
+          e.stopPropagation();
+          this.removeBranch(b.id);
+        });
+
+        const meter = document.createElement('meter');
+        meter.min = 0;
+        meter.max = Number.isFinite(quota) ? quota : 1;
+        meter.value = used;
+        meter.low = meter.max * 0.6;
+        meter.high = meter.max * 0.85;
+        meter.optimum = 0;
+
+        const info = document.createElement('small');
+        info.textContent = Number.isFinite(quota)
+          ? `Context: ${used.toLocaleString()} / ${quota.toLocaleString()} tokens (${pct}%)` +
+            (b.overflowed ? ' — overflowed, oldest turns dropped' : '')
+          : `Context: ${used.toLocaleString()} tokens`;
+
+        li.append(title, del, meter, info);
+        return li;
+      }),
+    );
+  },
+
+  init() {
+    this.sendBtn.addEventListener('click', () => this.send());
+    this.cloneBtn.addEventListener('click', () => this.clone());
+  },
+};
+
+// ---------------------------------------------------------------------------
+// Boot
+// ---------------------------------------------------------------------------
+
+barista.init();
+sentiment.init();
+branching.init();
+
+// Proactively tell users if the feature can't work, without triggering a download.
+checkAvailability().then((status) => {
+  if (status === 'unsupported' || status === 'unavailable') {
+    const msg = describeUnavailable(status);
+    for (const el of [barista.status, sentiment.status, branching.status]) setStatus(el, msg, true);
+    for (const btn of [barista.btn, sentiment.btn, branching.sendBtn, branching.cloneBtn]) btn.disabled = true;
+  } else if (status === 'downloadable' || status === 'downloading') {
+    setStatus(barista.status, 'The on-device model will download the first time you ask a question.');
+  }
+});
+
+// Release model resources when leaving the page.
+window.addEventListener('pagehide', () => {
+  barista.controller?.abort();
+  sentiment.controller?.abort();
+  branching.controller?.abort();
+  for (const s of [...liveSessions]) destroy(s);
+  // Drop references so a page restored from the back/forward cache recreates sessions.
+  barista.session = null;
+  sentiment.baseSession = null;
+  branching.branches = [];
+  branching.activeId = null;
+  branching.render();
+});

