+    const message =
+      name === 'TimeoutError'
+        ? `No response within ${REQUEST_TIMEOUT_MS / 1000}s.`
+        : 'Connection failed. The endpoint may be offline, unreachable, missing CORS headers, or access was blocked.';
+    return { kind: 'error', message, at: new Date() };
+  }
