+  denied: { label: 'Blocked', className: 'bg-red-100 text-red-800' },
+  unsupported: { label: 'Not reported', className: 'bg-gray-100 text-gray-700' },
+};
+
+function PermissionBadge({ state }: { state: PermState }) {
+  const b = PERM_BADGE[state];
+  return (
+    <span className={`inline-flex items-center rounded-full px-2 py-0.5 text-xs font-semibold ${b.className}`}>
+      {b.label}
+    </span>
+  );
+}
+
+function StatusPanel({ status }: { status: ConnStatus }) {
+  return (
+    <div aria-live="polite" className="mt-4 min-h-6 text-sm">
+      {status.kind === 'connecting' && <p className="text-gray-600">Connecting…</p>}
