+          <p className="font-semibold text-green-700">
+            Connected · HTTP {status.httpStatus} · {status.latencyMs} ms
+            <span className="ml-2 font-normal text-gray-500">at {status.at.toLocaleTimeString()}</span>
+          </p>
+          {status.body && (
+            <pre className="mt-2 max-h-48 overflow-auto rounded bg-gray-900 p-3 text-xs text-gray-100">
