+    return (
+      <div className="mt-3 rounded border border-red-200 bg-red-50 p-3 text-sm text-red-800">
+        {kind === 'device' ? 'Local network' : 'Loopback network'} access is blocked for this site. Click the
+        site-information icon in the address bar, open <strong>Site settings</strong>, and set{' '}
+        <strong>{kind === 'device' ? 'Local network' : 'Loopback network'}</strong> to <em>Allow</em>, then try again.
+      </div>
