+ * Safety design:
+ *   - Nothing is contacted automatically. Every request is the result of an
+ *     explicit click, to a single address the reader typed in. No scanning,
+ *     no address enumeration.
+ *   - Targets are validated client-side: the device must be a private-range
+ *     IPv4 literal (RFC 1918) or an mDNS `.local` name; the CLI must be a
+ *     loopback address. Public hosts are rejected, so the widget cannot be
+ *     abused as a generic request tool.
+ *   - Requests use Chrome's Local Network Access `targetAddressSpace` hint so
+ *     the browser shows its permission prompt and the reader stays in control.
+ *   - Cookies/credentials are never sent (`credentials: 'omit'`), redirects are
+ *     refused, requests time out, and response bodies are size-capped and only
+ *     ever rendered as plain text.
+ *   - The CLI pairing token lives only in component memory: it is never
+ *     persisted, logged, or sent anywhere other than the loopback address.
+ */
+
+type AddressSpace = 'local' | 'loopback';
+type Status = 'idle' | 'connecting' | 'connected' | 'error';
+
+interface ProbeResult {
+  status: Status;
+  message?: string;
+  httpStatus?: number;
+  latencyMs?: number;
+  body?: string;
+  checkedAt?: string;
+}
+
+const REQUEST_TIMEOUT_MS = 5000;
+const MAX_BODY_CHARS = 4000;
+const STORAGE_KEY = 'devtools-times:diagnostics-targets';
+
+// ---------------------------------------------------------------------------
+// Validation helpers
+// ---------------------------------------------------------------------------
+
+function parseIPv4(host: string): number[] | null {
+  const parts = host.split('.');
+  if (parts.length !== 4) return null;
+  const octets: number[] = [];
+  for (const p of parts) {
+    if (!/^\d{1,3}$/.test(p)) return null;
+    // Reject leading zeros ("010") which some parsers treat as octal.
+    if (p.length > 1 && p.startsWith('0')) return null;
+    const n = Number(p);
+    if (n > 255) return null;
+    octets.push(n);
+  }
+  return octets;
+}
+
+function isPrivateLanHost(host: string): boolean {
+  const ip = parseIPv4(host);
+  if (ip) {
+    const [a, b] = ip;
+    if (a === 10) return true; // 10.0.0.0/8
+    if (a === 172 && b >= 16 && b <= 31) return true; // 172.16.0.0/12
+    if (a === 192 && b === 168) return true; // 192.168.0.0/16
+    return false;
+  }
+  // mDNS hostnames such as "testrig.local" (letters, digits, hyphens only).
+  return /^(?=.{1,253}$)([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+local$/i.test(host);
+}
+
+function isLoopbackHost(host: string): boolean {
+  if (host === 'localhost' || host === '[::1]' || host === '::1') return true;
+  const ip = parseIPv4(host);
+  return !!ip && ip[0] === 127;
+}
+
+function parsePort(port: string): number | null {
+  if (!/^\d{1,5}$/.test(port)) return null;
+  const n = Number(port);
+  return n >= 1 && n <= 65535 ? n : null;
+}
+
+function normalizePath(path: string): string | null {
+  const trimmed = path.trim() || '/';
+  const withSlash = trimmed.startsWith('/') ? trimmed : `/${trimmed}`;
+  // Plain path only: no scheme, authority, backslashes, or whitespace tricks.
+  if (!/^\/[A-Za-z0-9._~\-/]*$/.test(withSlash)) return null;
+  if (withSlash.startsWith('//')) return null;
+  return withSlash;
+}
+
+function buildUrl(
+  host: string,
+  port: string,
+  path: string,
+  space: AddressSpace,
+): { url?: string; error?: string } {
+  const h = host.trim().toLowerCase();
+  if (!h) return { error: 'Enter a host address.' };
+
+  if (space === 'local' && !isPrivateLanHost(h)) {
+    return {
+      error:
+        'Device address must be on a private LAN (10.x.x.x, 172.16–31.x.x, 192.168.x.x) or an mDNS name ending in .local.',
+    };
+  }
+  if (space === 'loopback' && !isLoopbackHost(h)) {
+    return { error: 'Companion CLI address must be loopback (127.0.0.1, ::1 or localhost).' };
+  }
+
+  const p = parsePort(port.trim());
+  if (p === null) return { error: 'Port must be a number between 1 and 65535.' };
+
+  const normalizedPath = normalizePath(path);
+  if (!normalizedPath) return { error: 'Path may only contain letters, digits and - . _ ~ /' };
+
+  const hostPart = h === '::1' ? '[::1]' : h;
+  const url = new URL(`http://${hostPart}:${p}${normalizedPath}`);
+
+  // Defence in depth: re-check what the URL parser actually produced.
+  const parsedHost = url.hostname.toLowerCase();
+  const ok = space === 'local' ? isPrivateLanHost(parsedHost) : isLoopbackHost(parsedHost);
+  if (!ok || url.username || url.password) return { error: 'Address rejected.' };
+
+  return { url: url.toString() };
+}
+
+// ---------------------------------------------------------------------------
+// Network probe
+// ---------------------------------------------------------------------------
+
+async function probe(
+  url: string,
+  space: AddressSpace,
+  signal: AbortSignal,
+  token?: string,
+): Promise<ProbeResult> {
+  const started = performance.now();
+  const headers: Record<string, string> = { Accept: 'application/json, text/plain;q=0.9' };
+  if (token) headers['Authorization'] = `Bearer ${token}`;
+
+  const init: RequestInit & { targetAddressSpace?: AddressSpace } = {
+    method: 'GET',
+    mode: 'cors',
+    credentials: 'omit',
+    cache: 'no-store',
+    redirect: 'error',
+    referrerPolicy: 'no-referrer',
+    headers,
+    signal,
+    // Chrome Local Network Access: declares intent so the browser can prompt
+    // the reader and allow http:// local targets from this https:// page.
+    targetAddressSpace: space,
+  };
+
+  try {
+    const res = await fetch(url, init);
+    const latencyMs = Math.round(performance.now() - started);
+    const raw = (await res.text()).slice(0, MAX_BODY_CHARS);
+
+    let body = raw;
+    if ((res.headers.get('content-type') || '').includes('json')) {
+      try {
+        body = JSON.stringify(JSON.parse(raw), null, 2);
+      } catch {
+        /* show raw text */
+      }
+    }
+
+    return {
+      status: res.ok ? 'connected' : 'error',
+      httpStatus: res.status,
+      latencyMs,
+      body,
+      message: res.ok
+        ? 'Connected.'
+        : res.status === 401 || res.status === 403
+          ? 'Reachable, but the request was not authorized. Check the pairing token.'
+          : `Reachable, but responded with HTTP ${res.status}.`,
+      checkedAt: new Date().toLocaleTimeString(),
+    };
+  } catch (err) {
+    const e = err as Error;
+    let message: string;
+    if (e.name === 'TimeoutError' || (e.name === 'AbortError' && signal.reason?.name === 'TimeoutError')) {
+      message = `No response within ${REQUEST_TIMEOUT_MS / 1000}s. Is the target powered on and on the same network?`;
+    } else if (e.name === 'AbortError') {
+      message = 'Cancelled.';
+    } else {
+      message =
+        'Connection failed. The browser may have blocked the request (local network permission denied), ' +
+        'the target may be offline, or it may not send the required CORS / Access-Control-Allow-Private-Network headers.';
+    }
+    return { status: 'error', message, checkedAt: new Date().toLocaleTimeString() };
+  }
+}
+
+// ---------------------------------------------------------------------------
+// UI
+// ---------------------------------------------------------------------------
+
+const STATUS_STYLES: Record<Status, { dot: string; label: string }> = {
+  idle: { dot: 'bg-gray-300', label: 'Not connected' },
+  connecting: { dot: 'bg-amber-400 animate-pulse', label: 'Connecting…' },
+  connected: { dot: 'bg-green-500', label: 'Connected' },
+  error: { dot: 'bg-red-500', label: 'Error' },
+};
+
+interface PanelProps {
+  id: string;
+  title: string;
+  description: string;
+  space: AddressSpace;
+  host: string;
+  port: string;
+  path: string;
+  onHost: (v: string) => void;
+  onPort: (v: string) => void;
+  onPath: (v: string) => void;
+  hostPlaceholder: string;
+  token?: string;
+  onToken?: (v: string) => void;
+}
+
+function TargetPanel(props: PanelProps) {
+  const { id, title, description, space, host, port, path, token } = props;
+  const [result, setResult] = useState<ProbeResult>({ status: 'idle' });
+  const controllerRef = useRef<AbortController | null>(null);
+
+  useEffect(() => () => controllerRef.current?.abort(), []);
+
+  const connect = async (e: React.FormEvent) => {
+    e.preventDefault();
+    const built = buildUrl(host, port, path, space);
+    if (!built.url) {
+      setResult({ status: 'error', message: built.error });
+      return;
+    }
+    controllerRef.current?.abort();
+    const controller = new AbortController();
+    controllerRef.current = controller;
+    const signal = AbortSignal.any([controller.signal, AbortSignal.timeout(REQUEST_TIMEOUT_MS)]);
+
+    setResult({ status: 'connecting' });
+    const r = await probe(built.url, space, signal, token?.trim() || undefined);
+    if (controllerRef.current === controller) setResult(r);
+  };
+
+  const cancel = () => controllerRef.current?.abort();
+  const style = STATUS_STYLES[result.status];
+  const inputCls =
+    'w-full px-3 py-2 border border-gray-300 rounded-md text-sm font-mono focus:outline-none focus:ring-2 focus:ring-gray-900';
+
+  return (
+    <section aria-labelledby={`${id}-title`} className="border border-gray-200 rounded-lg p-5 bg-white flex flex-col">
+      <div className="flex items-start justify-between gap-4 mb-2">
+        <h3 id={`${id}-title`} className="text-lg font-bold text-gray-900">
+          {title}
+        </h3>
+        <span className="flex items-center gap-2 text-xs text-gray-600 whitespace-nowrap" aria-live="polite">
+          <span className={`inline-block w-2.5 h-2.5 rounded-full ${style.dot}`} aria-hidden="true" />
+          {style.label}
+        </span>
+      </div>
+      <p className="text-sm text-gray-600 mb-4">{description}</p>
+
+      <form onSubmit={connect} className="space-y-3" noValidate>
+        <div className="grid grid-cols-3 gap-3">
+          <div className="col-span-2">
+            <label htmlFor={`${id}-host`} className="block text-xs font-semibold text-gray-700 mb-1">
+              Host
+            </label>
+            <input
+              id={`${id}-host`}
+              className={inputCls}
+              value={host}
+              onChange={(e) => props.onHost(e.target.value)}
+              placeholder={props.hostPlaceholder}
+              autoComplete="off"
+              spellCheck={false}
+              inputMode="url"
+            />
+          </div>
+          <div>
+            <label htmlFor={`${id}-port`} className="block text-xs font-semibold text-gray-700 mb-1">
+              Port
+            </label>
+            <input
+              id={`${id}-port`}
+              className={inputCls}
+              value={port}
+              onChange={(e) => props.onPort(e.target.value)}
+              inputMode="numeric"
+              autoComplete="off"
+            />
+          </div>
+        </div>
+        <div>
+          <label htmlFor={`${id}-path`} className="block text-xs font-semibold text-gray-700 mb-1">
+            Status endpoint
+          </label>
+          <input
+            id={`${id}-path`}
+            className={inputCls}
+            value={path}
+            onChange={(e) => props.onPath(e.target.value)}
+            autoComplete="off"
+            spellCheck={false}
+          />
+        </div>
+        {props.onToken && (
+          <div>
+            <label htmlFor={`${id}-token`} className="block text-xs font-semibold text-gray-700 mb-1">
+              Pairing token <span className="font-normal text-gray-500">(printed by the CLI; kept in memory only)</span>
+            </label>
+            <input
+              id={`${id}-token`}
+              type="password"
+              className={inputCls}
+              value={token}
+              onChange={(e) => props.onToken!(e.target.value)}
+              autoComplete="off"
+              spellCheck={false}
+            />
+          </div>
+        )}
+
+        <div className="flex gap-2 pt-1">
+          <button
+            type="submit"
+            disabled={result.status === 'connecting'}
+            className="flex-1 py-2 px-4 rounded-md text-sm font-semibold text-white bg-gray-900 hover:bg-gray-800 disabled:opacity-60 disabled:cursor-not-allowed"
+          >
+            {result.status === 'connected' ? 'Re-check' : 'Connect'}
+          </button>
+          {result.status === 'connecting' && (
+            <button
+              type="button"
+              onClick={cancel}
+              className="py-2 px-4 rounded-md text-sm font-semibold text-gray-800 bg-gray-100 hover:bg-gray-200"
+            >
+              Cancel
+            </button>
+          )}
+        </div>
+      </form>
+
+      {result.status !== 'idle' && result.status !== 'connecting' && (
+        <div
+          role={result.status === 'error' ? 'alert' : 'status'}
+          className={`mt-4 p-3 rounded-md text-sm ${
+            result.status === 'connected' ? 'bg-green-50 text-green-800' : 'bg-red-50 text-red-800'
+          }`}
+        >
+          <p>{result.message}</p>
+          {(result.httpStatus !== undefined || result.latencyMs !== undefined) && (
+            <p className="mt-1 text-xs opacity-80 font-mono">
+              {result.httpStatus !== undefined && `HTTP ${result.httpStatus}`}
+              {result.latencyMs !== undefined && ` · ${result.latencyMs} ms`}
+              {result.checkedAt && ` · ${result.checkedAt}`}
+            </p>
+          )}
+        </div>
+      )}
+
+      {result.body && (
+        <details className="mt-3" open={result.status === 'connected'}>
+          <summary className="text-xs font-semibold text-gray-700 cursor-pointer">Response</summary>
+          {/* Rendered as text only; never interpreted as HTML. */}
+          <pre className="mt-2 p-3 bg-gray-900 text-gray-100 text-xs rounded-md overflow-auto max-h-64 whitespace-pre-wrap break-all">
+            {result.body}
+          </pre>
+        </details>
+      )}
+    </section>
+  );
+}
+
+interface SavedTargets {
+  deviceHost: string;
+  devicePort: string;
+  devicePath: string;
+  cliHost: string;
+  cliPort: string;
+  cliPath: string;
+}
+
+const DEFAULTS: SavedTargets = {
+  deviceHost: '192.168.1.50',
+  devicePort: '80',
+  devicePath: '/status',
+  cliHost: '127.0.0.1',
+  cliPort: '7878',
+  cliPath: '/health',
+};
+
+export default function DiagnosticsConnect() {
+  const [targets, setTargets] = useState<SavedTargets>(DEFAULTS);
+  const [token, setToken] = useState('');
+  const [loaded, setLoaded] = useState(false);
+
+  // Restore non-secret settings (addresses/ports only — never the token).
+  useEffect(() => {
+    try {
+      const saved = JSON.parse(localStorage.getItem(STORAGE_KEY) || 'null');
+      if (saved && typeof saved === 'object') {
+        const next = { ...DEFAULTS };
+        for (const k of Object.keys(DEFAULTS) as (keyof SavedTargets)[]) {
+          if (typeof saved[k] === 'string' && saved[k].length <= 255) next[k] = saved[k];
+        }
+        setTargets(next);
+      }
+    } catch {
+      /* ignore */
+    }
+    setLoaded(true);
+  }, []);
+
+  useEffect(() => {
+    if (!loaded) return;
+    try {
+      localStorage.setItem(STORAGE_KEY, JSON.stringify(targets));
+    } catch {
+      /* ignore */
+    }
+  }, [targets, loaded]);
+
+  const set = (k: keyof SavedTargets) => (v: string) => setTargets((t) => ({ ...t, [k]: v }));
+
+  return (
+    <div className="space-y-6">
+      <div className="grid gap-6 md:grid-cols-2">
+        <TargetPanel
+          id="device"
+          title="Hardware test device"
+          description="A test rig on your private Wi-Fi network. Enter its LAN address — e.g. 192.168.1.50 or testrig.local."
+          space="local"
+          host={targets.deviceHost}
+          port={targets.devicePort}
+          path={targets.devicePath}
+          onHost={set('deviceHost')}
+          onPort={set('devicePort')}
+          onPath={set('devicePath')}
+          hostPlaceholder="192.168.1.50"
+        />
+        <TargetPanel
+          id="cli"
+          title="Companion CLI"
+          description="The diagnostics CLI running on this computer. Start it with `devtools-times-cli serve` and paste the pairing token it prints."
+          space="loopback"
+          host={targets.cliHost}
+          port={targets.cliPort}
+          path={targets.cliPath}
+          onHost={set('cliHost')}
+          onPort={set('cliPort')}
+          onPath={set('cliPath')}
+          hostPlaceholder="127.0.0.1"
+          token={token}
+          onToken={setToken}
+        />
+      </div>
+
+      <div className="text-xs text-gray-600 border-t border-gray-200 pt-4 space-y-2">
+          <p>
+            <strong>Privacy:</strong> connections go directly from your browser to the address you enter. Nothing is
+            contacted until you click <em>Connect</em>, only private-LAN and loopback addresses are accepted, and no
+            results are sent to The DevTools Times.
+          </p>
+          <p>
+            <strong>Browser permission:</strong> Chrome will ask whether this site may access devices on your local
+            network. You can revoke it at any time from the site settings (padlock icon). Other browsers may block
+            requests from an HTTPS page to <code>http://</code> local addresses.
+          </p>
+          <p>
+            <strong>Target requirements:</strong> the device and CLI must answer CORS requests from this origin (
+            <code>Access-Control-Allow-Origin</code>, and <code>Access-Control-Allow-Headers: Authorization</code> for
+            the CLI) and reply to preflights with <code>Access-Control-Allow-Private-Network: true</code>.
+          </p>
+      </div>
+    </div>
+  );
+}
