--- /dev/null
+++ b/migrate-config.js
@@ -0,0 +1,38 @@
+// One-time import of user configuration from the previous origin.
+// Web App Origin Migration moves the *installation* only; storage is origin-bound,
+// so we pull the old origin's localStorage through a same-site hidden iframe.
+const OLD_ORIGIN = 'https://dailygrind.example.com';
+const DONE_KEY = 'dg:config-migrated';
+
+if (location.origin !== OLD_ORIGIN && !localStorage.getItem(DONE_KEY)) {
+  const frame = document.createElement('iframe');
+  frame.src = `${OLD_ORIGIN}/migrate-export.html`;
+  frame.hidden = true;
+  frame.setAttribute('aria-hidden', 'true');
+  frame.tabIndex = -1;
+
+  const cleanup = () => {
+    window.removeEventListener('message', onMessage);
+    frame.remove();
+  };
+  const timer = setTimeout(cleanup, 8000);
+
+  function onMessage(event) {
+    if (event.origin !== OLD_ORIGIN || event.source !== frame.contentWindow) return;
+    const data = event.data;
+    if (!data || data.type !== 'dg:config-export' || typeof data.entries !== 'object') return;
+    for (const [key, value] of Object.entries(data.entries)) {
+      // Never clobber settings the user has already changed on the new origin.
+      if (typeof value === 'string' && localStorage.getItem(key) === null) {
+        localStorage.setItem(key, value);
+      }
+    }
+    localStorage.setItem(DONE_KEY, new Date().toISOString());
+    clearTimeout(timer);
+    cleanup();
+    window.dispatchEvent(new CustomEvent('dg:config-migrated'));
+  }
+
+  window.addEventListener('message', onMessage);
+  document.body.append(frame);
+}

