+
+        if (!verified) {
+          // The authenticator holds a credential the server doesn't know about; remove it.
+          await signalOrphanedCredential(rpId, credential.id);
+        }
+      }
+
+      // ---------- password sign-in ----------
+      form.addEventListener('submit', async function (event) {
+        event.preventDefault();
+        var username = form.username.value.trim();
+        var password = form.password.value;
+        if (!username || !password) {
+          showMessage('Please enter your username and password.', 'error');
+          return;
+        }
+
+        button.disabled = true;
+        showMessage('Signing in…');
+
+        var ok = false;
+        try {
+          var res = await fetch('/api/login', {
+            method: 'POST',
+            credentials: 'same-origin',
+            headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
+            body: JSON.stringify({ username: username, password: password })
+          });
+          ok = res.ok;
+          if (!ok) {
+            var err = await res.json().catch(function () { return {}; });
+            showMessage(err.error || err.message || 'Invalid username or password.', 'error');
+          }
+        } catch (e) {
+          showMessage('Unable to sign in right now. Please try again.', 'error');
+        } finally {
+          button.disabled = false;
+        }
+
+        if (!ok) return;
+
+        form.password.value = '';
+        showMessage('Welcome back, ' + username + '!', 'success');
+
+        // Fire-and-forget: never surfaces UI or errors to the user.
+        silentlyRegisterPasskey().catch(function () { /* silent */ });
+      });
+    })();
+  </script>
+
 </body>

