+// Small subset of the community AAGUID registry:
+// https://github.com/passkeydeveloper/passkey-authenticator-aaguids
+// Used purely to help users recognize their passkeys (AAGUIDs are not attested).
+
+export const ZERO_AAGUID = '00000000-0000-0000-0000-000000000000';
+
+const PROVIDERS = {
+  'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4': { name: 'Google Password Manager', color: '#1a73e8' },
+  'adce0002-35bc-c60a-648b-0b25f1f05503': { name: 'Chrome on Mac', color: '#1a73e8' },
+  'fbfc3007-154e-4ecc-8c0b-6e020557d7bd': { name: 'iCloud Keychain', color: '#555555' },
+  'dd4ec289-e01d-41c9-bb89-70fa845d4bf2': { name: 'iCloud Keychain (Managed)', color: '#555555' },
+  '08987058-cadc-4b81-b6e1-30de50dcbe96': { name: 'Windows Hello', color: '#0078d4' },
+  '9ddd1817-af5a-4672-a2b9-3e3dd95000a9': { name: 'Windows Hello', color: '#0078d4' },
+  '6028b017-b1d4-4c02-b4b3-afcdafc96bb2': { name: 'Windows Hello', color: '#0078d4' },
+  'bada5566-a7aa-401f-bd96-45619a55120d': { name: '1Password', color: '#0572ec' },
+  'd548826e-79b4-db40-a3d8-11116f7e8349': { name: 'Bitwarden', color: '#175ddc' },
+  '531126d6-e717-415c-9320-3d9aa6981239': { name: 'Dashlane', color: '#0e353d' },
+  'b84e4048-15dc-4dd0-8640-f4f60813c8af': { name: 'NordPass', color: '#3e5fff' },
+  'cb69481e-8ff7-4039-93ec-0a2729a154a8': { name: 'YubiKey 5 Series', color: '#84bd00' },
+  'ee882879-721c-4913-9775-3dfcce97072a': { name: 'YubiKey 5 Series', color: '#84bd00' },
+};
+
+function monogramIcon(label, color) {
+  const letter = (label.trim()[0] || '?').toUpperCase();
+  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 40 40">` +
+    `<rect width="40" height="40" rx="8" fill="${color}"/>` +
+    `<text x="20" y="27" text-anchor="middle" font-family="system-ui,sans-serif" font-size="20" font-weight="700" fill="#fff">${letter}</text>` +
+    `</svg>`;
+  return `data:image/svg+xml,${encodeURIComponent(svg)}`;
+}
+
+const KEY_ICON = `data:image/svg+xml,${encodeURIComponent(
+  '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 40 40"><rect width="40" height="40" rx="8" fill="#d7ccc8"/>' +
+  '<g fill="none" stroke="#4e342e" stroke-width="2.5" stroke-linecap="round"><circle cx="15" cy="17" r="6"/>' +
+  '<path d="M19.5 21 30 31.5M26 27.5l3-3M23 24.5l2.5-2.5"/></g></svg>',
+)}`;
+
+/** Returns { name, icon } describing who stores this passkey. */
+export function describeProvider(aaguid) {
+  if (!aaguid || aaguid === ZERO_AAGUID) {
+    return { name: 'Unknown passkey provider', icon: KEY_ICON };
+  }
+  const provider = PROVIDERS[aaguid.toLowerCase()];
+  if (!provider) return { name: 'Passkey', icon: KEY_ICON };
+  return { name: provider.name, icon: monogramIcon(provider.name, provider.color) };
+}
