+// Client for the account/passkey endpoints. Credential IDs and the user's
+// passkey user ID are unpadded Base64URL strings; timestamps are epoch ms.
+//
+//   GET    /api/credentials                 -> { rpId, userId, user: { name, displayName }, credentials: [...] }
+//   PUT    /api/credential/:id   { name }   -> credential
+//   DELETE /api/credential/:id              -> { success: true }
+//   PUT    /api/user  { name, displayName } -> { name, displayName, rpId, userId }
+//   POST   /api/passkey/register/options    -> PublicKeyCredentialCreationOptionsJSON
+//   POST   /api/passkey/register/verify     -> credential
+//
+// <meta name="passkey-api" content="mock"> swaps in an in-browser demo backend.
+
+import { createMockBackend } from './mock-backend.js';
+
+export class ApiError extends Error {
+  constructor(message, status) {
+    super(message);
+    this.status = status;
+  }
+}
+
+async function request(method, path, body) {
+  const response = await fetch(path, {
+    method,
+    credentials: 'same-origin',
+    headers: body ? { 'Content-Type': 'application/json' } : undefined,
+    body: body ? JSON.stringify(body) : undefined,
+  });
+  if (response.status === 401) {
+    location.assign(`/login?next=${encodeURIComponent(location.pathname)}`);
+    throw new ApiError('Please sign in again.', 401);
+  }
+  const data = await response.json().catch(() => ({}));
+  if (!response.ok) {
+    throw new ApiError(data.error || `Request failed (${response.status}).`, response.status);
+  }
+  return data;
+}
+
+const liveBackend = {
+  listCredentials: () => request('GET', '/api/credentials'),
+  renameCredential: (id, name) => request('PUT', `/api/credential/${encodeURIComponent(id)}`, { name }),
+  deleteCredential: (id) => request('DELETE', `/api/credential/${encodeURIComponent(id)}`),
+  updateUser: (details) => request('PUT', '/api/user', details),
+  getRegistrationOptions: () => request('POST', '/api/passkey/register/options'),
+  verifyRegistration: (credential) => request('POST', '/api/passkey/register/verify', credential),
+};
+
+const mode = document.querySelector('meta[name="passkey-api"]')?.content;
+
+export const api = mode === 'mock' ? createMockBackend() : liveBackend;
