+// In-browser stand-in for the account API so the page works on the static
+// site before the real endpoints ship. Data lives in localStorage.
+// Not secure: it does not verify attestation. Never use it in production.
+
+import { base64UrlToBuffer, randomBase64Url } from './webauthn.js';
+import { describeProvider } from './aaguids.js';
+
+const STORAGE_KEY = 'daily-grind:mock-account';
+const DAY = 24 * 60 * 60 * 1000;
+
+// Plays the role of the server's configured RP ID. A real backend returns its
+// own configured value; the client never derives it from the hostname.
+const RP_ID = location.hostname;
+const RP_NAME = 'The Daily Grind';
+
+function seed() {
+  const now = Date.now();
+  return {
+    user: {
+      passkeyUserId: 'ZGFpbHktZ3JpbmQtdXNlci0wMDQy', // base64url("daily-grind-user-0042")
+      name: 'sam.rivera@example.com',
+      displayName: 'Sam Rivera',
+    },
+    credentials: [
+      {
+        id: 'ZGctY3JlZC1waXhlbC04', // base64url("dg-cred-pixel-8")
+        name: 'Google Password Manager',
+        aaguid: 'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4',
+        registeredAt: now - 120 * DAY,
+        lastUsedAt: now - 2 * DAY,
+      },
+      {
+        id: 'ZGctY3JlZC1tYWNib29r', // base64url("dg-cred-macbook")
+        name: 'Work MacBook',
+        aaguid: 'fbfc3007-154e-4ecc-8c0b-6e020557d7bd',
+        registeredAt: now - 45 * DAY,
+        lastUsedAt: now - 9 * DAY,
+      },
+      {
+        id: 'ZGctY3JlZC15dWJpa2Vy', // base64url("dg-cred-yubiker")
+        name: 'YubiKey 5 Series',
+        aaguid: 'cb69481e-8ff7-4039-93ec-0a2729a154a8',
+        registeredAt: now - 300 * DAY,
+        lastUsedAt: null,
+      },
+    ],
+  };
+}
+
+function load() {
+  try {
+    const stored = JSON.parse(localStorage.getItem(STORAGE_KEY));
+    if (stored?.user && Array.isArray(stored.credentials)) return stored;
+  } catch { /* fall through to seed */ }
+  const data = seed();
+  save(data);
+  return data;
+}
+
+function save(data) {
+  localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
+}
+
+const latency = () => new Promise((r) => setTimeout(r, 250));
+
+function notFound() {
+  const error = new Error('Passkey not found.');
+  error.status = 404;
+  return error;
+}
+
+// Reads the AAGUID from authenticator data: rpIdHash(32) flags(1) signCount(4) aaguid(16).
+function aaguidFromAuthData(authenticatorDataB64) {
+  if (!authenticatorDataB64) return null;
+  const bytes = new Uint8Array(base64UrlToBuffer(authenticatorDataB64));
+  const hasAttestedData = bytes.length >= 53 && (bytes[32] & 0x40);
+  if (!hasAttestedData) return null;
+  const hex = [...bytes.slice(37, 53)].map((b) => b.toString(16).padStart(2, '0')).join('');
+  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
+}
+
+export function createMockBackend() {
+  let pendingChallenge = null;
+
+  return {
+    async listCredentials() {
+      await latency();
+      const { user, credentials } = load();
+      return {
+        rpId: RP_ID,
+        userId: user.passkeyUserId,
+        user: { name: user.name, displayName: user.displayName },
+        credentials: [...credentials].sort((a, b) => b.registeredAt - a.registeredAt),
+      };
+    },
+
+    async renameCredential(id, name) {
+      await latency();
+      const data = load();
+      const cred = data.credentials.find((c) => c.id === id);
+      if (!cred) throw notFound();
+      cred.name = String(name).trim().slice(0, 64);
+      save(data);
+      return cred;
+    },
+
+    async deleteCredential(id) {
+      await latency();
+      const data = load();
+      const before = data.credentials.length;
+      data.credentials = data.credentials.filter((c) => c.id !== id);
+      if (data.credentials.length === before) throw notFound();
+      save(data);
+      return { success: true };
+    },
+
+    async updateUser({ name, displayName }) {
+      await latency();
+      const data = load();
+      data.user.name = String(name).trim();
+      data.user.displayName = String(displayName).trim();
+      save(data);
+      return { name: data.user.name, displayName: data.user.displayName, rpId: RP_ID, userId: data.user.passkeyUserId };
+    },
+
+    async getRegistrationOptions() {
+      await latency();
+      const { user, credentials } = load();
+      pendingChallenge = randomBase64Url(32);
+      return {
+        challenge: pendingChallenge,
+        rp: { id: RP_ID, name: RP_NAME },
+        user: { id: user.passkeyUserId, name: user.name, displayName: user.displayName },
+        pubKeyCredParams: [
+          { type: 'public-key', alg: -7 },
+          { type: 'public-key', alg: -257 },
+        ],
+        timeout: 300000,
+        attestation: 'none',
+        excludeCredentials: credentials.map((c) => ({ type: 'public-key', id: c.id })),
+        // authenticatorAttachment omitted so security keys can be registered too.
+        authenticatorSelection: { residentKey: 'required', userVerification: 'preferred' },
+        hints: [],
+      };
+    },
+
+    async verifyRegistration(credential) {
+      await latency();
+      if (!pendingChallenge) throw new Error('Registration session expired. Please try again.');
+      pendingChallenge = null;
+      const data = load();
+      const now = Date.now();
+      const aaguid = aaguidFromAuthData(credential.response?.authenticatorData);
+      const record = {
+        id: credential.id,
+        name: describeProvider(aaguid).name,
+        aaguid,
+        registeredAt: now,
+        lastUsedAt: null,
+      };
+      data.credentials.push(record);
+      save(data);
+      return record;
+    },
+  };
+}
diff --git a/account/js/passkeys.js b/account/js/passkeys.js
new file mode 100644
index 0000000..19a2bbe
--- /dev/null
+++ b/account/js/passkeys.js
@@ -0,0 +1,254 @@
+import { api } from './api.js';
+import { describeProvider } from './aaguids.js';
+import {
+  createPasskey,
+  isPasskeySupported,
+  signalAcceptedCredentials,
+  signalUserDetails,
+} from './webauthn.js';
+
+const $ = (selector) => document.querySelector(selector);
+
+const els = {
+  status: $('#status'),
+  list: $('#passkey-list'),
+  empty: $('#passkey-empty'),
+  rowTemplate: $('#passkey-row'),
+  heading: $('#passkeys-title'),
+  createButton: $('#create-passkey'),
+  unsupported: $('#passkey-unsupported'),
+  profileForm: $('#profile-form'),
+  renameDialog: $('#rename-dialog'),
+  renameInput: $('#rename-form [name="name"]'),
+  deleteDialog: $('#delete-dialog'),
+};
+
+const dateFormat = new Intl.DateTimeFormat(undefined, { dateStyle: 'medium' });
+
+/** Latest server state: { rpId, userId, user, credentials }. */
+let state = { rpId: null, userId: null, user: null, credentials: [] };
+
+// ---------- UI helpers ----------
+
+function announce(message, tone = 'info') {
+  els.status.dataset.tone = tone;
+  els.status.textContent = message;
+}
+
+function formatDate(epochMs) {
+  const date = new Date(epochMs);
+  return { text: dateFormat.format(date), iso: date.toISOString() };
+}
+
+function displayName(credential) {
+  return credential.name?.trim() || describeProvider(credential.aaguid).name;
+}
+
+async function withBusy(button, task) {
+  button.disabled = true;
+  try {
+    return await task();
+  } finally {
+    button.disabled = false;
+  }
+}
+
+/** Opens a modal dialog and resolves with the button value used to close it ('' if dismissed). */
+function openDialog(dialog) {
+  return new Promise((resolve) => {
+    dialog.addEventListener('close', () => {
+      const value = dialog.returnValue;
+      dialog.returnValue = '';
+      resolve(value);
+    }, { once: true });
+    dialog.showModal();
+  });
+}
+
+// ---------- Rendering ----------
+
+function renderCredentials(credentials) {
+  const rows = credentials.map((credential) => {
+    const row = els.rowTemplate.content.firstElementChild.cloneNode(true);
+    const provider = describeProvider(credential.aaguid);
+    const name = displayName(credential);
+    row.dataset.id = credential.id;
+
+    row.querySelector('.passkey-icon').src = provider.icon;
+    row.querySelector('.passkey-name').textContent = name;
+    row.querySelector('.passkey-provider').textContent = provider.name;
+
+    const created = formatDate(credential.registeredAt);
+    const createdEl = row.querySelector('.passkey-created');
+    createdEl.textContent = created.text;
+    createdEl.dateTime = created.iso;
+
+    const usedEl = row.querySelector('.passkey-used');
+    if (credential.lastUsedAt) {
+      const used = formatDate(credential.lastUsedAt);
+      usedEl.append('Last used ', Object.assign(document.createElement('time'), {
+        textContent: used.text,
+        dateTime: used.iso,
+      }));
+    } else {
+      usedEl.textContent = 'Never used';
+    }
+
+    for (const button of row.querySelectorAll('[data-action]')) {
+      const label = button.dataset.action === 'rename' ? 'Rename' : 'Delete';
+      button.setAttribute('aria-label', `${label} ${name}`);
+    }
+    return row;
+  });
+
+  els.list.replaceChildren(...rows);
+  els.list.hidden = credentials.length === 0;
+  els.empty.hidden = credentials.length !== 0;
+  els.list.setAttribute('aria-busy', 'false');
+}
+
+function renderProfile(user) {
+  if (!user) return;
+  els.profileForm.elements.name.value = user.name;
+  els.profileForm.elements.displayName.value = user.displayName;
+}
+
+/**
+ * Fetches the server's credential list and re-renders. With `sync`, also tells
+ * the browser's passkey provider which credentials are still accepted so
+ * passkeys deleted here (or elsewhere) are removed from the user's vault.
+ */
+async function refresh({ sync = false } = {}) {
+  state = await api.listCredentials();
+  renderCredentials(state.credentials);
+  if (sync) {
+    // Background sync: never blocks or breaks the UI.
+    signalAcceptedCredentials(state);
+  }
+}
+
+// ---------- Actions ----------
+
+async function renameCredential(credential, button) {
+  els.renameInput.value = displayName(credential);
+  const choice = await openDialog(els.renameDialog);
+  const newName = els.renameInput.value.trim();
+  if (choice !== 'save' || !newName || newName === displayName(credential)) return;
+
+  await withBusy(button, async () => {
+    try {
+      // A nickname is a server-side label only; nothing to signal to the authenticator.
+      await api.renameCredential(credential.id, newName);
+      await refresh();
+      announce(`Renamed passkey to "${newName}".`);
+    } catch (error) {
+      announce(`Couldn't rename the passkey. ${error.message}`, 'error');
+    }
+  });
+}
+
+async function deleteCredential(credential, button) {
+  const dialog = els.deleteDialog;
+  const name = displayName(credential);
+  dialog.querySelector('[data-slot="name"]').textContent = name;
+  dialog.querySelector('[data-slot="last-warning"]').hidden = state.credentials.length > 1;
+
+  if (await openDialog(dialog) !== 'delete') return;
+
+  await withBusy(button, async () => {
+    try {
+      await api.deleteCredential(credential.id);
+      await refresh({ sync: true });
+      announce(`Deleted "${name}".`);
+      // The invoking row is gone, so move focus somewhere stable.
+      els.heading.focus();
+    } catch (error) {
+      if (error.status === 404) {
+        await refresh({ sync: true });
+        announce(`"${name}" was already removed.`);
+        els.heading.focus();
+      } else {
+        announce(`Couldn't delete the passkey. ${error.message}`, 'error');
+      }
+    }
+  });
+}
+
+async function registerPasskey() {
+  await withBusy(els.createButton, async () => {
+    try {
+      const options = await api.getRegistrationOptions();
+      const credential = await createPasskey(options);
+      const saved = await api.verifyRegistration(credential);
+      await refresh({ sync: true });
+      announce(`Passkey created${saved?.name ? ` with ${saved.name}` : ''}.`);
+    } catch (error) {
+      if (error.name === 'NotAllowedError' || error.name === 'AbortError') {
+        announce('Passkey creation was cancelled.');
+      } else if (error.name === 'InvalidStateError') {
+        announce('You already have a passkey for this account on this device.', 'error');
+      } else {
+        announce(`Couldn't create a passkey. ${error.message}`, 'error');
+      }
+    }
+  });
+}
+
+async function saveProfile(event) {
+  event.preventDefault();
+  const form = els.profileForm;
+  const name = form.elements.name.value.trim();
+  const newDisplayName = form.elements.displayName.value.trim();
+  const button = form.querySelector('[type="submit"]');
+
+  await withBusy(button, async () => {
+    try {
+      const updated = await api.updateUser({ name, displayName: newDisplayName });
+      state.user = { name: updated.name, displayName: updated.displayName };
+      renderProfile(state.user);
+      announce('Profile saved.');
+      // Update the name shown for our passkeys in the user's password manager.
+      signalUserDetails({
+        rpId: updated.rpId,
+        userId: updated.userId,
+        name: updated.name,
+        displayName: updated.displayName,
+      });
+    } catch (error) {
+      announce(`Couldn't save your profile. ${error.message}`, 'error');
+    }
+  });
+}
+
+// ---------- Wiring ----------
+
+els.list.addEventListener('click', (event) => {
+  const button = event.target.closest('button[data-action]');
+  if (!button) return;
+  const id = button.closest('.passkey')?.dataset.id;
+  const credential = state.credentials.find((c) => c.id === id);
+  if (!credential) return;
+  if (button.dataset.action === 'rename') renameCredential(credential, button);
+  else if (button.dataset.action === 'delete') deleteCredential(credential, button);
+});
+
+els.createButton.addEventListener('click', registerPasskey);
+els.profileForm.addEventListener('submit', saveProfile);
+
+async function init() {
+  isPasskeySupported().then((supported) => {
+    els.createButton.hidden = !supported;
+    els.unsupported.hidden = supported;
+  });
+
+  try {
+    // Sync on page load so passkeys removed on other devices also leave this vault.
+    await refresh({ sync: true });
+    renderProfile(state.user);
+  } catch (error) {
+    els.list.setAttribute('aria-busy', 'false');
+    announce(`Couldn't load your passkeys. ${error.message}`, 'error');
+  }
+}
+
+init();
