@@ -0,0 +1,122 @@
+// WebAuthn helpers: Base64URL encoding, JSON (de)serialization fallbacks,
+// feature detection and the Signal API wrappers.
+
+export function isValidBase64Url(value) {
+  return typeof value === 'string' &&
+    value.length > 0 &&
+    value.length % 4 !== 1 &&
+    /^[A-Za-z0-9_-]+$/.test(value);
+}
+
+export function bufferToBase64Url(buffer) {
+  const bytes = buffer instanceof Uint8Array ? buffer : new Uint8Array(buffer);
+  let binary = '';
+  for (const b of bytes) binary += String.fromCharCode(b);
+  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+}
+
+export function base64UrlToBuffer(value) {
+  const base64 = value.replace(/-/g, '+').replace(/_/g, '/');
+  const padded = base64 + '='.repeat((4 - (base64.length % 4)) % 4);
+  return Uint8Array.from(atob(padded), (c) => c.charCodeAt(0)).buffer;
+}
+
+export function randomBase64Url(byteLength = 32) {
+  return bufferToBase64Url(crypto.getRandomValues(new Uint8Array(byteLength)));
+}
+
+/** True when this browser can create a passkey on a platform authenticator. */
+export async function isPasskeySupported() {
+  if (!window.PublicKeyCredential) return false;
+  try {
+    if (PublicKeyCredential.getClientCapabilities) {
+      const caps = await PublicKeyCredential.getClientCapabilities();
+      return Boolean(caps.passkeyPlatformAuthenticator);
+    }
+    // Pre-getClientCapabilities browsers: fall back to the older probe.
+    return await PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable();
+  } catch {
+    return false;
+  }
+}
+
+function parseCreationOptions(json) {
+  if (PublicKeyCredential.parseCreationOptionsFromJSON) {
+    return PublicKeyCredential.parseCreationOptionsFromJSON(json);
+  }
+  return {
+    ...json,
+    challenge: base64UrlToBuffer(json.challenge),
+    user: { ...json.user, id: base64UrlToBuffer(json.user.id) },
+    excludeCredentials: (json.excludeCredentials ?? []).map((c) => ({
+      ...c,
+      id: base64UrlToBuffer(c.id),
+    })),
+  };
+}
+
+function registrationToJSON(credential) {
+  if (typeof credential.toJSON === 'function') {
+    try {
+      return credential.toJSON();
+    } catch {
+      // Some password-manager extensions return objects whose toJSON throws.
+    }
+  }
+  const { response } = credential;
+  return {
+    id: credential.id,
+    rawId: bufferToBase64Url(credential.rawId),
+    type: credential.type,
+    authenticatorAttachment: credential.authenticatorAttachment ?? undefined,
+    clientExtensionResults: credential.getClientExtensionResults(),
+    response: {
+      clientDataJSON: bufferToBase64Url(response.clientDataJSON),
+      attestationObject: bufferToBase64Url(response.attestationObject),
+      authenticatorData: response.getAuthenticatorData
+        ? bufferToBase64Url(response.getAuthenticatorData())
+        : undefined,
+      transports: response.getTransports ? response.getTransports() : [],
+    },
+  };
+}
+
+/** Runs navigator.credentials.create() with server-provided JSON options. */
+export async function createPasskey(optionsJSON) {
+  const credential = await navigator.credentials.create({
+    publicKey: parseCreationOptions(optionsJSON),
+  });
+  return registrationToJSON(credential);
+}
+
+/**
+ * Tells the passkey provider which credential IDs are still valid, so deleted
+ * passkeys disappear from the user's password manager. Never throws.
+ */
+export async function signalAcceptedCredentials({ rpId, userId, credentials }) {
+  if (!window.PublicKeyCredential || !PublicKeyCredential.signalAllAcceptedCredentials) return;
+  const allAcceptedCredentialIds = credentials.map((c) => c.id);
+  if (!rpId || !isValidBase64Url(userId) || !allAcceptedCredentialIds.every(isValidBase64Url)) {
+    console.warn('signalAllAcceptedCredentials skipped: server rpId and valid Base64URL IDs are required.');
+    return;
+  }
+  try {
+    await PublicKeyCredential.signalAllAcceptedCredentials({ rpId, userId, allAcceptedCredentialIds });
+  } catch (e) {
+    console.warn('signalAllAcceptedCredentials sync warning:', e);
+  }
+}
+
+/** Updates the user name/display name shown for saved passkeys. Never throws. */
+export async function signalUserDetails({ rpId, userId, name, displayName }) {
+  if (!window.PublicKeyCredential || !PublicKeyCredential.signalCurrentUserDetails) return;
+  if (!rpId || !isValidBase64Url(userId)) {
+    console.warn('signalCurrentUserDetails skipped: server rpId and valid Base64URL userId are required.');
+    return;
+  }
+  try {
+    await PublicKeyCredential.signalCurrentUserDetails({ rpId, userId, name, displayName });
+  } catch (e) {
+    console.warn('signalCurrentUserDetails sync warning:', e);
+  }
+}
