+/**
+ * My Account → Passkeys
+ *
+ * Lets a signed-in customer list, rename and delete their registered passkeys,
+ * and keeps the browser / password manager in sync via the WebAuthn Signal API
+ * so deleted passkeys stop being offered at sign-in.
+ *
+ * Backend contract (same-origin, cookie session):
+ *
+ *   GET    /api/account/passkeys
+ *     200 → {
+ *       rpId: "dailygrind.example",
+ *       user: { id: "<base64url user handle>", name: "sam@example.com", displayName: "Sam" },
+ *       passkeys: [{
+ *         id: "pk_123",                     // server-side record id
+ *         credentialId: "<base64url>",      // WebAuthn credential id
+ *         name: "Sam's iPhone",
+ *         createdAt: "2026-01-02T10:00:00Z",
+ *         lastUsedAt: "2026-11-01T08:12:00Z" | null,
+ *         backedUp: true                    // synced passkey (BS flag)
+ *       }]
+ *     }
+ *   PATCH  /api/account/passkeys/:id   body { name }  → 200 updated passkey
+ *   DELETE /api/account/passkeys/:id                  → 204
+ *
+ *   401 on any call → session expired; we redirect to /login.
+ *
+ * Append `?demo` to the URL to try the UI against an in-memory mock (no network,
+ * and no signals are sent to the browser's authenticator).
+ */
+
+const API_BASE = '/api/account/passkeys';
+const NAME_MAX = 64;
+const DEMO = new URLSearchParams(location.search).has('demo');
+
+const els = {
+  greeting: document.getElementById('greeting'),
+  status: document.getElementById('passkeys-status'),
+  list: document.getElementById('passkey-list'),
+  syncNote: document.getElementById('sync-note'),
+  refresh: document.getElementById('refresh-btn'),
+  toast: document.getElementById('toast'),
+  renameDialog: document.getElementById('rename-dialog'),
+  renameForm: document.getElementById('rename-form'),
+  renameInput: document.getElementById('rename-input'),
+  renameError: document.getElementById('rename-error'),
+  renameSubmit: document.getElementById('rename-submit'),
+  deleteDialog: document.getElementById('delete-dialog'),
+  deleteForm: document.getElementById('delete-form'),
+  deleteName: document.getElementById('delete-name'),
+  deleteWarning: document.getElementById('delete-last-warning'),
+  deleteError: document.getElementById('delete-error'),
+  deleteSubmit: document.getElementById('delete-submit'),
+};
+
+/** @type {{ rpId: string, user: {id: string, name: string, displayName: string}, passkeys: any[] } | null} */
+let state = null;
+let activePasskey = null;
+
+/* -------------------------------------------------------------------------- */
+/* API                                                                        */
+/* -------------------------------------------------------------------------- */
+
+class ApiError extends Error {
+  constructor(message, status) {
+    super(message);
+    this.status = status;
+  }
+}
+
+function csrfHeaders() {
+  const token = document.querySelector('meta[name="csrf-token"]')?.content;
+  return token ? { 'X-CSRF-Token': token } : {};
+}
+
+async function request(path, { method = 'GET', body } = {}) {
+  let res;
+  try {
+    res = await fetch(API_BASE + path, {
+      method,
+      credentials: 'same-origin',
+      headers: {
+        Accept: 'application/json',
+        ...(body !== undefined ? { 'Content-Type': 'application/json' } : {}),
+        ...(method !== 'GET' ? csrfHeaders() : {}),
+      },
+      body: body !== undefined ? JSON.stringify(body) : undefined,
+    });
+  } catch {
+    throw new ApiError('We couldn\'t reach the server. Check your connection and try again.', 0);
+  }
+
+  if (res.status === 401) {
+    location.assign('/login?next=' + encodeURIComponent(location.pathname));
+    throw new ApiError('Your session has expired. Please sign in again.', 401);
+  }
+
+  if (!res.ok) {
+    let message = 'Something went wrong. Please try again.';
+    try {
+      const data = await res.json();
+      if (data && typeof data.message === 'string') message = data.message;
+      else if (data && typeof data.error === 'string') message = data.error;
+    } catch { /* non-JSON error body */ }
+    throw new ApiError(message, res.status);
+  }
+
+  if (res.status === 204) return null;
+  return res.json();
+}
+
+const realApi = {
+  list: () => request(''),
+  rename: (id, name) => request('/' + encodeURIComponent(id), { method: 'PATCH', body: { name } }),
+  remove: (id) => request('/' + encodeURIComponent(id), { method: 'DELETE' }),
+};
+
+function createDemoApi() {
+  const day = 86400000;
+  const now = Date.now();
+  const db = {
+    rpId: location.hostname,
+    user: { id: 'ZGVtby11c2Vy', name: 'sam@example.com', displayName: 'Sam' },
+    passkeys: [
+      { id: 'pk_1', credentialId: 'Y3JlZC0x', name: 'iPhone 16', createdAt: new Date(now - 200 * day).toISOString(), lastUsedAt: new Date(now - 2 * 3600000).toISOString(), backedUp: true },
+      { id: 'pk_2', credentialId: 'Y3JlZC0y', name: 'Work laptop', createdAt: new Date(now - 90 * day).toISOString(), lastUsedAt: new Date(now - 12 * day).toISOString(), backedUp: true },
+      { id: 'pk_3', credentialId: 'Y3JlZC0z', name: 'YubiKey 5C', createdAt: new Date(now - 400 * day).toISOString(), lastUsedAt: null, backedUp: false },
+    ],
+  };
+  const delay = (v) => new Promise((r) => setTimeout(() => r(structuredClone(v)), 300));
+  return {
+    list: () => delay(db),
+    rename: (id, name) => {
+      const pk = db.passkeys.find((p) => p.id === id);
+      if (!pk) return Promise.reject(new ApiError('That passkey no longer exists.', 404));
+      pk.name = name;
+      return delay(pk);
+    },
+    remove: (id) => {
+      db.passkeys = db.passkeys.filter((p) => p.id !== id);
+      return delay(null);
+    },
+  };
+}
+
+const api = DEMO ? createDemoApi() : realApi;
+
+/* -------------------------------------------------------------------------- */
+/* WebAuthn Signal API — keep the authenticator / password manager in sync    */
+/* -------------------------------------------------------------------------- */
+
+const signalSupported = typeof window.PublicKeyCredential !== 'undefined' &&
+  typeof PublicKeyCredential.signalAllAcceptedCredentials === 'function';
+
+/**
+ * Tell the browser exactly which credential IDs the server still accepts for
+ * this user. Passkeys not in the list are hidden/removed by supporting
+ * password managers, so deleted keys stop showing in the sign-in prompt.
+ * Only ever called with the authoritative list returned by the server.
+ */
+async function syncAcceptedCredentials(data) {
+  if (DEMO || !data?.rpId || !data?.user?.id) return;
+  try {
+    if (signalSupported) {
+      await PublicKeyCredential.signalAllAcceptedCredentials({
+        rpId: data.rpId,
+        userId: data.user.id,
+        allAcceptedCredentialIds: data.passkeys.map((p) => p.credentialId).filter(Boolean),
+      });
+    }
+    if (typeof PublicKeyCredential?.signalCurrentUserDetails === 'function' && data.user.name) {
+      await PublicKeyCredential.signalCurrentUserDetails({
+        rpId: data.rpId,
+        userId: data.user.id,
+        name: data.user.name,
+        displayName: data.user.displayName || data.user.name,
+      });
+    }
+  } catch (err) {
+    // Signals are best-effort; the server is the source of truth.
+    console.warn('[passkeys] authenticator sync failed:', err);
+  }
+}
+
+/**
