+/**
+ * Subset of the community AAGUID registry
+ * (https://github.com/passkeydeveloper/passkey-authenticator-aaguids).
+ * AAGUIDs are UX hints only — never use them for security decisions.
+ */
+export interface PasskeyProvider {
+  name: string;
+  /** Tailwind classes for the provider badge. */
+  badge: string;
+}
+
+const ZERO_AAGUID = '00000000-0000-0000-0000-000000000000';
+
+const PROVIDERS: Record<string, PasskeyProvider> = {
+  'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4': { name: 'Google Password Manager', badge: 'bg-blue-100 text-blue-800' },
+  'adce0002-35bc-c60a-648b-0b25f1f05503': { name: 'Chrome on Mac', badge: 'bg-blue-100 text-blue-800' },
+  'fbfc3007-154e-4ecc-8c0b-6e020557d7bd': { name: 'iCloud Keychain', badge: 'bg-gray-200 text-gray-800' },
+  '08987058-cadc-4b81-b6e1-30de50dcbe96': { name: 'Windows Hello', badge: 'bg-sky-100 text-sky-800' },
+  '9ddd1817-af5a-4672-a2b9-3e3dd95000a9': { name: 'Windows Hello', badge: 'bg-sky-100 text-sky-800' },
+  'bada5566-a7aa-401f-bd96-45619a55120d': { name: '1Password', badge: 'bg-indigo-100 text-indigo-800' },
+  'd548826e-79b4-db40-a3d8-11116f7e8349': { name: 'Bitwarden', badge: 'bg-indigo-100 text-indigo-800' },
+  '531126d6-e717-415c-9320-3d9aa6981239': { name: 'Dashlane', badge: 'bg-teal-100 text-teal-800' },
+  'b5397666-4885-aa6b-cebf-e52262a439a2': { name: 'Chromium Browser', badge: 'bg-blue-100 text-blue-800' },
+};
+
+const UNKNOWN: PasskeyProvider = { name: 'Unknown passkey provider', badge: 'bg-amber-100 text-amber-800' };
+
+export function lookupProvider(aaguid: string | undefined): PasskeyProvider {
+  if (!aaguid || aaguid === ZERO_AAGUID) return UNKNOWN;
+  return PROVIDERS[aaguid.toLowerCase()] ?? UNKNOWN;
+}
