new file mode 100644
index 0000000..bfc7c6d
--- /dev/null
+++ b/src/lib/account.ts
@@ -0,0 +1,147 @@
+/**
+ * Server-side account + passkey store for The DevTools Times.
+ *
+ * Accounts live in the Astro session (the same storage that backs the reading
+ * list). There is no WebAuthn registration ceremony in this demo app yet, so a
+ * reader who signs in gets a few seeded passkeys to manage. All credential IDs
+ * and the WebAuthn user handle are unpadded Base64URL strings, because the
+ * browser's Signal API rejects anything else.
+ */
+
+export interface AccountUser {
+  /** Username (WebAuthn `user.name`). */
+  name: string;
+  /** Human-friendly name (WebAuthn `user.displayName`). */
+  displayName: string;
+  /** WebAuthn user handle, unpadded Base64URL. */
+  passkeyUserId: string;
+}
+
+export interface StoredPasskeyCredential {
+  /** Credential ID, unpadded Base64URL. */
+  id: string;
+  /** User-editable nickname. */
+  name: string;
+  /** Authenticator model identifier, used for UX hints only. */
+  aaguid: string;
+  /** Epoch milliseconds. */
+  registeredAt: number;
+  /** Epoch milliseconds. */
+  lastUsedAt?: number;
+}
+
+export interface Account {
+  user: AccountUser;
+  credentials: StoredPasskeyCredential[];
+}
+
+type Session = NonNullable<import('astro').APIContext['session']>;
+
+const SESSION_KEY = 'account';
+export const MAX_NAME_LENGTH = 64;
+
+/**
+ * The RP ID the passkeys were registered against. Configure it explicitly in
+ * production (it may be a registrable parent domain of the serving host);
+ * otherwise fall back to the host serving this request.
+ */
+export function getRpId(request: Request): string {
+  return import.meta.env.PASSKEY_RP_ID || new URL(request.url).hostname;
+}
+
+function randomBase64Url(byteLength: number): string {
+  const bytes = crypto.getRandomValues(new Uint8Array(byteLength));
+  return Buffer.from(bytes).toString('base64url');
+}
+
+const DAY = 24 * 60 * 60 * 1000;
+
+function seedCredentials(now = Date.now()): StoredPasskeyCredential[] {
+  return [
+    {
+      id: randomBase64Url(32),
+      name: 'Google Password Manager',
+      aaguid: 'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4',
+      registeredAt: now - 120 * DAY,
+      lastUsedAt: now - 1 * DAY,
+    },
+    {
+      id: randomBase64Url(32),
+      name: 'iCloud Keychain',
+      aaguid: 'fbfc3007-154e-4ecc-8c0b-6e020557d7bd',
+      registeredAt: now - 64 * DAY,
+      lastUsedAt: now - 9 * DAY,
+    },
+    {
+      id: randomBase64Url(32),
+      name: 'Security key',
+      aaguid: '00000000-0000-0000-0000-000000000000',
+      registeredAt: now - 300 * DAY,
+    },
+  ];
+}
+
+export async function getAccount(session: Session | undefined): Promise<Account | null> {
+  if (!session) return null;
+  return ((await session.get(SESSION_KEY)) as Account | undefined) ?? null;
+}
+
+export function saveAccount(session: Session, account: Account): void {
+  session.set(SESSION_KEY, account);
+}
+
+export async function signInAccount(session: Session, username: string): Promise<Account> {
+  const existing = await getAccount(session);
+  if (existing && existing.user.name === username) return existing;
+
+  const account: Account = {
+    user: {
+      name: username,
+      displayName: username,
+      passkeyUserId: randomBase64Url(16),
+    },
+    credentials: seedCredentials(),
+  };
+  // New identity: rotate the session ID to prevent session fixation.
+  await session.regenerate();
+  session.set(SESSION_KEY, account);
+  return account;
+}
+
+export async function signOutAccount(session: Session): Promise<void> {
+  session.delete(SESSION_KEY);
+  await session.regenerate();
+}
+
+/** Trim, collapse whitespace, strip control chars; returns null when invalid. */
+export function sanitizeName(value: unknown): string | null {
+  if (typeof value !== 'string') return null;
+  const cleaned = value.replace(/[\u0000-\u001f\u007f]/g, '').replace(/\s+/g, ' ').trim();
+  if (!cleaned || cleaned.length > MAX_NAME_LENGTH) return null;
+  return cleaned;
+}
+
+export function json(body: unknown, init: ResponseInit = {}): Response {
+  return new Response(JSON.stringify(body), {
+    ...init,
+    headers: {
+      'Content-Type': 'application/json',
+      'Cache-Control': 'no-store',
+      ...init.headers,
+    },
+  });
+}
+
+export const unauthorized = () => json({ error: 'Not signed in.' }, { status: 401 });
+
+/**
+ * Basic CSRF defense for state-changing JSON endpoints: Astro's checkOrigin is
+ * disabled for this app, so require a same-origin request explicitly.
+ */
+export function isSameOrigin(request: Request): boolean {
+  const origin = request.headers.get('origin');
+  if (origin) return origin === new URL(request.url).origin;
+  return request.headers.get('sec-fetch-site') === 'same-origin';
+}
+
+export const forbidden = () => json({ error: 'Cross-origin request rejected.' }, { status: 403 });
