+import type { APIRoute } from 'astro';
+import {
+  forbidden,
+  getAccount,
+  isSameOrigin,
+  json,
+  sanitizeName,
+  saveAccount,
+  unauthorized,
+} from '../../../../lib/account';
+
+const notFound = () => json({ error: 'Passkey not found.' }, { status: 404 });
+
+/** Renames a passkey (server-side nickname only). */
+export const PUT: APIRoute = async ({ params, request, session }) => {
+  if (!isSameOrigin(request)) return forbidden();
+  const account = await getAccount(session);
+  if (!account || !session) return unauthorized();
+
+  const credential = account.credentials.find((c) => c.id === params.id);
+  if (!credential) return notFound();
+
+  const body = await request.json().catch(() => ({}));
+  const name = sanitizeName(body?.name);
+  if (!name) return json({ error: 'Enter a name between 1 and 64 characters.' }, { status: 400 });
+
+  credential.name = name;
+  saveAccount(session, account);
+  return json(credential);
+};
+
+/** Removes a passkey from the account. */
+export const DELETE: APIRoute = async ({ params, request, session }) => {
+  if (!isSameOrigin(request)) return forbidden();
+  const account = await getAccount(session);
+  if (!account || !session) return unauthorized();
+
+  const remaining = account.credentials.filter((c) => c.id !== params.id);
+  if (remaining.length === account.credentials.length) return notFound();
+
+  account.credentials = remaining;
+  saveAccount(session, account);
+  return json({ success: true });
+};
