+import type { APIRoute } from 'astro';
+import { getAccount, getRpId, json, unauthorized } from '../../../../lib/account';
+
+/** Lists the signed-in reader's passkeys with the server's RP ID and user handle. */
+export const GET: APIRoute = async ({ request, session }) => {
+  const account = await getAccount(session);
+  if (!account) return unauthorized();
+
+  return json({
+    rpId: getRpId(request),
+    userId: account.user.passkeyUserId,
+    credentials: [...account.credentials].sort((a, b) => b.registeredAt - a.registeredAt),
+  });
+};
