+import type { APIRoute } from 'astro';
+import {
+  forbidden,
+  getAccount,
+  getRpId,
+  isSameOrigin,
+  json,
+  sanitizeName,
+  saveAccount,
+  unauthorized,
+} from '../../../lib/account';
+
+/**
+ * Updates the reader's display name. The username stays tied to the Times
+ * auth service, so only `displayName` is editable here.
+ */
+export const PUT: APIRoute = async ({ request, session }) => {
+  if (!isSameOrigin(request)) return forbidden();
+  const account = await getAccount(session);
+  if (!account || !session) return unauthorized();
+
+  const body = await request.json().catch(() => ({}));
+  const displayName = sanitizeName(body?.displayName);
+  if (!displayName) {
+    return json({ error: 'Enter a display name between 1 and 64 characters.' }, { status: 400 });
+  }
+
+  account.user.displayName = displayName;
+  saveAccount(session, account);
+
+  return json({
+    name: account.user.name,
+    displayName: account.user.displayName,
+    rpId: getRpId(request),
+    userId: account.user.passkeyUserId,
+  });
+};
