+++ b/src/pages/api/auth/signin.ts
@@ -0,0 +1,34 @@
+import type { APIRoute } from 'astro';
+import { forbidden, isSameOrigin, json, sanitizeName, signInAccount } from '../../../lib/account';
+
+const LOGIN_URL = 'https://us-central1-web-devrel-apps.cloudfunctions.net/times_cdn/api/login';
+
+/**
+ * Proxies the sign-in to the Times auth service and, on success, records the
+ * signed-in reader in the session so account settings can be served.
+ * The upstream status and body are passed through unchanged.
+ */
+export const POST: APIRoute = async ({ request, session }) => {
+  if (!isSameOrigin(request)) return forbidden();
+
+  let body: { username?: unknown; password?: unknown };
+  try {
+    body = await request.json();
+  } catch {
+    return json({ error: 'Invalid request body.' }, { status: 400 });
+  }
+
+  const upstream = await fetch(LOGIN_URL, {
+    method: 'POST',
+    headers: { 'Content-Type': 'application/json' },
+    body: JSON.stringify({ username: body.username, password: body.password }),
+  });
+  const data = await upstream.json().catch(() => ({}));
+
+  if (upstream.ok && session) {
+    const username = sanitizeName(body.username);
+    if (username) await signInAccount(session, username);
+  }
+
+  return json(data, { status: upstream.status });
+};
