+import type { APIRoute } from 'astro';
+import { signOutAccount } from '../../../lib/account';
+
+// Plain form POST from the header; SameSite=Lax session cookies are not sent on
+// cross-site POSTs, so this cannot be triggered by another site.
+export const POST: APIRoute = async ({ session, redirect }) => {
+  if (session) await signOutAccount(session);
+  return redirect(import.meta.env.BASE_URL, 303);
+};
