@@ -0,0 +1,475 @@
+import React, { useEffect, useId, useRef, useState } from 'react';
+import {
+  KeyIcon,
+  PencilSquareIcon,
+  TrashIcon,
+  PlusIcon,
+  CloudIcon,
+  DevicePhoneMobileIcon,
+  ArrowPathIcon,
+} from '@heroicons/react/24/outline';
+import type { PasskeyListResponse, PasskeySummary } from '../lib/passkeys';
+import {
+  createPasskey,
+  isWebAuthnSupported,
+  signalAcceptedCredentials,
+  signalSupport,
+  signalUserDetails,
+  type SignalSupport,
+} from '../lib/webauthnClient';
+
+const API = `${import.meta.env.BASE_URL}api/account`;
+const MAX_LABEL = 64;
+
+type Status = { kind: 'success' | 'error' | 'info'; message: string } | null;
+
+async function request<T>(path: string, init: RequestInit = {}): Promise<T> {
+  const res = await fetch(`${API}${path}`, {
+    credentials: 'same-origin',
+    ...init,
+    headers: init.body ? { 'Content-Type': 'application/json', ...init.headers } : init.headers,
+  });
+  const data = await res.json().catch(() => ({}));
+  if (!res.ok) {
+    if (res.status === 401) {
+      window.location.href = `${import.meta.env.BASE_URL}signin`;
+    }
+    throw new Error(data?.error || `Request failed (${res.status})`);
+  }
+  return data as T;
+}
+
+const dateFormat = new Intl.DateTimeFormat('en-US', {
+  year: 'numeric',
+  month: 'short',
+  day: 'numeric',
+});
+
+function formatDate(iso: string | null) {
+  return iso ? dateFormat.format(new Date(iso)) : null;
+}
+
+interface Props {
+  initial: PasskeyListResponse;
+}
+
+export default function PasskeyManager({ initial }: Props) {
+  const [data, setData] = useState<PasskeyListResponse>(initial);
+  const [status, setStatus] = useState<Status>(null);
+  const [creating, setCreating] = useState(false);
+  const [supported, setSupported] = useState(true);
+  const [signals, setSignals] = useState<SignalSupport>({
+    acceptedCredentials: false,
+    userDetails: false,
+  });
+
+  /** Push the server's view of this account to the browser's authenticator. */
+  const syncAuthenticator = async (next: PasskeyListResponse, { credentials = true, details = true } = {}) => {
+    await Promise.all([
+      credentials &&
+        signalAcceptedCredentials(next.rpId, next.userId, next.passkeys.map((p) => p.id)),
+      details && signalUserDetails(next.rpId, next.userId, next.username, next.displayName),
+    ]);
+  };
+
+  // On first view, reconcile the authenticator with the server so passkeys
+  // removed elsewhere (or on another device) stop being offered.
+  useEffect(() => {
+    setSupported(isWebAuthnSupported());
+    setSignals(signalSupport());
+    void syncAuthenticator(initial);
+    // eslint-disable-next-line react-hooks/exhaustive-deps
+  }, []);
+
+  const handleCreate = async () => {
+    setStatus(null);
+    setCreating(true);
+    try {
+      const options = await request<Record<string, any>>('/passkeys/options', {
+        method: 'POST',
+        body: '{}',
+      });
+      const credential = await createPasskey(options);
+      const next = await request<PasskeyListResponse>('/passkeys', {
+        method: 'POST',
+        body: JSON.stringify(credential),
+      });
+      setData(next);
+      setStatus({ kind: 'success', message: 'Passkey created. You can rename it below.' });
+    } catch (err: any) {
+      if (err?.name === 'NotAllowedError' || err?.name === 'AbortError') {
+        setStatus({ kind: 'info', message: 'Passkey creation was cancelled.' });
+      } else if (err?.name === 'InvalidStateError') {
+        setStatus({
+          kind: 'info',
+          message: 'This device already has a passkey for your account.',
+        });
+      } else {
+        setStatus({ kind: 'error', message: err?.message || 'Could not create a passkey.' });
+      }
+    } finally {
+      setCreating(false);
+    }
+  };
+
+  const handleRename = async (passkey: PasskeySummary, name: string) => {
+    setStatus(null);
+    const next = await request<PasskeyListResponse>(
+      `/passkeys/${encodeURIComponent(passkey.id)}`,
+      { method: 'PATCH', body: JSON.stringify({ name }) },
+    );
+    setData(next);
+    setStatus({ kind: 'success', message: `Renamed passkey to “${name}”.` });
+  };
+
+  const handleRemove = async (passkey: PasskeySummary) => {
+    setStatus(null);
+    const next = await request<PasskeyListResponse>(
+      `/passkeys/${encodeURIComponent(passkey.id)}`,
+      { method: 'DELETE' },
+    );
+    setData(next);
+    await syncAuthenticator(next, { details: false });
+    setStatus({
+      kind: 'success',
+      message: signals.acceptedCredentials
+        ? `Removed “${passkey.name}”. Your browser was told to stop offering it.`
+        : `Removed “${passkey.name}”. You may also want to delete it from your password manager.`,
+    });
+  };
+
+  const handleDisplayName = async (displayName: string) => {
+    setStatus(null);
+    const next = await request<PasskeyListResponse>('/profile', {
+      method: 'PATCH',
+      body: JSON.stringify({ displayName }),
+    });
+    setData(next);
+    await syncAuthenticator(next, { credentials: false });
+    setStatus({
+      kind: 'success',
+      message: signals.userDetails
+        ? 'Display name updated here and in your passkey provider.'
+        : 'Display name updated.',
+    });
+  };
+
+  return (
+    <section
+      aria-labelledby="passkeys-heading"
+      className="bg-white border border-gray-200 rounded-lg shadow-sm"
+    >
+      <div className="p-6 border-b border-gray-200 flex flex-col sm:flex-row sm:items-start sm:justify-between gap-4">
+        <div>
+          <h2 id="passkeys-heading" className="text-xl font-bold text-gray-900 flex items-center gap-2">
+            <KeyIcon className="w-6 h-6" aria-hidden="true" />
+            Passkeys
+          </h2>
+          <p className="mt-1 text-sm text-gray-600 max-w-prose">
+            Passkeys let you sign in with your fingerprint, face, screen lock or security key
+            instead of a password. Manage the passkeys registered to{' '}
+            <span className="font-semibold">{data.username}</span>.
+          </p>
+        </div>
+        <button
+          type="button"
+          onClick={handleCreate}
+          disabled={!supported || creating}
+          className="inline-flex items-center justify-center gap-1.5 shrink-0 py-2 px-4 rounded-md text-sm font-medium text-white bg-gray-900 hover:bg-gray-800 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-900 disabled:opacity-60 disabled:cursor-not-allowed"
+        >
+          {creating ? (
+            <ArrowPathIcon className="w-4 h-4 animate-spin" aria-hidden="true" />
+          ) : (
+            <PlusIcon className="w-4 h-4" aria-hidden="true" />
+          )}
+          {creating ? 'Waiting for device…' : 'Create a passkey'}
+        </button>
+      </div>
+
+      <div aria-live="polite" className="px-6 empty:hidden">
+        {status && (
+          <div
+            role={status.kind === 'error' ? 'alert' : 'status'}
+            className={`mt-4 p-3 text-sm rounded-lg ${
+              status.kind === 'error'
+                ? 'text-red-700 bg-red-100'
+                : status.kind === 'success'
+                  ? 'text-green-700 bg-green-100'
+                  : 'text-gray-700 bg-gray-100'
+            }`}
+          >
+            {status.message}
+          </div>
+        )}
+      </div>
+
+      {!supported && (
+        <p className="mx-6 mt-4 p-3 text-sm text-amber-800 bg-amber-50 rounded-lg">
+          This browser doesn’t support passkeys. You can still rename or remove existing ones.
+        </p>
+      )}
+
+      <DisplayNameForm
+        value={data.displayName}
+        onSave={handleDisplayName}
+        onError={(message) => setStatus({ kind: 'error', message })}
+      />
+
+      {data.passkeys.length === 0 ? (
+        <div className="p-6 text-center text-sm text-gray-600">
+          <KeyIcon className="w-10 h-10 mx-auto text-gray-300" aria-hidden="true" />
+          <p className="mt-2 font-medium text-gray-800">No passkeys yet</p>
+          <p>Create one to sign in faster and more securely.</p>
+        </div>
+      ) : (
+        <ul className="divide-y divide-gray-200" aria-label="Registered passkeys">
+          {data.passkeys.map((passkey) => (
+            <PasskeyRow
+              key={passkey.id}
+              passkey={passkey}
+              onRename={handleRename}
+              onRemove={handleRemove}
+              onError={(message) => setStatus({ kind: 'error', message })}
+            />
+          ))}
+        </ul>
+      )}
+
+      <p className="px-6 py-4 border-t border-gray-200 text-xs text-gray-500">
+        {signals.acceptedCredentials || signals.userDetails
+          ? 'Changes you make here are automatically shared with your browser’s passkey provider, so removed passkeys stop appearing when you sign in.'
+          : 'Your browser can’t be updated automatically. After removing a passkey here, also delete it from your password manager or device settings.'}
+      </p>
+    </section>
+  );
+}
+
+function DisplayNameForm({
+  value,
+  onSave,
+  onError,
+}: {
+  value: string;
+  onSave: (value: string) => Promise<void>;
+  onError: (message: string) => void;
+}) {
+  const id = useId();
+  const [draft, setDraft] = useState(value);
+  const [saving, setSaving] = useState(false);
+  useEffect(() => setDraft(value), [value]);
+
+  const trimmed = draft.trim();
+  const dirty = trimmed !== value;
+
+  const submit = async (e: React.FormEvent) => {
+    e.preventDefault();
+    if (!trimmed || !dirty) return;
+    setSaving(true);
+    try {
+      await onSave(trimmed);
+    } catch (err: any) {
+      onError(err?.message || 'Could not update display name.');
+    } finally {
+      setSaving(false);
+    }
+  };
+
+  return (
+    <form onSubmit={submit} className="p-6 border-b border-gray-200">
+      <label htmlFor={id} className="block text-sm font-medium text-gray-700">
+        Display name
+      </label>
+      <p className="text-xs text-gray-500 mb-2">
+        Shown next to your passkeys in your browser or password manager.
+      </p>
+      <div className="flex gap-2 max-w-md">
+        <input
+          id={id}
+          type="text"
+          value={draft}
+          maxLength={MAX_LABEL}
+          required
+          onChange={(e) => setDraft(e.target.value)}
+          className="flex-1 min-w-0 px-3 py-2 border border-gray-300 rounded-md text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
+        />
+        <button
+          type="submit"
+          disabled={!dirty || !trimmed || saving}
+          className="py-2 px-4 rounded-md text-sm font-medium border border-gray-300 text-gray-800 hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
+        >
+          {saving ? 'Saving…' : 'Save'}
+        </button>
+      </div>
+    </form>
+  );
+}
+
+function PasskeyRow({
+  passkey,
+  onRename,
+  onRemove,
+  onError,
+}: {
+  passkey: PasskeySummary;
+  onRename: (passkey: PasskeySummary, name: string) => Promise<void>;
+  onRemove: (passkey: PasskeySummary) => Promise<void>;
+  onError: (message: string) => void;
+}) {
+  const [mode, setMode] = useState<'view' | 'rename' | 'confirm-remove'>('view');
+  const [draft, setDraft] = useState(passkey.name);
+  const [busy, setBusy] = useState(false);
+  const inputRef = useRef<HTMLInputElement>(null);
+  const inputId = useId();
+
+  useEffect(() => {
+    if (mode === 'rename') inputRef.current?.select();
+  }, [mode]);
+
+  const run = async (fn: () => Promise<void>, fallback: string) => {
+    setBusy(true);
+    try {
+      await fn();
+      setMode('view');
+    } catch (err: any) {
+      onError(err?.message || fallback);
+    } finally {
+      setBusy(false);
+    }
+  };
+
+  const submitRename = (e: React.FormEvent) => {
+    e.preventDefault();
+    const name = draft.trim();
+    if (!name || name === passkey.name) {
+      setMode('view');
+      return;
+    }
+    void run(() => onRename(passkey, name), 'Could not rename passkey.');
+  };
+
+  const details = [
+    passkey.provider,
+    `Created ${formatDate(passkey.createdAt)}`,
+    passkey.lastUsedAt ? `Last used ${formatDate(passkey.lastUsedAt)}` : 'Not used to sign in yet',
+  ].filter(Boolean);
+
+  const DeviceIcon = passkey.synced ? CloudIcon : DevicePhoneMobileIcon;
+
+  return (
+    <li className="p-6 flex flex-col sm:flex-row sm:items-center gap-4">
+      <div className="flex items-start gap-3 flex-1 min-w-0">
+        <span className="mt-0.5 p-2 rounded-full bg-gray-100 text-gray-700" aria-hidden="true">
+          <DeviceIcon className="w-5 h-5" />
+        </span>
+        <div className="flex-1 min-w-0">
+          {mode === 'rename' ? (
+            <form onSubmit={submitRename} className="flex flex-wrap gap-2">
+              <label htmlFor={inputId} className="sr-only">
+                Passkey name
+              </label>
+              <input
+                id={inputId}
+                ref={inputRef}
+                type="text"
+                value={draft}
+                maxLength={MAX_LABEL}
+                required
+                disabled={busy}
+                onChange={(e) => setDraft(e.target.value)}
+                onKeyDown={(e) => {
+                  if (e.key === 'Escape') {
+                    setDraft(passkey.name);
+                    setMode('view');
+                  }
+                }}
+                className="flex-1 min-w-[12rem] px-3 py-1.5 border border-gray-300 rounded-md text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
+              />
+              <button
+                type="submit"
+                disabled={busy || !draft.trim()}
+                className="py-1.5 px-3 rounded-md text-sm font-medium text-white bg-gray-900 hover:bg-gray-800 disabled:opacity-60"
+              >
+                {busy ? 'Saving…' : 'Save'}
+              </button>
+              <button
+                type="button"
+                disabled={busy}
+                onClick={() => {
+                  setDraft(passkey.name);
+                  setMode('view');
+                }}
+                className="py-1.5 px-3 rounded-md text-sm font-medium border border-gray-300 text-gray-800 hover:bg-gray-50"
+              >
+                Cancel
+              </button>
+            </form>
+          ) : (
+            <p className="font-semibold text-gray-900 truncate">{passkey.name}</p>
+          )}
+          <p className="mt-0.5 text-xs text-gray-500">
+            <span
+              className={`inline-block mr-2 px-1.5 py-0.5 rounded text-[11px] font-medium ${
+                passkey.synced ? 'bg-blue-50 text-blue-700' : 'bg-gray-100 text-gray-700'
+              }`}
+            >
+              {passkey.synced ? 'Synced' : 'This device only'}
+            </span>
+            {details.join(' · ')}
+          </p>
+        </div>
+      </div>
+
+      {mode === 'confirm-remove' ? (
+        <div
+          role="group"
+          aria-label={`Confirm removing ${passkey.name}`}
+          className="flex flex-wrap items-center gap-2 text-sm"
+        >
+          <span className="text-gray-700">Remove this passkey?</span>
+          <button
+            type="button"
+            disabled={busy}
+            onClick={() => run(() => onRemove(passkey), 'Could not remove passkey.')}
+            className="py-1.5 px-3 rounded-md font-medium text-white bg-red-600 hover:bg-red-700 disabled:opacity-60"
+          >
+            {busy ? 'Removing…' : 'Remove'}
+          </button>
+          <button
+            type="button"
+            disabled={busy}
+            onClick={() => setMode('view')}
+            className="py-1.5 px-3 rounded-md font-medium border border-gray-300 text-gray-800 hover:bg-gray-50"
+          >
+            Keep
+          </button>
+        </div>
+      ) : (
+        mode === 'view' && (
+          <div className="flex gap-2">
+            <button
+              type="button"
+              onClick={() => {
+                setDraft(passkey.name);
+                setMode('rename');
+              }}
+              className="inline-flex items-center gap-1 py-1.5 px-3 rounded-md text-sm font-medium border border-gray-300 text-gray-800 hover:bg-gray-50"
+              aria-label={`Rename ${passkey.name}`}
+            >
+              <PencilSquareIcon className="w-4 h-4" aria-hidden="true" />
+              Rename
+            </button>
+            <button
+              type="button"
+              onClick={() => setMode('confirm-remove')}
+              className="inline-flex items-center gap-1 py-1.5 px-3 rounded-md text-sm font-medium border border-red-200 text-red-700 hover:bg-red-50"
+              aria-label={`Remove ${passkey.name}`}
+            >
+              <TrashIcon className="w-4 h-4" aria-hidden="true" />
+              Remove
+            </button>
+          </div>
+        )
+      )}
+    </li>
+  );
+}
