@@ -0,0 +1,97 @@
+import { promises as fs } from 'node:fs';
+import path from 'node:path';
+import { randomBytes } from 'node:crypto';
+
+/**
+ * A passkey registered to a reader's account. Only public material is stored.
+ */
+export interface StoredPasskey {
+  /** Base64URL credential ID */
+  id: string;
+  /** Base64URL-encoded COSE public key */
+  publicKey: string;
+  counter: number;
+  transports?: string[];
+  /** Reader-editable label shown in account settings */
+  name: string;
+  aaguid?: string;
+  deviceType?: 'singleDevice' | 'multiDevice';
+  backedUp?: boolean;
+  createdAt: string;
+  lastUsedAt?: string;
+}
+
+export interface StoredAccount {
+  username: string;
+  /** Base64URL WebAuthn user handle. Stable per account and never reused. */
+  userId: string;
+  displayName: string;
+  passkeys: StoredPasskey[];
+}
+
+type StoreShape = Record<string, StoredAccount>;
+
+const STORE_PATH = path.resolve(
+  process.env.ACCOUNT_STORE_PATH ?? path.join(process.cwd(), '.data', 'accounts.json'),
+);
+
+let cache: StoreShape | null = null;
+// Serialise all writes so concurrent requests can't clobber each other.
+let queue: Promise<unknown> = Promise.resolve();
+
+async function load(): Promise<StoreShape> {
+  if (cache) return cache;
+  try {
+    cache = JSON.parse(await fs.readFile(STORE_PATH, 'utf8')) as StoreShape;
+  } catch (err: any) {
+    if (err?.code !== 'ENOENT') throw err;
+    cache = {};
+  }
+  return cache;
+}
+
+async function persist(data: StoreShape) {
+  await fs.mkdir(path.dirname(STORE_PATH), { recursive: true });
+  const tmp = `${STORE_PATH}.${process.pid}.tmp`;
+  await fs.writeFile(tmp, JSON.stringify(data, null, 2), 'utf8');
+  await fs.rename(tmp, STORE_PATH);
+}
+
+function key(username: string) {
+  return username.trim().toLowerCase();
+}
+
+export async function getAccount(username: string): Promise<StoredAccount | undefined> {
+  const data = await load();
+  return data[key(username)];
+}
+
+/**
+ * Run a mutation against an account (created on first use) and persist the result.
+ */
+export function updateAccount<T>(
+  username: string,
+  mutate: (account: StoredAccount) => T,
+): Promise<T> {
+  const run = queue.then(async () => {
+    const data = await load();
+    const k = key(username);
+    const account =
+      data[k] ??
+      (data[k] = {
+        username: username.trim(),
+        userId: randomBytes(32).toString('base64url'),
+        displayName: username.trim(),
+        passkeys: [],
+      });
+    const result = mutate(account);
+    await persist(data);
+    return result;
+  });
+  queue = run.catch(() => undefined);
+  return run;
+}
+
+export function ensureAccount(username: string) {
+  return updateAccount(username, (account) => account);
+}
diff --git a/src/lib/auth.ts b/src/lib/auth.ts
new file mode 100644
index 0000000..75de53c
--- /dev/null
+++ b/src/lib/auth.ts
@@ -0,0 +1,59 @@
+import type { APIContext, AstroGlobal } from 'astro';
+
+export interface SessionUser {
+  username: string;
+}
+
+type Ctx = Pick<APIContext, 'session'> | Pick<AstroGlobal, 'session'>;
+
+export async function getSessionUser(ctx: Ctx): Promise<SessionUser | null> {
+  const user = (await ctx.session?.get('user')) as SessionUser | undefined;
+  return user?.username ? user : null;
+}
+
+export function json(body: unknown, status = 200) {
+  return new Response(JSON.stringify(body), {
+    status,
+    headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' },
+  });
+}
+
+/**
+ * Basic CSRF protection for state-changing JSON endpoints. Astro's built-in
+ * origin check is disabled for this app, so we require a JSON body (which forces
+ * a CORS preflight cross-origin) and reject requests the browser marks cross-site.
+ */
+export function rejectUnsafeRequest(request: Request): Response | null {
+  const fetchSite = request.headers.get('sec-fetch-site');
+  if (fetchSite && fetchSite !== 'same-origin' && fetchSite !== 'none') {
+    return json({ error: 'Cross-site requests are not allowed' }, 403);
+  }
+  if (request.method !== 'DELETE') {
+    const type = request.headers.get('content-type') ?? '';
+    if (!type.toLowerCase().startsWith('application/json')) {
+      return json({ error: 'Expected application/json' }, 415);
+    }
+  }
+  return null;
+}
+
+/**
+ * Resolve the signed-in user for an API route, applying CSRF checks to
+ * non-GET requests. Returns either the user or an error response.
+ */
+export async function requireUser(
+  ctx: APIContext,
+): Promise<{ user: SessionUser; error?: never } | { user?: never; error: Response }> {
+  if (ctx.request.method !== 'GET' && ctx.request.method !== 'HEAD') {
+    const unsafe = rejectUnsafeRequest(ctx.request);
+    if (unsafe) return { error: unsafe };
+  }
+  const user = await getSessionUser(ctx);
+  if (!user) return { error: json({ error: 'You need to sign in first' }, 401) };
+  return { user };
+}
+
+/** WebAuthn relying party details derived from the request URL. */
+export function relyingParty(url: URL) {
+  return { rpID: url.hostname, origin: url.origin, rpName: 'The DevTools Times' };
+}
diff --git a/src/lib/passkeys.ts b/src/lib/passkeys.ts
new file mode 100644
index 0000000..64d27a5
--- /dev/null
+++ b/src/lib/passkeys.ts
@@ -0,0 +1,86 @@
+import type { StoredAccount, StoredPasskey } from './accountStore';
+
+/** A few well-known passkey providers, keyed by AAGUID, for friendlier default names. */
+const KNOWN_PROVIDERS: Record<string, string> = {
+  'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4': 'Google Password Manager',
+  'adce0002-35bc-c60a-648b-0b25f1f05503': 'Chrome on Mac',
+  'fbfc3007-154e-4ecc-8c0b-6e020557d7bd': 'iCloud Keychain',
+  'dd4ec289-e01d-41c9-bb89-70fa845d4bf2': 'iCloud Keychain (Managed)',
+  '08987058-cadc-4b81-b6e1-30de50dcbe96': 'Windows Hello',
+  '9ddd1817-af5a-4672-a2b9-3e3dd95000a9': 'Windows Hello',
+  '6028b017-b1d4-4c02-b4b3-afcdafc96bb2': 'Windows Hello',
+  'bada5566-a7aa-401f-bd96-45619a55120d': '1Password',
+  'd548826e-79b4-db40-a3d8-11116f7e8349': 'Bitwarden',
+  '531126d6-e717-415c-9320-3d9aa6981239': 'Dashlane',
+  '53414d53-554e-4700-0000-000000000000': 'Samsung Pass',
+  'b84e4048-15dc-4dd0-8640-f4f60813c8af': 'NordPass',
+  '0ea242b4-43c4-4a1b-8b17-dd6d0b6baec6': 'Keeper',
+  'f3809540-7f14-49c1-a8b3-8f813b225541': 'Enpass',
+  'cb69481e-8ff7-4039-93ec-0a2729a154a8': 'YubiKey 5',
+};
+
+const EMPTY_AAGUID = '00000000-0000-0000-0000-000000000000';
+
+export const MAX_PASSKEY_NAME = 64;
+export const MAX_DISPLAY_NAME = 64;
+
+export function defaultPasskeyName(aaguid: string | undefined, existing: StoredPasskey[]) {
+  const base =
+    (aaguid && aaguid !== EMPTY_AAGUID && KNOWN_PROVIDERS[aaguid.toLowerCase()]) || 'Passkey';
+  const taken = new Set(existing.map((p) => p.name));
+  if (!taken.has(base)) return base;
+  let n = 2;
+  while (taken.has(`${base} (${n})`)) n++;
+  return `${base} (${n})`;
+}
+
+/** Normalise user-entered labels: collapse whitespace, strip control chars, cap length. */
+export function cleanLabel(value: unknown, max: number): string | null {
+  if (typeof value !== 'string') return null;
+  const cleaned = value
+    .replace(/[\u0000-\u001f\u007f]/g, '')
+    .replace(/\s+/g, ' ')
+    .trim();
+  if (!cleaned || cleaned.length > max) return null;
+  return cleaned;
+}
+
+export interface PasskeySummary {
+  id: string;
+  name: string;
+  provider: string | null;
+  createdAt: string;
+  lastUsedAt: string | null;
+  synced: boolean;
+  transports: string[];
+}
+
+export interface PasskeyListResponse {
+  rpId: string;
+  userId: string;
+  username: string;
+  displayName: string;
+  passkeys: PasskeySummary[];
+}
+
+export function toListResponse(account: StoredAccount, rpId: string): PasskeyListResponse {
+  return {
+    rpId,
+    userId: account.userId,
+    username: account.username,
+    displayName: account.displayName,
+    passkeys: [...account.passkeys]
+      .sort((a, b) => b.createdAt.localeCompare(a.createdAt))
+      .map((p) => ({
+        id: p.id,
+        name: p.name,
+        provider:
+          (p.aaguid && p.aaguid !== EMPTY_AAGUID && KNOWN_PROVIDERS[p.aaguid.toLowerCase()]) ||
+          null,
+        createdAt: p.createdAt,
+        lastUsedAt: p.lastUsedAt ?? null,
+        synced: p.deviceType === 'multiDevice',
+        transports: p.transports ?? [],
+      })),
+  };
+}
