index 0000000..b27cfb4
--- /dev/null
+++ b/src/lib/webauthnClient.ts
@@ -0,0 +1,131 @@
+/**
+ * Browser-side WebAuthn helpers: passkey creation plus the WebAuthn Signal API,
+ * which keeps the reader's password manager / authenticator in sync with the
+ * passkeys and account details stored on the server.
+ */
+
+type Json = Record<string, any>;
+
+function b64urlToBuffer(value: string): ArrayBuffer {
+  const pad = '='.repeat((4 - (value.length % 4)) % 4);
+  const bin = atob((value + pad).replace(/-/g, '+').replace(/_/g, '/'));
+  const bytes = new Uint8Array(bin.length);
+  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
+  return bytes.buffer;
+}
+
+function bufferToB64url(buf: ArrayBuffer): string {
+  const bytes = new Uint8Array(buf);
+  let bin = '';
+  for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
+  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+}
+
+const PKC = (): any => (typeof window !== 'undefined' ? (window as any).PublicKeyCredential : undefined);
+
+export function isWebAuthnSupported() {
+  return !!PKC() && typeof navigator?.credentials?.create === 'function';
+}
+
+function parseCreationOptions(options: Json): PublicKeyCredentialCreationOptions {
+  const pkc = PKC();
+  if (typeof pkc?.parseCreationOptionsFromJSON === 'function') {
+    return pkc.parseCreationOptionsFromJSON(options);
+  }
+  return {
+    ...options,
+    challenge: b64urlToBuffer(options.challenge),
+    user: { ...options.user, id: b64urlToBuffer(options.user.id) },
+    excludeCredentials: (options.excludeCredentials ?? []).map((c: Json) => ({
+      ...c,
+      id: b64urlToBuffer(c.id),
+    })),
+  } as PublicKeyCredentialCreationOptions;
+}
+
+function credentialToJSON(cred: any): Json {
+  if (typeof cred.toJSON === 'function') {
+    try {
+      return cred.toJSON();
+    } catch {
+      // Fall through to manual serialisation (some older browsers throw here).
+    }
+  }
+  const res = cred.response;
+  return {
+    id: cred.id,
+    rawId: bufferToB64url(cred.rawId),
+    type: cred.type,
+    authenticatorAttachment: cred.authenticatorAttachment ?? undefined,
+    clientExtensionResults: cred.getClientExtensionResults?.() ?? {},
+    response: {
+      clientDataJSON: bufferToB64url(res.clientDataJSON),
+      attestationObject: bufferToB64url(res.attestationObject),
+      transports: res.getTransports?.() ?? [],
+    },
+  };
+}
+
+/** Run navigator.credentials.create() with server-provided JSON options. */
+export async function createPasskey(optionsJSON: Json): Promise<Json> {
+  const publicKey = parseCreationOptions(optionsJSON);
+  const cred = await navigator.credentials.create({ publicKey });
+  if (!cred) throw new Error('No passkey was created');
+  return credentialToJSON(cred);
+}
+
+export interface SignalSupport {
+  acceptedCredentials: boolean;
+  userDetails: boolean;
+}
+
+export function signalSupport(): SignalSupport {
+  const pkc = PKC();
+  return {
+    acceptedCredentials: typeof pkc?.signalAllAcceptedCredentials === 'function',
+    userDetails: typeof pkc?.signalCurrentUserDetails === 'function',
+  };
+}
+
+/**
+ * Tell the authenticator the complete list of credential IDs this account still
+ * accepts. Providers hide or remove any passkey for this user that isn't listed,
+ * so removed passkeys disappear from the browser's sign-in prompts.
+ */
+export async function signalAcceptedCredentials(
+  rpId: string,
+  userId: string,
+  credentialIds: string[],
+): Promise<boolean> {
+  const pkc = PKC();
+  if (typeof pkc?.signalAllAcceptedCredentials !== 'function') return false;
+  try {
+    await pkc.signalAllAcceptedCredentials({
+      rpId,
+      userId,
+      allAcceptedCredentialIds: credentialIds,
+    });
+    return true;
+  } catch (err) {
+    console.warn('signalAllAcceptedCredentials failed', err);
+    return false;
+  }
+}
+
+/** Tell the authenticator the account's current username and display name. */
+export async function signalUserDetails(
+  rpId: string,
+  userId: string,
+  name: string,
+  displayName: string,
+): Promise<boolean> {
+  const pkc = PKC();
+  if (typeof pkc?.signalCurrentUserDetails !== 'function') return false;
+  try {
+    await pkc.signalCurrentUserDetails({ rpId, userId, name, displayName });
+    return true;
+  } catch (err) {
+    console.warn('signalCurrentUserDetails failed', err);
+    return false;
+  }
+}
