+---
+import Layout from '../../layouts/Layout.astro';
+import PasskeyManager from '../../components/PasskeyManager';
+import { getSessionUser, relyingParty } from '../../lib/auth';
+import { ensureAccount } from '../../lib/accountStore';
+import { toListResponse } from '../../lib/passkeys';
+
+const baseUrl = import.meta.env.BASE_URL;
+const user = await getSessionUser(Astro);
+if (!user) {
+  return Astro.redirect(`${baseUrl}signin?next=account`);
+}
+
+const account = await ensureAccount(user.username);
+const initial = toListResponse(account, relyingParty(Astro.url).rpID);
+Astro.response.headers.set('Cache-Control', 'no-store');
+---
+
+<Layout title="Account settings | The DevTools Times">
+  <div class="py-10 px-4 sm:px-6 lg:px-8 max-w-3xl mx-auto">
+    <header class="mb-8">
+      <h1 class="text-3xl font-bold text-gray-900">Account settings</h1>
+      <p class="mt-1 text-sm text-gray-600">
+        Signed in as <span class="font-semibold">{account.username}</span>
+      </p>
+    </header>
+
+    <nav aria-label="Account settings sections" class="mb-6 text-sm">
+      <ul class="flex gap-4 border-b border-gray-200">
+        <li>
+          <a href="#passkeys-heading" class="inline-block pb-2 border-b-2 border-gray-900 font-semibold text-gray-900" aria-current="true">
+            Sign-in &amp; security
+          </a>
+        </li>
+      </ul>
+    </nav>
+
+    <PasskeyManager client:load initial={initial} />
+
+    <form method="post" action={`${baseUrl}api/auth/logout`} class="mt-8">
+      <button type="submit" class="text-sm font-medium text-gray-600 underline hover:text-gray-900">
+        Sign out
+      </button>
+    </form>
+  </div>
+</Layout>
