+++ b/src/pages/api/account/passkeys/[id].ts
@@ -0,0 +1,42 @@
+import type { APIRoute } from 'astro';
+import { json, relyingParty, requireUser } from '../../../../lib/auth';
+import { updateAccount } from '../../../../lib/accountStore';
+import { cleanLabel, MAX_PASSKEY_NAME, toListResponse } from '../../../../lib/passkeys';
+
+/** Rename a passkey. */
+export const PATCH: APIRoute = async (ctx) => {
+  const { user, error } = await requireUser(ctx);
+  if (error) return error;
+
+  const body = await ctx.request.json().catch(() => null);
+  const name = cleanLabel(body?.name, MAX_PASSKEY_NAME);
+  if (!name) {
+    return json({ error: `Name must be between 1 and ${MAX_PASSKEY_NAME} characters` }, 400);
+  }
+
+  const id = ctx.params.id!;
+  const result = await updateAccount(user.username, (account) => {
+    const passkey = account.passkeys.find((p) => p.id === id);
+    if (!passkey) return null;
+    passkey.name = name;
+    return toListResponse(account, relyingParty(ctx.url).rpID);
+  });
+
+  return result ? json(result) : json({ error: 'Passkey not found' }, 404);
+};
+
+/** Remove a passkey from the account. */
+export const DELETE: APIRoute = async (ctx) => {
+  const { user, error } = await requireUser(ctx);
+  if (error) return error;
+
+  const id = ctx.params.id!;
+  const result = await updateAccount(user.username, (account) => {
+    const before = account.passkeys.length;
+    account.passkeys = account.passkeys.filter((p) => p.id !== id);
+    if (account.passkeys.length === before) return null;
+    return toListResponse(account, relyingParty(ctx.url).rpID);
+  });
+
+  return result ? json(result) : json({ error: 'Passkey not found' }, 404);
+};
