@@ -0,0 +1,76 @@
+import type { APIRoute } from 'astro';
+import { verifyRegistrationResponse } from '@simplewebauthn/server';
+import { isoBase64URL } from '@simplewebauthn/server/helpers';
+import { json, relyingParty, requireUser } from '../../../../lib/auth';
+import { ensureAccount, updateAccount } from '../../../../lib/accountStore';
+import { defaultPasskeyName, toListResponse } from '../../../../lib/passkeys';
+
+/** List the signed-in reader's passkeys. */
+export const GET: APIRoute = async (ctx) => {
+  const { user, error } = await requireUser(ctx);
+  if (error) return error;
+  const account = await ensureAccount(user.username);
+  return json(toListResponse(account, relyingParty(ctx.url).rpID));
+};
+
+/** Verify a freshly created passkey and add it to the account. */
+export const POST: APIRoute = async (ctx) => {
+  const { user, error } = await requireUser(ctx);
+  if (error) return error;
+
+  const pending = (await ctx.session?.get('passkeyRegistration')) as
+    | { challenge: string; expires: number; username: string }
+    | undefined;
+  ctx.session?.delete('passkeyRegistration');
+  if (!pending || pending.expires < Date.now() || pending.username !== user.username) {
+    return json({ error: 'Passkey request expired. Please try again.' }, 400);
+  }
+
+  let response;
+  try {
+    response = await ctx.request.json();
+  } catch {
+    return json({ error: 'Invalid request body' }, 400);
+  }
+
+  const { rpID, origin } = relyingParty(ctx.url);
+  let verification;
+  try {
+    verification = await verifyRegistrationResponse({
+      response,
+      expectedChallenge: pending.challenge,
+      expectedOrigin: origin,
+      expectedRPID: rpID,
+      requireUserVerification: false,
+    });
+  } catch (err) {
+    return json({ error: `Passkey could not be verified: ${(err as Error).message}` }, 400);
+  }
+  if (!verification.verified) {
+    return json({ error: 'Passkey could not be verified' }, 400);
+  }
+
+  const { credential, aaguid, credentialDeviceType, credentialBackedUp } =
+    verification.registrationInfo;
+
+  const result = await updateAccount(user.username, (account) => {
+    if (account.passkeys.some((p) => p.id === credential.id)) return 'duplicate' as const;
+    account.passkeys.push({
+      id: credential.id,
+      publicKey: isoBase64URL.fromBuffer(credential.publicKey),
+      counter: credential.counter,
+      transports: credential.transports ?? response?.response?.transports,
+      name: defaultPasskeyName(aaguid, account.passkeys),
+      aaguid,
+      deviceType: credentialDeviceType,
+      backedUp: credentialBackedUp,
+      createdAt: new Date().toISOString(),
+    });
+    return toListResponse(account, rpID);
+  });
+
+  if (result === 'duplicate') {
+    return json({ error: 'This passkey is already registered' }, 409);
+  }
+  return json(result, 201);
+};
diff --git a/src/pages/api/account/passkeys/options.ts b/src/pages/api/account/passkeys/options.ts
new file mode 100644
index 0000000..04fbb09
--- /dev/null
+++ b/src/pages/api/account/passkeys/options.ts
@@ -0,0 +1,41 @@
+import type { APIRoute } from 'astro';
+import { generateRegistrationOptions } from '@simplewebauthn/server';
+import { isoBase64URL } from '@simplewebauthn/server/helpers';
+import { json, relyingParty, requireUser } from '../../../../lib/auth';
+import { ensureAccount } from '../../../../lib/accountStore';
+
+const CHALLENGE_TTL_MS = 5 * 60 * 1000;
+
+/** Issue WebAuthn creation options for adding a new passkey. */
+export const POST: APIRoute = async (ctx) => {
+  const { user, error } = await requireUser(ctx);
+  if (error) return error;
+
+  const account = await ensureAccount(user.username);
+  const { rpID, rpName } = relyingParty(ctx.url);
+
+  const options = await generateRegistrationOptions({
+    rpName,
+    rpID,
+    userName: account.username,
+    userDisplayName: account.displayName,
+    userID: isoBase64URL.toBuffer(account.userId),
+    attestationType: 'none',
+    timeout: CHALLENGE_TTL_MS,
+    // Don't let the reader register the same authenticator twice.
+    excludeCredentials: account.passkeys.map((p) => ({ id: p.id, transports: p.transports })),
+    authenticatorSelection: {
+      residentKey: 'required',
+      userVerification: 'preferred',
+    },
+    extensions: { credProps: true },
+  });
+
+  ctx.session?.set('passkeyRegistration', {
+    challenge: options.challenge,
+    expires: Date.now() + CHALLENGE_TTL_MS,
+    username: user.username,
+  });
+
+  return json(options);
+};
diff --git a/src/pages/api/account/profile.ts b/src/pages/api/account/profile.ts
