--- /dev/null
+++ b/src/pages/api/account/profile.ts
@@ -0,0 +1,25 @@
+import type { APIRoute } from 'astro';
+import { json, relyingParty, requireUser } from '../../../lib/auth';
+import { updateAccount } from '../../../lib/accountStore';
+import { cleanLabel, MAX_DISPLAY_NAME, toListResponse } from '../../../lib/passkeys';
+
+/** Update the reader's display name (also shown by their passkey provider). */
