+import type { APIRoute } from 'astro';
+import { json, rejectUnsafeRequest } from '../../../lib/auth';
+import { ensureAccount } from '../../../lib/accountStore';
+
+const LOGIN_URL = 'https://us-central1-web-devrel-apps.cloudfunctions.net/times_cdn/api/login';
+
+/**
+ * Proxies the sign-in request to the Times identity service and, on success,
+ * records the reader in the server session so account settings can be served.
+ */
+export const POST: APIRoute = async ({ request, session }) => {
+  const unsafe = rejectUnsafeRequest(request);
+  if (unsafe) return unsafe;
+
+  let body: { username?: unknown; password?: unknown };
+  try {
+    body = await request.json();
+  } catch {
+    return json({ error: 'Invalid request body' }, 400);
+  }
+  const username = typeof body.username === 'string' ? body.username.trim() : '';
+  const password = typeof body.password === 'string' ? body.password : '';
+  if (!username || !password) {
+    return json({ error: 'Username and password are required' }, 400);
+  }
+
+  let upstream: Response;
+  try {
+    upstream = await fetch(LOGIN_URL, {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json' },
+      body: JSON.stringify({ username, password }),
+    });
+  } catch {
+    return json({ error: 'Sign-in service unavailable' }, 502);
+  }
+
+  const data = await upstream.json().catch(() => ({}));
+  if (!upstream.ok) {
+    return json({ error: data?.error || 'Unknown error' }, upstream.status);
+  }
+
+  if (!session) return json({ error: 'Sessions are not available' }, 500);
+  // Prevent session fixation: issue a fresh session ID on privilege change.
+  await session.regenerate();
+  session.set('user', { username });
+  await ensureAccount(username);
+
+  return json({ ok: true, username });
+};
