+
+  profileForm: $('#profile-form'),
+  passkeyList: $('#passkey-list'),
+  passkeyEmpty: $('#passkey-empty'),
+  passkeyTemplate: $('#passkey-item-template'),
+  createPasskeyButton: $('#create-passkey'),
+  passkeyUnsupported: $('#passkey-unsupported'),
+  signoutButton: $('#signout'),
+
+  renameDialog: $('#rename-dialog'),
+  renameInput: $('#rename-input'),
+  deleteDialog: $('#delete-dialog'),
+  deleteName: $('#delete-passkey-name'),
+  reauthDialog: $('#reauth-dialog'),
+  reauthError: $('#reauth-error'),
+  reauthPasskeyGroup: $('#reauth-passkey-group'),
+  reauthPasskeyButton: $('#reauth-passkey'),
+  reauthDivider: $('#reauth-divider'),
+  reauthPasswordForm: $('#reauth-password-form'),
+  reauthUsername: $('#reauth-username'),
+  reauthPassword: $('#reauth-password'),
