+}
+
+// Valid unpadded Base64URL: non-empty, [A-Za-z0-9_-] only, no '=' padding, length % 4 !== 1
+function isValidBase64Url(value) {
+  return typeof value === 'string' && value.length > 0 && value.length % 4 !== 1 && /^[A-Za-z0-9_-]+$/.test(value);
+}
+
+async function detectPasskeySupport() {
+  if (!window.PublicKeyCredential) return;
+  support.webauthn = true;
+  try {
+    const capabilities = await PublicKeyCredential.getClientCapabilities();
+    support.conditional = capabilities.conditionalGet === true;
+    support.create = Boolean(capabilities.passkeyPlatformAuthenticator && capabilities.conditionalGet);
+  } catch {
+    // Treat failed capability detection as "no passkey creation". Password flows keep working.
+  }
+}
+
+/** Opens a modal dialog and resolves with its returnValue ('' = dismissed). */
+function openDialog(dialog) {
+  dialog.returnValue = '';
+  return new Promise((resolve) => {
+    dialog.addEventListener(
+      'close',
+      () => {
+        const value = dialog.returnValue;
+        dialog.returnValue = '';
+        resolve(value);
+      },
+      { once: true },
+    );
+    dialog.showModal();
+  });
+}
+
+function setTime(el, epoch) {
+  el.dateTime = new Date(epoch).toISOString();
+  el.textContent = dateFormat.format(epoch);
+}
+
+function bindShowPassword(checkbox, input) {
+  checkbox.addEventListener('change', () => {
+    input.type = checkbox.checked ? 'text' : 'password';
+  });
+}
+
+// ---------------------------------------------------------------------------
+// Signal API (passive password-manager sync, never fatal)
+// ---------------------------------------------------------------------------
+
+async function signalUnknownCredential(rpId, credentialId) {
+  if (!window.PublicKeyCredential?.signalUnknownCredential || !rpId || !isValidBase64Url(credentialId)) return;
+  try {
+    await PublicKeyCredential.signalUnknownCredential({ rpId, credentialId });
+  } catch (error) {
+    console.warn('signalUnknownCredential sync warning:', error);
+  }
+}
+
+async function syncAcceptedCredentials(rpId, userId, credentials) {
+  if (!window.PublicKeyCredential?.signalAllAcceptedCredentials) return;
+  const allAcceptedCredentialIds = credentials.map((c) => c.id);
+  if (!rpId || !isValidBase64Url(userId) || !allAcceptedCredentialIds.every(isValidBase64Url)) {
+    console.warn('signalAllAcceptedCredentials skipped: server rpId and valid Base64URL IDs are required.');
+    return;
+  }
+  try {
+    // rpId always comes from the server, never from window.location.hostname.
+    await PublicKeyCredential.signalAllAcceptedCredentials({ rpId, userId, allAcceptedCredentialIds });
+  } catch (error) {
+    console.warn('signalAllAcceptedCredentials sync warning:', error);
+  }
+}
+
+async function syncCurrentUserDetails({ rpId, userId, name, displayName }) {
+  if (!window.PublicKeyCredential?.signalCurrentUserDetails) return;
+  if (!rpId || !isValidBase64Url(userId)) {
+    console.warn('signalCurrentUserDetails skipped: server rpId and valid Base64URL userId are required.');
+    return;
+  }
+  try {
+    await PublicKeyCredential.signalCurrentUserDetails({ rpId, userId, name, displayName });
+  } catch (error) {
+    console.warn('signalCurrentUserDetails sync warning:', error);
+  }
+}
+
+// ---------------------------------------------------------------------------
+// Rendering
+// ---------------------------------------------------------------------------
+
+function render() {
+  const signedIn = Boolean(state.user);
+  els.signedOut.hidden = signedIn;
+  els.signedIn.hidden = !signedIn;
+  els.navSignout.hidden = !signedIn;
+  els.navAccount.textContent = signedIn ? 'My Account' : 'Sign In';
+
+  els.passkeySigninGroup.hidden = !support.webauthn;
+  els.createPasskeyButton.hidden = !support.create;
+  els.passkeyUnsupported.hidden = support.create;
+
+  if (signedIn) {
+    els.welcomeName.textContent = state.user.displayName;
+    els.profileForm.elements.displayName.value = state.user.displayName;
+    els.profileForm.elements.email.value = state.user.name;
+  }
+}
+
+function renderCredentials() {
+  const items = state.credentials.map((credential) => {
+    const item = els.passkeyTemplate.content.firstElementChild.cloneNode(true);
+    item.dataset.id = credential.id;
+
+    const icon = item.querySelector('.passkey-icon');
+    const fallbackIcon = item.querySelector('.passkey-icon-fallback');
+    if (credential.providerIcon?.startsWith('data:image/')) {
+      icon.src = credential.providerIcon;
+      fallbackIcon.remove();
+    } else {
+      icon.remove();
+    }
+
+    item.querySelector('.passkey-name').textContent = credential.name;
+    const provider = item.querySelector('.passkey-provider');
+    if (credential.providerName && credential.providerName !== credential.name) {
+      provider.textContent = credential.providerName;
+    } else {
+      provider.remove();
+    }
+
+    setTime(item.querySelector('.passkey-created'), credential.registeredAt);
+    const lastUsed = item.querySelector('.passkey-last-used');
+    if (credential.lastUsedAt) {
+      setTime(lastUsed.querySelector('time'), credential.lastUsedAt);
+    } else {
+      lastUsed.textContent = 'Not used yet';
+    }
+
+    item.querySelector('.passkey-sync').textContent =
+      credential.credentialDeviceType === 'multiDevice' ? 'Synced across your devices' : 'Saved on one device';
+
+    item.querySelector('[data-action="rename"]').setAttribute('aria-label', `Rename ${credential.name}`);
+    item.querySelector('[data-action="delete"]').setAttribute('aria-label', `Delete ${credential.name}`);
+    return item;
+  });
+
+  els.passkeyList.replaceChildren(...items);
+  els.passkeyList.hidden = items.length === 0;
+  els.passkeyEmpty.hidden = items.length > 0;
+}
+
+const promoDismissKey = () => `daily-grind:passkey-promo-dismissed:${state.user?.userId}`;
+
+function updatePromo() {
+  els.promo.hidden = !(
+    state.user &&
+    support.create &&
+    state.credentials.length === 0 &&
+    !localStorage.getItem(promoDismissKey())
+  );
+}
+
+// ---------------------------------------------------------------------------
+// Session
+// ---------------------------------------------------------------------------
+
+async function onSignedIn(user, message) {
+  abortConditionalSignIn();
+  state.user = user;
+  state.credentials = [];
+  render();
+  announce(message, 'success');
+  els.heading.focus();
+  await loadManagementPanel();
+}
+
+async function signOut() {
+  await api('/api/signout', { method: 'POST' });
+  state.user = null;
+  state.credentials = [];
+  render();
+  updatePromo();
+  announce('You’ve been signed out.', 'info');
+  els.heading.focus();
+  armConditionalSignIn();
+}
+
+// ---------------------------------------------------------------------------
+// Passkey sign-in
+// ---------------------------------------------------------------------------
+
+function abortConditionalSignIn() {
+  conditionalController?.abort();
+  conditionalController = null;
+}
+
+/** Offers passkeys in the email field's autofill (conditional mediation). */
+async function armConditionalSignIn() {
+  if (!support.conditional || state.user) return;
+  abortConditionalSignIn();
+  const controller = new AbortController();
+  conditionalController = controller;
+
+  const { ok, data } = await api('/api/passkey/signin/options', { method: 'POST' });
+  if (!ok || controller.signal.aborted) return;
+  const publicKey = PublicKeyCredential.parseRequestOptionsFromJSON(data);
+
+  let credential;
+  try {
+    credential = await navigator.credentials.get({ publicKey, signal: controller.signal, mediation: 'conditional' });
+  } catch (error) {
+    if (!['NotAllowedError', 'AbortError'].includes(error.name)) {
+      console.warn('Conditional passkey sign-in error:', error);
+    }
+    return;
+  }
+  if (credential) await completePasskeySignIn(credential, publicKey);
+}
+
+async function signInWithPasskeyButton() {
+  // Abort any pending autofill request so it doesn't collide with this prompt.
+  abortConditionalSignIn();
+  setBusy(els.passkeySigninButton, true);
+  try {
+    const { ok, data } = await api('/api/passkey/signin/options', { method: 'POST' });
+    if (!ok) {
+      announce(data.error ?? 'Passkey sign-in is unavailable right now.', 'error');
+      armConditionalSignIn();
+      return;
+    }
+    const publicKey = PublicKeyCredential.parseRequestOptionsFromJSON(data);
+
+    let credential;
+    try {
+      credential = await navigator.credentials.get({ publicKey });
+    } catch (error) {
+      if (error.name === 'NotAllowedError') {
+        announce('Passkey sign-in was cancelled. You can try again or use your password.', 'info');
+      } else if (error.name === 'SecurityError') {
+        announce('Passkeys can’t be used on this address. Please use your password.', 'error');
+      } else if (error.name !== 'AbortError') {
+        announce('Something went wrong with passkey sign-in. Please try again.', 'error');
+      }
+      armConditionalSignIn(); // re-arm autofill after a cancelled prompt
+      return;
+    }
+    await completePasskeySignIn(credential, publicKey);
+  } finally {
+    setBusy(els.passkeySigninButton, false);
+  }
+}
+
+async function completePasskeySignIn(credential, publicKey) {
+  const encoded = credential.toJSON();
+  const { ok, status, data } = await api('/api/passkey/signin/verify', { method: 'POST', body: encoded });
+  if (ok) {
+    await onSignedIn(data.user, `Welcome back, ${data.user.displayName}! You’re signed in with your passkey.`);
+    return;
+  }
+  announce(data.error ?? 'We couldn’t verify that passkey. Please try again.', 'error');
+  // The user isn't signed in yet, so we can tell the password manager to drop an unknown credential.
+  if (status === 404) await signalUnknownCredential(publicKey.rpId, encoded.id);
+  armConditionalSignIn();
+}
+
+// ---------------------------------------------------------------------------
+// Password sign-in and registration
+// ---------------------------------------------------------------------------
+
+async function handlePasswordSignIn(event) {
+  event.preventDefault();
+  const form = event.currentTarget;
+  const submit = event.submitter ?? form.querySelector('[type="submit"]');
+  abortConditionalSignIn();
+  setBusy(submit, true);
+  const { ok, data } = await api('/api/signin', {
+    method: 'POST',
+    body: { name: form.elements.email.value, password: form.elements.password.value },
+  });
+  setBusy(submit, false);
+  if (!ok) {
+    announce(data.error ?? 'Sign-in failed. Please try again.', 'error');
+    form.elements.password.select();
+    armConditionalSignIn();
+    return;
+  }
+  form.reset();
+  await onSignedIn(data.user, `Welcome back, ${data.user.displayName}!`);
+}
+
+async function handleRegister(event) {
+  event.preventDefault();
+  const form = event.currentTarget;
+  const submit = event.submitter ?? form.querySelector('[type="submit"]');
+  abortConditionalSignIn();
+  setBusy(submit, true);
+  const { ok, data } = await api('/api/register', {
+    method: 'POST',
+    body: {
+      displayName: form.elements.fullname.value,
+      name: form.elements.email.value,
+      password: form.elements.password.value,
+    },
+  });
+  setBusy(submit, false);
+  if (!ok) {
+    announce(data.error ?? 'We couldn’t create your account. Please try again.', 'error');
+    armConditionalSignIn();
+    return;
+  }
+  form.reset();
+  await onSignedIn(data.user, `Welcome to The Daily Grind, ${data.user.displayName}! Your account is ready.`);
+}
+
+// ---------------------------------------------------------------------------
+// Passkey registration
+// ---------------------------------------------------------------------------
+
+async function registerPasskey({ promotion = false, button } = {}) {
+  if (!support.create) return;
+  abortConditionalSignIn();
+  setBusy(button, true);
+  try {
+    const { ok, data } = await api('/api/passkey/register/options', { method: 'POST', body: { promotion } });
+    if (!ok) {
+      announce(data.error ?? 'Passkey creation is unavailable right now.', 'error');
+      return;
+    }
+    const publicKey = PublicKeyCredential.parseCreationOptionsFromJSON(data);
+
+    let credential;
+    try {
+      credential = await navigator.credentials.create({ publicKey });
+    } catch (error) {
+      const messages = {
+        InvalidStateError: 'You already have a passkey for this account in this password manager.',
+        NotAllowedError: 'Passkey creation was cancelled.',
+        AbortError: 'Passkey creation was cancelled.',
+        SecurityError: 'Passkeys can’t be created on this address.',
+      };
+      announce(messages[error.name] ?? 'Something went wrong creating your passkey. Please try again.', error.name === 'NotAllowedError' || error.name === 'AbortError' ? 'info' : 'error');
+      return; // Normal WebAuthn cancellations aren't unknown credentials, so don't signal.
+    }
+
+    const encoded = credential.toJSON();
+    const result = await api('/api/passkey/register/verify', { method: 'POST', body: encoded });
+    if (!result.ok) {
+      announce(result.data.error ?? 'We couldn’t save your passkey. Please try again.', 'error');
+      // The authenticator holds a credential the server rejected. Ask the provider to remove it.
+      await signalUnknownCredential(publicKey.rp.id, encoded.id);
+      return;
+    }
+    announce(`Passkey created. Next time, sign in with ${result.data.credential.name}.`, 'success');
+    await loadManagementPanel();
+  } finally {
+    setBusy(button, false);
+  }
+}
+
+// ---------------------------------------------------------------------------
+// Reauthentication
+// ---------------------------------------------------------------------------
+
+/** Shows the "Confirm it's you" dialog. Resolves true once the server accepts verification. */
+function reauthenticate() {
+  const dialog = els.reauthDialog;
+  const canUsePasskey = support.webauthn && state.credentials.length > 0;
+  const canUsePassword = Boolean(state.user?.hasPassword);
+  let verified = false;
+  let ceremony = null;
+
+  els.reauthError.textContent = '';
+  els.reauthPasskeyGroup.hidden = !canUsePasskey;
+  els.reauthPasswordForm.hidden = !canUsePassword;
+  els.reauthDivider.hidden = !(canUsePasskey && canUsePassword);
+  els.reauthPasswordForm.reset();
+  els.reauthUsername.value = state.user?.name ?? '';
+  els.reauthPasskeyButton.toggleAttribute('autofocus', canUsePasskey);
+  els.reauthPassword.toggleAttribute('autofocus', !canUsePasskey && canUsePassword);
+
+  const fail = (message) => {
+    els.reauthError.textContent = message;
+  };
+
+  const onPasskey = async () => {
+    abortConditionalSignIn();
+    ceremony?.abort();
+    ceremony = new AbortController();
+    setBusy(els.reauthPasskeyButton, true);
+    try {
+      const options = await api('/api/reauth/options', { method: 'POST' });
+      if (!options.ok) return fail(options.data.error ?? 'Passkey verification is unavailable.');
+      const publicKey = PublicKeyCredential.parseRequestOptionsFromJSON(options.data);
+
+      let credential;
+      try {
+        credential = await navigator.credentials.get({ publicKey, signal: ceremony.signal });
+      } catch (error) {
+        if (error.name === 'AbortError') return;
+        return fail(
+          error.name === 'NotAllowedError'
+            ? 'Verification was cancelled. Try again' + (canUsePassword ? ' or use your password.' : '.')
+            : 'We couldn’t verify your passkey. Please try again.',
+        );
+      }
+
+      const encoded = credential.toJSON();
+      const result = await api('/api/reauth/verify', { method: 'POST', body: encoded });
+      if (result.ok) {
+        verified = true;
+        dialog.close('verified');
+        return;
+      }
+      fail(result.data.error ?? 'We couldn’t verify your passkey.');
+      if (result.status === 404) await signalUnknownCredential(publicKey.rpId, encoded.id);
+    } finally {
+      setBusy(els.reauthPasskeyButton, false);
+    }
+  };
+
+  const onPassword = async (event) => {
+    event.preventDefault();
+    const submit = event.submitter;
+    setBusy(submit, true);
+    const result = await api('/api/reauth/password', {
+      method: 'POST',
+      body: { password: els.reauthPassword.value },
+    });
+    setBusy(submit, false);
+    if (result.ok) {
+      verified = true;
+      dialog.close('verified');
+      return;
+    }
+    fail(result.data.error ?? 'We couldn’t verify your password.');
+    els.reauthPassword.select();
+  };
+
+  els.reauthPasskeyButton.addEventListener('click', onPasskey);
+  els.reauthPasswordForm.addEventListener('submit', onPassword);
+
+  return openDialog(dialog).then(() => {
+    ceremony?.abort();
+    els.reauthPasskeyButton.removeEventListener('click', onPasskey);
+    els.reauthPasswordForm.removeEventListener('submit', onPassword);
+    els.reauthPasswordForm.reset();
+    return verified;
+  });
+}
+
+/** Runs a request and retries it once after reauthentication if the server asks for it. */
+async function withReauth(request) {
+  let result = await request();
+  if (result.status === 403 && result.data.code === 'reauth_required') {
+    if (!(await reauthenticate())) return { ...result, cancelled: true };
+    result = await request();
+  }
+  return result;
+}
+
+// ---------------------------------------------------------------------------
+// Passkey management and profile
+// ---------------------------------------------------------------------------
+
+async function loadManagementPanel() {
+  const { ok, status, data } = await api('/api/credentials');
+  if (!ok) {
+    if (status === 401) {
+      state.user = null;
+      render();
+      armConditionalSignIn();
+    } else {
+      announce(data.error ?? 'We couldn’t load your passkeys.', 'error');
+    }
+    return;
+  }
+  state.credentials = data.credentials;
+  renderCredentials();
+  updatePromo();
+  // Keep the password manager in sync with the server's passkey list.
+  await syncAcceptedCredentials(data.rpId, data.userId, data.credentials);
+}
+
+async function renamePasskey(credential) {
+  els.renameInput.value = credential.name;
+  if ((await openDialog(els.renameDialog)) !== 'save') return;
+  const name = els.renameInput.value.trim();
+  if (!name || name === credential.name) return;
+
+  // A passkey nickname is a server-side label. It doesn't change the password manager entry.
+  const { ok, data } = await api(`/api/credential/${encodeURIComponent(credential.id)}`, {
+    method: 'PUT',
+    body: { name },
+  });
+  if (!ok) {
+    announce(data.error ?? 'We couldn’t rename that passkey.', 'error');
+    return;
+  }
+  announce(`Passkey renamed to “${data.credential.name}”.`, 'success');
+  await loadManagementPanel();
+}
+
+async function deletePasskey(credential) {
+  els.deleteName.textContent = credential.name;
+  if ((await openDialog(els.deleteDialog)) !== 'delete') return;
+
+  const result = await withReauth(() =>
+    api(`/api/credential/${encodeURIComponent(credential.id)}`, { method: 'DELETE' }),
+  );
+  if (result.cancelled) {
+    announce('Your passkey was not deleted because verification was cancelled.', 'info');
+    return;
+  }
+  if (!result.ok) {
+    announce(result.data.error ?? 'We couldn’t delete that passkey.', 'error');
+    return;
+  }
+  announce(`“${credential.name}” was deleted.`, 'success');
+  // Reload the list, which also calls signalAllAcceptedCredentials so the
+  // password manager hides the deleted passkey.
+  await loadManagementPanel();
+  els.passkeyList.hidden ? els.createPasskeyButton.focus() : els.passkeyList.querySelector('button')?.focus();
+}
+
+async function handleProfileUpdate(event) {
+  event.preventDefault();
+  const form = event.currentTarget;
+  const submit = event.submitter ?? form.querySelector('[type="submit"]');
+  const displayName = form.elements.displayName.value.trim();
+  const name = form.elements.email.value.trim();
+  if (displayName === state.user.displayName && name.toLowerCase() === state.user.name) {
+    announce('There are no changes to save.', 'info');
+    return;
+  }
+
+  setBusy(submit, true);
+  const result = await withReauth(() => api('/api/user', { method: 'PUT', body: { name, displayName } }));
+  setBusy(submit, false);
+  if (result.cancelled) {
+    announce('Your profile was not updated because verification was cancelled.', 'info');
+    return;
+  }
+  if (!result.ok) {
+    announce(result.data.error ?? 'We couldn’t update your profile.', 'error');
+    return;
+  }
+  state.user = result.data;
+  render();
+  announce('Your profile was updated.', 'success');
+  // Update the username and display name saved with the user's passkeys.
+  await syncCurrentUserDetails(result.data);
+}
+
+// ---------------------------------------------------------------------------
+// Wiring
+// ---------------------------------------------------------------------------
+
+els.signinForm.addEventListener('submit', handlePasswordSignIn);
+els.registerForm.addEventListener('submit', handleRegister);
+els.profileForm.addEventListener('submit', handleProfileUpdate);
+els.passkeySigninButton.addEventListener('click', signInWithPasskeyButton);
+els.createPasskeyButton.addEventListener('click', () => registerPasskey({ button: els.createPasskeyButton }));
+els.promoCreate.addEventListener('click', () => registerPasskey({ promotion: true, button: els.promoCreate }));
+els.promoDismiss.addEventListener('click', () => {
+  localStorage.setItem(promoDismissKey(), '1');
+  updatePromo();
+  els.createPasskeyButton.focus();
+});
+els.signoutButton.addEventListener('click', signOut);
+els.navSignout.addEventListener('click', signOut);
+bindShowPassword(els.signinShowPassword, els.signinForm.elements.password);
+bindShowPassword(els.registerShowPassword, els.registerForm.elements.password);
+
+els.passkeyList.addEventListener('click', (event) => {
+  const button = event.target.closest('button[data-action]');
+  if (!button) return;
+  const credential = state.credentials.find((c) => c.id === button.closest('[data-id]')?.dataset.id);
+  if (!credential) return;
+  if (button.dataset.action === 'rename') renamePasskey(credential);
+  if (button.dataset.action === 'delete') deletePasskey(credential);
+});
+
+await detectPasskeySupport();
+const session = await api('/api/session');
+state.user = session.ok ? session.data.user : null;
+render();
+if (state.user) {
+  await loadManagementPanel();
+} else {
+  armConditionalSignIn();
+}
diff --git a/js/api.js b/js/api.js
new file mode 100644
index 0000000..795106f
--- /dev/null
+++ b/js/api.js
@@ -0,0 +1,29 @@
+/**
+ * Thin API client for the account endpoints.
+ *
+ * By default requests go to the in-browser mock backend (./mock-server.js)
+ * because this site is static. To use a real backend that serves the same
+ * routes, set `<meta name="daily-grind-api" content="remote">` in index.html.
+ */
+const mode = document.querySelector('meta[name="daily-grind-api"]')?.content ?? 'mock';
+const transport =
+  mode === 'remote' ? window.fetch.bind(window) : (await import('./mock-server.js')).mockFetch;
+
+/**
+ * Sends a JSON request. Resolves to `{ ok, status, data }` and never throws
+ * on HTTP errors. A network failure resolves with `status: 0`.
+ */
+export async function api(path, { method = 'GET', body } = {}) {
+  try {
+    const response = await transport(path, {
+      method,
+      credentials: 'same-origin',
+      headers: body === undefined ? {} : { 'Content-Type': 'application/json' },
+      body: body === undefined ? undefined : JSON.stringify(body),
+    });
+    const data = await response.json().catch(() => ({}));
+    return { ok: response.ok, status: response.status, data };
+  } catch (error) {
+    return { ok: false, status: 0, data: { error: 'Network error. Check your connection and try again.' } };
+  }
+}
diff --git a/js/mock-server.js b/js/mock-server.js
new file mode 100644
index 0000000..4cea3fa
--- /dev/null
+++ b/js/mock-server.js
@@ -0,0 +1,638 @@
+/**
+ * In-browser mock of the Daily Grind account API.
+ *
+ * The homepage is a static site with no backend. This module stands in for
+ * the server so the passkey flows work end to end. It exposes a
+ * fetch-compatible `mockFetch(url, init)` that routes the same REST endpoints a
+ * real backend would serve, and returns real `Response` objects.
+ *
+ * It does the core WebAuthn relying-party checks with WebCrypto:
+ * challenge, origin, RP ID hash, user presence, signature (ES256 / RS256),
+ * signature counter, and credential ownership. Attestation statements are not
+ * checked (we request `attestation: "none"`).
+ *
+ * PRODUCTION: Replace this with a real server that uses a vetted FIDO2
+ * library such as SimpleWebAuthn (github.com/MasterKale/SimpleWebAuthn).
+ * Keep challenges in an HttpOnly server session. Never keep users,
+ * credentials or sessions in browser storage the way this mock does.
+ */
+
+// ---------------------------------------------------------------------------
+// "Server" configuration
+// ---------------------------------------------------------------------------
+
+// Stand-in for a predefined server constant. The mock runs on whatever host
+// serves the page, so it reads the hostname here, on the "server" side. The
+// client never derives rpId itself. It always reads it from the API responses.
+const RP_ID = location.hostname;
+const RP_NAME = 'The Daily Grind';
+const EXPECTED_ORIGIN = location.origin;
+const REAUTH_WINDOW_MS = 5 * 60 * 1000;
+const CHALLENGE_TTL_MS = 5 * 60 * 1000;
+const DB_KEY = 'daily-grind:mock-db';
+const SESSION_KEY = 'daily-grind:mock-session';
+const AAGUID_REGISTRY_URL =
+  'https://raw.githubusercontent.com/passkeydeveloper/passkey-authenticator-aaguids/refs/heads/main/combined_aaguid.json';
+const ZERO_AAGUID = '00000000-0000-0000-0000-000000000000';
+
+// Small built-in subset of the community AAGUID registry, used when the full
+// registry can't be fetched. Use these only as UX hints, never for security.
+const KNOWN_AAGUIDS = {
+  'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4': 'Google Password Manager',
+  'adce0002-35bc-c60a-648b-0b25f1f05503': 'Chrome on Mac',
+  'fbfc3007-154e-4ecc-8c0b-6e020557d7bd': 'iCloud Keychain',
+  'dd4ec289-e01d-41c9-bb89-70fa845d4bf2': 'iCloud Keychain (Managed)',
+  '08987058-cadc-4b81-b6e1-30de50dcbe96': 'Windows Hello',
+  '9ddd1817-af5a-4672-a2b9-3e3dd95000a9': 'Windows Hello',
+  '6028b017-b1d4-4c02-b4b3-afcdafc96bb2': 'Windows Hello',
+  'bada5566-a7aa-401f-bd96-45619a55120d': '1Password',
+  'd548826e-79b4-db40-a3d8-11116f7e8349': 'Bitwarden',
+  '531126d6-e717-415c-9320-3d9aa6981239': 'Dashlane',
+  'b84e4048-15dc-4dd0-8640-f4f60813c8af': 'NordPass',
+  '0ea242b4-43c4-4a1b-8b17-dd6d0b6baec6': 'Keeper',
+  'f3809540-7f14-49c1-a8b3-8f813b225541': 'Enpass',
+  '53414d53-554e-4700-0000-000000000000': 'Samsung Pass',
+};
+
+// ---------------------------------------------------------------------------
+// Encoding helpers
+// ---------------------------------------------------------------------------
+
+const b64url = {
+  encode(input) {
+    const bytes = input instanceof Uint8Array ? input : new Uint8Array(input);
+    let bin = '';
+    for (const b of bytes) bin += String.fromCharCode(b);
+    return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+  },
+  decode(str) {
+    const b64 = str.replace(/-/g, '+').replace(/_/g, '/');
+    const padded = b64 + '==='.slice((b64.length + 3) % 4);
+    return Uint8Array.from(atob(padded), (c) => c.charCodeAt(0));
+  },
+};
+
+const randomB64url = (size = 32) => b64url.encode(crypto.getRandomValues(new Uint8Array(size)));
+
+async function sha256(data) {
+  const bytes = typeof data === 'string' ? new TextEncoder().encode(data) : data;
+  return new Uint8Array(await crypto.subtle.digest('SHA-256', bytes));
+}
+
+function concatBytes(...parts) {
+  const out = new Uint8Array(parts.reduce((n, p) => n + p.length, 0));
+  let offset = 0;
+  for (const p of parts) {
+    out.set(p, offset);
+    offset += p.length;
+  }
+  return out;
+}
+
+const bytesEqual = (a, b) => a.length === b.length && a.every((v, i) => v === b[i]);
+
+function formatUuid(bytes) {
+  const hex = [...bytes].map((b) => b.toString(16).padStart(2, '0')).join('');
+  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
+}
+
+// Minimal CBOR decoder. It covers what attestation objects and COSE keys use.
+function decodeCbor(bytes, start = 0) {
+  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
+  let offset = start;
+
+  const readLength = (info) => {
+    if (info < 24) return info;
+    if (info === 24) return view.getUint8(offset++);
+    if (info === 25) { const v = view.getUint16(offset); offset += 2; return v; }
+    if (info === 26) { const v = view.getUint32(offset); offset += 4; return v; }
+    if (info === 27) { const v = Number(view.getBigUint64(offset)); offset += 8; return v; }
+    throw new Error('Unsupported CBOR length encoding');
+  };
+
+  const readItem = () => {
+    const initial = view.getUint8(offset++);
+    const major = initial >> 5;
+    const info = initial & 0x1f;
+    switch (major) {
+      case 0: return readLength(info);
+      case 1: return -1 - readLength(info);
+      case 2: { const n = readLength(info); const v = bytes.slice(offset, offset + n); offset += n; return v; }
+      case 3: { const n = readLength(info); const v = new TextDecoder().decode(bytes.subarray(offset, offset + n)); offset += n; return v; }
+      case 4: { const n = readLength(info); const arr = []; for (let i = 0; i < n; i++) arr.push(readItem()); return arr; }
+      case 5: { const n = readLength(info); const map = new Map(); for (let i = 0; i < n; i++) { const k = readItem(); map.set(k, readItem()); } return map; }
+      case 6: readLength(info); return readItem(); // ignore tags
+      case 7:
+        if (info === 20) return false;
+        if (info === 21) return true;
+        if (info === 22) return null;
+        if (info === 23) return undefined;
+        throw new Error('Unsupported CBOR simple value');
+      default:
+        throw new Error('Invalid CBOR');
+    }
+  };
+
+  const value = readItem();
+  return { value, offset };
+}
+
+function parseAuthenticatorData(bytes) {
+  if (bytes.length < 37) throw new Error('Authenticator data too short');
+  const flags = bytes[32];
+  const result = {
+    rpIdHash: bytes.slice(0, 32),
+    flags,
+    userPresent: Boolean(flags & 0x01),
+    userVerified: Boolean(flags & 0x04),
+    backupEligible: Boolean(flags & 0x08),
+    backedUp: Boolean(flags & 0x10),
+    signCount: new DataView(bytes.buffer, bytes.byteOffset + 33, 4).getUint32(0),
+  };
+  if (flags & 0x40) {
+    // Attested credential data is present.
+    result.aaguid = formatUuid(bytes.slice(37, 53));
+    const idLength = (bytes[53] << 8) | bytes[54];
+    const keyStart = 55 + idLength;
+    result.credentialId = bytes.slice(55, keyStart);
+    const { offset } = decodeCbor(bytes, keyStart);
+    result.cosePublicKey = bytes.slice(keyStart, offset);
+  }
+  return result;
+}
+
+async function importCoseKey(coseBytes) {
+  const key = decodeCbor(coseBytes).value;
+  const kty = key.get(1);
+  const alg = key.get(3);
+  if (kty === 2 && alg === -7 && key.get(-1) === 1) {
+    const jwk = { kty: 'EC', crv: 'P-256', x: b64url.encode(key.get(-2)), y: b64url.encode(key.get(-3)), ext: true };
+    return { alg, cryptoKey: await crypto.subtle.importKey('jwk', jwk, { name: 'ECDSA', namedCurve: 'P-256' }, false, ['verify']) };
+  }
+  if (kty === 3 && alg === -257) {
+    const jwk = { kty: 'RSA', n: b64url.encode(key.get(-1)), e: b64url.encode(key.get(-2)), alg: 'RS256', ext: true };
+    return { alg, cryptoKey: await crypto.subtle.importKey('jwk', jwk, { name: 'RSASSA-PKCS1-v1_5', hash: 'SHA-256' }, false, ['verify']) };
+  }
+  throw new Error('Unsupported public key algorithm');
+}
+
+// WebAuthn ES256 signatures are DER-encoded. WebCrypto expects raw r||s.
+function derToRawEcdsa(der) {
+  let offset = 2; // SEQUENCE tag + length (always < 128 for P-256)
+  const readInt = () => {
+    if (der[offset++] !== 0x02) throw new Error('Invalid DER signature');
+    const len = der[offset++];
+    let int = der.slice(offset, offset + len);
+    offset += len;
+    while (int.length > 32 && int[0] === 0) int = int.slice(1);
+    const out = new Uint8Array(32);
+    out.set(int, 32 - int.length);
+    return out;
+  };
+  return concatBytes(readInt(), readInt());
+}
+
+// ---------------------------------------------------------------------------
+// Persistence ("database" and "session")
+// ---------------------------------------------------------------------------
+
+const loadDb = () => JSON.parse(localStorage.getItem(DB_KEY) || '{"users":[],"credentials":[]}');
+const saveDb = (db) => localStorage.setItem(DB_KEY, JSON.stringify(db));
+const loadSession = () => JSON.parse(sessionStorage.getItem(SESSION_KEY) || '{"challenges":{}}');
+const saveSession = (s) => sessionStorage.setItem(SESSION_KEY, JSON.stringify(s));
+
+function issueChallenge(kind, extra = {}) {
+  const session = loadSession();
+  const challenge = randomB64url(32);
+  session.challenges[kind] = { challenge, expiresAt: Date.now() + CHALLENGE_TTL_MS, ...extra };
+  saveSession(session);
+  return challenge;
+}
+
+// Single use: the challenge is removed whether or not verification passes.
+function consumeChallenge(kind) {
+  const session = loadSession();
+  const entry = session.challenges[kind];
+  delete session.challenges[kind];
+  saveSession(session);
+  if (!entry || entry.expiresAt < Date.now()) throw new HttpError(400, 'Challenge expired. Please try again.');
+  return entry;
+}
+
+async function hashPassword(password, saltB64 = randomB64url(16)) {
+  const material = await crypto.subtle.importKey('raw', new TextEncoder().encode(password), 'PBKDF2', false, ['deriveBits']);
+  const bits = await crypto.subtle.deriveBits(
+    { name: 'PBKDF2', hash: 'SHA-256', salt: b64url.decode(saltB64), iterations: 210000 },
+    material,
+    256,
+  );
+  return { salt: saltB64, hash: b64url.encode(bits) };
+}
+
+// ---------------------------------------------------------------------------
+// HTTP plumbing
+// ---------------------------------------------------------------------------
+
+class HttpError extends Error {
+  constructor(status, message, code) {
+    super(message);
+    this.status = status;
+    this.code = code;
+  }
+}
+
+const json = (status, body) =>
+  new Response(JSON.stringify(body ?? {}), { status, headers: { 'Content-Type': 'application/json' } });
+
+function currentUser(db = loadDb()) {
+  const { userId } = loadSession();
+  return db.users.find((u) => u.id === userId) ?? null;
+}
+
+function requireUser(db) {
+  const user = currentUser(db);
+  if (!user) throw new HttpError(401, 'Please sign in first.', 'unauthenticated');
+  return user;
+}
+
+function requireRecentReauth() {
+  const { reauthAt = 0 } = loadSession();
+  if (Date.now() - reauthAt > REAUTH_WINDOW_MS) {
+    throw new HttpError(403, 'Please confirm it’s you to continue.', 'reauth_required');
+  }
+}
+
+function startSession(user, { verified = true } = {}) {
+  const session = loadSession();
+  session.userId = user.id;
+  // A fresh sign-in counts as a recent verification.
+  session.reauthAt = verified ? Date.now() : 0;
+  saveSession(session);
+}
+
+const publicUser = (user, db) => ({
+  rpId: RP_ID,
+  userId: user.passkeyUserId, // unpadded Base64URL WebAuthn user handle
+  name: user.name,
+  displayName: user.displayName,
+  hasPassword: Boolean(user.password),
+  passkeyCount: db.credentials.filter((c) => c.userId === user.id).length,
+});
+
+const publicCredential = (c) => ({
+  id: c.id,
+  name: c.name,
+  providerName: c.providerName,
+  providerIcon: c.providerIcon,
+  aaguid: c.aaguid,
+  credentialDeviceType: c.credentialDeviceType,
+  credentialBackedUp: c.credentialBackedUp,
+  registeredAt: c.registeredAt,
+  lastUsedAt: c.lastUsedAt,
+});
+
+const normalizeEmail = (v) => String(v ?? '').trim().toLowerCase();
+const normalizeName = (v) => String(v ?? '').trim().replace(/\s+/g, ' ').slice(0, 80);
+
+// ---------------------------------------------------------------------------
+// AAGUID → provider metadata (UX hint only)
+// ---------------------------------------------------------------------------
+
+let registryPromise;
+function loadAaguidRegistry() {
+  registryPromise ??= fetch(AAGUID_REGISTRY_URL, { signal: AbortSignal.timeout(4000) })
+    .then((r) => (r.ok ? r.json() : {}))
+    .catch(() => ({}));
+  return registryPromise;
+}
+
+async function describeProvider(aaguid) {
+  if (!aaguid || aaguid === ZERO_AAGUID) {
+    const platform = navigator.userAgentData?.platform;
+    return { providerName: platform ? `Passkey on ${platform}` : 'Unknown passkey provider', providerIcon: undefined };
+  }
+  const registry = await loadAaguidRegistry();
+  const entry = registry[aaguid];
+  return {
+    providerName: entry?.name ?? KNOWN_AAGUIDS[aaguid] ?? 'Unknown passkey provider',
+    providerIcon: entry?.icon_light,
+  };
+}
+
+// ---------------------------------------------------------------------------
+// WebAuthn verification
+// ---------------------------------------------------------------------------
+
+function verifyClientData(clientDataB64, expectedType, expectedChallenge) {
+  const bytes = b64url.decode(clientDataB64);
+  const clientData = JSON.parse(new TextDecoder().decode(bytes));
+  if (clientData.type !== expectedType) throw new HttpError(400, 'Unexpected ceremony type.');
+  if (clientData.challenge !== expectedChallenge) throw new HttpError(400, 'Challenge mismatch.');
+  if (clientData.origin !== EXPECTED_ORIGIN) throw new HttpError(400, 'Origin mismatch.');
+  return bytes;
+}
+
+async function verifyRpIdHash(authData) {
+  if (!bytesEqual(authData.rpIdHash, await sha256(RP_ID))) throw new HttpError(400, 'RP ID mismatch.');
+  if (!authData.userPresent) throw new HttpError(400, 'User presence was not confirmed.');
+}
+
+async function verifyAssertion(body, kind) {
+  const db = loadDb();
+  const { challenge } = consumeChallenge(kind);
+  const stored = db.credentials.find((c) => c.id === body?.id);
+  // An explicit 404 lets the client call signalUnknownCredential().
+  if (!stored) throw new HttpError(404, 'This passkey is no longer registered with The Daily Grind.', 'credential_not_found');
+
+  const { response } = body;
+  const clientDataBytes = verifyClientData(response.clientDataJSON, 'webauthn.get', challenge);
+  const authDataBytes = b64url.decode(response.authenticatorData);
+  const authData = parseAuthenticatorData(authDataBytes);
+  await verifyRpIdHash(authData);
+  // userVerification was "preferred", so UV is not enforced (requireUserVerification: false).
+
+  const { alg, cryptoKey } = await importCoseKey(b64url.decode(stored.credentialPublicKey));
+  const signedData = concatBytes(authDataBytes, await sha256(clientDataBytes));
+  const signature = b64url.decode(response.signature);
+  const valid =
+    alg === -7
+      ? await crypto.subtle.verify({ name: 'ECDSA', hash: 'SHA-256' }, cryptoKey, derToRawEcdsa(signature), signedData)
+      : await crypto.subtle.verify({ name: 'RSASSA-PKCS1-v1_5' }, cryptoKey, signature, signedData);
+  if (!valid) throw new HttpError(400, 'Passkey signature could not be verified.');
+
+  if ((authData.signCount > 0 || stored.counter > 0) && authData.signCount <= stored.counter) {
+    throw new HttpError(400, 'Passkey counter check failed. The passkey may be cloned.');
+  }
+
+  const user = db.users.find((u) => u.id === stored.userId);
+  if (!user) throw new HttpError(404, 'Account not found.', 'credential_not_found');
+  if (response.userHandle && response.userHandle !== user.passkeyUserId) {
+    throw new HttpError(400, 'Passkey does not belong to this account.');
+  }
+
+  stored.counter = authData.signCount;
+  stored.lastUsedAt = Date.now();
+  stored.credentialBackedUp = authData.backedUp;
+  saveDb(db);
+  return { user, stored };
+}
+
+// ---------------------------------------------------------------------------
+// Route handlers
+// ---------------------------------------------------------------------------
+
+const routes = {
+  'GET /api/session': async () => {
+    const db = loadDb();
+    const user = currentUser(db);
+    return json(200, { user: user ? publicUser(user, db) : null });
+  },
+
+  'POST /api/register': async (body) => {
+    const db = loadDb();
+    const name = normalizeEmail(body.name);
+    const displayName = normalizeName(body.displayName);
+    const password = String(body.password ?? '');
+    if (!/^[^\s@]+@[^\s@]+$/.test(name)) throw new HttpError(400, 'Enter a valid email address.');
+    if (!displayName) throw new HttpError(400, 'Enter your name.');
+    if (password.length < 8) throw new HttpError(400, 'Use a password with at least 8 characters.');
+    if (db.users.some((u) => u.name === name)) throw new HttpError(409, 'An account with this email already exists. Try signing in.');
+
+    const user = {
+      id: crypto.randomUUID(),
+      passkeyUserId: randomB64url(32), // opaque WebAuthn user handle, no PII
+      name,
+      displayName,
+      password: await hashPassword(password),
+      createdAt: Date.now(),
+    };
+    db.users.push(user);
+    saveDb(db);
+    startSession(user);
+    return json(201, { user: publicUser(user, db) });
+  },
+
+  'POST /api/signin': async (body) => {
+    const db = loadDb();
+    const user = db.users.find((u) => u.name === normalizeEmail(body.name));
+    const ok = user?.password && (await hashPassword(String(body.password ?? ''), user.password.salt)).hash === user.password.hash;
+    if (!ok) throw new HttpError(401, 'That email and password don’t match our records.');
+    startSession(user);
+    return json(200, { user: publicUser(user, db) });
+  },
+
+  'POST /api/signout': async () => {
+    saveSession({ challenges: {} });
+    return json(200, { success: true });
+  },
+
+  // --- Passkey registration -------------------------------------------------
+  'POST /api/passkey/register/options': async (body) => {
+    const db = loadDb();
+    const user = requireUser(db);
+    const promotion = Boolean(body?.promotion);
+    const challenge = issueChallenge('register');
+    return json(200, {
+      challenge,
+      rp: { id: RP_ID, name: RP_NAME },
+      user: { id: user.passkeyUserId, name: user.name, displayName: user.displayName },
+      pubKeyCredParams: [
+        { type: 'public-key', alg: -7 },
+        { type: 'public-key', alg: -257 },
+      ],
+      timeout: 300000,
+      attestation: 'none',
+      excludeCredentials: db.credentials
+        .filter((c) => c.userId === user.id)
+        .map((c) => ({ type: 'public-key', id: c.id, transports: c.transports })),
+      authenticatorSelection: {
+        residentKey: 'required',
+        requireResidentKey: true,
+        userVerification: 'preferred',
+        // Promotions push the platform authenticator. The management panel
+        // leaves attachment open so security keys work too.
+        ...(promotion && { authenticatorAttachment: 'platform' }),
+      },
+      hints: promotion ? ['client-device'] : [],
+    });
+  },
+
+  'POST /api/passkey/register/verify': async (body) => {
+    const db = loadDb();
+    const user = requireUser(db);
+    const { challenge } = consumeChallenge('register');
+    const { response } = body ?? {};
+    if (!response?.attestationObject) throw new HttpError(400, 'Malformed registration response.');
+
+    verifyClientData(response.clientDataJSON, 'webauthn.create', challenge);
+    const attestation = decodeCbor(b64url.decode(response.attestationObject)).value;
+    const authData = parseAuthenticatorData(attestation.get('authData'));
+    await verifyRpIdHash(authData);
+    // userVerification was "preferred", so UV is not enforced (requireUserVerification: false).
+    if (!authData.credentialId) throw new HttpError(400, 'No credential in registration response.');
+
+    const credentialId = b64url.encode(authData.credentialId);
+    if (credentialId !== body.id) throw new HttpError(400, 'Credential ID mismatch.');
+    if (db.credentials.some((c) => c.id === credentialId)) throw new HttpError(409, 'This passkey is already registered.');
