+  },
+
+  // --- Passkey sign-in (discoverable) ---------------------------------------
+  'POST /api/passkey/signin/options': async () => {
+    // Store the expected UV level in the session, not in client-supplied input.
+    const challenge = issueChallenge('signin', { userVerification: 'preferred' });
+    return json(200, { challenge, rpId: RP_ID, allowCredentials: [], userVerification: 'preferred', timeout: 300000 });
+  },
+
+  'POST /api/passkey/signin/verify': async (body) => {
+    const { user } = await verifyAssertion(body, 'signin');
+    startSession(user);
+    return json(200, { user: publicUser(user, loadDb()) });
+  },
+
+  // --- Reauthentication -----------------------------------------------------
+  'POST /api/reauth/options': async () => {
+    const db = loadDb();
+    const user = requireUser(db);
+    const passkeys = db.credentials.filter((c) => c.userId === user.id);
+    if (!passkeys.length) throw new HttpError(400, 'No passkeys registered for this account.', 'no_passkeys');
+    const challenge = issueChallenge('reauth', { userVerification: 'preferred' });
+    return json(200, {
+      challenge,
+      rpId: RP_ID,
+      // Only allow the signed-in user's passkeys. Never use a discoverable request here.
+      allowCredentials: passkeys.map((c) => ({ type: 'public-key', id: c.id, transports: c.transports })),
+      userVerification: 'preferred',
+      timeout: 300000,
+    });
+  },
+
+  'POST /api/reauth/verify': async (body) => {
+    const db = loadDb();
+    const user = requireUser(db);
+    const { stored } = await verifyAssertion(body, 'reauth');
+    if (stored.userId !== user.id) throw new HttpError(403, 'That passkey belongs to a different account.');
+    const session = loadSession();
+    session.reauthAt = Date.now();
+    saveSession(session);
+    return json(200, { success: true });
+  },
+
+  'POST /api/reauth/password': async (body) => {
+    const db = loadDb();
+    const user = requireUser(db);
+    const ok = user.password && (await hashPassword(String(body?.password ?? ''), user.password.salt)).hash === user.password.hash;
+    if (!ok) throw new HttpError(401, 'Incorrect password.');
+    const session = loadSession();
+    session.reauthAt = Date.now();
+    saveSession(session);
+    return json(200, { success: true });
+  },
+
+  // --- Passkey management ---------------------------------------------------
+  'GET /api/credentials': async () => {
+    const db = loadDb();
+    const user = requireUser(db);
+    return json(200, {
+      rpId: RP_ID,
+      userId: user.passkeyUserId,
+      credentials: db.credentials
+        .filter((c) => c.userId === user.id)
+        .sort((a, b) => b.registeredAt - a.registeredAt)
+        .map(publicCredential),
+    });
+  },
+
+  'PUT /api/credential/:id': async (body, { id }) => {
+    const db = loadDb();
+    const user = requireUser(db);
+    const cred = db.credentials.find((c) => c.id === id && c.userId === user.id);
+    if (!cred) throw new HttpError(404, 'Passkey not found.');
+    const name = normalizeName(body?.name);
+    if (!name) throw new HttpError(400, 'Enter a name for this passkey.');
+    cred.name = name;
+    saveDb(db);
+    return json(200, { credential: publicCredential(cred) });
+  },
+
+  'DELETE /api/credential/:id': async (_body, { id }) => {
+    const db = loadDb();
+    const user = requireUser(db);
+    requireRecentReauth();
+    const cred = db.credentials.find((c) => c.id === id && c.userId === user.id);
+    if (!cred) throw new HttpError(404, 'Passkey not found.');
+    const remaining = db.credentials.filter((c) => c.userId === user.id && c.id !== id);
+    if (!remaining.length && !user.password) {
