+    }
+    db.credentials = db.credentials.filter((c) => c.id !== id);
+    saveDb(db);
+    return json(200, { success: true });
+  },
+
+  'PUT /api/user': async (body) => {
+    const db = loadDb();
+    const user = requireUser(db);
+    requireRecentReauth();
+    const name = normalizeEmail(body?.name);
+    const displayName = normalizeName(body?.displayName);
+    if (!/^[^\s@]+@[^\s@]+$/.test(name)) throw new HttpError(400, 'Enter a valid email address.');
+    if (!displayName) throw new HttpError(400, 'Enter your name.');
+    if (db.users.some((u) => u.name === name && u.id !== user.id)) throw new HttpError(409, 'That email is already in use.');
+    user.name = name;
+    user.displayName = displayName;
+    saveDb(db);
+    return json(200, publicUser(user, db));
+  },
+};
+
+const compiledRoutes = Object.entries(routes).map(([key, handler]) => {
+  const [method, pattern] = key.split(' ');
+  const names = [];
+  const regex = new RegExp(
+    '^' + pattern.replace(/:(\w+)/g, (_, n) => { names.push(n); return '([^/]+)'; }) + '$',
+  );
+  return { method, regex, names, handler };
+});
+
+/** fetch-compatible entry point for the mock API. */
+export async function mockFetch(input, init = {}) {
+  const url = new URL(typeof input === 'string' ? input : input.url, location.href);
+  const method = (init.method ?? 'GET').toUpperCase();
+  for (const route of compiledRoutes) {
+    if (route.method !== method) continue;
+    const match = url.pathname.match(route.regex);
+    if (!match) continue;
+    const params = Object.fromEntries(route.names.map((n, i) => [n, decodeURIComponent(match[i + 1])]));
+    try {
+      const body = init.body ? JSON.parse(init.body) : {};
+      return await route.handler(body, params);
+    } catch (err) {
+      if (err instanceof HttpError) return json(err.status, { error: err.message, code: err.code });
+      console.warn('Mock API error:', err);
+      return json(400, { error: 'The request could not be verified.' });
+    }
+  }
+  return json(404, { error: 'Not found' });
+}
