diff --git a/js/account.js b/js/account.js
new file mode 100644
index 0000000..9cfebc7
--- /dev/null
+++ b/js/account.js
@@ -0,0 +1,680 @@
+/**
+ * "My Account" UI: passkey sign-up, sign-in (modal + autofill), passkey
+ * management, profile updates and reauthentication for sensitive actions.
+ */
+import {
+  isWebAuthnSupported,
+  isConditionalMediationAvailable,
+  createPasskey,
+  getPasskey,
+  abortPendingCeremony,
+  isAbort,
+  describeError,
+  signals,
+} from './webauthn.js';
+import { LocalRelyingParty, RPError, REAUTH_WINDOW_MS } from './relying-party.js';
+
+const rp = new LocalRelyingParty();
+const supported = isWebAuthnSupported();
+
+const $ = (id) => document.getElementById(id);
+const els = {
+  accountLink: $('account-link'),
+  authLink: $('auth-link'),
+  dialog: $('account-dialog'),
+  status: $('account-status'),
+  unsupported: $('account-unsupported'),
+  signedOut: $('view-signed-out'),
+  signedIn: $('view-signed-in'),
+  tabs: { signin: $('tab-signin'), signup: $('tab-signup') },
+  panels: { signin: $('panel-signin'), signup: $('panel-signup') },
+  signinForm: $('signin-form'),
+  signupForm: $('signup-form'),
+  profileForm: $('profile-form'),
+  avatar: $('acct-avatar'),
+  welcomeName: $('acct-welcome-name'),
+  welcomeEmail: $('acct-welcome-email'),
+  passkeyList: $('passkey-list'),
+  addPasskeyBtn: $('add-passkey-btn'),
+  verificationStatus: $('verification-status'),
+  signoutBtn: $('signout-btn'),
+  reauthDialog: $('reauth-dialog'),
+  reauthReason: $('reauth-reason'),
+  reauthError: $('reauth-error'),
+  reauthBtn: $('reauth-btn'),
+  renameDialog: $('rename-dialog'),
+  renameForm: $('rename-form'),
+  renameInput: $('rename-input'),
+  renameError: $('rename-error'),
+  removeDialog: $('remove-dialog'),
+  removeMessage: $('remove-message'),
+  removeError: $('remove-error'),
+  removeConfirm: $('remove-confirm'),
+  toast: $('toast'),
+};
+
+let currentSession = null;
+let currentTab = 'signin';
+let conditionalRunning = false;
+
+/* ====================================================================
+ * Small UI helpers
+ * ================================================================== */
+function setBusy(btn, busy) {
+  if (!btn) return;
+  btn.disabled = busy || (!supported && btn.hasAttribute('data-requires-webauthn'));
+  if (busy) btn.setAttribute('aria-busy', 'true');
+  else btn.removeAttribute('aria-busy');
+}
+
+function showStatus(message, kind = 'info') {
+  els.status.textContent = message;
+  els.status.dataset.kind = kind;
+  els.status.hidden = false;
+}
+
+function clearStatus() {
+  els.status.hidden = true;
+  els.status.textContent = '';
+}
+
+function showInlineError(el, message) {
+  el.textContent = message;
+  el.hidden = !message;
+}
+
+let toastTimer;
+function toast(message) {
+  const t = els.toast;
+  t.textContent = message;
+  t.classList.add('is-visible');
+  try { if (t.matches(':popover-open')) t.hidePopover(); t.showPopover?.(); } catch { /* no popover support */ }
+  clearTimeout(toastTimer);
+  toastTimer = setTimeout(() => {
+    t.classList.remove('is-visible');
+    try { t.hidePopover?.(); } catch { /* ignore */ }
+  }, 3500);
+}
+
+function errorMessage(err, ceremony) {
+  if (err instanceof RPError) return err.message;
+  if (err instanceof DOMException) return describeError(err, ceremony);
+  console.error(err);
+  return 'Something went wrong. Please try again.';
+}
+
+/** Common handling for errors returned by a WebAuthn get() + verification. */
+function authErrorMessage(err) {
+  if (err instanceof RPError && err.code === 'unknown_credential' && err.credentialId) {
+    // Tell the password manager this passkey is dead so it stops offering it.
+    signals.unknownCredential(rp.rpId, err.credentialId);
+  }
+  return errorMessage(err, 'get');
+}
+
+function markInvalid(input, invalid) {
+  input.setAttribute('aria-invalid', String(!!invalid));
+}
+
+const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+
+const dateFmt = new Intl.DateTimeFormat(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
+const relFmt = new Intl.RelativeTimeFormat(undefined, { numeric: 'auto' });
+
+function relativeTime(ts) {
+  const diff = (ts - Date.now()) / 1000;
+  const units = [['year', 31536000], ['month', 2592000], ['week', 604800], ['day', 86400], ['hour', 3600], ['minute', 60]];
+  for (const [unit, secs] of units) {
+    if (Math.abs(diff) >= secs) return relFmt.format(Math.round(diff / secs), unit);
+  }
+  return 'just now';
+}
+
+/* ====================================================================
+ * Dialog + navigation
+ * ================================================================== */
+async function openAccount(tab) {
+  if (tab) currentTab = tab;
+  if (!els.dialog.open) els.dialog.showModal();
+  await render();
+}
+
+function closeAccount() {
+  if (els.dialog.open) els.dialog.close();
+}
+
+function updateNav() {
+  const signedIn = !!currentSession;
+  els.authLink.textContent = signedIn ? 'Logout' : 'Sign in';
+  els.authLink.dataset.state = signedIn ? 'signed-in' : 'signed-out';
+  els.authLink.setAttribute('href', signedIn ? '/logout' : '/account');
+}
+
+async function signOut() {
+  abortPendingCeremony();
+  await rp.signOut();
+  currentSession = null;
+  updateNav();
+  toast('You have been signed out.');
+  if (els.dialog.open) {
+    currentTab = 'signin';
+    await render();
+  }
+}
+
+/* ====================================================================
+ * Rendering
+ * ================================================================== */
+async function render() {
+  currentSession = await rp.getSession();
+  updateNav();
+  els.unsupported.hidden = supported;
+  if (currentSession) {
+    stopConditional();
+    els.signedOut.hidden = true;
+    els.signedIn.hidden = false;
+    renderSignedIn();
+    await renderPasskeys();
+  } else {
+    els.signedIn.hidden = true;
+    els.signedOut.hidden = false;
+    selectTab(currentTab, { focus: false });
+  }
+}
+
+function selectTab(name, { focus = true } = {}) {
+  currentTab = name;
+  for (const key of ['signin', 'signup']) {
+    const active = key === name;
+    els.tabs[key].setAttribute('aria-selected', String(active));
+    els.tabs[key].tabIndex = active ? 0 : -1;
+    els.panels[key].hidden = !active;
+  }
+  if (focus) els.tabs[name].focus();
+  if (name === 'signin') startConditional();
+}
+
+function renderSignedIn() {
+  const { user, verifiedAt } = currentSession;
+  const name = user.displayName || user.email;
+  els.avatar.textContent = name.trim().charAt(0).toUpperCase();
+  els.welcomeName.textContent = `Hi, ${name}!`;
+  els.welcomeEmail.textContent = user.email;
+  els.profileForm.elements.displayName.value = user.displayName;
+  els.profileForm.elements.email.value = user.email;
+  markInvalid(els.profileForm.elements.displayName, false);
+  markInvalid(els.profileForm.elements.email, false);
+  const recent = Date.now() - verifiedAt <= REAUTH_WINDOW_MS;
+  els.verificationStatus.textContent = recent
+    ? `You confirmed it’s you ${relativeTime(verifiedAt)}. Sensitive changes won’t ask again for a few minutes.`
+    : 'Sensitive changes, like your email or passkeys, will ask you to confirm it’s you with a passkey.';
+}
+
+async function renderPasskeys() {
+  let passkeys;
+  try {
+    passkeys = await rp.listPasskeys();
+  } catch (err) {
+    return handleSessionError(err);
+  }
+  const list = els.passkeyList;
+  list.replaceChildren();
+  const onlyOne = passkeys.length <= 1;
+
+  for (const pk of passkeys) {
+    const li = document.createElement('li');
+    li.className = 'acct-passkey';
+
+    const icon = document.createElement('span');
+    icon.className = 'acct-key-icon';
+    icon.setAttribute('aria-hidden', 'true');
+
+    const body = document.createElement('div');
+    body.className = 'acct-passkey-body';
+    const nameEl = document.createElement('div');
+    nameEl.className = 'acct-passkey-name';
+    nameEl.textContent = pk.name;
+
+    const badge = (text, cls, title) => {
+      const b = document.createElement('span');
+      b.className = `acct-badge ${cls || ''}`;
+      b.textContent = text;
+      if (title) b.title = title;
+      nameEl.append(b);
+    };
+    if (pk.backedUp) badge('Synced', 'acct-badge-sync', 'Backed up and available on your other devices');
+    else if (!pk.backupEligible) badge('This device only', '', 'Not synced – only works on the device or key where it was created');
+    if (pk.currentSession) badge('Used to sign in now', 'acct-badge-current');
+
+    const meta = document.createElement('p');
+    meta.className = 'acct-passkey-meta';
+    const parts = [`Added ${dateFmt.format(pk.createdAt)}`];
+    parts.push(pk.lastUsedAt ? `Last used ${relativeTime(pk.lastUsedAt)}` : 'Not used yet');
+    if (pk.provider && pk.provider !== pk.name) parts.push(pk.provider);
+    meta.textContent = parts.join(' · ');
+    body.append(nameEl, meta);
+
+    const actions = document.createElement('div');
+    actions.className = 'acct-passkey-actions';
+    const renameBtn = document.createElement('button');
+    renameBtn.type = 'button';
+    renameBtn.className = 'acct-btn acct-btn-secondary acct-btn-sm';
+    renameBtn.textContent = 'Rename';
+    renameBtn.setAttribute('aria-label', `Rename passkey ${pk.name}`);
+    renameBtn.addEventListener('click', () => openRename(pk));
+
+    const removeBtn = document.createElement('button');
+    removeBtn.type = 'button';
+    removeBtn.className = 'acct-btn acct-btn-secondary acct-btn-sm';
+    removeBtn.textContent = 'Remove';
+    removeBtn.setAttribute('aria-label', `Remove passkey ${pk.name}`);
+    if (onlyOne) {
+      removeBtn.disabled = true;
+      removeBtn.title = 'Add another passkey before removing your only one.';
+    }
+    removeBtn.addEventListener('click', () => openRemove(pk));
+    actions.append(renameBtn, removeBtn);
+
+    li.append(icon, body, actions);
+    list.append(li);
+  }
+}
+
+async function handleSessionError(err) {
+  if (err instanceof RPError && err.code === 'unauthenticated') {
+    currentSession = null;
+    await render();
+    showStatus(err.message, 'error');
+    return true;
+  }
+  return false;
+}
+
+/* ====================================================================
+ * Sign-in (autofill / conditional UI + modal)
+ * ================================================================== */
+async function startConditional() {
+  if (!supported || conditionalRunning || currentSession || !els.dialog.open || currentTab !== 'signin') return;
+  if (!(await isConditionalMediationAvailable())) return;
+  conditionalRunning = true;
+  try {
+    const options = await rp.startSignIn();
+    const credential = await getPasskey(options, { conditional: true });
+    conditionalRunning = false;
+    await completeSignIn(credential);
+  } catch (err) {
+    conditionalRunning = false;
+    if (isAbort(err)) return;
+    showStatus(authErrorMessage(err), 'error');
+    // Re-arm autofill after a verification failure so the user can pick
+    // another passkey (not after browser errors, to avoid a retry loop).
+    if (err instanceof RPError) setTimeout(startConditional, 0);
+  }
+}
+
+function stopConditional() {
+  if (conditionalRunning) abortPendingCeremony();
+  conditionalRunning = false;
+}
+
+async function completeSignIn(credential) {
+  const { user } = await rp.finishAuthentication(credential);
+  clearStatus();
+  els.signinForm.reset();
+  await render();
+  toast(`Welcome back, ${user.displayName || user.email}!`);
+}
+
+async function onSignIn(event) {
+  event.preventDefault();
+  const btn = event.submitter || els.signinForm.querySelector('button[type="submit"]');
+  clearStatus();
+  setBusy(btn, true);
+  stopConditional();
+  try {
+    const options = await rp.startSignIn();
+    const credential = await getPasskey(options);
+    await completeSignIn(credential);
+  } catch (err) {
+    if (!isAbort(err)) showStatus(authErrorMessage(err), 'error');
+  } finally {
+    setBusy(btn, false);
+    if (!currentSession) startConditional();
+  }
+}
+
+/* ====================================================================
+ * Registration
+ * ================================================================== */
+async function onSignUp(event) {
+  event.preventDefault();
+  const form = els.signupForm;
