+/** Run a server action; if it reports reauth_required, verify and retry once. */
+async function withReauth(reason, action) {
+  try {
+    return { ok: true, value: await action() };
+  } catch (err) {
+    if (!(err instanceof RPError && err.code === 'reauth_required')) throw err;
+    if (!(await promptReauth(reason))) return { ok: false };
+    return { ok: true, value: await action() };
+  }
+}
+
+/* ====================================================================
+ * Profile
+ * ================================================================== */
+async function onProfileSave(event) {
