+/**
+ * Daily Grind WebAuthn Relying Party.
+ *
+ * The site is deployed as static files, so this module plays the role of the
+ * account server: it issues ceremony options, verifies WebAuthn responses
+ * (challenge, origin, RP ID hash, user presence/verification flags, COSE public
+ * key, signature and signature counter) and stores accounts + passkeys.
+ *
+ * Every public method takes/returns plain JSON exactly as a REST backend
+ * would, so it can be replaced by `fetch('/api/passkeys/...')` calls without
+ * touching the UI. NOTE: when a real backend exists, all of this verification
+ * MUST move server-side — browser storage is not a trust boundary.
+ */
+import { b64url } from './webauthn.js';
