+export class RPError extends Error {
+  constructor(code, message, extra = {}) {
+    super(message);
+    this.name = 'RPError';
+    this.code = code;
+    Object.assign(this, extra);
+  }
+}
+
+/* ======================================================================
+ * Minimal CBOR decoder (RFC 8949 subset used by WebAuthn)
+ * ==================================================================== */
+function decodeCBOR(bytes, start = 0) {
+  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
+  let pos = start;
+
+  function readLength(info) {
+    if (info < 24) return info;
+    if (info === 24) return view.getUint8(pos++);
+    if (info === 25) { const v = view.getUint16(pos); pos += 2; return v; }
+    if (info === 26) { const v = view.getUint32(pos); pos += 4; return v; }
+    if (info === 27) {
+      const v = view.getUint32(pos) * 2 ** 32 + view.getUint32(pos + 4);
+      pos += 8;
+      return v;
+    }
+    throw new RPError('cbor', 'Unsupported CBOR length encoding');
+  }
+
+  function item() {
+    if (pos >= bytes.length) throw new RPError('cbor', 'Truncated CBOR data');
+    const initial = view.getUint8(pos++);
+    const major = initial >> 5;
+    const info = initial & 0x1f;
+    switch (major) {
+      case 0: return readLength(info);
+      case 1: return -1 - readLength(info);
+      case 2: {
+        const len = readLength(info);
+        const v = bytes.slice(pos, pos + len);
+        pos += len;
+        return v;
+      }
+      case 3: {
+        const len = readLength(info);
+        const v = new TextDecoder().decode(bytes.subarray(pos, pos + len));
+        pos += len;
+        return v;
+      }
+      case 4: {
+        const len = readLength(info);
+        const arr = [];
+        for (let i = 0; i < len; i++) arr.push(item());
+        return arr;
+      }
+      case 5: {
+        const len = readLength(info);
+        const map = new Map();
+        for (let i = 0; i < len; i++) {
+          const k = item();
+          map.set(k, item());
+        }
+        return map;
+      }
+      case 6: readLength(info); return item(); // ignore tags
+      case 7:
+        if (info === 20) return false;
+        if (info === 21) return true;
+        if (info === 22) return null;
+        if (info === 23) return undefined;
+        if (info === 25) { const v = view.getFloat16?.(pos); pos += 2; return v; }
+        if (info === 26) { const v = view.getFloat32(pos); pos += 4; return v; }
+        if (info === 27) { const v = view.getFloat64(pos); pos += 8; return v; }
+        throw new RPError('cbor', 'Unsupported CBOR simple value');
+      default:
+        throw new RPError('cbor', 'Unsupported CBOR major type');
+    }
+  }
+
+  const value = item();
+  return { value, end: pos };
+}
+
+/* ======================================================================
+ * Crypto helpers
+ * ==================================================================== */
+const sha256 = async (data) =>
+  new Uint8Array(await crypto.subtle.digest('SHA-256', data));
+
+const concat = (...parts) => {
+  const out = new Uint8Array(parts.reduce((n, p) => n + p.length, 0));
+  let o = 0;
+  for (const p of parts) { out.set(p, o); o += p.length; }
+  return out;
+};
+
+const equalBytes = (a, b) => a.length === b.length && a.every((v, i) => v === b[i]);
