+/** Convert a COSE_Key (Map) to { alg, jwk } usable with WebCrypto. */
+function coseToJwk(cose) {
+  const kty = cose.get(1);
+  const alg = cose.get(3);
+  if (kty === 2 && alg === COSE_ALG.ES256 && cose.get(-1) === 1) {
+    return { alg, jwk: { kty: 'EC', crv: 'P-256', x: b64url.encode(cose.get(-2)), y: b64url.encode(cose.get(-3)) } };
+  }
+  if (kty === 3 && alg === COSE_ALG.RS256) {
+    return { alg, jwk: { kty: 'RSA', alg: 'RS256', n: b64url.encode(cose.get(-1)), e: b64url.encode(cose.get(-2)) } };
+  }
+  if (kty === 1 && alg === COSE_ALG.EdDSA && cose.get(-1) === 6) {
+    return { alg, jwk: { kty: 'OKP', crv: 'Ed25519', x: b64url.encode(cose.get(-2)) } };
+  }
+  throw new RPError('unsupported_key', 'This passkey uses an unsupported key type.');
+}
+
+function importParams(alg) {
+  switch (alg) {
+    case COSE_ALG.ES256: return [{ name: 'ECDSA', namedCurve: 'P-256' }, { name: 'ECDSA', hash: 'SHA-256' }];
+    case COSE_ALG.RS256: return [{ name: 'RSASSA-PKCS1-v1_5', hash: 'SHA-256' }, { name: 'RSASSA-PKCS1-v1_5' }];
+    case COSE_ALG.EdDSA: return [{ name: 'Ed25519' }, { name: 'Ed25519' }];
+    default: throw new RPError('unsupported_key', 'Unsupported signature algorithm.');
+  }
+}
+
+async function importKey(alg, jwk) {
+  const [params] = importParams(alg);
+  return crypto.subtle.importKey('jwk', jwk, params, false, ['verify']);
+}
+
+/** ECDSA signatures from authenticators are ASN.1 DER; WebCrypto wants raw r||s. */
+function derToRawEcdsa(der, size = 32) {
+  let p = 0;
+  const readLen = () => {
+    let len = der[p++];
+    if (len & 0x80) {
+      const n = len & 0x7f;
+      len = 0;
+      for (let i = 0; i < n; i++) len = (len << 8) | der[p++];
+    }
+    return len;
+  };
+  if (der[p++] !== 0x30) throw new RPError('bad_signature', 'Malformed signature');
+  readLen();
+  const readInt = () => {
+    if (der[p++] !== 0x02) throw new RPError('bad_signature', 'Malformed signature');
+    const len = readLen();
+    let int = der.subarray(p, p + len);
+    p += len;
+    while (int.length > size && int[0] === 0) int = int.subarray(1);
+    if (int.length > size) throw new RPError('bad_signature', 'Malformed signature');
+    const out = new Uint8Array(size);
+    out.set(int, size - int.length);
+    return out;
+  };
+  return concat(readInt(), readInt());
+}
+
+async function verifySignature(alg, jwk, signature, data) {
+  const key = await importKey(alg, jwk);
+  const [, verifyParams] = importParams(alg);
+  const sig = alg === COSE_ALG.ES256 ? derToRawEcdsa(signature) : signature;
+  return crypto.subtle.verify(verifyParams, key, sig, data);
+}
