+function parseAuthData(authData) {
+  if (authData.length < 37) throw new RPError('bad_auth_data', 'Authenticator data is too short.');
+  const view = new DataView(authData.buffer, authData.byteOffset, authData.byteLength);
+  const flagsByte = authData[32];
+  const parsed = {
+    rpIdHash: authData.slice(0, 32),
+    flags: {
+      up: !!(flagsByte & FLAG.UP),
+      uv: !!(flagsByte & FLAG.UV),
+      be: !!(flagsByte & FLAG.BE),
+      bs: !!(flagsByte & FLAG.BS),
+      at: !!(flagsByte & FLAG.AT),
+      ed: !!(flagsByte & FLAG.ED),
+    },
+    signCount: view.getUint32(33),
+  };
+  if (parsed.flags.bs && !parsed.flags.be) {
+    throw new RPError('bad_auth_data', 'Invalid backup flags.');
+  }
+  if (parsed.flags.at) {
+    let p = 37;
+    parsed.aaguid = authData.slice(p, p + 16); p += 16;
+    const idLen = view.getUint16(p); p += 2;
+    if (idLen > 1023) throw new RPError('bad_auth_data', 'Credential ID is too long.');
+    parsed.credentialId = authData.slice(p, p + idLen); p += idLen;
+    const { value, end } = decodeCBOR(authData, p);
+    parsed.credentialPublicKey = value;
+    parsed.attestedEnd = end;
+  }
+  return parsed;
+}
