+  if (/android/i.test(navigator.userAgent)) return 'Passkey on Android';
+  if (/iphone|ipad/i.test(navigator.userAgent)) return 'Passkey on iPhone/iPad';
+  if (/linux/i.test(ua)) return 'Passkey on Linux';
+  return 'Passkey';
+}
+
+/* ======================================================================
+ * Relying party
+ * ==================================================================== */
+export class LocalRelyingParty {
+  constructor({ rpId = location.hostname, origin = location.origin } = {}) {
+    this.rpId = rpId;
+    this.origin = origin;
+    this.challenges = new Map(); // challenge -> { purpose, expires, ...context }
+  }
+
+  /* ---------- persistence ---------- */
+  #load() {
+    try {
+      const data = JSON.parse(localStorage.getItem(STORE_KEY));
+      if (data && data.users && data.credentials) return data;
+    } catch { /* corrupt store -> reset */ }
+    return { users: {}, credentials: {} };
+  }
+
+  #save(data) {
+    localStorage.setItem(STORE_KEY, JSON.stringify(data));
+  }
+
+  #readSession() {
+    try {
+      const s = JSON.parse(localStorage.getItem(SESSION_KEY));
+      if (s && s.expiresAt > Date.now()) return s;
+    } catch { /* ignore */ }
+    localStorage.removeItem(SESSION_KEY);
+    return null;
+  }
+
+  #writeSession(session) {
+    if (session) localStorage.setItem(SESSION_KEY, JSON.stringify(session));
+    else localStorage.removeItem(SESSION_KEY);
+  }
+
+  #requireSession() {
+    const session = this.#readSession();
+    if (!session) throw new RPError('unauthenticated', 'Please sign in again.');
+    const data = this.#load();
+    const user = data.users[session.userId];
+    if (!user) {
+      this.#writeSession(null);
+      throw new RPError('unauthenticated', 'Your account could not be found. Please sign in again.');
+    }
+    return { session, data, user };
+  }
+
+  #requireRecentVerification(session) {
+    if (!session.verifiedAt || Date.now() - session.verifiedAt > REAUTH_WINDOW_MS) {
+      throw new RPError('reauth_required', 'Please confirm it’s you to continue.');
+    }
+  }
+
+  /* ---------- challenges ---------- */
+  #issueChallenge(purpose, context = {}) {
+    const now = Date.now();
+    for (const [c, v] of this.challenges) if (v.expires < now) this.challenges.delete(c);
+    const challenge = randomId(32);
+    this.challenges.set(challenge, { purpose, expires: now + CHALLENGE_TTL_MS, ...context });
+    return challenge;
+  }
+
+  #consumeChallenge(challenge, purpose) {
+    const entry = this.challenges.get(challenge);
+    this.challenges.delete(challenge); // single use, even on failure
+    if (!entry || entry.purpose !== purpose || entry.expires < Date.now()) {
+      throw new RPError('bad_challenge', 'This request has expired. Please try again.');
+    }
