+  #checkClientData(clientDataJSON, expectedType) {
+    let clientData;
+    try {
+      clientData = JSON.parse(new TextDecoder().decode(clientDataJSON));
+    } catch {
+      throw new RPError('bad_client_data', 'Malformed client data.');
+    }
+    if (clientData.type !== expectedType) throw new RPError('bad_client_data', 'Unexpected ceremony type.');
+    if (clientData.origin !== this.origin) throw new RPError('bad_origin', 'Request came from an unexpected origin.');
+    if (clientData.crossOrigin === true) throw new RPError('bad_origin', 'Cross-origin requests are not allowed.');
+    return clientData;
+  }
