+  async #checkRpIdHash(authData) {
+    const expected = await sha256(new TextEncoder().encode(this.rpId));
+    if (!equalBytes(authData.rpIdHash, expected)) {
+      throw new RPError('bad_rp_id', 'Passkey was created for a different site.');
+    }
+  }
+
+  #publicUser(user) {
+    return { id: user.id, email: user.email, displayName: user.displayName, createdAt: user.createdAt };
+  }
+
+  #publicPasskey(c) {
+    return {
+      id: c.id,
+      name: c.name,
+      createdAt: c.createdAt,
+      lastUsedAt: c.lastUsedAt,
+      backupEligible: c.backupEligible,
+      backedUp: c.backedUp,
+      transports: c.transports,
+      attachment: c.attachment,
+      provider: KNOWN_PROVIDERS[c.aaguid] || null,
+    };
+  }
+
+  #userPasskeys(data, userId) {
+    return Object.values(data.credentials)
+      .filter((c) => c.userId === userId)
+      .sort((a, b) => a.createdAt - b.createdAt);
+  }
+
+  #creationOptions(challenge, user, exclude) {
+    return {
+      rp: { id: this.rpId, name: RP_NAME },
+      user: { id: user.id, name: user.email, displayName: user.displayName || user.email },
+      challenge,
+      pubKeyCredParams: [
+        { type: 'public-key', alg: COSE_ALG.ES256 },
+        { type: 'public-key', alg: COSE_ALG.EdDSA },
+        { type: 'public-key', alg: COSE_ALG.RS256 },
+      ],
+      timeout: CEREMONY_TIMEOUT_MS,
+      excludeCredentials: exclude.map((c) => ({ type: 'public-key', id: c.id, transports: c.transports })),
+      authenticatorSelection: { residentKey: 'required', requireResidentKey: true, userVerification: 'preferred' },
+      attestation: 'none',
+      hints: [],
+      extensions: { credProps: true },
+    };
+  }
+
+  /* ================== Registration ================== */
+
+  /** POST /api/passkeys/register/options (new customer) */
+  async startSignUp({ email, displayName }) {
+    email = String(email || '').trim().toLowerCase();
+    displayName = String(displayName || '').trim();
+    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) throw new RPError('invalid_email', 'Please enter a valid email address.');
+    if (!displayName) throw new RPError('invalid_name', 'Please enter your name.');
+    if (displayName.length > 64) throw new RPError('invalid_name', 'Name must be 64 characters or fewer.');
+    const data = this.#load();
+    if (Object.values(data.users).some((u) => u.email === email)) {
+      throw new RPError('email_taken', 'An account with this email already exists. Try signing in instead.');
+    }
+    // User handle: random, opaque, contains no personal information.
+    const pendingUser = { id: randomId(32), email, displayName };
+    const challenge = this.#issueChallenge('register', { signup: true, user: pendingUser });
+    return this.#creationOptions(challenge, pendingUser, []);
+  }
+
+  /** POST /api/passkeys/options (add a passkey to the signed-in account) */
+  async startAddPasskey() {
+    const { session, data, user } = this.#requireSession();
+    this.#requireRecentVerification(session);
+    const challenge = this.#issueChallenge('register', { signup: false, userId: user.id });
+    return this.#creationOptions(challenge, user, this.#userPasskeys(data, user.id));
+  }
+
+  /** POST /api/passkeys/register/verify */
+  async finishRegistration(credential) {
+    const clientDataJSON = b64url.decode(credential.response.clientDataJSON);
+    const clientData = this.#checkClientData(clientDataJSON, 'webauthn.create');
+    const ctx = this.#consumeChallenge(clientData.challenge, 'register');
+
+    const attObj = decodeCBOR(b64url.decode(credential.response.attestationObject)).value;
+    if (!(attObj instanceof Map) || !(attObj.get('authData') instanceof Uint8Array)) {
+      throw new RPError('bad_attestation', 'Malformed attestation object.');
+    }
+    // attestation: 'none' was requested; we don't rely on attestation statements.
+    const authData = parseAuthData(attObj.get('authData'));
+    await this.#checkRpIdHash(authData);
+    if (!authData.flags.up) throw new RPError('no_user_presence', 'User presence was not confirmed.');
+    if (!authData.flags.at || !authData.credentialId) throw new RPError('bad_auth_data', 'No credential data returned.');
+
+    const credentialId = b64url.encode(authData.credentialId);
+    if (credentialId !== credential.id) throw new RPError('bad_credential', 'Credential ID mismatch.');
+
+    const { alg, jwk } = coseToJwk(authData.credentialPublicKey);
+    await importKey(alg, jwk); // ensure the key is valid / supported by this browser
+
+    const data = this.#load();
+    if (data.credentials[credentialId]) throw new RPError('duplicate', 'This passkey is already registered.');
+
+    let user;
+    let session = this.#readSession();
+    if (ctx.signup) {
+      if (Object.values(data.users).some((u) => u.email === ctx.user.email)) {
+        throw new RPError('email_taken', 'An account with this email already exists.');
+      }
+      user = { ...ctx.user, createdAt: Date.now() };
+      data.users[user.id] = user;
+    } else {
+      if (!session || session.userId !== ctx.userId) throw new RPError('unauthenticated', 'Please sign in again.');
+      user = data.users[ctx.userId];
+      if (!user) throw new RPError('unauthenticated', 'Account not found.');
+    }
+
+    const transports = credential.response.transports || [];
+    const aaguid = formatAaguid(authData.aaguid);
+    data.credentials[credentialId] = {
+      id: credentialId,
+      userId: user.id,
+      alg,
+      publicKey: jwk,
+      signCount: authData.signCount,
+      aaguid,
+      transports,
+      attachment: credential.authenticatorAttachment || null,
+      discoverable: credential.clientExtensionResults?.credProps?.rk ?? null,
+      backupEligible: authData.flags.be,
+      backedUp: authData.flags.bs,
+      userVerified: authData.flags.uv,
+      name: defaultPasskeyName(aaguid, credential.authenticatorAttachment, transports),
+      createdAt: Date.now(),
+      lastUsedAt: null,
+    };
