+  }
+
+  /* ================== Authentication ================== */
+
+  /** POST /api/passkeys/authenticate/options — discoverable sign-in (modal or autofill) */
+  async startSignIn() {
+    const challenge = this.#issueChallenge('authenticate', { reauth: false });
+    return { challenge, rpId: this.rpId, timeout: CEREMONY_TIMEOUT_MS, userVerification: 'preferred', allowCredentials: [] };
+  }
+
+  /** POST /api/passkeys/reauthenticate/options — confirm the signed-in user */
+  async startReauthentication() {
+    const { data, user } = this.#requireSession();
+    const passkeys = this.#userPasskeys(data, user.id);
+    const challenge = this.#issueChallenge('authenticate', { reauth: true, userId: user.id });
