+      challenge,
+      rpId: this.rpId,
+      timeout: CEREMONY_TIMEOUT_MS,
+      userVerification: 'required',
+      allowCredentials: passkeys.map((c) => ({ type: 'public-key', id: c.id, transports: c.transports })),
+    };
+  }
+
+  /** POST /api/passkeys/authenticate/verify */
+  async finishAuthentication(credential) {
+    const clientDataJSON = b64url.decode(credential.response.clientDataJSON);
+    const clientData = this.#checkClientData(clientDataJSON, 'webauthn.get');
+    const ctx = this.#consumeChallenge(clientData.challenge, 'authenticate');
+
+    const data = this.#load();
+    const stored = data.credentials[credential.id];
+    if (!stored) {
+      throw new RPError('unknown_credential', 'This passkey is no longer registered with The Daily Grind. It may have been removed.', {
+        credentialId: credential.id,
+      });
+    }
+    const user = data.users[stored.userId];
+    if (!user) throw new RPError('unknown_credential', 'Account not found.', { credentialId: credential.id });
+
+    if (credential.response.userHandle && credential.response.userHandle !== user.id) {
+      throw new RPError('bad_user_handle', 'Passkey does not belong to this account.');
+    }
+    if (ctx.reauth) {
+      const session = this.#readSession();
+      if (!session || session.userId !== ctx.userId || stored.userId !== ctx.userId) {
+        throw new RPError('wrong_account', 'Please use a passkey for the account you are signed in to.');
+      }
+    }
