+    const authDataBytes = b64url.decode(credential.response.authenticatorData);
+    const authData = parseAuthData(authDataBytes);
+    await this.#checkRpIdHash(authData);
+    if (!authData.flags.up) throw new RPError('no_user_presence', 'User presence was not confirmed.');
+    if (ctx.reauth && !authData.flags.uv) {
+      throw new RPError('no_user_verification', 'Your device must verify you (PIN, fingerprint or face) to continue.');
+    }
+
+    const signedData = concat(authDataBytes, await sha256(clientDataJSON));
