+    if (!valid) throw new RPError('bad_signature', 'Passkey signature could not be verified.');
+
+    if ((authData.signCount > 0 || stored.signCount > 0) && authData.signCount <= stored.signCount) {
+      throw new RPError('cloned_authenticator', 'This passkey may have been cloned. Please contact support.');
+    }
