+    const now = Date.now();
+    stored.signCount = authData.signCount;
+    stored.backedUp = authData.flags.bs;
+    stored.lastUsedAt = now;
+    this.#save(data);
+
+    let session;
+    if (ctx.reauth) {
+      session = { ...this.#readSession(), verifiedAt: now };
+    } else {
+      session = { userId: user.id, credentialId: stored.id, signedInAt: now, verifiedAt: now, expiresAt: now + SESSION_TTL_MS };
+    }
+    this.#writeSession(session);
+    return { user: this.#publicUser(user) };
+  }
+
+  /* ================== Session ================== */
+
+  /** GET /api/session */
+  async getSession() {
+    const session = this.#readSession();
+    if (!session) return null;
+    const data = this.#load();
+    const user = data.users[session.userId];
+    if (!user) { this.#writeSession(null); return null; }
+    return {
+      user: this.#publicUser(user),
+      signedInAt: session.signedInAt,
+      verifiedAt: session.verifiedAt,
+      recentlyVerified: Date.now() - session.verifiedAt <= REAUTH_WINDOW_MS,
+    };
+  }
+
+  /** POST /api/logout */
+  async signOut() {
+    this.#writeSession(null);
+  }
+
+  /* ================== Passkey management ================== */
+
+  /** GET /api/passkeys */
+  async listPasskeys() {
+    const { session, data, user } = this.#requireSession();
+    return this.#userPasskeys(data, user.id).map((c) => ({
+      ...this.#publicPasskey(c),
+      currentSession: c.id === session.credentialId,
+    }));
+  }
+
+  /** PATCH /api/passkeys/:id */
+  async renamePasskey(id, name) {
+    const { data, user } = this.#requireSession();
+    name = String(name || '').trim();
+    if (!name) throw new RPError('invalid_name', 'Please enter a name for this passkey.');
+    if (name.length > 48) throw new RPError('invalid_name', 'Passkey names must be 48 characters or fewer.');
+    const cred = data.credentials[id];
+    if (!cred || cred.userId !== user.id) throw new RPError('not_found', 'Passkey not found.');
+    cred.name = name;
+    this.#save(data);
+    return this.#publicPasskey(cred);
+  }
+
+  /** DELETE /api/passkeys/:id — requires recent verification */
+  async deletePasskey(id) {
+    const { session, data, user } = this.#requireSession();
+    this.#requireRecentVerification(session);
+    const cred = data.credentials[id];
+    if (!cred || cred.userId !== user.id) throw new RPError('not_found', 'Passkey not found.');
+    if (this.#userPasskeys(data, user.id).length <= 1) {
+      throw new RPError('last_passkey', 'You can’t remove your only passkey — add another one first so you don’t get locked out.');
+    }
+    delete data.credentials[id];
+    this.#save(data);
+    return { remainingIds: this.#userPasskeys(data, user.id).map((c) => c.id) };
+  }
+
+  /* ================== Profile ================== */
+
+  /** PATCH /api/profile — email changes require recent verification */
+  async updateProfile({ displayName, email }) {
+    const { session, data, user } = this.#requireSession();
+    displayName = String(displayName ?? user.displayName).trim();
+    email = String(email ?? user.email).trim().toLowerCase();
+    if (!displayName) throw new RPError('invalid_name', 'Please enter your name.');
+    if (displayName.length > 64) throw new RPError('invalid_name', 'Name must be 64 characters or fewer.');
+    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) throw new RPError('invalid_email', 'Please enter a valid email address.');
+    if (email !== user.email) {
+      this.#requireRecentVerification(session);
+      if (Object.values(data.users).some((u) => u.id !== user.id && u.email === email)) {
+        throw new RPError('email_taken', 'Another account already uses this email.');
+      }
+    }
+    user.displayName = displayName;
+    user.email = email;
+    this.#save(data);
+    return this.#publicUser(user);
+  }
+}
