+/**
+ * Browser-side WebAuthn helpers: base64url, JSON (de)serialisation of
+ * ceremony options/credentials, feature detection, ceremony abort handling,
+ * the Signal API and user-friendly error messages.
+ */
+
+export const b64url = {
+  encode(input) {
+    const bytes = input instanceof Uint8Array ? input : new Uint8Array(input);
+    let bin = '';
+    for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
+    return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+  },
+  decode(str) {
+    const b64 = str.replace(/-/g, '+').replace(/_/g, '/');
+    const bin = atob(b64 + '='.repeat((4 - (b64.length % 4)) % 4));
+    const out = new Uint8Array(bin.length);
+    for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
+    return out;
+  },
+};
+
+export function isWebAuthnSupported() {
+  return (
+    window.isSecureContext &&
+    typeof window.PublicKeyCredential === 'function' &&
+    typeof navigator.credentials?.create === 'function' &&
+    typeof navigator.credentials?.get === 'function'
+  );
+}
+
+export async function isConditionalMediationAvailable() {
+  if (!isWebAuthnSupported()) return false;
+  try {
+    if (typeof PublicKeyCredential.getClientCapabilities === 'function') {
+      const caps = await PublicKeyCredential.getClientCapabilities();
+      if (typeof caps.conditionalGet === 'boolean') return caps.conditionalGet;
+    }
+    return (await PublicKeyCredential.isConditionalMediationAvailable?.()) === true;
+  } catch {
+    return false;
+  }
+}
+
+/* ---------- Options: JSON -> WebAuthn API objects ---------- */
+
+function decodeDescriptors(list) {
+  return (list || []).map((d) => ({ ...d, id: b64url.decode(d.id) }));
+}
+
+export function parseCreationOptions(json) {
+  if (typeof PublicKeyCredential.parseCreationOptionsFromJSON === 'function') {
+    try {
+      return PublicKeyCredential.parseCreationOptionsFromJSON(json);
+    } catch { /* fall through to manual parsing */ }
+  }
+  return {
+    ...json,
+    challenge: b64url.decode(json.challenge),
+    user: { ...json.user, id: b64url.decode(json.user.id) },
+    excludeCredentials: decodeDescriptors(json.excludeCredentials),
+  };
+}
+
+export function parseRequestOptions(json) {
+  if (typeof PublicKeyCredential.parseRequestOptionsFromJSON === 'function') {
+    try {
+      return PublicKeyCredential.parseRequestOptionsFromJSON(json);
+    } catch { /* fall through to manual parsing */ }
+  }
+  return {
+    ...json,
+    challenge: b64url.decode(json.challenge),
+    allowCredentials: decodeDescriptors(json.allowCredentials),
+  };
+}
+
+/* ---------- Credential -> JSON ---------- */
+
+export function credentialToJSON(cred) {
+  // Native toJSON() is preferred, but some password-manager extensions
+  // inject broken implementations, so always keep a manual fallback.
+  try {
+    if (typeof cred.toJSON === 'function') {
+      const json = cred.toJSON();
+      if (json?.response?.clientDataJSON) return json;
+    }
+  } catch { /* use manual serialisation */ }
+
+  const r = cred.response;
+  const response = { clientDataJSON: b64url.encode(r.clientDataJSON) };
+  if ('attestationObject' in r) {
+    response.attestationObject = b64url.encode(r.attestationObject);
+    response.transports = typeof r.getTransports === 'function' ? r.getTransports() : [];
+  } else {
+    response.authenticatorData = b64url.encode(r.authenticatorData);
+    response.signature = b64url.encode(r.signature);
+    if (r.userHandle) response.userHandle = b64url.encode(r.userHandle);
+  }
+  return {
+    id: cred.id,
+    rawId: b64url.encode(cred.rawId),
+    type: cred.type,
+    authenticatorAttachment: cred.authenticatorAttachment ?? null,
+    clientExtensionResults: cred.getClientExtensionResults?.() ?? {},
+    response,
+  };
+}
+
+/* ---------- Ceremonies ---------- */
+
+// Only one WebAuthn request may be pending at a time. Starting a new one
+// (e.g. a modal sign-in) must cancel any pending conditional (autofill) request.
+let pending = null;
+
+export function abortPendingCeremony() {
+  if (pending) {
+    pending.abort(new DOMException('Superseded by another request', 'AbortError'));
+    pending = null;
+  }
+}
+
+function nextSignal() {
+  abortPendingCeremony();
+  pending = new AbortController();
+  return pending.signal;
+}
+
+export async function createPasskey(optionsJSON) {
+  const publicKey = parseCreationOptions(optionsJSON);
+  const cred = await navigator.credentials.create({ publicKey, signal: nextSignal() });
+  return credentialToJSON(cred);
+}
+
+export async function getPasskey(optionsJSON, { conditional = false } = {}) {
+  const publicKey = parseRequestOptions(optionsJSON);
+  const request = { publicKey, signal: nextSignal() };
+  if (conditional) request.mediation = 'conditional';
+  const cred = await navigator.credentials.get(request);
+  return credentialToJSON(cred);
+}
+
+/* ---------- Signal API (keeps password managers in sync) ---------- */
+
+async function signal(method, payload) {
+  try {
+    if (typeof PublicKeyCredential?.[method] === 'function') {
+      await PublicKeyCredential[method](payload);
+    }
+  } catch (err) {
+    console.debug(`[passkeys] ${method} failed`, err);
+  }
+}
+
+export const signals = {
+  unknownCredential: (rpId, credentialId) =>
+    signal('signalUnknownCredential', { rpId, credentialId }),
+  allAcceptedCredentials: (rpId, userId, allAcceptedCredentialIds) =>
+    signal('signalAllAcceptedCredentials', { rpId, userId, allAcceptedCredentialIds }),
+  currentUserDetails: (rpId, userId, name, displayName) =>
+    signal('signalCurrentUserDetails', { rpId, userId, name, displayName }),
+};
+
+/* ---------- Errors ---------- */
+
+export function isAbort(err) {
+  return err?.name === 'AbortError';
+}
+
+export function describeError(err, ceremony = 'get') {
+  switch (err?.name) {
+    case 'NotAllowedError':
+      return ceremony === 'create'
+        ? 'Passkey creation was cancelled or timed out.'
+        : 'Sign-in was cancelled, timed out, or no passkey was found for this site.';
+    case 'InvalidStateError':
+      return 'A passkey for this account already exists on this device or password manager.';
+    case 'SecurityError':
+      return 'Passkeys are not available on this domain. Make sure you are using HTTPS.';
+    case 'NotSupportedError':
+      return 'Your device does not support the required passkey type.';
+    case 'ConstraintError':
+      return 'Your device could not verify you (e.g. no screen lock or biometric set up).';
+    default:
+      return err?.message || 'Something went wrong. Please try again.';
+  }
+}

