--- /dev/null
+++ b/src/components/AccountSettings.tsx
@@ -0,0 +1,486 @@
+import React, { useCallback, useEffect, useId, useRef, useState } from 'react';
+import { useReauth } from './ReauthDialog';
+import {
+  authUrl,
+  getCapabilities,
+  isReauthRequired,
+  postJSON,
+  readError,
+  registerPasskey,
+  signalAllAcceptedCredentials,
+  signalCurrentUserDetails,
+  type PasskeySummary,
+} from '../lib/passkeys-client';
+
+interface AccountSettingsProps {
+  username: string;
+  displayName: string;
+}
+
+interface PasskeyList {
+  rpId: string;
+  userId: string;
+  credentials: PasskeySummary[];
+}
+
+const dateFormat = new Intl.DateTimeFormat(undefined, { dateStyle: 'medium', timeStyle: 'short' });
+const signInHref = `${import.meta.env.BASE_URL}signin`;
+
+export default function AccountSettings({ username, displayName: initialDisplayName }: AccountSettingsProps) {
+  const [list, setList] = useState<PasskeyList | null>(null);
+  const [loadError, setLoadError] = useState<string | null>(null);
+  const [notice, setNotice] = useState<{ type: 'success' | 'error'; text: string } | null>(null);
+  const [canCreate, setCanCreate] = useState<boolean | null>(null);
+  const [creating, setCreating] = useState(false);
+  const [pendingDelete, setPendingDelete] = useState<PasskeySummary | null>(null);
+  const hasPasskeys = (list?.credentials.length ?? 0) > 0;
+  const { requestReauth, reauthDialog } = useReauth(username, hasPasskeys);
+
+  const fetchPasskeys = useCallback(async () => {
+    const response = await fetch(authUrl('passkeys'), { cache: 'no-store' });
+    if (response.status === 401) {
+      window.location.assign(signInHref);
+      return null;
+    }
+    if (!response.ok) throw new Error(await readError(response, 'We couldn’t load your passkeys.'));
+    const data = (await response.json()) as PasskeyList;
+    setList(data);
+    return data;
+  }, []);
+
+  /** Refreshes the list and keeps the user's password managers in sync with it. */
+  const refreshAndSync = useCallback(async () => {
+    const data = await fetchPasskeys();
+    if (data) await signalAllAcceptedCredentials(data.rpId, data.userId, data.credentials.map((c) => c.id));
+  }, [fetchPasskeys]);
+
+  useEffect(() => {
+    refreshAndSync().catch((err) => setLoadError((err as Error).message));
+    // Security keys are allowed here, but we still require a platform authenticator to promote passkeys.
+    getCapabilities().then((c) => setCanCreate(!!c.passkeyPlatformAuthenticator));
+  }, [refreshAndSync]);
+
+  /** Runs a sensitive request, prompting for reauthentication and retrying once if the server asks. */
+  const withReauth = async (reason: string, run: () => Promise<Response>) => {
+    let response = await run();
+    if (await isReauthRequired(response)) {
+      if (!(await requestReauth(reason))) return null;
+      response = await run();
+    }
+    return response;
+  };
+
+  const handleCreate = async () => {
+    setNotice(null);
+    setCreating(true);
+    try {
+      let result = await registerPasskey();
+      if (result.status === 'reauth-required') {
+        if (!(await requestReauth('Verify your identity before adding a new passkey to your account.'))) return;
+        result = await registerPasskey();
+      }
+      switch (result.status) {
+        case 'created':
+          setNotice({ type: 'success', text: `Passkey “${result.credential.name}” added.` });
+          await fetchPasskeys();
+          break;
+        case 'exists':
+          setNotice({ type: 'error', text: 'This device or password manager already has a passkey for your account.' });
+          break;
+        case 'error':
+          setNotice({ type: 'error', text: result.message });
+          break;
+      }
+    } finally {
+      setCreating(false);
+    }
+  };
+
+  const handleRename = async (passkey: PasskeySummary, name: string) => {
+    setNotice(null);
+    const response = await postJSON(`passkeys/${encodeURIComponent(passkey.id)}`, { name }, 'PUT');
+    if (!response.ok) {
+      setNotice({ type: 'error', text: await readError(response) });
+      return false;
+    }
+    // A passkey nickname is a server-side label only; no Signal API call is needed.
+    await fetchPasskeys();
+    setNotice({ type: 'success', text: 'Passkey renamed.' });
+    return true;
+  };
+
+  const handleDelete = async (passkey: PasskeySummary) => {
+    setNotice(null);
+    const response = await withReauth('Verify your identity before removing a passkey.', () =>
+      postJSON(`passkeys/${encodeURIComponent(passkey.id)}`, undefined, 'DELETE'),
+    );
+    if (!response) return;
+    if (!response.ok) {
+      setNotice({ type: 'error', text: await readError(response) });
+      return;
+    }
+    // Tell password managers which passkeys remain valid so the deleted one stops being offered.
+    await refreshAndSync();
+    setNotice({ type: 'success', text: `Passkey “${passkey.name}” removed.` });
+  };
+
+  const handleDisplayNameSave = async (newDisplayName: string) => {
+    setNotice(null);
+    const response = await withReauth('Verify your identity before changing your account details.', () =>
+      postJSON('user', { displayName: newDisplayName }, 'PUT'),
+    );
+    if (!response) return false;
+    if (!response.ok) {
+      setNotice({ type: 'error', text: await readError(response) });
+      return false;
+    }
+    const profile = await response.json();
+    // Update the name shown in passkey account pickers.
+    await signalCurrentUserDetails({
+      rpId: profile.rpId,
+      userId: profile.userId,
+      name: profile.name,
+      displayName: profile.displayName,
+    });
+    setNotice({ type: 'success', text: 'Display name updated.' });
+    return true;
+  };
+
+  const handleSignOut = async () => {
+    await postJSON('logout');
+    window.location.assign(import.meta.env.BASE_URL);
+  };
+
+  return (
+    <div className="mx-auto max-w-2xl space-y-8">
+      <div className="flex flex-wrap items-end justify-between gap-4 border-b border-gray-200 pb-4">
+        <div>
+          <h1 className="text-3xl font-bold text-gray-900">Account settings</h1>
+          <p className="mt-1 text-sm text-gray-600">
+            Signed in as <strong>{username}</strong>
+          </p>
+        </div>
+        <button
+          type="button"
+          onClick={handleSignOut}
+          className="rounded-md border border-gray-300 px-3 py-2 text-sm font-medium text-gray-700 hover:bg-gray-50"
+        >
+          Sign out
+        </button>
+      </div>
+
+      {notice && (
+        <div
+          role={notice.type === 'error' ? 'alert' : 'status'}
+          className={`rounded-lg p-3 text-sm ${notice.type === 'error' ? 'bg-red-100 text-red-700' : 'bg-green-100 text-green-700'}`}
+        >
+          {notice.text}
+        </div>
+      )}
+
+      <ProfileSection username={username} initialDisplayName={initialDisplayName} onSave={handleDisplayNameSave} />
+
+      <section aria-labelledby="passkeys-heading" className="rounded-lg border border-gray-200 p-6">
+        <div className="flex flex-wrap items-start justify-between gap-4">
+          <div>
+            <h2 id="passkeys-heading" className="text-xl font-semibold text-gray-900">
+              Passkeys
+            </h2>
+            <p className="mt-1 max-w-prose text-sm text-gray-600">
+              Sign in with your fingerprint, face, screen lock, or a security key instead of a password.
+            </p>
+          </div>
+          {canCreate && (
+            <button
+              type="button"
+              onClick={handleCreate}
+              disabled={creating}
+              className="rounded-md bg-gray-900 px-4 py-2 text-sm font-medium text-white hover:bg-gray-800 disabled:cursor-not-allowed disabled:opacity-75"
+            >
+              {creating ? 'Creating…' : 'Create a passkey'}
+            </button>
+          )}
+        </div>
+
+        {canCreate === false && (
+          <p className="mt-4 rounded-md bg-gray-50 p-3 text-sm text-gray-700">
+            This browser or device can’t create passkeys. Keep using a strong, unique password, or open this page on
+            a device that supports passkeys to add one.
+          </p>
+        )}
+
+        <div className="mt-6">
+          {loadError ? (
+            <p role="alert" className="text-sm text-red-700">
+              {loadError}
+            </p>
+          ) : !list ? (
+            <p className="text-sm text-gray-500">Loading passkeys…</p>
+          ) : list.credentials.length === 0 ? (
+            <p className="rounded-md border border-dashed border-gray-300 p-6 text-center text-sm text-gray-600">
+              No passkeys yet. Create one to sign in faster and more securely.
+            </p>
+          ) : (
+            <ul className="divide-y divide-gray-200 rounded-md border border-gray-200">
+              {list.credentials.map((passkey) => (
+                <PasskeyRow
+                  key={passkey.id}
+                  passkey={passkey}
+                  onRename={handleRename}
+                  onDelete={() => setPendingDelete(passkey)}
+                />
+              ))}
+            </ul>
+          )}
+        </div>
+      </section>
+
+      {pendingDelete && (
+        <ConfirmDeleteDialog
+          passkey={pendingDelete}
+          isLast={list?.credentials.length === 1}
+          onClose={(confirmed) => {
+            const passkey = pendingDelete;
+            setPendingDelete(null);
+            if (confirmed) handleDelete(passkey);
+          }}
+        />
+      )}
+
+      {reauthDialog}
+    </div>
+  );
+}
+
+// ------------------------------------------------------------------ profile
+
+function ProfileSection({
+  username,
+  initialDisplayName,
+  onSave,
+}: {
+  username: string;
+  initialDisplayName: string;
+  onSave: (displayName: string) => Promise<boolean>;
+}) {
+  const [saved, setSaved] = useState(initialDisplayName);
+  const [value, setValue] = useState(initialDisplayName);
+  const [busy, setBusy] = useState(false);
+  const inputId = useId();
+  const hintId = useId();
+
+  const submit = async (e: React.FormEvent) => {
+    e.preventDefault();
+    setBusy(true);
+    const trimmed = value.trim();
+    if (await onSave(trimmed)) {
+      setSaved(trimmed);
+      setValue(trimmed);
+    }
+    setBusy(false);
+  };
+
+  return (
+    <section aria-labelledby="profile-heading" className="rounded-lg border border-gray-200 p-6">
+      <h2 id="profile-heading" className="text-xl font-semibold text-gray-900">
+        Profile
+      </h2>
+      <dl className="mt-4 text-sm">
+        <dt className="font-medium text-gray-700">Username</dt>
+        <dd className="mt-1 text-gray-900">{username}</dd>
+      </dl>
+      <form onSubmit={submit} className="mt-4 space-y-2">
+        <label htmlFor={inputId} className="block text-sm font-medium text-gray-700">
+          Display name
+        </label>
+        <div className="flex flex-wrap gap-2">
+          <input
+            id={inputId}
+            name="displayName"
+            autoComplete="name"
+            required
+            maxLength={64}
+            aria-describedby={hintId}
+            value={value}
+            onChange={(e) => setValue(e.target.value)}
+            className="min-w-0 flex-1 rounded-md border border-gray-300 px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
+          />
+          <button
+            type="submit"
+            disabled={busy || value.trim() === saved || !value.trim()}
+            className="rounded-md bg-gray-900 px-4 py-2 text-sm font-medium text-white hover:bg-gray-800 disabled:cursor-not-allowed disabled:opacity-50"
+          >
+            {busy ? 'Saving…' : 'Save'}
+          </button>
+        </div>
+        <p id={hintId} className="text-xs text-gray-500">
+          Shown when your browser or password manager lists your passkeys.
+        </p>
+      </form>
+    </section>
+  );
+}
+
+// ------------------------------------------------------------- passkey row
+
+function PasskeyRow({
+  passkey,
+  onRename,
+  onDelete,
+}: {
+  passkey: PasskeySummary;
+  onRename: (passkey: PasskeySummary, name: string) => Promise<boolean>;
+  onDelete: () => void;
+}) {
+  const [editing, setEditing] = useState(false);
+  const [name, setName] = useState(passkey.name);
+  const [busy, setBusy] = useState(false);
+  const inputId = useId();
+
+  const submit = async (e: React.FormEvent) => {
+    e.preventDefault();
+    setBusy(true);
+    if (await onRename(passkey, name.trim())) setEditing(false);
+    setBusy(false);
+  };
+
+  return (
+    <li className="flex flex-wrap items-center gap-4 p-4">
+      {passkey.providerIcon ? (
+        <img src={passkey.providerIcon} alt="" width={32} height={32} className="size-8 shrink-0" />
+      ) : (
+        <svg aria-hidden="true" viewBox="0 0 24 24" className="size-8 shrink-0 text-gray-500" fill="none" stroke="currentColor" strokeWidth="1.5">
+          <circle cx="9" cy="7" r="4" />
+          <path d="M2 21v-1a6 6 0 0 1 9.5-4.9" strokeLinecap="round" />
+          <circle cx="17.5" cy="13.5" r="2.5" />
+          <path d="M17.5 16v5m0-2h2" strokeLinecap="round" />
+        </svg>
+      )}
+
+      <div className="min-w-0 flex-1">
+        {editing ? (
+          <form onSubmit={submit} className="flex flex-wrap items-center gap-2">
+            <label htmlFor={inputId} className="sr-only">
+              Passkey name
+            </label>
+            <input
+              id={inputId}
+              autoFocus
+              required
+              maxLength={64}
+              value={name}
+              onChange={(e) => setName(e.target.value)}
+              onKeyDown={(e) => {
+                if (e.key === 'Escape') {
+                  setName(passkey.name);
+                  setEditing(false);
+                }
+              }}
+              className="min-w-0 flex-1 rounded-md border border-gray-300 px-2 py-1 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
+            />
+            <button type="submit" disabled={busy} className="text-sm font-medium text-gray-900 underline">
+              Save
+            </button>
+            <button
+              type="button"
+              onClick={() => {
+                setName(passkey.name);
+                setEditing(false);
+              }}
+              className="text-sm text-gray-600"
+            >
+              Cancel
+            </button>
+          </form>
+        ) : (
+          <p className="truncate font-medium text-gray-900">{passkey.name}</p>
+        )}
+        <p className="mt-1 text-xs text-gray-600">
+          Created {dateFormat.format(passkey.registeredAt)}
+          {' · '}
+          {passkey.lastUsedAt ? `Last used ${dateFormat.format(passkey.lastUsedAt)}` : 'Never used to sign in'}
+        </p>
+        <p className="mt-1 text-xs text-gray-500">
+          {passkey.credentialBackedUp ? 'Synced across your devices' : 'Stored on a single device'}
+        </p>
+      </div>
+
+      {!editing && (
+        <div className="flex gap-3">
+          <button
+            type="button"
+            onClick={() => setEditing(true)}
+            aria-label={`Rename ${passkey.name}`}
+            className="text-sm font-medium text-gray-700 hover:text-gray-900"
+          >
+            Rename
+          </button>
+          <button
+            type="button"
+            onClick={onDelete}
+            aria-label={`Remove ${passkey.name}`}
+            className="text-sm font-medium text-red-700 hover:text-red-900"
+          >
+            Remove
+          </button>
+        </div>
+      )}
+    </li>
+  );
+}
+
+// ---------------------------------------------------------- confirm delete
+
+function ConfirmDeleteDialog({
+  passkey,
+  isLast,
+  onClose,
+}: {
+  passkey: PasskeySummary;
+  isLast: boolean;
+  onClose: (confirmed: boolean) => void;
+}) {
+  const ref = useRef<HTMLDialogElement>(null);
+  const titleId = useId();
+  const descId = useId();
+  const onCloseRef = useRef(onClose);
+  onCloseRef.current = onClose;
+
+  useEffect(() => {
+    const dialog = ref.current!;
+    dialog.showModal();
+    const handleClose = () => {
+      // Esc / close requests leave returnValue empty, which counts as "cancel".
+      const confirmed = dialog.returnValue === 'remove';
+      dialog.returnValue = '';
+      onCloseRef.current(confirmed);
+    };
+    dialog.addEventListener('close', handleClose);
+    return () => dialog.removeEventListener('close', handleClose);
+  }, []);
+
+  return (
+    <dialog
+      ref={ref}
+      aria-labelledby={titleId}
+      aria-describedby={descId}
+      className="m-auto w-[min(28rem,calc(100%-2rem))] rounded-lg border border-gray-200 bg-white p-6 shadow-xl"
+    >
+      <h2 id={titleId} className="text-xl font-bold text-gray-900">
+        Remove “{passkey.name}”?
+      </h2>
+      <p id={descId} className="mt-2 text-sm text-gray-600">
+        You won’t be able to sign in to The DevTools Times with this passkey anymore.
+        {isLast && ' It’s your only passkey, so you’ll need your password to sign in.'}
+      </p>
+      <form method="dialog" className="mt-6 flex justify-end gap-3">
+        <button value="cancel" autoFocus className="rounded-md border border-gray-300 px-4 py-2 text-sm font-medium text-gray-700 hover:bg-gray-50">
+          Cancel
+        </button>
+        <button value="remove" className="rounded-md bg-red-700 px-4 py-2 text-sm font-medium text-white hover:bg-red-800">
+          Remove passkey
+        </button>
+      </form>
+    </dialog>
+  );
+}
