@@ -0,0 +1,94 @@
+import React, { useState } from 'react';
+import { registerPasskey } from '../lib/passkeys-client';
+
+interface PasskeyPromotionProps {
+  heading: string;
+  /** Where to go after the passkey is created or the user skips. */
+  continueHref: string;
+}
+
+/** Post sign-up / sign-in prompt to create a platform passkey. */
+export default function PasskeyPromotion({ heading, continueHref }: PasskeyPromotionProps) {
+  const [busy, setBusy] = useState(false);
+  const [error, setError] = useState<string | null>(null);
+  const [created, setCreated] = useState(false);
+
+  const create = async () => {
+    setError(null);
+    setBusy(true);
+    const result = await registerPasskey({ promotion: true });
+    setBusy(false);
+    switch (result.status) {
+      case 'created':
+      case 'exists':
+        setCreated(true);
+        break;
+      case 'reauth-required':
+        setError('For your security, please sign in again to add a passkey.');
+        break;
+      case 'error':
+        setError(result.message);
+        break;
+      // 'cancelled': leave the prompt as-is so the user can retry or skip.
+    }
+  };
+
+  if (created) {
+    return (
+      <section aria-labelledby="passkey-promo-done" className="space-y-4 text-center">
+        <h3 id="passkey-promo-done" className="text-lg font-semibold text-gray-900">
+          Passkey saved
+        </h3>
+        <p className="text-sm text-gray-600">
+          Next time, sign in with your fingerprint, face, or screen lock — no password needed.
+        </p>
+        <a
+          href={continueHref}
+          className="inline-block w-full rounded-md bg-gray-900 px-4 py-2 text-sm font-medium text-white hover:bg-gray-800"
+        >
+          Continue
+        </a>
+      </section>
+    );
+  }
+
+  return (
+    <section aria-labelledby="passkey-promo-title" className="space-y-4">
+      <div className="flex items-start gap-3">
+        <svg aria-hidden="true" viewBox="0 0 24 24" className="mt-0.5 size-8 shrink-0 text-gray-900" fill="none" stroke="currentColor" strokeWidth="1.5">
+          <circle cx="9" cy="7" r="4" />
+          <path d="M2 21v-1a6 6 0 0 1 9.5-4.9" strokeLinecap="round" />
+          <circle cx="17.5" cy="13.5" r="2.5" />
+          <path d="M17.5 16v5m0-2h2" strokeLinecap="round" />
+        </svg>
+        <div>
+          <h3 id="passkey-promo-title" className="text-lg font-semibold text-gray-900">
+            {heading}
+          </h3>
+          <p className="mt-1 text-sm text-gray-600">
+            Passkeys let you sign in with your fingerprint, face, or screen lock. They’re faster than passwords and
+            can’t be phished.
+          </p>
+        </div>
+      </div>
+
+      {error && (
+        <div className="rounded-lg bg-red-100 p-3 text-sm text-red-700" role="alert">
+          {error}
+        </div>
+      )}
+
+      <button
+        type="button"
+        onClick={create}
+        disabled={busy}
+        className="w-full rounded-md bg-gray-900 px-4 py-2 text-sm font-medium text-white hover:bg-gray-800 disabled:cursor-not-allowed disabled:opacity-75"
+      >
+        {busy ? 'Creating passkey…' : 'Create a passkey'}
+      </button>
+      <a href={continueHref} className="block text-center text-sm text-gray-700 underline hover:text-gray-900">
+        Not now
+      </a>
+    </section>
+  );
+}
diff --git a/src/components/ReauthDialog.tsx b/src/components/ReauthDialog.tsx
new file mode 100644
index 0000000..487f787
--- /dev/null
+++ b/src/components/ReauthDialog.tsx
@@ -0,0 +1,183 @@
+import React, { useCallback, useEffect, useId, useRef, useState } from 'react';
+import { reauthenticateWithPassword, reauthenticateWithPasskey } from '../lib/passkeys-client';
+
+interface ReauthDialogProps {
+  username: string;
+  hasPasskeys: boolean;
+  reason: string;
+  onDone: (verified: boolean) => void;
+}
+
+/** Modal "Confirm it's you" step shown before sensitive account changes. */
+function ReauthDialog({ username, hasPasskeys, reason, onDone }: ReauthDialogProps) {
+  const dialogRef = useRef<HTMLDialogElement>(null);
+  const verifiedRef = useRef(false);
+  const abortRef = useRef<AbortController | null>(null);
+  const [usePassword, setUsePassword] = useState(!hasPasskeys);
+  const [password, setPassword] = useState('');
+  const [busy, setBusy] = useState(false);
+  const [error, setError] = useState<string | null>(null);
+  const titleId = useId();
+  const descId = useId();
+  const passwordId = useId();
+
+  useEffect(() => {
+    const dialog = dialogRef.current!;
+    dialog.showModal();
+    const handleClose = () => {
+      abortRef.current?.abort();
+      onDone(verifiedRef.current);
+    };
+    dialog.addEventListener('close', handleClose);
+    return () => dialog.removeEventListener('close', handleClose);
+  }, [onDone]);
+
+  const finish = () => {
+    verifiedRef.current = true;
+    dialogRef.current?.close();
+  };
+
+  const verifyWithPasskey = async () => {
+    setError(null);
+    setBusy(true);
+    abortRef.current = new AbortController();
+    const result = await reauthenticateWithPasskey(abortRef.current.signal);
+    setBusy(false);
+    if (result.status === 'verified') finish();
+    else if (result.status === 'no-passkeys') setUsePassword(true);
+    else if (result.status === 'error') setError(result.message);
+  };
+
+  const verifyWithPassword = async (e: React.FormEvent) => {
+    e.preventDefault();
+    setError(null);
+    setBusy(true);
+    const result = await reauthenticateWithPassword(password);
+    setBusy(false);
+    if (result.status === 'verified') finish();
+    else if (result.status === 'error') setError(result.message);
+  };
+
+  return (
+    <dialog
+      ref={dialogRef}
+      aria-labelledby={titleId}
+      aria-describedby={descId}
+      className="m-auto w-[min(28rem,calc(100%-2rem))] rounded-lg border border-gray-200 bg-white p-6 shadow-xl"
+    >
+      <h2 id={titleId} className="text-xl font-bold text-gray-900">
+        Confirm it’s you
+      </h2>
+      <p id={descId} className="mt-2 text-sm text-gray-600">
+        {reason}
+      </p>
+
+      {error && (
+        <div className="mt-4 rounded-lg bg-red-100 p-3 text-sm text-red-700" role="alert">
+          {error}
+        </div>
+      )}
+
+      {!usePassword ? (
+        <div className="mt-6 space-y-3">
+          <button
+            type="button"
+            autoFocus
+            disabled={busy}
+            onClick={verifyWithPasskey}
+            className="w-full rounded-md bg-gray-900 px-4 py-2 text-sm font-medium text-white hover:bg-gray-800 disabled:cursor-not-allowed disabled:opacity-75"
+          >
+            {busy ? 'Waiting for passkey…' : 'Verify with passkey'}
+          </button>
+          <button
+            type="button"
+            onClick={() => {
+              abortRef.current?.abort();
+              setError(null);
+              setUsePassword(true);
+            }}
+            className="w-full text-sm text-gray-700 underline hover:text-gray-900"
+          >
+            Use your password instead
+          </button>
+        </div>
+      ) : (
+        <form onSubmit={verifyWithPassword} className="mt-6 space-y-4">
+          {/* Lets password managers match the saved credential for this account. */}
+          <input type="text" name="username" autoComplete="username" value={username} readOnly hidden />
+          <div>
+            <label htmlFor={passwordId} className="mb-1 block text-sm font-medium text-gray-700">
+              Password
+            </label>
+            <input
+              id={passwordId}
+              type="password"
+              name="password"
+              autoComplete="current-password"
+              autoFocus
+              required
+              value={password}
+              onChange={(e) => setPassword(e.target.value)}
+              className="w-full rounded-md border border-gray-300 px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
+            />
+          </div>
+          <button
+            type="submit"
+            disabled={busy}
+            className="w-full rounded-md bg-gray-900 px-4 py-2 text-sm font-medium text-white hover:bg-gray-800 disabled:cursor-not-allowed disabled:opacity-75"
+          >
+            {busy ? 'Verifying…' : 'Continue'}
+          </button>
+          {hasPasskeys && (
+            <button
+              type="button"
+              onClick={() => {
+                setError(null);
+                setUsePassword(false);
+              }}
+              className="w-full text-sm text-gray-700 underline hover:text-gray-900"
+            >
+              Use a passkey instead
+            </button>
+          )}
+        </form>
+      )}
+
+      <div className="mt-4 text-right">
+        <button
+          type="button"
+          onClick={() => dialogRef.current?.close()}
+          className="text-sm font-medium text-gray-600 hover:text-gray-900"
+        >
+          Cancel
+        </button>
+      </div>
+    </dialog>
+  );
+}
+
+/**
+ * Hook exposing `requestReauth(reason)`, which opens the dialog and resolves to
+ * true once the user has re-verified (or false if they cancelled).
+ */
+export function useReauth(username: string, hasPasskeys: boolean) {
+  const [pending, setPending] = useState<{ reason: string; resolve: (ok: boolean) => void } | null>(null);
+  const pendingRef = useRef(pending);
+  pendingRef.current = pending;
+
+  const requestReauth = useCallback(
+    (reason: string) => new Promise<boolean>((resolve) => setPending({ reason, resolve })),
+    [],
+  );
+
+  const handleDone = useCallback((verified: boolean) => {
+    pendingRef.current?.resolve(verified);
+    setPending(null);
+  }, []);
+
+  const dialog = pending ? (
+    <ReauthDialog username={username} hasPasskeys={hasPasskeys} reason={pending.reason} onDone={handleDone} />
+  ) : null;
+
+  return { requestReauth, reauthDialog: dialog };
+}
