+++ b/src/lib/auth/aaguid.ts
@@ -0,0 +1,64 @@
+/**
+ * Maps an authenticator AAGUID to a passkey provider name and icon.
+ *
+ * AAGUIDs are used for UX hints only (labelling passkeys in the management
+ * list) and never for security decisions – they are not attested for platform
+ * passkeys and can be spoofed.
+ */
+
+const REGISTRY_URL =
+  'https://raw.githubusercontent.com/passkeydeveloper/passkey-authenticator-aaguids/refs/heads/main/combined_aaguid.json';
+
+const ZERO_AAGUID = '00000000-0000-0000-0000-000000000000';
+
+interface RegistryEntry {
+  name: string;
+  icon_light?: string;
+  icon_dark?: string;
+}
+
+let registry: Promise<Record<string, RegistryEntry>> | null = null;
+
+function loadRegistry() {
+  registry ??= fetch(REGISTRY_URL, { signal: AbortSignal.timeout(5000) })
+    .then((r) => (r.ok ? r.json() : Promise.reject(new Error(`HTTP ${r.status}`))))
+    .catch((err) => {
+      console.warn('AAGUID registry unavailable:', err);
+      registry = null; // Retry on the next registration
+      return {};
+    });
+  return registry;
+}
+
+export interface ProviderInfo {
+  name: string;
+  icon?: string;
+  iconDark?: string;
+}
+
+export async function lookupProvider(aaguid: string, userAgent?: string | null): Promise<ProviderInfo> {
+  if (!aaguid || aaguid === ZERO_AAGUID) {
+    return { name: deviceNameFromUserAgent(userAgent) ?? 'Passkey' };
+  }
+  const entry = (await loadRegistry())[aaguid];
+  if (!entry) return { name: 'Passkey' };
+  return { name: entry.name, icon: entry.icon_light, iconDark: entry.icon_dark };
+}
+
+function deviceNameFromUserAgent(ua?: string | null): string | null {
+  if (!ua) return null;
+  const os = /Android/.test(ua)
+    ? 'Android'
+    : /iPhone|iPad/.test(ua)
+      ? 'iOS'
+      : /Mac OS X/.test(ua)
+        ? 'macOS'
+        : /Windows/.test(ua)
+          ? 'Windows'
+          : /CrOS/.test(ua)
+            ? 'ChromeOS'
+            : /Linux/.test(ua)
+              ? 'Linux'
+              : null;
+  return os ? `Passkey on ${os}` : null;
+}
