+import { ACCOUNT_API } from './config';
+
+/** Forwards a username/password request to the external account service. */
+export async function callAccountService(endpoint: 'login' | 'register', username: string, password: string) {
+  const response = await fetch(`${ACCOUNT_API}/${endpoint}`, {
+    method: 'POST',
+    headers: { 'Content-Type': 'application/json' },
+    body: JSON.stringify({ username, password }),
+  });
+  const data = await response.json().catch(() => ({}));
+  return { ok: response.ok, status: response.status, data: data as Record<string, unknown> };
+}
