index 0000000..3871aad
--- /dev/null
+++ b/src/lib/auth/config.ts
@@ -0,0 +1,37 @@
+/**
+ * Relying Party configuration for WebAuthn / passkeys.
+ *
+ * The RP ID is a predefined server-side value. Set `WEBAUTHN_RP_ID` (e.g.
+ * `astro-news-pytrpecapa-uc.a.run.app`) and `WEBAUTHN_ORIGINS` (comma-separated
+ * list of allowed origins) in production. When unset, the values fall back to
+ * the host the request was served from, which keeps local development on
+ * `http://localhost` working out of the box.
+ *
+ * The client never derives the RP ID itself – it always reads it from the
+ * options/responses returned by these endpoints.
+ */
+export const RP_NAME = 'The DevTools Times';
+
+/** External account service that owns usernames and passwords. */
+export const ACCOUNT_API = 'https://us-central1-web-devrel-apps.cloudfunctions.net/times_cdn/api';
+
+/** How long a sign-in or reauthentication counts as "recent" for sensitive actions. */
+export const RECENT_AUTH_WINDOW_MS = 5 * 60 * 1000;
+
+/** How long a WebAuthn challenge remains valid. */
+export const CHALLENGE_TTL_MS = 5 * 60 * 1000;
+
+export interface RelyingParty {
+  rpID: string;
+  rpName: string;
+  origins: string[];
+}
+
+export function getRelyingParty(request: Request): RelyingParty {
+  const url = new URL(request.url);
+  const rpID = process.env.WEBAUTHN_RP_ID?.trim() || url.hostname;
+  const origins = process.env.WEBAUTHN_ORIGINS
+    ? process.env.WEBAUTHN_ORIGINS.split(',').map((o) => o.trim()).filter(Boolean)
+    : [url.origin];
+  return { rpID, rpName: RP_NAME, origins };
+}
diff --git a/src/lib/auth/session.ts b/src/lib/auth/session.ts
new file mode 100644
index 0000000..5441e67
--- /dev/null
+++ b/src/lib/auth/session.ts
@@ -0,0 +1,92 @@
+import { CHALLENGE_TTL_MS, RECENT_AUTH_WINDOW_MS } from './config';
+import { findUserByUsername, type StoredPasskeyCredential, type StoredUser } from './store';
+
+type Session = NonNullable<import('astro').APIContext['session']>;
+
+export interface AuthState {
+  username: string;
+  /** Epoch ms of the last full sign-in or successful reauthentication. */
+  verifiedAt: number;
+  /** How the user last signed in. Conditional create is only offered after password sign-ins. */
+  method: 'password' | 'passkey' | 'signup';
+}
+
+export type ChallengePurpose = 'register' | 'authenticate' | 'reauthenticate';
+
+export interface PendingChallenge {
+  challenge: string;
+  purpose: ChallengePurpose;
+  userVerification: 'preferred' | 'required';
+  /** Set for conditional-create registrations, which may omit user presence. */
+  conditional?: boolean;
+  expiresAt: number;
+}
+
+export function json(body: unknown, status = 200) {
+  return new Response(JSON.stringify(body), {
+    status,
+    headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' },
+  });
+}
+
+export async function getAuth(session: Session | undefined): Promise<AuthState | null> {
+  return ((await session?.get('auth')) as AuthState | undefined) ?? null;
+}
+
+export async function getCurrentUser(session: Session | undefined): Promise<StoredUser | null> {
+  const auth = await getAuth(session);
+  return auth ? findUserByUsername(auth.username) : null;
+}
+
+/** Starts a fresh session (new ID, preventing fixation) for a verified user. */
+export async function signIn(session: Session | undefined, username: string, method: AuthState['method']) {
+  if (!session) throw new Error('Sessions are not configured');
+  const readingList = await session.get('readingList');
+  await session.regenerate();
+  session.set('readingList', readingList ?? []);
+  session.set('auth', { username, verifiedAt: Date.now(), method } satisfies AuthState);
+}
+
+export async function markReauthenticated(session: Session) {
+  const auth = await getAuth(session);
+  if (auth) session.set('auth', { ...auth, verifiedAt: Date.now() });
+}
+
+export async function hasRecentAuth(session: Session | undefined) {
+  const auth = await getAuth(session);
+  return !!auth && Date.now() - auth.verifiedAt < RECENT_AUTH_WINDOW_MS;
+}
+
+/** Response the client uses to trigger the reauthentication dialog and retry. */
+export const reauthRequired = () =>
+  json({ error: 'Please confirm it’s you to continue.', code: 'REAUTH_REQUIRED' }, 401);
+
+export const unauthenticated = () => json({ error: 'You need to be signed in.', code: 'UNAUTHENTICATED' }, 401);
+
+export function storeChallenge(session: Session, pending: Omit<PendingChallenge, 'expiresAt'>) {
+  session.set('webauthnChallenge', { ...pending, expiresAt: Date.now() + CHALLENGE_TTL_MS });
+}
+
+/** Reads and invalidates the pending challenge so it can only be used once. */
+export async function consumeChallenge(session: Session, purpose: ChallengePurpose) {
+  const pending = (await session.get('webauthnChallenge')) as PendingChallenge | undefined;
+  session.delete('webauthnChallenge');
+  if (!pending || pending.purpose !== purpose || pending.expiresAt < Date.now()) return null;
+  return pending;
+}
+
+/** Credential shape returned to the browser (no public key / counter). */
+export function toPublicCredential(c: StoredPasskeyCredential) {
+  return {
+    id: c.id,
+    name: c.name,
+    aaguid: c.aaguid,
+    providerIcon: c.providerIcon,
+    providerIconDark: c.providerIconDark,
+    credentialDeviceType: c.credentialDeviceType,
+    credentialBackedUp: c.credentialBackedUp,
+    registeredAt: c.registeredAt,
+    lastUsedAt: c.lastUsedAt,
+  };
+}
+
diff --git a/src/lib/auth/store.ts b/src/lib/auth/store.ts
new file mode 100644
index 0000000..104abf6
--- /dev/null
+++ b/src/lib/auth/store.ts
@@ -0,0 +1,136 @@
+import { promises as fs } from 'node:fs';
+import path from 'node:path';
+import { randomBytes } from 'node:crypto';
+
+/**
+ * Minimal file-backed persistence for accounts and passkeys.
+ *
+ * Usernames/passwords live in the external account service; this store keeps
+ * the passkey-specific data that service doesn't know about. Point
+ * `AUTH_DB_PATH` at a persistent volume in production.
+ */
+
+export interface StoredUser {
+  username: string; // Matches the username in the external account service
+  displayName: string;
+  passkeyUserId: string; // Unpadded Base64URL WebAuthn user handle
+  createdAt: number;
+}
+
+export interface StoredPasskeyCredential {
+  id: string; // Base64URL-encoded credential ID
+  passkeyUserId: string;
+  credentialPublicKey: string; // Base64URL-encoded COSE public key
+  credentialType: 'public-key';
+  credentialDeviceType: 'singleDevice' | 'multiDevice';
+  credentialBackedUp: boolean;
+  aaguid: string;
+  providerIcon?: string;
+  providerIconDark?: string;
+  name: string;
+  transports: string[];
+  lastUsedAt?: number;
+  registeredAt: number;
+  counter: number;
+}
+
+interface Database {
+  users: StoredUser[];
+  credentials: StoredPasskeyCredential[];
+}
+
+const DB_PATH = path.resolve(process.env.AUTH_DB_PATH || '.data/auth-db.json');
+
+let cache: Database | null = null;
+let writeQueue: Promise<void> = Promise.resolve();
+
+async function load(): Promise<Database> {
+  if (cache) return cache;
+  try {
+    cache = JSON.parse(await fs.readFile(DB_PATH, 'utf8')) as Database;
+  } catch {
+    cache = { users: [], credentials: [] };
+  }
+  cache.users ??= [];
+  cache.credentials ??= [];
+  return cache;
+}
+
+function persist(db: Database): Promise<void> {
+  writeQueue = writeQueue
+    .catch(() => {})
+    .then(async () => {
+      await fs.mkdir(path.dirname(DB_PATH), { recursive: true });
+      const tmp = `${DB_PATH}.${process.pid}.tmp`;
+      await fs.writeFile(tmp, JSON.stringify(db, null, 2));
+      await fs.rename(tmp, DB_PATH);
+    });
+  return writeQueue;
+}
+
+// ---------------------------------------------------------------- users
+
+export async function findUserByUsername(username: string) {
+  const db = await load();
+  return db.users.find((u) => u.username === username) ?? null;
+}
+
+export async function findUserByPasskeyUserId(passkeyUserId: string) {
+  const db = await load();
+  return db.users.find((u) => u.passkeyUserId === passkeyUserId) ?? null;
+}
+
+/** Returns the local record for an externally-authenticated user, creating it on first sign-in. */
+export async function ensureUser(username: string): Promise<StoredUser> {
+  const db = await load();
+  let user = db.users.find((u) => u.username === username);
+  if (!user) {
+    user = {
+      username,
+      displayName: username,
+      passkeyUserId: randomBytes(32).toString('base64url'),
+      createdAt: Date.now(),
+    };
+    db.users.push(user);
+    await persist(db);
+  }
+  return user;
+}
+
+export async function updateUser(username: string, patch: Pick<StoredUser, 'displayName'>) {
+  const db = await load();
+  const user = db.users.find((u) => u.username === username);
+  if (!user) return null;
+  user.displayName = patch.displayName;
+  await persist(db);
+  return user;
+}
+
+// ---------------------------------------------------------- credentials
+
+export async function findCredentialsByUser(passkeyUserId: string) {
+  const db = await load();
+  return db.credentials
+    .filter((c) => c.passkeyUserId === passkeyUserId)
+    .sort((a, b) => a.registeredAt - b.registeredAt);
+}
+
+export async function findCredentialById(id: string) {
+  const db = await load();
+  return db.credentials.find((c) => c.id === id) ?? null;
+}
+
+export async function saveCredential(credential: StoredPasskeyCredential) {
+  const db = await load();
+  const index = db.credentials.findIndex((c) => c.id === credential.id);
+  if (index === -1) db.credentials.push(credential);
+  else db.credentials[index] = credential;
+  await persist(db);
+  return credential;
+}
+
+export async function deleteCredential(id: string) {
+  const db = await load();
+  db.credentials = db.credentials.filter((c) => c.id !== id);
+  await persist(db);
+}
diff --git a/src/lib/passkeys-client.ts b/src/lib/passkeys-client.ts
new file mode 100644
index 0000000..461b20b
--- /dev/null
+++ b/src/lib/passkeys-client.ts
@@ -0,0 +1,367 @@
+/**
+ * Browser-side passkey helpers built on the native WebAuthn APIs.
+ *
+ * The RP ID is always read from server responses (`publicKey.rp.id`,
+ * `publicKey.rpId`, or the `rpId` returned by the management endpoints),
+ * never from `window.location.hostname`.
+ */
+
+// The DOM lib in older TypeScript versions doesn't know these yet.
+type PKC = typeof PublicKeyCredential & {
+  getClientCapabilities?: () => Promise<Record<string, boolean>>;
+  parseCreationOptionsFromJSON: (json: unknown) => PublicKeyCredentialCreationOptions;
+  parseRequestOptionsFromJSON: (json: unknown) => PublicKeyCredentialRequestOptions;
+  signalUnknownCredential?: (o: { rpId: string; credentialId: string }) => Promise<void>;
+  signalAllAcceptedCredentials?: (o: { rpId: string; userId: string; allAcceptedCredentialIds: string[] }) => Promise<void>;
+  signalCurrentUserDetails?: (o: { rpId: string; userId: string; name: string; displayName: string }) => Promise<void>;
+};
+type JSONCredential = PublicKeyCredential & { toJSON(): { id: string } & Record<string, unknown> };
+
+export interface PasskeySummary {
+  id: string;
+  name: string;
+  aaguid: string;
+  providerIcon?: string;
+  providerIconDark?: string;
+  credentialDeviceType: 'singleDevice' | 'multiDevice';
+  credentialBackedUp: boolean;
+  registeredAt: number;
+  lastUsedAt?: number;
+}
+
+export const authUrl = (path: string) => `${import.meta.env.BASE_URL}api/auth/${path}`;
+
+export async function postJSON(path: string, body?: unknown, method = 'POST') {
+  return fetch(authUrl(path), {
+    method,
+    headers: { 'Content-Type': 'application/json' },
+    body: body === undefined ? undefined : JSON.stringify(body),
+  });
+}
+
+export async function readError(response: Response, fallback = 'Something went wrong. Please try again.') {
+  const data = await response.json().catch(() => ({}));
+  return (data?.error as string) || fallback;
+}
+
+// ------------------------------------------------------------ detection
+
+let ready: Promise<PKC | null> | null = null;
+
+/** Returns PublicKeyCredential with JSON/capability polyfills applied, or null if WebAuthn is unavailable. */
+export function loadWebAuthn(): Promise<PKC | null> {
+  if (typeof window === 'undefined' || !window.PublicKeyCredential) return Promise.resolve(null);
+  ready ??= import('webauthn-polyfills')
+    .catch((err) => console.warn('webauthn-polyfills failed to load:', err))
+    .then(() => window.PublicKeyCredential as PKC);
+  return ready;
+}
+
+export async function getCapabilities(): Promise<Record<string, boolean>> {
+  const PKC = await loadWebAuthn();
+  if (!PKC?.getClientCapabilities) return {};
+  try {
+    return await PKC.getClientCapabilities();
+  } catch {
+    return {};
+  }
+}
+
+// ---------------------------------------------------------- Signal API
+
+export function isValidBase64Url(value: unknown): value is string {
+  return typeof value === 'string' && value.length > 0 && value.length % 4 !== 1 && /^[A-Za-z0-9_-]+$/.test(value);
+}
+
+export async function signalUnknownCredential(rpId: string | undefined, credentialId: string) {
+  const PKC = await loadWebAuthn();
+  if (!PKC?.signalUnknownCredential || !rpId || !isValidBase64Url(credentialId)) return;
+  try {
+    await PKC.signalUnknownCredential({ rpId, credentialId });
+  } catch (e) {
+    console.warn('signalUnknownCredential sync warning:', e);
+  }
+}
+
+export async function signalAllAcceptedCredentials(rpId: string, userId: string, credentialIds: string[]) {
+  const PKC = await loadWebAuthn();
+  if (!PKC?.signalAllAcceptedCredentials) return;
+  if (!rpId || !isValidBase64Url(userId) || !credentialIds.every(isValidBase64Url)) {
+    console.warn('signalAllAcceptedCredentials skipped: invalid rpId, userId, or credential IDs.');
+    return;
+  }
+  try {
+    await PKC.signalAllAcceptedCredentials({ rpId, userId, allAcceptedCredentialIds: credentialIds });
+  } catch (e) {
+    console.warn('signalAllAcceptedCredentials sync warning:', e);
+  }
+}
+
+export async function signalCurrentUserDetails(details: { rpId: string; userId: string; name: string; displayName: string }) {
+  const PKC = await loadWebAuthn();
+  if (!PKC?.signalCurrentUserDetails) return;
+  if (!details.rpId || !isValidBase64Url(details.userId)) {
+    console.warn('signalCurrentUserDetails skipped: invalid rpId or userId.');
+    return;
+  }
+  try {
+    await PKC.signalCurrentUserDetails(details);
+  } catch (e) {
+    console.warn('signalCurrentUserDetails sync warning:', e);
+  }
+}
+
+// --------------------------------------------------------- registration
+
+export type RegisterResult =
+  | { status: 'created'; credential: PasskeySummary }
+  | { status: 'cancelled' }
+  | { status: 'exists' }
+  | { status: 'reauth-required' }
+  | { status: 'error'; message: string };
+
+/**
+ * Creates a passkey for the signed-in user.
+ * `promotion: true` restricts creation to the platform authenticator (post sign-up/sign-in prompts);
+ * otherwise security keys are allowed too (account settings).
+ */
+export async function registerPasskey({ promotion = false } = {}): Promise<RegisterResult> {
+  const PKC = await loadWebAuthn();
+  if (!PKC) return { status: 'error', message: 'Passkeys aren’t supported in this browser.' };
+
+  const optionsResponse = await postJSON('passkey/register-options', { promotion });
+  if (optionsResponse.status === 401) {
+    const data = await optionsResponse.json().catch(() => ({}));
+    if (data.code === 'REAUTH_REQUIRED') return { status: 'reauth-required' };
+    return { status: 'error', message: data.error ?? 'You need to be signed in.' };
+  }
+  if (!optionsResponse.ok) return { status: 'error', message: await readError(optionsResponse) };
+  const publicKey = PKC.parseCreationOptionsFromJSON(await optionsResponse.json());
+
+  let credential: JSONCredential;
+  try {
+    credential = (await navigator.credentials.create({ publicKey })) as JSONCredential;
+  } catch (err) {
+    const name = (err as DOMException).name;
+    if (name === 'InvalidStateError') return { status: 'exists' };
+    if (name === 'NotAllowedError' || name === 'AbortError') return { status: 'cancelled' };
+    if (name === 'SecurityError') {
+      console.error('Passkey RP ID or secure context misconfiguration:', err);
+      return { status: 'error', message: 'Passkeys can’t be created on this site right now.' };
+    }
+    return { status: 'error', message: 'The passkey couldn’t be created.' };
+  }
+
+  // Verification is kept separate from the WebAuthn call so only server/network failures signal the provider.
+  const encoded = credential.toJSON();
+  try {
+    const response = await postJSON('passkey/register-verify', encoded);
+    if (!response.ok) {
+      await signalUnknownCredential(publicKey.rp.id, encoded.id);
+      return { status: 'error', message: await readError(response, 'We couldn’t save your passkey.') };
+    }
+    const data = await response.json();
+    return { status: 'created', credential: data.credential };
+  } catch (err) {
+    console.error('Passkey verification request failed:', err);
+    await signalUnknownCredential(publicKey.rp.id, encoded.id);
+    return { status: 'error', message: 'We couldn’t save your passkey. Check your connection and try again.' };
+  }
+}
+
+/**
+ * Conditional create: lets the password manager silently add a passkey right after a
+ * successful password sign-in. Never shows UI or errors.
+ */
+export async function conditionalCreatePasskey(): Promise<boolean> {
+  const PKC = await loadWebAuthn();
+  if (!PKC) return false;
+  const capabilities = await getCapabilities();
+  if (capabilities.conditionalCreate !== true) return false;
+
+  try {
+    const optionsResponse = await postJSON('passkey/register-options', { conditional: true });
+    if (!optionsResponse.ok) return false;
+    const publicKey = PKC.parseCreationOptionsFromJSON(await optionsResponse.json());
+
+    let credential: JSONCredential;
+    try {
+      credential = (await navigator.credentials.create({
+        publicKey,
+        mediation: 'conditional',
+      } as CredentialCreationOptions)) as JSONCredential;
+    } catch (err) {
+      const name = (err as DOMException).name;
+      if (!['InvalidStateError', 'NotAllowedError', 'AbortError'].includes(name)) {
+        console.warn('Unexpected conditional create error:', err);
+      }
+      return false;
+    }
+
+    const encoded = credential.toJSON();
+    try {
+      const response = await postJSON('passkey/register-verify', encoded);
+      if (!response.ok) {
+        await signalUnknownCredential(publicKey.rp.id, encoded.id);
+        return false;
+      }
+      return true;
+    } catch {
+      await signalUnknownCredential(publicKey.rp.id, encoded.id);
+      return false;
+    }
+  } catch (err) {
+    console.warn('Conditional create skipped:', err);
+    return false;
+  }
+}
+
+// ------------------------------------------------------- authentication
+
+export type SignInResult =
+  | { status: 'signed-in'; username: string }
+  | { status: 'cancelled' }
+  | { status: 'error'; message: string };
+
+async function verifySignIn(credential: JSONCredential, rpId: string | undefined): Promise<SignInResult> {
+  const encoded = credential.toJSON();
+  try {
+    const response = await postJSON('passkey/login-verify', encoded);
+    if (response.ok) {
+      const data = await response.json();
+      return { status: 'signed-in', username: data.username };
+    }
+    if (response.status === 404) {
+      // The user is unauthenticated here, so it's safe to tell the provider to hide this passkey.
+      await signalUnknownCredential(rpId, encoded.id);
+      return {
+        status: 'error',
+        message: 'That passkey is no longer registered with The DevTools Times. Sign in with your password instead.',
+      };
+    }
+    return { status: 'error', message: await readError(response, 'We couldn’t verify your passkey.') };
+  } catch (err) {
+    console.error('Passkey verification request failed:', err);
+    return { status: 'error', message: 'We couldn’t reach the server. Check your connection and try again.' };
+  }
+}
+
+async function getLoginOptions(PKC: PKC) {
+  const response = await postJSON('passkey/login-options');
+  if (!response.ok) throw new Error(await readError(response));
+  return PKC.parseRequestOptionsFromJSON(await response.json());
+}
+
+/**
+ * Offers passkeys in the username field's autofill (conditional mediation).
+ * Resolves with null if unsupported, aborted, or dismissed.
+ */
+export async function conditionalSignIn(signal: AbortSignal): Promise<SignInResult | null> {
+  const PKC = await loadWebAuthn();
+  if (!PKC) return null;
+  const capabilities = await getCapabilities();
+  if (capabilities.conditionalGet !== true || signal.aborted) return null;
+
+  let publicKey: PublicKeyCredentialRequestOptions;
+  try {
+    publicKey = await getLoginOptions(PKC);
+  } catch (err) {
+    console.warn('Could not prepare passkey autofill:', err);
+    return null;
+  }
+
+  let credential: JSONCredential;
+  try {
+    credential = (await navigator.credentials.get({
+      publicKey,
+      signal,
+      mediation: 'conditional',
+    } as CredentialRequestOptions)) as JSONCredential;
+  } catch (err) {
+    const name = (err as DOMException).name;
+    if (name !== 'NotAllowedError' && name !== 'AbortError') console.warn('Unexpected conditional get error:', err);
+    return null;
+  }
+  if (!credential) return null;
+  return verifySignIn(credential, publicKey.rpId);
+}
+
+/** Explicit "Sign in with a passkey" button flow. */
+export async function signInWithPasskey(signal?: AbortSignal): Promise<SignInResult> {
+  const PKC = await loadWebAuthn();
+  if (!PKC) return { status: 'error', message: 'Passkeys aren’t supported in this browser.' };
+
+  let publicKey: PublicKeyCredentialRequestOptions;
+  try {
+    publicKey = await getLoginOptions(PKC);
+  } catch (err) {
+    return { status: 'error', message: (err as Error).message };
+  }
+
+  let credential: JSONCredential;
+  try {
+    credential = (await navigator.credentials.get({ publicKey, signal })) as JSONCredential;
+  } catch (err) {
+    const name = (err as DOMException).name;
+    if (name === 'NotAllowedError' || name === 'AbortError') return { status: 'cancelled' };
+    return { status: 'error', message: 'Passkey sign-in failed. Please try again.' };
+  }
+  if (!credential) return { status: 'cancelled' };
+  return verifySignIn(credential, publicKey.rpId);
+}
+
+// ------------------------------------------------------ reauthentication
+
+export type ReauthResult =
+  | { status: 'verified' }
+  | { status: 'cancelled' }
+  | { status: 'no-passkeys' }
+  | { status: 'error'; message: string };
+
+/** Step-up verification limited to the signed-in user's own passkeys. */
+export async function reauthenticateWithPasskey(signal?: AbortSignal): Promise<ReauthResult> {
+  const PKC = await loadWebAuthn();
+  if (!PKC) return { status: 'error', message: 'Passkeys aren’t supported in this browser.' };
+
+  const optionsResponse = await postJSON('reauth/options');
+  if (optionsResponse.status === 409) return { status: 'no-passkeys' };
+  if (!optionsResponse.ok) return { status: 'error', message: await readError(optionsResponse) };
+  const publicKey = PKC.parseRequestOptionsFromJSON(await optionsResponse.json());
+
+  let credential: JSONCredential;
+  try {
+    credential = (await navigator.credentials.get({ publicKey, signal })) as JSONCredential;
+  } catch (err) {
+    const name = (err as DOMException).name;
+    if (name === 'NotAllowedError' || name === 'AbortError') return { status: 'cancelled' };
+    return { status: 'error', message: 'Passkey verification failed. Please try again.' };
+  }
+  if (!credential) return { status: 'cancelled' };
+
+  const encoded = credential.toJSON();
+  try {
+    const response = await postJSON('reauth/verify', encoded);
+    if (response.ok) return { status: 'verified' };
+    if (response.status === 404) await signalUnknownCredential(publicKey.rpId, encoded.id);
+    return { status: 'error', message: await readError(response, 'We couldn’t verify your passkey.') };
+  } catch {
+    return { status: 'error', message: 'We couldn’t reach the server. Check your connection and try again.' };
+  }
+}
+
+export async function reauthenticateWithPassword(password: string): Promise<ReauthResult> {
+  try {
+    const response = await postJSON('reauth/password', { password });
+    if (response.ok) return { status: 'verified' };
+    return { status: 'error', message: await readError(response, 'That password is incorrect.') };
+  } catch {
+    return { status: 'error', message: 'We couldn’t reach the server. Check your connection and try again.' };
+  }
+}
+
+/** True when a response asks the client to reauthenticate before retrying. */
+export async function isReauthRequired(response: Response) {
+  if (response.status !== 401) return false;
+  const data = await response.clone().json().catch(() => ({}));
+  return data?.code === 'REAUTH_REQUIRED';
+}
