+import type { APIRoute } from 'astro';
+import { generateAuthenticationOptions } from '@simplewebauthn/server';
+import { getRelyingParty } from '../../../../lib/auth/config';
+import { json, storeChallenge } from '../../../../lib/auth/session';
+
+/** Discoverable-credential sign-in options (empty allowCredentials). */
+export const POST: APIRoute = async ({ request, session }) => {
+  if (!session) return json({ error: 'Sessions are not configured.' }, 500);
+  const { rpID } = getRelyingParty(request);
+  const options = await generateAuthenticationOptions({
+    rpID,
+    allowCredentials: [],
+    userVerification: 'preferred',
+  });
+  // The expected UV level is kept server-side, never round-tripped through the client.
+  storeChallenge(session, { challenge: options.challenge, purpose: 'authenticate', userVerification: 'preferred' });
+  return json(options);
+};
