+import type { APIRoute } from 'astro';
+import { verifyAuthenticationResponse } from '@simplewebauthn/server';
+import { isoBase64URL } from '@simplewebauthn/server/helpers';
+import { getRelyingParty } from '../../../../lib/auth/config';
+import { consumeChallenge, json, signIn } from '../../../../lib/auth/session';
+import { findCredentialById, findUserByPasskeyUserId, saveCredential } from '../../../../lib/auth/store';
+
+export const POST: APIRoute = async ({ request, session }) => {
+  if (!session) return json({ error: 'Sessions are not configured.' }, 500);
+  const pending = await consumeChallenge(session, 'authenticate');
+  if (!pending) return json({ error: 'The sign-in request expired. Please try again.' }, 400);
+
+  const response = await request.json().catch(() => null);
+  if (!response?.id) return json({ error: 'Invalid passkey response.' }, 400);
+
+  const stored = await findCredentialById(response.id);
+  // 404 lets the client signal the password manager that this passkey no longer exists.
+  if (!stored) return json({ error: 'This passkey isn’t registered with The DevTools Times.' }, 404);
+  const user = await findUserByPasskeyUserId(stored.passkeyUserId);
+  if (!user) return json({ error: 'This passkey isn’t registered with The DevTools Times.' }, 404);
+
+  const { rpID, origins } = getRelyingParty(request);
+  let verification;
+  try {
+    verification = await verifyAuthenticationResponse({
+      response,
+      expectedChallenge: pending.challenge,
+      expectedOrigin: origins,
+      expectedRPID: rpID,
+      requireUserVerification: pending.userVerification === 'required',
+      credential: {
+        id: stored.id,
+        publicKey: isoBase64URL.toBuffer(stored.credentialPublicKey),
+        counter: stored.counter,
+        transports: stored.transports as any,
+      },
+    });
+  } catch (err) {
+    console.warn('Passkey sign-in verification failed:', err);
+    return json({ error: 'We couldn’t verify your passkey.' }, 400);
+  }
+  if (!verification.verified) return json({ error: 'We couldn’t verify your passkey.' }, 400);
+
+  await saveCredential({
+    ...stored,
+    counter: verification.authenticationInfo.newCounter,
+    credentialBackedUp: verification.authenticationInfo.credentialBackedUp,
+    lastUsedAt: Date.now(),
+  });
+  await signIn(session, user.username, 'passkey');
+  return json({ username: user.username, displayName: user.displayName });
+};
