+import type { APIRoute } from 'astro';
+import { generateRegistrationOptions } from '@simplewebauthn/server';
+import { isoBase64URL } from '@simplewebauthn/server/helpers';
+import { getRelyingParty } from '../../../../lib/auth/config';
+import {
+  getAuth,
+  getCurrentUser,
+  hasRecentAuth,
+  json,
+  reauthRequired,
+  storeChallenge,
+  unauthenticated,
+} from '../../../../lib/auth/session';
+import { findCredentialsByUser } from '../../../../lib/auth/store';
+
+/**
+ * Body: { promotion?: boolean, conditional?: boolean }
+ *  - promotion: offered right after sign-up/sign-in → restrict to the platform authenticator.
+ *  - conditional: automatic passkey creation after a password sign-in (conditional create).
+ *  - neither: created from account settings → security keys allowed too.
+ */
+export const POST: APIRoute = async ({ request, session }) => {
+  const user = await getCurrentUser(session);
+  if (!user || !session) return unauthenticated();
+  if (!(await hasRecentAuth(session))) return reauthRequired();
+
+  const { promotion = false, conditional = false } = await request.json().catch(() => ({}));
+  if (conditional && (await getAuth(session))?.method !== 'password') {
+    return json({ error: 'Automatic passkey creation is only available after a password sign-in.' }, 400);
+  }
+
+  const { rpID, rpName } = getRelyingParty(request);
+  const existing = await findCredentialsByUser(user.passkeyUserId);
+
+  const options = await generateRegistrationOptions({
+    rpName,
+    rpID,
+    userID: isoBase64URL.toBuffer(user.passkeyUserId),
+    userName: user.username,
+    userDisplayName: user.displayName,
+    attestationType: 'none',
+    excludeCredentials: existing.map((c) => ({ id: c.id, transports: c.transports })),
+    authenticatorSelection: {
+      residentKey: 'required',
+      requireResidentKey: true,
+      userVerification: 'preferred',
+      ...((promotion || conditional) && { authenticatorAttachment: 'platform' as const }),
+    },
+  });
+
+  storeChallenge(session, {
+    challenge: options.challenge,
+    purpose: 'register',
+    userVerification: 'preferred',
+    conditional: !!conditional,
+  });
+  return json(options);
+};
