+import type { APIRoute } from 'astro';
+import { verifyRegistrationResponse } from '@simplewebauthn/server';
+import { isoBase64URL } from '@simplewebauthn/server/helpers';
+import { lookupProvider } from '../../../../lib/auth/aaguid';
+import { getRelyingParty } from '../../../../lib/auth/config';
+import {
+  consumeChallenge,
+  getCurrentUser,
+  json,
+  toPublicCredential,
+  unauthenticated,
+} from '../../../../lib/auth/session';
+import { findCredentialById, saveCredential } from '../../../../lib/auth/store';
+
+export const POST: APIRoute = async ({ request, session }) => {
+  const user = await getCurrentUser(session);
+  if (!user || !session) return unauthenticated();
+
+  const pending = await consumeChallenge(session, 'register');
+  if (!pending) return json({ error: 'The passkey request expired. Please try again.' }, 400);
+
+  const response = await request.json().catch(() => null);
+  if (!response?.id) return json({ error: 'Invalid passkey response.' }, 400);
+
+  const { rpID, origins } = getRelyingParty(request);
+  let verification;
+  try {
+    verification = await verifyRegistrationResponse({
+      response,
+      expectedChallenge: pending.challenge,
+      expectedOrigin: origins,
+      expectedRPID: rpID,
+      // userVerification was "preferred", so authenticators without UV must still pass.
+      requireUserVerification: false,
+      // Conditional create may complete without a user-presence gesture; explicit creation may not.
+      requireUserPresence: !pending.conditional,
+    });
+  } catch (err) {
+    console.warn('Passkey registration verification failed:', err);
+    return json({ error: 'We couldn’t verify the new passkey.' }, 400);
+  }
+  if (!verification.verified) return json({ error: 'We couldn’t verify the new passkey.' }, 400);
+
+  const { credential, credentialDeviceType, credentialBackedUp, aaguid } = verification.registrationInfo;
+  if (await findCredentialById(credential.id)) {
+    return json({ error: 'This passkey is already registered.' }, 409);
+  }
+
+  const provider = await lookupProvider(aaguid, request.headers.get('user-agent'));
+  const saved = await saveCredential({
+    id: credential.id,
+    passkeyUserId: user.passkeyUserId,
+    credentialPublicKey: isoBase64URL.fromBuffer(credential.publicKey),
+    credentialType: 'public-key',
+    credentialDeviceType,
+    credentialBackedUp,
+    aaguid,
+    name: provider.name,
+    providerIcon: provider.icon,
+    providerIconDark: provider.iconDark,
+    transports: credential.transports ?? [],
+    registeredAt: Date.now(),
+    counter: credential.counter,
+  });
+
+  return json({ verified: true, credential: toPublicCredential(saved) });
+};
