@@ -0,0 +1,43 @@
+import type { APIRoute } from 'astro';
+import {
+  getCurrentUser,
+  hasRecentAuth,
+  json,
+  reauthRequired,
+  toPublicCredential,
+  unauthenticated,
+} from '../../../../lib/auth/session';
+import { deleteCredential, findCredentialById, saveCredential } from '../../../../lib/auth/store';
+
+async function ownedCredential(session: Parameters<typeof getCurrentUser>[0], id: string | undefined) {
+  const user = await getCurrentUser(session);
+  if (!user) return { error: unauthenticated() };
+  const credential = id ? await findCredentialById(id) : null;
+  if (!credential || credential.passkeyUserId !== user.passkeyUserId) {
+    return { error: json({ error: 'Passkey not found.' }, 404) };
+  }
+  return { credential };
+}
+
+/** Renames a passkey. This is a server-side label only (no Signal API call). */
+export const PUT: APIRoute = async ({ params, request, session }) => {
+  const { credential, error } = await ownedCredential(session, params.id);
+  if (error) return error;
+
+  const { name } = await request.json().catch(() => ({}));
+  const trimmed = typeof name === 'string' ? name.trim() : '';
+  if (!trimmed || trimmed.length > 64) return json({ error: 'Name must be 1–64 characters.' }, 400);
+
+  const saved = await saveCredential({ ...credential!, name: trimmed });
+  return json(toPublicCredential(saved));
+};
+
+/** Deletes a passkey. Sensitive: requires a recent sign-in or reauthentication. */
+export const DELETE: APIRoute = async ({ params, session }) => {
+  const { credential, error } = await ownedCredential(session, params.id);
+  if (error) return error;
+  if (!(await hasRecentAuth(session))) return reauthRequired();
+
+  await deleteCredential(credential!.id);
+  return json({ success: true });
+};
