+import type { APIRoute } from 'astro';
+import { generateAuthenticationOptions } from '@simplewebauthn/server';
+import { getRelyingParty } from '../../../../lib/auth/config';
+import { getCurrentUser, json, storeChallenge, unauthenticated } from '../../../../lib/auth/session';
+import { findCredentialsByUser } from '../../../../lib/auth/store';
+
+/** Step-up options restricted to the signed-in user's own passkeys. */
+export const POST: APIRoute = async ({ request, session }) => {
+  const user = await getCurrentUser(session);
+  if (!user || !session) return unauthenticated();
+
+  const passkeys = await findCredentialsByUser(user.passkeyUserId);
+  if (passkeys.length === 0) {
+    return json({ error: 'No passkeys are registered for this account.', code: 'NO_PASSKEYS' }, 409);
+  }
+
+  const { rpID } = getRelyingParty(request);
+  const options = await generateAuthenticationOptions({
+    rpID,
+    // Never empty here: an empty list would fall back to discoverable credentials of any account.
+    allowCredentials: passkeys.map((c) => ({ id: c.id, transports: c.transports })),
+    userVerification: 'preferred',
+  });
+  storeChallenge(session, { challenge: options.challenge, purpose: 'reauthenticate', userVerification: 'preferred' });
+  return json(options);
+};
