+import type { APIRoute } from 'astro';
+import { callAccountService } from '../../../../lib/auth/account-service';
+import { getCurrentUser, json, markReauthenticated, unauthenticated } from '../../../../lib/auth/session';
+
+/** Password fallback for reauthentication, e.g. for accounts without passkeys. */
+export const POST: APIRoute = async ({ request, session }) => {
+  const user = await getCurrentUser(session);
+  if (!user || !session) return unauthenticated();
+
+  const { password } = await request.json().catch(() => ({}));
+  if (typeof password !== 'string' || !password) return json({ error: 'Password is required.' }, 400);
+
+  try {
+    const result = await callAccountService('login', user.username, password);
+    if (!result.ok) return json({ error: 'That password is incorrect.' }, 401);
+  } catch {
+    return json({ error: 'The account service is unavailable. Please try again later.' }, 502);
+  }
+  await markReauthenticated(session);
+  return json({ verified: true });
+};
