+import type { APIRoute } from 'astro';
+import { json, signIn } from '../../../lib/auth/session';
+import { ensureUser } from '../../../lib/auth/store';
+import { callAccountService } from '../../../lib/auth/account-service';
+
+/** Account creation, proxied to the account service; signs the new user in so they can add a passkey. */
+export const POST: APIRoute = async ({ request, session }) => {
+  const { username, password } = await request.json().catch(() => ({}));
+  if (typeof username !== 'string' || typeof password !== 'string' || !username || !password) {
+    return json({ error: 'Username and password are required.' }, 400);
+  }
+  try {
+    const result = await callAccountService('register', username, password);
+    if (!result.ok) return json({ error: result.data.error ?? 'Unknown error' }, result.status);
+  } catch {
+    return json({ error: 'The account service is unavailable. Please try again later.' }, 502);
+  }
+
+  const user = await ensureUser(username);
+  await signIn(session, username, 'signup');
+  return json({ username: user.username, displayName: user.displayName });
+};
