+import type { APIRoute } from 'astro';
+import { getRelyingParty } from '../../../lib/auth/config';
+import { getCurrentUser, hasRecentAuth, json, reauthRequired, unauthenticated } from '../../../lib/auth/session';
+import { updateUser } from '../../../lib/auth/store';
+
+function profile(user: { username: string; displayName: string; passkeyUserId: string }, rpId: string) {
+  return { name: user.username, displayName: user.displayName, rpId, userId: user.passkeyUserId };
+}
+
+export const GET: APIRoute = async ({ request, session }) => {
+  const user = await getCurrentUser(session);
+  if (!user) return unauthenticated();
+  return json(profile(user, getRelyingParty(request).rpID));
+};
+
+/** Updates the display name. Returns rpId + userId so the client can call signalCurrentUserDetails(). */
+export const PUT: APIRoute = async ({ request, session }) => {
+  const user = await getCurrentUser(session);
+  if (!user) return unauthenticated();
+  if (!(await hasRecentAuth(session))) return reauthRequired();
+
+  const { displayName } = await request.json().catch(() => ({}));
+  const trimmed = typeof displayName === 'string' ? displayName.trim() : '';
+  if (!trimmed || trimmed.length > 64) return json({ error: 'Display name must be 1–64 characters.' }, 400);
+
+  const updated = await updateUser(user.username, { displayName: trimmed });
+  return json(profile(updated!, getRelyingParty(request).rpID));
+};
