+import React, { useEffect, useRef, useState } from 'react';
+import {
+  CloudIcon,
+  DevicePhoneMobileIcon,
+  KeyIcon,
+  PencilIcon,
+  PlusIcon,
+  ShieldCheckIcon,
+  TrashIcon,
+} from '@heroicons/react/24/outline';
+import {
+  PasskeyError,
+  api,
+  appUrl,
+  authenticateWithPasskey,
+  createPasskey,
+  getPasskeySupport,
+  signalAcceptedCredentials,
+  type AccountPayload,
+  type PasskeySupport,
+  type PublicPasskey,
+} from '../lib/auth/client';
+
+interface AccountSettingsProps {
+  initialAccount: AccountPayload;
+}
+
+type Notice = { kind: 'success' | 'error'; text: string } | null;
+
+const dateFormat = new Intl.DateTimeFormat('en-US', { year: 'numeric', month: 'short', day: 'numeric' });
+const formatDate = (ms: number) => dateFormat.format(new Date(ms));
+
+function relativeTime(ms: number) {
+  const diff = Date.now() - ms;
+  const minutes = Math.round(diff / 60000);
+  if (minutes < 1) return 'just now';
+  if (minutes < 60) return `${minutes} minute${minutes === 1 ? '' : 's'} ago`;
+  const hours = Math.round(minutes / 60);
+  if (hours < 24) return `${hours} hour${hours === 1 ? '' : 's'} ago`;
+  const days = Math.round(hours / 24);
+  if (days < 30) return `${days} day${days === 1 ? '' : 's'} ago`;
+  return formatDate(ms);
+}
+
+/* ------------------------------------------------------------------ */
+/* Modal dialog built on <dialog> (focus trapping & Esc for free)      */
+/* ------------------------------------------------------------------ */
+
+function Modal({
+  open,
+  onClose,
+  labelledBy,
+  children,
+}: {
+  open: boolean;
+  onClose: () => void;
+  labelledBy: string;
+  children: React.ReactNode;
+}) {
+  const ref = useRef<HTMLDialogElement>(null);
+  useEffect(() => {
+    const dialog = ref.current;
+    if (!dialog) return;
+    if (open && !dialog.open) dialog.showModal();
+    if (!open && dialog.open) dialog.close();
+  }, [open]);
+  return (
+    <dialog
+      ref={ref}
+      aria-labelledby={labelledBy}
+      onClose={onClose}
+      onCancel={(e) => {
+        e.preventDefault();
+        onClose();
+      }}
+      className="m-auto w-full max-w-sm rounded-lg p-0 shadow-xl backdrop:bg-black/40"
+    >
+      {open && <div className="p-6">{children}</div>}
+    </dialog>
+  );
+}
+
+/* ------------------------------------------------------------------ */
+/* Reauthentication                                                    */
+/* ------------------------------------------------------------------ */
+
+function ReauthDialog({
+  open,
+  hasPasskeys,
+  reason,
+  onSuccess,
+  onCancel,
+}: {
+  open: boolean;
+  hasPasskeys: boolean;
+  reason: string;
+  onSuccess: () => void;
+  onCancel: () => void;
+}) {
+  const [mode, setMode] = useState<'passkey' | 'password'>(hasPasskeys ? 'passkey' : 'password');
+  const [password, setPassword] = useState('');
+  const [busy, setBusy] = useState(false);
+  const [error, setError] = useState<string | null>(null);
+
+  useEffect(() => {
+    if (open) {
+      setMode(hasPasskeys ? 'passkey' : 'password');
+      setPassword('');
+      setError(null);
+    }
+  }, [open, hasPasskeys]);
+
+  const withPasskey = async () => {
+    setError(null);
+    setBusy(true);
+    try {
+      await authenticateWithPasskey({ purpose: 'reauth' });
+      onSuccess();
+    } catch (err) {
+      const e = err as PasskeyError;
+      setError(e.code === 'cancelled' ? 'Passkey verification was cancelled. Try again or use your password.' : e.message);
+    } finally {
+      setBusy(false);
+    }
+  };
+
+  const withPassword = async (e: React.FormEvent) => {
+    e.preventDefault();
+    setError(null);
+    setBusy(true);
+    try {
+      const { ok, data } = await api('auth/reauth/password', { body: { password } });
+      if (!ok) setError(data.error || 'Incorrect password.');
+      else onSuccess();
+    } catch {
+      setError('An unexpected error occurred. Please try again later.');
+    } finally {
+      setBusy(false);
+    }
+  };
+
+  return (
+    <Modal open={open} onClose={onCancel} labelledBy="reauth-title">
+      <div className="flex items-center gap-2 mb-2">
+        <ShieldCheckIcon className="w-6 h-6 text-gray-900" aria-hidden="true" />
+        <h3 id="reauth-title" className="text-lg font-bold text-gray-900">
+          Confirm it’s you
+        </h3>
+      </div>
+      <p className="text-sm text-gray-600 mb-4">{reason}</p>
+
+      {error && (
+        <div className="mb-4 p-3 text-sm text-red-700 bg-red-100 rounded-lg" role="alert">
+          {error}
+        </div>
+      )}
+
+      {mode === 'passkey' ? (
+        <>
+          <button
+            type="button"
+            onClick={withPasskey}
+            disabled={busy}
+            autoFocus
+            className="w-full inline-flex items-center justify-center gap-2 py-2 px-4 rounded-md text-sm font-medium text-white bg-gray-900 hover:bg-gray-800 disabled:opacity-75"
+          >
+            <KeyIcon className="w-5 h-5" aria-hidden="true" />
+            {busy ? 'Waiting for passkey...' : 'Use your passkey'}
+          </button>
+          <button
+            type="button"
+            onClick={() => {
+              setError(null);
+              setMode('password');
+            }}
+            className="mt-3 w-full text-sm text-gray-600 underline hover:text-gray-900"
+          >
+            Use your password instead
+          </button>
+        </>
+      ) : (
+        <form onSubmit={withPassword} className="space-y-3">
+          <div>
+            <label htmlFor="reauth-password" className="block text-sm font-medium text-gray-700 mb-1">
+              Password
+            </label>
+            <input
+              id="reauth-password"
+              type="password"
+              autoComplete="current-password"
+              value={password}
+              onChange={(e) => setPassword(e.target.value)}
+              required
+              autoFocus
+              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
+            />
+          </div>
+          <button
+            type="submit"
+            disabled={busy}
+            className="w-full py-2 px-4 rounded-md text-sm font-medium text-white bg-gray-900 hover:bg-gray-800 disabled:opacity-75"
+          >
+            {busy ? 'Verifying...' : 'Continue'}
+          </button>
+          {hasPasskeys && (
+            <button
+              type="button"
+              onClick={() => {
+                setError(null);
+                setMode('passkey');
+              }}
+              className="w-full text-sm text-gray-600 underline hover:text-gray-900"
+            >
+              Use a passkey instead
+            </button>
+          )}
+        </form>
+      )}
+
+      <button
+        type="button"
+        onClick={onCancel}
+        className="mt-4 w-full py-2 px-4 rounded-md text-sm font-medium text-gray-700 border border-gray-300 hover:bg-gray-50"
+      >
+        Cancel
+      </button>
+    </Modal>
+  );
+}
+
+/* ------------------------------------------------------------------ */
+/* Passkey row                                                         */
+/* ------------------------------------------------------------------ */
+
+function PasskeyRow({
+  passkey,
+  onRename,
+  onRemove,
+}: {
+  passkey: PublicPasskey;
+  onRename: (id: string, name: string) => Promise<boolean>;
+  onRemove: (passkey: PublicPasskey) => void;
+}) {
+  const [editing, setEditing] = useState(false);
+  const [name, setName] = useState(passkey.name);
+  const [saving, setSaving] = useState(false);
+
+  const save = async (e: React.FormEvent) => {
+    e.preventDefault();
+    setSaving(true);
+    const ok = await onRename(passkey.id, name);
+    setSaving(false);
+    if (ok) setEditing(false);
+  };
+
+  const Icon = passkey.synced ? CloudIcon : DevicePhoneMobileIcon;
+
+  return (
+    <li className="flex flex-col sm:flex-row sm:items-center gap-3 py-4">
+      <div className="flex items-start gap-3 flex-1 min-w-0">
+        <div className="mt-0.5 flex h-10 w-10 flex-shrink-0 items-center justify-center rounded-full bg-gray-100">
+          <KeyIcon className="h-5 w-5 text-gray-800" aria-hidden="true" />
+        </div>
+        <div className="min-w-0 flex-1">
+          {editing ? (
+            <form onSubmit={save} className="flex flex-wrap items-center gap-2">
+              <label htmlFor={`name-${passkey.id}`} className="sr-only">
+                Passkey name
+              </label>
+              <input
+                id={`name-${passkey.id}`}
+                value={name}
+                onChange={(e) => setName(e.target.value)}
+                maxLength={64}
+                required
+                autoFocus
+                className="flex-1 min-w-0 px-2 py-1 text-sm border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
+              />
+              <button
+                type="submit"
+                disabled={saving}
+                className="px-3 py-1 text-xs font-semibold text-white bg-gray-900 rounded hover:bg-gray-800 disabled:opacity-75"
+              >
+                {saving ? 'Saving...' : 'Save'}
+              </button>
+              <button
+                type="button"
+                onClick={() => {
+                  setName(passkey.name);
+                  setEditing(false);
+                }}
+                className="px-3 py-1 text-xs font-semibold text-gray-700 border border-gray-300 rounded hover:bg-gray-50"
+              >
+                Cancel
+              </button>
+            </form>
+          ) : (
+            <p className="font-semibold text-gray-900 truncate">{passkey.name}</p>
+          )}
+          <p className="mt-1 flex flex-wrap items-center gap-x-2 gap-y-1 text-xs text-gray-600">
+            <span className="inline-flex items-center gap-1">
+              <Icon className="h-4 w-4" aria-hidden="true" />
+              {passkey.synced ? 'Synced passkey' : 'Device-bound passkey'}
+            </span>
+            {passkey.provider && passkey.provider !== passkey.name && (
+              <>
+                <span aria-hidden="true">·</span>
+                <span>{passkey.provider}</span>
+              </>
+            )}
+          </p>
+          <p className="mt-1 text-xs text-gray-500">
+            Created {formatDate(passkey.createdAt)} ·{' '}
+            {passkey.lastUsedAt ? `Last used ${relativeTime(passkey.lastUsedAt)}` : 'Not used yet'}
+          </p>
+        </div>
+      </div>
+      {!editing && (
+        <div className="flex gap-2 sm:flex-shrink-0 pl-13 sm:pl-0">
+          <button
+            type="button"
+            onClick={() => setEditing(true)}
+            className="inline-flex items-center gap-1 px-3 py-1.5 text-xs font-semibold text-gray-700 border border-gray-300 rounded hover:bg-gray-50"
+          >
+            <PencilIcon className="h-4 w-4" aria-hidden="true" />
+            Rename<span className="sr-only"> {passkey.name}</span>
+          </button>
+          <button
+            type="button"
+            onClick={() => onRemove(passkey)}
+            className="inline-flex items-center gap-1 px-3 py-1.5 text-xs font-semibold text-red-700 border border-red-200 rounded hover:bg-red-50"
+          >
+            <TrashIcon className="h-4 w-4" aria-hidden="true" />
+            Remove<span className="sr-only"> {passkey.name}</span>
+          </button>
+        </div>
+      )}
+    </li>
+  );
+}
+
+/* ------------------------------------------------------------------ */
+/* Account settings                                                    */
+/* ------------------------------------------------------------------ */
+
+type PendingAction = { reason: string; run: () => Promise<void> };
+
+export default function AccountSettings({ initialAccount }: AccountSettingsProps) {
+  const [account, setAccount] = useState<AccountPayload>(initialAccount);
+  const [support, setSupport] = useState<PasskeySupport | null>(null);
+  const [notice, setNotice] = useState<Notice>(null);
+  const [creating, setCreating] = useState(false);
+  const [toRemove, setToRemove] = useState<PublicPasskey | null>(null);
+  const [removing, setRemoving] = useState(false);
+  const [reauth, setReauth] = useState<PendingAction | null>(null);
+  const [signingOut, setSigningOut] = useState(false);
+
+  useEffect(() => {
+    getPasskeySupport().then(setSupport);
+    // Keep password managers in sync with the passkeys this account still accepts.
+    signalAcceptedCredentials(initialAccount);
+
+    const params = new URLSearchParams(window.location.search);
+    if (params.get('passkey') === 'created') {
+      setNotice({ kind: 'success', text: 'Passkey created. Next time, sign in with your fingerprint, face, or screen lock.' });
+      params.delete('passkey');
+      const query = params.toString();
+      window.history.replaceState(null, '', `${window.location.pathname}${query ? `?${query}` : ''}`);
+    }
+  }, []);
+
+  const update = (next: AccountPayload) => {
+    setAccount(next);
+    signalAcceptedCredentials(next);
+  };
+
+  /** Run a sensitive action, asking the user to confirm their identity first if the server requires it. */
+  const withReauth = async (reason: string, run: () => Promise<void>) => {
+    try {
+      await run();
+    } catch (err) {
+      if (err instanceof PasskeyError && err.code === 'reauth_required') {
+        setReauth({ reason, run });
+      } else {
+        throw err;
+      }
+    }
+  };
+
+  const handleCreate = async () => {
+    setNotice(null);
+    setCreating(true);
+    try {
+      await withReauth('For your security, confirm it’s you before adding a passkey.', async () => {
+        const result = await createPasskey();
+        update(result);
+        setNotice({ kind: 'success', text: `Passkey “${result.passkey.name}” created.` });
+      });
+    } catch (err) {
+      const e = err as PasskeyError;
+      if (e.code === 'not_signed_in') window.location.assign(appUrl('signin?next=' + encodeURIComponent(window.location.pathname)));
+      else if (e.code !== 'cancelled') setNotice({ kind: 'error', text: e.message });
+    } finally {
+      setCreating(false);
+    }
+  };
+
+  const handleRename = async (id: string, name: string) => {
+    setNotice(null);
+    const { ok, data } = await api(`auth/passkeys/${encodeURIComponent(id)}`, { method: 'PATCH', body: { name } });
+    if (!ok) {
+      setNotice({ kind: 'error', text: data.error || 'Could not rename passkey.' });
+      return false;
+    }
+    update(data);
+    setNotice({ kind: 'success', text: 'Passkey renamed.' });
+    return true;
+  };
+
+  const removePasskey = async (passkey: PublicPasskey) => {
+    const { ok, data } = await api(`auth/passkeys/${encodeURIComponent(passkey.id)}`, { method: 'DELETE' });
+    if (!ok) {
+      throw new PasskeyError(data.code === 'reauth_required' ? 'reauth_required' : 'failed', data.error || 'Could not remove passkey.');
+    }
+    update(data);
+    setNotice({
+      kind: 'success',
+      text: `Passkey “${passkey.name}” removed. You may also want to delete it from your password manager.`,
+    });
+  };
+
+  const confirmRemove = async () => {
+    if (!toRemove) return;
+    const passkey = toRemove;
+    setNotice(null);
+    setRemoving(true);
+    try {
+      await withReauth('For your security, confirm it’s you before removing a passkey.', () => removePasskey(passkey));
+      setToRemove(null);
+    } catch (err) {
+      setToRemove(null);
+      setNotice({ kind: 'error', text: (err as Error).message });
+    } finally {
+      setRemoving(false);
+    }
+  };
+
+  const onReauthSuccess = async () => {
+    const pending = reauth;
+    setReauth(null);
+    setToRemove(null);
+    if (!pending) return;
+    try {
+      await pending.run();
+    } catch (err) {
+      const e = err as PasskeyError;
+      if (e.code !== 'cancelled') setNotice({ kind: 'error', text: e.message });
+    }
+  };
+
+  const signOut = async () => {
+    setSigningOut(true);
+    try {
+      await api('auth/logout', { body: {} });
+    } finally {
+      window.location.assign(appUrl(''));
+    }
+  };
+
+  const passkeys = account.passkeys;
+  const canCreate = support?.webauthn;
+
