new file mode 100644
index 0000000..19a95ca
--- /dev/null
+++ b/src/components/PasskeyPrompt.tsx
@@ -0,0 +1,91 @@
+import React, { useState } from 'react';
+import { CheckIcon, KeyIcon } from '@heroicons/react/24/outline';
+import { PasskeyError, createPasskey } from '../lib/auth/client';
+
+interface PasskeyPromptProps {
+  title: string;
+  intro?: string;
+  onCreated: () => void;
+  onSkip: () => void;
+  skipLabel?: string;
+}
+
+/** Explains passkeys and lets a freshly signed-in user create one. */
+export default function PasskeyPrompt({ title, intro, onCreated, onSkip, skipLabel = 'Skip for now' }: PasskeyPromptProps) {
+  const [loading, setLoading] = useState(false);
+  const [error, setError] = useState<string | null>(null);
+  const [created, setCreated] = useState(false);
+
+  const handleCreate = async () => {
+    setError(null);
+    setLoading(true);
+    try {
+      await createPasskey();
+      setCreated(true);
+      // Let the confirmation register before moving on.
+      setTimeout(onCreated, 1200);
+    } catch (err) {
+      const e = err as PasskeyError;
+      if (e.code !== 'cancelled') setError(e.message);
+    } finally {
+      setLoading(false);
+    }
+  };
+
+  return (
+    <div className="text-center">
+      <div className="mx-auto mb-4 flex h-12 w-12 items-center justify-center rounded-full bg-gray-100">
+        {created ? (
+          <CheckIcon className="h-6 w-6 text-green-700" aria-hidden="true" />
+        ) : (
+          <KeyIcon className="h-6 w-6 text-gray-900" aria-hidden="true" />
+        )}
+      </div>
+      <h2 className="text-2xl font-bold mb-2 text-gray-800">{created ? 'Passkey created' : title}</h2>
+      {intro && <p className="text-sm text-gray-600 mb-4">{intro}</p>}
+
+      {created ? (
+        <p className="text-sm text-gray-600" role="status">
+          You can now sign in with your fingerprint, face, or screen lock.
+        </p>
+      ) : (
+        <>
+          <p className="text-sm text-gray-700 mb-3">
+            Create a passkey to sign in with your fingerprint, face, or screen lock instead of typing your password.
+          </p>
+          <ul className="text-left text-sm text-gray-600 mb-5 space-y-1 list-disc pl-5">
+            <li>Faster: no password to remember or type.</li>
+            <li>Safer: passkeys can’t be phished or leaked in a data breach.</li>
+            <li>Synced across your devices by your password manager.</li>
+          </ul>
+
+          {error && (
+            <div className="mb-4 p-3 text-sm text-left text-red-700 bg-red-100 rounded-lg" role="alert">
+              {error}
+            </div>
+          )}
+
+          <button
+            type="button"
+            onClick={handleCreate}
+            disabled={loading}
+            className={`w-full inline-flex items-center justify-center gap-2 py-2 px-4 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-gray-900 hover:bg-gray-800 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-900 ${
+              loading ? 'opacity-75 cursor-not-allowed' : ''
+            }`}
+          >
+            <KeyIcon className="w-5 h-5" aria-hidden="true" />
+            {loading ? 'Creating passkey...' : 'Create a passkey'}
+          </button>
+          <button
+            type="button"
+            onClick={onSkip}
+            disabled={loading}
+            className="mt-3 w-full py-2 px-4 text-sm font-medium text-gray-600 hover:text-gray-900 underline"
+          >
+            {skipLabel}
+          </button>
+        </>
+      )}
+    </div>
+  );
+}
