+/**
+ * Friendly names for common passkey providers, keyed by AAGUID.
+ * Subset of the community list at
+ * https://github.com/passkeydeveloper/passkey-authenticator-aaguids
+ */
+const PROVIDERS: Record<string, string> = {
+  'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4': 'Google Password Manager',
+  'adce0002-35bc-c60a-648b-0b25f1f05503': 'Chrome on Mac',
+  'b5397666-4885-aa6b-cebf-e52262a439a2': 'Chromium Browser',
+  '771b48fd-d3d4-4f74-9232-fc157ab0507a': 'Edge on Mac',
+  'fbfc3007-154e-4ecc-8c0b-6e020557d7bd': 'iCloud Keychain',
+  'dd4ec289-e01d-41c9-bb89-70fa845d4bf2': 'iCloud Keychain (Managed)',
+  '08987058-cadc-4b81-b6e1-30de50dcbe96': 'Windows Hello',
+  '9ddd1817-af5a-4672-a2b9-3e3dd95000a9': 'Windows Hello',
+  '6028b017-b1d4-4c02-b4b3-afcdafc96bb2': 'Windows Hello',
+  'bada5566-a7aa-401f-bd96-45619a55120d': '1Password',
+  'd548826e-79b4-db40-a3d8-11116f7e8349': 'Bitwarden',
+  '53414d53-554e-4700-0000-000000000000': 'Samsung Pass',
+  '531126d6-e717-415c-9320-3d9aa6981239': 'Dashlane',
+  'b84e4048-15dc-4dd0-8640-f4f60813c8af': 'NordPass',
+  '0ea242b4-43c4-4a1b-8b17-dd6d0b6baec6': 'Keeper',
+};
+
+export function providerNameForAaguid(aaguid: string | undefined): string | undefined {
+  if (!aaguid) return undefined;
+  return PROVIDERS[aaguid.toLowerCase()];
+}
diff --git a/src/lib/auth/client.ts b/src/lib/auth/client.ts
new file mode 100644
index 0000000..8d0580d
--- /dev/null
+++ b/src/lib/auth/client.ts
@@ -0,0 +1,228 @@
+/**
+ * Browser-side helpers for password + passkey auth against the /api/auth routes.
+ */
+import {
+  WebAuthnError,
+  browserSupportsWebAuthn,
+  browserSupportsWebAuthnAutofill,
+  sendSignal,
+  startAuthentication,
+  startRegistration,
+} from '@simplewebauthn/browser';
+
+export interface PublicPasskey {
+  id: string;
+  name: string;
+  provider?: string;
+  synced: boolean;
+  deviceType: string;
+  transports: string[];
+  createdAt: number;
+  lastUsedAt: number | null;
+}
+
+export interface AccountPayload {
+  user: { id: string; username: string };
+  rpID: string;
+  passkeys: PublicPasskey[];
+}
+
+export type PasskeyErrorCode =
+  | 'cancelled'
+  | 'unsupported'
+  | 'already_registered'
+  | 'unknown_credential'
+  | 'reauth_required'
+  | 'not_signed_in'
+  | 'failed';
+
+export class PasskeyError extends Error {
+  constructor(public code: PasskeyErrorCode, message: string) {
+    super(message);
+  }
+}
+
+const BASE = import.meta.env.BASE_URL.replace(/\/$/, '');
+
+export const appUrl = (path: string) => `${BASE}/${path.replace(/^\//, '')}`;
+
+export async function api<T = any>(
+  path: string,
+  init: { method?: string; body?: unknown } = {},
+): Promise<{ ok: boolean; status: number; data: T }> {
+  const response = await fetch(appUrl(`api/${path}`), {
+    method: init.method ?? (init.body !== undefined ? 'POST' : 'GET'),
+    credentials: 'same-origin',
+    headers: init.body !== undefined ? { 'Content-Type': 'application/json' } : undefined,
+    body: init.body !== undefined ? JSON.stringify(init.body) : undefined,
+  });
+  let data: any = {};
+  try {
+    data = await response.json();
+  } catch {
+    // Non-JSON response.
+  }
+  return { ok: response.ok, status: response.status, data };
+}
+
+/* ------------------------------------------------------------------ */
+/* Feature detection                                                   */
+/* ------------------------------------------------------------------ */
+
+export interface PasskeySupport {
+  /** WebAuthn is available at all. */
+  webauthn: boolean;
+  /** Passkeys can be offered in form autofill (conditional mediation). */
+  conditionalGet: boolean;
+  /** The browser can create a passkey automatically after a password sign-in. */
+  conditionalCreate: boolean;
+}
+
+export async function getPasskeySupport(): Promise<PasskeySupport> {
+  if (!browserSupportsWebAuthn()) {
+    return { webauthn: false, conditionalGet: false, conditionalCreate: false };
+  }
+  let conditionalGet = false;
+  let conditionalCreate = false;
+  const PKC = window.PublicKeyCredential as any;
+  try {
+    if (typeof PKC.getClientCapabilities === 'function') {
+      const caps = await PKC.getClientCapabilities();
+      conditionalGet = !!caps.conditionalGet;
+      conditionalCreate = !!caps.conditionalCreate;
+    } else {
+      conditionalGet = await browserSupportsWebAuthnAutofill();
+    }
+  } catch {
+    // Capability detection failed; fall back to explicit buttons only.
+  }
+  return { webauthn: true, conditionalGet, conditionalCreate };
+}
+
+/* ------------------------------------------------------------------ */
+/* Ceremonies                                                          */
+/* ------------------------------------------------------------------ */
+
+function toPasskeyError(err: unknown, context: 'create' | 'get'): PasskeyError {
+  if (err instanceof PasskeyError) return err;
+  const name = (err as any)?.name;
+  const code = err instanceof WebAuthnError ? err.code : undefined;
+  if (code === 'ERROR_CEREMONY_ABORTED' || name === 'AbortError') {
+    return new PasskeyError('cancelled', 'The passkey request was cancelled.');
+  }
+  if (code === 'ERROR_AUTHENTICATOR_PREVIOUSLY_REGISTERED' || name === 'InvalidStateError') {
+    return new PasskeyError(
+      'already_registered',
+      'A passkey for this account already exists in this password manager or security key.',
+    );
+  }
+  if (name === 'NotAllowedError') {
+    // Raised when the user dismisses the dialog or it times out. Treated as a quiet cancel.
+    return new PasskeyError('cancelled', 'The passkey request was cancelled or timed out.');
+  }
+  if (name === 'NotSupportedError' || code === 'ERROR_INVALID_DOMAIN') {
+    return new PasskeyError('unsupported', 'Passkeys are not supported on this device or browser.');
+  }
+  return new PasskeyError(
+    'failed',
+    context === 'create'
+      ? 'Something went wrong while creating your passkey. Please try again.'
+      : 'Something went wrong while using your passkey. Please try again.',
+  );
+}
+
+function fromApiError(data: any, fallback: string): PasskeyError {
+  const code: PasskeyErrorCode = ['reauth_required', 'not_signed_in', 'unknown_credential', 'already_registered'].includes(
+    data?.code,
+  )
+    ? data.code
+    : 'failed';
+  return new PasskeyError(code, data?.error || fallback);
+}
+
+/**
+ * Create a passkey for the signed-in user.
+ * With `automatic: true`, uses conditional create: the browser silently upgrades
+ * the password the user just used into a passkey, without showing a dialog.
+ */
+export async function createPasskey({ automatic = false } = {}): Promise<AccountPayload & { passkey: PublicPasskey }> {
+  const options = await api('auth/passkeys/register-options', { body: {} });
+  if (!options.ok) throw fromApiError(options.data, 'Could not start passkey creation.');
+
+  let response;
+  try {
+    response = await startRegistration({ optionsJSON: options.data, useAutoRegister: automatic });
+  } catch (err) {
+    throw toPasskeyError(err, 'create');
+  }
+
+  const verify = await api('auth/passkeys/register-verify', { body: { response } });
+  if (!verify.ok) throw fromApiError(verify.data, 'Could not save your passkey.');
+  signalAcceptedCredentials(verify.data);
+  return verify.data;
+}
+
+/**
+ * Authenticate with a passkey.
+ *  - `purpose: 'signin'` signs the user in (discoverable credentials).
+ *  - `purpose: 'reauth'` confirms the signed-in user's identity.
+ *  - `autofill: true` waits for the user to pick a passkey from form autofill.
+ */
+export async function authenticateWithPasskey({
+  purpose = 'signin',
+  autofill = false,
+}: { purpose?: 'signin' | 'reauth'; autofill?: boolean } = {}): Promise<AccountPayload> {
+  const options = await api('auth/passkeys/auth-options', { body: { purpose } });
+  if (!options.ok) throw fromApiError(options.data, 'Could not start passkey sign-in.');
+
+  let response;
+  try {
+    response = await startAuthentication({ optionsJSON: options.data, useBrowserAutofill: autofill });
+  } catch (err) {
+    throw toPasskeyError(err, 'get');
+  }
+
+  const verify = await api('auth/passkeys/auth-verify', { body: { purpose, response } });
+  if (!verify.ok) {
+    if (verify.data?.code === 'unknown_credential') {
+      // Ask the passkey provider to hide/remove the passkey the server no longer recognizes.
+      sendSignal({
+        signalName: 'unknownCredential',
+        rpID: options.data.rpId ?? window.location.hostname,
+        credentialID: verify.data.credentialId ?? response.id,
+      }).catch(() => undefined);
+    }
+    throw fromApiError(verify.data, 'Passkey sign-in failed.');
+  }
+  signalAcceptedCredentials(verify.data);
+  return verify.data;
+}
+
+/**
+ * Keep the user's passkey providers in sync with the server: hide passkeys that
+ * were removed here, and update the displayed account name. Best effort; ignored
+ * by browsers without the Signal API.
+ */
+export function signalAcceptedCredentials(account: AccountPayload | null | undefined) {
+  if (!account?.user || !account.rpID) return;
+  sendSignal({
+    signalName: 'allAcceptedCredentials',
+    rpID: account.rpID,
+    userID: account.user.id,
+    allAcceptedCredentialIDs: account.passkeys.map((p) => p.id),
+  }).catch(() => undefined);
+  sendSignal({
+    signalName: 'currentUserDetails',
+    rpID: account.rpID,
+    userID: account.user.id,
+    userName: account.user.username,
+    userDisplayName: account.user.username,
+  }).catch(() => undefined);
+}
+
+/** Only allow same-site relative redirects. */
+export function safeNextUrl(fallback = appUrl('account')) {
+  const next = new URLSearchParams(window.location.search).get('next');
+  if (next && next.startsWith('/') && !next.startsWith('//')) return next;
+  return fallback;
+}
diff --git a/src/lib/auth/server.ts b/src/lib/auth/server.ts
new file mode 100644
index 0000000..f702dce
--- /dev/null
+++ b/src/lib/auth/server.ts
@@ -0,0 +1,163 @@
+/**
+ * Shared server-side helpers for the auth & passkey API routes.
+ */
+import type { APIContext } from 'astro';
+import type { StoredPasskey, StoredUser } from './store';
+import { providerNameForAaguid } from './aaguids';
+
+/** Upstream account service (owns usernames & passwords). */
+export const AUTH_API = 'https://us-central1-web-devrel-apps.cloudfunctions.net/times_cdn/api';
+
+export const RP_NAME = 'The DevTools Times';
+
+/** How long a WebAuthn challenge stays valid. */
+export const CHALLENGE_TTL_MS = 5 * 60 * 1000;
+
+/** Sensitive actions (adding/removing passkeys) require an authentication this recent. */
+export const REAUTH_WINDOW_MS = 5 * 60 * 1000;
+
+/**
+ * Relying party ID and expected origins.
+ *
+ * Defaults to the host the request was served from (Astro resolves
+ * X-Forwarded-* headers for the domains listed in `security.allowedDomains`).
+ * Override with `PASSKEY_RP_ID` / `PASSKEY_ORIGINS` (comma separated) when the
+ * app is served from multiple hosts that should share passkeys.
+ */
+export function getRelyingParty(url: URL) {
+  const rpID = process.env.PASSKEY_RP_ID || url.hostname;
+  const origins = process.env.PASSKEY_ORIGINS
+    ? process.env.PASSKEY_ORIGINS.split(',').map((o) => o.trim()).filter(Boolean)
+    : [url.origin];
+  return { rpID, origins };
+}
+
+export function json(body: unknown, status = 200, headers: Record<string, string> = {}) {
+  return new Response(JSON.stringify(body), {
+    status,
+    headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store', ...headers },
+  });
+}
+
+export function error(status: number, code: string, message: string) {
+  return json({ error: message, code }, status);
+}
+
+/** Reject requests whose Origin header (when present) isn't this site. */
+export function rejectForeignOrigin(context: APIContext): Response | null {
+  const { request, url } = context;
+  const origin = request.headers.get('origin');
+  if (origin && origin !== url.origin && !getRelyingParty(url).origins.includes(origin)) {
+    return error(403, 'forbidden_origin', 'Cross-site request rejected.');
+  }
+  return null;
+}
+
+/**
+ * Basic CSRF protection for state-changing JSON endpoints. Astro's built-in
+ * `checkOrigin` is disabled in this project, so we require a JSON content type
+ * (forcing a CORS preflight for cross-site callers) and, when the browser sends
+ * an Origin header, that it matches this site.
+ */
+export function rejectCrossSite(context: APIContext): Response | null {
+  const contentType = context.request.headers.get('content-type') ?? '';
+  if (!contentType.includes('application/json')) {
+    return error(415, 'unsupported_media_type', 'Expected application/json.');
+  }
+  return rejectForeignOrigin(context);
+}
+
+export async function readJson<T = any>(request: Request): Promise<T | null> {
+  try {
+    return (await request.json()) as T;
+  } catch {
+    return null;
+  }
+}
+
+export async function getSessionUser(context: APIContext) {
+  return (await context.session?.get('user')) ?? null;
+}
+
+export async function isRecentlyAuthenticated(context: Pick<APIContext, 'session'>) {
+  const at = await context.session?.get('authenticatedAt');
+  return typeof at === 'number' && Date.now() - at < REAUTH_WINDOW_MS;
+}
+
+/** Establish a fresh signed-in session (rotating the session ID to prevent fixation). */
+export async function signIn(context: APIContext, user: { id: string; username: string }) {
+  const session = context.session;
+  if (!session) throw new Error('Sessions are not configured');
+  await session.regenerate();
+  session.set('user', { id: user.id, username: user.username });
+  session.set('authenticatedAt', Date.now());
+  session.delete('webauthnChallenge');
+}
+
+export async function issueChallenge(
+  context: APIContext,
+  challenge: string,
+  purpose: App.SessionData['webauthnChallenge']['purpose'],
+) {
+  context.session?.set('webauthnChallenge', {
+    challenge,
+    purpose,
+    expiresAt: Date.now() + CHALLENGE_TTL_MS,
+  });
+}
+
+/** Retrieve and invalidate the pending challenge (challenges are single use). */
+export async function consumeChallenge(
+  context: APIContext,
+  purpose: App.SessionData['webauthnChallenge']['purpose'],
+) {
+  const pending = await context.session?.get('webauthnChallenge');
+  context.session?.delete('webauthnChallenge');
+  if (!pending || pending.purpose !== purpose || pending.expiresAt < Date.now()) return null;
+  return pending.challenge;
+}
+
+/** Public, client-safe representation of a passkey. */
+export function toPublicPasskey(p: StoredPasskey) {
+  return {
+    id: p.id,
+    name: p.name,
+    provider: p.provider ?? providerNameForAaguid(p.aaguid),
+    synced: p.backedUp,
+    deviceType: p.deviceType,
+    transports: p.transports ?? [],
+    createdAt: p.createdAt,
+    lastUsedAt: p.lastUsedAt ?? null,
+  };
+}
+
+export type PublicPasskey = ReturnType<typeof toPublicPasskey>;
+
+export function accountPayload(context: { url: URL }, user: StoredUser) {
+  const { rpID } = getRelyingParty(context.url);
+  return {
+    user: { id: user.id, username: user.username },
+    rpID,
+    passkeys: user.passkeys.map(toPublicPasskey),
+  };
+}
+
+/** Forward a credential check to the upstream account service. */
+export async function upstreamAuth(
+  endpoint: 'login' | 'register',
+  username: string,
+  password: string,
+) {
+  const response = await fetch(`${AUTH_API}/${endpoint}`, {
+    method: 'POST',
+    headers: { 'Content-Type': 'application/json' },
+    body: JSON.stringify({ username, password }),
+  });
+  let data: any = {};
+  try {
+    data = await response.json();
+  } catch {
+    // Upstream returned a non-JSON body; fall through with an empty object.
+  }
+  return { ok: response.ok, status: response.status, data };
+}
