--- /dev/null
+++ b/src/lib/auth/store.ts
@@ -0,0 +1,162 @@
+/**
+ * Minimal persistent store for user handles and passkey credentials.
+ *
+ * Accounts themselves (username + password) live in the external Times auth
+ * service. This store only keeps the WebAuthn data that service doesn't know
+ * about: a stable, opaque user handle per username and the public keys of the
+ * passkeys registered for it.
+ *
+ * Data is kept in a single JSON file (path configurable with
+ * `PASSKEY_STORE_PATH`). Writes are serialized through a promise chain and
+ * written atomically (temp file + rename) so concurrent requests can't corrupt
+ * the file. Swap this module for a real database in production.
+ */
+import { promises as fs } from 'node:fs';
+import path from 'node:path';
+import { randomBytes } from 'node:crypto';
+
+export interface StoredPasskey {
+  /** Base64URL credential ID. */
+  id: string;
+  /** Base64URL COSE public key. */
+  publicKey: string;
+  counter: number;
+  transports?: string[];
+  /** 'singleDevice' | 'multiDevice' */
+  deviceType: string;
+  backedUp: boolean;
+  aaguid: string;
+  /** User-editable label. */
+  name: string;
+  /** Name of the passkey provider (e.g. "Google Password Manager"), if known. */
+  provider?: string;
+  createdAt: number;
+  lastUsedAt?: number;
+}
+
+export interface StoredUser {
+  /** Base64URL WebAuthn user handle (random, never the username). */
+  id: string;
+  username: string;
+  passkeys: StoredPasskey[];
+}
+
+interface StoreData {
+  users: Record<string, StoredUser>; // keyed by user handle
+}
+
+const STORE_PATH =
+  process.env.PASSKEY_STORE_PATH ?? path.join(process.cwd(), '.data', 'passkeys.json');
+
+let cache: StoreData | null = null;
+let queue: Promise<unknown> = Promise.resolve();
+
+async function load(): Promise<StoreData> {
+  if (cache) return cache;
+  try {
+    const raw = await fs.readFile(STORE_PATH, 'utf8');
+    const parsed = JSON.parse(raw) as StoreData;
+    cache = { users: parsed.users ?? {} };
+  } catch (err: any) {
+    if (err?.code !== 'ENOENT') throw err;
+    cache = { users: {} };
+  }
+  return cache;
+}
+
+async function persist(data: StoreData) {
+  await fs.mkdir(path.dirname(STORE_PATH), { recursive: true });
+  const tmp = `${STORE_PATH}.${process.pid}.${Date.now()}.tmp`;
+  await fs.writeFile(tmp, JSON.stringify(data, null, 2), 'utf8');
+  await fs.rename(tmp, STORE_PATH);
+}
+
+/** Run `fn` with exclusive access to the store; persists afterwards when `write` is true. */
+function withStore<T>(fn: (data: StoreData) => T | Promise<T>, write = false): Promise<T> {
+  const run = queue.then(async () => {
+    const data = await load();
+    const result = await fn(data);
+    if (write) await persist(data);
+    return result;
+  });
+  // Keep the chain alive even if this operation fails.
+  queue = run.catch(() => undefined);
+  return run;
+}
+
+const normalize = (username: string) => username.trim().toLowerCase();
+
+function findByUsername(data: StoreData, username: string) {
+  const key = normalize(username);
+  return Object.values(data.users).find((u) => normalize(u.username) === key);
+}
+
+/** Returns the user record for `username`, creating a fresh user handle if needed. */
+export function getOrCreateUser(username: string): Promise<StoredUser> {
+  return withStore((data) => {
+    const existing = findByUsername(data, username);
+    if (existing) return structuredClone(existing);
+    const user: StoredUser = {
+      id: randomBytes(32).toString('base64url'),
+      username: username.trim(),
+      passkeys: [],
+    };
+    data.users[user.id] = user;
+    return structuredClone(user);
+  }, true);
+}
+
+export function getUserById(id: string): Promise<StoredUser | undefined> {
+  return withStore((data) => {
+    const user = data.users[id];
+    return user ? structuredClone(user) : undefined;
+  });
+}
+
+export function findCredential(
+  credentialId: string,
+): Promise<{ user: StoredUser; passkey: StoredPasskey } | undefined> {
+  return withStore((data) => {
+    for (const user of Object.values(data.users)) {
+      const passkey = user.passkeys.find((p) => p.id === credentialId);
+      if (passkey) return structuredClone({ user, passkey });
+    }
+    return undefined;
+  });
+}
+
+export function addPasskey(userId: string, passkey: StoredPasskey): Promise<void> {
+  return withStore((data) => {
+    const user = data.users[userId];
+    if (!user) throw new Error('Unknown user');
+    for (const other of Object.values(data.users)) {
+      if (other.passkeys.some((p) => p.id === passkey.id)) {
+        throw new Error('Credential already registered');
+      }
+    }
+    user.passkeys.push(passkey);
+  }, true);
+}
+
+export function updatePasskey(
+  userId: string,
+  credentialId: string,
+  patch: Partial<Pick<StoredPasskey, 'name' | 'counter' | 'lastUsedAt' | 'backedUp'>>,
+): Promise<StoredPasskey | undefined> {
+  return withStore((data) => {
+    const passkey = data.users[userId]?.passkeys.find((p) => p.id === credentialId);
+    if (!passkey) return undefined;
+    Object.assign(passkey, patch);
+    return structuredClone(passkey);
+  }, true);
+}
+
+export function deletePasskey(userId: string, credentialId: string): Promise<boolean> {
+  return withStore((data) => {
+    const user = data.users[userId];
+    if (!user) return false;
+    const before = user.passkeys.length;
+    user.passkeys = user.passkeys.filter((p) => p.id !== credentialId);
+    return user.passkeys.length !== before;
+  }, true);
+}
