+---
+import Layout from '../layouts/Layout.astro';
+import AccountSettings from '../components/AccountSettings';
+import { getUserById } from '../lib/auth/store';
+import { accountPayload } from '../lib/auth/server';
+
+const baseUrl = import.meta.env.BASE_URL;
+const sessionUser = await Astro.session?.get('user');
+const user = sessionUser ? await getUserById(sessionUser.id) : undefined;
+
+if (!user) {
+  return Astro.redirect(`${baseUrl}signin?next=${encodeURIComponent(`${baseUrl}account`)}`);
+}
+
+Astro.response.headers.set('Cache-Control', 'no-store');
+const account = accountPayload(Astro, user);
+---
+
+<Layout title="Account Settings | The DevTools Times">
+  <div class="py-12 px-4 sm:px-6 lg:px-8">
+    <AccountSettings client:load initialAccount={account} />
+  </div>
+</Layout>
