+import type { APIRoute } from 'astro';
+import { getOrCreateUser } from '../../../lib/auth/store';
+import { error, json, readJson, rejectCrossSite, signIn, upstreamAuth } from '../../../lib/auth/server';
+
+/**
+ * Password sign-in. Credentials are verified by the upstream account service;
+ * on success we establish a server session so passkeys can be managed.
+ */
+export const POST: APIRoute = async (context) => {
+  const rejected = rejectCrossSite(context);
+  if (rejected) return rejected;
+
+  const body = await readJson<{ username?: string; password?: string }>(context.request);
+  const username = body?.username?.trim();
+  const password = body?.password;
+  if (!username || !password) {
+    return error(400, 'invalid_request', 'Username and password are required.');
+  }
+
+  let upstream;
+  try {
+    upstream = await upstreamAuth('login', username, password);
+  } catch {
+    return error(502, 'upstream_unavailable', 'The sign-in service is unavailable.');
+  }
+  if (!upstream.ok) {
+    // Pass the upstream error (including its APP_ERR_* code) straight through.
+    return json(upstream.data, upstream.status);
+  }
+
+  const user = await getOrCreateUser(username);
+  await signIn(context, user);
+
+  return json({
+    ...upstream.data,
+    user: { id: user.id, username: user.username },
+    hasPasskeys: user.passkeys.length > 0,
+  });
+};
