@@ -0,0 +1,55 @@
+import type { APIRoute } from 'astro';
+import { deletePasskey, getUserById, updatePasskey } from '../../../../lib/auth/store';
+import {
+  accountPayload,
+  error,
+  getSessionUser,
+  isRecentlyAuthenticated,
+  json,
+  readJson,
+  rejectCrossSite,
+  rejectForeignOrigin,
+} from '../../../../lib/auth/server';
+
+const MAX_NAME_LENGTH = 64;
+
+/** Rename a passkey. */
+export const PATCH: APIRoute = async (context) => {
+  const rejected = rejectCrossSite(context);
+  if (rejected) return rejected;
+
+  const sessionUser = await getSessionUser(context);
+  if (!sessionUser) return error(401, 'not_signed_in', 'Please sign in first.');
+
+  const body = await readJson<{ name?: string }>(context.request);
+  const name = body?.name?.trim();
+  if (!name) return error(400, 'invalid_request', 'Please enter a name.');
+  if (name.length > MAX_NAME_LENGTH) {
+    return error(400, 'invalid_request', `Names can be at most ${MAX_NAME_LENGTH} characters.`);
+  }
+
+  const updated = await updatePasskey(sessionUser.id, context.params.id!, { name });
+  if (!updated) return error(404, 'not_found', 'Passkey not found.');
+
+  const user = (await getUserById(sessionUser.id))!;
+  return json(accountPayload(context, user));
+};
+
+/** Remove a passkey. Requires a recent (re)authentication. */
+export const DELETE: APIRoute = async (context) => {
+  // DELETE is never a "simple" CORS request, so cross-site callers also get a preflight.
+  const rejected = rejectForeignOrigin(context);
+  if (rejected) return rejected;
+
+  const sessionUser = await getSessionUser(context);
+  if (!sessionUser) return error(401, 'not_signed_in', 'Please sign in first.');
+  if (!(await isRecentlyAuthenticated(context))) {
+    return error(403, 'reauth_required', 'Please confirm it’s you before removing a passkey.');
+  }
+
+  const removed = await deletePasskey(sessionUser.id, context.params.id!);
+  if (!removed) return error(404, 'not_found', 'Passkey not found.');
+
+  const user = (await getUserById(sessionUser.id))!;
+  return json(accountPayload(context, user));
+};
