+import type { APIRoute } from 'astro';
+import { generateAuthenticationOptions } from '@simplewebauthn/server';
+import { getUserById } from '../../../../lib/auth/store';
+import {
+  error,
+  getRelyingParty,
+  getSessionUser,
+  issueChallenge,
+  json,
+  readJson,
+  rejectCrossSite,
+} from '../../../../lib/auth/server';
+
+/**
+ * Step 1 of passkey authentication.
+ *  - purpose "signin": discoverable-credential flow (no allowCredentials), used for
+ *    the sign-in button and form autofill (conditional mediation).
+ *  - purpose "reauth": restricted to the signed-in user's passkeys, used to confirm
+ *    identity before sensitive account changes.
+ */
+export const POST: APIRoute = async (context) => {
+  const rejected = rejectCrossSite(context);
+  if (rejected) return rejected;
+
+  const body = await readJson<{ purpose?: string }>(context.request);
+  const purpose = body?.purpose === 'reauth' ? 'reauth' : 'signin';
+  const { rpID } = getRelyingParty(context.url);
+
+  let allowCredentials: { id: string; transports?: string[] }[] = [];
+  if (purpose === 'reauth') {
+    const sessionUser = await getSessionUser(context);
+    const user = sessionUser && (await getUserById(sessionUser.id));
+    if (!user) return error(401, 'not_signed_in', 'Please sign in first.');
+    if (user.passkeys.length === 0) {
+      return error(400, 'no_passkeys', 'This account has no passkeys.');
+    }
+    allowCredentials = user.passkeys.map((p) => ({ id: p.id, transports: p.transports }));
+  }
+
+  const options = await generateAuthenticationOptions({
+    rpID,
+    allowCredentials,
+    userVerification: 'preferred',
+  });
+
+  await issueChallenge(context, options.challenge, purpose);
+  return json(options);
+};
