@@ -0,0 +1,99 @@
+import type { APIRoute } from 'astro';
+import { verifyAuthenticationResponse } from '@simplewebauthn/server';
+import type { AuthenticationResponseJSON } from '@simplewebauthn/server';
+import { isoBase64URL } from '@simplewebauthn/server/helpers';
+import { findCredential, getUserById, updatePasskey } from '../../../../lib/auth/store';
+import {
+  accountPayload,
+  consumeChallenge,
+  error,
+  getRelyingParty,
+  getSessionUser,
+  json,
+  readJson,
+  rejectCrossSite,
+  signIn,
+} from '../../../../lib/auth/server';
+
+/** Step 2 of passkey authentication: verify the assertion and sign in / refresh the auth timestamp. */
+export const POST: APIRoute = async (context) => {
+  const rejected = rejectCrossSite(context);
+  if (rejected) return rejected;
+
+  const body = await readJson<{ purpose?: string; response?: AuthenticationResponseJSON }>(
+    context.request,
+  );
+  const purpose = body?.purpose === 'reauth' ? 'reauth' : 'signin';
+  const response = body?.response;
+  if (!response?.id) return error(400, 'invalid_request', 'Missing authentication response.');
+
+  const expectedChallenge = await consumeChallenge(context, purpose);
+  if (!expectedChallenge) {
+    return error(400, 'challenge_expired', 'This request expired. Please try again.');
+  }
+
+  const match = await findCredential(response.id);
+  if (!match) {
+    // Lets the client signal the passkey provider to hide/remove this stale passkey.
+    return json(
+      {
+        error: 'This passkey is no longer registered with The DevTools Times. It may have been removed from your account.',
+        code: 'unknown_credential',
+        credentialId: response.id,
+      },
+      404,
+    );
+  }
+  const { user, passkey } = match;
+
+  // The user handle returned by a discoverable credential must match the owner.
+  if (response.response.userHandle && response.response.userHandle !== user.id) {
+    return error(400, 'verification_failed', 'Passkey could not be verified.');
+  }
+
+  if (purpose === 'reauth') {
+    const sessionUser = await getSessionUser(context);
+    if (!sessionUser) return error(401, 'not_signed_in', 'Please sign in first.');
+    if (sessionUser.id !== user.id) {
+      return error(403, 'wrong_account', 'That passkey belongs to a different account.');
+    }
+  }
+
+  const { rpID, origins } = getRelyingParty(context.url);
+  let verification;
+  try {
+    verification = await verifyAuthenticationResponse({
+      response,
+      expectedChallenge,
+      expectedOrigin: origins,
+      expectedRPID: rpID,
+      credential: {
+        id: passkey.id,
+        publicKey: isoBase64URL.toBuffer(passkey.publicKey),
+        counter: passkey.counter,
+        transports: passkey.transports,
+      },
+      requireUserVerification: false,
+    });
+  } catch (err) {
+    return error(400, 'verification_failed', `Passkey could not be verified: ${(err as Error).message}`);
+  }
+  if (!verification.verified) {
+    return error(400, 'verification_failed', 'Passkey could not be verified.');
+  }
+
+  await updatePasskey(user.id, passkey.id, {
+    counter: verification.authenticationInfo.newCounter,
+    backedUp: verification.authenticationInfo.credentialBackedUp,
+    lastUsedAt: Date.now(),
+  });
+
+  if (purpose === 'signin') {
+    await signIn(context, user);
+  } else {
+    context.session?.set('authenticatedAt', Date.now());
+  }
+
+  const updated = (await getUserById(user.id))!;
+  return json({ ok: true, ...accountPayload(context, updated) });
+};
