+import type { APIRoute } from 'astro';
+import { generateRegistrationOptions } from '@simplewebauthn/server';
+import { isoBase64URL } from '@simplewebauthn/server/helpers';
+import { getUserById } from '../../../../lib/auth/store';
+import {
+  RP_NAME,
+  error,
+  getRelyingParty,
+  getSessionUser,
+  isRecentlyAuthenticated,
+  issueChallenge,
+  json,
+  rejectCrossSite,
+} from '../../../../lib/auth/server';
+
+/** Step 1 of passkey creation: issue PublicKeyCredentialCreationOptions for the signed-in user. */
+export const POST: APIRoute = async (context) => {
+  const rejected = rejectCrossSite(context);
+  if (rejected) return rejected;
+
+  const sessionUser = await getSessionUser(context);
+  const user = sessionUser && (await getUserById(sessionUser.id));
+  if (!user) return error(401, 'not_signed_in', 'Please sign in first.');
+  if (!(await isRecentlyAuthenticated(context))) {
+    return error(403, 'reauth_required', 'Please confirm it’s you before adding a passkey.');
+  }
+
+  const { rpID } = getRelyingParty(context.url);
+  const options = await generateRegistrationOptions({
+    rpName: RP_NAME,
+    rpID,
+    userID: isoBase64URL.toBuffer(user.id),
+    userName: user.username,
+    userDisplayName: user.username,
+    attestationType: 'none',
+    // Prevent registering a second passkey on an authenticator that already has one for this account.
+    excludeCredentials: user.passkeys.map((p) => ({ id: p.id, transports: p.transports })),
+    authenticatorSelection: {
+      residentKey: 'required',
+      requireResidentKey: true,
+      userVerification: 'preferred',
+    },
+    // Ed25519, ES256, RS256
+    supportedAlgorithmIDs: [-8, -7, -257],
+  });
+
+  await issueChallenge(context, options.challenge, 'register');
+  return json(options);
+};
diff --git a/src/pages/api/auth/passkeys/register-verify.ts b/src/pages/api/auth/passkeys/register-verify.ts
new file mode 100644
index 0000000..25bcac6
--- /dev/null
