@@ -0,0 +1,79 @@
+import type { APIRoute } from 'astro';
+import { verifyRegistrationResponse } from '@simplewebauthn/server';
+import type { RegistrationResponseJSON } from '@simplewebauthn/server';
+import { isoBase64URL } from '@simplewebauthn/server/helpers';
+import { addPasskey, getUserById } from '../../../../lib/auth/store';
+import { providerNameForAaguid } from '../../../../lib/auth/aaguids';
+import {
+  accountPayload,
+  consumeChallenge,
+  error,
+  getRelyingParty,
+  getSessionUser,
+  json,
+  readJson,
+  rejectCrossSite,
+  toPublicPasskey,
+} from '../../../../lib/auth/server';
+
+/** Step 2 of passkey creation: verify the attestation and store the new credential. */
+export const POST: APIRoute = async (context) => {
+  const rejected = rejectCrossSite(context);
+  if (rejected) return rejected;
+
+  const sessionUser = await getSessionUser(context);
+  const user = sessionUser && (await getUserById(sessionUser.id));
+  if (!user) return error(401, 'not_signed_in', 'Please sign in first.');
+
+  const body = await readJson<{ response?: RegistrationResponseJSON }>(context.request);
+  if (!body?.response) return error(400, 'invalid_request', 'Missing registration response.');
+
+  // Challenges are consumed whether or not verification succeeds.
+  const expectedChallenge = await consumeChallenge(context, 'register');
+  if (!expectedChallenge) {
+    return error(400, 'challenge_expired', 'This request expired. Please try again.');
+  }
+
+  const { rpID, origins } = getRelyingParty(context.url);
+  let verification;
+  try {
+    verification = await verifyRegistrationResponse({
+      response: body.response,
+      expectedChallenge,
+      expectedOrigin: origins,
+      expectedRPID: rpID,
+      // Conditional (automatic) passkey creation is performed without user verification.
+      requireUserVerification: false,
+    });
+  } catch (err) {
+    return error(400, 'verification_failed', `Passkey could not be verified: ${(err as Error).message}`);
+  }
+  if (!verification.verified) {
+    return error(400, 'verification_failed', 'Passkey could not be verified.');
+  }
+
+  const info = verification.registrationInfo;
+  const provider =
+    info.passkeyProviderMetadata?.friendlyNames?.['en-US'] ?? providerNameForAaguid(info.aaguid);
+  const passkey = {
+    id: info.credential.id,
+    publicKey: isoBase64URL.fromBuffer(info.credential.publicKey),
+    counter: info.credential.counter,
+    transports: info.credential.transports ?? body.response.response.transports,
+    deviceType: info.credentialDeviceType,
+    backedUp: info.credentialBackedUp,
+    aaguid: info.aaguid,
+    name: provider ?? 'Passkey',
+    provider,
+    createdAt: Date.now(),
+  };
+
+  try {
+    await addPasskey(user.id, passkey);
+  } catch {
+    return error(409, 'already_registered', 'This passkey is already registered.');
+  }
+
+  const updated = (await getUserById(user.id))!;
+  return json({ passkey: toPublicPasskey(passkey), ...accountPayload(context, updated) });
+};
