+import type { APIRoute } from 'astro';
+import {
+  error,
+  getSessionUser,
+  json,
+  readJson,
+  rejectCrossSite,
+  upstreamAuth,
+} from '../../../../lib/auth/server';
+
+/** Reauthenticate the signed-in user with their password (fallback when no passkey is available). */
+export const POST: APIRoute = async (context) => {
+  const rejected = rejectCrossSite(context);
+  if (rejected) return rejected;
+
+  const sessionUser = await getSessionUser(context);
+  if (!sessionUser) return error(401, 'not_signed_in', 'Please sign in first.');
+
+  const body = await readJson<{ password?: string }>(context.request);
+  if (!body?.password) return error(400, 'invalid_request', 'Please enter your password.');
+
+  let upstream;
+  try {
+    upstream = await upstreamAuth('login', sessionUser.username, body.password);
+  } catch {
+    return error(502, 'upstream_unavailable', 'The sign-in service is unavailable.');
+  }
+  if (!upstream.ok) {
+    return error(401, 'invalid_password', `Incorrect password${upstream.data?.error ? ` (${upstream.data.error})` : ''}.`);
+  }
+
+  context.session?.set('authenticatedAt', Date.now());
+  return json({ ok: true });
+};
diff --git a/src/pages/api/auth/register.ts b/src/pages/api/auth/register.ts
