new file mode 100644
index 0000000..ec130a1
--- /dev/null
+++ b/drink-card.js
@@ -0,0 +1,90 @@
+// <drink-card>: server-rendered via Declarative Shadow DOM, hydrated in place.
+// The shadow tree (markup + styles) is already in the HTML, so this script only
+// attaches behavior. It never re-renders, so there is no flash or layout shift.
+
+const STORAGE_KEY = 'daily-grind:favorites';
+
+function readFavorites() {
+  try {
+    return new Set(JSON.parse(localStorage.getItem(STORAGE_KEY) ?? '[]'));
+  } catch {
+    return new Set();
+  }
+}
+
+function writeFavorites(favorites) {
+  try {
+    localStorage.setItem(STORAGE_KEY, JSON.stringify([...favorites]));
+  } catch {
+    // Storage unavailable (private mode, quota): keep in-memory state only.
+  }
+}
+
+class DrinkCard extends HTMLElement {
+  static observedAttributes = ['favorite'];
+
+  #button;
+
+  constructor() {
+    super();
+
+    // Reuse the server-rendered shadow root. If the browser didn't parse
+    // `shadowrootmode` (pre-DSD engines), attach it from the same inert template.
+    if (!this.shadowRoot) {
+      const template = this.querySelector(':scope > template[shadowrootmode]');
+      if (!template) return;
+      this.attachShadow({ mode: template.getAttribute('shadowrootmode') || 'open' });
+      this.shadowRoot.append(template.content);
+      template.remove();
+    }
+
+    // Hydrate: bind once to the existing button (constructor runs once per element,
+    // unlike connectedCallback, which re-runs when the element is moved).
+    this.#button = this.shadowRoot.querySelector('.fav');
+    this.#button?.addEventListener('click', () => {
+      this.favorite = !this.favorite;
+    });
+  }
+
+  connectedCallback() {
+    // Restore persisted state by flipping an attribute — not re-rendering.
+    if (this.drinkId && readFavorites().has(this.drinkId)) {
+      this.favorite = true;
+    }
+  }
+
+  get drinkId() {
+    return this.getAttribute('drink-id');
+  }
+
+  get favorite() {
+    return this.hasAttribute('favorite');
+  }
+
+  set favorite(value) {
+    this.toggleAttribute('favorite', Boolean(value));
+  }
+
+  attributeChangedCallback(name, oldValue, newValue) {
+    if (name !== 'favorite' || oldValue === newValue) return;
+    const isFavorite = newValue !== null;
+    this.#button?.setAttribute('aria-pressed', String(isFavorite));
+
+    if (this.drinkId) {
+      const favorites = readFavorites();
+      if (isFavorite) favorites.add(this.drinkId);
+      else favorites.delete(this.drinkId);
+      writeFavorites(favorites);
+    }
+
+    this.dispatchEvent(
+      new CustomEvent('favorite-change', {
+        bubbles: true,
+        composed: true,
+        detail: { drinkId: this.drinkId, favorite: isFavorite },
+      }),
+    );
+  }
+}
+
+customElements.define('drink-card', DrinkCard);
