+// The Daily Grind: client-side privacy safeguards.
+//
+// Principles (see PRIVACY.md):
+//   * Collect nothing: this script never sends data anywhere and loads no third parties.
+//   * Store nothing: the site keeps no data in Web Storage; anything not in the
+//     allowlist below is treated as stale and removed.
+//   * Never fingerprint: feature detection only, no UA sniffing or device probing.
+
+// Web Storage keys the site is permitted to keep. Intentionally empty: add a key
+// here only with a documented purpose and retention period in PRIVACY.md, and
+// never store tokens or PII (any script on the origin can read Web Storage).
+const ALLOWED_STORAGE_KEYS = new Set();
+
+// Campaign/click identifiers appended by ad networks and email tools. They
+// identify individual users or campaigns and are useless to us.
+const TRACKING_PARAM_PATTERNS = [
+  /^utm_/i,
+  /^(gclid|gclsrc|dclid|gbraid|wbraid|fbclid|msclkid|twclid|ttclid|li_fat_id|igshid|yclid)$/i,
+  /^(mc_cid|mc_eid|_hsenc|_hsmi|mkt_tok|oly_anon_id|oly_enc_id|vero_id|rb_clickid|s_cid)$/i,
+];
+
+const isTrackingParam = (name) => TRACKING_PARAM_PATTERNS.some((re) => re.test(name));
+
+/**
+ * Drops tracking identifiers from the address bar so they aren't kept in
+ * history or bookmarks, re-shared when a visitor copies the URL, or sent on
+ * later same-origin requests.
+ */
+function stripTrackingParams() {
+  const url = new URL(window.location.href);
+  const names = [...new Set(url.searchParams.keys())];
+  const tracked = names.filter(isTrackingParam);
+  if (tracked.length === 0) return;
+  for (const name of tracked) url.searchParams.delete(name);
+  history.replaceState(history.state, '', url);
+}
+
+/** Removes Web Storage entries that are not explicitly allowlisted. */
+function purgeStorage({ all = false } = {}) {
+  for (const area of ['localStorage', 'sessionStorage']) {
+    let storage;
+    try {
+      storage = window[area]; // Throws when storage is blocked by the user.
+    } catch {
+      continue;
+    }
+    if (!storage) continue;
+    for (const key of Object.keys(storage)) {
+      if (all || !ALLOWED_STORAGE_KEYS.has(key)) storage.removeItem(key);
+    }
+  }
+}
+
+/**
+ * Clears client-side state when the visitor logs out. The server also sends
+ * `Clear-Site-Data` on the /logout response; this covers hosts or browsers
+ * that don't honor that header.
+ */
+function wireLogout() {
+  for (const form of document.querySelectorAll('form[data-logout]')) {
+    form.addEventListener('submit', () => purgeStorage({ all: true }));
+  }
+}
+
+/** Shows the visitor that their Global Privacy Control signal was received. */
+function reflectPrivacySignals() {
+  // Feature-detected; absent in browsers without GPC support.
+  if (navigator.globalPrivacyControl !== true) return;
+  const status = document.getElementById('gpc-status');
+  if (status) {
+    status.textContent =
+      'Your browser sent a Global Privacy Control signal. We honor it, though we never sell or share your data anyway.';
+    status.hidden = false;
+  }
+}
+
+stripTrackingParams();
+purgeStorage();
+wireLogout();
+reflectPrivacySignals();
