index 0000000..e7f5c59
--- /dev/null
+++ b/js/privacy.js
@@ -0,0 +1,246 @@
+/*
+ * The Daily Grind - client-side privacy controls.
+ *
+ * Principles applied (privacy by design):
+ *  - Default deny: optional processing is off until the user opts in.
+ *  - Data minimization: nothing is written to the device until the user saves
+ *    a choice; what is stored is a few booleans + a timestamp, no identifiers.
+ *  - Storage limitation: saved choices expire and are purged automatically.
+ *  - Respect browser signals: Global Privacy Control / Do Not Track force an
+ *    opt-out that the UI cannot override.
+ *  - No third parties: this file makes no network requests and loads no
+ *    scripts. Optional features must call DailyGrindPrivacy.hasConsent()
+ *    before running.
+ */
+(function () {
+  'use strict';
+
+  var STORAGE_KEY = 'dg_privacy_choices';
+  var SCHEMA_VERSION = 1;
+  var RETENTION_MS = 180 * 24 * 60 * 60 * 1000; // re-ask after ~6 months
+  var OPTIONAL_CATEGORIES = ['analytics', 'personalization'];
+
+  // URL parameters used for cross-site tracking. Removed from the address bar
+  // so they are not saved in history/bookmarks or re-shared.
+  var TRACKING_PARAMS = [
+    'utm_source', 'utm_medium', 'utm_campaign', 'utm_term', 'utm_content', 'utm_id',
+    'gclid', 'gclsrc', 'dclid', 'gbraid', 'wbraid', 'fbclid', 'msclkid', 'twclid',
+    'ttclid', 'li_fat_id', 'mc_cid', 'mc_eid', 'igshid', '_hsenc', '_hsmi', 'yclid'
+  ];
+
+  // Cookie/storage names left behind by common third-party trackers. We don't
+  // use any of them; purge if an older version of the site set them.
+  var LEGACY_TRACKER_COOKIES = /^(_ga|_gid|_gat|_gcl_|_fbp|_fbc|_hj|_uet|_clck|_clsk|__utm|ajs_|mp_|amplitude_|IDE$|NID$)/;
+
+  // ---- Browser privacy signals ---------------------------------------------
+  function privacySignalEnabled() {
+    var nav = window.navigator || {};
+    return nav.globalPrivacyControl === true ||
+      nav.doNotTrack === '1' || nav.doNotTrack === 'yes' ||
+      window.doNotTrack === '1' || nav.msDoNotTrack === '1';
+  }
+
+  // ---- Storage (fails closed if storage is blocked) ------------------------
+  function safeStorage() {
+    try {
+      var s = window.localStorage;
+      var probe = '__dg_probe__';
+      s.setItem(probe, probe);
+      s.removeItem(probe);
+      return s;
+    } catch (e) {
+      return null;
+    }
+  }
+
+  function defaultChoices() {
+    var c = { necessary: true };
+    OPTIONAL_CATEGORIES.forEach(function (k) { c[k] = false; });
+    return c;
+  }
+
+  function readChoices() {
+    var store = safeStorage();
+    var choices = defaultChoices();
+    if (!store) return choices;
+    var raw = store.getItem(STORAGE_KEY);
+    if (!raw) return choices;
+    try {
+      var saved = JSON.parse(raw);
+      var expired = typeof saved.savedAt !== 'number' || Date.now() - saved.savedAt > RETENTION_MS;
+      if (saved.v !== SCHEMA_VERSION || expired) {
+        store.removeItem(STORAGE_KEY);
+        return choices;
+      }
+      OPTIONAL_CATEGORIES.forEach(function (k) { choices[k] = saved.choices[k] === true; });
+    } catch (e) {
+      store.removeItem(STORAGE_KEY);
+    }
+    return choices;
+  }
+
+  function writeChoices(choices) {
+    var store = safeStorage();
+    if (!store) return;
+    var minimal = {};
+    OPTIONAL_CATEGORIES.forEach(function (k) { minimal[k] = choices[k] === true; });
+    // Store only booleans and a coarse (day-precision) timestamp - no IDs.
+    var day = Math.floor(Date.now() / 86400000) * 86400000;
+    store.setItem(STORAGE_KEY, JSON.stringify({ v: SCHEMA_VERSION, savedAt: day, choices: minimal }));
+  }
+
+  function effectiveChoices() {
+    var choices = readChoices();
+    if (privacySignalEnabled()) {
+      OPTIONAL_CATEGORIES.forEach(function (k) { choices[k] = false; });
+    }
+    return choices;
+  }
+
+  // ---- Data hygiene --------------------------------------------------------
+  function stripTrackingParams() {
+    if (!window.URL || !window.history || !history.replaceState) return;
+    try {
+      var url = new URL(window.location.href);
+      var changed = false;
+      TRACKING_PARAMS.forEach(function (p) {
+        if (url.searchParams.has(p)) { url.searchParams.delete(p); changed = true; }
+      });
+      if (changed) history.replaceState(history.state, '', url.pathname + url.search + url.hash);
+    } catch (e) { /* ignore */ }
+  }
+
+  function expireCookie(name) {
+    var host = window.location.hostname;
+    var parts = host.split('.');
+    var domains = [''];
+    for (var i = 0; i < parts.length - 1; i++) {
+      domains.push('; domain=.' + parts.slice(i).join('.'));
+    }
+    domains.forEach(function (d) {
+      document.cookie = name + '=; expires=Thu, 01 Jan 1970 00:00:00 GMT; path=/' + d;
+    });
+  }
+
+  function purgeLegacyTrackers() {
+    document.cookie.split(';').forEach(function (pair) {
+      var name = pair.split('=')[0].trim();
+      if (name && LEGACY_TRACKER_COOKIES.test(name)) expireCookie(name);
+    });
+    var store = safeStorage();
+    if (!store) return;
+    for (var i = store.length - 1; i >= 0; i--) {
+      var key = store.key(i);
+      if (key && LEGACY_TRACKER_COOKIES.test(key)) store.removeItem(key);
+    }
+  }
+
+  // Remove data tied to optional categories the user has not consented to.
+  function enforceChoices(choices) {
+    var store = safeStorage();
+    if (store && !choices.personalization) store.removeItem('dg_favorites');
+  }
+
+  // Harden any off-site link (including ones added later by a CMS) so the
+  // destination gets no window.opener handle and no referrer.
+  function hardenExternalLinks(root) {
+    var links = (root || document).querySelectorAll('a[href]');
+    Array.prototype.forEach.call(links, function (a) {
+      if (a.origin && a.origin !== window.location.origin && /^https?:$/.test(a.protocol)) {
+        var rel = (a.getAttribute('rel') || '').split(/\s+/).filter(Boolean);
+        ['noopener', 'noreferrer'].forEach(function (r) { if (rel.indexOf(r) === -1) rel.push(r); });
+        a.setAttribute('rel', rel.join(' '));
+        a.setAttribute('referrerpolicy', 'no-referrer');
+      }
+    });
+  }
+
+  // Clear locally held personal data when signing out. The server should also
+  // answer POST /logout with `Clear-Site-Data: "cache", "cookies", "storage"`.
+  function wireLogout() {
+    var forms = document.querySelectorAll('form[data-logout]');
+    Array.prototype.forEach.call(forms, function (form) {
+      form.addEventListener('submit', function () {
+        try { window.sessionStorage.clear(); } catch (e) { /* ignore */ }
+        var store = safeStorage();
+        if (store) {
+          // Keep only the privacy choice itself (it's not personal data and
+          // re-asking after logout would be a dark pattern).
+          for (var i = store.length - 1; i >= 0; i--) {
+            var key = store.key(i);
+            if (key !== STORAGE_KEY) store.removeItem(key);
+          }
+        }
+      });
+    });
+  }
+
+  // ---- Preferences dialog --------------------------------------------------
+  function wireDialog() {
+    var dialog = document.getElementById('privacy-dialog');
+    var form = document.getElementById('privacy-form');
+    var triggers = document.querySelectorAll('[data-privacy-choices]');
+    if (!dialog || !form || typeof dialog.showModal !== 'function') return; // falls back to policy link
+
+    var signal = privacySignalEnabled();
+    var notice = document.getElementById('gpc-notice');
+    if (notice) notice.hidden = !signal;
+
+    function syncForm() {
+      var choices = effectiveChoices();
+      OPTIONAL_CATEGORIES.forEach(function (k) {
+        var input = form.elements[k];
+        if (!input) return;
+        input.checked = choices[k];
+        input.disabled = signal;
+      });
+    }
+
+    Array.prototype.forEach.call(triggers, function (t) {
+      t.addEventListener('click', function (e) {
+        e.preventDefault();
+        syncForm();
+        dialog.showModal();
+      });
+    });
+
+    dialog.addEventListener('close', function () {
+      var action = dialog.returnValue;
+      if (action !== 'save' && action !== 'reject') return; // Esc = no change, nothing stored
+      var choices = defaultChoices();
+      if (action === 'save' && !signal) {
+        OPTIONAL_CATEGORIES.forEach(function (k) {
+          choices[k] = !!(form.elements[k] && form.elements[k].checked);
+        });
+      }
+      writeChoices(choices);
+      enforceChoices(choices);
+      dialog.returnValue = '';
+      document.dispatchEvent(new CustomEvent('dg:privacy-change', { detail: effectiveChoices() }));
+    });
+  }
+
+  // ---- Public API (read-only) ----------------------------------------------
+  window.DailyGrindPrivacy = Object.freeze({
+    hasConsent: function (category) {
+      if (category === 'necessary') return true;
+      return effectiveChoices()[category] === true;
+    },
+    privacySignal: privacySignalEnabled
+  });
+
+  function init() {
+    stripTrackingParams();
+    purgeLegacyTrackers();
+    enforceChoices(effectiveChoices());
+    hardenExternalLinks();
+    wireLogout();
+    wireDialog();
+  }
+
+  if (document.readyState === 'loading') {
+    document.addEventListener('DOMContentLoaded', init);
+  } else {
+    init();
+  }
+})();
