+#!/usr/bin/env node
+/*
+ * Privacy & third-party audit for The Daily Grind static site.
+ * Zero dependencies. Exits non-zero if any check fails so it can gate CI.
+ *
+ *   node scripts/privacy-audit.mjs
+ *
+ * Checks:
+ *  1. Third-party requests: every absolute URL in site HTML/CSS/JS/SVG must be
+ *     on the reviewed allowlist (docs/PRIVACY-BY-DESIGN.md#third-party-inventory).
+ *  2. CSP compatibility: no inline <script>/<style>, style="" or on* handlers.
+ *  3. Required meta tags (CSP fallback, referrer policy).
+ *  4. Links opening new windows / off-site links carry rel="noopener noreferrer".
+ *  5. Forms: state-changing or sensitive forms must POST; logout must not be a GET link.
+ *  6. Required security/privacy headers are declared in _headers.
+ *  7. Images carry no EXIF metadata (GPS, device serials, etc.).
+ */
+import { readFileSync, readdirSync, statSync, existsSync } from 'node:fs';
+import { join, relative, extname, dirname } from 'node:path';
+import { fileURLToPath } from 'node:url';
+
+const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
+const SKIP_DIRS = new Set(['.git', 'node_modules', 'scripts', 'docs']);
+
+// Reviewed third-party hosts. Each entry needs a matching row in the
+// third-party inventory with purpose, data shared and legal basis.
+// Currently EMPTY: the site makes no third-party requests.
+const THIRD_PARTY_ALLOWLIST = new Set([]);
+
+// Non-request URLs that are safe to appear in source (XML namespaces).
+const NON_REQUEST_URLS = [/^http:\/\/www\.w3\.org\/\d{4}\/(svg|xlink)/];
+
+const REQUIRED_HEADERS = [
+  'Content-Security-Policy',
+  'Strict-Transport-Security',
+  'Referrer-Policy',
+  'X-Content-Type-Options',
+  'X-Frame-Options',
+  'Permissions-Policy',
+  'Cross-Origin-Opener-Policy',
+  'Cross-Origin-Resource-Policy',
+  'Clear-Site-Data',
+];
+const REQUIRED_CSP_DIRECTIVES = ["default-src 'none'", 'frame-ancestors', "base-uri 'none'", "object-src 'none'", "form-action 'self'"];
+const REQUIRED_PERMISSIONS_DENY = ['camera=()', 'microphone=()', 'geolocation=()', 'browsing-topics=()', 'interest-cohort=()'];
+
+const failures = [];
+const warnings = [];
+const fail = (file, msg) => failures.push(`${file}: ${msg}`);
+const warn = (file, msg) => warnings.push(`${file}: ${msg}`);
+
+function walk(dir, out = []) {
+  for (const name of readdirSync(dir)) {
+    if (SKIP_DIRS.has(name)) continue;
+    const full = join(dir, name);
+    if (statSync(full).isDirectory()) walk(full, out);
+    else out.push(full);
+  }
+  return out;
+}
+
+const files = walk(ROOT);
+const rel = (f) => relative(ROOT, f);
+const byExt = (...exts) => files.filter((f) => exts.includes(extname(f).toLowerCase()));
+
+// 1. Third-party URLs --------------------------------------------------------
+const URL_RE = /(?:https?:)?\/\/[a-z0-9.-]+\.[a-z]{2,}[^\s"'()<>]*/gi;
+const thirdParties = new Map();
+for (const f of byExt('.html', '.css', '.js', '.mjs', '.svg', '.json', '.webmanifest')) {
+  const src = readFileSync(f, 'utf8')
+    // ignore comments so documentation doesn't trip the check
+    .replace(/<!--[\s\S]*?-->/g, '')
+    .replace(/\/\*[\s\S]*?\*\//g, '');
+  for (const match of src.matchAll(URL_RE)) {
+    const url = match[0];
+    if (NON_REQUEST_URLS.some((re) => re.test(url))) continue;
+    let host;
+    try { host = new URL(url.startsWith('//') ? `https:${url}` : url).hostname; } catch { continue; }
+    if (!THIRD_PARTY_ALLOWLIST.has(host)) {
+      if (!thirdParties.has(host)) thirdParties.set(host, new Set());
+      thirdParties.get(host).add(rel(f));
+    }
+  }
+}
+for (const [host, where] of thirdParties) {
+  fail([...where].join(', '), `un-reviewed third-party host "${host}" (self-host it or add it to the allowlist + inventory)`);
+}
+
+// 2-5. HTML checks -----------------------------------------------------------
+for (const f of byExt('.html')) {
+  const name = rel(f);
+  const html = readFileSync(f, 'utf8').replace(/<!--[\s\S]*?-->/g, '');
+
+  for (const m of html.matchAll(/<script\b([^>]*)>([\s\S]*?)<\/script>/gi)) {
+    if (!/\bsrc\s*=/.test(m[1]) && m[2].trim()) fail(name, 'inline <script> (blocked by CSP; move to /js)');
+  }
+  if (/<style\b/i.test(html)) fail(name, 'inline <style> block (blocked by CSP; move to /css)');
+  if (/\sstyle\s*=/i.test(html)) fail(name, 'inline style="" attribute (blocked by CSP)');
+  if (/\son[a-z]+\s*=/i.test(html)) fail(name, 'inline event handler attribute (blocked by CSP)');
+  if (/javascript:/i.test(html)) fail(name, 'javascript: URL');
+
+  if (!/<meta[^>]+http-equiv=["']Content-Security-Policy["']/i.test(html)) fail(name, 'missing CSP <meta> fallback');
+  if (!/<meta[^>]+name=["']referrer["']/i.test(html)) fail(name, 'missing referrer-policy <meta>');
+
+  for (const m of html.matchAll(/<a\b[^>]*>/gi)) {
+    const tag = m[0];
+    const href = (tag.match(/href=["']([^"']+)["']/i) || [])[1] || '';
+    const offsite = /^(https?:)?\/\//i.test(href);
+    const blank = /target=["']_blank["']/i.test(tag);
+    if (offsite || blank) {
+      const relAttr = ((tag.match(/rel=["']([^"']*)["']/i) || [])[1] || '').split(/\s+/);
+      if (!relAttr.includes('noopener') || !relAttr.includes('noreferrer')) {
+        fail(name, `link ${href || tag} must have rel="noopener noreferrer"`);
+      }
+    }
+    if (/^\/logout\b/i.test(href)) fail(name, 'logout is a GET link; use a POST form');
+  }
+
+  for (const m of html.matchAll(/<form\b([^>]*)>([\s\S]*?)<\/form>/gi)) {
+    const attrs = m[1];
+    if (/method=["']dialog["']/i.test(attrs)) continue;
+    const method = ((attrs.match(/method=["'](\w+)["']/i) || [])[1] || 'get').toLowerCase();
+    const sensitive = /type=["'](password|email|tel)["']|name=["'](card|cc-|ssn|dob|phone|address)/i.test(m[2]);
+    if (method !== 'post' && (sensitive || /action=["'][^"']*(logout|login|account|order)/i.test(attrs))) {
+      fail(name, 'sensitive/state-changing form must use method="post" (GET leaks data into URLs, logs and Referer)');
+    }
+    for (const input of m[2].matchAll(/<input\b[^>]*>/gi)) {
+      if (/type=["']password["']/i.test(input[0]) && !/autocomplete=/i.test(input[0])) {
+        warn(name, 'password input without autocomplete attribute');
+      }
+    }
+  }
+}
+
+// 6. Headers -----------------------------------------------------------------
+const headersFile = join(ROOT, '_headers');
+if (!existsSync(headersFile)) {
+  fail('_headers', 'missing security headers file');
+} else {
+  const h = readFileSync(headersFile, 'utf8');
+  for (const name of REQUIRED_HEADERS) {
+    if (!new RegExp(`^\\s+${name}:`, 'mi').test(h)) fail('_headers', `missing ${name}`);
+  }
+  const csp = (h.match(/^\s+Content-Security-Policy:\s*(.+)$/mi) || [])[1] || '';
+  for (const d of REQUIRED_CSP_DIRECTIVES) if (!csp.includes(d)) fail('_headers', `CSP missing "${d}"`);
+  if (/'unsafe-inline'|'unsafe-eval'|\*/.test(csp)) fail('_headers', 'CSP must not use unsafe-inline, unsafe-eval or wildcards');
+  const pp = (h.match(/^\s+Permissions-Policy:\s*(.+)$/mi) || [])[1] || '';
+  for (const d of REQUIRED_PERMISSIONS_DENY) if (!pp.includes(d)) fail('_headers', `Permissions-Policy should deny ${d}`);
+}
+
+// 7. Image metadata ----------------------------------------------------------
+for (const f of byExt('.jpg', '.jpeg')) {
+  const buf = readFileSync(f);
+  if (buf.includes(Buffer.from('Exif\0\0'))) fail(rel(f), 'contains EXIF metadata; strip it before publishing');
+}
+
+// Report ---------------------------------------------------------------------
+console.log(`Privacy audit: scanned ${files.length} files`);
+console.log(`Third-party hosts referenced: ${thirdParties.size === 0 ? 'none' : [...thirdParties.keys()].join(', ')}`);
+for (const w of warnings) console.warn(`  WARN  ${w}`);
+for (const e of failures) console.error(`  FAIL  ${e}`);
+if (failures.length) {
+  console.error(`\n${failures.length} privacy check(s) failed.`);
+  process.exit(1);
+}
+console.log('All privacy checks passed.');

