@@ -0,0 +1,213 @@
+---
+/**
+ * Opt-in consent for optional third-party processing (click analytics).
+ *
+ * - Nothing optional loads until the visitor explicitly allows it.
+ * - Global Privacy Control (Sec-GPC / navigator.globalPrivacyControl) is
+ *   honored as a refusal, and the banner is not shown to those visitors.
+ * - "Allow" and "Decline" carry equal visual weight (no dark patterns).
+ * - The choice can be changed at any time via "Manage Privacy Preferences".
+ */
+const baseUrl = import.meta.env.BASE_URL;
+const privacyHref = `${baseUrl}legal/privacy`.replace(/\/{2,}/g, '/');
+---
+
+<section
+  id="privacy-banner"
+  aria-labelledby="privacy-banner-title"
+  hidden
+  class="fixed inset-x-0 bottom-0 z-[60] border-t border-gray-300 bg-white p-4 shadow-lg md:p-6"
+>
+  <div class="mx-auto flex max-w-4xl flex-col gap-4 md:flex-row md:items-end md:justify-between">
+    <div class="text-sm text-gray-700">
+      <h2 id="privacy-banner-title" class="mb-1 text-base font-bold text-gray-900">Your privacy choices</h2>
+      <p>
+        We'd like to measure which links and buttons readers use, to improve the site. If you allow it, our
+        analytics service (hosted on <code>cloudfunctions.net</code>) receives the <strong>label text of what
+        you click and a timestamp</strong> — no account details, and never on the sign-in or sign-up pages.
+        It's off unless you turn it on, and you can change your mind any time from the footer.
+        <a href={privacyHref} class="underline" data-skip-tracking>Privacy Policy</a>
+      </p>
+    </div>
+    <div class="flex shrink-0 gap-2">
+      <button
+        type="button"
+        data-privacy-choice="deny"
+        data-skip-tracking
+        class="rounded border border-gray-900 bg-white px-4 py-2 text-sm font-semibold text-gray-900 hover:bg-gray-100"
+      >
+        Decline
+      </button>
+      <button
+        type="button"
+        data-privacy-choice="allow"
+        data-skip-tracking
+        class="rounded border border-gray-900 bg-white px-4 py-2 text-sm font-semibold text-gray-900 hover:bg-gray-100"
+      >
+        Allow analytics
+      </button>
+    </div>
+  </div>
+</section>
+
+<dialog
+  id="privacy-dialog"
+  aria-labelledby="privacy-dialog-title"
+  class="m-auto w-[min(32rem,calc(100%-2rem))] rounded-lg p-6 shadow-xl backdrop:bg-black/40"
+>
+  <form method="dialog" class="space-y-4 text-sm text-gray-700">
+    <h2 id="privacy-dialog-title" class="text-lg font-bold text-gray-900">Privacy preferences</h2>
+
+    <div>
+      <p class="font-semibold text-gray-900">Strictly necessary</p>
+      <p>
+        A session cookie remembers your reading list once you bookmark an article. It is first-party, HttpOnly,
+        and never shared. Always on, because the feature cannot work without it.
+      </p>
+    </div>
+
+    <div>
+      <label class="flex items-start gap-2">
+        <input type="checkbox" id="privacy-analytics" name="analytics" class="mt-1" />
+        <span>
+          <span class="font-semibold text-gray-900">Click analytics (third party)</span><br />
+          Sends the label text of links and buttons you click, plus a timestamp, to our analytics service on
+          <code>cloudfunctions.net</code>. Never runs on sign-in or sign-up pages.
+        </span>
+      </label>
+      <p id="privacy-gpc-note" hidden class="mt-2 text-xs text-gray-500">
+        Your browser is sending a Global Privacy Control signal, so analytics stays off unless you turn it on here.
+      </p>
+    </div>
+
+    <p class="text-xs text-gray-500">
+      Your choice is stored only in this browser. See our <a href={privacyHref} class="underline" data-skip-tracking>Privacy Policy</a>.
+    </p>
+
+    <div class="flex justify-end gap-2">
+      <button value="cancel" data-skip-tracking class="rounded border border-gray-300 px-4 py-2 font-semibold hover:bg-gray-100">
+        Cancel
+      </button>
+      <button value="save" data-skip-tracking class="rounded bg-gray-900 px-4 py-2 font-semibold text-white hover:bg-gray-800">
+        Save preferences
+      </button>
+    </div>
+  </form>
+</dialog>
+
+<script>
+  import {
+    ANALYTICS_SCRIPT_SRC,
+    CONSENT_STORAGE_KEY,
+    CONSENT_VERSION,
+    isSensitivePath,
+  } from '../utils/privacy';
+
+  type Consent = { version: number; analytics: boolean };
+
+  const BASE = import.meta.env.BASE_URL;
+  let analyticsLoaded = false;
+
+  const gpcEnabled = () =>
+    (navigator as Navigator & { globalPrivacyControl?: boolean }).globalPrivacyControl === true;
+
+  function readConsent(): Consent | null {
+    try {
+      const parsed = JSON.parse(localStorage.getItem(CONSENT_STORAGE_KEY) ?? 'null');
+      return parsed && parsed.version === CONSENT_VERSION ? parsed : null;
+    } catch {
+      return null;
+    }
+  }
+
+  function writeConsent(analytics: boolean) {
+    try {
+      localStorage.setItem(CONSENT_STORAGE_KEY, JSON.stringify({ version: CONSENT_VERSION, analytics }));
+    } catch {
+      // Storage unavailable: the choice applies to this page view only.
+    }
+  }
+
+  function analyticsAllowed(): boolean {
+    const consent = readConsent();
+    return consent?.analytics === true;
+  }
+
+  function loadAnalytics() {
+    if (analyticsLoaded || !analyticsAllowed() || isSensitivePath(location.pathname, BASE)) return;
+    analyticsLoaded = true;
+    const script = document.createElement('script');
+    script.src = ANALYTICS_SCRIPT_SRC;
+    script.async = true;
+    // Don't reveal which article the reader is on to the third party.
+    script.referrerPolicy = 'no-referrer';
+    document.head.append(script);
+  }
+
+  function syncBanner() {
+    const banner = document.getElementById('privacy-banner');
+    if (!banner) return;
+    // GPC is an explicit refusal: don't ask again (no consent fatigue).
+    const needsDecision = readConsent() === null && !gpcEnabled() && !isSensitivePath(location.pathname, BASE);
+    banner.hidden = !needsDecision;
+  }
+
+  function applyChoice(allow: boolean) {
+    const wasLoaded = analyticsLoaded;
+    writeConsent(allow);
+    syncBanner();
+    if (allow) {
+      loadAnalytics();
+    } else if (wasLoaded) {
+      // A loaded third-party listener can't be detached; reload to stop it now.
