+    checkbox.checked = analyticsAllowed();
+    if (gpcNote) gpcNote.hidden = !gpcEnabled();
+    dialog.addEventListener(
+      'close',
+      () => {
+        if (dialog.returnValue === 'save') applyChoice(checkbox.checked);
+      },
+      { once: true },
