+    const { to } = event as Event & { to: URL };
+    if (analyticsLoaded && isSensitivePath(to.pathname, BASE)) {
+      event.preventDefault();
+      location.assign(to.href);
+    }
+  });
+
+  document.addEventListener('astro:page-load', () => {
+    syncBanner();
+    loadAnalytics();
+  });
+</script>
