new file mode 100644
index 0000000..c49ee80
--- /dev/null
+++ b/src/utils/privacy.ts
@@ -0,0 +1,33 @@
+/**
+ * Privacy configuration shared by the layout, middleware, and consent UI.
+ *
+ * Principles:
+ * - Privacy by default: nothing optional loads until the visitor opts in.
+ * - Data minimization: third-party code never runs on pages that handle
+ *   credentials, and only the data described in the consent text is sent.
+ * - Transparency: the consent UI says exactly what is collected and by whom.
+ */
+
+/** Third-party click analytics. Only loaded after explicit opt-in. */
+export const ANALYTICS_SCRIPT_SRC =
+  'https://us-central1-web-devrel-apps.cloudfunctions.net/times_cdn/lib/analytics-client.js';
+
+/** Pages handling credentials. No third-party scripts may run on them. */
+export const SENSITIVE_PAGES = ['signin', 'signup'];
+
+/** localStorage key for the visitor's choice (no personal data is stored). */
+export const CONSENT_STORAGE_KEY = 'dtt-privacy-consent';
+
+/** Bump when the consent text or the set of processors changes, to re-ask. */
+export const CONSENT_VERSION = 1;
+
+/** Normalizes a pathname and checks whether it is a sensitive page. */
+export function isSensitivePath(pathname: string, base: string): boolean {
+  const normalizedBase = ('/' + base).replace(/\/+/g, '/').replace(/\/$/, '');
+  let path = pathname.replace(/\/+/g, '/');
+  if (normalizedBase && path.startsWith(normalizedBase)) {
+    path = path.slice(normalizedBase.length);
+  }
+  path = path.replace(/^\/|\/$/g, '');
+  return SENSITIVE_PAGES.includes(path);
+}

