new file mode 100644
index 0000000..8c38b11
--- /dev/null
+++ b/src/components/ConsentManager.astro
@@ -0,0 +1,180 @@
+---
+/**
+ * Consent manager — privacy by design.
+ *
+ * - Optional third-party scripts (analytics) are OFF by default and are only
+ *   injected after an explicit, informed opt-in.
+ * - Browser privacy signals (Global Privacy Control / Do Not Track) are
+ *   honoured as a refusal; no banner is shown to those visitors.
+ * - The choice is stored locally (localStorage) only — it is never sent to a
+ *   server — and can be changed at any time via any element carrying the
+ *   `data-consent-open` attribute (e.g. "Manage Privacy Preferences" in the
+ *   footer).
+ * - Pages may pass `disableThirdParty` (e.g. sign-in / sign-up) so that
+ *   optional scripts are never loaded where credentials are entered.
+ */
+export interface Props {
+  disableThirdParty?: boolean;
+}
+
+const { disableThirdParty = false } = Astro.props;
+const baseUrl = import.meta.env.BASE_URL;
+---
+
+<div
+  id="consent-manager"
+  data-disable-third-party={disableThirdParty ? "true" : "false"}
+>
+  <div
+    id="consent-banner"
+    role="dialog"
+    aria-modal="false"
+    aria-labelledby="consent-title"
+    aria-describedby="consent-desc"
+    hidden
+    class="fixed inset-x-0 bottom-0 z-[100] border-t border-gray-300 bg-white p-4 shadow-lg md:p-6"
+  >
+    <div class="mx-auto flex max-w-4xl flex-col gap-4 md:flex-row md:items-end md:justify-between">
+      <div class="text-sm text-gray-700">
+        <h2 id="consent-title" class="mb-1 text-base font-bold text-gray-900">Your privacy choices</h2>
+        <p id="consent-desc">
+          We only use what is strictly necessary to run this site (e.g. your reading list session).
+          With your permission we would also like to use <strong>optional usage analytics</strong>:
+          when you click a link or button, its label and the time are sent to our analytics provider
+          to help us improve the site. No analytics are loaded unless you allow them, and you can
+          change your mind at any time via "Manage Privacy Preferences" in the footer.
+          <a href={`${baseUrl}legal/privacy`} class="underline">Read our Privacy Policy</a>.
+        </p>
+      </div>
+      <div class="flex shrink-0 gap-2">
+        <button
+          type="button"
+          data-consent-choice="denied"
+          data-skip-tracking
+          class="rounded-md border border-gray-900 px-4 py-2 text-sm font-medium text-gray-900 hover:bg-gray-100"
+        >
+          Decline
+        </button>
+        <button
+          type="button"
+          data-consent-choice="granted"
+          data-skip-tracking
+          class="rounded-md border border-gray-900 bg-gray-900 px-4 py-2 text-sm font-medium text-white hover:bg-gray-800"
+        >
+          Allow analytics
+        </button>
+      </div>
+    </div>
+  </div>
+</div>
+
+<script>
+  const STORAGE_KEY = "dt-privacy-consent";
+  const ANALYTICS_SRC =
+    "https://us-central1-web-devrel-apps.cloudfunctions.net/times_cdn/lib/analytics-client.js";
+
+  type Choice = "granted" | "denied";
+
+  function readChoice(): Choice | null {
+    try {
+      const raw = localStorage.getItem(STORAGE_KEY);
+      return raw === "granted" || raw === "denied" ? raw : null;
+    } catch {
+      return null;
+    }
+  }
+
+  function saveChoice(choice: Choice) {
+    try {
+      localStorage.setItem(STORAGE_KEY, choice);
+    } catch {
+      /* storage unavailable: the choice applies to this page view only */
+    }
+  }
+
+  function browserSignalsOptOut(): boolean {
+    const nav = navigator as Navigator & { globalPrivacyControl?: boolean };
+    return nav.globalPrivacyControl === true || navigator.doNotTrack === "1";
+  }
+
+  function thirdPartyDisabledOnPage(): boolean {
+    return (
+      document.getElementById("consent-manager")?.dataset.disableThirdParty === "true"
+    );
+  }
+
+  let analyticsLoaded = false;
+  function loadAnalytics() {
+    if (analyticsLoaded || thirdPartyDisabledOnPage()) return;
+    analyticsLoaded = true;
+    const script = document.createElement("script");
+    script.src = ANALYTICS_SRC;
+    script.async = true;
+    script.referrerPolicy = "no-referrer";
+    document.head.appendChild(script);
+  }
+
+  function banner(): HTMLElement | null {
+    return document.getElementById("consent-banner");
+  }
+
+  function showBanner() {
+    const el = banner();
+    if (!el) return;
+    el.hidden = false;
+    el.querySelector<HTMLButtonElement>('[data-consent-choice="denied"]')?.focus();
+  }
+
+  function hideBanner() {
+    const el = banner();
+    if (el) el.hidden = true;
+  }
+
+  function apply() {
+    if (analyticsLoaded && thirdPartyDisabledOnPage()) {
+      // A client-side navigation reached a page that must stay free of
+      // third-party code (e.g. sign-in). Do a full load to drop the script.
+      window.location.reload();
+      return;
+    }
+    const choice = readChoice();
+    if (choice === "granted" && !browserSignalsOptOut()) {
+      loadAnalytics();
+    }
+    if (choice === null && !browserSignalsOptOut()) {
+      showBanner();
+    } else {
+      hideBanner();
+    }
+  }
+
+  // Event delegation survives client-side (view transition) navigations.
+  document.addEventListener("click", (event) => {
+    const target = event.target as Element | null;
+    if (!target) return;
+
+    const choiceBtn = target.closest<HTMLElement>("[data-consent-choice]");
+    if (choiceBtn) {
+      const choice = choiceBtn.dataset.consentChoice as Choice;
+      const previous = readChoice();
+      saveChoice(choice);
+      hideBanner();
+      if (choice === "granted") {
+        loadAnalytics();
+      } else if (previous === "granted" && analyticsLoaded) {
+        // An already-executed script cannot be unloaded; reload so the
+        // withdrawal takes effect immediately.
+        window.location.reload();
+      }
+      return;
+    }
+
+    if (target.closest("[data-consent-open]")) {
+      event.preventDefault();
+      showBanner();
+    }
+  });
+
+  apply();
+  document.addEventListener("astro:after-swap", apply);
+</script>
