@@ -0,0 +1,53 @@
+/**
+ * Shared auth client helpers — built for data minimisation:
+ * only the username and password are sent, without cookies or a referrer,
+ * and raw server error codes are never shown to the user.
+ */
+const AUTH_API = 'https://us-central1-web-devrel-apps.cloudfunctions.net/times_cdn/api';
+
+// Login failures intentionally share one message so the form does not reveal
+// whether an account exists for a given username (the API's own message for
+// APP_ERR_2001 is "User not found").
+const LOGIN_FAILED = 'The username or password is incorrect.';
+
+export type AuthResult = { ok: true } | { ok: false; message: string };
+
+export async function postCredentials(
+  endpoint: 'login' | 'register',
+  username: string,
+  password: string,
+): Promise<AuthResult> {
+  const fallback =
+    endpoint === 'login'
+      ? 'Sign-in failed. Please check your details and try again.'
+      : 'Registration failed. Please check your details and try again.';
+
+  try {
+    const response = await fetch(`${AUTH_API}/${endpoint}`, {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json' },
+      body: JSON.stringify({ username: username.trim(), password }),
+      credentials: 'omit',
+      referrerPolicy: 'no-referrer',
+      cache: 'no-store',
+    });
+
+    if (response.ok) return { ok: true };
+
+    if (endpoint === 'login') return { ok: false, message: LOGIN_FAILED };
+
+    // For registration, the server's human-readable explanation (e.g. password
+    // requirements) is useful; the internal error code is not shown.
+    let serverMessage: unknown;
+    try {
+      serverMessage = (await response.json())?.message;
+    } catch {
+      /* non-JSON error body */
+    }
+    const message =
+      typeof serverMessage === 'string' && serverMessage.trim() ? serverMessage : fallback;
+    return { ok: false, message };
+  } catch {
+    return { ok: false, message: 'An unexpected error occurred. Please try again later.' };
+  }
+}

