+      function setBusy(state) {
+        busy = state;
+        submitBtn.disabled = state;
+        passkeyBtn.disabled = state;
+        submitBtn.textContent = state ? 'Signing in…' : 'Sign in';
+      }
+
+      /* ---------- auth state ---------- */
+
+      function renderAuthState() {
+        const signedIn = !!currentUser;
+        document.querySelectorAll('[data-auth="signed-in"]').forEach((el) => { el.hidden = !signedIn; });
+        document.querySelectorAll('[data-auth="signed-out"]').forEach((el) => { el.hidden = signedIn; });
+        $('nav-greeting').textContent = signedIn
+          ? `Hi, ${(currentUser.name || currentUser.email || '').split(' ')[0]}`
+          : '';
+      }
+
+      async function onSignedIn(user, { announce = true } = {}) {
+        currentUser = user || { name: '' };
+        localStorage.setItem(SILENT_OK_KEY, '1');
+        renderAuthState();
+        abortConditional();
+        if (dialog.open) dialog.close('signed-in');
+        if (announce) toast(`Welcome back${currentUser.name ? ', ' + currentUser.name.split(' ')[0] : ''}!`);
+
+        const dest = pendingHref;
+        pendingHref = null;
+        if (dest) window.location.assign(dest); // continue to what they clicked
+      }
+
+      async function loadSession() {
+        try {
+          const res = await fetch(API.session, { credentials: 'same-origin', headers: { Accept: 'application/json' } });
+          if (res.ok) {
+            const data = await res.json();
+            if (data && data.user) { currentUser = data.user; }
+          }
+        } catch { /* offline / no backend: treat as signed out */ }
+        renderAuthState();
+      }
+
+      /* ---------- saved passwords (Credential Management API) ---------- */
+
+      async function signInWithPasswordCredential(cred) {
+        const data = await postJSON(API.login, { email: cred.id, password: cred.password });
+        await onSignedIn(data.user || { name: cred.name, email: cred.id });
+      }
+
+      // mediation: 'silent' (no UI, auto sign-in) or 'optional' (browser account chooser if needed)
+      async function getSavedPassword(mediation) {
+        if (!supportsPasswordCred) return null;
+        try {
+          const cred = await navigator.credentials.get({ password: true, mediation });
+          return cred && cred.type === 'password' ? cred : null;
+        } catch {
+          return null;
+        }
+      }
+
+      async function storePassword(email, password, name) {
+        if (!supportsPasswordCred) return;
+        try {
+          const cred = new PasswordCredential({ id: email, password, name: name || email });
+          await navigator.credentials.store(cred);
+        } catch { /* user declined or unsupported */ }
+      }
+
+      /* ---------- passkeys (WebAuthn) ---------- */
+
+      async function fetchPasskeyOptions() {
+        const json = await postJSON(API.passkeyOptions);
+        return parseRequestOptions(json.publicKey || json);
+      }
+
+      async function verifyPasskey(cred) {
+        const data = await postJSON(API.passkeyVerify, assertionToJSON(cred));
+        await onSignedIn(data.user);
+      }
+
+      function abortConditional() {
+        if (conditionalAbort) {
+          conditionalAbort.abort();
+          conditionalAbort = null;
+        }
+      }
+
+      // Passkey autofill: passkeys appear in the email field's autofill dropdown.
+      async function startConditionalPasskey() {
+        if (!supportsWebAuthn || typeof PublicKeyCredential.isConditionalMediationAvailable !== 'function') return;
+        try {
+          if (!(await PublicKeyCredential.isConditionalMediationAvailable())) return;
+          abortConditional();
+          const controller = new AbortController();
+          conditionalAbort = controller;
+          const publicKey = await fetchPasskeyOptions();
+          if (controller.signal.aborted) return;
+          const cred = await navigator.credentials.get({
+            mediation: 'conditional',
+            publicKey,
+            signal: controller.signal,
+          });
+          if (conditionalAbort === controller) conditionalAbort = null;
+          if (cred) {
+            setBusy(true);
+            setError('');
+            try { await verifyPasskey(cred); }
+            catch (e) { setError(e.message); }
+            finally { setBusy(false); }
+          }
+        } catch (e) {
+          if (e && e.name !== 'AbortError') console.debug('Passkey autofill unavailable:', e);
+        }
+      }
+
+      // Explicit "Sign in with a passkey" button (modal browser prompt).
+      async function signInWithPasskey() {
+        if (busy) return;
+        abortConditional(); // only one WebAuthn request may be active at a time
+        setError('');
+        setBusy(true);
+        try {
+          const publicKey = await fetchPasskeyOptions();
+          const cred = await navigator.credentials.get({ publicKey, mediation: 'optional' });
+          if (cred) await verifyPasskey(cred);
+        } catch (e) {
+          if (e && e.name === 'NotAllowedError') {
+            setError('Passkey sign-in was cancelled. You can try again or use your password.');
+          } else {
+            setError((e && e.message) || 'Passkey sign-in failed.');
+          }
+        } finally {
+          setBusy(false);
+          if (dialog.open && !currentUser) startConditionalPasskey();
+        }
+      }
+
+      /* ---------- dialog ---------- */
+
+      function openDialog(label) {
+        setError('');
+        subtitle.textContent = label
+          ? `Sign in to continue to ${label}.`
+          : 'Sign in to earn rewards and order ahead.';
+        if (!dialog.open) dialog.showModal();
+        emailInput.focus();
+        startConditionalPasskey();
+      }
+
+      // Entry point when a signed-out user wants a protected area.
+      async function requestSignIn(href, label) {
+        pendingHref = href || null;
+        // Offer saved passwords first via the browser's native account chooser.
+        // Returns null immediately if there are none or the user dismisses it.
+        const saved = await getSavedPassword('optional');
+        if (saved) {
+          try { await signInWithPasswordCredential(saved); return; }
+          catch (e) { openDialog(label); emailInput.value = saved.id; setError(e.message); return; }
+        }
+        openDialog(label);
+      }
+
+      dialog.addEventListener('close', () => {
+        abortConditional();
+        if (dialog.returnValue !== 'signed-in') pendingHref = null;
+        dialog.returnValue = '';
+        passwordInput.value = '';
+        setBusy(false);
+      });
+
+      // Click on backdrop closes the dialog.
+      dialog.addEventListener('click', (e) => {
+        if (e.target === dialog) dialog.close('dismissed');
+      });
+
+      $('signin-close').addEventListener('click', () => dialog.close('dismissed'));
+      passkeyBtn.addEventListener('click', signInWithPasskey);
+
+      form.addEventListener('submit', async (e) => {
+        e.preventDefault();
+        if (busy) return;
+        const email = emailInput.value.trim();
+        const password = passwordInput.value;
+        if (!email || !emailInput.checkValidity()) { setError('Please enter a valid email address.'); emailInput.focus(); return; }
+        if (!password) { setError('Please enter your password.'); passwordInput.focus(); return; }
+
+        setError('');
+        setBusy(true);
+        try {
+          const data = await postJSON(API.login, { email, password });
+          await storePassword(email, password, data.user && data.user.name);
+          await onSignedIn(data.user || { email });
+        } catch (err) {
+          setError(err.status === 401 ? 'That email and password don’t match our records.' : err.message);
+          passwordInput.select();
+        } finally {
+          setBusy(false);
+        }
+      });
+
+      /* ---------- link interception ---------- */
+
+      document.addEventListener('click', (e) => {
+        if (e.defaultPrevented || e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
+        const link = e.target.closest('a');
+        if (!link) return;
+
+        if (link.id === 'signin-link') {
+          e.preventDefault();
+          requestSignIn(null, null);
+          return;
+        }
+
+        if (link.id === 'logout-link') {
+          e.preventDefault();
+          // Stop the browser from silently re-signing the user in on the next visit.
+          localStorage.removeItem(SILENT_OK_KEY);
+          const done = () => window.location.assign(link.href);
+          Promise.allSettled([
+            navigator.credentials && navigator.credentials.preventSilentAccess
+              ? navigator.credentials.preventSilentAccess() : null,
+            postJSON(API.logout),
+          ]).then(() => {
+            currentUser = null;
+            renderAuthState();
+            done();
+          });
+          return;
+        }
+
+        if (link.hasAttribute('data-requires-auth') && !currentUser) {
+          e.preventDefault();
+          requestSignIn(link.href, link.dataset.authLabel || link.textContent.trim());
+        }
+      });
+
+      /* ---------- boot ---------- */
+
+      (async () => {
+        if (supportsWebAuthn) {
+          passkeyBtn.hidden = false;
+          $('passkey-divider').hidden = false;
+        }
+
+        await loadSession();
+
+        // Returning customers who previously signed in get signed back in automatically
+        // with their saved password, without any prompt (respects preventSilentAccess on logout).
+        if (!currentUser && localStorage.getItem(SILENT_OK_KEY) === '1') {
+          const saved = await getSavedPassword('silent');
+          if (saved) {
+            try { await signInWithPasswordCredential(saved); }
+            catch { /* stale credential; user can sign in manually */ }
+          }
+        }
+      })();
+    })();
+  </script>
+
 </body>

