new file mode 100644
index 0000000..0cf969f
--- /dev/null
+++ b/public/app.js
@@ -0,0 +1,64 @@
+// Newsletter signup. Posts only to our own origin; the server's
+// Connection-Allowlist / CSP headers block any other destination.
+const form = document.getElementById('newsletter-form');
+
+if (form) {
+  const email = form.elements.namedItem('email');
+  const status = document.getElementById('newsletter-status');
+  const button = form.querySelector('button[type="submit"]');
+
+  const setStatus = (state, message) => {
+    status.dataset.state = state;
+    status.textContent = message;
+  };
+
+  const clearError = () => {
+    email.removeAttribute('aria-invalid');
+    if (status.dataset.state === 'error') setStatus('', '');
+  };
+
+  email.addEventListener('input', clearError);
+
+  form.addEventListener('submit', async (event) => {
+    event.preventDefault();
+
+    if (!email.checkValidity()) {
+      email.setAttribute('aria-invalid', 'true');
+      setStatus('error', email.validity.valueMissing
+        ? 'Please enter your email address.'
+        : 'Please enter a valid email address, like name@example.com.');
+      email.focus();
+      return;
+    }
+
+    button.disabled = true;
+    setStatus('pending', 'Signing you up…');
+
+    try {
+      const response = await fetch(form.action, {
+        method: 'POST',
+        headers: { Accept: 'application/json' },
+        body: new URLSearchParams(new FormData(form)),
+      });
+      const result = await response.json().catch(() => ({}));
+
+      if (!response.ok) {
+        if (response.status === 400) email.setAttribute('aria-invalid', 'true');
+        setStatus('error', result.message ||
+          'Sorry, we couldn’t sign you up right now. Please try again in a few minutes.');
+        return;
+      }
+
+      form.reset();
+      setStatus('success', result.message || 'Thanks! You’re on the list.');
+    } catch {
+      // Network failure, offline, or the request was blocked by the
+      // outbound connection policy (fetch rejects with a TypeError).
+      setStatus('error',
+        'We couldn’t reach our server, so your signup didn’t go through. ' +
+        'Please check your connection and try again.');
+    } finally {
+      button.disabled = false;
+    }
+  });
+}
