+++ b/server.js
@@ -0,0 +1,249 @@
+// The Daily Grind homepage server.
+// Serves the static homepage, accepts newsletter signups, and sets the response
+// headers that restrict where the page is allowed to send data.
+import { createServer } from 'node:http';
+import { readFile, appendFile, mkdir } from 'node:fs/promises';
+import { extname, join, normalize, sep } from 'node:path';
+import { fileURLToPath } from 'node:url';
+
+const ROOT = fileURLToPath(new URL('.', import.meta.url));
+const PUBLIC_DIR = join(ROOT, 'public');
+const DATA_DIR = join(ROOT, 'data');
+const SUBSCRIBERS_FILE = join(DATA_DIR, 'subscribers.jsonl');
+const PORT = Number(process.env.PORT) || 11222;
+const MAX_BODY_BYTES = 4 * 1024;
+
+// The only external origin the page may contact. Our own origin is covered
+// by `response-origin` (Connection-Allowlist) and `'self'` (CSP).
+const PHOTO_HOST = 'https://images.unsplash.com';
+const REPORT_ENDPOINT = 'conn-reports';
+const REPORT_PATH = '/api/security-reports';
+
+// Connection-Allowlist (Chrome/Edge 152+) is a single network-layer allowlist for
+// every outbound connection: fetch, subresources, beacons, navigations, resource
+// hints, WebSocket, WebRTC. Redirects and WebRTC stay blocked (the defaults).
+const CONNECTION_ALLOWLIST = `(response-origin "${PHOTO_HOST}"); report-to=${REPORT_ENDPOINT}`;
+
+// CSP fallback for browsers without Connection-Allowlist (Firefox, Safari).
+// No 'unsafe-inline' anywhere, so injected inline scripts/handlers can't run.
+// form-action and worker-src are listed explicitly because default-src
+// doesn't cover form-action, and blob: workers could bypass restrictions.
+const CONTENT_SECURITY_POLICY = [
+  "default-src 'none'",
+  "script-src 'self'",
+  "style-src 'self'",
+  `img-src 'self' ${PHOTO_HOST}`,
+  "connect-src 'self'",
+  "font-src 'self'",
+  "manifest-src 'self'",
+  "form-action 'self'",
+  "worker-src 'self'",
+  "frame-src 'none'",
+  "object-src 'none'",
+  "base-uri 'none'",
+  "frame-ancestors 'none'",
+  `report-uri ${REPORT_PATH}`,
+  `report-to ${REPORT_ENDPOINT}`,
+].join('; ');
+
+// Destinations where browsers honor Connection-Allowlist.
+const ALLOWLIST_DESTS = new Set(['document', 'iframe', 'worker', 'sharedworker', 'serviceworker']);
+
+const MIME_TYPES = {
+  '.html': 'text/html; charset=utf-8',
+  '.css': 'text/css; charset=utf-8',
+  '.js': 'text/javascript; charset=utf-8',
+  '.svg': 'image/svg+xml',
+  '.png': 'image/png',
+  '.jpg': 'image/jpeg',
+  '.ico': 'image/x-icon',
+};
+
+function setSecurityHeaders(req, res) {
+  res.setHeader('Vary', 'Sec-Fetch-Dest');
+  res.setHeader('X-Content-Type-Options', 'nosniff');
+  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
+  res.setHeader('Cross-Origin-Opener-Policy', 'same-origin');
+
+  const dest = String(req.headers['sec-fetch-dest'] || 'document').toLowerCase();
+  if (!ALLOWLIST_DESTS.has(dest)) return;
+
+  res.setHeader('Reporting-Endpoints', `${REPORT_ENDPOINT}="${REPORT_PATH}"`);
+  res.setHeader('Connection-Allowlist', CONNECTION_ALLOWLIST);
+  res.setHeader('Content-Security-Policy', CONTENT_SECURITY_POLICY);
+}
+
+function send(res, status, body, contentType) {
+  res.writeHead(status, {
+    'Content-Type': contentType,
+    'Content-Length': Buffer.byteLength(body),
+  });
+  res.end(body);
+}
+
+function escapeHtml(text) {
+  return String(text).replace(/[&<>"']/g, (c) => (
+    { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]
+  ));
+}
+
+// Responds to newsletter submissions. JS clients get JSON; the no-JS form post
+// gets a small HTML page (rendered directly, never redirected, because
+// Connection-Allowlist blocks redirects by default).
+function respondNewsletter(req, res, status, message) {
+  const wantsJson = String(req.headers.accept || '').includes('application/json');
+  if (wantsJson) {
+    send(res, status, JSON.stringify({ ok: status < 400, message }), 'application/json; charset=utf-8');
+    return;
+  }
+  const html = `<!DOCTYPE html>
+<html lang="en">
+<head>
+  <meta charset="UTF-8">
+  <meta name="viewport" content="width=device-width, initial-scale=1.0">
+  <title>Newsletter | The Daily Grind</title>
+  <link rel="stylesheet" href="/styles.css">
+</head>
+<body>
+  <main class="container">
+    <section class="newsletter">
+      <h2>${status < 400 ? 'You’re subscribed' : 'Signup didn’t go through'}</h2>
+      <p class="form-status" data-state="${status < 400 ? 'success' : 'error'}">${escapeHtml(message)}</p>
+      <a class="btn" href="/">Back to the homepage</a>
+    </section>
+  </main>
+</body>
+</html>`;
+  send(res, status, html, 'text/html; charset=utf-8');
+}
+
+function readBody(req) {
+  return new Promise((resolve, reject) => {
+    let size = 0;
+    const chunks = [];
+    req.on('data', (chunk) => {
+      size += chunk.length;
+      if (size > MAX_BODY_BYTES) {
+        reject(Object.assign(new Error('Payload too large'), { status: 413 }));
+        req.destroy();
+        return;
+      }
+      chunks.push(chunk);
+    });
+    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
+    req.on('error', reject);
+  });
+}
+
+const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+
+async function handleNewsletter(req, res) {
+  let body;
+  try {
+    body = await readBody(req);
+  } catch (err) {
+    respondNewsletter(req, res, err.status || 400, 'That request was too large. Please try again.');
+    return;
+  }
+
+  const params = new URLSearchParams(body);
+  // Honeypot filled in: pretend success so bots don't retry.
+  if (params.get('website')) {
+    respondNewsletter(req, res, 200, 'Thanks! You’re on the list.');
+    return;
+  }
+
+  const email = (params.get('email') || '').trim().toLowerCase();
+  if (!email || email.length > 254 || !EMAIL_PATTERN.test(email)) {
+    respondNewsletter(req, res, 400, 'Please enter a valid email address, like name@example.com.');
+    return;
+  }
+
+  try {
+    await mkdir(DATA_DIR, { recursive: true });
+    await appendFile(SUBSCRIBERS_FILE, `${JSON.stringify({ email, subscribedAt: new Date().toISOString() })}\n`);
+  } catch (err) {
+    console.error('Failed to save subscriber:', err);
+    respondNewsletter(req, res, 500, 'Sorry, we couldn’t sign you up right now. Please try again in a few minutes.');
+    return;
+  }
+
+  respondNewsletter(req, res, 201, 'Thanks! You’re on the list. Watch your inbox for the next issue.');
+}
+
+// Receives Connection-Allowlist and CSP violation reports (Reporting API and
+// legacy report-uri formats) so blocked exfiltration attempts are visible.
+async function handleSecurityReport(req, res) {
+  try {
+    const body = await readBody(req);
+    console.warn('[security-report]', body);
+  } catch {
+    // Ignore oversized/malformed reports.
+  }
+  res.writeHead(204);
+  res.end();
+}
+
+async function serveStatic(req, res, pathname) {
+  const relative = pathname === '/' ? 'index.html' : decodeURIComponent(pathname).replace(/^\/+/, '');
+  const filePath = normalize(join(PUBLIC_DIR, relative));
+  if (!filePath.startsWith(PUBLIC_DIR + sep)) {
+    send(res, 403, 'Forbidden', 'text/plain; charset=utf-8');
+    return;
+  }
+
+  try {
+    const data = await readFile(filePath);
+    res.writeHead(200, {
+      'Content-Type': MIME_TYPES[extname(filePath)] || 'application/octet-stream',
+      'Content-Length': data.length,
+      'Cache-Control': 'no-cache',
+    });
+    res.end(req.method === 'HEAD' ? undefined : data);
+  } catch {
+    send(res, 404, 'Not found', 'text/plain; charset=utf-8');
+  }
+}
+
+const server = createServer(async (req, res) => {
+  setSecurityHeaders(req, res);
+  let pathname;
+  try {
+    pathname = new URL(req.url, 'http://localhost').pathname;
+  } catch {
+    send(res, 400, 'Bad request', 'text/plain; charset=utf-8');
+    return;
+  }
+
+  try {
+    if (pathname === '/api/newsletter') {
+      if (req.method !== 'POST') {
+        res.setHeader('Allow', 'POST');
+        send(res, 405, 'Method not allowed', 'text/plain; charset=utf-8');
+        return;
+      }
+      await handleNewsletter(req, res);
+      return;
+    }
+
+    if (pathname === REPORT_PATH && req.method === 'POST') {
+      await handleSecurityReport(req, res);
+      return;
+    }
+
+    if (req.method !== 'GET' && req.method !== 'HEAD') {
+      res.setHeader('Allow', 'GET, HEAD');
+      send(res, 405, 'Method not allowed', 'text/plain; charset=utf-8');
+      return;
+    }
+
+    await serveStatic(req, res, pathname);
+  } catch (err) {
+    console.error(err);
+    if (!res.headersSent) send(res, 500, 'Internal server error', 'text/plain; charset=utf-8');
+  }
+});
+
+server.listen(PORT, () => {
+  console.log(`The Daily Grind is serving on http://localhost:${PORT}`);
+});

