+'use strict';
+
+(function () {
+  var notice = document.getElementById('network-notice');
+  var noticeTimer;
+
+  function showNotice(message) {
+    if (!notice) return;
+    notice.textContent = message;
+    notice.hidden = false;
+    clearTimeout(noticeTimer);
+    noticeTimer = setTimeout(function () { notice.hidden = true; }, 8000);
+  }
+
+  // The server's Content-Security-Policy only lets this page talk to our own
+  // origin and the Unsplash image host. If anything tries to reach elsewhere,
+  // the browser blocks it and fires this event, so let the customer know.
+  document.addEventListener('securitypolicyviolation', function (event) {
+    var directive = event.effectiveDirective || event.violatedDirective || '';
+    if (/^(connect|img|form-action|default|font|media|script|style|frame|worker)/.test(directive)) {
+      showNotice("Sorry, part of this page couldn't load because the request was blocked for your security.");
+    }
+  });
+
+  var form = document.getElementById('newsletter-form');
+  var status = document.getElementById('newsletter-status');
+  if (!form || !status) return;
+
+  var input = form.elements.namedItem('email');
+  var button = form.querySelector('button[type="submit"]');
+
+  function setStatus(message, kind) {
+    status.textContent = message;
+    status.className = 'form-status ' + kind;
+    status.hidden = false;
+  }
+
+  // Message for customers who were redirected back after a no-JS submission.
+  var params = new URLSearchParams(window.location.search);
+  if (params.get('newsletter') === 'subscribed') {
+    setStatus("Thanks! You're on the list.", 'success');
+  } else if (params.get('newsletter') === 'error') {
+    setStatus("Sorry, we couldn't sign you up. Please check your email and try again.", 'error');
+  }
+
+  form.addEventListener('submit', function (event) {
+    event.preventDefault();
+
+    var email = (input.value || '').trim();
+    if (!email || !input.checkValidity()) {
+      setStatus('Please enter a valid email address.', 'error');
+      input.focus();
+      return;
+    }
+
+    button.disabled = true;
+    setStatus('Signing you up…', 'success');
+
+    var controller = typeof AbortController === 'function' ? new AbortController() : null;
+    var timeout = setTimeout(function () { if (controller) controller.abort(); }, 10000);
+
+    // Relative URL: always goes to our own server.
+    fetch('/api/newsletter', {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
+      body: JSON.stringify({ email: email }),
+      credentials: 'same-origin',
+      signal: controller ? controller.signal : undefined
+    })
+      .then(function (response) {
+        return response.json().catch(function () { return {}; }).then(function (data) {
+          if (!response.ok) {
+            throw new Error(data.error || 'Request failed');
+          }
+          setStatus(data.message || "Thanks! You're on the list.", 'success');
+          form.reset();
+        });
+      })
+      .catch(function (err) {
+        var message;
+        if (err && err.name === 'AbortError') {
+          message = 'The request timed out. Please check your connection and try again.';
+        } else if (err instanceof TypeError) {
+          // Network failure, server unreachable, or blocked by the browser.
+          message = "We couldn't reach our server. Please check your connection and try again.";
+        } else {
+          message = (err && err.message) || 'Something went wrong. Please try again.';
+        }
+        setStatus(message, 'error');
+      })
+      .then(function () {
+        clearTimeout(timeout);
+        button.disabled = false;
+      });
+  });
+})();
