@@ -0,0 +1,205 @@
+'use strict';
+
+const http = require('node:http');
+const fs = require('node:fs');
+const path = require('node:path');
+
+const PORT = Number(process.env.PORT) || 11222;
+const HOST = process.env.HOST || '0.0.0.0';
+const PUBLIC_DIR = path.join(__dirname, 'public');
+const DATA_DIR = path.join(__dirname, 'data');
+const SUBSCRIBERS_FILE = path.join(DATA_DIR, 'subscribers.jsonl');
+const MAX_BODY_BYTES = 4 * 1024;
+
+// Only our own origin ('self') and the Unsplash photo CDN are reachable.
+// Every fetch/XHR/beacon/WebSocket is limited to 'self' via connect-src, and
+// form submissions are limited via form-action. No inline scripts or styles
+// are allowed, so an injected <script> or event handler won't run.
+const CSP = [
+  "default-src 'none'",
+  "script-src 'self'",
+  "style-src 'self'",
+  "img-src 'self' https://images.unsplash.com",
+  "connect-src 'self'",
+  "font-src 'self'",
+  "manifest-src 'self'",
+  "form-action 'self'",
+  "base-uri 'none'",
+  "frame-src 'none'",
+  "frame-ancestors 'none'",
+  "object-src 'none'",
+  "worker-src 'none'",
+  "media-src 'none'",
+].join('; ');
+
+const SECURITY_HEADERS = {
+  'Content-Security-Policy': CSP,
+  'Referrer-Policy': 'no-referrer',
+  'X-Content-Type-Options': 'nosniff',
+  'X-Frame-Options': 'DENY',
+  'Cross-Origin-Opener-Policy': 'same-origin',
+  'Cross-Origin-Resource-Policy': 'same-origin',
+  'Permissions-Policy': 'camera=(), microphone=(), geolocation=(), payment=(), usb=()',
+};
+
+// Explicit allowlist of static files; nothing else on disk is served.
+const STATIC_FILES = {
+  '/': { file: 'index.html', type: 'text/html; charset=utf-8' },
+  '/index.html': { file: 'index.html', type: 'text/html; charset=utf-8' },
+  '/styles.css': { file: 'styles.css', type: 'text/css; charset=utf-8' },
+  '/app.js': { file: 'app.js', type: 'text/javascript; charset=utf-8' },
+};
+
+const EMAIL_RE = /^[^\s@<>()[\]\\,;:"]+@[^\s@<>()[\]\\,;:"]+\.[^\s@<>()[\]\\,;:"]{2,}$/;
+
+function send(res, status, body, headers = {}) {
+  res.writeHead(status, { ...SECURITY_HEADERS, ...headers });
+  res.end(body);
+}
+
+function sendJson(res, status, data) {
+  send(res, status, JSON.stringify(data), {
+    'Content-Type': 'application/json; charset=utf-8',
+    'Cache-Control': 'no-store',
+  });
+}
+
+function serveStatic(req, res, entry) {
+  fs.readFile(path.join(PUBLIC_DIR, entry.file), (err, data) => {
+    if (err) {
+      send(res, 500, 'Internal Server Error', { 'Content-Type': 'text/plain; charset=utf-8' });
+      return;
+    }
+    send(res, 200, req.method === 'HEAD' ? undefined : data, {
+      'Content-Type': entry.type,
+      'Content-Length': data.length,
+      'Cache-Control': entry.file === 'index.html' ? 'no-cache' : 'public, max-age=3600',
+    });
+  });
+}
+
+function readBody(req) {
+  return new Promise((resolve, reject) => {
+    let size = 0;
+    const chunks = [];
+    req.on('data', (chunk) => {
+      size += chunk.length;
+      if (size > MAX_BODY_BYTES) {
+        reject(Object.assign(new Error('Payload too large'), { status: 413 }));
+        req.destroy();
+        return;
+      }
+      chunks.push(chunk);
+    });
+    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
+    req.on('error', reject);
+  });
+}
+
+function isSameOrigin(req) {
+  // Reject cross-site form posts / fetches (CSRF). Browsers send Origin on POST;
+  // when it's absent (non-browser clients), fall back to Sec-Fetch-Site.
+  const origin = req.headers.origin;
+  if (origin) {
+    try {
+      return new URL(origin).host === req.headers.host;
+    } catch {
+      return false;
+    }
+  }
+  const site = req.headers['sec-fetch-site'];
+  return !site || site === 'same-origin' || site === 'none';
+}
+
+async function saveSubscriber(email) {
+  await fs.promises.mkdir(DATA_DIR, { recursive: true });
+  const existing = await fs.promises.readFile(SUBSCRIBERS_FILE, 'utf8').catch(() => '');
+  const already = existing
+    .split('\n')
+    .filter(Boolean)
+    .some((line) => {
+      try {
+        return JSON.parse(line).email === email;
+      } catch {
+        return false;
+      }
+    });
+  if (already) return false;
+  await fs.promises.appendFile(
+    SUBSCRIBERS_FILE,
+    JSON.stringify({ email, subscribedAt: new Date().toISOString() }) + '\n',
+    { mode: 0o600 },
+  );
+  return true;
+}
+
+async function handleNewsletter(req, res) {
+  const contentType = (req.headers['content-type'] || '').split(';')[0].trim().toLowerCase();
+  const isJson = contentType === 'application/json';
+  const isForm = contentType === 'application/x-www-form-urlencoded';
+
+  // Non-JS fallback: a plain form post gets redirected back to the homepage.
+  const respond = (status, ok, message) => {
+    if (isForm) {
+      send(res, 303, undefined, { Location: `/?newsletter=${ok ? 'subscribed' : 'error'}#newsletter-title` });
+    } else {
+      sendJson(res, status, ok ? { ok, message } : { ok, error: message });
+    }
+  };
+
+  if (!isSameOrigin(req)) return respond(403, false, 'Request not allowed.');
+  if (!isJson && !isForm) return respond(415, false, 'Unsupported request format.');
+
+  let email;
+  try {
+    const raw = await readBody(req);
+    email = isJson ? JSON.parse(raw).email : new URLSearchParams(raw).get('email');
+  } catch (err) {
+    return respond(err.status || 400, false, err.status === 413 ? 'Request too large.' : 'Invalid request.');
+  }
+
+  email = typeof email === 'string' ? email.trim().toLowerCase() : '';
+  if (!email || email.length > 254 || !EMAIL_RE.test(email)) {
+    return respond(400, false, 'Please enter a valid email address.');
+  }
+
+  try {
+    const added = await saveSubscriber(email);
+    // Same response either way so the form can't be used to check who's subscribed.
+    respond(added ? 201 : 200, true, "Thanks! You're on the list.");
+  } catch (err) {
+    console.error('Failed to save subscriber:', err);
+    respond(500, false, "Sorry, we couldn't sign you up right now. Please try again later.");
+  }
+}
+
+const server = http.createServer((req, res) => {
+  let pathname;
+  try {
+    pathname = new URL(req.url, 'http://localhost').pathname;
+  } catch {
+    return send(res, 400, 'Bad Request', { 'Content-Type': 'text/plain; charset=utf-8' });
+  }
+
+  if (pathname === '/api/newsletter') {
+    if (req.method !== 'POST') {
+      return sendJson(res, 405, { ok: false, error: 'Method not allowed.' });
+    }
+    handleNewsletter(req, res).catch((err) => {
+      console.error(err);
+      if (!res.headersSent) sendJson(res, 500, { ok: false, error: 'Something went wrong.' });
+    });
+    return;
+  }
+
+  const entry = STATIC_FILES[pathname];
+  if (entry && (req.method === 'GET' || req.method === 'HEAD')) {
+    return serveStatic(req, res, entry);
+  }
+
+  send(res, 404, 'Not Found', { 'Content-Type': 'text/plain; charset=utf-8' });
+});
+
+server.listen(PORT, HOST, () => {
+  console.log(`The Daily Grind running at http://localhost:${PORT}`);
+});

