+            focusTarget.focus();
+          });
+          announce(`${extra} removed from ${card.querySelector('h3').textContent}.`);
+        }
+      });
+
+      // ----- Card-level: add extras -----
+      grid.addEventListener('submit', (e) => {
+        const form = e.target.closest('.add-extra');
+        if (!form) return;
+        e.preventDefault();
+        const card = form.closest('.card');
+        const extra = form.elements.extra.value;
+        if (!extra) return;
+        const title = card.querySelector('h3').textContent;
+
+        const li = document.createElement('li');
+        li.dataset.extra = extra;
+        const label = document.createElement('span');
+        label.textContent = extra;
+        const remove = document.createElement('button');
+        remove.type = 'button';
+        remove.className = 'icon-btn remove-extra';
+        remove.setAttribute('aria-label', `Remove ${extra} from ${title}`);
+        remove.textContent = '×';
+        li.append(label, remove);
+
+        runScopedTransition(card, () => {
+          card.querySelector('.extras').append(li);
+          refreshSelect(card);
+        });
+        announce(`${extra} added to ${title}.`);
+      });
+
+      // ----- Section controls (outside the grid scope, always interactive) -----
+      document.getElementById('sort-cards').addEventListener('click', (e) => {
+        const slots = [...grid.children].sort((a, b) => titleOf(a).localeCompare(titleOf(b)));
+        applyOrder(slots, e.currentTarget);
+        announce(`Favorites sorted A to Z, ${slots.length} drinks.`);
+      });
+
+      document.getElementById('reset-cards').addEventListener('click', (e) => {
+        applyOrder(originalOrder, e.currentTarget);
+        announce(`Favorites reset, ${originalOrder.length} drinks.`);
+      });
+
+      grid.querySelectorAll('.card').forEach(refreshSelect);
+      syncMoveButtons();
+    })();
+  </script>
+
 </body>

