+/*
+ * Seasonal Favorites: reorder / remove drink cards and customize each cup.
+ *
+ * Animations are scoped to this component only:
+ *  - Card reorder/remove/restore runs a view transition scoped to the grid
+ *    element (element.startViewTransition), so the sticky nav and the rest of
+ *    the page are never captured or blocked.
+ *  - Customizing a drink runs a transition scoped to that single card, so
+ *    several cards can animate at the same time independently.
+ *  - Browsers without element-scoped view transitions fall back to a FLIP
+ *    animation built on the Web Animations API, which is equally
+ *    non-blocking and concurrent.
+ */
+(() => {
+  'use strict';
+
+  const grid = document.getElementById('seasonal-grid');
+  if (!grid) return;
+
+  const resetBtn = document.getElementById('seasonal-reset');
+  const emptyMsg = document.getElementById('seasonal-empty');
+  const status = document.getElementById('seasonal-status');
+
+  const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
+  const hasScopedVT =
+    typeof Element !== 'undefined' &&
+    typeof Element.prototype.startViewTransition === 'function';
+
+  const EASE = 'cubic-bezier(0.2, 0.8, 0.2, 1)';
+
+  const ADDONS = {
+    'extra-shot': { label: 'Extra shot', price: 0.75 },
+    oat: { label: 'Oat milk', price: 0.6 },
+    vanilla: { label: 'Vanilla', price: 0.5 },
+    cinnamon: { label: 'Cinnamon', price: 0.3 },
+    whip: { label: 'Whipped cream', price: 0.5 },
+    'cold-foam': { label: 'Cold foam', price: 0.75 },
+  };
+  const ADDON_ORDER = Object.keys(ADDONS);
+
+  const SIZES = [
+    { id: 's', label: 'Small', delta: -0.5 },
+    { id: 'm', label: 'Medium', delta: 0 },
+    { id: 'l', label: 'Large', delta: 0.75 },
+  ];
+
+  const money = (n) => `$${n.toFixed(2)}`;
+  const cardName = (card) => card.querySelector('h3').textContent.trim();
+  const cards = () => [...grid.querySelectorAll(':scope > .drink-card')];
+  const originalOrder = cards();
+
+  let announceTimer;
+  function announce(msg) {
+    // Clear first so repeated identical messages are still read out.
+    status.textContent = '';
+    clearTimeout(announceTimer);
+    announceTimer = setTimeout(() => (status.textContent = msg), 50);
+  }
+
+  /* ------------------------------------------------------------------ */
+  /* Transition engine                                                   */
+  /* ------------------------------------------------------------------ */
+
+  /**
+   * Run `update` (a synchronous DOM mutation) with an animation scoped to
+   * `scope`. `track` returns the elements whose movement should be animated
+   * in the FLIP fallback; `exiting` are elements about to be removed.
+   */
+  function animateIn(scope, update, { track, exiting = [] } = {}) {
+    if (reduceMotion.matches) {
+      update();
+      return Promise.resolve();
+    }
+
+    if (hasScopedVT) {
+      let ran = false;
+      const guarded = () => {
+        if (ran) return;
+        ran = true;
+        update();
+      };
+      try {
+        const t = scope.startViewTransition(guarded);
+        return t.finished.catch(() => {}).finally(guarded);
+      } catch {
+        guarded();
+        return Promise.resolve();
+      }
+    }
+
+    return flip(update, track, exiting);
+  }
+
+  async function flip(update, track, exiting) {
+    if (exiting.length) {
+      await Promise.all(
+        exiting.map((el) =>
+          el
+            .animate(
+              [
+                { opacity: 1, transform: 'scale(1)' },
+                { opacity: 0, transform: 'scale(0.9)' },
+              ],
+              { duration: 220, easing: 'cubic-bezier(0.4, 0, 1, 1)', fill: 'forwards' }
+            )
+            .finished.catch(() => {})
+        )
+      );
+    }
+
+    const tracked = track ? track() : [];
+    // Measure the current *visual* position (including any in-flight FLIP),
+    // then cancel in-flight FLIPs so the new one starts from where the
+    // element actually is. This keeps rapid, overlapping actions smooth.
+    const before = new Map();
+    for (const el of tracked) {
