+        pairs.forEach(function (p, i) {
+          var r = p.step.getBoundingClientRect();
+          // 0 when the step's top reaches mid-viewport, 1 when its bottom passes it.
+          p.progress = clamp((mid - r.top) / r.height);
+          if (r.top <= mid) activeIndex = i;
+        });
+
+        var activeProgress = pairs[activeIndex].progress;
+
+        pairs.forEach(function (p, i) {
+          var visibility = 0;
+          if (i === activeIndex) {
+            visibility = 1;
+          } else if (i === activeIndex + 1) {
+            // Cross-fade the next visual in over the last 20% of the current step.
+            visibility = clamp((activeProgress - 0.8) / 0.2);
+          }
