+}
+
+nav a:hover,
+nav a:focus-visible {
+  color: var(--accent);
+}
+
+.logout-form {
+  display: inline;
+}
+
+/* Logout is a POST form (state-changing), styled to match the nav links. */
+.logout-link {
+  font: inherit;
+  font-size: 0.9rem;
+  color: white;
+  background: none;
+  cursor: pointer;
+  border: 1px solid var(--accent);
+  padding: 5px 12px;
+  border-radius: 4px;
+  transition: color 0.3s;
+}
+
+.logout-link:hover,
+.logout-link:focus-visible {
+  color: var(--accent);
+}
+
+/* Hero Section */
+.hero {
+  height: 60vh;
+  background: linear-gradient(rgba(0, 0, 0, 0.5), rgba(0, 0, 0, 0.5)),
