+/**
+ * <drink-card> — reusable menu card with encapsulated layout and styles.
+ *
+ * Content is supplied from the page via slots:
+ *   slot="title"   – the drink name (use a heading element, e.g. <h3>)
+ *   (default)      – the description
+ *   slot="action"  – the call-to-action link
+ *
+ * Attributes:
+ *   limited        – boolean; shows a "Limited" badge. Add/remove it at any
+ *                    time (or set `card.limited = true/false`) to toggle it.
+ *
+ * Theming hooks (custom properties, inherited from the page):
+ *   --drink-card-bg, --drink-card-accent, --drink-card-badge-bg,
+ *   --drink-card-badge-fg, --drink-card-radius
+ * Parts: card, badge
+ */
+
+const sheet = new CSSStyleSheet();
+sheet.replaceSync(`
+  :host {
+    --_bg: var(--drink-card-bg, white);
+    --_accent: var(--drink-card-accent, #4e342e);
+    --_accent-hover: var(--drink-card-accent-hover, #3e2723);
+    --_badge-bg: var(--drink-card-badge-bg, #ffab40);
+    --_badge-fg: var(--drink-card-badge-fg, #3e2723);
+    --_radius: var(--drink-card-radius, 8px);
+    display: block;
+  }
+
+  :host([hidden]) { display: none; }
+
+  .card {
+    position: relative;
+    box-sizing: border-box;
+    height: 100%;
+    display: flex;
+    flex-direction: column;
+    align-items: center;
+    gap: 10px;
+    padding: 20px;
+    background: var(--_bg);
+    border-radius: var(--_radius);
+    box-shadow: 0 2px 5px rgb(0 0 0 / 0.1);
+    text-align: center;
+  }
+
+  .badge {
+    position: absolute;
+    top: 12px;
+    right: 12px;
+    padding: 2px 10px;
+    border-radius: 999px;
+    background: var(--_badge-bg);
+    color: var(--_badge-fg);
+    font-size: 0.75rem;
+    font-weight: 700;
+    letter-spacing: 0.05em;
+    text-transform: uppercase;
+    line-height: 1.6;
+  }
+
+  :host(:not([limited])) .badge { display: none; }
+
+  ::slotted([slot="title"]) {
+    margin: 0;
+    color: var(--_accent);
+  }
+
+  /* Keep the title clear of the badge when it's shown. */
+  :host([limited]) ::slotted([slot="title"]) {
+    padding-inline: 4.5rem;
+  }
+
+  .description { flex: 1; }
+
+  ::slotted(:not([slot])) { margin: 0; }
+
+  ::slotted(a[slot="action"]) {
+    display: inline-block;
+    margin-top: 5px;
+    padding: 10px 20px;
+    border-radius: 5px;
+    background: var(--_accent);
