--- /dev/null
+++ b/components/drink-card.js
@@ -0,0 +1,144 @@
+/**
+ * <drink-card> — reusable card for menu items.
+ *
+ * Attributes (all reactive, so the page can change them at any time):
+ *   heading       Card title, e.g. "Cold Brew"
+ *   description   Short blurb shown under the title
+ *   href          Destination of the action link
+ *   action-label  Text of the action link (default: "View Details")
+ *   limited       Boolean; when present a badge is shown
+ *   badge-label   Text of the badge (default: "Limited")
+ *
+ * Layout and styles live in a shadow root, so global page CSS cannot leak in.
+ * Theme hooks (optional, inherited from the page):
+ *   --drink-card-primary, --drink-card-accent
+ */
+const styles = `
+  :host {
+    display: block;
+    --_primary: var(--drink-card-primary, #4e342e);
+    --_primary-hover: var(--drink-card-primary-hover, #3e2723);
+    --_accent: var(--drink-card-accent, #ffab40);
+  }
+  :host([hidden]) { display: none; }
+
+  * { box-sizing: border-box; margin: 0; padding: 0; }
+
+  .card {
+    position: relative;
+    height: 100%;
+    background: #fff;
+    padding: 20px;
+    border-radius: 8px;
+    box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
+    text-align: center;
+    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
+    line-height: 1.6;
+    color: #3e2723;
+  }
+
+  .badge {
+    position: absolute;
+    top: 12px;
+    right: 12px;
+    background: var(--_accent);
+    color: #3e2723;
+    font-size: 0.7rem;
+    font-weight: 700;
+    letter-spacing: 0.05em;
+    text-transform: uppercase;
+    padding: 2px 8px;
+    border-radius: 999px;
+  }
+  .badge[hidden] { display: none; }
+
+  h3 {
+    font-size: 1.17em;
+    margin-bottom: 10px;
+    color: var(--_primary);
+  }
+
+  .btn {
+    display: inline-block;
+    background: var(--_primary);
+    color: #fff;
+    padding: 10px 20px;
+    text-decoration: none;
+    border-radius: 5px;
+    margin-top: 15px;
+    transition: background 0.3s;
+  }
+  .btn:hover,
+  .btn:focus-visible { background: var(--_primary-hover); }
+`;
+
+class DrinkCard extends HTMLElement {
+  static observedAttributes = [
+    'heading',
+    'description',
+    'href',
+    'action-label',
+    'limited',
+    'badge-label',
+  ];
+
+  constructor() {
+    super();
+    const root = this.attachShadow({ mode: 'open' });
+
+    const style = document.createElement('style');
+    style.textContent = styles;
+
+    const card = document.createElement('article');
+    card.className = 'card';
+    card.setAttribute('part', 'card');
+
+    this._badge = document.createElement('span');
+    this._badge.className = 'badge';
+    this._badge.setAttribute('part', 'badge');
+
+    this._title = document.createElement('h3');
+    this._title.setAttribute('part', 'title');
+
+    this._desc = document.createElement('p');
+    this._desc.setAttribute('part', 'description');
+
+    this._link = document.createElement('a');
+    this._link.className = 'btn';
+    this._link.setAttribute('part', 'action');
+
+    card.append(this._badge, this._title, this._desc, this._link);
+    root.append(style, card);
+  }
+
+  connectedCallback() {
+    this._render();
+  }
+
+  attributeChangedCallback() {
+    this._render();
+  }
+
+  get limited() {
+    return this.hasAttribute('limited');
+  }
+
+  set limited(value) {
+    this.toggleAttribute('limited', Boolean(value));
+  }
+
+  _render() {
+    // textContent (not innerHTML) so attribute values are never parsed as markup.
+    this._title.textContent = this.getAttribute('heading') ?? '';
+    this._desc.textContent = this.getAttribute('description') ?? '';
+    this._link.textContent = this.getAttribute('action-label') || 'View Details';
+    this._link.setAttribute('href', this.getAttribute('href') || '#');
+
+    this._badge.textContent = this.getAttribute('badge-label') || 'Limited';
+    this._badge.hidden = !this.limited;
+  }
+}
+
+if (!customElements.get('drink-card')) {
+  customElements.define('drink-card', DrinkCard);
+}
