+import type { APIRoute } from 'astro';
+import {
+  CODE_TTL_MS,
+  RESEND_COOLDOWN_MS,
+  SESSION_KEY_PENDING,
+  SESSION_KEY_VERIFIED,
+  buildSmsMessage,
+  generateCode,
+  generateSalt,
+  hashCode,
+  json,
+  maskPhone,
+  normalizePhone,
+  sendSms,
+  type PendingVerification,
+} from '../../../utils/phoneVerification';
+
+export const prerender = false;
+
+export const POST: APIRoute = async ({ request, session, url }) => {
+  if (!session) {
+    return json({ error: 'Sessions are not available.' }, 500);
+  }
+
+  let body: { phone?: unknown };
+  try {
+    body = await request.json();
+  } catch {
+    return json({ error: 'Invalid request body.' }, 400);
+  }
+
+  const phone = normalizePhone(body.phone);
+  if (!phone) {
+    return json(
+      { error: 'Enter a phone number with its country code, for example +1 555 123 4567.' },
+      422,
+    );
+  }
+
+  const now = Date.now();
+  const previous = (await session.get(SESSION_KEY_PENDING)) as PendingVerification | undefined;
+  if (previous && previous.phone === phone && now - previous.sentAt < RESEND_COOLDOWN_MS) {
+    const retryAfter = Math.ceil((RESEND_COOLDOWN_MS - (now - previous.sentAt)) / 1000);
+    return json({ error: `Please wait ${retryAfter} seconds before requesting a new code.`, retryAfter }, 429);
+  }
+
+  const code = generateCode();
+  const salt = generateSalt();
+  const pending: PendingVerification = {
+    phone,
+    salt,
+    codeHash: hashCode(code, salt),
+    sentAt: now,
+    expiresAt: now + CODE_TTL_MS,
+    attempts: 0,
+  };
+
+  try {
+    await sendSms(phone, buildSmsMessage(code, url.hostname));
+  } catch (err) {
+    console.error('[sms] delivery failed', err);
+    return json({ error: "We couldn't send a text message to that number. Please try again." }, 502);
+  }
+
+  session.set(SESSION_KEY_PENDING, pending);
+  session.delete(SESSION_KEY_VERIFIED);
+
+  return json({
+    phone: maskPhone(phone),
+    expiresIn: CODE_TTL_MS / 1000,
+    resendAfter: RESEND_COOLDOWN_MS / 1000,
+  });
+};
