+import type { APIRoute } from 'astro';
+import {
+  CODE_LENGTH,
+  MAX_ATTEMPTS,
+  SESSION_KEY_PENDING,
+  SESSION_KEY_VERIFIED,
+  codeMatches,
+  json,
+  type PendingVerification,
+  type VerifiedPhone,
+} from '../../../utils/phoneVerification';
+
+export const prerender = false;
+
+const CODE_PATTERN = new RegExp(`^\\d{${CODE_LENGTH}}$`);
+
+export const POST: APIRoute = async ({ request, session }) => {
+  if (!session) {
+    return json({ error: 'Sessions are not available.' }, 500);
+  }
+
+  let body: { code?: unknown };
+  try {
+    body = await request.json();
+  } catch {
+    return json({ error: 'Invalid request body.' }, 400);
+  }
+
+  const code = typeof body.code === 'string' ? body.code.trim() : '';
+  if (!CODE_PATTERN.test(code)) {
+    return json({ error: `Enter the ${CODE_LENGTH}-digit code from the text message.` }, 422);
+  }
+
+  const pending = (await session.get(SESSION_KEY_PENDING)) as PendingVerification | undefined;
+  if (!pending) {
+    return json({ error: 'No verification code is pending. Request a new code.', expired: true }, 410);
+  }
+
+  if (Date.now() > pending.expiresAt || pending.attempts >= MAX_ATTEMPTS) {
+    session.delete(SESSION_KEY_PENDING);
+    return json({ error: 'This code has expired. Request a new code.', expired: true }, 410);
+  }
+
+  if (!codeMatches(code, pending)) {
+    const attempts = pending.attempts + 1;
+    const remaining = MAX_ATTEMPTS - attempts;
+    if (remaining <= 0) {
+      session.delete(SESSION_KEY_PENDING);
+      return json({ error: 'Too many incorrect attempts. Request a new code.', expired: true }, 410);
+    }
+    session.set(SESSION_KEY_PENDING, { ...pending, attempts });
+    return json(
+      {
+        error: `That code is incorrect. ${remaining} ${remaining === 1 ? 'attempt' : 'attempts'} remaining.`,
+        remaining,
+      },
+      422,
+    );
+  }
+
+  const verified: VerifiedPhone = { phone: pending.phone, verifiedAt: Date.now() };
+  session.delete(SESSION_KEY_PENDING);
+  session.set(SESSION_KEY_VERIFIED, verified);
+
+  return json({ verified: true, phone: pending.phone });
+};
