+/**
+ * Shared (client + server) phone helpers. Keep this file free of Node APIs so
+ * it can be bundled into client components.
+ */
+
+/**
+ * Normalizes a user-entered phone number to E.164 (+<country><number>).
+ * Accepts common separators (spaces, dashes, dots, parentheses) and a
+ * leading "00" international prefix. Returns null when the result is not a
+ * plausible E.164 number.
+ */
+export function normalizePhone(input: unknown): string | null {
+  if (typeof input !== 'string') return null;
+  let value = input.trim().replace(/[\s().-]/g, '');
+  if (value.startsWith('00')) value = `+${value.slice(2)}`;
+  return /^\+[1-9]\d{7,14}$/.test(value) ? value : null;
+}
