+import { createHash, randomInt, timingSafeEqual } from 'node:crypto';
+
+export { normalizePhone } from './phone';
+
+export const CODE_LENGTH = 6;
+export const CODE_TTL_MS = 5 * 60 * 1000;
+export const RESEND_COOLDOWN_MS = 30 * 1000;
+export const MAX_ATTEMPTS = 5;
+
+export const SESSION_KEY_PENDING = 'phoneVerificationPending';
+export const SESSION_KEY_VERIFIED = 'phoneVerified';
+
+export interface PendingVerification {
+  phone: string;
+  codeHash: string;
+  salt: string;
+  expiresAt: number;
+  sentAt: number;
+  attempts: number;
+}
+
+export interface VerifiedPhone {
+  phone: string;
+  verifiedAt: number;
+}
+
+/** Masks all but the last 2 digits, e.g. +1••••••••67. */
+export function maskPhone(phone: string): string {
+  const visibleTail = phone.slice(-2);
+  const prefix = phone.slice(0, 2);
+  return `${prefix}${'•'.repeat(Math.max(phone.length - 4, 0))}${visibleTail}`;
+}
+
+export function generateCode(): string {
+  return randomInt(0, 10 ** CODE_LENGTH).toString().padStart(CODE_LENGTH, '0');
+}
+
+export function generateSalt(): string {
+  return randomInt(0, 2 ** 47).toString(36) + Date.now().toString(36);
+}
+
+export function hashCode(code: string, salt: string): string {
+  return createHash('sha256').update(`${salt}:${code}`).digest('hex');
+}
+
+export function codeMatches(code: string, pending: PendingVerification): boolean {
+  const expected = Buffer.from(pending.codeHash, 'hex');
+  const actual = Buffer.from(hashCode(code, pending.salt), 'hex');
+  return expected.length === actual.length && timingSafeEqual(expected, actual);
+}
+
+/**
+ * Builds an origin-bound SMS body. The final line must be exactly
+ * "@<host> #<code>" so the WebOTP API and `autocomplete="one-time-code"`
+ * autofill only offer the code on the matching domain.
+ */
+export function buildSmsMessage(code: string, host: string): string {
+  return `Your DevTools Times verification code is ${code}. It expires in 5 minutes.\n\n@${host} #${code}`;
+}
+
+/**
+ * Delivers the SMS. Wire a real provider by setting SMS_WEBHOOK_URL to an
+ * endpoint that accepts `{ to, body }` JSON (e.g. a thin proxy in front of
+ * Twilio / Vonage / SNS). Without it, the message is logged server-side so
+ * the flow can be exercised during development.
+ */
+export async function sendSms(to: string, body: string): Promise<void> {
+  const webhook = process.env.SMS_WEBHOOK_URL;
+  if (!webhook) {
+    console.info(`[sms] (no SMS_WEBHOOK_URL configured) to=${to}\n${body}`);
+    return;
+  }
+  const response = await fetch(webhook, {
+    method: 'POST',
+    headers: {
+      'Content-Type': 'application/json',
+      ...(process.env.SMS_WEBHOOK_TOKEN
+        ? { Authorization: `Bearer ${process.env.SMS_WEBHOOK_TOKEN}` }
+        : {}),
+    },
+    body: JSON.stringify({ to, body }),
+  });
+  if (!response.ok) {
+    throw new Error(`SMS provider responded with ${response.status}`);
+  }
+}
+
+export function json(data: unknown, status = 200): Response {
+  return new Response(JSON.stringify(data), {
+    status,
+    headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' },
+  });
+}

