+/**
+ * Server-only SMS one-time-passcode (OTP) service.
+ *
+ * - Codes are 6 random digits, stored only as an HMAC hash, and expire after 5 minutes.
+ * - Each code allows a limited number of verification attempts.
+ * - Sending is rate limited per phone number and per client IP.
+ * - A successful verification yields a short-lived signed token that proves
+ *   ownership of the phone number when the account is registered.
+ *
+ * State lives in process memory. For multi-instance deployments swap the
+ * `Map`s below for a shared store (e.g. Redis).
+ *
+ * Environment variables:
+ *   OTP_SECRET            HMAC secret (falls back to a random per-process secret)
+ *   SMS_OTP_DOMAIN        Host used in the WebOTP origin-binding line (defaults to the request host)
+ *   TWILIO_ACCOUNT_SID    \
+ *   TWILIO_AUTH_TOKEN      > When set, SMS is delivered via Twilio. Otherwise codes are logged to the console.
+ *   TWILIO_FROM_NUMBER    /
+ */
+import { createHmac, randomBytes, randomInt, timingSafeEqual } from 'node:crypto';
+import { OTP_LENGTH } from './phone';
+
+const CODE_TTL_MS = 5 * 60 * 1000;
+const RESEND_COOLDOWN_MS = 30 * 1000;
+const MAX_VERIFY_ATTEMPTS = 5;
+const MAX_SENDS_PER_PHONE_PER_HOUR = 5;
+const MAX_SENDS_PER_IP_PER_HOUR = 20;
+const VERIFICATION_TOKEN_TTL_MS = 15 * 60 * 1000;
+const HOUR_MS = 60 * 60 * 1000;
+
+function env(name: string): string | undefined {
+  return process.env[name] || (import.meta.env as Record<string, string | undefined> | undefined)?.[name];
+}
+
+const SECRET = env('OTP_SECRET') || randomBytes(32).toString('hex');
+
+interface PendingCode {
+  hash: string;
+  expiresAt: number;
+  attempts: number;
+  lastSentAt: number;
+}
+
+const pending = new Map<string, PendingCode>();
+const sendLog = new Map<string, number[]>();
+
+function hmac(value: string): string {
+  return createHmac('sha256', SECRET).update(value).digest('base64url');
+}
+
+function safeEqual(a: string, b: string): boolean {
+  const ab = Buffer.from(a);
+  const bb = Buffer.from(b);
+  return ab.length === bb.length && timingSafeEqual(ab, bb);
+}
+
+function prune(now: number) {
+  for (const [phone, entry] of pending) {
+    if (entry.expiresAt <= now) pending.delete(phone);
+  }
+  for (const [key, stamps] of sendLog) {
+    const recent = stamps.filter((t) => now - t < HOUR_MS);
+    if (recent.length) sendLog.set(key, recent);
+    else sendLog.delete(key);
+  }
+}
+
+function recentSends(key: string, now: number): number {
+  return (sendLog.get(key) ?? []).filter((t) => now - t < HOUR_MS).length;
+}
+
+function recordSend(key: string, now: number) {
+  const stamps = sendLog.get(key) ?? [];
+  stamps.push(now);
+  sendLog.set(key, stamps);
+}
+
+export type SendResult =
+  | { ok: true; expiresInSeconds: number; resendInSeconds: number }
+  | { ok: false; status: number; error: string; retryAfterSeconds?: number };
+
+export async function sendOtp(phone: string, opts: { ip: string; host: string }): Promise<SendResult> {
+  const now = Date.now();
+  prune(now);
+
+  const existing = pending.get(phone);
+  if (existing && now - existing.lastSentAt < RESEND_COOLDOWN_MS) {
+    const retryAfterSeconds = Math.ceil((RESEND_COOLDOWN_MS - (now - existing.lastSentAt)) / 1000);
+    return { ok: false, status: 429, error: 'Please wait before requesting another code.', retryAfterSeconds };
+  }
+
+  const phoneKey = `phone:${phone}`;
+  const ipKey = `ip:${opts.ip}`;
+  if (recentSends(phoneKey, now) >= MAX_SENDS_PER_PHONE_PER_HOUR || recentSends(ipKey, now) >= MAX_SENDS_PER_IP_PER_HOUR) {
+    return { ok: false, status: 429, error: 'Too many codes requested. Please try again later.', retryAfterSeconds: 3600 };
+  }
+
+  const code = randomInt(0, 10 ** OTP_LENGTH).toString().padStart(OTP_LENGTH, '0');
+  const domain = env('SMS_OTP_DOMAIN') || opts.host;
+
+  // The final line follows the WebOTP / SMS Retriever origin-bound format so
+  // supporting browsers can extract the code automatically.
+  const body = `Your DevTools Times verification code is ${code}. It expires in 5 minutes.\n\n@${domain} #${code}`;
+
+  try {
+    await deliverSms(phone, body);
+  } catch (err) {
+    console.error('[otp] SMS delivery failed', err);
+    return { ok: false, status: 502, error: 'We could not send a text message to that number. Please check it and try again.' };
+  }
+
+  pending.set(phone, { hash: hmac(`${phone}:${code}`), expiresAt: now + CODE_TTL_MS, attempts: 0, lastSentAt: now });
+  recordSend(phoneKey, now);
+  recordSend(ipKey, now);
+
+  return { ok: true, expiresInSeconds: CODE_TTL_MS / 1000, resendInSeconds: RESEND_COOLDOWN_MS / 1000 };
+}
+
+export type VerifyResult =
+  | { ok: true; token: string }
+  | { ok: false; status: number; error: string; attemptsRemaining?: number };
+
+export function verifyOtp(phone: string, code: string): VerifyResult {
+  const now = Date.now();
+  const entry = pending.get(phone);
+
+  if (!entry || entry.expiresAt <= now) {
+    pending.delete(phone);
+    return { ok: false, status: 410, error: 'This code has expired. Please request a new one.' };
+  }
+
+  if (entry.attempts >= MAX_VERIFY_ATTEMPTS) {
+    pending.delete(phone);
+    return { ok: false, status: 429, error: 'Too many incorrect attempts. Please request a new code.' };
+  }
+
+  entry.attempts += 1;
+
+  if (!safeEqual(entry.hash, hmac(`${phone}:${code}`))) {
+    const attemptsRemaining = MAX_VERIFY_ATTEMPTS - entry.attempts;
+    if (attemptsRemaining <= 0) pending.delete(phone);
+    return {
+      ok: false,
+      status: 400,
+      error: attemptsRemaining > 0
+        ? `That code is incorrect. ${attemptsRemaining} attempt${attemptsRemaining === 1 ? '' : 's'} remaining.`
+        : 'Too many incorrect attempts. Please request a new code.',
+      attemptsRemaining,
+    };
+  }
+
+  pending.delete(phone);
+  return { ok: true, token: createVerificationToken(phone, now + VERIFICATION_TOKEN_TTL_MS) };
+}
+
+function createVerificationToken(phone: string, expiresAt: number): string {
+  const payload = Buffer.from(JSON.stringify({ phone, exp: expiresAt })).toString('base64url');
+  return `${payload}.${hmac(`token:${payload}`)}`;
+}
+
+/** Returns the verified phone number if the token is valid and unexpired. */
+export function readVerificationToken(token: unknown): string | null {
+  if (typeof token !== 'string') return null;
+  const [payload, sig] = token.split('.');
+  if (!payload || !sig || !safeEqual(sig, hmac(`token:${payload}`))) return null;
+  try {
+    const { phone, exp } = JSON.parse(Buffer.from(payload, 'base64url').toString('utf8'));
+    if (typeof phone !== 'string' || typeof exp !== 'number' || exp <= Date.now()) return null;
+    return phone;
+  } catch {
+    return null;
+  }
+}
+
+async function deliverSms(to: string, body: string): Promise<void> {
+  const sid = env('TWILIO_ACCOUNT_SID');
+  const authToken = env('TWILIO_AUTH_TOKEN');
+  const from = env('TWILIO_FROM_NUMBER');
+
+  if (!sid || !authToken || !from) {
+    console.warn(`[otp] No SMS provider configured. Message for ${to}:\n${body}`);
+    return;
+  }
+
+  const res = await fetch(`https://api.twilio.com/2010-04-01/Accounts/${encodeURIComponent(sid)}/Messages.json`, {
+    method: 'POST',
+    headers: {
+      Authorization: `Basic ${Buffer.from(`${sid}:${authToken}`).toString('base64')}`,
+      'Content-Type': 'application/x-www-form-urlencoded',
+    },
+    body: new URLSearchParams({ To: to, From: from, Body: body }),
+  });
+
+  if (!res.ok) {
+    throw new Error(`Twilio responded with ${res.status}: ${await res.text()}`);
+  }
+}
