+/**
+ * Phone number helpers shared by the client and the server.
+ * Numbers are normalised to E.164 (e.g. +15551234567).
+ */
+
+export interface CountryDialCode {
+  code: string; // ISO 3166-1 alpha-2
+  name: string;
+  dial: string; // without "+"
+}
+
+export const COUNTRY_DIAL_CODES: CountryDialCode[] = [
+  { code: 'US', name: 'United States', dial: '1' },
+  { code: 'CA', name: 'Canada', dial: '1' },
+  { code: 'GB', name: 'United Kingdom', dial: '44' },
+  { code: 'DE', name: 'Germany', dial: '49' },
+  { code: 'FR', name: 'France', dial: '33' },
+  { code: 'ES', name: 'Spain', dial: '34' },
+  { code: 'IT', name: 'Italy', dial: '39' },
+  { code: 'NL', name: 'Netherlands', dial: '31' },
+  { code: 'CH', name: 'Switzerland', dial: '41' },
+  { code: 'SE', name: 'Sweden', dial: '46' },
+  { code: 'IE', name: 'Ireland', dial: '353' },
+  { code: 'IN', name: 'India', dial: '91' },
+  { code: 'JP', name: 'Japan', dial: '81' },
+  { code: 'AU', name: 'Australia', dial: '61' },
+  { code: 'BR', name: 'Brazil', dial: '55' },
+  { code: 'MX', name: 'Mexico', dial: '52' },
+];
+
+const E164_RE = /^\+[1-9]\d{7,14}$/;
+
+export function isValidE164(value: string): boolean {
+  return E164_RE.test(value);
+}
+
+/**
+ * Normalise user input to E.164. Accepts numbers that already include a
+ * "+"/"00" international prefix (e.g. from browser autofill), otherwise
+ * prefixes the given country dial code and drops a national trunk "0".
+ * Returns null when the result is not a plausible E.164 number.
+ */
+export function toE164(input: string, dialCode: string): string | null {
+  const trimmed = input.trim();
+  if (!trimmed) return null;
+
+  let digits: string;
+  if (trimmed.startsWith('+')) {
+    digits = trimmed.slice(1).replace(/\D/g, '');
+  } else {
+    const raw = trimmed.replace(/\D/g, '');
+    if (raw.startsWith('00')) {
+      digits = raw.slice(2);
+    } else {
+      const national = raw.replace(/^0+/, '');
+      // Tolerate users typing the country code without "+".
+      digits = national.startsWith(dialCode) && national.length > 10 ? national : dialCode + national;
+    }
+  }
+
+  const e164 = `+${digits}`;
+  return isValidE164(e164) ? e164 : null;
+}
+
+/** Mask all but the last four digits, e.g. "••• ••• 4567". */
+export function maskPhone(e164: string): string {
+  return `••• ••• ${e164.slice(-4)}`;
+}
+
+export const OTP_LENGTH = 6;
