+import type { APIRoute } from 'astro';
+import { sendOtp } from '../../../lib/otp.server';
+import { isValidE164 } from '../../../lib/phone';
+import { clientIp, json, readJson } from '../../../lib/api.server';
+
+export const prerender = false;
+
+export const POST: APIRoute = async ({ request, url, clientAddress }) => {
+  const body = await readJson(request);
+  const phone = typeof body?.phone === 'string' ? body.phone : '';
+
+  if (!isValidE164(phone)) {
+    return json({ error: 'Please enter a valid phone number, including the country code.' }, 400);
+  }
+
+  const result = await sendOtp(phone, {
+    ip: clientIp(request, () => clientAddress),
+    host: url.host,
+  });
+
+  if (!result.ok) {
+    const headers: Record<string, string> = result.retryAfterSeconds ? { 'Retry-After': String(result.retryAfterSeconds) } : {};
+    return json({ error: result.error, retryAfterSeconds: result.retryAfterSeconds }, result.status, headers);
+  }
+
+  return json({ expiresInSeconds: result.expiresInSeconds, resendInSeconds: result.resendInSeconds });
+};
