+import type { APIRoute } from 'astro';
+import { verifyOtp } from '../../../lib/otp.server';
+import { isValidE164, OTP_LENGTH } from '../../../lib/phone';
+import { json, readJson } from '../../../lib/api.server';
+
+export const prerender = false;
+
+const CODE_RE = new RegExp(`^\\d{${OTP_LENGTH}}$`);
+
+export const POST: APIRoute = async ({ request }) => {
+  const body = await readJson(request);
+  const phone = typeof body?.phone === 'string' ? body.phone : '';
+  const code = typeof body?.code === 'string' ? body.code.trim() : '';
+
+  if (!isValidE164(phone)) {
+    return json({ error: 'Invalid phone number.' }, 400);
+  }
+  if (!CODE_RE.test(code)) {
+    return json({ error: `Enter the ${OTP_LENGTH}-digit code from the text message.` }, 400);
+  }
+
+  const result = verifyOtp(phone, code);
+  if (!result.ok) {
+    return json({ error: result.error, attemptsRemaining: result.attemptsRemaining }, result.status);
+  }
+
+  return json({ verificationToken: result.token });
+};
