+import type { APIRoute } from 'astro';
+import { readVerificationToken } from '../../lib/otp.server';
+import { json, readJson } from '../../lib/api.server';
+
+export const prerender = false;
+
+const UPSTREAM_REGISTER_URL = 'https://us-central1-web-devrel-apps.cloudfunctions.net/times_cdn/api/register';
+
+/**
+ * Registers a new account once the phone number has been verified via SMS OTP.
+ * The verification token is checked server-side before forwarding to the
+ * upstream registration service.
+ */
+export const POST: APIRoute = async ({ request }) => {
+  const body = await readJson(request);
+  const username = typeof body?.username === 'string' ? body.username.trim() : '';
+  const password = typeof body?.password === 'string' ? body.password : '';
+  const phone = typeof body?.phone === 'string' ? body.phone : '';
+
+  if (!username || !password) {
+    return json({ error: 'Username and password are required.' }, 400);
+  }
+
+  const verifiedPhone = readVerificationToken(body?.verificationToken);
+  if (!verifiedPhone || verifiedPhone !== phone) {
+    return json({ error: 'Your phone verification has expired. Please verify your number again.', code: 'PHONE_NOT_VERIFIED' }, 403);
+  }
+
+  try {
+    const upstream = await fetch(UPSTREAM_REGISTER_URL, {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json' },
+      body: JSON.stringify({ username, password, phone: verifiedPhone }),
+    });
+    const data = await upstream.json().catch(() => ({}));
+    return json(data, upstream.status);
+  } catch (err) {
+    console.error('[register] upstream request failed', err);
+    return json({ error: 'Registration service is unavailable. Please try again later.' }, 502);
+  }
+};

