+/**
+ * <drink-card> — an encapsulated menu card for The Daily Grind.
+ *
+ * Light DOM API (slots):
+ *   slot="media"   an <img> (optional) shown as the card's hero image
+ *   slot="title"   the drink name, usually an <h3>
+ *   (default)      the description, usually a <p>
+ *   slot="action"  call-to-action link(s)
+ *
+ * Attributes:
+ *   variant="featured" | "bold" | "chilled"   outer styling variants
+ *   badge="Text"                              optional ribbon label
+ *
+ * Theming: inherited custom properties cross the shadow boundary, so the
+ * card reads the site palette (--primary, --secondary, --accent, --text,
+ * --light) automatically. Fine-grained overrides go through the public
+ * --drink-card-* properties, which are never set on :host so they can be
+ * inherited from any ancestor.
+ *
+ * Parts (styleable from the page via drink-card::part(name)):
+ *   frame, media, badge, body, footer
+ *
+ * Custom state: :state(has-media) when an image is slotted.
+ */
+
+const sheet = new CSSStyleSheet();
+sheet.replaceSync(/* css */ `
+  /* Priority tiers, lowest to highest. Consumer ::part() and light-DOM
+     rules still win over all of these because they come from the outer
+     tree context. */
+  @layer reset, tokens, base, layout, variants, states;
+
+  @layer reset {
+    *, *::before, *::after { box-sizing: border-box; }
+    figure, p { margin: 0; }
+  }
+
+  @layer tokens {
+    :host {
+      /* Private aliases: fallbacks live here once, falling back first to the
+         site theme (inherited from :root) and then to hard defaults. */
+      --_bg: var(--drink-card-bg, #fff);
+      --_fg: var(--drink-card-fg, var(--text, #3e2723));
+      --_heading: var(--drink-card-heading, var(--primary, #4e342e));
+      --_accent: var(--drink-card-accent, var(--accent, #ffab40));
+      --_radius: var(--drink-card-radius, 8px);
+      --_shadow: var(--drink-card-shadow, 0 2px 5px rgb(0 0 0 / 0.1));
+      --_pad: var(--drink-card-padding, 20px);
+      --_border: 2px solid transparent;
+    }
+  }
+
+  @layer base {
+    :host {
+      display: block; /* custom elements default to inline; containment needs a box */
+      container: drink-card / inline-size;
+      color: var(--_fg);
+    }
+
+    :host([hidden]) { display: none; }
+
+    .frame {
+      position: relative;
+      block-size: 100%;
+      background: var(--_bg);
+      color: inherit;
+      border: var(--_border);
+      border-radius: var(--_radius);
+      box-shadow: var(--_shadow);
+      overflow: hidden;
+      transition: box-shadow 0.3s, translate 0.3s;
+    }
+
+    .media { display: none; }
+
+    .body {
+      padding: var(--_pad);
+      text-align: center;
+    }
+
+    .badge {
+      position: absolute;
+      inset-block-start: 12px;
+      inset-inline-start: 12px;
+      z-index: 1;
+      padding: 2px 10px;
+      border-radius: 999px;
+      background: var(--_accent);
+      color: var(--_heading);
+      font-size: 0.75rem;
+      font-weight: 700;
+      letter-spacing: 0.05em;
+      text-transform: uppercase;
+    }
+    .badge:empty { display: none; }
+
+    .footer { margin-block-start: 15px; }
+
+    /* Light touch-ups on projected content only; the page owns the rest. */
+    ::slotted([slot="title"]) {
+      margin-block-end: 10px;
+      color: var(--_heading);
+    }
+    ::slotted([slot="media"]) {
+      display: block;
+      inline-size: 100%;
+      block-size: 100%;
+      aspect-ratio: 16 / 10;
+      object-fit: cover;
+    }
+  }
+
+  @layer layout {
+    :host(:state(has-media)) .media { display: block; }
+
+    /* Medium cards: tighten the body and left-align longer copy. */
+    @container drink-card (min-width: 360px) {
+      .body { text-align: start; }
+      .footer { display: flex; gap: 10px; flex-wrap: wrap; }
+    }
+
+    /* Wide cards with an image: media beside the content. */
+    @container drink-card (min-width: 480px) {
+      :host(:state(has-media)) .frame {
+        display: grid;
+        grid-template-columns: minmax(0, 2fr) minmax(0, 3fr);
+      }
+      :host(:state(has-media)) .body {
+        display: flex;
+        flex-direction: column;
+        justify-content: center;
+        padding: calc(var(--_pad) * 1.5);
+      }
+      ::slotted([slot="media"]) { aspect-ratio: auto; }
+    }
+
+    /* Very narrow cards: shrink padding so content isn't cramped. */
+    @container drink-card (max-width: 220px) {
+      .body { padding: calc(var(--_pad) * 0.6); }
