+    </div>
+  </article>
+`;
+
+class DrinkCard extends HTMLElement {
+  static observedAttributes = ['badge'];
+
+  #internals = this.attachInternals();
+
+  constructor() {
+    super();
+    const root = this.attachShadow({ mode: 'open' });
+    root.adoptedStyleSheets = [sheet];
+    root.append(template.content.cloneNode(true));
+
+    root.querySelector('slot[name="media"]').addEventListener('slotchange', (e) => {
+      this.#setState('has-media', e.target.assignedElements().length > 0);
+    });
+  }
+
+  connectedCallback() {
+    this.#renderBadge();
+  }
+
+  attributeChangedCallback() {
+    this.#renderBadge();
+  }
+
+  #renderBadge() {
+    const badge = this.shadowRoot.querySelector('.badge');
+    badge.textContent = this.getAttribute('badge') ?? '';
+  }
+
+  #setState(name, on) {
+    // CustomStateSet is progressive: without it the card keeps its
+    // stacked text-only layout.
+    try {
+      on ? this.#internals.states.add(name) : this.#internals.states.delete(name);
+    } catch { /* unsupported */ }
+  }
+}
+
+if (!customElements.get('drink-card')) {
+  customElements.define('drink-card', DrinkCard);
+}
