+++ b/drink-card.js
@@ -0,0 +1,311 @@
+/**
+ * <drink-card> — encapsulated card for the Seasonal Favorites menu.
+ *
+ * Attributes
+ *   variant    "standard" (default) | "featured" | "limited"
+ *   href       destination for the built-in call-to-action link
+ *
+ * Slots
+ *   media      image/illustration shown at the top (or side, when wide)
+ *   badge      small label pinned over the media (hidden when empty)
+ *   title      the drink name, ideally an <h3>
+ *   (default)  description / body copy
+ *   price      price tag (hidden when empty)
+ *   cta-label  text for the call-to-action (defaults to "View Details")
+ *
+ * Parts (style from the page with drink-card::part(name))
+ *   card, media, badge, body, title, description, footer, price, cta
+ *
+ * Theme
+ *   Inherits the site tokens --primary, --secondary, --accent, --text and
+ *   --light across the shadow boundary (custom properties inherit).
+ *   Per-card hooks: --drink-card-bg, --drink-card-fg, --drink-card-accent,
+ *   --drink-card-radius, --drink-card-shadow, --drink-card-padding,
+ *   --drink-card-media-ratio.
+ *
+ * Internal styles are organised with cascade layers
+ *   reset < tokens < base < layout < variants < states
+ * and the layout responds to the card's own width via container queries.
+ */
+(() => {
+  const css = /* css */ `
+    @layer reset, tokens, base, layout, variants, states;
+
+    /* ---------- reset: neutralise inherited box quirks ---------- */
+    @layer reset {
+      *, *::before, *::after { box-sizing: border-box; }
+      ::slotted(*) { margin: 0; }
+      [hidden] { display: none !important; }
+    }
+
+    /* ---------- tokens: map site theme -> component tokens ---------- */
+    @layer tokens {
+      :host {
+        --_bg: var(--drink-card-bg, #fff);
+        --_fg: var(--drink-card-fg, var(--text, #3e2723));
+        --_brand: var(--primary, #4e342e);
+        --_brand-dark: var(--text, #3e2723);
+        --_muted: var(--secondary, #d7ccc8);
+        --_accent: var(--drink-card-accent, var(--accent, #ffab40));
+        --_radius: var(--drink-card-radius, 8px);
+        --_shadow: var(--drink-card-shadow, 0 2px 5px rgba(0, 0, 0, 0.1));
+        --_pad: var(--drink-card-padding, 20px);
+        --_ratio: var(--drink-card-media-ratio, 16 / 10);
+        --_border: transparent;
+      }
+    }
+
+    /* ---------- base: outer box + typography ---------- */
+    @layer base {
+      :host {
+        display: block;
+        container: drink-card / inline-size;
+        color: var(--_fg);
+        text-align: center;
+      }
+
+      .card {
+        height: 100%;
+        display: flex;
+        flex-direction: column;
+        background: var(--_bg);
+        border: 2px solid var(--_border);
+        border-radius: var(--_radius);
+        box-shadow: var(--_shadow);
+        overflow: hidden;
+        transition: transform 0.25s ease, box-shadow 0.25s ease;
+      }
+
+      .media {
+        position: relative;
+        aspect-ratio: var(--_ratio);
+        background: linear-gradient(135deg, var(--_muted), var(--_brand));
+        overflow: hidden;
+      }
+      .media.empty { display: none; }
+
+      ::slotted([slot="media"]) {
+        display: block;
+        width: 100%;
+        height: 100%;
+        object-fit: cover;
+      }
+
+      .badge {
+        position: absolute;
+        top: 12px;
+        left: 12px;
+        padding: 3px 10px;
+        border-radius: 999px;
+        background: var(--_accent);
+        color: var(--_brand-dark);
+        font-size: 0.72rem;
+        font-weight: 700;
+        text-transform: uppercase;
+      }
+
+      .body {
+        flex: 1;
+        display: flex;
+        flex-direction: column;
+        gap: 8px;
+        padding: var(--_pad);
+      }
+
+      .title ::slotted(*) {
+        color: var(--_brand);
+        font-size: 1.17rem;
+        line-height: 1.3;
+      }
+
+      .description { flex: 1; }
+      .description ::slotted(*) { line-height: 1.6; }
+
+      .footer {
+        display: flex;
+        flex-wrap: wrap;
+        align-items: center;
+        justify-content: center;
+        gap: 12px;
+        margin-top: 7px;
+      }
+
+      .price {
+        font-weight: 700;
+        color: var(--_brand);
+      }
+
+      .cta {
+        display: inline-block;
+        background: var(--_brand);
+        color: #fff;
+        padding: 10px 20px;
+        border-radius: 5px;
+        text-decoration: none;
+        font: inherit;
+        transition: background 0.3s;
+      }
+    }
+
+    /* ---------- layout: respond to the card's own width ---------- */
+    @layer layout {
+      /* Narrow cards: tighten spacing, stack price + CTA full width. */
+      @container drink-card (max-width: 259px) {
+        .body { padding: calc(var(--_pad) * 0.7); gap: 6px; }
+        .title ::slotted(*) { font-size: 1.05rem; }
+        .footer { flex-direction: column; align-items: stretch; }
+        .cta { text-align: center; }
+      }
+
+      /* Medium cards: price on the left, CTA on the right. */
+      @container drink-card (min-width: 260px) {
+        .footer { justify-content: space-between; }
+        .footer.no-price { justify-content: center; }
+      }
+
+      /* Wide cards: horizontal media/body split, left-aligned copy. */
+      @container drink-card (min-width: 520px) {
+        .card {
+          display: grid;
+          grid-template-columns: minmax(180px, 2fr) 3fr;
+        }
+        .media { aspect-ratio: auto; min-height: 100%; }
+        .body { text-align: start; padding: calc(var(--_pad) * 1.4); }
+        .footer { justify-content: flex-start; }
+      }
+    }
+
+    /* ---------- variants: adjust the outer styling ---------- */
+    @layer variants {
+      :host([variant="featured"]) {
+        --_border: var(--_accent);
+        --_shadow: var(--drink-card-shadow, 0 8px 22px rgba(78, 52, 46, 0.22));
+      }
+      :host([variant="featured"]) .cta {
+        background: var(--_accent);
+        color: var(--_brand-dark);
+      }
+
+      :host([variant="limited"]) {
+        --_bg: var(--drink-card-bg, var(--light, #fafafa));
+        --_border: var(--_muted);
+        --_shadow: var(--drink-card-shadow, none);
+      }
+      :host([variant="limited"]) .card { border-style: dashed; }
+      :host([variant="limited"]) .badge {
+        background: var(--_brand);
+        color: #fff;
+      }
+    }
+
+    /* ---------- states: interaction, highest internal priority ---------- */
+    @layer states {
+      @media (hover: hover) {
+        :host(:hover) .card { transform: translateY(-3px); }
+      }
+      .cta:hover { background: var(--_brand-dark); }
+      :host([variant="featured"]) .cta:hover { filter: brightness(0.92); background: var(--_accent); }
+      .cta:focus-visible { outline: 2px solid var(--_accent); outline-offset: 2px; }
+
+      @media (prefers-reduced-motion: reduce) {
+        .card, .cta { transition: none; }
+        :host(:hover) .card { transform: none; }
+      }
+    }
+  `;
+
+  const template = document.createElement('template');
+  template.innerHTML = `
+    <article class="card" part="card">
+      <div class="media" part="media">
+        <slot name="media"></slot>
+        <span class="badge" part="badge" hidden><slot name="badge"></slot></span>
+      </div>
+      <div class="body" part="body">
+        <div class="title" part="title"><slot name="title"></slot></div>
+        <div class="description" part="description"><slot></slot></div>
+        <div class="footer" part="footer">
+          <span class="price" part="price"><slot name="price"></slot></span>
+          <a class="cta" part="cta" href="#"><slot name="cta-label">View Details</slot></a>
+        </div>
+      </div>
+    </article>
+  `;
+
+  let sheet = null;
+  const supportsAdopted =
+    'adoptedStyleSheets' in Document.prototype && 'replaceSync' in CSSStyleSheet.prototype;
+  if (supportsAdopted) {
+    sheet = new CSSStyleSheet();
+    sheet.replaceSync(css);
+  }
+
+  class DrinkCard extends HTMLElement {
+    static observedAttributes = ['href'];
+
+    constructor() {
+      super();
+      const root = this.attachShadow({ mode: 'open' });
+      if (sheet) {
+        root.adoptedStyleSheets = [sheet];
+      } else {
+        const style = document.createElement('style');
+        style.textContent = css;
+        root.append(style);
+      }
+      root.append(template.content.cloneNode(true));
+
+      this._cta = root.querySelector('.cta');
+      this._media = root.querySelector('.media');
+      this._badge = root.querySelector('.badge');
+      this._footer = root.querySelector('.footer');
+      this._price = root.querySelector('.price');
+
+      // Hide optional regions when nothing is projected into them.
+      const watch = (name, fn) => {
+        const slot = root.querySelector(name ? `slot[name="${name}"]` : 'slot:not([name])');
+        slot.addEventListener('slotchange', () => fn(slot.assignedNodes().length > 0));
+        return () => fn(slot.assignedNodes().length > 0);
+      };
+      this._syncSlots = [
+        watch('media', (has) => this._media.classList.toggle('empty', !has && this._badge.hidden)),
+        watch('badge', (has) => {
+          this._badge.hidden = !has;
+          this._media.classList.toggle('empty', !has && !this._hasMedia());
+        }),
+        watch('price', (has) => {
+          this._price.hidden = !has;
+          this._footer.classList.toggle('no-price', !has);
+        }),
+      ];
+    }
+
+    _hasMedia() {
+      return this.shadowRoot.querySelector('slot[name="media"]').assignedNodes().length > 0;
+    }
+
+    connectedCallback() {
+      this._syncSlots.forEach((sync) => sync());
+      this._renderHref();
+    }
+
+    attributeChangedCallback(name) {
+      if (name === 'href') this._renderHref();
+    }
+
+    _renderHref() {
+      const href = this.getAttribute('href');
+      if (href) {
+        this._cta.setAttribute('href', href);
+        this._cta.hidden = false;
+      } else {
+        this._cta.removeAttribute('href');
+        this._cta.hidden = true;
+      }
+    }
+  }
+
+  if (!customElements.get('drink-card')) {
+    customElements.define('drink-card', DrinkCard);
+  }
+})();
