+  <script>
+    // Coffee menu tabs. focusgroup="tablist" supplies the tablist/tab roles and arrow-key focus
+    // movement; this script only syncs selection (which follows focus) with the panels.
+    const tablist = document.querySelector('#coffee-menu .tablist');
+    const tabs = [...tablist.querySelectorAll('button')];
+    const panelFor = tab => document.querySelector(`[role="tabpanel"][aria-labelledby="${tab.id}"]`);
+
+    function select(selected) {
+      for (const tab of tabs) {
+        const isSelected = tab === selected;
+        tab.ariaSelected = String(isSelected);
+        tab.toggleAttribute('focusgroupstart', isSelected);
+        panelFor(tab).hidden = isSelected ? false : 'until-found';
+      }
+      // Scroll only the tablist (not the page) so the selected tab, plus a peek of its neighbor, is visible
+      selected.scrollIntoView({ block: 'nearest', inline: 'nearest', container: 'nearest' });
+    }
