+      var behavior = function () { return reduceMotion.matches ? 'auto' : 'smooth'; };
+
+      /* ---------- Overflow state: arrows + edge fades ---------- */
+      function updateOverflow() {
+        var max = viewport.scrollWidth - viewport.clientWidth;
+        var overflowing = max > 1;
+        // Normalise for RTL where scrollLeft can be negative.
+        var pos = Math.abs(viewport.scrollLeft);
+        var atStart = pos <= 1;
+        var atEnd = pos >= max - 1;
+
+        prevBtn.hidden = nextBtn.hidden = !overflowing;
+        prevBtn.disabled = !overflowing || atStart;
+        nextBtn.disabled = !overflowing || atEnd;
+        tabbar.toggleAttribute('data-overflow-start', overflowing && !atStart);
+        tabbar.toggleAttribute('data-overflow-end', overflowing && !atEnd);
+      }
