+                nodes.map((el) => translateText(translator, originals.get(el), target))
+              );
+              if (id !== requestId) return; // a newer selection superseded this one
+              nodes.forEach((el, i) => { el.textContent = results[i]; });
+              done = true;
+            }
+          } catch (err) {
+            console.warn('Translation failed, using bundled text:', err);
+          } finally {
+            if (id === requestId) nodes.forEach((el) => el.classList.remove('is-translating'));
+          }
+        }
+        if (id !== requestId) return;
+
+        if (!done) done = applyFallback(target);
+
+        if (done) {
+          document.documentElement.lang = target;
+          setStatus('');
+        } else {
+          restoreOriginals();
+          document.documentElement.lang = SOURCE_LANG;
+          setStatus(`Sorry, ${languageName(target)} isn't available in this browser.`);
+        }
+      }
+
+      select.addEventListener('change', () => setLanguage(select.value));
+
+      // Restore a saved choice, otherwise suggest the visitor's browser language.
+      let initial = null;
+      try { initial = localStorage.getItem(STORAGE_KEY); } catch { /* storage blocked */ }
+      if (!initial) {
+        const preferred = (navigator.languages || [navigator.language])
+          .map((l) => (l || '').split('-')[0].toLowerCase())
+          .find((l) => select.querySelector(`option[value="${l}"]`));
+        initial = preferred || SOURCE_LANG;
+      }
+      if (!select.querySelector(`option[value="${initial}"]`)) initial = SOURCE_LANG;
+      select.value = initial;
+      if (initial !== SOURCE_LANG) setLanguage(initial, { persist: false });
+    })();
