@@ -0,0 +1,399 @@
+import React, { useEffect, useId, useRef, useState } from 'react';
+import { LanguageIcon } from '@heroicons/react/24/outline';
+
+/**
+ * On-device article translation using Chrome's built-in Translator API
+ * (and Language Detector API to figure out the source language).
+ *
+ * Every element marked with `data-translatable` on the current page is
+ * translated text-node by text-node, so inline markup (links, emphasis, …)
+ * inside article bodies is preserved. Elements (or descendants) marked with
+ * `translate="no"`, as well as `code`/`pre`, are left untouched.
+ */
+
+// Languages supported by Chrome's Translator implementation.
+const SUPPORTED_LANGUAGES = [
+  'ar', 'bg', 'bn', 'cs', 'da', 'de', 'el', 'en', 'es', 'fi', 'fr', 'he', 'hi', 'hr', 'hu',
+  'id', 'it', 'ja', 'kn', 'ko', 'lt', 'mr', 'nl', 'no', 'pl', 'pt', 'ro', 'ru', 'sk', 'sl',
+  'sv', 'ta', 'te', 'th', 'tr', 'uk', 'vi', 'zh', 'zh-Hant',
+];
+
+const STORAGE_KEY = 'devtools-times:translation-target';
+const TRANSLATABLE_SELECTOR = '[data-translatable]';
+const SKIP_SELECTOR = 'code, pre, script, style, [translate="no"]';
+const DEFAULT_SOURCE_LANGUAGE = 'en';
+const MIN_DETECTION_CONFIDENCE = 0.6;
+
+type Status =
+  | { kind: 'checking' }
+  | { kind: 'unsupported' }
+  | { kind: 'idle' }
+  | { kind: 'downloading'; progress: number }
+  | { kind: 'translating' }
+  | { kind: 'translated'; language: string }
+  | { kind: 'same-language'; language: string }
+  | { kind: 'error'; message: string };
+
+// --- Module-level state (survives client-side navigations via <ClientRouter />) ---
+
+const translatorCache = new Map<string, Promise<Translator>>();
+let detectorPromise: Promise<LanguageDetector> | null = null;
+/** Original text of every text node we have rewritten. */
+const originalText = new WeakMap<Text, string>();
+/** Text nodes currently showing a translation, so they can be restored. */
+const translatedNodes = new Set<Text>();
+/** Memoised translations per language pair, e.g. repeated teaser titles. */
+const translationMemo = new Map<string, Map<string, string>>();
+
+const displayNames =
+  typeof Intl !== 'undefined' && 'DisplayNames' in Intl
+    ? new Intl.DisplayNames(['en'], { type: 'language' })
+    : null;
+
+function languageName(code: string): string {
+  try {
+    return displayNames?.of(code) ?? code;
+  } catch {
+    return code;
+  }
+}
+
+function isTranslatorSupported(): boolean {
+  return typeof self !== 'undefined' && 'Translator' in self;
+}
+
+function getTranslatableRoots(): HTMLElement[] {
+  return Array.from(document.querySelectorAll<HTMLElement>(TRANSLATABLE_SELECTOR));
+}
+
+function collectTextNodes(root: HTMLElement): Text[] {
+  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
+    acceptNode(node) {
+      const parent = node.parentElement;
+      if (!parent || parent.closest(SKIP_SELECTOR)) return NodeFilter.FILTER_REJECT;
+      const text = originalText.get(node as Text) ?? node.nodeValue ?? '';
+      return text.trim() ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_REJECT;
+    },
+  });
+  const nodes: Text[] = [];
+  while (walker.nextNode()) nodes.push(walker.currentNode as Text);
+  return nodes;
+}
+
+/** The language the page content was authored in, as declared in the markup. */
+function declaredSourceLanguage(roots: HTMLElement[]): string {
+  const first = roots[0];
+  const declared =
+    first?.dataset.originalLang ||
+    first?.parentElement?.closest<HTMLElement>('[lang]')?.lang ||
+    document.documentElement.lang;
+  return declared || DEFAULT_SOURCE_LANGUAGE;
+}
+
+function sampleText(roots: HTMLElement[]): string {
+  let sample = '';
+  for (const root of roots) {
+    for (const node of collectTextNodes(root)) {
+      sample += ` ${originalText.get(node) ?? node.nodeValue}`;
+      if (sample.length > 1000) return sample.trim();
+    }
+  }
+  return sample.trim();
+}
+
+/**
+ * Detect the source language on-device. Only creates (and possibly downloads)
+ * the detector model when `allowDownload` is true, i.e. inside a user gesture.
+ */
+async function detectSourceLanguage(text: string, allowDownload: boolean): Promise<string | null> {
+  if (!('LanguageDetector' in self) || text.length < 20) return null;
+  try {
+    if (!detectorPromise) {
+      const availability = await LanguageDetector.availability();
+      if (availability === 'unavailable') return null;
+      if (availability !== 'available' && !allowDownload) return null;
+      detectorPromise = LanguageDetector.create();
+      detectorPromise.catch(() => {
+        detectorPromise = null;
+      });
+    }
+    const detector = await detectorPromise;
+    const [best] = await detector.detect(text);
+    if (!best || best.confidence < MIN_DETECTION_CONFIDENCE || best.detectedLanguage === 'und') return null;
+    return best.detectedLanguage;
+  } catch {
+    return null;
+  }
+}
+
+async function resolveSourceLanguage(roots: HTMLElement[], allowDownload: boolean): Promise<string> {
+  const detected = await detectSourceLanguage(sampleText(roots), allowDownload);
+  return detected ?? declaredSourceLanguage(roots);
+}
+
+function sameLanguage(a: string, b: string): boolean {
+  const norm = (code: string) => code.toLowerCase();
+  if (norm(a) === norm(b)) return true;
+  // "zh" vs "zh-Hant" are different targets; otherwise compare primary subtags.
+  if (norm(a).startsWith('zh') || norm(b).startsWith('zh')) return false;
+  return norm(a).split('-')[0] === norm(b).split('-')[0];
+}
+
+function getTranslator(
+  options: TranslatorOptions,
+  onProgress: (loaded: number) => void,
+): Promise<Translator> {
+  const key = `${options.sourceLanguage}→${options.targetLanguage}`;
+  let promise = translatorCache.get(key);
+  if (!promise) {
+    // Identical options object for availability() and create().
+    promise = Translator.create({
+      ...options,
+      monitor(m) {
+        m.addEventListener('downloadprogress', (e) => onProgress(e.loaded));
+      },
+    });
+    translatorCache.set(key, promise);
+    promise.catch(() => translatorCache.delete(key));
+  }
+  return promise;
+}
+
+function restorePage() {
+  for (const node of translatedNodes) {
+    const original = originalText.get(node);
+    if (original !== undefined) node.nodeValue = original;
+  }
+  translatedNodes.clear();
+  for (const root of getTranslatableRoots()) {
+    if (root.dataset.originalLang === undefined) continue;
+    if (root.dataset.originalLang) root.lang = root.dataset.originalLang;
+    else root.removeAttribute('lang');
+    delete root.dataset.originalLang;
+  }
+}
+
+async function translateNode(
+  node: Text,
+  translator: Translator,
+  memo: Map<string, string>,
+  signal: AbortSignal,
+) {
+  const original = originalText.get(node) ?? node.nodeValue ?? '';
+  originalText.set(node, original);
+  // Preserve surrounding whitespace, which matters between inline elements.
+  const [, leading, core, trailing] = original.match(/^(\s*)([\s\S]*?)(\s*)$/)!;
+  let translated = memo.get(core);
+  if (translated === undefined) {
+    translated = await translator.translate(core, { signal });
+    memo.set(core, translated);
+  }
+  if (signal.aborted) return;
+  node.nodeValue = `${leading}${translated}${trailing}`;
+  translatedNodes.add(node);
+}
+
+// --- Component ---
+
+export default function TranslateControl() {
+  const selectId = useId();
+  const [status, setStatus] = useState<Status>({ kind: 'checking' });
+  const [target, setTarget] = useState<string>('');
+  const abortRef = useRef<AbortController | null>(null);
+
+  const run = async (targetLanguage: string, userInitiated: boolean) => {
+    abortRef.current?.abort();
+    const controller = new AbortController();
+    abortRef.current = controller;
+    const { signal } = controller;
+
+    const roots = getTranslatableRoots();
+    if (roots.length === 0) {
+      setStatus({ kind: 'idle' });
+      return;
+    }
+
+    try {
+      // Always translate from the original text, never from a previous translation.
+      restorePage();
+      const sourceLanguage = await resolveSourceLanguage(roots, userInitiated);
+      if (signal.aborted) return;
+
+      if (sameLanguage(sourceLanguage, targetLanguage)) {
+        setStatus({ kind: 'same-language', language: targetLanguage });
+        return;
+      }
+
+      const options: TranslatorOptions = { sourceLanguage, targetLanguage };
+      const key = `${sourceLanguage}→${targetLanguage}`;
+      if (!translatorCache.has(key)) {
+        const availability = await Translator.availability(options);
+        if (signal.aborted) return;
+        if (availability === 'unavailable') {
+          setStatus({
+            kind: 'error',
+            message: `Translating ${languageName(sourceLanguage)} to ${languageName(targetLanguage)} isn't available on this device.`,
+          });
+          return;
+        }
+        // Downloading a language pack requires a user gesture.
+        if (availability !== 'available' && !userInitiated) {
+          setStatus({ kind: 'idle' });
+          return;
+        }
+        if (availability !== 'available') setStatus({ kind: 'downloading', progress: 0 });
+      }
+
+      const translator = await getTranslator(options, (loaded) => {
+        if (!signal.aborted) setStatus({ kind: 'downloading', progress: loaded });
+      });
+      if (signal.aborted) return;
+      setStatus({ kind: 'translating' });
+
+      let memo = translationMemo.get(key);
+      if (!memo) translationMemo.set(key, (memo = new Map()));
+
+      for (const root of roots) {
+        if (signal.aborted) return;
+        // The translated container must declare the target language.
+        root.dataset.originalLang = root.getAttribute('lang') ?? '';
+        root.lang = targetLanguage;
+        for (const node of collectTextNodes(root)) {
+          if (signal.aborted) return;
+          await translateNode(node, translator, memo, signal);
+        }
+      }
+      setStatus({ kind: 'translated', language: targetLanguage });
+    } catch (error) {
+      if (signal.aborted || (error as DOMException)?.name === 'AbortError') return;
+      console.error('On-device translation failed:', error);
+      restorePage();
+      const name = (error as DOMException)?.name;
+      setStatus({
+        kind: 'error',
+        message:
+          name === 'NotAllowedError'
+            ? 'Click "Translate" to download the language pack.'
+            : 'Translation failed. Please try again.',
+      });
+    }
+  };
+
+  useEffect(() => {
+    // The header is re-rendered on every client-side navigation; forget nodes
+    // from the previous page.
+    translatedNodes.clear();
+
+    if (!isTranslatorSupported()) {
+      setStatus({ kind: 'unsupported' });
+      return;
+    }
+
+    const saved = localStorage.getItem(STORAGE_KEY);
+    const browserLanguage = navigator.language?.split('-')[0];
+    const initial =
+      saved && SUPPORTED_LANGUAGES.includes(saved)
+        ? saved
+        : SUPPORTED_LANGUAGES.find((l) => l === browserLanguage && l !== 'en') ?? 'es';
+    setTarget(initial);
+    setStatus({ kind: 'idle' });
+
+    // Re-apply a previously chosen translation if the model is already on-device.
+    if (saved) void run(saved, false);
+
+    return () => abortRef.current?.abort();
+  }, []);
+
+  const handleTranslate = () => {
+    if (!target) return;
+    localStorage.setItem(STORAGE_KEY, target);
+    void run(target, true);
+  };
+
+  const handleShowOriginal = () => {
+    abortRef.current?.abort();
+    localStorage.removeItem(STORAGE_KEY);
+    restorePage();
+    setStatus({ kind: 'idle' });
+  };
+
+  const unsupported = status.kind === 'unsupported';
+  const busy = status.kind === 'downloading' || status.kind === 'translating';
+  const disabled = unsupported || status.kind === 'checking';
+  const isTranslated = status.kind === 'translated' || busy;
+
+  let message = '';
+  switch (status.kind) {
+    case 'unsupported':
+      message = "On-device translation isn't supported in this browser.";
+      break;
+    case 'downloading':
+      message = `Downloading language pack… ${Math.round(status.progress * 100)}%`;
+      break;
+    case 'translating':
+      message = 'Translating on your device…';
+      break;
+    case 'translated':
+      message = `Translated to ${languageName(status.language)} on your device.`;
+      break;
+    case 'same-language':
+      message = `This page is already in ${languageName(status.language)}.`;
+      break;
+    case 'error':
+      message = status.message;
+      break;
+  }
+
+  return (
+    <div className="flex flex-col items-end gap-1" translate="no">
+      <div className="flex items-center justify-end gap-1.5 flex-wrap">
+        <LanguageIcon className="w-5 h-5 text-gray-600 shrink-0" aria-hidden="true" />
+        <label htmlFor={selectId} className="sr-only">
+          Translate articles to
+        </label>
+        <select
+          id={selectId}
+          value={target}
+          disabled={disabled}
+          onChange={(e) => setTarget(e.target.value)}
+          className="border border-gray-300 rounded bg-white text-xs font-semibold py-1.5 px-1 max-w-32 disabled:opacity-50"
+        >
+          {target === '' && <option value="">Language</option>}
+          {SUPPORTED_LANGUAGES.map((code) => (
+            <option key={code} value={code}>
+              {languageName(code)}
+            </option>
+          ))}
+        </select>
+        <button
+          type="button"
+          onClick={handleTranslate}
+          disabled={disabled || busy}
+          className="bg-amber-400 text-gray-900 text-xs font-semibold py-2 px-3 rounded hover:bg-amber-300 disabled:opacity-50 disabled:cursor-not-allowed"
+        >
+          Translate
+        </button>
+        {isTranslated && (
+          <button
+            type="button"
+            onClick={handleShowOriginal}
+            className="text-xs font-semibold py-2 px-2 rounded text-gray-700 underline hover:text-amber-500"
+          >
+            Original
+          </button>
+        )}
+      </div>
+      <p role="status" aria-live="polite" className="text-[11px] font-normal text-gray-500 min-h-4">
+        {status.kind === 'downloading' && (
+          <progress
+            className="w-16 h-1.5 align-middle mr-1 accent-amber-400"
+            max={1}
+            value={status.progress}
+            aria-hidden="true"
+          />
+        )}
+        {message}
+      </p>
+    </div>
+  );
+}
