diff --git a/src/components/TranslateControl.tsx b/src/components/TranslateControl.tsx
new file mode 100644
index 0000000..a42a66c
--- /dev/null
+++ b/src/components/TranslateControl.tsx
@@ -0,0 +1,353 @@
+import React, { useCallback, useEffect, useId, useRef, useState } from 'react';
+import { LanguageIcon, ArrowUturnLeftIcon, XMarkIcon } from '@heroicons/react/24/outline';
+import {
+  SORTED_LANGUAGES,
+  type Availability,
+  detectLanguage,
+  findTranslatableRoots,
+  getTranslator,
+  isTranslated,
+  isTranslatorSupported,
+  languageName,
+  matchSupported,
+  pageLanguage,
+  preferredTargetLanguage,
+  rememberTargetLanguage,
+  restoreRoots,
+  sameLanguage,
+  sampleText,
+  translateRoots,
+  translatorAvailability,
+} from '../lib/translation';
+
+interface Props {
+  /**
+   * CSS selector of the element whose `[data-translatable]` content should be
+   * translated. Defaults to the whole page.
+   */
+  scope?: string;
+  /** Button label, e.g. "Translate article". */
+  label?: string;
+  /** Which edge of the button the popover aligns to. */
+  align?: 'left' | 'right';
+}
+
+type Status = 'idle' | 'downloading' | 'translating' | 'translated' | 'error';
+
+const AUTO = 'auto';
+
+export default function TranslateControl({ scope, label = 'Translate', align = 'left' }: Props) {
+  const id = useId();
+  const containerRef = useRef<HTMLDivElement>(null);
+  const abortRef = useRef<AbortController | null>(null);
+
+  const [supported, setSupported] = useState<boolean | null>(null);
+  const [open, setOpen] = useState(false);
+  const [source, setSource] = useState<string>(AUTO);
+  const [detected, setDetected] = useState<string | null>(null);
+  const [detecting, setDetecting] = useState(false);
+  const [target, setTarget] = useState<string>('es');
+  const [availability, setAvailability] = useState<Availability | null>(null);
+  const [status, setStatus] = useState<Status>('idle');
+  const [progress, setProgress] = useState(0);
+  const [message, setMessage] = useState<string | null>(null);
+  const [translatedTo, setTranslatedTo] = useState<string | null>(null);
+
+  const getRoots = useCallback(
+    () => findTranslatableRoots(scope ? document.querySelector(scope) : document),
+    [scope],
+  );
+
+  const effectiveSource = source === AUTO ? detected ?? matchSupported(pageLanguage()) ?? 'en' : source;
+  const busy = status === 'downloading' || status === 'translating';
+
+  // Feature detection + initial target (client only).
+  useEffect(() => {
+    setSupported(isTranslatorSupported());
+    setTarget(preferredTargetLanguage(pageLanguage()));
+    return () => abortRef.current?.abort();
+  }, []);
+
+  // Detect the source language when the panel is first opened.
+  useEffect(() => {
+    if (!open || !supported || source !== AUTO || detected) return;
+    let cancelled = false;
+    setDetecting(true);
+    detectLanguage(sampleText(getRoots())).then((lang) => {
+      if (cancelled) return;
+      setDetected(lang ?? matchSupported(pageLanguage()) ?? 'en');
+      setDetecting(false);
+    });
+    return () => {
+      cancelled = true;
+      setDetecting(false);
+    };
+  }, [open, supported, source, detected, getRoots]);
+
+  // Check whether a model is available for the chosen language pair.
+  useEffect(() => {
+    if (!open || !supported || sameLanguage(effectiveSource, target)) {
+      setAvailability(null);
+      return;
+    }
+    let cancelled = false;
+    translatorAvailability(effectiveSource, target).then((a) => !cancelled && setAvailability(a));
+    return () => {
+      cancelled = true;
+    };
+  }, [open, supported, effectiveSource, target]);
+
+  // Close on outside click / Escape.
+  useEffect(() => {
+    if (!open) return;
+    const onPointer = (e: PointerEvent) => {
+      if (!containerRef.current?.contains(e.target as Node)) setOpen(false);
+    };
+    const onKey = (e: KeyboardEvent) => e.key === 'Escape' && setOpen(false);
+    document.addEventListener('pointerdown', onPointer);
+    document.addEventListener('keydown', onKey);
+    return () => {
+      document.removeEventListener('pointerdown', onPointer);
+      document.removeEventListener('keydown', onKey);
+    };
+  }, [open]);
+
+  const handleTranslate = async () => {
+    const roots = getRoots();
+    if (roots.length === 0) {
+      setMessage('There is nothing to translate here.');
+      return;
+    }
+    if (sameLanguage(effectiveSource, target)) {
+      setMessage(`This content is already in ${languageName(target)}.`);
+      return;
+    }
+
+    abortRef.current?.abort();
+    const controller = new AbortController();
+    abortRef.current = controller;
+    setMessage(null);
+    setProgress(0);
+    rememberTargetLanguage(target);
+
+    try {
+      // Create the translator synchronously within the click so the browser
+      // still sees the user gesture it requires to download a model.
+      const needsDownload = availability !== 'available';
+      if (needsDownload) setStatus('downloading');
+      const translator = await getTranslator(effectiveSource, target, (loaded) => {
+        if (!controller.signal.aborted) setProgress(loaded);
+      });
+      if (controller.signal.aborted) return;
+
+      setStatus('translating');
+      setProgress(0);
+      setAvailability('available');
+      await translateRoots(roots, translator, {
+        signal: controller.signal,
+        onProgress: (done, total) => setProgress(total ? done / total : 1),
+      });
+      setStatus('translated');
+      setTranslatedTo(target);
+    } catch (err) {
+      if (controller.signal.aborted || (err instanceof DOMException && err.name === 'AbortError')) return;
+      console.error('[TranslateControl]', err);
+      setStatus('error');
+      setMessage(
+        err instanceof DOMException && err.name === 'NotAllowedError'
+          ? 'The browser blocked the language model download. Please try again.'
+          : `Couldn't translate from ${languageName(effectiveSource)} to ${languageName(target)} on this device.`,
+      );
+    } finally {
+      if (abortRef.current === controller) abortRef.current = null;
+    }
+  };
+
+  const handleRestore = () => {
+    abortRef.current?.abort();
+    abortRef.current = null;
+    restoreRoots(getRoots());
+    setStatus('idle');
+    setTranslatedTo(null);
+    setProgress(0);
+    setMessage(null);
+  };
+
+  const showRestore = status === 'translated' || busy || (status === 'error' && isTranslated(getRoots()));
+
+  return (
+    <div ref={containerRef} className="relative inline-block" translate="no" data-no-translate>
+      <button
+        type="button"
+        onClick={() => setOpen((o) => !o)}
+        aria-expanded={open}
+        aria-controls={`${id}-panel`}
+        className={`flex items-center gap-1 p-1 text-sm font-semibold rounded hover:text-amber-500 transition-colors ${
+          translatedTo ? 'text-amber-600' : 'text-gray-600'
+        }`}
+        title={label}
+      >
+        <LanguageIcon className="h-6 w-6" aria-hidden="true" />
+        <span className="hidden sm:inline">
+          {translatedTo ? languageName(translatedTo) : label}
+        </span>
+      </button>
+
+      {open && (
+        <div
+          id={`${id}-panel`}
+          role="dialog"
+          aria-label={label}
+          className={`absolute z-50 mt-2 w-72 rounded-md border border-gray-200 bg-white p-4 text-left shadow-lg ${
+            align === 'right' ? 'right-0' : 'left-0'
+          }`}
+        >
+          <div className="flex items-start justify-between mb-3">
+            <div>
+              <h2 className="text-sm font-bold text-gray-900">{label}</h2>
+              <p className="text-xs text-gray-500">Translated privately on your device.</p>
+            </div>
+            <button
+              type="button"
+              onClick={() => setOpen(false)}
+              className="p-0.5 text-gray-400 hover:text-gray-700"
+              aria-label="Close"
+            >
+              <XMarkIcon className="h-4 w-4" />
+            </button>
+          </div>
+
+          {supported === false ? (
+            <p className="text-sm text-gray-700">
+              On-device translation isn't available in this browser. It requires a browser with the
+              built-in{' '}
+              <a
+                className="text-amber-700 underline"
+                href="https://developer.chrome.com/docs/ai/translator-api"
+                target="_blank"
+                rel="noreferrer"
+              >
+                Translator API
+              </a>{' '}
+              (Chrome 138 or later on desktop).
+            </p>
+          ) : (
+            <>
+              <label className="block text-xs font-semibold text-gray-700" htmlFor={`${id}-from`}>
+                From
+              </label>
+              <select
+                id={`${id}-from`}
+                value={source}
+                disabled={busy}
+                onChange={(e) => setSource(e.target.value)}
+                className="mt-1 mb-3 w-full rounded border border-gray-300 bg-white px-2 py-1 text-sm"
+              >
+                <option value={AUTO}>
+                  {detecting
+                    ? 'Detect language…'
+                    : `Detect language${detected ? ` (${languageName(detected)})` : ''}`}
+                </option>
+                {SORTED_LANGUAGES.map((code) => (
+                  <option key={code} value={code}>
+                    {languageName(code)}
+                  </option>
+                ))}
+              </select>
+
+              <label className="block text-xs font-semibold text-gray-700" htmlFor={`${id}-to`}>
+                To
+              </label>
+              <select
+                id={`${id}-to`}
+                value={target}
+                disabled={busy}
+                onChange={(e) => setTarget(e.target.value)}
+                className="mt-1 mb-2 w-full rounded border border-gray-300 bg-white px-2 py-1 text-sm"
+              >
+                {SORTED_LANGUAGES.map((code) => (
+                  <option key={code} value={code}>
+                    {languageName(code)}
+                    {code !== 'en' ? ` — ${languageName(code, code)}` : ''}
+                  </option>
+                ))}
+              </select>
+
+              <p className="min-h-4 mb-3 text-xs text-gray-500" aria-live="polite">
+                {sameLanguage(effectiveSource, target)
+                  ? 'Choose a different language to translate to.'
+                  : availability === 'unavailable'
+                    ? 'This language pair isn’t supported on this device.'
+                    : availability === 'downloadable' || availability === 'downloading'
+                      ? 'A language pack will be downloaded once.'
+                      : availability === 'available'
+                        ? 'Ready to translate.'
+                        : ' '}
+              </p>
+
+              {busy && (
+                <div className="mb-3" aria-live="polite">
+                  <div className="flex justify-between text-xs text-gray-600 mb-1">
+                    <span>{status === 'downloading' ? 'Downloading language pack…' : 'Translating…'}</span>
+                    <span>{Math.round(progress * 100)}%</span>
+                  </div>
+                  <div
+                    className="h-1.5 w-full rounded bg-gray-200 overflow-hidden"
+                    role="progressbar"
+                    aria-valuemin={0}
+                    aria-valuemax={100}
+                    aria-valuenow={Math.round(progress * 100)}
+                  >
+                    <div
+                      className="h-full bg-amber-400 transition-[width] duration-200"
+                      style={{ width: `${progress * 100}%` }}
+                    />
+                  </div>
+                </div>
+              )}
+
+              {status === 'translated' && translatedTo && (
+                <p className="mb-3 text-xs text-green-700" aria-live="polite">
+                  Translated from {languageName(effectiveSource)} to {languageName(translatedTo)}.
+                </p>
+              )}
+
+              {message && (
+                <p className={`mb-3 text-xs ${status === 'error' ? 'text-red-700' : 'text-gray-700'}`} role="status">
+                  {message}
+                </p>
+              )}
+
+              <div className="flex gap-2">
+                <button
+                  type="button"
+                  onClick={handleTranslate}
+                  disabled={
+                    busy ||
+                    supported !== true ||
+                    availability === 'unavailable' ||
+                    sameLanguage(effectiveSource, target) ||
+                    (source === AUTO && detecting)
+                  }
+                  className="flex-1 rounded bg-gray-800 px-3 py-1.5 text-xs font-semibold text-white hover:bg-gray-700 disabled:cursor-not-allowed disabled:opacity-50"
+                >
+                  {status === 'translated' && translatedTo !== target ? 'Translate again' : 'Translate'}
+                </button>
+                {showRestore && (
+                  <button
+                    type="button"
+                    onClick={handleRestore}
+                    className="flex items-center gap-1 rounded border border-gray-300 px-3 py-1.5 text-xs font-semibold text-gray-700 hover:bg-gray-50"
+                  >
+                    <ArrowUturnLeftIcon className="h-3.5 w-3.5" aria-hidden="true" />
+                    {busy ? 'Cancel' : 'Show original'}
+                  </button>
+                )}
+              </div>
+            </>
+          )}
+        </div>
+      )}
+    </div>
+  );
+}
diff --git a/src/lib/translation.ts b/src/lib/translation.ts
new file mode 100644
index 0000000..a896503
--- /dev/null
+++ b/src/lib/translation.ts
@@ -0,0 +1,363 @@
+/**
+ * On-device translation helpers built on the browser's built-in
+ * Translator and LanguageDetector APIs (https://developer.chrome.com/docs/ai/translator-api).
+ *
+ * Text never leaves the device: the browser downloads a language model once
+ * and translates locally.
+ *
+ * Content opts in to translation with the `data-translatable` attribute.
+ * Translation works on individual text nodes so links, emphasis and other
+ * inline markup are preserved, and originals are kept so they can be restored.
+ */
+
+// ---------------------------------------------------------------------------
+// Minimal typings for the built-in AI translation APIs
+// ---------------------------------------------------------------------------
+
+export type Availability = 'unavailable' | 'downloadable' | 'downloading' | 'available';
+
+interface DownloadProgressEvent extends Event {
+  loaded: number; // 0..1
+}
+
+interface CreateMonitor extends EventTarget {
+  addEventListener(
+    type: 'downloadprogress',
+    listener: (e: DownloadProgressEvent) => void,
+  ): void;
+}
+
+interface TranslatorInstance {
+  readonly sourceLanguage: string;
+  readonly targetLanguage: string;
+  translate(input: string, options?: { signal?: AbortSignal }): Promise<string>;
+  destroy(): void;
+}
+
+interface TranslatorStatic {
+  availability(options: { sourceLanguage: string; targetLanguage: string }): Promise<Availability>;
+  create(options: {
+    sourceLanguage: string;
+    targetLanguage: string;
+    signal?: AbortSignal;
+    monitor?: (m: CreateMonitor) => void;
+  }): Promise<TranslatorInstance>;
+}
+
+interface LanguageDetectorInstance {
+  detect(
+    input: string,
+    options?: { signal?: AbortSignal },
+  ): Promise<Array<{ detectedLanguage: string; confidence: number }>>;
+  destroy(): void;
+}
+
+interface LanguageDetectorStatic {
+  availability(options?: Record<string, unknown>): Promise<Availability>;
+  create(options?: {
+    signal?: AbortSignal;
+    monitor?: (m: CreateMonitor) => void;
+  }): Promise<LanguageDetectorInstance>;
+}
+
+declare global {
+  // eslint-disable-next-line no-var
+  var Translator: TranslatorStatic | undefined;
+  // eslint-disable-next-line no-var
+  var LanguageDetector: LanguageDetectorStatic | undefined;
+}
+
+// ---------------------------------------------------------------------------
+// Languages
+// ---------------------------------------------------------------------------
+
+/** BCP 47 codes supported by Chrome's on-device translation models. */
+export const LANGUAGES = [
+  'ar', 'bg', 'bn', 'cs', 'da', 'de', 'el', 'en', 'es', 'fi', 'fr', 'hi', 'hr',
+  'hu', 'id', 'it', 'iw', 'ja', 'kn', 'ko', 'lt', 'mr', 'nl', 'no', 'pl', 'pt',
+  'ro', 'ru', 'sk', 'sl', 'sv', 'ta', 'te', 'th', 'tr', 'uk', 'vi', 'zh', 'zh-Hant',
+] as const;
+
+const displayNamesCache = new Map<string, Intl.DisplayNames | null>();
+
+export function languageName(code: string, locale = 'en'): string {
+  if (!displayNamesCache.has(locale)) {
+    try {
+      displayNamesCache.set(locale, new Intl.DisplayNames([locale], { type: 'language' }));
+    } catch {
+      displayNamesCache.set(locale, null);
+    }
+  }
+  // `iw` is the legacy code for Hebrew used by the translation models.
+  const lookup = code === 'iw' ? 'he' : code;
+  return displayNamesCache.get(locale)?.of(lookup) ?? code;
+}
+
+/** Sort languages by their English display name. */
+export const SORTED_LANGUAGES: string[] = [...LANGUAGES].sort((a, b) =>
+  languageName(a).localeCompare(languageName(b)),
+);
+
+export function pageLanguage(): string {
+  return (typeof document !== 'undefined' && document.documentElement.lang) || 'en';
+}
+
+/** Best guess at a useful default target: the reader's preferred browser language. */
+export function preferredTargetLanguage(source: string): string {
+  const stored = safeStorageGet(TARGET_STORAGE_KEY);
+  if (stored && (LANGUAGES as readonly string[]).includes(stored)) return stored;
+
+  const candidates = typeof navigator !== 'undefined' ? navigator.languages ?? [navigator.language] : [];
+  for (const lang of candidates) {
+    const match = matchSupported(lang);
+    if (match && !sameLanguage(match, source)) return match;
+  }
+  return sameLanguage(source, 'es') ? 'en' : 'es';
+}
+
+export function rememberTargetLanguage(lang: string) {
+  try {
+    localStorage.setItem(TARGET_STORAGE_KEY, lang);
+  } catch {
+    /* storage may be unavailable */
+  }
+}
+
+const TARGET_STORAGE_KEY = 'devtools-times:translate-target';
+
+function safeStorageGet(key: string): string | null {
+  try {
+    return localStorage.getItem(key);
+  } catch {
+    return null;
+  }
+}
+
+/** Map an arbitrary BCP 47 tag (e.g. "de-AT", "he", "zh-TW") to a supported code. */
+export function matchSupported(tag: string): string | null {
+  if (!tag) return null;
+  const lower = tag.toLowerCase();
+  if (lower.startsWith('zh')) {
+    return /hant|tw|hk|mo/.test(lower) ? 'zh-Hant' : 'zh';
+  }
+  const base = lower.split('-')[0];
+  const normalized = base === 'he' ? 'iw' : base === 'nb' || base === 'nn' ? 'no' : base;
+  return (LANGUAGES as readonly string[]).includes(normalized) ? normalized : null;
+}
+
+export function sameLanguage(a: string, b: string): boolean {
+  return matchSupported(a) === matchSupported(b);
+}
+
+// ---------------------------------------------------------------------------
+// Feature detection
+// ---------------------------------------------------------------------------
+
+export function isTranslatorSupported(): boolean {
+  return typeof self !== 'undefined' && 'Translator' in self && !!self.Translator;
+}
+
+export function isLanguageDetectorSupported(): boolean {
+  return typeof self !== 'undefined' && 'LanguageDetector' in self && !!self.LanguageDetector;
+}
+
+export async function translatorAvailability(source: string, target: string): Promise<Availability> {
+  if (!isTranslatorSupported()) return 'unavailable';
+  try {
+    return await self.Translator!.availability({ sourceLanguage: source, targetLanguage: target });
+  } catch {
+    return 'unavailable';
+  }
+}
+
+// ---------------------------------------------------------------------------
+// Translator / detector instances (cached per language pair)
+// ---------------------------------------------------------------------------
+
+const translatorCache = new Map<string, Promise<TranslatorInstance>>();
+
+/**
+ * Get (or create) a translator for a language pair.
+ * Must be called from a user gesture if the model still needs downloading.
+ */
+export function getTranslator(
+  source: string,
+  target: string,
+  onDownloadProgress?: (loaded: number) => void,
+): Promise<TranslatorInstance> {
+  const key = `${source}→${target}`;
+  let pending = translatorCache.get(key);
+  if (!pending) {
+    pending = self.Translator!.create({
+      sourceLanguage: source,
+      targetLanguage: target,
+      monitor(m) {
+        m.addEventListener('downloadprogress', (e) => onDownloadProgress?.(e.loaded));
+      },
+    });
+    translatorCache.set(key, pending);
+    // Don't cache failures, so the user can retry.
+    pending.catch(() => translatorCache.delete(key));
+  }
+  return pending;
+}
+
+let detectorPromise: Promise<LanguageDetectorInstance> | null = null;
+
+/**
+ * Detect the dominant language of some text. Resolves to `null` when
+ * detection isn't supported or isn't confident enough.
+ */
+export async function detectLanguage(text: string): Promise<string | null> {
+  if (!isLanguageDetectorSupported() || !text.trim()) return null;
+  try {
+    if (!detectorPromise) {
+      const availability = await self.LanguageDetector!.availability();
+      if (availability === 'unavailable') return null;
+      detectorPromise = self.LanguageDetector!.create();
+      detectorPromise.catch(() => (detectorPromise = null));
+    }
+    const detector = await detectorPromise;
+    const [best] = await detector.detect(text.slice(0, 2000));
+    if (!best || best.confidence < 0.5 || best.detectedLanguage === 'und') return null;
+    return matchSupported(best.detectedLanguage);
+  } catch {
+    return null;
+  }
+}
+
+// ---------------------------------------------------------------------------
+// DOM translation
+// ---------------------------------------------------------------------------
+
+export const TRANSLATABLE_SELECTOR = '[data-translatable]';
+
+const SKIP_TAGS = new Set(['SCRIPT', 'STYLE', 'NOSCRIPT', 'CODE', 'PRE', 'KBD', 'SAMP', 'TEXTAREA', 'SVG']);
+
+/** Original text for every node we've translated (shared across all controls). */
+const originals = new WeakMap<Text, string>();
+/** Original `lang` attribute for each translated root element. */
+const originalLang = new WeakMap<Element, string | null>();
+/** Latest translation run per text node; stale runs must not overwrite newer ones. */
+const nodeRun = new WeakMap<Text, number>();
+let runCounter = 0;
+
+/** Resolve the translatable elements inside the given scope. */
+export function findTranslatableRoots(scope: ParentNode | null | undefined = document): Element[] {
+  if (!scope) return [];
+  const roots = Array.from(scope.querySelectorAll(TRANSLATABLE_SELECTOR));
+  if (scope instanceof Element && scope.matches(TRANSLATABLE_SELECTOR)) roots.unshift(scope);
+  // Drop roots nested inside other roots so text isn't processed twice.
+  return roots.filter((el) => !roots.some((other) => other !== el && other.contains(el)));
+}
+
+function collectTextNodes(root: Element): Text[] {
+  const nodes: Text[] = [];
+  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
+    acceptNode(node) {
+      const parent = node.parentElement;
+      if (!parent) return NodeFilter.FILTER_REJECT;
+      if (SKIP_TAGS.has(parent.tagName.toUpperCase())) return NodeFilter.FILTER_REJECT;
+      if (parent.closest('[translate="no"], [data-no-translate], astro-island')) return NodeFilter.FILTER_REJECT;
+      const text = originals.get(node as Text) ?? node.nodeValue ?? '';
+      // Skip whitespace and strings without any letters (numbers, punctuation).
+      if (!/\p{L}/u.test(text)) return NodeFilter.FILTER_REJECT;
+      return NodeFilter.FILTER_ACCEPT;
+    },
+  });
+  while (walker.nextNode()) nodes.push(walker.currentNode as Text);
+  return nodes;
+}
+
+/** Sample of the original text in the given roots, used for language detection. */
+export function sampleText(roots: Element[], maxLength = 2000): string {
+  let out = '';
+  for (const root of roots) {
+    for (const node of collectTextNodes(root)) {
+      out += (originals.get(node) ?? node.nodeValue ?? '').trim() + ' ';
+      if (out.length >= maxLength) return out;
+    }
+  }
+  return out;
+}
+
+export function isTranslated(roots: Element[]): boolean {
+  return roots.some((root) => originalLang.has(root));
+}
+
+export interface TranslateOptions {
+  signal?: AbortSignal;
+  onProgress?: (done: number, total: number) => void;
+}
+
+/**
+ * Translate all text inside `roots`. Always translates from the original text,
+ * so switching target languages doesn't compound translation errors.
+ */
+export async function translateRoots(
+  roots: Element[],
+  translator: TranslatorInstance,
+  { signal, onProgress }: TranslateOptions = {},
+): Promise<void> {
+  const run = ++runCounter;
+  const nodes = roots.flatMap(collectTextNodes);
+  const total = nodes.length;
+  let done = 0;
+  onProgress?.(done, total);
+
+  for (const root of roots) {
+    if (!originalLang.has(root)) originalLang.set(root, root.getAttribute('lang'));
+    root.setAttribute('lang', translator.targetLanguage);
+  }
+
+  // Identical strings (e.g. repeated category labels) are only translated once.
+  const memo = new Map<string, Promise<string>>();
+
+  for (const node of nodes) nodeRun.set(node, run);
+
+  for (const node of nodes) {
+    signal?.throwIfAborted();
+    if (nodeRun.get(node) !== run) {
+      onProgress?.(++done, total);
+      continue;
+    }
+    if (!originals.has(node)) originals.set(node, node.nodeValue ?? '');
+    const source = originals.get(node)!;
+
+    // Preserve leading/trailing whitespace, which the translator may trim.
+    const [, lead, core, trail] = source.match(/^(\s*)([\s\S]*?)(\s*)$/)!;
+    let pending = memo.get(core);
+    if (!pending) {
+      pending = translator.translate(core, { signal });
+      memo.set(core, pending);
+    }
+    const translated = await pending;
+    if (nodeRun.get(node) === run && node.isConnected) {
+      node.nodeValue = lead + translated + trail;
+    }
+    onProgress?.(++done, total);
+  }
+}
+
+/** Restore the original text of everything inside `roots`. */
+export function restoreRoots(roots: Element[]): void {
+  for (const root of roots) {
+    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
+    while (walker.nextNode()) {
+      const node = walker.currentNode as Text;
+      // Invalidate any in-flight translation run for this node.
+      nodeRun.delete(node);
+      const original = originals.get(node);
+      if (original !== undefined) {
+        node.nodeValue = original;
+        originals.delete(node);
+      }
+    }
+    if (originalLang.has(root)) {
+      const lang = originalLang.get(root);
+      if (lang == null) root.removeAttribute('lang');
+      else root.setAttribute('lang', lang);
+      originalLang.delete(root);
+    }
+  }
+}
