+/*
+ * Context-aware teaser presentation.
+ *
+ * Sections declare their semantic context via `data-section-variant`, which
+ * sets the inherited `--section-variant` custom property. Teaser badges and
+ * action buttons query that property with container style queries, so the
+ * same teaser markup renders "featured" (badge visible, filled button) inside
+ * featured sections and "default" (badge hidden, outlined button) elsewhere.
+ */
+@layer components {
+  [data-section-variant="featured"] {
+    --section-variant: featured;
+  }
+
+  [data-section-variant="default"] {
+    --section-variant: default;
+  }
+
+  /* Default presentation (also used outside of any section). */
+  .teaser-badge {
+    display: none;
+    align-items: center;
+    gap: 0.25rem;
+    width: fit-content;
+    padding: 0.125rem 0.5rem;
+    border-radius: 9999px;
