diff --git a/server.js b/server.js
new file mode 100644
index 0000000..d8db000
--- /dev/null
+++ b/server.js
@@ -0,0 +1,250 @@
+// The Daily Grind web server.
+//
+// Serves the homepage with a per-render Email Verification Protocol nonce, and
+// handles rewards sign-up at POST /api/verify-email. When the browser supplies
+// a valid Email Verification Token, the account is activated right away.
+// Otherwise it falls back to the usual verification email.
+
+import http from 'node:http';
+import { readFile } from 'node:fs/promises';
+import { randomBytes, scrypt as scryptCb, randomUUID } from 'node:crypto';
+import { promisify } from 'node:util';
+import { verifyEmailVerificationToken } from './lib/email-verification.js';
+
+const scrypt = promisify(scryptCb);
+
+const PORT = Number(process.env.PORT) || 11222;
+// Public origin of this site. The KB-JWT `aud` must match it exactly.
+const RP_ORIGIN = (process.env.RP_ORIGIN || `http://localhost:${PORT}`).replace(/\/$/, '');
+// Chrome Origin Trial token for the Email Verification API (optional).
+const ORIGIN_TRIAL_TOKEN = process.env.EVP_ORIGIN_TRIAL_TOKEN || '';
+
+const SESSION_COOKIE = 'dg_sid';
+const NONCE_TTL_MS = 10 * 60 * 1000;
+const MAX_BODY_BYTES = 16 * 1024;
+
+const indexTemplate = await readFile(new URL('./index.html', import.meta.url), 'utf8');
+
+// ---- In-memory stores (swap for Redis/DB in production) --------------------
+
+/** sessionId -> { nonce, expiresAt } */
+const sessions = new Map();
+/** lowercased email -> account */
+const accounts = new Map();
+
+setInterval(() => {
+  const now = Date.now();
+  for (const [sid, s] of sessions) if (s.expiresAt <= now) sessions.delete(sid);
+}, 60_000).unref();
+
+function issueNonce(sid) {
+  const nonce = randomBytes(32).toString('base64url');
+  sessions.set(sid, { nonce, expiresAt: Date.now() + NONCE_TTL_MS });
+  return nonce;
+}
+
+/** Atomically read and delete the single-use nonce for this session. */
+function consumeNonce(sid) {
+  const s = sid && sessions.get(sid);
+  if (!s) return null;
+  sessions.delete(sid);
+  return s.expiresAt > Date.now() ? s.nonce : null;
+}
+
+// ---- Helpers ----------------------------------------------------------------
+
+function parseCookies(header = '') {
+  const out = {};
+  for (const part of header.split(';')) {
+    const i = part.indexOf('=');
+    if (i > 0) out[part.slice(0, i).trim()] = decodeURIComponent(part.slice(i + 1).trim());
+  }
+  return out;
+}
+
+function sessionCookie(sid) {
+  const secure = RP_ORIGIN.startsWith('https://') || new URL(RP_ORIGIN).hostname === 'localhost';
+  return `${SESSION_COOKIE}=${sid}; Path=/; HttpOnly; SameSite=Lax; Max-Age=86400${secure ? '; Secure' : ''}`;
+}
+
+function readBody(req) {
+  return new Promise((resolve, reject) => {
+    let size = 0;
+    const chunks = [];
+    req.on('data', (chunk) => {
+      size += chunk.length;
+      if (size > MAX_BODY_BYTES) {
+        reject(Object.assign(new Error('Body too large'), { status: 413 }));
+        req.destroy();
+        return;
+      }
+      chunks.push(chunk);
+    });
+    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
+    req.on('error', reject);
+  });
+}
+
+function baseHeaders() {
+  return {
+    'X-Content-Type-Options': 'nosniff',
+    'Referrer-Policy': 'strict-origin-when-cross-origin',
+    'Content-Security-Policy': "frame-ancestors 'none'",
+  };
+}
+
+function redirect(res, status) {
+  res.writeHead(303, { ...baseHeaders(), Location: `/?signup=${status}#rewards-signup`, 'Cache-Control': 'no-store' });
+  res.end();
+}
+
+// Fixed messages only; nothing user-supplied is reflected into the page.
+const STATUS_MESSAGES = {
+  verified: ['success', 'Welcome to Daily Grind Rewards! Your email address is confirmed and your account is ready. Your first drink is on us.'],
+  pending: ['info', 'Almost there! We sent a confirmation link to your inbox. Open it to activate your rewards account.'],
+  existing: ['info', 'You already have a rewards account with this email address. Sign in from My Account.'],
+  invalid: ['error', 'Please check your details and try again. Passwords need at least 8 characters.'],
+  expired: ['error', 'Your sign-up session expired. Please try again.'],
+};
+
+function renderStatus(status) {
+  const entry = STATUS_MESSAGES[status];
+  if (!entry) return '';
+  const [kind, text] = entry;
+  return `<p class="signup-status signup-status--${kind}" role="${kind === 'error' ? 'alert' : 'status'}">${text}</p>`;
+}
+
+// ---- Account actions (stubs for your real backend) --------------------------
+
+async function hashPassword(password) {
+  const salt = randomBytes(16);
+  const key = await scrypt(password.normalize('NFKC'), salt, 64);
+  return `scrypt$${salt.toString('base64url')}$${key.toString('base64url')}`;
+}
+
+async function sendTraditionalVerificationEmail(account) {
+  // TODO: Plug in your email provider. Send a one-time link or code here.
+  console.info(`[signup] EVP unavailable. Queued fallback verification email for account ${account.id}`);
+}
+
+async function sendWelcomeEmail(account) {
+  // EVP proves the user controls the account, not that mail is deliverable.
+  // Still send transactional mail and handle bounces as usual.
+  console.info(`[signup] Queued welcome email for account ${account.id}`);
+}
+
+// ---- Routes -----------------------------------------------------------------
+
+async function handleHome(req, res, url) {
+  const cookies = parseCookies(req.headers.cookie);
+  const sid = cookies[SESSION_COOKIE] && sessions.has(cookies[SESSION_COOKIE]) ? cookies[SESSION_COOKIE] : randomUUID();
+  const nonce = issueNonce(sid);
+
+  const html = indexTemplate
+    .replace('{{EVP_NONCE}}', nonce)
+    .replace('<!--SIGNUP_STATUS-->', renderStatus(url.searchParams.get('signup')));
+
+  const headers = {
+    ...baseHeaders(),
+    'Content-Type': 'text/html; charset=utf-8',
+    // Back/forward navigation must not reuse an already-consumed nonce.
+    'Cache-Control': 'no-store',
+    'Set-Cookie': sessionCookie(sid),
+  };
+  if (ORIGIN_TRIAL_TOKEN) headers['Origin-Trial'] = ORIGIN_TRIAL_TOKEN;
+  res.writeHead(200, headers);
+  res.end(req.method === 'HEAD' ? undefined : html);
+}
+
+async function handleSignup(req, res) {
+  if (!String(req.headers['content-type'] || '').startsWith('application/x-www-form-urlencoded')) {
+    res.writeHead(415, baseHeaders());
+    res.end();
+    return;
+  }
+
+  const sid = parseCookies(req.headers.cookie)[SESSION_COOKIE];
+  // Consume the nonce first so a token can never be replayed, even if later steps fail.
+  const expectedNonce = consumeNonce(sid);
+
+  const form = new URLSearchParams(await readBody(req));
+  const name = String(form.get('name') || '').trim();
+  const email = String(form.get('email') || '').trim();
+  const password = String(form.get('new-password') || '');
+  const rawToken = String(form.get('token') || '').trim();
+
+  // The nonce doubles as a CSRF check: no valid session nonce, no sign-up.
+  if (!expectedNonce) return redirect(res, 'expired');
+
+  const emailOk = email.length <= 254 && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
+  if (!name || name.length > 100 || !emailOk || password.length < 8 || password.length > 256) {
+    return redirect(res, 'invalid');
+  }
+
+  let emailVerified = false;
+  if (rawToken) {
+    try {
+      await verifyEmailVerificationToken({ rawToken, submittedEmail: email, expectedNonce, expectedAudience: RP_ORIGIN });
+      emailVerified = true;
+    } catch (err) {
+      console.warn('[signup] Email verification token check failed:', err?.message || err);
+    }
+  }
+
+  const key = email.toLowerCase();
+  const existing = accounts.get(key);
+  if (existing) {
+    // Only reveal that an account exists to someone who has proven they own the address.
+    if (emailVerified) return redirect(res, 'existing');
+    console.info(`[signup] Duplicate sign-up attempt for account ${existing.id}`);
+    // TODO: Email the owner a "someone tried to sign up" notice instead.
+    return redirect(res, 'pending');
+  }
+
+  const account = {
+    id: randomUUID(),
+    name,
+    email,
+    passwordHash: await hashPassword(password),
+    emailVerified,
+    emailVerifiedVia: emailVerified ? 'email-verification-protocol' : null,
+    createdAt: new Date().toISOString(),
+  };
+  accounts.set(key, account);
+
+  if (emailVerified) {
+    // Fast path: ownership was proven cryptographically, so skip the OTP/magic link.
+    await sendWelcomeEmail(account);
+    return redirect(res, 'verified');
+  }
+
+  // Fallback path: unsupported browser, signed-out provider, or invalid token.
+  await sendTraditionalVerificationEmail(account);
+  return redirect(res, 'pending');
+}
+
+const server = http.createServer(async (req, res) => {
+  try {
+    const url = new URL(req.url, RP_ORIGIN);
+    if ((req.method === 'GET' || req.method === 'HEAD') && (url.pathname === '/' || url.pathname === '/index.html')) {
+      return await handleHome(req, res, url);
+    }
+    if (url.pathname === '/api/verify-email') {
+      if (req.method !== 'POST') {
+        res.writeHead(405, { ...baseHeaders(), Allow: 'POST' });
+        return res.end();
+      }
+      return await handleSignup(req, res);
+    }
+    res.writeHead(404, { ...baseHeaders(), 'Content-Type': 'text/plain; charset=utf-8' });
+    res.end('Not found');
+  } catch (err) {
+    console.error(err);
+    if (!res.headersSent) res.writeHead(err.status || 500, baseHeaders());
+    res.end();
+  }
+});
+
+server.listen(PORT, () => {
+  console.log(`The Daily Grind listening on ${RP_ORIGIN} (port ${PORT})`);
+});

