--- /dev/null
+++ b/lib/accounts.js
@@ -0,0 +1,79 @@
+'use strict';
+
+/**
+ * Minimal rewards-account store persisted to a JSON file. Writes are serialised and atomic
+ * (write temp file + rename). Swap for a real database in production.
+ */
+
+const crypto = require('node:crypto');
+const fs = require('node:fs');
+const path = require('node:path');
+
+const DRINKS = ['latte', 'cappuccino', 'espresso', 'cold-brew', 'drip', 'tea', 'other'];
+const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+
+function validateSignup(body) {
+  const errors = [];
+  const firstName = typeof body.firstName === 'string' ? body.firstName.trim() : '';
+  const email = typeof body.email === 'string' ? body.email.trim() : '';
+  const favoriteDrink = typeof body.favoriteDrink === 'string' && body.favoriteDrink ? body.favoriteDrink : null;
+  const birthday = typeof body.birthday === 'string' && body.birthday ? body.birthday : null;
+
+  if (!firstName || firstName.length > 50) errors.push('Please enter your first name (up to 50 characters).');
+  if (!EMAIL_RE.test(email) || email.length > 254) errors.push('Please enter a valid email address.');
+  if (favoriteDrink && !DRINKS.includes(favoriteDrink)) errors.push('Please choose a drink from the list.');
+  if (birthday && !/^(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])$/.test(birthday)) errors.push('Birthday must be MM-DD.');
+  if (body.acceptTerms !== true) errors.push('Please accept the Rewards terms.');
+
+  return {
+    errors,
+    value: { firstName, email, favoriteDrink, birthday, marketingOptIn: body.marketingOptIn === true },
+  };
+}
+
+function createAccountStore(file) {
+  let accounts = [];
+  try {
+    accounts = JSON.parse(fs.readFileSync(file, 'utf8'));
+  } catch {
+    accounts = [];
+  }
+  let queue = Promise.resolve();
+
+  const normalise = (email) => email.toLowerCase();
+
+  function persist() {
+    fs.mkdirSync(path.dirname(file), { recursive: true });
+    const tmp = `${file}.${process.pid}.tmp`;
+    fs.writeFileSync(tmp, JSON.stringify(accounts, null, 2), { mode: 0o600 });
+    fs.renameSync(tmp, file);
+  }
+
+  /** Create an account; resolves to the account, or null if the email is already registered. */
+  function create(data) {
+    const run = queue.then(() => {
+      if (accounts.some((a) => normalise(a.email) === normalise(data.email))) return null;
+      const account = {
+        id: crypto.randomUUID(),
+        ...data,
+        emailVerified: true,
+        stars: 25, // welcome bonus
+        createdAt: new Date().toISOString(),
+      };
+      accounts.push(account);
+      try {
+        persist();
+      } catch (err) {
+        accounts.pop();
+        throw err;
+      }
+      return account;
+    });
+    queue = run.catch(() => {});
+    return run;
+  }
+
+  return { create };
+}
+
+module.exports = { createAccountStore, validateSignup, DRINKS };
diff --git a/lib/evp-verifier.js b/lib/evp-verifier.js
new file mode 100644
index 0000000..e464f7e
--- /dev/null
+++ b/lib/evp-verifier.js
@@ -0,0 +1,286 @@
+'use strict';
+
+/**
+ * Server-side verifier for the Email Verification Protocol (EVP).
+ *
+ * Spec references:
+ *   - WICG explainer: https://github.com/WICG/email-verification-protocol
+ *   - IETF draft:     draft-hardt-email-verification (§2.8, §5.3, §6.5)
+ *
+ * Presentation format received from the browser:  <EVT-JWT>~<KB-JWT>
+ *
+ *   EVT    – signed by the email domain's issuer. Header {alg, kid, typ:"evt+jwt"},
+ *            payload {iss, iat, cnf:{jwk}, email, email_verified:true}.
+ *   KB-JWT – signed by the browser's ephemeral key (EVT cnf.jwk). Header {alg, typ:"kb+jwt"},
+ *            payload {aud: RP origin, nonce, iat, sd_hash: b64url(sha256("<EVT>~"))}.
+ *
+ * Network access (DNS TXT + HTTPS metadata/JWKS fetches) is injected so the verifier can be
+ * unit-tested; see lib/net.js for the hardened production implementations.
+ */
+
+const crypto = require('node:crypto');
+const { domainToASCII } = require('node:url');
+
+// Fully-specified algorithms only. The polymorphic "EdDSA", "none" and MAC algs are rejected.
+const ALGS = {
+  Ed25519: { kty: 'OKP', crv: 'Ed25519', hash: null },
+  ES256: { kty: 'EC', crv: 'P-256', hash: 'sha256', dsaEncoding: 'ieee-p1363' },
+  ES384: { kty: 'EC', crv: 'P-384', hash: 'sha384', dsaEncoding: 'ieee-p1363' },
+  RS256: { kty: 'RSA', hash: 'sha256' },
+  PS256: { kty: 'RSA', hash: 'sha256', padding: crypto.constants.RSA_PKCS1_PSS_PADDING, saltLength: 32 },
+};
+
+const PUBLIC_JWK_MEMBERS = { OKP: ['kty', 'crv', 'x'], EC: ['kty', 'crv', 'x', 'y'], RSA: ['kty', 'n', 'e'] };
+
+class EvpError extends Error {
+  constructor(code, message) {
+    super(message);
+    this.name = 'EvpError';
+    this.code = code;
+  }
+}
+
+const fail = (code, message) => {
+  throw new EvpError(code, message);
+};
+
+const B64URL_RE = /^[A-Za-z0-9_-]*$/;
+
+function b64urlDecode(part, what) {
+  if (typeof part !== 'string' || !B64URL_RE.test(part)) fail('malformed_token', `${what} is not base64url`);
+  return Buffer.from(part, 'base64url');
+}
+
+function parseJwt(jwt, what) {
+  const parts = jwt.split('.');
+  if (parts.length !== 3 || parts.some((p) => p.length === 0)) fail('malformed_token', `${what} is not a compact JWS`);
+  let header;
+  let payload;
+  try {
+    header = JSON.parse(b64urlDecode(parts[0], `${what} header`).toString('utf8'));
+    payload = JSON.parse(b64urlDecode(parts[1], `${what} payload`).toString('utf8'));
+  } catch (err) {
+    if (err instanceof EvpError) throw err;
+    fail('malformed_token', `${what} header/payload is not valid JSON`);
+  }
+  if (!isPlainObject(header) || !isPlainObject(payload)) fail('malformed_token', `${what} header/payload must be objects`);
+  return {
+    header,
+    payload,
+    signingInput: Buffer.from(`${parts[0]}.${parts[1]}`, 'ascii'),
+    signature: b64urlDecode(parts[2], `${what} signature`),
+  };
+}
+
+function isPlainObject(v) {
+  return v !== null && typeof v === 'object' && !Array.isArray(v);
+}
+
+function importPublicJwk(jwk, alg, what) {
+  const spec = ALGS[alg];
+  if (!spec) fail('unsupported_alg', `${what}: unsupported or forbidden alg "${alg}"`);
+  if (!isPlainObject(jwk)) fail('bad_key', `${what}: key is not a JWK object`);
+  if (jwk.kty !== spec.kty) fail('bad_key', `${what}: key type ${jwk.kty} does not match alg ${alg}`);
+  if (spec.crv && jwk.crv !== spec.crv) fail('bad_key', `${what}: curve ${jwk.crv} does not match alg ${alg}`);
+  if (jwk.alg !== undefined && jwk.alg !== alg) fail('bad_key', `${what}: key is restricted to alg ${jwk.alg}`);
+  if (jwk.use !== undefined && jwk.use !== 'sig') fail('bad_key', `${what}: key is not a signing key`);
+
+  const pub = {};
+  for (const m of PUBLIC_JWK_MEMBERS[spec.kty]) {
+    if (typeof jwk[m] !== 'string') fail('bad_key', `${what}: JWK is missing "${m}"`);
+    pub[m] = jwk[m];
+  }
+  let key;
+  try {
+    key = crypto.createPublicKey({ key: pub, format: 'jwk' });
+  } catch {
+    fail('bad_key', `${what}: JWK could not be imported`);
+  }
+  if (spec.kty === 'RSA' && key.asymmetricKeyDetails.modulusLength < 2048) fail('bad_key', `${what}: RSA key too small`);
+  return key;
+}
+
+function verifySignature(jws, key, alg) {
+  const spec = ALGS[alg];
+  const opts = { key };
+  if (spec.dsaEncoding) opts.dsaEncoding = spec.dsaEncoding;
+  if (spec.padding) {
+    opts.padding = spec.padding;
+    opts.saltLength = spec.saltLength;
+  }
+  try {
+    return crypto.verify(spec.hash, jws.signingInput, opts, jws.signature);
+  } catch {
+    return false;
+  }
+}
+
+/** Split the email domain out of an address and normalise it to lowercase A-labels. */
+function emailDomain(email) {
+  const at = email.lastIndexOf('@');
+  if (at < 1 || at === email.length - 1) fail('bad_email', 'email address has no domain');
+  const ascii = domainToASCII(email.slice(at + 1).replace(/\.$/, '').toLowerCase());
+  if (!ascii || !/^[a-z0-9-]+(\.[a-z0-9-]+)+$/.test(ascii)) fail('bad_email', 'email domain is invalid');
+  return ascii;
+}
+
+const HOSTNAME_RE = /^(?=.{1,253}$)([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)(\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)+$/;
+
+/**
+ * Look up `_email-verification.<domain>` and return the issuer origin `https://<host>`.
+ * TXT records are arrays of chunks; chunks of one record are concatenated.
+ */
+async function discoverIssuer(domain, resolveTxt) {
+  let records;
+  try {
+    records = await resolveTxt(`_email-verification.${domain}`);
+  } catch {
+    fail('issuer_discovery_failed', `no _email-verification TXT record for ${domain}`);
+  }
+  const issuers = new Set();
+  for (const chunks of records || []) {
+    const txt = (Array.isArray(chunks) ? chunks.join('') : String(chunks)).trim();
+    const m = /^iss=(.+)$/.exec(txt);
+    if (m) issuers.add(m[1].trim().toLowerCase());
+  }
+  if (issuers.size !== 1) fail('issuer_discovery_failed', `expected exactly one iss= TXT record for ${domain}`);
+  const host = [...issuers][0];
+  if (!HOSTNAME_RE.test(host)) fail('issuer_discovery_failed', 'issuer in DNS is not a valid hostname');
+  return `https://${host}`;
+}
+
+function assertHttpsUrl(value, what) {
+  let url;
+  try {
+    url = new URL(value);
+  } catch {
+    fail('issuer_metadata_invalid', `${what} is not a URL`);
+  }
+  if (url.protocol !== 'https:' || url.username || url.password) fail('issuer_metadata_invalid', `${what} must be an https URL`);
+  return url;
+}
+
+/** Create a verifier bound to an RP origin and injected network primitives. */
+function createEvpVerifier({
+  rpOrigin,
+  resolveTxt,
+  fetchJson,
+  now = () => Date.now(),
+  maxEvtAgeSec = 300,
+  maxKbAgeSec = 300,
+  clockSkewSec = 60,
+  keyCacheTtlMs = 5 * 60 * 1000,
+}) {
+  if (!rpOrigin || new URL(rpOrigin).origin !== rpOrigin) throw new Error('rpOrigin must be a bare origin, e.g. https://dailygrind.example');
+  const keyCache = new Map(); // issuer -> { expires, keys }
+
+  async function loadIssuerKeys(issuer, { force = false } = {}) {
+    const cached = keyCache.get(issuer);
+    if (!force && cached && cached.expires > now()) return cached.keys;
+
+    const metadata = await fetchJson(`${issuer}/.well-known/email-verification`).catch(() =>
+      fail('issuer_metadata_invalid', 'could not fetch issuer metadata'),
+    );
+    if (!isPlainObject(metadata)) fail('issuer_metadata_invalid', 'issuer metadata is not an object');
+    if (metadata.issuer !== issuer) fail('issuer_metadata_invalid', 'metadata "issuer" does not match the issuer identifier');
+    const jwksUrl = assertHttpsUrl(metadata.jwks_uri, 'jwks_uri');
+
+    const jwks = await fetchJson(jwksUrl.href).catch(() => fail('issuer_metadata_invalid', 'could not fetch issuer JWKS'));
+    if (!isPlainObject(jwks) || !Array.isArray(jwks.keys)) fail('issuer_metadata_invalid', 'JWKS has no "keys" array');
+
+    const keys = { list: jwks.keys.filter(isPlainObject), algs: metadata.signing_alg_values_supported, fetchedAt: now() };
+    keyCache.set(issuer, { expires: now() + keyCacheTtlMs, keys });
+    return keys;
+  }
+
+  async function findIssuerKey(issuer, kid, alg) {
+    let keys = await loadIssuerKeys(issuer);
+    let jwk = keys.list.find((k) => k.kid === kid);
+    // Unknown kid: the issuer may have rotated keys. Refetch, but at most every 30s per issuer
+    // so that tokens with made-up kids cannot be used to hammer the issuer.
+    if (!jwk && now() - keys.fetchedAt > 30 * 1000) {
+      keys = await loadIssuerKeys(issuer, { force: true });
+      jwk = keys.list.find((k) => k.kid === kid);
+    }
+    if (Array.isArray(keys.algs) && !keys.algs.includes(alg)) fail('unsupported_alg', `issuer does not advertise alg ${alg}`);
+    if (!jwk) fail('unknown_key', `issuer has no key with kid "${kid}"`);
+    return importPublicJwk(jwk, alg, 'issuer key');
+  }
+
+  function checkIat(iat, maxAge, what) {
+    const t = Math.floor(now() / 1000);
+    if (!Number.isInteger(iat)) fail('bad_claims', `${what} iat missing or not an integer`);
+    if (iat > t + clockSkewSec) fail('token_expired', `${what} iat is in the future`);
+    if (iat < t - maxAge - clockSkewSec) fail('token_expired', `${what} is too old`);
+  }
+
+  /**
+   * Verify an EVT+KB presentation.
+   * @param {string} token         `<EVT>~<KB-JWT>` as delivered by the browser
+   * @param {object} expect
+   * @param {string} expect.nonce  the nonce the RP issued for this session (single-use)
+   * @param {string} expect.email  the email address submitted in the form
+   * @returns {Promise<{email: string, issuer: string, isPrivateEmail: boolean}>}
+   */
+  async function verify(token, { nonce, email }) {
+    if (typeof token !== 'string' || token.length === 0 || token.length > 16384) fail('malformed_token', 'token missing or too large');
+    if (typeof nonce !== 'string' || nonce.length < 16) fail('bad_nonce', 'no nonce issued for this session');
+    if (typeof email !== 'string' || email.length === 0) fail('bad_email', 'email missing');
+
+    // ---- Parse "<EVT>~<KB-JWT>" (exactly one tilde, no disclosures) ----
+    const parts = token.split('~');
+    if (parts.length !== 2 || !parts[0] || !parts[1]) fail('malformed_token', 'expected <EVT>~<KB-JWT>');
+    const [evtJwt, kbJwt] = parts;
+    const evt = parseJwt(evtJwt, 'EVT');
+    const kb = parseJwt(kbJwt, 'KB-JWT');
+
+    // ---- EVT header / claims (§5.3 steps 1-3) ----
+    const { alg: evtAlg, kid, typ: evtTyp } = evt.header;
+    if (typeof evtAlg !== 'string' || !ALGS[evtAlg]) fail('unsupported_alg', `EVT alg "${evtAlg}" is not allowed`);
+    if (typeof kid !== 'string' || !kid) fail('malformed_token', 'EVT header has no kid');
+    if (evtTyp !== 'evt+jwt') fail('malformed_token', 'EVT typ must be "evt+jwt"');
+    if (evt.header.crit !== undefined) fail('malformed_token', 'EVT crit header is not supported');
+
+    const { iss, iat: evtIat, cnf, email: evtEmail, email_verified: emailVerified } = evt.payload;
+    if (typeof iss !== 'string') fail('bad_claims', 'EVT iss missing');
+    if (!isPlainObject(cnf) || !isPlainObject(cnf.jwk)) fail('bad_claims', 'EVT cnf.jwk missing');
+    if (typeof evtEmail !== 'string') fail('bad_claims', 'EVT email missing');
+    if (emailVerified !== true) fail('bad_claims', 'EVT email_verified is not true'); // §5.3 step 8
+
+    // The token must be for the address the customer actually typed into our form.
+    if (evtEmail !== email) fail('email_mismatch', 'verified email does not match the submitted email');
+
+    // ---- KB-JWT checks (§6.5) — cheap, local; done before any network I/O ----
+    const kbAlg = kb.header.alg;
+    if (kb.header.typ !== 'kb+jwt') fail('malformed_token', 'KB-JWT typ must be "kb+jwt"');
+    if (kb.header.crit !== undefined) fail('malformed_token', 'KB-JWT crit header is not supported');
+    if (typeof cnf.jwk.alg !== 'string' || kbAlg !== cnf.jwk.alg) fail('bad_kb', 'KB-JWT alg does not match cnf.jwk.alg');
+    const { aud, nonce: kbNonce, iat: kbIat, sd_hash: sdHash } = kb.payload;
+    if (aud !== rpOrigin) fail('bad_kb', 'KB-JWT aud is not this site');
+    if (typeof kbNonce !== 'string' || !timingSafeEqualStr(kbNonce, nonce)) fail('bad_nonce', 'KB-JWT nonce does not match');
+    checkIat(kbIat, maxKbAgeSec, 'KB-JWT');
+    const expectedSdHash = crypto.createHash('sha256').update(`${evtJwt}~`, 'ascii').digest('base64url');
+    if (typeof sdHash !== 'string' || !timingSafeEqualStr(sdHash, expectedSdHash)) fail('bad_kb', 'KB-JWT sd_hash does not match the EVT');
+    const holderKey = importPublicJwk(cnf.jwk, kbAlg, 'cnf.jwk');
+    if (!verifySignature(kb, holderKey, kbAlg)) fail('bad_signature', 'KB-JWT signature is invalid');
+
+    // ---- EVT freshness, DNS issuer binding and issuer signature (§5.3 steps 4-7) ----
+    checkIat(evtIat, maxEvtAgeSec, 'EVT');
+    const expectedIssuer = await discoverIssuer(emailDomain(evtEmail), resolveTxt);
+    if (iss !== expectedIssuer) fail('issuer_mismatch', 'EVT iss is not the issuer authorised in DNS for this email domain');
+    const issuerKey = await findIssuerKey(iss, kid, evtAlg);
+    if (!verifySignature(evt, issuerKey, evtAlg)) fail('bad_signature', 'EVT signature is invalid');
+
+    return { email: evtEmail, issuer: iss, isPrivateEmail: evt.payload.is_private_email === true };
+  }
+
+  return { verify };
+}
+
+function timingSafeEqualStr(a, b) {
+  const ab = Buffer.from(a);
+  const bb = Buffer.from(b);
+  return ab.length === bb.length && crypto.timingSafeEqual(ab, bb);
+}
+
+module.exports = { createEvpVerifier, EvpError, emailDomain, ALGS };
diff --git a/lib/net.js b/lib/net.js
new file mode 100644
index 0000000..f367401
--- /dev/null
+++ b/lib/net.js
@@ -0,0 +1,95 @@
+'use strict';
+
+/**
+ * Hardened network primitives for EVP verification.
+ *
+ * The issuer host comes from a DNS record controlled by whoever owns the email domain, and the
+ * jwks_uri comes from that issuer — both are attacker-influenced. To avoid SSRF we:
+ *   - only speak HTTPS on port 443 (cert validation on),
+ *   - resolve the hostname ourselves and refuse private / loopback / link-local / reserved IPs,
+ *     pinning the connection to the vetted address (no DNS-rebinding window),
+ *   - refuse redirects, cap response size and enforce a timeout.
+ */
+
+const dns = require('node:dns');
+const https = require('node:https');
+const net = require('node:net');
+
+const MAX_BYTES = 64 * 1024;
+const TIMEOUT_MS = 5000;
+
+const blockList = new net.BlockList();
+for (const [addr, prefix] of [
+  ['0.0.0.0', 8], ['10.0.0.0', 8], ['100.64.0.0', 10], ['127.0.0.0', 8], ['169.254.0.0', 16],
+  ['172.16.0.0', 12], ['192.0.0.0', 24], ['192.0.2.0', 24], ['192.168.0.0', 16], ['198.18.0.0', 15],
+  ['198.51.100.0', 24], ['203.0.113.0', 24], ['224.0.0.0', 4], ['240.0.0.0', 4],
+]) blockList.addSubnet(addr, prefix, 'ipv4');
+for (const [addr, prefix] of [
+  ['::', 128], ['::1', 128], ['64:ff9b::', 96], ['100::', 64], ['2001:db8::', 32],
+  ['fc00::', 7], ['fe80::', 10], ['ff00::', 8],
+]) blockList.addSubnet(addr, prefix, 'ipv6');
+
+function isPublicAddress(address, family) {
+  // IPv4-mapped IPv6 (::ffff:a.b.c.d) is judged by its embedded IPv4 address.
+  const mapped = /^::ffff:(\d+\.\d+\.\d+\.\d+)$/i.exec(address);
+  if (mapped) return isPublicAddress(mapped[1], 4);
+  if (family === 6 && /^::ffff:/i.test(address)) return false; // hex-form mapped address: refuse
+  return !blockList.check(address, family === 6 ? 'ipv6' : 'ipv4');
+}
+
+/** dns.lookup replacement that only ever yields public addresses. */
+function safeLookup(hostname, options, callback) {
+  dns.lookup(hostname, { all: true, verbatim: true }, (err, addresses) => {
+    if (err) return callback(err);
+    const ok = addresses.filter((a) => isPublicAddress(a.address, a.family));
+    if (ok.length === 0) return callback(new Error(`refusing to connect to non-public address for ${hostname}`));
+    if (options && options.all) return callback(null, ok);
+    return callback(null, ok[0].address, ok[0].family);
+  });
+}
+
+function fetchJson(urlString) {
+  return new Promise((resolve, reject) => {
+    const url = new URL(urlString);
+    if (url.protocol !== 'https:' || (url.port && url.port !== '443') || url.username || url.password) {
+      return reject(new Error('only https://host/ URLs on port 443 are allowed'));
+    }
+    if (net.isIP(url.hostname.replace(/^\[|\]$/g, ''))) return reject(new Error('IP-literal hosts are not allowed'));
+
+    const req = https.get(
+      url,
+      { lookup: safeLookup, timeout: TIMEOUT_MS, headers: { accept: 'application/json' }, agent: false },
+      (res) => {
+        if (res.statusCode !== 200) {
+          res.resume();
+          return reject(new Error(`unexpected HTTP ${res.statusCode} from ${url.host}`));
+        }
+        const chunks = [];
+        let size = 0;
+        res.on('data', (c) => {
+          size += c.length;
+          if (size > MAX_BYTES) {
+            req.destroy(new Error('response too large'));
+            return;
+          }
+          chunks.push(c);
+        });
+        res.on('end', () => {
+          try {
+            resolve(JSON.parse(Buffer.concat(chunks).toString('utf8')));
+          } catch {
+            reject(new Error('response is not JSON'));
+          }
+        });
+        res.on('error', reject);
+      },
+    );
+    req.on('timeout', () => req.destroy(new Error('request timed out')));
+    req.on('error', reject);
+  });
+}
+
+const resolver = new dns.promises.Resolver({ timeout: TIMEOUT_MS, tries: 2 });
+const resolveTxt = (name) => resolver.resolveTxt(name);
+
+module.exports = { fetchJson, resolveTxt, isPublicAddress };
