--- /dev/null
+++ b/public/js/rewards-signup.js
@@ -0,0 +1,143 @@
+/*
+ * Daily Grind Rewards sign-up — email verification via the Email Verification Protocol.
+ *
+ * Flow:
+ *   1. The server renders the page with a single-use nonce on the hidden
+ *      `autocomplete="email-verification-token"` input.
+ *   2. When the customer picks their email from autofill, a supporting browser obtains a
+ *      signed Email Verification Token from their email provider, binds it to the nonce and
+ *      this origin (EVT+KB) and fills it into the hidden input before submit.
+ *   3. We POST {email, token} to /api/email-verification/verify; the server checks it
+ *      cryptographically (DNS-authorised issuer, issuer signature, nonce, audience, freshness).
+ *   4. With the session marked verified, we POST the profile to /api/rewards/signup.
+ *
+ * No one-time passcode or magic link is ever emailed.
+ */
+(() => {
+  'use strict';
+
+  const form = document.getElementById('rewards-signup-form');
+  if (!form) return;
+
+  const emailInput = document.getElementById('rewards-email');
+  const tokenInput = document.getElementById('rewards-email-token');
+  const statusEl = document.getElementById('rewards-status');
+  const verifiedBadge = document.getElementById('rewards-email-verified');
+  const submitBtn = document.getElementById('rewards-submit');
+
+  // Token delivered via the alternative event-based API shape, if a browser implements it.
+  let eventToken = '';
+  emailInput.addEventListener('emailverified', (e) => {
+    if (typeof e.presentationToken === 'string') eventToken = e.presentationToken;
+  });
+
+  // Changing the email invalidates any token obtained for the previous address.
+  emailInput.addEventListener('input', () => {
+    eventToken = '';
+    verifiedBadge.classList.remove('show');
+  });
+
+  function setStatus(message, kind = '') {
+    statusEl.textContent = message;
+    statusEl.className = `form-status${kind ? ` ${kind}` : ''}`;
+  }
+
+  function currentNonce() {
+    // The `nonce` content attribute is hidden from script once parsed; the IDL property keeps it.
+    return tokenInput.nonce || tokenInput.getAttribute('nonce') || '';
+  }
+
+  function setNonce(nonce) {
+    if (typeof nonce !== 'string' || !nonce) return;
+    tokenInput.setAttribute('nonce', nonce);
+    tokenInput.nonce = nonce;
+  }
+
+  /** Imperative API shape under discussion; best-effort and silently ignored where unsupported. */
+  async function requestTokenImperatively() {
+    if (!navigator.credentials || typeof navigator.credentials.get !== 'function') return '';
+    try {
+      const cred = await navigator.credentials.get({ mediation: 'optional', email: { nonce: currentNonce() } });
+      return cred && typeof cred.token === 'string' ? cred.token : '';
+    } catch {
+      return '';
+    }
+  }
+
+  async function postJson(url, body) {
+    const res = await fetch(url, {
+      method: 'POST',
+      credentials: 'same-origin',
+      headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
+      body: JSON.stringify(body),
+    });
+    let data = {};
+    try {
+      data = await res.json();
+    } catch {
+      /* non-JSON error */
+    }
+    if (data.nonce) setNonce(data.nonce);
+    return { ok: res.ok, status: res.status, data };
+  }
+
+  function clientValidate() {
+    if (!form.checkValidity()) {
+      const firstInvalid = form.querySelector(':invalid');
+      if (firstInvalid) firstInvalid.focus();
+      if (firstInvalid && firstInvalid.id === 'rewards-terms') return 'Please accept the Rewards terms.';
+      if (firstInvalid && firstInvalid.id === 'rewards-birthday') return 'Birthday must be in MM-DD format.';
+      return 'Please complete the highlighted field.';
+    }
+    return '';
+  }
+
+  form.addEventListener('submit', async (e) => {
+    e.preventDefault();
+    const problem = clientValidate();
+    if (problem) return setStatus(problem, 'error');
+
+    const email = emailInput.value.trim();
+    submitBtn.disabled = true;
+    setStatus('Verifying your email…');
+
+    try {
+      const token = tokenInput.value || eventToken || (await requestTokenImperatively());
+      // Tokens are single-use; never resubmit one.
+      tokenInput.value = '';
+      eventToken = '';
+
+      const verify = await postJson('/api/email-verification/verify', { email, token });
+      if (!verify.ok) {
+        verifiedBadge.classList.remove('show');
+        setStatus(verify.data.message || 'We could not verify this email address.', 'error');
+        if (verify.data.error === 'no_token') emailInput.focus();
+        return;
+      }
+      verifiedBadge.classList.add('show');
+      setStatus('Email verified. Creating your account…');
+
+      const fd = new FormData(form);
+      const signup = await postJson('/api/rewards/signup', {
+        firstName: String(fd.get('firstName') || '').trim(),
+        email,
+        favoriteDrink: String(fd.get('favoriteDrink') || ''),
+        birthday: String(fd.get('birthday') || '').trim(),
+        marketingOptIn: fd.get('marketingOptIn') === 'on',
+        acceptTerms: fd.get('acceptTerms') === 'on',
+      });
+      if (!signup.ok) {
+        setStatus(signup.data.message || 'Sorry, we could not create your account.', 'error');
+        return;
+      }
+      const { firstName, stars } = signup.data.account;
+      form.reset();
+      verifiedBadge.classList.remove('show');
+      setStatus(`Welcome to Daily Grind Rewards, ${firstName}! ${stars} bonus stars are waiting for you.`, 'success');
+    } catch {
+      setStatus('Network error — please check your connection and try again.', 'error');
+    } finally {
+      submitBtn.disabled = false;
+    }
+  });
+})();
