+'use strict';
+
+/**
+ * The Daily Grind web server (zero dependencies, Node >= 20).
+ *
+ *   GET  /                               homepage, rendered with a per-session EVP nonce
+ *   POST /api/email-verification/verify  verify an Email Verification Protocol token (EVT+KB)
+ *   POST /api/rewards/signup             create a rewards account for a verified email
+ *
+ * Env:
+ *   PORT       listen port (default 11222)
+ *   RP_ORIGIN  public origin of the site, e.g. https://dailygrind.example. This is the
+ *              audience the browser binds tokens to, so it MUST match what users see in
+ *              the address bar. Defaults to http://localhost:$PORT.
+ */
+
+const crypto = require('node:crypto');
+const fs = require('node:fs');
+const http = require('node:http');
+const path = require('node:path');
+
+const { createEvpVerifier, EvpError } = require('./lib/evp-verifier');
+const { fetchJson, resolveTxt } = require('./lib/net');
+const { createAccountStore, validateSignup } = require('./lib/accounts');
+
+const PORT = Number(process.env.PORT) || 11222;
+const RP_ORIGIN = new URL(process.env.RP_ORIGIN || `http://localhost:${PORT}`).origin;
+const SECURE_COOKIES = RP_ORIGIN.startsWith('https:');
+const PUBLIC_DIR = path.join(__dirname, 'public');
+
+const SESSION_TTL_MS = 30 * 60 * 1000;
+const NONCE_TTL_MS = 10 * 60 * 1000;
+const VERIFIED_EMAIL_TTL_MS = 15 * 60 * 1000;
+const MAX_SESSIONS = 50_000;
+const MAX_BODY_BYTES = 16 * 1024;
+
+const verifier = createEvpVerifier({ rpOrigin: RP_ORIGIN, resolveTxt, fetchJson });
+const accounts = createAccountStore(path.join(__dirname, 'data', 'accounts.json'));
+
+/* ------------------------------------------------------------------ sessions & nonces */
+
+const sessions = new Map(); // sid -> { expires, nonce, nonceExpires, verified: {email, issuer, expires} | null }
+
+function randomToken(bytes = 32) {
+  return crypto.randomBytes(bytes).toString('base64url');
+}
+
+function parseCookies(header = '') {
+  const out = {};
+  for (const part of header.split(';')) {
+    const i = part.indexOf('=');
+    if (i > 0) out[part.slice(0, i).trim()] = part.slice(i + 1).trim();
+  }
+  return out;
+}
+
+function getSession(req, res, { create }) {
+  const sid = parseCookies(req.headers.cookie).dg_sid;
+  let session = sid && sessions.get(sid);
+  if (session && session.expires < Date.now()) {
+    sessions.delete(sid);
+    session = null;
+  }
+  if (!session) {
+    if (!create) return null;
+    if (sessions.size >= MAX_SESSIONS) sessions.delete(sessions.keys().next().value); // evict oldest
+    const newSid = randomToken();
+    session = { id: newSid, nonce: null, nonceExpires: 0, verified: null };
+    sessions.set(newSid, session);
+  }
+  session.expires = Date.now() + SESSION_TTL_MS;
+  res.setHeader(
+    'Set-Cookie',
+    `dg_sid=${session.id}; Path=/; HttpOnly; SameSite=Lax; Max-Age=${SESSION_TTL_MS / 1000}${SECURE_COOKIES ? '; Secure' : ''}`,
+  );
+  return session;
+}
+
+/** Issue a fresh single-use nonce for the session (replacing any previous one). */
+function issueNonce(session) {
+  session.nonce = randomToken();
+  session.nonceExpires = Date.now() + NONCE_TTL_MS;
+  return session.nonce;
+}
+
+/** Take the session's nonce, invalidating it so it can never be replayed. */
+function consumeNonce(session) {
+  const { nonce, nonceExpires } = session;
+  session.nonce = null;
+  session.nonceExpires = 0;
+  return nonce && nonceExpires > Date.now() ? nonce : null;
+}
+
+setInterval(() => {
+  const t = Date.now();
+  for (const [sid, s] of sessions) if (s.expires < t) sessions.delete(sid);
+}, 60_000).unref();
+
+/* ------------------------------------------------------------------ rate limiting */
+
+const buckets = new Map(); // key -> { count, reset }
+function rateLimited(key, limit, windowMs) {
+  const t = Date.now();
+  let b = buckets.get(key);
+  if (!b || b.reset < t) {
+    if (buckets.size > 100_000) buckets.clear();
+    b = { count: 0, reset: t + windowMs };
+    buckets.set(key, b);
+  }
+  b.count += 1;
+  return b.count > limit;
+}
+
+/* ------------------------------------------------------------------ http helpers */
+
+const SECURITY_HEADERS = {
+  'Content-Security-Policy':
+    "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' https://images.unsplash.com; " +
+    "connect-src 'self'; form-action 'self'; frame-ancestors 'none'; base-uri 'none'; object-src 'none'",
+  'X-Content-Type-Options': 'nosniff',
+  'Referrer-Policy': 'strict-origin-when-cross-origin',
+  'X-Frame-Options': 'DENY',
+  ...(SECURE_COOKIES ? { 'Strict-Transport-Security': 'max-age=31536000; includeSubDomains' } : {}),
+};
+
+function send(res, status, body, type = 'application/json; charset=utf-8') {
+  const payload = typeof body === 'string' || Buffer.isBuffer(body) ? body : JSON.stringify(body);
+  res.writeHead(status, { ...SECURITY_HEADERS, 'Content-Type': type, 'Cache-Control': 'no-store' });
+  res.end(payload);
+}
+
+function readJson(req) {
+  return new Promise((resolve, reject) => {
+    if (!/^application\/json\b/i.test(req.headers['content-type'] || '')) return reject(Object.assign(new Error('expected JSON'), { status: 415 }));
+    const chunks = [];
+    let size = 0;
+    req.on('data', (c) => {
+      size += c.length;
+      if (size > MAX_BODY_BYTES) {
+        reject(Object.assign(new Error('body too large'), { status: 413 }));
+        req.destroy();
+      } else chunks.push(c);
+    });
+    req.on('end', () => {
+      try {
+        const body = JSON.parse(Buffer.concat(chunks).toString('utf8'));
+        if (body === null || typeof body !== 'object' || Array.isArray(body)) throw new Error();
+        resolve(body);
+      } catch {
+        reject(Object.assign(new Error('invalid JSON'), { status: 400 }));
+      }
+    });
+    req.on('error', reject);
+  });
+}
+
+/** CSRF defence for state-changing requests: require a same-origin Origin header. */
+function sameOrigin(req) {
+  return req.headers.origin === RP_ORIGIN;
+}
+
+const escapeAttr = (s) => String(s).replace(/[&"<>']/g, (c) => `&#${c.charCodeAt(0)};`);
+
+/* ------------------------------------------------------------------ routes */
+
+const indexTemplate = fs.readFileSync(path.join(PUBLIC_DIR, 'index.html'), 'utf8');
+
+function renderIndex(req, res) {
+  const session = getSession(req, res, { create: true });
+  const nonce = issueNonce(session);
+  send(res, 200, indexTemplate.replaceAll('{{EVP_NONCE}}', escapeAttr(nonce)), 'text/html; charset=utf-8');
+}
+
+async function handleVerify(req, res) {
+  const session = getSession(req, res, { create: false });
+  if (!session) return send(res, 401, { error: 'session_expired', message: 'Your session expired. Please reload the page.' });
+  if (rateLimited(`verify:${req.socket.remoteAddress}`, 20, 10 * 60 * 1000)) {
+    return send(res, 429, { error: 'rate_limited', message: 'Too many attempts. Please try again later.' });
+  }
+  const body = await readJson(req);
+  const email = typeof body.email === 'string' ? body.email.trim() : '';
+  const token = typeof body.token === 'string' ? body.token.trim() : '';
+
+  // The nonce is single-use: consume it now, whatever the outcome, and hand back a new one.
+  const nonce = consumeNonce(session);
+  const nextNonce = issueNonce(session);
+  session.verified = null;
+
+  if (!token) {
+    return send(res, 400, {
+      error: 'no_token',
+      message: "Your browser didn't provide an email verification token. Choose your email from the browser's autofill suggestions, or use a browser that supports email verification.",
+      nonce: nextNonce,
+    });
+  }
+  if (!nonce) return send(res, 400, { error: 'bad_nonce', message: 'This form expired. Please try again.', nonce: nextNonce });
+
+  try {
+    const result = await verifier.verify(token, { nonce, email });
+    session.verified = { email: result.email, issuer: result.issuer, expires: Date.now() + VERIFIED_EMAIL_TTL_MS };
+    return send(res, 200, { verified: true, email: result.email, nonce: nextNonce });
+  } catch (err) {
+    if (!(err instanceof EvpError)) throw err;
+    console.warn(`[evp] verification failed: ${err.code}: ${err.message}`);
+    return send(res, 400, { verified: false, error: err.code, message: 'We could not verify this email address.', nonce: nextNonce });
+  }
+}
+
+async function handleSignup(req, res) {
+  const session = getSession(req, res, { create: false });
+  if (!session) return send(res, 401, { error: 'session_expired', message: 'Your session expired. Please reload the page.' });
+  const body = await readJson(req);
+  const { value, errors } = validateSignup(body);
+  if (errors.length) return send(res, 400, { error: 'invalid_input', message: errors.join(' ') });
+
+  const v = session.verified;
+  if (!v || v.expires < Date.now() || v.email !== value.email) {
+    return send(res, 403, { error: 'email_not_verified', message: 'Please verify your email address first.' });
+  }
+  session.verified = null; // one account per verification
+
+  const created = await accounts.create({ ...value, emailVerifiedVia: 'email-verification-protocol', emailIssuer: v.issuer });
+  if (!created) return send(res, 409, { error: 'already_registered', message: 'A rewards account already exists for this email. Try signing in instead.' });
+  return send(res, 201, { ok: true, account: { firstName: created.firstName, email: created.email, stars: created.stars } });
+}
+
+const STATIC_TYPES = { '.css': 'text/css; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.svg': 'image/svg+xml', '.png': 'image/png', '.jpg': 'image/jpeg', '.ico': 'image/x-icon' };
+
+function serveStatic(req, res, pathname) {
+  let decoded;
+  try {
+    decoded = decodeURIComponent(pathname);
+  } catch {
+    return send(res, 400, 'Bad request', 'text/plain');
+  }
+  const file = path.join(PUBLIC_DIR, path.normalize(decoded));
+  const type = STATIC_TYPES[path.extname(file)];
+  if (!file.startsWith(PUBLIC_DIR + path.sep) || !type) return send(res, 404, 'Not found', 'text/plain');
+  fs.readFile(file, (err, data) => {
+    if (err) return send(res, 404, 'Not found', 'text/plain');
+    res.writeHead(200, { ...SECURITY_HEADERS, 'Content-Type': type, 'Cache-Control': 'public, max-age=300' });
+    res.end(data);
+  });
+}
+
+const server = http.createServer(async (req, res) => {
+  const { pathname } = new URL(req.url, 'http://localhost');
+  try {
+    if (req.method === 'GET' && (pathname === '/' || pathname === '/index.html')) return renderIndex(req, res);
+    if (req.method === 'POST' && (pathname === '/api/email-verification/verify' || pathname === '/api/rewards/signup')) {
+      if (!sameOrigin(req)) return send(res, 403, { error: 'bad_origin' });
+      return pathname === '/api/rewards/signup' ? await handleSignup(req, res) : await handleVerify(req, res);
+    }
+    if (req.method === 'GET' || req.method === 'HEAD') return serveStatic(req, res, pathname);
+    return send(res, 405, { error: 'method_not_allowed' });
+  } catch (err) {
+    if (err.status) return send(res, err.status, { error: 'bad_request', message: err.message });
+    console.error(err);
+    if (!res.headersSent) send(res, 500, { error: 'server_error', message: 'Something went wrong.' });
+  }
+});
+
+if (require.main === module) {
+  server.listen(PORT, () => console.log(`The Daily Grind listening on :${PORT} (RP origin ${RP_ORIGIN})`));
+}
+
+module.exports = { server };
diff --git a/test/evp-verifier.test.js b/test/evp-verifier.test.js
new file mode 100644
index 0000000..61c144e
--- /dev/null
+++ b/test/evp-verifier.test.js
@@ -0,0 +1,171 @@
+'use strict';
+
+const test = require('node:test');
+const assert = require('node:assert/strict');
+const crypto = require('node:crypto');
+const { createEvpVerifier, EvpError } = require('../lib/evp-verifier');
+
+const RP = 'https://dailygrind.example';
+const ISSUER = 'https://issuer.mail.example';
+const NONCE = 'n-0S6_WzA2Mj1234567890abcdef';
+const EMAIL = 'ada@mail.example';
+const NOW = 1_800_000_000_000;
+
+const b64 = (o) => Buffer.from(JSON.stringify(o)).toString('base64url');
+const issuerKeys = crypto.generateKeyPairSync('ed25519');
+const holderKeys = crypto.generateKeyPairSync('ec', { namedCurve: 'P-256' });
+const issuerJwk = { ...issuerKeys.publicKey.export({ format: 'jwk' }), kid: 'k1', alg: 'Ed25519', use: 'sig' };
+const holderJwk = { ...holderKeys.publicKey.export({ format: 'jwk' }), alg: 'ES256' };
+
+function signJwt(header, payload, alg, key) {
+  const input = `${b64(header)}.${b64(payload)}`;
+  const sig =
+    alg === 'Ed25519'
+      ? crypto.sign(null, Buffer.from(input), key)
+      : crypto.sign('sha256', Buffer.from(input), { key, dsaEncoding: 'ieee-p1363' });
+  return `${input}.${sig.toString('base64url')}`;
+}
+
+function mint({ evtHeader = {}, evt = {}, kbHeader = {}, kb = {}, issuerKey = issuerKeys.privateKey, holderKey = holderKeys.privateKey } = {}) {
+  const t = Math.floor(NOW / 1000);
+  const evtJwt = signJwt(
+    { alg: 'Ed25519', kid: 'k1', typ: 'evt+jwt', ...evtHeader },
+    { iss: ISSUER, iat: t, cnf: { jwk: holderJwk }, email: EMAIL, email_verified: true, ...evt },
+    'Ed25519',
+    issuerKey,
+  );
+  const sdHash = crypto.createHash('sha256').update(`${evtJwt}~`).digest('base64url');
+  const kbJwt = signJwt({ alg: 'ES256', typ: 'kb+jwt', ...kbHeader }, { aud: RP, nonce: NONCE, iat: t, sd_hash: sdHash, ...kb }, 'ES256', holderKey);
+  return `${evtJwt}~${kbJwt}`;
+}
+
+function makeVerifier(overrides = {}) {
+  const fetched = [];
+  const docs = {
+    [`${ISSUER}/.well-known/email-verification`]: { issuer: ISSUER, issuance_endpoint: `${ISSUER}/issue`, jwks_uri: `${ISSUER}/jwks`, signing_alg_values_supported: ['Ed25519'] },
+    [`${ISSUER}/jwks`]: { keys: [issuerJwk] },
+    ...overrides.docs,
+  };
+  const verifier = createEvpVerifier({
+    rpOrigin: RP,
+    now: () => NOW,
+    resolveTxt: async (name) => {
+      if (overrides.txt) return overrides.txt(name);
+      if (name === '_email-verification.mail.example') return [['iss=issuer.mail.example']];
+      throw Object.assign(new Error('ENOTFOUND'), { code: 'ENOTFOUND' });
+    },
+    fetchJson: async (url) => {
+      fetched.push(url);
+      if (!(url in docs)) throw new Error('404');
+      return docs[url];
+    },
+  });
+  return { verifier, fetched };
+}
+
+async function rejects(promise, code) {
+  await assert.rejects(promise, (err) => err instanceof EvpError && err.code === code);
+}
+
+test('accepts a valid EVT+KB', async () => {
+  const { verifier } = makeVerifier();
+  const r = await verifier.verify(mint(), { nonce: NONCE, email: EMAIL });
+  assert.deepEqual(r, { email: EMAIL, issuer: ISSUER, isPrivateEmail: false });
+});
+
+test('rejects wrong nonce (replay / cross-session)', async () => {
+  const { verifier, fetched } = makeVerifier();
+  await rejects(verifier.verify(mint(), { nonce: 'some-other-nonce-value-123', email: EMAIL }), 'bad_nonce');
+  assert.equal(fetched.length, 0, 'no network I/O before cheap local checks pass');
+});
+
+test('rejects token minted for another site', async () => {
+  const { verifier } = makeVerifier();
+  await rejects(verifier.verify(mint({ kb: { aud: 'https://evil.example' } }), { nonce: NONCE, email: EMAIL }), 'bad_kb');
+});
+
+test('rejects email mismatch with the submitted form value', async () => {
+  const { verifier } = makeVerifier();
+  await rejects(verifier.verify(mint(), { nonce: NONCE, email: 'someone@mail.example' }), 'email_mismatch');
+});
+
+test('rejects email_verified !== true', async () => {
+  const { verifier } = makeVerifier();
+  await rejects(verifier.verify(mint({ evt: { email_verified: 'true' } }), { nonce: NONCE, email: EMAIL }), 'bad_claims');
+});
+
+test('rejects tampered EVT (sd_hash no longer matches)', async () => {
+  const { verifier } = makeVerifier();
+  const [evt, kb] = mint().split('~');
+  const [h, , s] = evt.split('.');
+  const forged = `${h}.${b64({ iss: ISSUER, iat: NOW / 1000, cnf: { jwk: holderJwk }, email: EMAIL, email_verified: true, x: 1 })}.${s}`;
+  await rejects(verifier.verify(`${forged}~${kb}`, { nonce: NONCE, email: EMAIL }), 'bad_kb');
+});
+
+test('rejects EVT signed by a key the issuer does not publish', async () => {
+  const { verifier } = makeVerifier();
+  const rogue = crypto.generateKeyPairSync('ed25519').privateKey;
+  await rejects(verifier.verify(mint({ issuerKey: rogue }), { nonce: NONCE, email: EMAIL }), 'bad_signature');
+});
+
+test('rejects KB-JWT not signed by cnf key', async () => {
+  const { verifier } = makeVerifier();
+  const rogue = crypto.generateKeyPairSync('ec', { namedCurve: 'P-256' }).privateKey;
+  await rejects(verifier.verify(mint({ holderKey: rogue }), { nonce: NONCE, email: EMAIL }), 'bad_signature');
+});
+
+test('rejects issuer not authorised in DNS for the email domain', async () => {
+  const { verifier } = makeVerifier({ txt: async () => [['iss=attacker.example']] });
+  await rejects(verifier.verify(mint(), { nonce: NONCE, email: EMAIL }), 'issuer_mismatch');
+});
+
+test('rejects domains without a DNS delegation record', async () => {
+  const { verifier } = makeVerifier({ txt: async () => { throw new Error('ENOTFOUND'); } });
+  await rejects(verifier.verify(mint(), { nonce: NONCE, email: EMAIL }), 'issuer_discovery_failed');
+});
+
+test('rejects metadata whose issuer field does not match', async () => {
+  const { verifier } = makeVerifier({ docs: { [`${ISSUER}/.well-known/email-verification`]: { issuer: 'https://other.example', jwks_uri: `${ISSUER}/jwks` } } });
+  await rejects(verifier.verify(mint(), { nonce: NONCE, email: EMAIL }), 'issuer_metadata_invalid');
+});
+
+test('rejects non-https jwks_uri', async () => {
+  const { verifier } = makeVerifier({ docs: { [`${ISSUER}/.well-known/email-verification`]: { issuer: ISSUER, jwks_uri: 'http://169.254.169.254/jwks' } } });
+  await rejects(verifier.verify(mint(), { nonce: NONCE, email: EMAIL }), 'issuer_metadata_invalid');
+});
+
+test('rejects stale tokens and future-dated tokens', async () => {
+  const { verifier } = makeVerifier();
+  const old = Math.floor(NOW / 1000) - 3600;
+  await rejects(verifier.verify(mint({ kb: { iat: old } }), { nonce: NONCE, email: EMAIL }), 'token_expired');
+  await rejects(verifier.verify(mint({ evt: { iat: old } }), { nonce: NONCE, email: EMAIL }), 'token_expired');
+  await rejects(verifier.verify(mint({ kb: { iat: Math.floor(NOW / 1000) + 3600 } }), { nonce: NONCE, email: EMAIL }), 'token_expired');
+});
+
+test('rejects alg none / polymorphic EdDSA / HMAC', async () => {
+  const { verifier } = makeVerifier();
+  for (const alg of ['none', 'EdDSA', 'HS256']) {
+    await rejects(verifier.verify(mint({ evtHeader: { alg } }), { nonce: NONCE, email: EMAIL }), 'unsupported_alg');
+  }
+});
+
+test('rejects KB alg that differs from cnf.jwk.alg', async () => {
+  const { verifier } = makeVerifier();
+  await rejects(verifier.verify(mint({ kbHeader: { alg: 'ES384' } }), { nonce: NONCE, email: EMAIL }), 'bad_kb');
+});
+
+test('rejects wrong typ headers and malformed tokens', async () => {
+  const { verifier } = makeVerifier();
+  await rejects(verifier.verify(mint({ evtHeader: { typ: 'JWT' } }), { nonce: NONCE, email: EMAIL }), 'malformed_token');
+  await rejects(verifier.verify(mint({ kbHeader: { typ: 'JWT' } }), { nonce: NONCE, email: EMAIL }), 'malformed_token');
+  await rejects(verifier.verify('a.b.c', { nonce: NONCE, email: EMAIL }), 'malformed_token');
+  await rejects(verifier.verify(`${mint()}~extra`, { nonce: NONCE, email: EMAIL }), 'malformed_token');
+});
+
+test('unknown kid triggers at most one JWKS refetch', async () => {
+  const { verifier, fetched } = makeVerifier();
+  await verifier.verify(mint(), { nonce: NONCE, email: EMAIL });
+  const before = fetched.length;
+  await rejects(verifier.verify(mint({ evtHeader: { kid: 'nope' } }), { nonce: NONCE, email: EMAIL }), 'unknown_key');
+  assert.equal(fetched.length, before, 'cache is fresh (<30s), so no refetch');
+});
