@@ -0,0 +1,20 @@
+'use strict';
+
+const test = require('node:test');
+const assert = require('node:assert/strict');
+const { isPublicAddress, fetchJson } = require('../lib/net');
+
+test('blocks private, loopback, link-local and metadata addresses', () => {
+  for (const [a, f] of [['127.0.0.1', 4], ['10.1.2.3', 4], ['169.254.169.254', 4], ['192.168.1.1', 4], ['172.20.0.1', 4], ['::1', 6], ['fd00::1', 6], ['fe80::1', 6], ['::ffff:127.0.0.1', 6]]) {
+    assert.equal(isPublicAddress(a, f), false, a);
+  }
+  assert.equal(isPublicAddress('93.184.216.34', 4), true);
+  assert.equal(isPublicAddress('2606:4700::1111', 6), true);
+});
+
+test('refuses non-https and IP-literal URLs', async () => {
+  await assert.rejects(fetchJson('http://issuer.example/jwks'));
+  await assert.rejects(fetchJson('https://127.0.0.1/jwks'));
+  await assert.rejects(fetchJson('https://[::1]/jwks'));
+  await assert.rejects(fetchJson('https://issuer.example:8443/jwks'));
+});

