+    super();
+    const root = this.shadowRoot ?? this.attachShadow({ mode: 'open' });
+    root.adoptedStyleSheets = [sheet];
+    if (!root.firstChild) root.append(template.content.cloneNode(true));
+
+    this.#button = root.querySelector('.favorite');
+    this.#titleSlot = root.querySelector('slot[name="title"]');
+
+    this.#button.addEventListener('click', () => this.toggleFavorite());
+    this.#titleSlot.addEventListener('slotchange', () => this.#updateLabel());
+  }
+
+  connectedCallback() {
+    const id = this.productId;
+    if (id) this.#setFavorited(favoritesStore.read().has(id), { silent: true });
+    this.#updateLabel();
+  }
+
+  get productId() {
+    return this.getAttribute('product-id') ?? '';
+  }
+
+  get tags() {
+    return (this.getAttribute('tags') ?? '').split(/\s+/).filter(Boolean);
+  }
+
+  get name() {
+    return this.#titleSlot
+      .assignedElements()
+      .map((el) => el.textContent.trim())
+      .join(' ');
+  }
+
+  get favorited() {
+    return this.#favorited;
+  }
+
+  set favorited(value) {
+    this.#setFavorited(Boolean(value));
+  }
+
+  toggleFavorite() {
+    this.#setFavorited(!this.#favorited);
+  }
+
+  /** `silent` restores state (e.g. from storage) without persisting or emitting. */
+  #setFavorited(on, { silent = false } = {}) {
+    const changed = on !== this.#favorited;
+    this.#favorited = on;
+    this.#render();
+    if (!changed || silent) return;
+
+    if (this.productId) favoritesStore.set(this.productId, on);
+    this.dispatchEvent(
+      new CustomEvent('favorite-change', {
+        bubbles: true,
+        composed: true,
+        detail: { productId: this.productId, favorited: on },
+      }),
+    );
+  }
+
+  #render() {
+    this.#button.setAttribute('aria-pressed', String(this.#favorited));
+    try {
+      this.#favorited
+        ? this.#internals.states.add('favorited')
+        : this.#internals.states.delete('favorited');
+    } catch {
+      // CustomStateSet unsupported — fall back to a reflected attribute hook.
+      this.toggleAttribute('data-favorited', this.#favorited);
+    }
+  }
+
+  #updateLabel() {
+    const name = this.name || 'this drink';
+    this.#button.setAttribute('aria-label', `Save ${name} to favorites`);
+  }
+}
+
+if (!customElements.get('coffee-card')) {
+  customElements.define('coffee-card', CoffeeCard);
+}
diff --git a/components/coffee-collection.js b/components/coffee-collection.js
new file mode 100644
index 0000000..fa21a14
--- /dev/null
+++ b/components/coffee-collection.js
@@ -0,0 +1,209 @@
+/**
+ * <coffee-collection> — a responsive grid of <coffee-card> elements with
+ * tag filters and a polite live status ("Showing 2 of 3 drinks · 1 favorite").
+ *
+ * Filter buttons are generated automatically from the `tags` attribute of the
+ * slotted cards. Without JS the cards are still laid out by the page stylesheet.
+ *
+ * Attributes:
+ *   label        Accessible name for the filter group (default "Filter drinks")
+ *   item-label   Plural noun used in the status message (default "drinks")
+ *
+ * Events:
+ *   "filter-change"  detail: { tag }  ("all" when cleared)
+ *
+ * Theming: --dg-primary, --dg-accent, --dg-collection-min (card min width)
+ * Parts:   filters, filter, status, grid
+ */
+
+const sheet = new CSSStyleSheet();
+sheet.replaceSync(`
+  :host {
+    --_primary: var(--dg-primary, #4e342e);
+    --_accent: var(--dg-accent, #ffab40);
+    --_min: var(--dg-collection-min, 250px);
+    display: block;
+  }
+  :host([hidden]) { display: none; }
+
+  .toolbar {
+    display: flex;
+    flex-wrap: wrap;
+    align-items: center;
+    justify-content: space-between;
+    gap: 0.75rem 1rem;
+    margin-block: 1.25rem;
+  }
+  .filters {
+    display: flex;
+    flex-wrap: wrap;
+    gap: 0.5rem;
+  }
+  .filters:empty { display: none; }
+
+  button {
+    min-block-size: 2.25rem;
+    padding: 0.35rem 1rem;
+    border: 2px solid var(--_primary);
+    border-radius: 999px;
+    background: transparent;
+    color: var(--_primary);
+    font: inherit;
+    font-size: 0.9rem;
+    cursor: pointer;
+    transition: background 0.2s, color 0.2s;
+  }
+  button:hover { background: color-mix(in srgb, var(--_primary) 10%, transparent); }
+  button[aria-pressed="true"] {
+    background: var(--_primary);
+    color: #fff;
+  }
+  button:focus-visible {
+    outline: 3px solid var(--_accent);
+    outline-offset: 2px;
+  }
+  @media (forced-colors: active) {
+    button[aria-pressed="true"] { outline: 2px solid Highlight; }
+  }
+
+  .status {
+    margin: 0;
+    font-size: 0.9rem;
+    opacity: 0.85;
+  }
+
+  .grid {
+    display: grid;
+    grid-template-columns: repeat(auto-fill, minmax(min(var(--_min), 100%), 1fr));
+    gap: 20px;
+  }
+  .empty {
+    grid-column: 1 / -1;
+    text-align: center;
+    padding: 2rem 1rem;
+  }
+`);
+
+const template = document.createElement('template');
+template.innerHTML = `
+  <div class="toolbar">
+    <div class="filters" part="filters" role="group"></div>
+    <p class="status" part="status"></p>
+  </div>
+  <div class="grid" part="grid">
+    <slot></slot>
+    <p class="empty" hidden>No matches for this filter.</p>
+  </div>
+`;
+
+const humanize = (tag) => {
+  const text = tag.replace(/[-_]+/g, ' ');
+  return text.charAt(0).toUpperCase() + text.slice(1);
+};
+
+export class CoffeeCollection extends HTMLElement {
+  #filters;
+  #status;
+  #empty;
+  #slot;
+  #activeTag = 'all';
+
+  constructor() {
+    super();
+    const root = this.shadowRoot ?? this.attachShadow({ mode: 'open' });
+    root.adoptedStyleSheets = [sheet];
+    if (!root.firstChild) root.append(template.content.cloneNode(true));
+
+    this.#filters = root.querySelector('.filters');
+    this.#status = root.querySelector('.status');
+    this.#empty = root.querySelector('.empty');
+    this.#slot = root.querySelector('slot');
+
+    this.#slot.addEventListener('slotchange', () => this.#refresh());
+    this.#filters.addEventListener('click', (e) => {
+      const button = e.target.closest('button[data-tag]');
+      if (button) this.filter(button.dataset.tag);
+    });
+    this.addEventListener('favorite-change', () => this.#updateStatus());
+  }
+
+  async connectedCallback() {
+    this.#filters.setAttribute('aria-label', this.getAttribute('label') ?? 'Filter drinks');
+    // Cards restore their favorite state on upgrade; wait so the first status is accurate.
+    await customElements.whenDefined('coffee-card');
+    this.#refresh();
+    // Only become a live region after the initial render, so page load isn't announced.
+    this.#status.setAttribute('role', 'status');
+  }
+
+  get cards() {
+    return this.#slot.assignedElements().filter((el) => el.localName === 'coffee-card');
+  }
+
+  get activeTag() {
+    return this.#activeTag;
+  }
+
+  /** Show only cards carrying `tag` ("all" shows every card). */
+  filter(tag = 'all') {
+    const known = tag === 'all' || this.#allTags().includes(tag);
+    this.#activeTag = known ? tag : 'all';
+    this.#apply();
+    this.dispatchEvent(
+      new CustomEvent('filter-change', { bubbles: true, detail: { tag: this.#activeTag } }),
+    );
+  }
+
+  #allTags() {
+    return [...new Set(this.cards.flatMap((card) => card.tags ?? []))];
+  }
+
+  #refresh() {
+    const tags = this.#allTags();
+    if (!tags.includes(this.#activeTag)) this.#activeTag = 'all';
+
+    const buttons = tags.length
+      ? ['all', ...tags].map((tag) => {
+          const button = document.createElement('button');
+          button.type = 'button';
+          button.setAttribute('part', 'filter');
+          button.dataset.tag = tag;
+          button.textContent = tag === 'all' ? 'All' : humanize(tag);
+          return button;
+        })
+      : [];
+
+    // Preserve keyboard focus across re-renders.
+    const focusedTag = this.shadowRoot.activeElement?.dataset?.tag;
+    this.#filters.replaceChildren(...buttons);
+    if (focusedTag) this.#filters.querySelector(`[data-tag="${CSS.escape(focusedTag)}"]`)?.focus();
+
+    this.#apply();
+  }
+
+  #apply() {
+    for (const button of this.#filters.querySelectorAll('button')) {
+      button.setAttribute('aria-pressed', String(button.dataset.tag === this.#activeTag));
+    }
+    for (const card of this.cards) {
+      card.hidden = this.#activeTag !== 'all' && !(card.tags ?? []).includes(this.#activeTag);
+    }
+    this.#updateStatus();
+  }
+
+  #updateStatus() {
+    const cards = this.cards;
+    const visible = cards.filter((card) => !card.hidden).length;
+    const favorites = cards.filter((card) => card.favorited).length;
+    const noun = this.getAttribute('item-label') ?? 'drinks';
+
+    this.#empty.hidden = visible > 0 || cards.length === 0;
+    let message = `Showing ${visible} of ${cards.length} ${noun}`;
+    if (favorites) message += ` · ${favorites} ${favorites === 1 ? 'favorite' : 'favorites'}`;
+    this.#status.textContent = message;
+  }
+}
+
+if (!customElements.get('coffee-collection')) {
+  customElements.define('coffee-collection', CoffeeCollection);
+}
