+/**
+ * <site-nav> — sticky site navigation that collapses into a disclosure menu
+ * when its own width is narrow (container query, not viewport).
+ *
+ * Light DOM content:
+ *   <a slot="brand">               Logo / home link
+ *   <a> … (default slot)           Navigation links (direct children)
+ *   data-variant="outline"         Optional emphasis style on a link
+ *
+ * Attributes:
+ *   label   Accessible name of the navigation landmark (default "Main")
+ *
+ * Behavior: the menu button exposes aria-expanded; Escape and outside clicks
+ * close the menu, Escape returns focus to the button. The link matching the
+ * current URL gets aria-current="page".
+ *
+ * Theming: --dg-primary, --dg-accent, --dg-nav-fg
+ * Parts:   nav, toggle, menu
+ */
+
+const sheet = new CSSStyleSheet();
+sheet.replaceSync(`
+  :host {
+    --_bg: var(--dg-primary, #4e342e);
+    --_fg: var(--dg-nav-fg, #fff);
+    --_accent: var(--dg-accent, #ffab40);
+    display: block;
+    position: sticky;
+    top: 0;
+    z-index: 1000;
+    container: site-nav / inline-size;
+  }
+
+  nav {
+    display: flex;
+    flex-wrap: wrap;
+    align-items: center;
+    justify-content: space-between;
+    gap: 0.5rem 1.5rem;
+    padding: 1rem 5%;
+    background: var(--_bg);
+    color: var(--_fg);
+  }
+
+  ::slotted([slot="brand"]) {
+    color: inherit;
+    font-size: 1.5rem;
+    font-weight: bold;
+    letter-spacing: 1px;
+    text-decoration: none;
+  }
+
+  .menu {
+    display: flex;
+    flex-wrap: wrap;
+    align-items: center;
+    gap: 0.5rem 1.25rem;
+  }
+
+  ::slotted(a) {
+    color: inherit;
+    font-size: 0.9rem;
+    text-decoration: none;
+    padding-block: 0.25rem;
+    transition: color 0.2s;
+  }
+  ::slotted(a:hover) { color: var(--_accent); }
+  ::slotted(a:focus-visible),
+  ::slotted([slot="brand"]:focus-visible) {
+    outline: 2px solid var(--_accent);
+    outline-offset: 3px;
+    border-radius: 2px;
+  }
+  ::slotted(a[aria-current="page"]) {
+    color: var(--_accent);
+    text-decoration: underline;
+    text-underline-offset: 0.3em;
+  }
+  ::slotted(a[data-variant="outline"]) {
+    border: 1px solid var(--_accent);
+    padding: 5px 12px;
+    border-radius: 4px;
+  }
+
+  .toggle {
+    display: none;
+    align-items: center;
+    gap: 0.5rem;
+    min-block-size: 2.75rem;
+    padding: 0.4rem 0.8rem;
+    border: 1px solid currentColor;
+    border-radius: 4px;
+    background: transparent;
+    color: inherit;
+    font: inherit;
+    cursor: pointer;
+  }
+  .toggle:focus-visible {
+    outline: 2px solid var(--_accent);
+    outline-offset: 2px;
+  }
+  .toggle svg {
+    inline-size: 1.25rem;
+    block-size: 1.25rem;
+    stroke: currentColor;
+    stroke-width: 2;
+    stroke-linecap: round;
+  }
+  .toggle .close { display: none; }
+  .toggle[aria-expanded="true"] .open { display: none; }
+  .toggle[aria-expanded="true"] .close { display: inline; }
+
+  @container site-nav (max-width: 44rem) {
+    .toggle { display: inline-flex; }
+    .menu {
+      display: none;
+      flex-basis: 100%;
+      flex-direction: column;
+      align-items: stretch;
+      gap: 0;
+      padding-block: 0.5rem;
+    }
+    .toggle[aria-expanded="true"] + .menu { display: flex; }
+    ::slotted(a) {
+      padding: 0.75rem 0.25rem;
+      font-size: 1rem;
+      border-block-start: 1px solid rgb(255 255 255 / 0.15);
+    }
+    ::slotted(a[data-variant="outline"]) {
+      margin-block-start: 0.75rem;
+      padding: 0.6rem 0.75rem;
+      text-align: center;
+    }
+  }
+`);
+
+const template = document.createElement('template');
+template.innerHTML = `
+  <nav part="nav">
+    <slot name="brand"></slot>
+    <button class="toggle" part="toggle" type="button" aria-expanded="false" aria-controls="menu">
+      <svg class="open" viewBox="0 0 24 24" aria-hidden="true" focusable="false">
+        <path d="M4 7h16M4 12h16M4 17h16"/>
+      </svg>
+      <svg class="close" viewBox="0 0 24 24" aria-hidden="true" focusable="false">
+        <path d="M6 6l12 12M18 6L6 18"/>
+      </svg>
+      <span>Menu</span>
+    </button>
+    <div class="menu" id="menu" part="menu"><slot></slot></div>
+  </nav>
+`;
+
+export class SiteNav extends HTMLElement {
+  #nav;
+  #toggle;
+  #slot;
+
+  constructor() {
+    super();
+    const root = this.shadowRoot ?? this.attachShadow({ mode: 'open' });
+    root.adoptedStyleSheets = [sheet];
+    if (!root.firstChild) root.append(template.content.cloneNode(true));
+
+    this.#nav = root.querySelector('nav');
+    this.#toggle = root.querySelector('.toggle');
+    this.#slot = root.querySelector('.menu slot');
+
+    this.#toggle.addEventListener('click', () => this.toggle());
+    this.#slot.addEventListener('slotchange', () => this.#markCurrent());
+
+    this.addEventListener('keydown', (e) => {
+      if (e.key === 'Escape' && this.open) {
+        this.close();
+        this.#toggle.focus();
+      }
+    });
+    // Following a link from the open mobile menu should collapse it.
+    this.addEventListener('click', (e) => {
+      if (e.target.closest?.('a') && this.open) this.close();
+    });
+  }
+
+  #onDocumentClick = (e) => {
+    if (this.open && !e.composedPath().includes(this)) this.close();
+  };
+
+  connectedCallback() {
+    this.#nav.setAttribute('aria-label', this.getAttribute('label') ?? 'Main');
+    document.addEventListener('click', this.#onDocumentClick);
+    this.#markCurrent();
+  }
+
+  disconnectedCallback() {
+    document.removeEventListener('click', this.#onDocumentClick);
+  }
+
+  get open() {
+    return this.#toggle.getAttribute('aria-expanded') === 'true';
+  }
+
+  set open(value) {
+    this.#toggle.setAttribute('aria-expanded', String(Boolean(value)));
+  }
+
+  toggle() {
+    this.open = !this.open;
+  }
+
+  close() {
+    this.open = false;
+  }
+
+  #markCurrent() {
+    const here = location.pathname.replace(/\/$/, '') || '/';
+    for (const link of this.#slot.assignedElements()) {
+      if (link.localName !== 'a' || !link.href) continue;
+      const path = new URL(link.href).pathname.replace(/\/$/, '') || '/';
+      if (path === here) link.setAttribute('aria-current', 'page');
+      else if (link.getAttribute('aria-current') === 'page') link.removeAttribute('aria-current');
+    }
+  }
+}
+
+if (!customElements.get('site-nav')) {
+  customElements.define('site-nav', SiteNav);
+}
