+import { attachStyledShadow } from './shared-styles.js';
+
+const styles = `
+  :host {
+    display: block;
+    container-type: inline-size;
+  }
+
+  :host([hidden]) {
+    display: none;
+  }
+
+  article {
+    display: flex;
+    flex-direction: column;
+    height: 100%;
+    background: var(--_surface);
+    border-radius: var(--_radius);
+    box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
+    overflow: hidden;
+    text-align: center;
+    transition: box-shadow 0.3s, transform 0.3s;
+  }
+
+  article:hover,
+  article:focus-within {
+    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.15);
+    transform: translateY(-2px);
+  }
+
+  .media {
+    position: relative;
+    aspect-ratio: 3 / 2;
+    background: var(--_secondary);
+  }
+
+  .media[hidden] {
+    display: none;
+  }
+
+  img {
+    display: block;
+    width: 100%;
+    height: 100%;
+    object-fit: cover;
+  }
+
+  .badge {
+    position: absolute;
+    top: 12px;
+    left: 12px;
+    background: var(--_accent);
+    color: var(--_text);
+    font-size: 0.75rem;
+    font-weight: 700;
+    letter-spacing: 0.05em;
+    text-transform: uppercase;
+    padding: 2px 10px;
+    border-radius: 999px;
+  }
+
+  .badge:empty {
+    display: none;
+  }
+
+  .body {
+    display: flex;
+    flex: 1;
+    flex-direction: column;
+    align-items: center;
+    padding: 20px;
+  }
+
+  ::slotted([slot="title"]) {
+    margin: 0 0 10px;
+    color: var(--_primary);
+    font-size: 1.17rem;
+  }
+
+  ::slotted(:not([slot])) {
+    margin: 0;
+  }
+
+  .price {
+    margin-top: 10px;
+    font-weight: 700;
+    color: var(--_primary);
+  }
+
+  .price:empty {
+    display: none;
+  }
+
+  .spacer {
+    flex: 1;
+  }
+
+  .btn {
+    margin-top: 15px;
+  }
+
+  .btn[hidden] {
+    display: none;
+  }
+`;
+
+const template = `
+  <article part="card">
+    <div class="media" part="media" hidden>
+      <img part="image" alt="" loading="lazy" decoding="async" width="600" height="400">
+      <span class="badge" part="badge"></span>
+    </div>
+    <div class="body" part="body">
+      <slot name="title"></slot>
+      <slot></slot>
+      <p class="price" part="price"></p>
+      <span class="spacer"></span>
+      <a class="btn" part="cta" hidden>
+        <span class="cta-label"></span><span class="visually-hidden cta-context"></span>
+      </a>
+    </div>
+  </article>
+`;
+
+/**
+ * <coffee-card> — a menu item card.
+ *
+ * Content (light DOM, so it stays in the document outline and is readable
+ * without JavaScript):
+ *   slot="title"  The item heading. Use the heading level that fits the page.
+ *   (default)     Description.
+ *
+ * Attributes:
+ *   href        Destination of the call-to-action link. No link without it.
+ *   cta-label   Visible link text (default "View Details").
+ *   image       Image URL. Omit to render a card without media.
+ *   image-alt   Alt text. Defaults to "" (decorative) since the title already
+ *               names the item; set it if the photo conveys extra meaning.
+ *   badge       Short label overlaid on the image, e.g. "New".
+ *   price       Display price, e.g. "$5.25".
+ *
+ * The CTA's accessible name is "<cta-label> <title>", e.g.
+ * "View Details Maple Oat Latte", so screen-reader users listing links don't
+ * hear a run of identical "View Details" entries.
+ *
+ * CSS parts: card, media, image, badge, body, price, cta.
+ */
+export class CoffeeCard extends HTMLElement {
+  static observedAttributes = ['href', 'cta-label', 'image', 'image-alt', 'badge', 'price'];
+
+  #root;
+  #titleSlot;
+
+  constructor() {
+    super();
+    this.#root = attachStyledShadow(this, styles, template);
+    this.#titleSlot = this.#root.querySelector('slot[name="title"]');
+    this.#titleSlot.addEventListener('slotchange', () => this.#renderContext());
+  }
+
+  connectedCallback() {
+    this.#render();
+  }
+
+  attributeChangedCallback() {
+    this.#render();
+  }
+
+  /** Visible text of the slotted title, used for link context. */
+  get itemName() {
+    return this.#titleSlot
+      .assignedElements()
+      .map((el) => el.textContent.trim())
+      .join(' ');
+  }
+
+  #render() {
+    const $ = (sel) => this.#root.querySelector(sel);
+
+    const image = this.getAttribute('image');
+    const media = $('.media');
+    const img = $('img');
+    media.hidden = !image;
+    if (image) {
+      if (img.getAttribute('src') !== image) img.src = image;
+      img.alt = this.getAttribute('image-alt') ?? '';
+    } else {
+      img.removeAttribute('src');
+    }
+
+    $('.badge').textContent = this.getAttribute('badge') ?? '';
+    $('.price').textContent = this.getAttribute('price') ?? '';
+
+    const href = this.getAttribute('href');
+    const link = $('a');
+    link.hidden = !href;
+    if (href) link.href = href;
+    else link.removeAttribute('href');
+    $('.cta-label').textContent = this.getAttribute('cta-label') || 'View Details';
+
+    this.#renderContext();
+  }
+
+  #renderContext() {
+    const name = this.itemName;
+    this.#root.querySelector('.cta-context').textContent = name ? ` ${name}` : '';
+  }
+}
+
+if (!customElements.get('coffee-card')) {
+  customElements.define('coffee-card', CoffeeCard);
+}
