+import { attachStyledShadow } from './shared-styles.js';
+
+const styles = `
+  :host {
+    display: block;
+    --_overlay: var(--dg-hero-overlay, rgba(0, 0, 0, 0.5));
+    --_min-height: var(--dg-hero-min-height, 60vh);
+  }
+
+  .hero {
+    position: relative;
+    display: flex;
+    flex-direction: column;
+    align-items: center;
+    justify-content: center;
+    min-height: var(--_min-height);
+    padding: 3rem 20px;
+    color: #fff;
+    text-align: center;
+    background-color: var(--_primary);
+    background-image: linear-gradient(var(--_overlay), var(--_overlay)), var(--_image, none);
+    background-size: cover;
+    background-position: center;
+  }
+
+  ::slotted([slot="heading"]) {
+    margin: 0 0 1rem;
+    font-size: clamp(2rem, 6vw, 3rem);
+    line-height: 1.2;
+  }
+
+  ::slotted(:not([slot])) {
+    margin: 0;
+    max-width: 40ch;
+    font-size: 1.1rem;
+  }
+
+  .actions {
+    display: flex;
+    flex-wrap: wrap;
+    justify-content: center;
+    gap: 12px;
+    margin-top: 15px;
+  }
+
+  ::slotted([slot="action"]) {
+    display: inline-block;
+    background: var(--_primary);
+    color: #fff;
+    padding: 10px 20px;
+    border-radius: 5px;
+    text-decoration: none;
+    transition: background-color 0.3s;
+  }
+
+  ::slotted([slot="action"]:hover) {
+    background: var(--_primary-dark);
+  }
+
+  ::slotted([slot="action"]:focus-visible) {
+    outline: var(--_focus-ring);
+    outline-offset: 3px;
+  }
+`;
+
+const template = `
+  <div class="hero" part="hero">
+    <slot name="heading"></slot>
+    <slot></slot>
+    <div class="actions" part="actions"><slot name="action"></slot></div>
+  </div>
+`;
+
+/**
+ * <hero-banner> — full-width introductory banner.
+ *
+ * Content (light DOM, so headings and links work without JavaScript):
+ *   slot="heading"  The page's main heading, normally an <h1>.
+ *   (default)       Supporting copy.
+ *   slot="action"   One or more call-to-action links, styled as buttons.
+ *
+ * Attributes:
+ *   image   Background image URL. It is purely decorative (CSS background);
+ *           put meaningful content in the slots instead.
+ *
+ * Custom properties: --dg-hero-overlay, --dg-hero-min-height.
+ * CSS parts: hero, actions.
+ *
+ * The component adds no landmark of its own; place it inside the page's
+ * <header> (or <main>) so it sits in the right region.
+ */
+export class HeroBanner extends HTMLElement {
+  static observedAttributes = ['image'];
+
+  #hero;
+
+  constructor() {
+    super();
+    const root = attachStyledShadow(this, styles, template);
+    this.#hero = root.querySelector('.hero');
+  }
+
+  connectedCallback() {
+    this.#applyImage();
+  }
+
+  attributeChangedCallback() {
+    this.#applyImage();
+  }
+
+  #applyImage() {
+    const image = this.getAttribute('image');
+    if (image) {
+      this.#hero.style.setProperty('--_image', `url(${JSON.stringify(image)})`);
+    } else {
+      this.#hero.style.removeProperty('--_image');
+    }
+  }
+}
+
+if (!customElements.get('hero-banner')) {
+  customElements.define('hero-banner', HeroBanner);
+}
