+/**
+ * Styles shared by every Daily Grind component.
+ *
+ * Exported as a constructable stylesheet so each shadow root can adopt the
+ * same parsed sheet instead of re-parsing a copy. Theme values come from CSS
+ * custom properties, which inherit through the shadow boundary, so pages can
+ * restyle components without reaching into their internals.
+ */
+export const sharedStyles = new CSSStyleSheet();
+
+sharedStyles.replaceSync(`
+  :host {
+    --_primary: var(--dg-primary, #4e342e);
+    --_primary-dark: var(--dg-primary-dark, #3e2723);
+    --_secondary: var(--dg-secondary, #d7ccc8);
+    --_accent: var(--dg-accent, #ffab40);
+    --_text: var(--dg-text, #3e2723);
+    --_surface: var(--dg-surface, #ffffff);
+    --_radius: var(--dg-radius, 8px);
+    --_focus-ring: var(--dg-focus-ring, 3px solid var(--_accent));
+    box-sizing: border-box;
+  }
+
+  *, *::before, *::after {
+    box-sizing: inherit;
+  }
+
+  .visually-hidden {
+    position: absolute !important;
+    width: 1px;
+    height: 1px;
+    padding: 0;
+    margin: -1px;
+    overflow: hidden;
+    clip: rect(0 0 0 0);
+    white-space: nowrap;
+    border: 0;
+  }
+
+  .btn {
+    display: inline-block;
+    background: var(--_primary);
+    color: #fff;
+    padding: 10px 20px;
+    border: 0;
+    border-radius: 5px;
+    font: inherit;
+    text-decoration: none;
+    cursor: pointer;
+    transition: background-color 0.3s;
+  }
+
+  .btn:hover {
+    background: var(--_primary-dark);
+  }
+
+  .btn:focus-visible {
+    outline: var(--_focus-ring);
+    outline-offset: 3px;
+  }
+
+  @media (prefers-reduced-motion: reduce) {
+    *, *::before, *::after {
+      transition: none !important;
+      animation: none !important;
+    }
+  }
+`);
+
+/** Attach an open shadow root that adopts the shared sheet plus `own`. */
+export function attachStyledShadow(host, own, html) {
+  const root = host.attachShadow({ mode: 'open' });
+  const sheet = new CSSStyleSheet();
+  sheet.replaceSync(own);
+  root.adoptedStyleSheets = [sharedStyles, sheet];
+  root.innerHTML = html;
+  return root;
+}
