+  constructor() {
+    super();
+    this.#root = attachStyledShadow(this, styles, template);
+    this.#nav = this.#root.querySelector('nav');
+    this.#toggle = this.#root.querySelector('.toggle');
+    this.#links = this.#root.querySelector('.links');
+
+    this.#toggle.addEventListener('click', () => this.toggle());
+    this.#root.addEventListener('keydown', (e) => this.#onKeydown(e));
+    this.addEventListener('click', (e) => {
+      if (this.open && e.target.closest?.('a')) this.close();
+    });
