+      .addEventListener('slotchange', () => this.#markCurrent());
+  }
+
+  connectedCallback() {
+    this.#abort = new AbortController();
+    const { signal } = this.#abort;
+    document.addEventListener('click', (e) => {
+      if (this.open && !e.composedPath().includes(this)) this.close();
