+          existing.quantity += quantity;
+        } else {
+          order.push({ lineId: nextLineId++, drinkId, size, milk, quantity });
+        }
+        commit(`Added ${quantity} × ${SIZES[size].label} ${drink.name} to your order.`);
+        return orderSummary();
+      }
+
+      function removeFromOrder(lineId) {
+        const idx = order.findIndex((l) => l.lineId === Number(lineId));
+        if (idx === -1) throw new Error(`No order line with id ${lineId}.`);
+        const [line] = order.splice(idx, 1);
+        commit(`Removed ${DRINK_BY_ID[line.drinkId].name} from your order.`);
+        return orderSummary();
+      }
+
+      function clearOrder() {
+        order = [];
+        commit('Order cleared.');
+        return orderSummary();
+      }
+
+      function placeOrder() {
+        if (!order.length) throw new Error('The order is empty. Add at least one drink first.');
+        const summary = orderSummary();
+        const confirmation = {
+          orderNumber: `DG-${Date.now().toString(36).toUpperCase()}`,
+          ...summary,
+          estimatedReadyMinutes: 5 + summary.itemCount * 2,
+        };
+        order = [];
+        commit(`Order ${confirmation.orderNumber} placed! Total ${money(confirmation.total)}. ` +
+          `Ready in about ${confirmation.estimatedReadyMinutes} minutes.`, true);
+        return confirmation;
+      }
+
+      // ---- Rendering ---------------------------------------------------------
+      const $ = (id) => document.getElementById(id);
+      const statusEl = $('order-status');
+
+      function commit(message, success = false) {
+        saveOrder();
+        renderOrder();
+        statusEl.textContent = message || '';
+        statusEl.classList.toggle('success', success);
+      }
+
+      function el(tag, attrs = {}, children = []) {
+        const node = document.createElement(tag);
+        for (const [k, v] of Object.entries(attrs)) {
+          if (k === 'text') node.textContent = v;
+          else node.setAttribute(k, v);
+        }
+        node.append(...children);
+        return node;
+      }
+
+      function renderCards() {
+        const grid = $('seasonal-grid');
+        for (const drink of DRINKS) {
+          const sizeSelect = el('select', { name: 'size' },
+            Object.entries(SIZES).map(([value, s]) =>
+              el('option', { value, text: `${s.label} – ${money(unitPrice(drink, value))}` })));
+          sizeSelect.value = 'medium';
+
+          const milkSelect = el('select', { name: 'milk' },
+            MILKS.map((m) => el('option', { value: m, text: m === 'none' ? 'No milk' : `${m[0].toUpperCase()}${m.slice(1)}` })));
+          milkSelect.value = drink.defaultMilk;
+
+          const qtyInput = el('input', { type: 'number', name: 'quantity', min: '1', max: String(MAX_QTY), value: '1', required: '' });
+
+          const form = el('form', { class: 'order-form', 'aria-label': `Order ${drink.name}` }, [
+            el('div', { class: 'row' }, [
+              el('label', {}, ['Size', sizeSelect]),
+              el('label', {}, ['Quantity', qtyInput]),
+            ]),
+            el('label', {}, ['Milk', milkSelect]),
+            el('div', { class: 'card-actions' }, [
+              el('a', { href: drink.detailsUrl, class: 'btn btn-outline', text: 'View Details' }),
+              el('button', { type: 'submit', class: 'btn', text: 'Add to Order' }),
+            ]),
+          ]);
+
+          form.addEventListener('submit', (e) => {
+            e.preventDefault();
+            try {
+              addToOrder({ drinkId: drink.id, size: sizeSelect.value, quantity: qtyInput.value, milk: milkSelect.value });
+              qtyInput.value = '1';
+            } catch (err) {
+              commit(err.message);
+            }
+          });
+
+          grid.append(el('article', { class: 'card', 'data-drink-id': drink.id }, [
