+              el('p', { class: 'price', text: `From ${money(drink.basePrice)}` }),
+              form,
+            ]),
+          ]));
+        }
+      }
+
+      function renderOrder() {
+        const { items, total } = orderSummary();
+        const list = $('order-items');
+        list.replaceChildren(...items.map((i) => {
+          const remove = el('button', { type: 'button', class: 'remove', 'aria-label': `Remove ${i.name}`, text: 'Remove' });
