+import { useEffect, useState } from 'react';
+import { useWebMCP } from 'use-webmcp-tool';
+import { absoluteUrl, agentSafe, fetchReadingList } from './readingListClient';
+
+interface Props {
+  slug: string;
+  title: string;
+  summary: string;
+  author: string;
+  date: string;
+  category: string;
+  tags: string[];
+  readingTime?: number;
+  /** id of the element wrapping the rendered article body */
+  bodyId: string;
+}
+
+const HIGHLIGHT_NAME = 'agent-find';
+const WORDS_PER_MINUTE = 230;
+
+const getBody = (bodyId: string) => document.getElementById(bodyId);
+const normalize = (text: string) => text.replace(/\s+/g, ' ').trim();
+
+function getHeadings(body: HTMLElement) {
+  return [...body.querySelectorAll<HTMLHeadingElement>('h2, h3, h4')];
+}
+
+/** Text blocks (paragraphs, list items, …) paired with the heading they sit under. */
+function getBlocks(body: HTMLElement) {
+  let section = '';
+  const blocks: { element: HTMLElement; section: string; text: string }[] = [];
+  for (const element of body.querySelectorAll<HTMLElement>('h2, h3, h4, p, li, blockquote, td')) {
+    if (/^H[2-4]$/.test(element.tagName)) {
+      section = normalize(element.textContent ?? '');
+    } else {
+      const text = normalize(element.textContent ?? '');
+      if (text) blocks.push({ element, section, text });
+    }
+  }
+  return blocks;
+}
+
+function scrollIntoViewRespectingMotion(element: HTMLElement) {
+  const reduceMotion = matchMedia('(prefers-reduced-motion: reduce)').matches;
+  element.scrollIntoView({ behavior: reduceMotion ? 'auto' : 'smooth', block: 'center' });
+}
+
+/** Highlights every occurrence of `needle` using the CSS Custom Highlight API, when supported. */
+function highlightMatches(body: HTMLElement, needle: string) {
+  if (!('highlights' in CSS) || typeof Highlight === 'undefined') return;
+  CSS.highlights.delete(HIGHLIGHT_NAME);
+  if (!needle) return;
+  const ranges: Range[] = [];
+  const walker = document.createTreeWalker(body, NodeFilter.SHOW_TEXT);
+  const lowerNeedle = needle.toLowerCase();
+  for (let node = walker.nextNode(); node; node = walker.nextNode()) {
+    const haystack = (node.textContent ?? '').toLowerCase();
+    for (let index = haystack.indexOf(lowerNeedle); index !== -1; index = haystack.indexOf(lowerNeedle, index + lowerNeedle.length)) {
+      const range = new Range();
+      range.setStart(node, index);
+      range.setEnd(node, index + lowerNeedle.length);
+      ranges.push(range);
+    }
+  }
+  if (ranges.length) CSS.highlights.set(HIGHLIGHT_NAME, new Highlight(...ranges));
+}
+
+/** Client-side article utilities exposed as WebMCP tools on article pages. */
+export default function ArticleTools(props: Props) {
+  const { slug, title, summary, author, date, category, tags, readingTime, bodyId } = props;
+  const [sections, setSections] = useState<string[]>([]);
+
+  useEffect(() => {
+    const body = getBody(bodyId);
+    if (body) setSections(getHeadings(body).map((heading) => normalize(heading.textContent ?? '')));
+    return () => {
+      if ('highlights' in CSS) CSS.highlights.delete(HIGHLIGHT_NAME);
+    };
+  }, [bodyId]);
+
+  useWebMCP({
+    name: 'get_current_article',
+    description:
+      'Get the full text and details of the article the reader is currently viewing, including its sections, length, estimated reading time, and whether it is on their reading list. Use this to summarize, quote, or answer questions about the article.',
+    inputSchema: { type: 'object', properties: {} },
+    annotations: { readOnlyHint: true },
+    execute: (_args, { signal }) =>
+      agentSafe(signal, async () => {
+        const body = getBody(bodyId);
+        if (!body) return { error: 'The article body is not on the page.' };
+        const text = normalize(body.innerText ?? body.textContent ?? '');
+        const wordCount = text ? text.split(' ').length : 0;
+        const readingList = await fetchReadingList(signal).catch(() => null);
+        return {
+          slug,
+          title,
+          summary,
+          author,
+          publishedOn: date,
+          category,
+          tags,
+          url: absoluteUrl(location.pathname),
+          wordCount,
+          readingTimeMinutes: readingTime ?? Math.max(1, Math.round(wordCount / WORDS_PER_MINUTE)),
+          inReadingList: readingList ? readingList.includes(slug) : 'unknown',
+          sections,
+          text,
+        };
+      }),
+  });
+
+  useWebMCP<{ text: string }>({
+    name: 'find_text_in_article',
+    description:
+      'Find where a word or phrase appears in the current article. Returns each matching passage with the section it belongs to, highlights the matches on the page, and scrolls to the first one.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        text: { type: 'string', minLength: 1, description: 'The word or phrase to look for (case-insensitive).' },
+      },
+      required: ['text'],
+    },
+    annotations: { readOnlyHint: true },
+    execute: ({ text }) => {
+      const body = getBody(bodyId);
+      if (!body) return { error: 'The article body is not on the page.' };
+      const needle = typeof text === 'string' ? text.trim() : '';
+      if (!needle) return { error: 'Pass a non-empty word or phrase to find.' };
+
+      const matches = getBlocks(body).filter((block) => block.text.toLowerCase().includes(needle.toLowerCase()));
+      highlightMatches(body, matches.length ? needle : '');
+      if (matches[0]) scrollIntoViewRespectingMotion(matches[0].element);
+
+      return {
+        text: needle,
+        totalMatches: matches.length,
+        matches: matches.slice(0, 20).map(({ section, text: passage }) => ({ section: section || null, passage })),
+      };
+    },
+  });
+
+  useWebMCP<{ section: string }>({
+    name: 'go_to_article_section',
+    description: 'Scroll the current article to one of its sections and return that section’s text.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        section: { type: 'string', enum: sections, description: 'Heading of the section to jump to.' },
+      },
+      required: ['section'],
+    },
+    enabled: sections.length > 0,
+    execute: ({ section }) => {
+      const body = getBody(bodyId);
+      if (!body) return { error: 'The article body is not on the page.' };
+      const headings = getHeadings(body);
+      const target = headings.find((heading) => normalize(heading.textContent ?? '').toLowerCase() === String(section).trim().toLowerCase());
+      if (!target) return { error: `No section named "${section}".`, sections };
+
+      target.tabIndex = -1;
+      scrollIntoViewRespectingMotion(target);
+      target.focus({ preventScroll: true });
+
+      const level = Number(target.tagName[1]);
+      const parts: string[] = [];
+      for (let el = target.nextElementSibling; el; el = el.nextElementSibling) {
+        if (/^H[1-6]$/.test(el.tagName) && Number(el.tagName[1]) <= level) break;
+        const text = normalize(el.textContent ?? '');
+        if (text) parts.push(text);
+      }
+      return { section: normalize(target.textContent ?? ''), text: parts.join('\n\n') };
+    },
+  });
+
+  return null;
+}
