+import { useWebMCP } from 'use-webmcp-tool';
+import {
+  agentSafe,
+  changeReadingList,
+  fetchArticles,
+  fetchReadingList,
+  slimArticle,
+} from './readingListClient';
+
+interface Props {
+  categories: string[];
+  /** The reading-list page exposes its own declarative `update_reading_list` form tool. */
+  onReadingListPage?: boolean;
+}
+
+const slugSchema = {
+  type: 'string',
+  description: "The article's slug: the last segment of its URL, as returned by list_articles.",
+} as const;
+
+/** Site-wide WebMCP tools, available on every page of The DevTools Times. */
+export default function SiteTools({ categories, onReadingListPage = false }: Props) {
+  useWebMCP<{ query?: string; category?: string; limit?: number }>({
+    name: 'list_articles',
+    description:
+      'Look up published articles, newest first, without leaving the current page. Use it to browse a section, find stories on a topic, or get the slug of an article.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        query: { type: 'string', description: 'Optional keywords matched against title, summary, author, and tags.' },
+        category: { type: 'string', enum: categories, description: 'Optional newspaper section to restrict results to.' },
+        limit: { type: 'integer', minimum: 1, maximum: 50, default: 10, description: 'Maximum number of articles to return.' },
+      },
+    },
+    annotations: { readOnlyHint: true },
+    execute: ({ query = '', category = '', limit = 10 }, { signal }) =>
+      agentSafe(signal, async () => {
+        if (category && !categories.includes(category.toLowerCase())) {
+          return { error: `Unknown section "${category}".`, sections: categories };
+        }
+        const max = Number.isInteger(limit) && limit >= 1 ? Math.min(limit, 50) : 10;
+        const words = String(query).toLowerCase().split(/\s+/).filter(Boolean);
+        const matches = (await fetchArticles(signal)).filter((article) => {
+          if (category && article.category !== category.toLowerCase()) return false;
+          const haystack = [article.title, article.summary, article.author, ...article.tags].join(' ').toLowerCase();
+          return words.every((word) => haystack.includes(word));
+        });
+        return { total: matches.length, articles: matches.slice(0, max).map(slimArticle) };
+      }),
+  });
+
+  useWebMCP({
+    name: 'get_reading_list',
+    description: "Get the articles the reader has saved to their reading list.",
+    inputSchema: { type: 'object', properties: {} },
+    annotations: { readOnlyHint: true },
+    execute: (_args, { signal }) =>
+      agentSafe(signal, async () => {
+        const [articles, readingList] = await Promise.all([fetchArticles(signal), fetchReadingList(signal)]);
+        const saved = articles.filter((article) => readingList.includes(article.slug)).map(slimArticle);
+        return { total: saved.length, articles: saved };
+      }),
+  });
+
+  useWebMCP<{ slug: string }>({
+    name: 'save_article_to_reading_list',
+    description: "Save an article to the reader's reading list so they can come back to it later.",
+    inputSchema: { type: 'object', properties: { slug: slugSchema }, required: ['slug'] },
+    annotations: { readOnlyHint: false },
+    enabled: !onReadingListPage,
+    execute: ({ slug }, { signal }) =>
+      agentSafe(signal, async () => {
+        if (typeof slug !== 'string' || !slug) return { error: 'Pass the slug of the article to save.' };
+        const result = await changeReadingList(slug, 'add', signal);
+        return 'error' in result ? result : { message: `Saved "${slug}" to the reading list.`, readingList: result.readingList };
+      }),
+  });
+
+  useWebMCP<{ slug: string }>({
+    name: 'remove_article_from_reading_list',
+    description: "Remove an article from the reader's reading list.",
+    inputSchema: { type: 'object', properties: { slug: slugSchema }, required: ['slug'] },
+    annotations: { readOnlyHint: false },
+    enabled: !onReadingListPage,
+    execute: ({ slug }, { signal }) =>
+      agentSafe(signal, async () => {
+        if (typeof slug !== 'string' || !slug) return { error: 'Pass the slug of the article to remove.' };
+        const result = await changeReadingList(slug, 'remove', signal);
+        return 'error' in result ? result : { message: `Removed "${slug}" from the reading list.`, readingList: result.readingList };
+      }),
+  });
+
+  return null;
+}
diff --git a/src/components/webmcp/readingListClient.ts b/src/components/webmcp/readingListClient.ts
new file mode 100644
index 0000000..9a7db77
--- /dev/null
+++ b/src/components/webmcp/readingListClient.ts
@@ -0,0 +1,58 @@
+const BASE = import.meta.env.BASE_URL;
+
+export interface ArticleSummary {
+  slug: string;
+  title: string;
+  summary: string;
+  category: string;
+  author: string;
+  date: string;
+  tags: string[];
+  url: string;
+}
+
+export const absoluteUrl = (path: string) => new URL(path, location.origin).href;
+
+export async function fetchArticles(signal?: AbortSignal): Promise<ArticleSummary[]> {
+  const response = await fetch(`${BASE}api/articles.json`, { signal });
+  if (!response.ok) throw new Error(`Article index request failed with status ${response.status}`);
+  return response.json();
+}
+
+export async function fetchReadingList(signal?: AbortSignal): Promise<string[]> {
+  const response = await fetch(`${BASE}api/reading-list.json`, { signal });
+  if (!response.ok) throw new Error(`Reading list request failed with status ${response.status}`);
+  return (await response.json()).readingList;
+}
+
+/** Adds or removes `slug`, broadcasts `readinglist:change` so on-page UI stays in sync. */
+export async function changeReadingList(
+  slug: string,
+  action: 'add' | 'remove',
+  signal?: AbortSignal,
+): Promise<{ readingList: string[] } | { error: string }> {
+  const response = await fetch(`${BASE}api/reading-list.json`, {
+    method: 'POST',
+    headers: { 'Content-Type': 'application/json' },
+    body: JSON.stringify({ slug, action }),
+    signal,
+  });
+  const body = await response.json();
+  if (!response.ok) return { error: body.error ?? `Request failed with status ${response.status}` };
+  window.dispatchEvent(new CustomEvent('readinglist:change', { detail: { readingList: body.readingList } }));
+  return { readingList: body.readingList };
+}
+
+export function slimArticle({ slug, title, summary, category, author, date, url }: ArticleSummary) {
+  return { slug, title, summary, category, author, date, url: absoluteUrl(url) };
+}
+
+/** Run `fn`, returning a structured error the agent can read unless the call was cancelled. */
+export async function agentSafe<T>(signal: AbortSignal, fn: () => Promise<T>): Promise<T | { error: string }> {
+  try {
+    return await fn();
+  } catch (error) {
+    if (signal.aborted) throw error;
+    return { error: error instanceof Error ? error.message : String(error) };
+  }
+}
