diff --git a/src/scripts/agentForms.ts b/src/scripts/agentForms.ts
new file mode 100644
index 0000000..eead158
--- /dev/null
+++ b/src/scripts/agentForms.ts
@@ -0,0 +1,131 @@
+/**
+ * Progressive enhancement for the WebMCP declarative forms (`toolname` attributes).
+ *
+ * Human submissions fall through to the normal server round-trip. When a browser
+ * agent submits a form (`event.agentInvoked`), we handle it client-side, update
+ * the page, and hand the result straight back to the agent via `respondWith()`
+ * so it doesn't have to scrape the re-rendered page.
+ *
+ * One delegated listener survives Astro ClientRouter page swaps. It listens in the
+ * capture phase on `window` so it runs before ClientRouter's own `submit` handler
+ * on `document`, which would otherwise turn the submission into a navigation.
+ */
+
+type AgentSubmitEvent = SubmitEvent & {
+  agentInvoked?: boolean;
+  respondWith?: (result: Promise<unknown>) => void;
+};
+
+interface ArticleSummary {
+  slug: string;
+  title: string;
+  summary: string;
+  category: string;
+  author: string;
+  date: string;
+  url: string;
+}
+
+const BASE = import.meta.env.BASE_URL;
+
+function renderArticleList(list: HTMLElement, articles: ArticleSummary[], { removable = false } = {}) {
+  const template = document.querySelector<HTMLTemplateElement>(`template#${list.dataset.template}`);
+  if (!template) return;
+  list.replaceChildren(
+    ...articles.map((article) => {
+      const item = template.content.firstElementChild!.cloneNode(true) as HTMLElement;
+      item.querySelector<HTMLAnchorElement>('[data-field="link"]')!.href = article.url;
+      item.querySelector('[data-field="title"]')!.textContent = article.title;
+      item.querySelector('[data-field="summary"]')!.textContent = article.summary;
+      const meta = item.querySelector('[data-field="meta"]');
+      if (meta) meta.textContent = `${article.category} · ${article.author} · ${article.date}`;
+      if (removable) {
+        const slugInput = item.querySelector<HTMLInputElement>('input[name="slug"]');
+        if (slugInput) slugInput.value = article.slug;
+      }
+      return item;
+    }),
+  );
+}
+
+function setStatus(id: string, text: string) {
+  const status = document.getElementById(id);
+  if (status) status.textContent = text;
+}
+
+async function runSearch(form: HTMLFormElement) {
+  const params = new URLSearchParams();
+  const data = new FormData(form);
+  const query = String(data.get('q') ?? '').trim();
+  const category = String(data.get('category') ?? '').trim();
+  if (query) params.set('q', query);
+  if (category) params.set('category', category);
+
+  const response = await fetch(`${BASE}api/search.json?${params}`);
+  if (!response.ok) return `Search failed with status ${response.status}. Try again.`;
+  const result = await response.json();
+
+  const list = document.getElementById('search-results');
+  if (list) renderArticleList(list, result.results);
+  setStatus(
+    'search-status',
+    result.total === 0 ? 'No articles matched your search.' : `${result.total} article${result.total === 1 ? '' : 's'} found.`,
+  );
+  history.replaceState(history.state, '', `${location.pathname}${params.size ? `?${params}` : ''}`);
+
+  return {
+    query,
+    category: category || 'all',
+    total: result.total,
+    results: result.results.map(({ slug, title, summary, category, author, date, url }: ArticleSummary) => ({
+      slug, title, summary, category, author, date, url: new URL(url, location.origin).href,
+    })),
+  };
+}
+
+async function runReadingListUpdate(form: HTMLFormElement) {
+  const data = new FormData(form);
+  const slug = String(data.get('slug') ?? '');
+  const action = String(data.get('operation') ?? 'add');
+  if (!slug) return 'Validation failed: choose an article (slug).';
+  if (action !== 'add' && action !== 'remove') return 'Validation failed: operation must be add or remove.';
+
+  const response = await fetch(`${BASE}api/reading-list.json`, {
+    method: 'POST',
+    headers: { 'Content-Type': 'application/json' },
+    body: JSON.stringify({ slug, action }),
+  });
+  const result = await response.json();
+  if (!response.ok) return `Could not update the reading list: ${result.error ?? response.status}`;
+
+  const index: ArticleSummary[] = JSON.parse(document.getElementById('article-index')?.textContent ?? '[]');
+  const saved = index.filter((article) => result.readingList.includes(article.slug));
+  const list = document.getElementById('reading-list-items');
+  if (list) renderArticleList(list, saved, { removable: true });
+  setStatus('reading-list-status', saved.length === 0 ? 'Your reading list is empty.' : `${saved.length} saved article${saved.length === 1 ? '' : 's'}.`);
+  window.dispatchEvent(new CustomEvent('readinglist:change', { detail: { readingList: result.readingList } }));
+
+  const title = index.find((article) => article.slug === slug)?.title ?? slug;
+  return {
+    message: action === 'add' ? `Saved "${title}" to the reading list.` : `Removed "${title}" from the reading list.`,
+    readingList: saved.map(({ slug, title, url }) => ({ slug, title, url: new URL(url, location.origin).href })),
+  };
+}
+
+const handlers: Record<string, (form: HTMLFormElement) => Promise<unknown>> = {
+  search_articles: runSearch,
+  update_reading_list: runReadingListUpdate,
+};
+
+window.addEventListener('submit', (event) => {
+  const submitEvent = event as AgentSubmitEvent;
+  const form = submitEvent.target;
+  if (!(form instanceof HTMLFormElement) || !submitEvent.agentInvoked) return;
+  const handler = handlers[form.getAttribute('toolname') ?? ''];
+  if (!handler) return;
+
+  submitEvent.preventDefault();
+  submitEvent.respondWith?.(
+    handler(form).catch((error) => `The request failed: ${error instanceof Error ? error.message : String(error)}`),
+  );
+}, { capture: true });
