@@ -0,0 +1,58 @@
+import { getCollection, type CollectionEntry } from 'astro:content';
+
+export interface ArticleSummary {
+  slug: string;
+  title: string;
+  summary: string;
+  image: string;
+  category: string;
+  author: string;
+  date: string;
+  tags: string[];
+  url: string;
+}
+
+export function toArticleSummary(article: CollectionEntry<'articles'>): ArticleSummary {
+  return {
+    slug: article.id,
+    title: article.data.title,
+    summary: article.data.summary,
+    image: article.data.image,
+    category: article.data.category.toLowerCase(),
+    author: article.data.author,
+    date: article.data.date.toISOString().slice(0, 10),
+    tags: article.data.tags ?? [],
+    url: `${import.meta.env.BASE_URL}articles/${article.id}`,
+  };
+}
+
+export async function getArticleIndex(): Promise<ArticleSummary[]> {
+  const articles = await getCollection('articles');
+  return articles
+    .map(toArticleSummary)
+    .sort((a, b) => b.date.localeCompare(a.date));
+}
+
+export async function getCategories(): Promise<string[]> {
+  const articles = await getArticleIndex();
+  return [...new Set(articles.map((a) => a.category))].sort();
+}
+
+/**
+ * Case-insensitive search: every word in `query` must appear in the article's
+ * title, summary, author, category, or tags. An empty query matches everything.
+ */
+export function searchArticleIndex(
+  articles: ArticleSummary[],
+  { query = '', category = '' }: { query?: string; category?: string },
+): ArticleSummary[] {
+  const words = query.toLowerCase().split(/\s+/).filter(Boolean);
+  const wantedCategory = category.trim().toLowerCase();
+  return articles.filter((article) => {
+    if (wantedCategory && article.category !== wantedCategory) return false;
+    const haystack = [article.title, article.summary, article.author, article.category, ...article.tags]
+      .join(' ')
+      .toLowerCase();
+    return words.every((word) => haystack.includes(word));
+  });
+}
