+
+export type ReadingListAction = 'add' | 'remove' | 'toggle';
+
+type Session = { get(key: string): Promise<any>; set(key: string, value: unknown): void | Promise<void> } | undefined;
+
+export async function getReadingList(session: Session): Promise<string[]> {
+  return (await session?.get('readingList')) || [];
+}
+
+/** Applies `action` for `slug` to the session reading list and returns the updated list. */
+export async function updateReadingList(session: Session, slug: string, action: ReadingListAction = 'toggle'): Promise<string[]> {
+  let readingList = await getReadingList(session);
+  const hasSlug = readingList.includes(slug);
+  const shouldAdd = action === 'add' || (action === 'toggle' && !hasSlug);
+
+  if (shouldAdd && !hasSlug) {
+    readingList = [...readingList, slug];
+  } else if (!shouldAdd && hasSlug) {
+    readingList = readingList.filter((item) => item !== slug);
+  }
+
+  await session?.set('readingList', readingList);
+  return readingList;
+}
+
+export function isReadingListAction(value: unknown): value is ReadingListAction {
+  return value === 'add' || value === 'remove' || value === 'toggle';
+}
+

