+/**
+ * Small, dependency-free helpers around the WebMCP browser API
+ * (`navigator.modelContext`) plus the client-side data access shared by the
+ * imperative tools (src/scripts/browser-tools.ts) and the declarative form
+ * tools rendered by the React flyouts.
+ *
+ * Everything here is feature-detected so the site keeps working unchanged in
+ * browsers without WebMCP support.
+ */
+
+const BASE_URL = import.meta.env.BASE_URL.endsWith('/')
+  ? import.meta.env.BASE_URL
+  : `${import.meta.env.BASE_URL}/`;
+
+/** Fired on `window` whenever the reading list changes (detail: string[] of slugs). */
+export const READING_LIST_CHANGED_EVENT = 'devtools-times:reading-list-changed';
+
+/** Fired on `window` to ask the header to open a flyout (detail: 'search' | 'reading-list'). */
+export const OPEN_FLYOUT_EVENT = 'devtools-times:open-flyout';
+
+export interface ArticleSummary {
+  slug: string;
+  title: string;
+  summary: string;
+  image?: string;
+  author?: string;
+  category?: string;
+  date?: string;
+  tags?: string[];
+  readingTime?: number;
+}
+
+/* ------------------------------------------------------------------------ */
+/* WebMCP registration                                                      */
+/* ------------------------------------------------------------------------ */
+
+export function isWebMCPSupported(): boolean {
+  return typeof navigator !== 'undefined' && !!navigator.modelContext?.registerTool;
+}
+
+export function textResult(value: unknown): ModelContextToolResult {
+  const text = typeof value === 'string' ? value : JSON.stringify(value, null, 2);
+  return { content: [{ type: 'text', text }] };
+}
+
+export function errorResult(message: string): ModelContextToolResult {
+  return { content: [{ type: 'text', text: message }], isError: true };
+}
+
+/**
+ * Registers a tool and returns a function that unregisters it again.
+ * Errors in `execute` are converted into MCP error results instead of
+ * rejecting, so agents get a readable message.
+ */
+export function registerTool(tool: ModelContextTool): () => void {
+  const modelContext = isWebMCPSupported() ? navigator.modelContext : undefined;
+  if (!modelContext) return () => {};
+
+  const controller = new AbortController();
+  const wrapped: ModelContextTool = {
+    ...tool,
+    async execute(input, client) {
+      try {
+        return await tool.execute(input ?? {}, client);
+      } catch (error) {
+        return errorResult(`Tool "${tool.name}" failed: ${error instanceof Error ? error.message : String(error)}`);
+      }
+    },
+  };
+
+  try {
+    // Unregister a stale registration with the same name (e.g. after HMR).
+    try {
+      modelContext.unregisterTool?.(tool.name);
+    } catch {
+      /* not registered */
+    }
+    modelContext.registerTool(wrapped, { signal: controller.signal });
+  } catch (error) {
+    console.warn(`[WebMCP] Failed to register tool "${tool.name}"`, error);
+    return () => {};
+  }
+
+  return () => {
+    controller.abort();
+    try {
+      modelContext.unregisterTool?.(tool.name);
+    } catch {
+      /* already gone */
+    }
+  };
+}
+
+/* ------------------------------------------------------------------------ */
+/* Data access                                                              */
+/* ------------------------------------------------------------------------ */
+
+export function articleUrl(slug: string): string {
+  return new URL(`${BASE_URL}articles/${encodeURIComponent(slug)}`, location.origin).href;
+}
+
+export function siteUrl(path = ''): string {
+  return new URL(`${BASE_URL}${path.replace(/^\//, '')}`, location.origin).href;
+}
+
+let articlesPromise: Promise<ArticleSummary[]> | null = null;
+
+export function fetchArticles(): Promise<ArticleSummary[]> {
+  if (!articlesPromise) {
+    articlesPromise = fetch(`${BASE_URL}api/articles.json`)
+      .then((response) => {
+        if (!response.ok) throw new Error(`Could not load articles (HTTP ${response.status})`);
+        return response.json() as Promise<ArticleSummary[]>;
+      })
+      .catch((error) => {
+        articlesPromise = null;
+        throw error;
+      });
+  }
+  return articlesPromise;
+}
+
+export interface SearchOptions {
+  query?: string;
+  category?: string;
+  limit?: number;
+}
+
+export async function searchArticles({ query = '', category, limit = 10 }: SearchOptions) {
+  const articles = await fetchArticles();
+  const terms = query.toLowerCase().split(/\s+/).filter(Boolean);
+  const wantedCategory = category?.trim().toLowerCase();
+
+  return articles
+    .filter((article) => !wantedCategory || article.category?.toLowerCase() === wantedCategory)
+    .map((article) => {
+      const title = article.title.toLowerCase();
+      const haystack = [article.summary, article.author, article.category, ...(article.tags ?? [])]
+        .join(' ')
+        .toLowerCase();
+      let score = terms.length === 0 ? 1 : 0;
+      for (const term of terms) {
+        if (title.includes(term)) score += 3;
+        else if (haystack.includes(term)) score += 1;
+        else return { article, score: 0 };
+      }
+      return { article, score };
+    })
+    .filter(({ score }) => score > 0)
+    .sort((a, b) => b.score - a.score)
+    .slice(0, Math.max(1, Math.min(limit, 50)))
+    .map(({ article }) => ({ ...article, url: articleUrl(article.slug) }));
+}
+
+function notifyReadingListChanged(readingList: string[]) {
+  window.dispatchEvent(new CustomEvent(READING_LIST_CHANGED_EVENT, { detail: readingList }));
+}
+
+export async function getReadingList(): Promise<string[]> {
+  const response = await fetch(`${BASE_URL}api/reading-list.json`);
+  if (!response.ok) throw new Error(`Could not load reading list (HTTP ${response.status})`);
+  const data = await response.json();
+  return Array.isArray(data.readingList) ? data.readingList : [];
+}
+
+/** The API only exposes a toggle; this wraps it so callers can ask for an explicit state. */
+export async function toggleReadingList(slug: string): Promise<string[]> {
+  const response = await fetch(`${BASE_URL}api/reading-list.json`, {
+    method: 'POST',
+    headers: { 'Content-Type': 'application/json' },
+    body: JSON.stringify({ slug }),
+  });
+  if (!response.ok) throw new Error(`Could not update reading list (HTTP ${response.status})`);
+  const data = await response.json();
+  const readingList: string[] = Array.isArray(data.readingList) ? data.readingList : [];
+  notifyReadingListChanged(readingList);
+  return readingList;
+}
+
+export type ReadingListAction = 'add' | 'remove' | 'toggle';
+
+export async function updateReadingList(slug: string, action: ReadingListAction) {
+  const articles = await fetchArticles();
+  const article = articles.find((a) => a.slug === slug);
+  if (!article) {
+    throw new Error(`Unknown article "${slug}". Use search_articles to find valid slugs.`);
+  }
+
+  const current = await getReadingList();
+  const isSaved = current.includes(slug);
+  const shouldToggle = action === 'toggle' || (action === 'add' && !isSaved) || (action === 'remove' && isSaved);
+  const readingList = shouldToggle ? await toggleReadingList(slug) : current;
+  const saved = readingList.includes(slug);
+
+  return {
+    slug,
+    title: article.title,
+    saved,
+    changed: shouldToggle,
+    message: shouldToggle
+      ? `"${article.title}" was ${saved ? 'added to' : 'removed from'} the reading list.`
+      : `"${article.title}" is already ${saved ? 'in' : 'not in'} the reading list.`,
+    readingList,
+  };
+}
+
+export async function getReadingListArticles() {
+  const [slugs, articles] = await Promise.all([getReadingList(), fetchArticles()]);
+  return slugs.map((slug) => {
+    const article = articles.find((a) => a.slug === slug);
+    return article
+      ? { slug, title: article.title, summary: article.summary, category: article.category, url: articleUrl(slug) }
+      : { slug, title: slug, url: articleUrl(slug) };
+  });
+}
