diff --git a/src/scripts/browser-tools.ts b/src/scripts/browser-tools.ts
new file mode 100644
index 0000000..c1fdf8c
--- /dev/null
+++ b/src/scripts/browser-tools.ts
@@ -0,0 +1,511 @@
+/**
+ * Imperative WebMCP tools for The DevTools Times.
+ *
+ * - Site-wide tools (search, reading list, navigation, panels) are registered
+ *   once per document.
+ * - Article utilities are registered while an article page is displayed and
+ *   unregistered before Astro's ClientRouter swaps to another page.
+ *
+ * The search and reading-list flyouts additionally expose declarative form
+ * tools (see SearchFlyout.tsx / ReadingListFlyout.tsx) while they are open.
+ */
+import { navigate } from 'astro:transitions/client';
+import {
+  OPEN_FLYOUT_EVENT,
+  articleUrl,
+  fetchArticles,
+  getReadingList,
+  getReadingListArticles,
+  isWebMCPSupported,
+  registerTool,
+  searchArticles,
+  siteUrl,
+  textResult,
+  errorResult,
+  updateReadingList,
+  type ReadingListAction,
+} from '../lib/webmcp';
+
+const WORDS_PER_MINUTE = 230;
+const HIGHLIGHT_NAME = 'webmcp-find';
+
+/* ------------------------------------------------------------------------ */
+/* Site-wide tools                                                          */
+/* ------------------------------------------------------------------------ */
+
+function registerSiteTools() {
+  registerTool({
+    name: 'search_articles',
+    title: 'Search articles',
+    description:
+      'Search The DevTools Times articles by keywords (matched against title, summary, author, category and tags). ' +
+      'Returns matching articles with slug, title, summary, category, author, date and URL. ' +
+      'Leave the query empty to list all articles (optionally filtered by category).',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        query: { type: 'string', description: 'Keywords to search for, e.g. "cycling" or "housing crisis".' },
+        category: { type: 'string', description: 'Optional category filter, e.g. "sports". Use list_categories for valid values.' },
+        limit: { type: 'integer', minimum: 1, maximum: 50, default: 10, description: 'Maximum number of results.' },
+      },
+    },
+    annotations: { readOnlyHint: true },
+    async execute({ query = '', category, limit = 10 }) {
+      const results = await searchArticles({ query, category, limit });
+      return textResult({ query, category: category ?? null, count: results.length, results });
+    },
+  });
+
+  registerTool({
+    name: 'list_categories',
+    title: 'List categories',
+    description: 'List all article categories with the number of articles in each and the category page URL.',
+    inputSchema: { type: 'object', properties: {} },
+    annotations: { readOnlyHint: true },
+    async execute() {
+      const articles = await fetchArticles();
+      const counts = new Map<string, number>();
+      for (const article of articles) {
+        if (article.category) counts.set(article.category, (counts.get(article.category) ?? 0) + 1);
+      }
+      const categories = [...counts]
+        .sort(([a], [b]) => a.localeCompare(b))
+        .map(([name, articleCount]) => ({ name, articleCount, url: siteUrl(`category/${name.toLowerCase()}`) }));
+      return textResult({ categories });
+    },
+  });
+
+  registerTool({
+    name: 'get_reading_list',
+    title: 'Get reading list',
+    description: "Return the articles currently saved in the reader's reading list (bookmarks).",
+    inputSchema: { type: 'object', properties: {} },
+    annotations: { readOnlyHint: true },
+    async execute() {
+      const articles = await getReadingListArticles();
+      return textResult({ count: articles.length, articles });
+    },
+  });
+
+  registerTool({
+    name: 'update_reading_list',
+    title: 'Update reading list',
+    description:
+      'Add an article to, remove it from, or toggle it in the reading list. ' +
+      'Identify the article by its slug (see search_articles).',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        slug: { type: 'string', description: 'Article slug, e.g. "urban-cycling".' },
+        action: { type: 'string', enum: ['add', 'remove', 'toggle'], default: 'add', description: 'What to do.' },
+      },
+      required: ['slug'],
+    },
+    annotations: { idempotentHint: true },
+    async execute({ slug, action = 'add' }: { slug: string; action?: ReadingListAction }) {
+      if (!slug) return errorResult('A "slug" is required.');
+      return textResult(await updateReadingList(slug, action));
+    },
+  });
+
+  registerTool({
+    name: 'navigate_to_page',
+    title: 'Navigate to page',
+    description:
+      'Navigate the browser to a page of The DevTools Times: the home page, an article, a category, ' +
+      'the reports page, the multimedia page, sign in or sign up.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        page: {
+          type: 'string',
+          enum: ['home', 'article', 'category', 'reports', 'multimedia', 'signin', 'signup'],
+          description: 'Which page to open.',
+        },
+        slug: { type: 'string', description: 'Article slug (required when page is "article").' },
+        category: { type: 'string', description: 'Category name (required when page is "category").' },
+      },
+      required: ['page'],
+    },
+    async execute({ page, slug, category }: { page: string; slug?: string; category?: string }) {
+      let url: string;
+      switch (page) {
+        case 'home':
+          url = siteUrl();
+          break;
+        case 'article': {
+          if (!slug) return errorResult('"slug" is required when page is "article".');
+          const articles = await fetchArticles();
+          if (!articles.some((a) => a.slug === slug)) {
+            return errorResult(`Unknown article "${slug}". Use search_articles to find valid slugs.`);
+          }
+          url = articleUrl(slug);
+          break;
+        }
+        case 'category':
+          if (!category) return errorResult('"category" is required when page is "category".');
+          url = siteUrl(`category/${encodeURIComponent(category.toLowerCase())}`);
+          break;
+        case 'reports':
+        case 'multimedia':
+        case 'signin':
+        case 'signup':
+          url = siteUrl(page);
+          break;
+        default:
+          return errorResult(`Unknown page "${page}".`);
+      }
+      // Navigate after responding so the result is delivered before the page changes.
+      setTimeout(() => navigate(url), 0);
+      return textResult({ navigatingTo: url });
+    },
+  });
+
+  registerTool({
+    name: 'open_panel',
+    title: 'Open panel',
+    description:
+      'Open the search or reading-list panel in the page header so the user can see it. ' +
+      'While open, these panels expose additional form tools (search_articles_form, update_reading_list_form).',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        panel: { type: 'string', enum: ['search', 'reading-list'], description: 'Panel to open.' },
+      },
+      required: ['panel'],
+    },
+    async execute({ panel }: { panel: 'search' | 'reading-list' }) {
+      if (panel !== 'search' && panel !== 'reading-list') return errorResult(`Unknown panel "${panel}".`);
+      window.dispatchEvent(new CustomEvent(OPEN_FLYOUT_EVENT, { detail: panel }));
+      return textResult(`Opened the ${panel} panel.`);
+    },
+  });
+}
+
+/* ------------------------------------------------------------------------ */
+/* Article utilities                                                        */
+/* ------------------------------------------------------------------------ */
+
+interface ArticleContext {
+  root: HTMLElement;
+  body: HTMLElement;
+  slug: string;
+  title: string;
+  summary: string;
+  author: string;
+  date: string;
+  category: string;
+}
+
+function getArticleContext(): ArticleContext | null {
+  const root = document.querySelector<HTMLElement>('[data-article-slug]');
+  const body = root?.querySelector<HTMLElement>('[data-article-body]');
+  if (!root || !body) return null;
+  const d = root.dataset;
+  return {
+    root,
+    body,
+    slug: d.articleSlug ?? '',
+    title: d.articleTitle ?? '',
+    summary: d.articleSummary ?? '',
+    author: d.articleAuthor ?? '',
+    date: d.articleDate ?? '',
+    category: d.articleCategory ?? '',
+  };
+}
+
+/** Text blocks of the article body, ignoring scripts/styles embedded in the markdown. */
+function getBlocks(body: HTMLElement): HTMLElement[] {
+  return [...body.querySelectorAll<HTMLElement>('h1, h2, h3, h4, h5, h6, p, li, blockquote, pre, td, th')].filter(
+    (el) => !el.closest('script, style') && !el.parentElement?.closest('li, blockquote') && el.innerText.trim(),
+  );
+}
+
+function getBodyText(body: HTMLElement): string {
+  return getBlocks(body)
+    .map((el) => el.innerText.trim())
+    .join('\n\n');
+}
+
+function countWords(text: string): number {
+  return text.split(/\s+/).filter(Boolean).length;
+}
+
+function getHeadings(body: HTMLElement) {
+  return [...body.querySelectorAll<HTMLHeadingElement>('h1, h2, h3, h4, h5, h6')].map((el, index) => ({
+    index,
+    level: Number(el.tagName[1]),
+    text: el.innerText.trim(),
+    id: el.id || null,
+    element: el,
+  }));
+}
+
+function clearFindHighlight() {
+  (CSS as any).highlights?.delete(HIGHLIGHT_NAME);
+}
+
+function highlightMatches(body: HTMLElement, needle: string): Range[] {
+  const ranges: Range[] = [];
+  const lowerNeedle = needle.toLowerCase();
+  const walker = document.createTreeWalker(body, NodeFilter.SHOW_TEXT, {
+    acceptNode: (node) =>
+      node.parentElement?.closest('script, style') ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT,
+  });
+  for (let node = walker.nextNode(); node; node = walker.nextNode()) {
+    const text = node.textContent?.toLowerCase() ?? '';
+    for (let i = text.indexOf(lowerNeedle); i !== -1; i = text.indexOf(lowerNeedle, i + lowerNeedle.length)) {
+      const range = document.createRange();
+      range.setStart(node, i);
+      range.setEnd(node, i + needle.length);
+      ranges.push(range);
+    }
+  }
+  const HighlightCtor = (window as any).Highlight;
+  const highlights = (CSS as any).highlights;
+  clearFindHighlight();
+  if (HighlightCtor && highlights && ranges.length) {
+    highlights.set(HIGHLIGHT_NAME, new HighlightCtor(...ranges));
+  }
+  return ranges;
+}
+
+function ensureHighlightStyle() {
+  if (document.getElementById('webmcp-highlight-style')) return;
+  const style = document.createElement('style');
+  style.id = 'webmcp-highlight-style';
+  style.textContent = `::highlight(${HIGHLIGHT_NAME}) { background-color: rgb(251 191 36 / 0.6); color: inherit; }`;
+  document.head.append(style);
+}
+
+function registerArticleTools(): () => void {
+  const ctx = getArticleContext();
+  if (!ctx) return () => {};
+  ensureHighlightStyle();
+
+  const meta = () => ({
+    slug: ctx.slug,
+    title: ctx.title,
+    summary: ctx.summary,
+    author: ctx.author,
+    date: ctx.date,
+    category: ctx.category,
+    url: articleUrl(ctx.slug),
+  });
+
+  const cleanups = [
+    registerTool({
+      name: 'get_current_article',
+      title: 'Get current article',
+      description:
+        'Return the article currently open in the browser: metadata (title, summary, author, date, category, URL), ' +
+        'whether it is in the reading list, and optionally its full body text.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          includeBody: { type: 'boolean', default: true, description: 'Include the full article text.' },
+        },
+      },
+      annotations: { readOnlyHint: true },
+      async execute({ includeBody = true }) {
+        const saved = await getReadingList()
+          .then((list) => list.includes(ctx.slug))
+          .catch(() => null);
+        return textResult({ ...meta(), inReadingList: saved, ...(includeBody ? { body: getBodyText(ctx.body) } : {}) });
+      },
+    }),
+
+    registerTool({
+      name: 'get_article_outline',
+      title: 'Get article outline',
+      description: 'List the section headings of the current article (level and text), in document order.',
+      inputSchema: { type: 'object', properties: {} },
+      annotations: { readOnlyHint: true },
+      execute() {
+        const headings = getHeadings(ctx.body).map(({ element, ...rest }) => rest);
+        return textResult({ title: ctx.title, headings });
+      },
+    }),
+
+    registerTool({
+      name: 'get_article_reading_stats',
+      title: 'Get reading stats',
+      description:
+        'Compute statistics for the current article: word count, paragraph count, estimated reading time ' +
+        'and how much of the article the user has scrolled through.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          wordsPerMinute: {
+            type: 'integer',
+            minimum: 50,
+            maximum: 1000,
+            default: WORDS_PER_MINUTE,
+            description: 'Reading speed used for the time estimate.',
+          },
+        },
+      },
+      annotations: { readOnlyHint: true },
+      execute({ wordsPerMinute = WORDS_PER_MINUTE }) {
+        const text = getBodyText(ctx.body);
+        const words = countWords(text);
+        const rect = ctx.root.getBoundingClientRect();
+        const progress = Math.min(1, Math.max(0, (window.innerHeight - rect.top) / Math.max(rect.height, 1)));
+        return textResult({
+          wordCount: words,
+          paragraphCount: ctx.body.querySelectorAll('p').length,
+          headingCount: getHeadings(ctx.body).length,
+          wordsPerMinute,
+          estimatedReadingMinutes: Math.max(1, Math.round(words / wordsPerMinute)),
+          scrollProgressPercent: Math.round(progress * 100),
+        });
+      },
+    }),
+
+    registerTool({
+      name: 'find_in_article',
+      title: 'Find in article',
+      description:
+        'Find a word or phrase in the current article (case-insensitive). Highlights all matches on the page, ' +
+        'scrolls to the first one and returns the passages that contain it. Pass an empty string to clear highlights.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          text: { type: 'string', description: 'Word or phrase to find.' },
+          scroll: { type: 'boolean', default: true, description: 'Scroll the first match into view.' },
+        },
+        required: ['text'],
+      },
+      execute({ text = '', scroll = true }: { text: string; scroll?: boolean }) {
+        const needle = text.trim();
+        if (!needle) {
+          clearFindHighlight();
+          return textResult('Cleared highlights.');
+        }
+        const ranges = highlightMatches(ctx.body, needle);
+        if (scroll && ranges[0]) {
+          ranges[0].startContainer.parentElement?.scrollIntoView({ behavior: 'smooth', block: 'center' });
+        }
+        const passages = getBlocks(ctx.body)
+          .map((el) => el.innerText.trim())
+          .filter((t) => t.toLowerCase().includes(needle.toLowerCase()));
+        return textResult({ text: needle, matchCount: ranges.length, passages });
+      },
+    }),
+
+    registerTool({
+      name: 'scroll_to_article_section',
+      title: 'Scroll to section',
+      description:
+        'Scroll the current article to a section. Use "top" or "end", or give (part of) a heading from get_article_outline.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          section: { type: 'string', description: 'Heading text, "top" or "end".' },
+        },
+        required: ['section'],
+      },
+      execute({ section = '' }: { section: string }) {
+        const wanted = section.trim().toLowerCase();
+        if (wanted === 'top') {
+          ctx.root.scrollIntoView({ behavior: 'smooth', block: 'start' });
+          return textResult('Scrolled to the top of the article.');
+        }
+        if (wanted === 'end') {
+          ctx.body.scrollIntoView({ behavior: 'smooth', block: 'end' });
+          return textResult('Scrolled to the end of the article.');
+        }
+        const headings = getHeadings(ctx.body);
+        const match =
+          headings.find((h) => h.text.toLowerCase() === wanted) ??
+          headings.find((h) => h.text.toLowerCase().includes(wanted));
+        if (!match) {
+          return errorResult(
+            `No section matching "${section}". Available sections: ${headings.map((h) => h.text).join('; ') || '(none)'}`,
+          );
+        }
+        match.element.scrollIntoView({ behavior: 'smooth', block: 'start' });
+        return textResult(`Scrolled to "${match.text}".`);
+      },
+    }),
+
+    registerTool({
+      name: 'save_current_article',
+      title: 'Save current article',
+      description: 'Add the current article to the reading list, or remove it (saved: false).',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          saved: { type: 'boolean', default: true, description: 'true to save, false to remove.' },
+        },
+      },
+      annotations: { idempotentHint: true },
+      async execute({ saved = true }: { saved?: boolean }) {
+        return textResult(await updateReadingList(ctx.slug, saved ? 'add' : 'remove'));
+      },
+    }),
+
+    registerTool({
+      name: 'get_article_citation',
+      title: 'Get article citation',
+      description: 'Build a citation and share links for the current article.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          style: { type: 'string', enum: ['apa', 'mla', 'chicago', 'plain'], default: 'plain', description: 'Citation style.' },
+        },
+      },
+      annotations: { readOnlyHint: true },
+      execute({ style = 'plain' }: { style?: string }) {
+        const { title, author, date, url } = meta();
+        const d = date ? new Date(`${date}T00:00:00Z`) : null;
+        const longDate = d?.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric', timeZone: 'UTC' }) ?? 'n.d.';
+        const today = new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
+        const year = d?.getUTCFullYear() ?? 'n.d.';
+        const citations: Record<string, string> = {
+          apa: `${author}. (${year}). ${title}. The DevTools Times. ${url}`,
+          mla: `${author}. "${title}." The DevTools Times, ${longDate}, ${url}. Accessed ${today}.`,
+          chicago: `${author}. "${title}." The DevTools Times, ${longDate}. ${url}.`,
+          plain: `"${title}" by ${author}, The DevTools Times (${longDate}) – ${url}`,
+        };
+        const encodedUrl = encodeURIComponent(url);
+        const encodedTitle = encodeURIComponent(title);
+        return textResult({
+          style,
+          citation: citations[style] ?? citations.plain,
+          shareLinks: {
+            x: `https://x.com/intent/post?url=${encodedUrl}&text=${encodedTitle}`,
+            facebook: `https://www.facebook.com/sharer/sharer.php?u=${encodedUrl}`,
+            whatsapp: `https://wa.me/?text=${encodedTitle}%20${encodedUrl}`,
+            email: `mailto:?subject=${encodedTitle}&body=${encodedUrl}`,
+          },
+        });
+      },
+    }),
+  ];
+
+  return () => {
+    clearFindHighlight();
+    cleanups.forEach((cleanup) => cleanup());
+  };
+}
+
+/* ------------------------------------------------------------------------ */
+/* Lifecycle (works with Astro's ClientRouter view transitions)             */
+/* ------------------------------------------------------------------------ */
+
+if (isWebMCPSupported()) {
+  registerSiteTools();
+
+  let cleanupArticleTools: (() => void) | null = null;
+  const syncPageTools = () => {
+    cleanupArticleTools?.();
+    cleanupArticleTools = registerArticleTools();
+  };
+
+  document.addEventListener('astro:page-load', syncPageTools);
+  document.addEventListener('astro:before-swap', () => {
+    cleanupArticleTools?.();
+    cleanupArticleTools = null;
+  });
+}
